local function isoNow()
	return os.date("!%Y-%m-%dT%H:%M:%SZ")
end

local function shortId(text)
	text = tostring(text or "")
	if #text <= 8 then
		return text
	end
	return string.sub(text, 1, 8)
end

local function getInstanceId(instance)
	if not instance then
		return nil
	end

	local existing = instanceIds[instance]
	if existing then
		idInstances[existing] = instance
		return existing
	end

	local id = "i" .. tostring(nextInstanceNumber)
	nextInstanceNumber += 1
	instanceIds[instance] = id
	idInstances[id] = instance
	return id
end

local function safeFullName(instance)
	local ok, value = pcall(function()
		return instance:GetFullName()
	end)
	if ok then
		return value
	end
	return instance.Name
end

local function encodeJson(value)
	local ok, encoded = pcall(function()
		return HttpService:JSONEncode(value)
	end)
	if ok then
		return encoded
	end
	return nil, encoded
end

local function decodeJson(value)
	local ok, decoded = pcall(function()
		return HttpService:JSONDecode(value)
	end)
	if ok then
		return decoded
	end
	return nil, decoded
end

local function sanitizeHeaderValue(value)
	local text = tostring(value or "")
	local safe = {}
	for index = 1, #text do
		local byte = string.byte(text, index)
		local character = string.char(byte)
		if (byte >= 48 and byte <= 57)
			or (byte >= 65 and byte <= 90)
			or (byte >= 97 and byte <= 122)
			or character == " "
			or character == "-"
			or character == "_"
			or character == "."
		then
			safe[#safe + 1] = string.char(byte)
		else
			safe[#safe + 1] = " "
		end
	end
	local sanitized = table.concat(safe)
	sanitized = string.gsub(sanitized, "%s+", " ")
	sanitized = string.gsub(sanitized, "^%s+", "")
	sanitized = string.gsub(sanitized, "%s+$", "")
	if #sanitized > 80 then
		sanitized = string.sub(sanitized, 1, 80)
	end
	if sanitized == "" then
		return "Place"
	end
	return sanitized
end

local function request(method, path, body, includeToken)
	local headers = {
		["Content-Type"] = "application/json",
	}
	if includeToken and sessionToken then
		headers["X-Codex-Studio-Token"] = sessionToken
		headers["X-Codex-Studio-Id"] = tostring(studioId)
		headers["X-Codex-Place-Id"] = tostring(game.PlaceId or 0)
		headers["X-Codex-Game-Id"] = tostring(game.GameId or 0)
		headers["X-Codex-Place-Name"] = sanitizeHeaderValue(game.Name or "Place")
	end

	local requestOptions = {
		Url = bridgeUrl .. path,
		Method = method,
		Headers = headers,
	}

	if body ~= nil then
		local encoded, encodeError = encodeJson(body)
		if not encoded then
			return nil, "JSON encode failed: " .. tostring(encodeError)
		end
		requestOptions.Body = encoded
	end

	local ok, response = pcall(function()
		return HttpService:RequestAsync(requestOptions)
	end)
	if not ok then
		return nil, tostring(response)
	end

	local decoded = {}
	if response.Body and response.Body ~= "" then
		local parsed = decodeJson(response.Body)
		if parsed then
			decoded = parsed
		else
			decoded = { rawBody = response.Body }
		end
	end

	if not response.Success then
		local message = "HTTP " .. tostring(response.StatusCode)
		if decoded.error and decoded.error.message then
			message = decoded.error.message
		end
		return nil, message, decoded
	end

	return decoded
end

local function isHttpRateLimitError(err)
	local text = string.lower(tostring(err or ""))
	return text:find("request", 1, true) ~= nil
		and (text:find("limit", 1, true) ~= nil or text:find("throttle", 1, true) ~= nil)
end

local function addOutput(message, messageType, source, skipUpload)
	local entry = {
		id = HttpService:GenerateGUID(false),
		at = isoNow(),
		message = tostring(message or ""),
		type = tostring(messageType or "Output"),
		source = source and tostring(source) or nil,
	}
	if not skipUpload then
		table.insert(outputQueue, entry)
	end
	table.insert(outputBuffer, entry)
	while #outputQueue > OUTPUT_LIMIT do
		table.remove(outputQueue, 1)
	end
	while #outputBuffer > OUTPUT_LIMIT do
		table.remove(outputBuffer, 1)
	end
end

local function serializeValue(value)
	local valueType = typeof(value)
	if value == nil or valueType == "string" or valueType == "number" or valueType == "boolean" then
		return value
	end
	if valueType == "Vector3" then
		return { __type = "Vector3", x = value.X, y = value.Y, z = value.Z }
	end
	if valueType == "Vector2" then
		return { __type = "Vector2", x = value.X, y = value.Y }
	end
	if valueType == "Color3" then
		return { __type = "Color3", r = value.R, g = value.G, b = value.B }
	end
	if valueType == "NumberRange" then
		return { __type = "NumberRange", min = value.Min, max = value.Max }
	end
	if valueType == "NumberSequence" then
		local keypoints = {}
		for _, keypoint in ipairs(value.Keypoints) do
			table.insert(keypoints, { time = keypoint.Time, value = keypoint.Value, envelope = keypoint.Envelope })
		end
		return { __type = "NumberSequence", keypoints = keypoints }
	end
	if valueType == "ColorSequence" then
		local keypoints = {}
		for _, keypoint in ipairs(value.Keypoints) do
			table.insert(keypoints, { time = keypoint.Time, color = serializeValue(keypoint.Value) })
		end
		return { __type = "ColorSequence", keypoints = keypoints }
	end
	if valueType == "UDim" then
		return { __type = "UDim", scale = value.Scale, offset = value.Offset }
	end
	if valueType == "UDim2" then
		return {
			__type = "UDim2",
			xScale = value.X.Scale,
			xOffset = value.X.Offset,
			yScale = value.Y.Scale,
			yOffset = value.Y.Offset,
		}
	end
	if valueType == "CFrame" then
		return { __type = "CFrame", components = { value:GetComponents() } }
	end
	if valueType == "BrickColor" then
		return { __type = "BrickColor", name = value.Name, number = value.Number }
	end
	if valueType == "EnumItem" then
		return {
			__type = "EnumItem",
			enumType = tostring(value.EnumType),
			name = value.Name,
			value = value.Value,
		}
	end
	if valueType == "Instance" then
		return { __type = "Instance", id = getInstanceId(value), path = safeFullName(value) }
	end
	return tostring(value)
end

local function readProperty(instance, propertyName, target)
	local ok, value = pcall(function()
		return instance[propertyName]
	end)
	if ok then
		target[propertyName] = serializeValue(value)
	end
end

local function readCommonProperties(instance)
	local properties = {}
	local baseProperties = { "Name", "Archivable" }
	for _, propertyName in ipairs(baseProperties) do
		readProperty(instance, propertyName, properties)
	end

	if instance:IsA("BasePart") then
		for _, propertyName in ipairs({
			"Anchored",
			"CanCollide",
			"CanQuery",
			"CanTouch",
			"Transparency",
			"Reflectance",
			"Color",
			"Material",
			"Size",
			"Position",
			"Orientation",
		}) do
			readProperty(instance, propertyName, properties)
		end
	end

	if instance:IsA("Model") then
		readProperty(instance, "PrimaryPart", properties)
	end

	if instance:IsA("GuiObject") then
		for _, propertyName in ipairs({
			"Visible",
			"Position",
			"Size",
			"AnchorPoint",
			"BackgroundTransparency",
			"BackgroundColor3",
			"ZIndex",
		}) do
			readProperty(instance, propertyName, properties)
		end
	end

	if instance:IsA("TextLabel") or instance:IsA("TextButton") or instance:IsA("TextBox") then
		for _, propertyName in ipairs({
			"Text",
			"TextColor3",
			"TextSize",
			"Font",
			"TextWrapped",
			"TextScaled",
		}) do
			readProperty(instance, propertyName, properties)
		end
	end

	if instance:IsA("LuaSourceContainer") then
		for _, propertyName in ipairs({ "Enabled", "Disabled", "RunContext" }) do
			readProperty(instance, propertyName, properties)
		end
	end

	return properties
end

local function deserializeValue(value, instance, propertyName)
	if type(value) ~= "table" then
		if type(value) == "string" and instance and propertyName then
			local ok, current = pcall(function()
				return instance[propertyName]
			end)
			if ok and typeof(current) == "EnumItem" then
				local enumTypeName = tostring(current.EnumType):gsub("^Enum%.", "")
				local enumType = Enum[enumTypeName]
				if enumType and enumType[value] then
					return enumType[value]
				end
			end
		end
		return value
	end

	local valueType = value.__type
	if valueType == "Vector3" then
		return Vector3.new(value.x or 0, value.y or 0, value.z or 0)
	end
	if valueType == "Vector2" then
		return Vector2.new(value.x or 0, value.y or 0)
	end
	if valueType == "Color3" then
		if value.mode == "rgb" then
			return Color3.fromRGB(value.r or 0, value.g or 0, value.b or 0)
		end
		return Color3.new(value.r or 0, value.g or 0, value.b or 0)
	end
	if valueType == "NumberRange" then
		return NumberRange.new(value.min or value.Min or 0, value.max or value.Max or value.min or value.Min or 0)
	end
	if valueType == "NumberSequence" then
		local keypoints = {}
		for _, keypoint in ipairs(value.keypoints or value.Keypoints or {}) do
			table.insert(keypoints, NumberSequenceKeypoint.new(keypoint.time or keypoint.Time or 0, keypoint.value or keypoint.Value or 0, keypoint.envelope or keypoint.Envelope or 0))
		end
		if #keypoints == 0 then
			return NumberSequence.new(value.value or 0)
		end
		return NumberSequence.new(keypoints)
	end
	if valueType == "ColorSequence" then
		local keypoints = {}
		for _, keypoint in ipairs(value.keypoints or value.Keypoints or {}) do
			local color = deserializeValue(keypoint.color or keypoint.Value or keypoint.value, nil, nil)
			if typeof(color) ~= "Color3" then
				color = Color3.new(1, 1, 1)
			end
			table.insert(keypoints, ColorSequenceKeypoint.new(keypoint.time or keypoint.Time or 0, color))
		end
		if #keypoints == 0 then
			local color = deserializeValue(value.color or value.value, nil, nil)
			if typeof(color) ~= "Color3" then
				color = Color3.new(1, 1, 1)
			end
			return ColorSequence.new(color)
		end
		return ColorSequence.new(keypoints)
	end
	if valueType == "UDim" then
		return UDim.new(value.scale or 0, value.offset or 0)
	end
	if valueType == "UDim2" then
		return UDim2.new(value.xScale or 0, value.xOffset or 0, value.yScale or 0, value.yOffset or 0)
	end
	if valueType == "CFrame" and type(value.components) == "table" then
		return CFrame.new(table.unpack(value.components))
	end
	if valueType == "BrickColor" then
		return BrickColor.new(value.name or value.number or "Medium stone grey")
	end
	if valueType == "EnumItem" then
		local enumTypeName = tostring(value.enumType or ""):gsub("^Enum%.", "")
		local enumType = Enum[enumTypeName]
		if enumType and value.name and enumType[value.name] then
			return enumType[value.name]
		end
	end
	if valueType == "Instance" then
		return idInstances[value.id] or nil
	end

	return value
end

local function resolvePath(path)
	if type(path) ~= "string" or path == "" then
		return nil
	end

	local normalized = path:gsub("^game%.", "")
	local segments = string.split(normalized, ".")
	if #segments == 0 then
		return nil
	end

	local ok, current = pcall(function()
		return game:GetService(segments[1])
	end)
	if not ok or not current then
		current = game:FindFirstChild(segments[1])
	end

	for index = 2, #segments do
		if not current then
			return nil
		end
		current = current:FindFirstChild(segments[index])
	end

	return current
end

local function resolveInstance(reference)
	if typeof(reference) == "Instance" then
		return reference
	end
	if type(reference) == "string" then
		return idInstances[reference] or resolvePath(reference)
	end
	if type(reference) == "table" then
		if reference.id and idInstances[reference.id] then
			return idInstances[reference.id]
		end
		if reference.instanceId and idInstances[reference.instanceId] then
			return idInstances[reference.instanceId]
		end
		if reference.path then
			return resolvePath(reference.path)
		end
	end
	return nil
end

local function collectReferences(payload)
	local references = {}
	if type(payload) ~= "table" then
		return references
	end

	if payload.instanceIds then
		for _, id in ipairs(payload.instanceIds) do
			table.insert(references, id)
		end
	end
	if payload.instances then
		for _, reference in ipairs(payload.instances) do
			table.insert(references, reference)
		end
	end
	if payload.refs then
		for _, reference in ipairs(payload.refs) do
			table.insert(references, reference)
		end
	end
	if payload.paths then
		for _, path in ipairs(payload.paths) do
			table.insert(references, path)
		end
	end
	if payload.instanceId then
		table.insert(references, payload.instanceId)
	end
	if payload.targetId then
		table.insert(references, payload.targetId)
	end
	if payload.path then
		table.insert(references, payload.path)
	end
	if payload.target then
		table.insert(references, payload.target)
	end

	return references
end

local function resolveInstances(payload)
	local instances = {}
	for _, reference in ipairs(collectReferences(payload)) do
		local instance = resolveInstance(reference)
		if instance then
			table.insert(instances, instance)
		end
	end
	return instances
end

local function getParentFromPayload(payload)
	local parent = resolveInstance(payload.parent or payload.parentId or payload.parentPath)
	if parent then
		return parent
	end
	return workspace
end

local function selectedIdSet()
	local selected = {}
	for _, instance in ipairs(Selection:Get()) do
		selected[getInstanceId(instance)] = true
	end
	return selected
end

local function nodeForInstance(instance, parentId, selected)
	local id = getInstanceId(instance)
	return {
		id = id,
		name = instance.Name,
		className = instance.ClassName,
		path = safeFullName(instance),
		parentId = parentId,
		childCount = #instance:GetChildren(),
		selected = selected[id] or false,
		hasSource = instance:IsA("LuaSourceContainer"),
		properties = readCommonProperties(instance),
	}
end

local function getServiceIfAvailable(serviceName)
	local ok, service = pcall(function()
		return game:GetService(serviceName)
	end)
	if ok then
		return service
	end
	return nil
end

local function isInternalRoot(instance)
	return INTERNAL_ROOTS[instance.ClassName] == true or INTERNAL_ROOTS[instance.Name] == true
end

local function getPriorityRoots()
	local roots = {}
	local included = {}

	for _, serviceName in ipairs(PRIORITY_SERVICE_NAMES) do
		local service = getServiceIfAvailable(serviceName)
		if service and not included[service] then
			table.insert(roots, service)
			included[service] = true
		end
	end

	for _, child in ipairs(game:GetChildren()) do
		if not included[child] and not isInternalRoot(child) then
			table.insert(roots, child)
			included[child] = true
		end
	end

	return roots, included
end

local function readScriptSource(instance)
	if not instance or not instance:IsA("LuaSourceContainer") then
		error("Target script was not found.")
	end

	local ok, source = pcall(function()
		return ScriptEditorService:GetEditorSource(instance)
	end)
	if not ok then
		ok, source = pcall(function()
			return instance.Source
		end)
		if not ok then
			error("Could not read script source: " .. tostring(source))
		end
	end
	return source
end

