local function uint32(value)
	return bit32.band(value, 0xffffffff)
end

local function sha256Hex(input)
	input = tostring(input or "")
	local bytes = {}
	for index = 1, #input do
		bytes[#bytes + 1] = string.byte(input, index)
	end

	local bitLength = #input * 8
	bytes[#bytes + 1] = 0x80
	while (#bytes % 64) ~= 56 do
		bytes[#bytes + 1] = 0
	end

	local high = math.floor(bitLength / 4294967296)
	local low = bitLength % 4294967296
	for shift = 24, 0, -8 do
		bytes[#bytes + 1] = bit32.band(bit32.rshift(high, shift), 0xff)
	end
	for shift = 24, 0, -8 do
		bytes[#bytes + 1] = bit32.band(bit32.rshift(low, shift), 0xff)
	end

	local h0 = 0x6a09e667
	local h1 = 0xbb67ae85
	local h2 = 0x3c6ef372
	local h3 = 0xa54ff53a
	local h4 = 0x510e527f
	local h5 = 0x9b05688c
	local h6 = 0x1f83d9ab
	local h7 = 0x5be0cd19

	for chunk = 1, #bytes, 64 do
		local w = {}
		for index = 1, 16 do
			local base = chunk + (index - 1) * 4
			w[index] = uint32(
				bit32.lshift(bytes[base], 24)
					+ bit32.lshift(bytes[base + 1], 16)
					+ bit32.lshift(bytes[base + 2], 8)
					+ bytes[base + 3]
			)
		end
		for index = 17, 64 do
			local s0 = bit32.bxor(bit32.rrotate(w[index - 15], 7), bit32.rrotate(w[index - 15], 18), bit32.rshift(w[index - 15], 3))
			local s1 = bit32.bxor(bit32.rrotate(w[index - 2], 17), bit32.rrotate(w[index - 2], 19), bit32.rshift(w[index - 2], 10))
			w[index] = uint32(w[index - 16] + s0 + w[index - 7] + s1)
		end

		local a = h0
		local b = h1
		local c = h2
		local d = h3
		local e = h4
		local f = h5
		local g = h6
		local h = h7

		for index = 1, 64 do
			local s1 = bit32.bxor(bit32.rrotate(e, 6), bit32.rrotate(e, 11), bit32.rrotate(e, 25))
			local ch = bit32.bxor(bit32.band(e, f), bit32.band(bit32.bnot(e), g))
			local temp1 = uint32(h + s1 + ch + SHA256_K[index] + w[index])
			local s0 = bit32.bxor(bit32.rrotate(a, 2), bit32.rrotate(a, 13), bit32.rrotate(a, 22))
			local maj = bit32.bxor(bit32.band(a, b), bit32.band(a, c), bit32.band(b, c))
			local temp2 = uint32(s0 + maj)

			h = g
			g = f
			f = e
			e = uint32(d + temp1)
			d = c
			c = b
			b = a
			a = uint32(temp1 + temp2)
		end

		h0 = uint32(h0 + a)
		h1 = uint32(h1 + b)
		h2 = uint32(h2 + c)
		h3 = uint32(h3 + d)
		h4 = uint32(h4 + e)
		h5 = uint32(h5 + f)
		h6 = uint32(h6 + g)
		h7 = uint32(h7 + h)
	end

	return string.format("%08x%08x%08x%08x%08x%08x%08x%08x", h0, h1, h2, h3, h4, h5, h6, h7)
end

local function sourceHash(source)
	return "sha256:" .. sha256Hex(source or "")
end

local splitLines

local function countLines(source)
	source = tostring(source or "")
	if source == "" then
		return 0
	end
	local _, count = source:gsub("\n", "\n")
	if string.sub(source, -1) == "\n" then
		return count
	end
	return count + 1
end

local function changedLineCount(oldSource, newSource)
	local oldLines = splitLines(oldSource)
	local newLines = splitLines(newSource)
	local maxLines = math.max(#oldLines, #newLines)
	local changed = 0
	for index = 1, maxLines do
		if oldLines[index] ~= newLines[index] then
			changed += 1
		end
	end
	return changed
end

local function makeTraversalOptions(payload)
	payload = payload or {}
	return {
		depth = math.max(0, math.min(tonumber(payload.depth) or SNAPSHOT_DEPTH_LIMIT, 20)),
		maxNodes = math.max(1, math.min(tonumber(payload.maxNodes) or SNAPSHOT_NODE_LIMIT, 10000)),
		includeInternal = payload.includeInternal == true,
		shallowInternal = payload.shallowInternal ~= false,
	}
end

local function collectTree(root, options)
	local selected = selectedIdSet()
	local nodes = {}
	local scripts = {}
	local classCounts = {}
	local visited = 0
	local truncated = false
	local seen = {}

	local function visit(instance, parentId, depth)
		if not instance or seen[instance] then
			return
		end
		if visited >= options.maxNodes then
			truncated = true
			return
		end

		seen[instance] = true
		visited += 1
		classCounts[instance.ClassName] = (classCounts[instance.ClassName] or 0) + 1

		local node = nodeForInstance(instance, parentId, selected)
		table.insert(nodes, node)
		if instance:IsA("LuaSourceContainer") then
			table.insert(scripts, {
				id = node.id,
				name = node.name,
				className = node.className,
				path = node.path,
				properties = node.properties,
			})
		end

		local childDepthLimit = options.depth
		if parentId == nil and isInternalRoot(instance) and options.shallowInternal and not options.includeInternal then
			childDepthLimit = 0
		end

		if depth >= childDepthLimit then
			if #instance:GetChildren() > 0 then
				truncated = true
			end
			return
		end

		for _, child in ipairs(instance:GetChildren()) do
			visit(child, node.id, depth + 1)
			if truncated and visited >= options.maxNodes then
				return
			end
		end
	end

	visit(root, nil, 0)

	return {
		nodes = nodes,
		scripts = scripts,
		classCounts = classCounts,
		scriptCount = #scripts,
		truncated = truncated,
		nodeCount = #nodes,
	}
end

local function buildSnapshot()
	local selected = selectedIdSet()
	local nodes = {}
	local scripts = {}
	local visited = 0
	local truncated = false
	local seen = {}

	local function visit(instance, parentId, depth)
		if seen[instance] then
			return
		end
		if visited >= SNAPSHOT_NODE_LIMIT then
			truncated = true
			return
		end
		seen[instance] = true
		visited += 1

		local node = nodeForInstance(instance, parentId, selected)
		table.insert(nodes, node)
		if instance:IsA("LuaSourceContainer") then
			table.insert(scripts, {
				id = node.id,
				name = node.name,
				className = node.className,
				path = node.path,
				properties = node.properties,
			})
		end

		local depthLimit = SNAPSHOT_DEPTH_LIMIT
		if parentId == nil and isInternalRoot(instance) then
			depthLimit = 0
		end

		if depth >= depthLimit then
			if #instance:GetChildren() > 0 then
				truncated = true
			end
			return
		end

		for _, child in ipairs(instance:GetChildren()) do
			visit(child, node.id, depth + 1)
			if truncated and visited >= SNAPSHOT_NODE_LIMIT then
				return
			end
		end
	end

	local roots = getPriorityRoots()
	for _, root in ipairs(roots) do
		visit(root, nil, 0)
		if truncated and visited >= SNAPSHOT_NODE_LIMIT then
			break
		end
	end

	local selection = {}
	for _, instance in ipairs(Selection:Get()) do
		table.insert(selection, nodeForInstance(instance, nil, selected))
	end

	State.snapshotStats = {
		capturedAt = isoNow(),
		nodeCount = #nodes,
		scriptCount = #scripts,
		truncated = truncated,
	}

	return {
		version = VERSION,
		studioId = studioId,
		capturedAt = isoNow(),
		place = {
			name = game.Name,
			placeId = game.PlaceId,
			gameId = game.GameId,
			jobId = game.JobId,
		},
		limits = {
			nodeLimit = SNAPSHOT_NODE_LIMIT,
			depthLimit = SNAPSHOT_DEPTH_LIMIT,
			truncated = truncated,
			nodeCount = #nodes,
			priorityRoots = PRIORITY_SERVICE_NAMES,
		},
		nodes = nodes,
		selection = selection,
		scripts = scripts,
		pluginStatus = {
			studioId = studioId,
			studioIdSettingKey = studioIdSettingKey,
			sessionTokenSettingKey = sessionTokenSettingKey,
			placeIdentityKey = placeIdentityKey,
			pluginVersion = VERSION,
			paired = paired,
			bridgeUrl = bridgeUrl,
			pendingCommands = #commandOrder,
			outputBuffered = #outputBuffer,
			placeId = game.PlaceId,
			gameId = game.GameId,
			placeName = game.Name,
			runtimeMode = State.runtimeStatus and State.runtimeStatus.mode or nil,
			playerCount = State.runtimeStatus and State.runtimeStatus.players and State.runtimeStatus.players.count or nil,
			remoteMissingCount = State.remoteInventory and State.remoteInventory.missingCount or nil,
			ruleforgeIssueCount = State.ruleforgeValidation and State.ruleforgeValidation.summary and State.ruleforgeValidation.summary.total or nil,
			projectProfile = State.projectProfile and State.projectProfile.id or nil,
			projectScore = State.projectHealth and State.projectHealth.score or nil,
			projectIssueCount = State.projectValidation and State.projectValidation.summary and State.projectValidation.summary.total or nil,
			loopHealth = State.loopHealth,
			lastStateUploadError = State.lastStateUploadError,
			lastStateUploadWarningClock = State.lastStateUploadWarningClock,
			lastPluginUnloadSignalAt = State.lastPluginUnloadSignalAt,
			runtimeMirrorMode = State.runtimeMirrorStatus and State.runtimeMirrorStatus.mode or nil,
			harnessInstalled = State.harnessStatus and State.harnessStatus.installed or nil,
			lastScenarioStatus = State.scenarioRunReport and State.scenarioRunReport.status or nil,
			builderFocus = State.builderBrainStatus and State.builderBrainStatus.currentFocus or nil,
			visualSnapshotAt = State.visualSnapshot and State.visualSnapshot.at or nil,
			lastAutonomousAction = State.autonomousPlan and State.autonomousPlan.nextAction or nil,
			lastMilestone = V16.last.milestonePlan and V16.last.milestonePlan.milestone and V16.last.milestonePlan.milestone.id or nil,
			lastVerificationStatus = V16.last.verificationReport and V16.last.verificationReport.summary and V16.last.verificationReport.summary.status or nil,
			verificationHarnessInstalled = V16.last.verificationHarnessStatus and V16.last.verificationHarnessStatus.installed or nil,
			qaActive = V17.session ~= nil and V17.session.endedAt == nil,
			qaTimelineCount = #V17.timeline,
			qaHarnessInstalled = V17.last.qaHarnessStatus and V17.last.qaHarnessStatus.installed or nil,
		},
	}
end

local function buildPluginStatusLite(extra)
	local status = {
		studioId = studioId,
		studioIdSettingKey = studioIdSettingKey,
		sessionTokenSettingKey = sessionTokenSettingKey,
		placeIdentityKey = placeIdentityKey,
		pluginVersion = VERSION,
		paired = paired,
		bridgeUrl = bridgeUrl,
		pendingCommands = #commandOrder,
		outputBuffered = #outputBuffer,
		placeId = game.PlaceId,
		gameId = game.GameId,
		placeName = game.Name,
		runtimeMode = State.runtimeStatus and State.runtimeStatus.mode or (RunService:IsRunning() and "play" or "edit"),
		playerCount = State.runtimeStatus and State.runtimeStatus.players and State.runtimeStatus.players.count or nil,
		loopHealth = State.loopHealth,
		lastStateUploadError = State.lastStateUploadError,
		lastOutputError = State.lastOutputError,
		lastPluginUnloadSignalAt = State.lastPluginUnloadSignalAt,
		lastHeartbeatSentAt = State.lastHeartbeatSentAt,
		lastHeartbeatAckAt = State.lastHeartbeatAckAt,
		lastHeartbeatError = State.lastHeartbeatError,
		contextId = contextId,
	}
	for key, value in pairs(extra or {}) do
		status[key] = value
	end
	return status
end

local function reportCommand(id, status, result, err)
	request("POST", "/studio/commands/result", {
		id = id,
		status = status,
		at = isoNow(),
		result = result,
		error = err,
		pluginStatus = {
			studioId = studioId,
			studioIdSettingKey = studioIdSettingKey,
			sessionTokenSettingKey = sessionTokenSettingKey,
			placeIdentityKey = placeIdentityKey,
			pluginVersion = VERSION,
			placeId = game.PlaceId,
			gameId = game.GameId,
			placeName = game.Name,
		},
	}, true)
end

local function sendHeartbeatAsync(reason)
	if not paired then
		return
	end
	local now = os.clock()
	if heartbeatInFlight and now - heartbeatStartedClock < heartbeatTimeoutSeconds then
		return
	end
	heartbeatSequence += 1
	heartbeatInFlight = true
	heartbeatStartedClock = now
	local sequence = heartbeatSequence
	task.spawn(function()
		local response, err = request("POST", "/studio/heartbeat", {
			pluginStatus = buildPluginStatusLite({
				heartbeatSequence = sequence,
				heartbeatReason = reason or "loop",
			}),
			heartbeat = {
				sequence = sequence,
				reason = reason or "loop",
				contextId = contextId,
				playMode = RunService:IsRunning(),
				at = isoNow(),
			},
		}, true)
		if sequence == heartbeatSequence then
			heartbeatInFlight = false
		end
		if response then
			State.lastHeartbeatSentAt = isoNow()
			State.lastHeartbeatAckAt = isoNow()
			State.lastHeartbeatError = nil
		else
			State.lastHeartbeatError = tostring(err)
			State.lastHeartbeatErrorAt = isoNow()
		end
	end)
end

local function sendState(force)
	if not paired then
		return
	end
	local now = os.clock()
	if not force and not stateDirty and now - lastStateSentAt < STATE_SECONDS then
		return
	end

	local snapshot = buildSnapshot()
	local response, err = request("POST", "/studio/state", snapshot, true)
	if response then
		lastStateSentAt = now
		State.lastStateSentAtIso = isoNow()
		State.lastSuccessfulSnapshotAt = State.snapshotStats and State.snapshotStats.capturedAt or State.lastStateSentAtIso
		State.lastStateUploadError = nil
		stateDirty = false
		updateSnapshotLabel()
	else
		State.lastStateUploadError = tostring(err)
		local lastWarning = tonumber(State.lastStateUploadWarningClock) or 0
		if now - lastWarning > 20 then
			State.lastStateUploadWarningClock = now
			addOutput("Bridge state upload failed: " .. tostring(err), "Warning", "CodexStudioBridge")
		end
	end
end

local function setProperties(instance, properties)
	local failures = {}
	for propertyName, rawValue in pairs(properties or {}) do
		if propertyName ~= "Parent" and propertyName ~= "Source" then
			local ok, err = pcall(function()
				instance[propertyName] = deserializeValue(rawValue, instance, propertyName)
			end)
			if not ok then
				table.insert(failures, propertyName .. ": " .. tostring(err))
			end
		end
	end
	return failures
end

local function withUndo(label, callback)
	local recording = nil
	local beginOk = pcall(function()
		recording = ChangeHistoryService:TryBeginRecording("CodexBridge_" .. label, "Codex Bridge: " .. label)
	end)

	local ok, result = pcall(callback)

	if beginOk and recording then
		pcall(function()
			local operation = ok and Enum.FinishRecordingOperation.Commit or Enum.FinishRecordingOperation.Cancel
			ChangeHistoryService:FinishRecording(recording, operation)
		end)
	else
		pcall(function()
			ChangeHistoryService:SetWaypoint("Codex Bridge: " .. label)
		end)
	end

	if not ok then
		error(result)
	end

	return result
end

local function updateScriptSource(scriptInstance, newSource)
	if not scriptInstance:IsA("LuaSourceContainer") then
		error("Target is not a Script, LocalScript, or ModuleScript.")
	end

	local updated = false
	local firstError = nil
	local ok, err = pcall(function()
		ScriptEditorService:UpdateSourceAsync(scriptInstance, function()
			return tostring(newSource or "")
		end)
		updated = true
	end)
	if not ok then
		firstError = err
	end

	if not updated then
		local directOk, directErr = pcall(function()
			scriptInstance.Source = tostring(newSource or "")
			updated = true
		end)
		if not directOk then
			error("Could not update script source: " .. tostring(firstError or directErr))
		end
	end
end

local function runDiagnostic()
	local diagnostics = {
		at = isoNow(),
		outputErrors = {},
		duplicateSiblingNames = {},
		disabledScripts = {},
	}

	for _, entry in ipairs(outputBuffer) do
		local entryType = tostring(entry.type or "")
		local message = tostring(entry.message or "")
		if entryType:lower():find("error") or message:lower():find("error") then
			table.insert(diagnostics.outputErrors, entry)
		end
	end

	local function visit(instance)
		if diagnostics.scanned and diagnostics.scanned >= 10000 then
			diagnostics.truncated = true
			return
		end
		diagnostics.scanned = (diagnostics.scanned or 0) + 1
		local seen = {}
		for _, child in ipairs(instance:GetChildren()) do
			local key = child.ClassName .. ":" .. child.Name
			if seen[key] then
				table.insert(diagnostics.duplicateSiblingNames, {
					parent = safeFullName(instance),
					name = child.Name,
					className = child.ClassName,
				})
			else
				seen[key] = true
			end
			if child:IsA("LuaSourceContainer") then
				local ok, disabled = pcall(function()
					return child.Disabled
				end)
				if ok and disabled then
					table.insert(diagnostics.disabledScripts, {
						id = getInstanceId(child),
						path = safeFullName(child),
						className = child.ClassName,
					})
				end
			end
			visit(child)
		end
	end

	local roots = getPriorityRoots()
	for _, root in ipairs(roots) do
		visit(root)
		if diagnostics.truncated then
			break
		end
	end

	return diagnostics
end

local function getSearchRoots(includeInternal)
	local roots = {}
	local included = {}

	if includeInternal then
		for _, child in ipairs(game:GetChildren()) do
			table.insert(roots, child)
		end
		return roots
	end

	roots, included = getPriorityRoots()
	return roots
end

local function walkRoots(payload, callback)
	local options = makeTraversalOptions({
		depth = payload and payload.depth or 20,
		maxNodes = payload and payload.maxScanNodes or 10000,
		includeInternal = payload and payload.includeInternal,
		shallowInternal = false,
	})
	local roots = getSearchRoots(options.includeInternal)
	local visited = 0
	local stopped = false

	local function visit(instance, depth)
		if stopped or not instance then
			return
		end
		visited += 1
		if visited > options.maxNodes then
			stopped = true
			return
		end
		if callback(instance, depth) == false then
			stopped = true
			return
		end
		if depth >= options.depth then
			return
		end
		for _, child in ipairs(instance:GetChildren()) do
			visit(child, depth + 1)
			if stopped then
				return
			end
		end
	end

	for _, root in ipairs(roots) do
		visit(root, 0)
		if stopped then
			break
		end
	end

	return visited, stopped
end

local function matchesQuery(instance, query)
	if query == "" then
		return true
	end
	local path = safeFullName(instance):lower()
	local name = instance.Name:lower()
	local className = instance.ClassName:lower()
	return name:find(query, 1, true) ~= nil or path:find(query, 1, true) ~= nil or className:find(query, 1, true) ~= nil
end

local function searchInstances(payload, scriptsOnly)
	local query = tostring(payload.query or payload.name or ""):lower()
	local maxResults = math.max(1, math.min(tonumber(payload.maxResults) or 100, 500))
	local results = {}

	local scanned, stopped = walkRoots(payload, function(instance)
		if scriptsOnly and not instance:IsA("LuaSourceContainer") then
			return true
		end
		if matchesQuery(instance, query) then
			table.insert(results, {
				id = getInstanceId(instance),
				name = instance.Name,
				className = instance.ClassName,
				path = safeFullName(instance),
				childCount = #instance:GetChildren(),
				hasSource = instance:IsA("LuaSourceContainer"),
			})
			if #results >= maxResults then
				return false
			end
		end
		return true
	end)

	return {
		query = query,
		results = results,
		resultCount = #results,
		scanned = scanned,
		truncated = stopped,
	}
end

splitLines = function(text)
	local lines = {}
	text = tostring(text or "")
	text = text:gsub("\r\n", "\n"):gsub("\r", "\n")
	for line in (text .. "\n"):gmatch("(.-)\n") do
		table.insert(lines, line)
	end
	return lines
end

local function searchSource(payload)
	local query = tostring(payload.query or "")
	local loweredQuery = query:lower()
	local maxResults = math.max(1, math.min(tonumber(payload.maxResults) or 50, 200))
	local contextLines = math.max(0, math.min(tonumber(payload.contextLines) or 2, 5))
	local matches = {}

	if loweredQuery == "" then
		error("searchSource requires payload.query.")
	end

	local scanned, stopped = walkRoots(payload, function(instance)
		if not instance:IsA("LuaSourceContainer") then
			return true
		end

		local ok, sourceOrErr = pcall(function()
			return readScriptSource(instance)
		end)
		if not ok then
			return true
		end

		local lines = splitLines(sourceOrErr)
		for lineNumber, line in ipairs(lines) do
			if line:lower():find(loweredQuery, 1, true) then
				local before = {}
				local after = {}
				for index = math.max(1, lineNumber - contextLines), lineNumber - 1 do
					table.insert(before, { line = index, text = lines[index] })
				end
				for index = lineNumber + 1, math.min(#lines, lineNumber + contextLines) do
					table.insert(after, { line = index, text = lines[index] })
				end
				table.insert(matches, {
					id = getInstanceId(instance),
					name = instance.Name,
					className = instance.ClassName,
					path = safeFullName(instance),
					line = lineNumber,
					text = line,
					before = before,
					after = after,
				})
				if #matches >= maxResults then
					return false
				end
			end
		end
		return true
	end)

	return {
		query = query,
		matches = matches,
		matchCount = #matches,
		scanned = scanned,
		truncated = stopped,
	}
end

local function getOutputDiagnostics(payload)
	local limit = math.max(1, math.min(tonumber(payload.limit) or 100, OUTPUT_LIMIT))
	local startIndex = math.max(1, #outputBuffer - limit + 1)
	local errors = {}
	local warnings = {}
	local infos = {}
	local grouped = {}

	for index = startIndex, #outputBuffer do
		local entry = outputBuffer[index]
		local kind = tostring(entry.type or "")
		local message = tostring(entry.message or "")
		local loweredKind = kind:lower()
		local bucket = infos
		if loweredKind:find("error", 1, true) then
			bucket = errors
		elseif loweredKind:find("warn", 1, true) then
			bucket = warnings
		end
		table.insert(bucket, entry)

		local groupKey = message:gsub("%s+", " ")
		if #groupKey > 120 then
			groupKey = string.sub(groupKey, 1, 120)
		end
		grouped[groupKey] = (grouped[groupKey] or 0) + 1
	end

	local groups = {}
	for message, count in pairs(grouped) do
		table.insert(groups, { message = message, count = count })
	end

	table.sort(groups, function(a, b)
		return a.count > b.count
	end)

	return {
		at = isoNow(),
		limit = limit,
		totalBuffered = #outputBuffer,
		errorCount = #errors,
		warningCount = #warnings,
		infoCount = #infos,
		errors = errors,
		warnings = warnings,
		groups = groups,
	}
end

local function isErrorOrWarning(entry)
	local kind = tostring(entry.type or ""):lower()
	return kind:find("error", 1, true) ~= nil or kind:find("warn", 1, true) ~= nil
end

local function getOutputErrors(payload)
	local limit = math.max(1, math.min(tonumber(payload.limit) or 100, OUTPUT_LIMIT))
	local startIndex = math.max(1, #outputBuffer - limit + 1)
	local entries = {}
	local groupsByMessage = {}

	for index = startIndex, #outputBuffer do
		local entry = outputBuffer[index]
		if isErrorOrWarning(entry) then
			table.insert(entries, entry)
			local key = tostring(entry.message or ""):gsub("%s+", " ")
			if #key > 160 then
				key = string.sub(key, 1, 160)
			end
			if not groupsByMessage[key] then
				groupsByMessage[key] = {
					message = key,
					count = 0,
					firstAt = entry.at,
					lastAt = entry.at,
					type = entry.type,
				}
			end
			groupsByMessage[key].count += 1
			groupsByMessage[key].lastAt = entry.at
		end
	end

	local groups = {}
	for _, group in pairs(groupsByMessage) do
		table.insert(groups, group)
	end
	table.sort(groups, function(a, b)
		return a.count > b.count
	end)

	return {
		at = isoNow(),
		limit = limit,
		entries = entries,
		groups = groups,
		count = #entries,
		totalBuffered = #outputBuffer,
	}
end

local function traceOutputError(payload)
	local text = tostring(payload.text or payload.message or "")
	local limit = math.max(1, math.min(tonumber(payload.limit) or 10, 50))
	if text == "" then
		for index = #outputBuffer, 1, -1 do
			if isErrorOrWarning(outputBuffer[index]) then
				text = tostring(outputBuffer[index].message or "")
				break
			end
		end
	end
	if text == "" then
		return { text = "", references = {}, candidates = {}, message = "No error text provided or found in Output." }
	end

	local references = {}
	for path, lineNumber in text:gmatch("([%w_%.%s]+):(%d+):") do
		table.insert(references, {
			path = path:gsub("^%s+", ""):gsub("%s+$", ""),
			line = tonumber(lineNumber),
		})
	end

	local candidateMap = {}
	local candidates = {}
	local function addCandidate(instance, reason, line)
		local id = getInstanceId(instance)
		if candidateMap[id] then
			return
		end
		candidateMap[id] = true
		table.insert(candidates, {
			id = id,
			name = instance.Name,
			className = instance.ClassName,
			path = safeFullName(instance),
			reason = reason,
			line = line,
		})
	end

	for _, reference in ipairs(references) do
		local resolved = resolvePath(reference.path)
		if resolved and resolved:IsA("LuaSourceContainer") then
			addCandidate(resolved, "exact path from output", reference.line)
		else
			local tail = reference.path:match("([%w_]+)$") or reference.path
			walkRoots({ maxScanNodes = 10000 }, function(instance)
				if #candidates >= limit then
					return false
				end
				if instance:IsA("LuaSourceContainer") and matchesQuery(instance, tail:lower()) then
					addCandidate(instance, "matched output script token", reference.line)
				end
				return true
			end)
		end
	end

	if #candidates < limit then
		for token in text:gmatch("[%w_]+") do
			if #token >= 5 then
				local lowered = token:lower()
				walkRoots({ maxScanNodes = 10000 }, function(instance)
					if #candidates >= limit then
						return false
					end
					if instance:IsA("LuaSourceContainer") and matchesQuery(instance, lowered) then
						addCandidate(instance, "matched error text token: " .. token, nil)
					end
					return true
				end)
			end
			if #candidates >= limit then
				break
			end
		end
	end

	return {
		text = text,
		references = references,
		candidates = candidates,
		candidateCount = #candidates,
	}
end

