local function runServiceBool(methodName)
	local ok, value = pcall(function()
		return RunService[methodName](RunService)
	end)
	if ok then
		return value == true
	end
	return nil
end

function V6.getRunServiceSnapshot()
	return {
		isStudio = runServiceBool("IsStudio"),
		isRunning = runServiceBool("IsRunning"),
		isEdit = runServiceBool("IsEdit"),
		isRunMode = runServiceBool("IsRunMode"),
		isClient = runServiceBool("IsClient"),
		isServer = runServiceBool("IsServer"),
	}
end

function V6.detectLocalContextType(runServiceSnapshot)
	local flags = runServiceSnapshot or V6.getRunServiceSnapshot()
	if flags.isRunning == true and flags.isServer == true then
		return "testServer"
	end
	if flags.isRunning == true and flags.isClient == true then
		return "testClient"
	end
	if flags.isRunning == true then
		return "runtime"
	end
	if flags.isEdit == true then
		return "edit"
	end
	return "unknown"
end

function V6.getPluginConnectionTargetType(name)
	local ok, value = pcall(function()
		return Enum.PluginConnectionTargetType[name]
	end)
	if ok then
		return value
	end
	return nil
end

function V6.collectPluginConnections(targetTypeName)
	local records = {}
	if not PluginConnectionService then
		return records, "PluginConnectionService is unavailable in this Studio session."
	end
	local enumValue = V6.getPluginConnectionTargetType(targetTypeName)
	if not enumValue then
		return records, "Enum.PluginConnectionTargetType." .. tostring(targetTypeName) .. " is unavailable."
	end
	local ok, connectionsOrError = pcall(function()
		return PluginConnectionService:GetPluginConnectionsOfType(enumValue)
	end)
	if not ok then
		return records, tostring(connectionsOrError)
	end
	for index, connection in ipairs(connectionsOrError or {}) do
		local canSend = false
		local hasSendMessage = false
		local pingOk = pcall(function()
			local sendMessage = connection.SendMessage
			if type(sendMessage) == "function" then
				hasSendMessage = true
				connection:SendMessage(encodeJson({
					type = "codexStudioBridgePing",
					version = VERSION,
					contextId = contextId,
					at = isoNow(),
				}) or "{}")
			end
		end)
		canSend = hasSendMessage and pingOk == true
		table.insert(records, {
			index = index,
			targetType = targetTypeName,
			description = tostring(connection),
			canSendMessage = canSend,
		})
	end
	return records, nil
end

function V6.getStudioContexts()
	local flags = V6.getRunServiceSnapshot()
	local localContextType = V6.detectLocalContextType(flags)
	local currentPlayers = Players:GetPlayers()
	local contexts = {
		{
			contextType = localContextType,
			contextId = contextId,
			source = "localPlugin",
			available = true,
			runService = flags,
			place = {
				name = game.Name,
				placeId = game.PlaceId,
				gameId = game.GameId,
				jobId = game.JobId,
			},
			playerCount = #currentPlayers,
		},
	}
	local connectionRecords = {}
	local connectionErrors = {}
	for _, targetType in ipairs({ "Edit", "Test" }) do
		local records, err = V6.collectPluginConnections(targetType)
		for _, record in ipairs(records) do
			table.insert(connectionRecords, record)
		end
		if err then
			table.insert(connectionErrors, { targetType = targetType, message = err })
		end
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		localContextType = localContextType,
		localContextId = contextId,
		pluginConnection = {
			serviceAvailable = PluginConnectionService ~= nil,
			connectionCount = #connectionRecords,
			connections = connectionRecords,
			errors = connectionErrors,
			runtimeMirroringAvailable = #connectionRecords > 0,
			limitation = #connectionRecords > 0 and nil or "Using V5 local-plugin fallback. Start Play/Test with compatible Studio plugin contexts to expose separate runtime mirrors.",
		},
		contexts = contexts,
		contextCount = #contexts,
	}
	State.studioContexts = result
	return result
end

local function serializeAttributes(instance)
	local result = {}
	if not instance then
		return result
	end
	local ok, attributes = pcall(function()
		return instance:GetAttributes()
	end)
	if not ok or type(attributes) ~= "table" then
		return result
	end
	for key, value in pairs(attributes) do
		result[tostring(key)] = serializeValue(value)
	end
	return result
end

local function summarizeSelection()
	local selected = {}
	for _, instance in ipairs(Selection:Get()) do
		table.insert(selected, {
			id = getInstanceId(instance),
			name = instance.Name,
			className = instance.ClassName,
			path = safeFullName(instance),
		})
	end
	return selected
end

local function outputCounts(limit)
	local outputErrors = getOutputErrors({ limit = limit or 100 })
	return {
		totalBuffered = #outputBuffer,
		errorOrWarningCount = outputErrors.count or 0,
		groupCount = outputErrors.groups and #outputErrors.groups or 0,
	}
end

local function getRuntimeStatus()
	local players = Players:GetPlayers()
	local flags = V6.getRunServiceSnapshot()
	local isRunning = flags.isRunning
	local isEdit = flags.isEdit
	local mode = "unknown"
	if isRunning == true and isEdit ~= true then
		mode = "play"
	elseif isEdit == true or isRunning == false then
		mode = "edit"
	end
	local contextType = V6.detectLocalContextType(flags)

	local result = {
		at = isoNow(),
		version = VERSION,
		mode = mode,
		contextType = contextType,
		contextId = contextId,
		source = "localPlugin",
		runtimeMirroringAvailable = State.studioContexts
			and State.studioContexts.pluginConnection
			and State.studioContexts.pluginConnection.runtimeMirroringAvailable
			or false,
		runService = flags,
		place = {
			name = game.Name,
			placeId = game.PlaceId,
			gameId = game.GameId,
			jobId = game.JobId,
		},
		players = {
			count = #players,
		},
		selection = summarizeSelection(),
		output = outputCounts(100),
		plugin = {
			paired = paired,
			bridgeUrl = bridgeUrl,
			pendingCommands = #commandOrder,
			lastSnapshotStats = State.snapshotStats,
			lastBuildStatus = State.buildStatus and State.buildStatus.summary or nil,
		},
	}

	State.runtimeStatus = result
	if updateRuntimeLabel then
		updateRuntimeLabel()
	end
	return result
end

local function summarizeFolder(path)
	local instance = resolvePath(path)
	if not instance then
		return {
			path = path,
			exists = false,
			childCount = 0,
			classCounts = {},
		}
	end

	local classCounts = {}
	for _, child in ipairs(instance:GetChildren()) do
		classCounts[child.ClassName] = (classCounts[child.ClassName] or 0) + 1
	end

	return {
		path = safeFullName(instance),
		exists = true,
		id = getInstanceId(instance),
		name = instance.Name,
		className = instance.ClassName,
		childCount = #instance:GetChildren(),
		classCounts = classCounts,
		attributes = serializeAttributes(instance),
	}
end

local function summarizeCharacter(player)
	local character = player.Character
	if not character then
		return nil
	end
	local humanoid = character:FindFirstChildOfClass("Humanoid")
	local root = character:FindFirstChild("HumanoidRootPart")
	local summary = {
		id = getInstanceId(character),
		name = character.Name,
		path = safeFullName(character),
		attributes = serializeAttributes(character),
	}
	if humanoid then
		summary.humanoid = {
			health = humanoid.Health,
			maxHealth = humanoid.MaxHealth,
			state = serializeValue(humanoid:GetState()),
			attributes = serializeAttributes(humanoid),
		}
	end
	if root and root:IsA("BasePart") then
		summary.root = {
			position = serializeValue(root.Position),
			velocity = serializeValue(root.AssemblyLinearVelocity),
		}
	end
	return summary
end

local function getRuntimeSnapshot(payload)
	payload = payload or {}
	local folderPaths = type(payload.folderPaths) == "table" and payload.folderPaths or RULEFORGE_WORLD_PATHS
	local players = {}
	for _, player in ipairs(Players:GetPlayers()) do
		table.insert(players, {
			userId = player.UserId,
			name = player.Name,
			displayName = player.DisplayName,
			team = player.Team and player.Team.Name or nil,
			attributes = serializeAttributes(player),
			character = summarizeCharacter(player),
		})
	end

	local folders = {}
	for _, path in ipairs(folderPaths) do
		table.insert(folders, summarizeFolder(path))
	end

	local result = {
		at = isoNow(),
		contextType = V6.detectLocalContextType(),
		contextId = contextId,
		source = "localPlugin",
		status = getRuntimeStatus(),
		workspace = {
			attributes = serializeAttributes(workspace),
			currentCamera = workspace.CurrentCamera and safeFullName(workspace.CurrentCamera) or nil,
		},
		players = players,
		playerCount = #players,
		folders = folders,
	}
	State.runtimeStatus = result.status
	if updateRuntimeLabel then
		updateRuntimeLabel()
	end
	return result
end

function V6.getContextSnapshot(payload)
	payload = payload or {}
	local target = tostring(payload.context or payload.contextType or payload.target or "all")
	local contexts = V6.getStudioContexts()
	local snapshot = getRuntimeSnapshot(payload.snapshot or {})
	local localType = snapshot.contextType or "unknown"
	local result = {
		at = isoNow(),
		requested = target,
		contexts = contexts,
		snapshots = {},
		unavailable = {},
	}

	local function addLocalSnapshot(key)
		result.snapshots[key] = snapshot
	end

	if target == "all" then
		addLocalSnapshot(localType)
		if localType ~= "edit" then
			result.unavailable.edit = "Edit-context snapshot is not separately mirrored by this Studio session."
		end
		if localType ~= "testServer" then
			result.unavailable.server = "Test server context is not separately mirrored by this Studio session."
		end
		if localType ~= "testClient" then
			result.unavailable.client = "Test client context is not separately mirrored by this Studio session."
		end
	elseif target == "edit" then
		if localType == "edit" or localType == "unknown" then
			addLocalSnapshot("edit")
		else
			result.unavailable.edit = "The local plugin is currently reporting " .. tostring(localType) .. "; edit mirroring is unavailable."
		end
	elseif target == "server" or target == "testServer" then
		if localType == "testServer" then
			addLocalSnapshot("testServer")
		else
			result.unavailable.server = "Test server context is unavailable; using V5 fallback cannot inspect server-only data separately."
		end
	elseif target == "client" or target == "testClient" then
		if localType == "testClient" or localType == "runtime" then
			addLocalSnapshot("testClient")
		else
			result.unavailable.client = "Test client context is unavailable; using V5 fallback cannot inspect client-only data separately."
		end
	else
		result.unavailable[target] = "Unknown context target. Use edit, server, client, or all."
	end

	State.contextSnapshot = result
	return result
end

local function addRemoteReference(expected, name, expectedClass, source)
	if type(name) ~= "string" or name == "" then
		return
	end
	if not expected[name] then
		expected[name] = {
			name = name,
			expectedClasses = {},
			references = {},
		}
	end
	if expectedClass and expectedClass ~= "" then
		expected[name].expectedClasses[expectedClass] = true
	end
	if source and #expected[name].references < 20 then
		table.insert(expected[name].references, source)
	end
end

local function addRemotePatternMatches(expected, line, pattern, expectedClass, reference)
	for name in line:gmatch(pattern) do
		addRemoteReference(expected, name, expectedClass, reference)
	end
end

local function tableKeysSorted(map)
	local keys = {}
	for key in pairs(map or {}) do
		table.insert(keys, key)
	end
	table.sort(keys)
	return keys
end

local function inferExpectedRemotes(payload)
	local expected = {}
	local scriptCount = 0
	local scanned, stopped = walkRoots({
		maxScanNodes = payload and payload.maxScanNodes or 12000,
		depth = payload and payload.depth or 20,
	}, function(instance)
		if not instance:IsA("LuaSourceContainer") then
			return true
		end
		scriptCount += 1
		local ok, source = pcall(function()
			return readScriptSource(instance)
		end)
		if not ok then
			return true
		end
		local lines = splitLines(source)
		for lineNumber, line in ipairs(lines) do
			local reference = {
				id = getInstanceId(instance),
				path = safeFullName(instance),
				line = lineNumber,
				text = line,
			}
			addRemotePatternMatches(expected, line, "Remotes%s*:%s*WaitForChild%s*%(%s*[\"']([^\"']+)[\"']", "Remote", reference)
			addRemotePatternMatches(expected, line, "Remotes%s*:%s*FindFirstChild%s*%(%s*[\"']([^\"']+)[\"']", "Remote", reference)
			addRemotePatternMatches(expected, line, "WaitForChild%s*%(%s*[\"']Remotes[\"']%s*%)%s*:%s*WaitForChild%s*%(%s*[\"']([^\"']+)[\"']", "Remote", reference)
			addRemotePatternMatches(expected, line, "WaitForChild%s*%(%s*[\"']Remotes[\"']%s*%)%s*:%s*FindFirstChild%s*%(%s*[\"']([^\"']+)[\"']", "Remote", reference)
			addRemotePatternMatches(expected, line, "getRemoteEvent%s*%(%s*[\"']([^\"']+)[\"']", "RemoteEvent", reference)
			addRemotePatternMatches(expected, line, "ensureRemoteEvent%s*%(%s*[\"']([^\"']+)[\"']", "RemoteEvent", reference)
			addRemotePatternMatches(expected, line, "getRemoteFunction%s*%(%s*[\"']([^\"']+)[\"']", "RemoteFunction", reference)
			addRemotePatternMatches(expected, line, "ensureRemoteFunction%s*%(%s*[\"']([^\"']+)[\"']", "RemoteFunction", reference)
		end
		return true
	end)

	local expectedList = {}
	for _, name in ipairs(tableKeysSorted(expected)) do
		local item = expected[name]
		table.insert(expectedList, {
			name = item.name,
			expectedClasses = tableKeysSorted(item.expectedClasses),
			references = item.references,
		})
	end

	return expectedList, {
		scanned = scanned,
		truncated = stopped,
		scriptCount = scriptCount,
	}
end

local function getRemoteInventory(payload)
	payload = payload or {}
	local remotesFolder = resolvePath(payload.path or "ReplicatedStorage.Remotes")
	local actual = {}
	local actualByName = {}
	local actualRemoteCount = 0

	if remotesFolder then
		for _, child in ipairs(remotesFolder:GetChildren()) do
			local item = {
				id = getInstanceId(child),
				name = child.Name,
				className = child.ClassName,
				path = safeFullName(child),
				childCount = #child:GetChildren(),
				attributes = serializeAttributes(child),
			}
			table.insert(actual, item)
			actualByName[child.Name] = item
			if child:IsA("RemoteEvent") or child:IsA("RemoteFunction") then
				actualRemoteCount += 1
			end
		end
	end
	table.sort(actual, function(a, b)
		return a.name < b.name
	end)

	local expected, inference = inferExpectedRemotes(payload)
	local missing = {}
	local mismatched = {}
	for _, item in ipairs(expected) do
		local actualItem = actualByName[item.name]
		if not actualItem then
			table.insert(missing, item)
		else
			local expectedClasses = {}
			for _, className in ipairs(item.expectedClasses or {}) do
				expectedClasses[className] = true
			end
			if expectedClasses.RemoteEvent and actualItem.className ~= "RemoteEvent" then
				table.insert(mismatched, { expected = item, actual = actualItem, message = "Expected RemoteEvent." })
			elseif expectedClasses.RemoteFunction and actualItem.className ~= "RemoteFunction" then
				table.insert(mismatched, { expected = item, actual = actualItem, message = "Expected RemoteFunction." })
			end
		end
	end

	local result = {
		at = isoNow(),
		path = remotesFolder and safeFullName(remotesFolder) or tostring(payload.path or "ReplicatedStorage.Remotes"),
		folderExists = remotesFolder ~= nil,
		actual = actual,
		actualCount = #actual,
		actualRemoteCount = actualRemoteCount,
		expected = expected,
		expectedCount = #expected,
		missing = missing,
		missingCount = #missing,
		mismatched = mismatched,
		mismatchedCount = #mismatched,
		inference = inference,
	}
	State.remoteInventory = result
	if updateRuntimeLabel then
		updateRuntimeLabel()
	end
	return result
end

function V6.listToSet(list)
	local set = {}
	for _, value in ipairs(list or {}) do
		if type(value) == "string" and value ~= "" then
			set[value] = true
		elseif type(value) == "table" and type(value.name) == "string" and value.name ~= "" then
			set[value.name] = true
		end
	end
	return set
end

function V6.remoteClassForExpected(item)
	local classSet = {}
	for _, className in ipairs(item.expectedClasses or {}) do
		classSet[className] = true
	end
	if classSet.RemoteFunction then
		return "RemoteFunction"
	end
	return "RemoteEvent"
end

function V6.extractSetupRemoteNames()
	local setup = resolvePath("ServerScriptService.Systems.00_SetupRemotes")
	local result = {
		path = "ServerScriptService.Systems.00_SetupRemotes",
		exists = setup ~= nil,
		remoteNames = {},
		remoteCount = 0,
		sourceReadable = false,
		message = "",
	}
	if not setup or not setup:IsA("LuaSourceContainer") then
		result.message = "00_SetupRemotes was not found as a script-like object."
		return result
	end

	local ok, sourceOrError = pcall(function()
		return readScriptSource(setup)
	end)
	if not ok then
		result.message = "Could not read 00_SetupRemotes: " .. tostring(sourceOrError)
		return result
	end

	result.sourceReadable = true
	local inRemoteList = false
	local names = {}
	for _, line in ipairs(splitLines(sourceOrError)) do
		if line:find("ALL_REMOTE_EVENTS", 1, true) and line:find("{", 1, true) then
			inRemoteList = true
		end
		if inRemoteList then
			for name in line:gmatch("[\"']([^\"']+)[\"']") do
				names[name] = true
			end
			if line:find("}", 1, true) then
				break
			end
		end
	end

	result.remoteNames = tableKeysSorted(names)
	result.remoteCount = #result.remoteNames
	if result.remoteCount == 0 then
		result.message = "No quoted names were found in ALL_REMOTE_EVENTS."
	end
	return result
end

local normalizeBlueprint
local previewBuildPlan
local applyBuildPlan

function V6.buildRemoteRepairBlueprint(remoteDoctor)
	local doctor = remoteDoctor or {}
	local remotes = doctor.missingForRepair or {}
	local expectedByName = {}
	for _, item in ipairs((doctor.editRemotes and doctor.editRemotes.expected) or {}) do
		expectedByName[item.name] = item
	end

	local steps = {
		{
			type = "ensureFolder",
			path = "ReplicatedStorage.Remotes",
		},
	}
	for _, name in ipairs(remotes) do
		local expected = expectedByName[name]
		local stepType = "ensureRemoteEvent"
		if expected and V6.remoteClassForExpected(expected) == "RemoteFunction" then
			stepType = "ensureRemoteFunction"
		end
		table.insert(steps, {
			type = stepType,
			path = "ReplicatedStorage.Remotes." .. name,
		})
	end

	return {
		name = "Ruleforge Remote Repair",
		mode = "supervised",
		source = "diagnoseRemoteSystem",
		steps = steps,
	}
end

function V6.diagnoseRemoteSystem(payload)
	payload = payload or {}
	local editInventory = getRemoteInventory(payload.remotePayload or {})
	local setup = V6.extractSetupRemoteNames()
	local setupSet = V6.listToSet(setup.remoteNames)
	local inferredSet = V6.listToSet(editInventory.expected)
	local actualSet = V6.listToSet(editInventory.actual)
	local expectedUnion = {}
	for name in pairs(setupSet) do
		expectedUnion[name] = true
	end
	for name in pairs(inferredSet) do
		expectedUnion[name] = true
	end

	local missingFromEdit = {}
	local presentInEdit = {}
	for _, name in ipairs(tableKeysSorted(expectedUnion)) do
		if actualSet[name] then
			table.insert(presentInEdit, name)
		else
			table.insert(missingFromEdit, name)
		end
	end

	local setupOnly = {}
	for _, name in ipairs(tableKeysSorted(setupSet)) do
		if not inferredSet[name] then
			table.insert(setupOnly, name)
		end
	end

	local inferredOnly = {}
	for _, name in ipairs(tableKeysSorted(inferredSet)) do
		if not setupSet[name] then
			table.insert(inferredOnly, name)
		end
	end

	local runtimeInventory = nil
	local runtimeMessage = "Separate runtime remote mirror is unavailable; using local plugin context."
	local contexts = V6.getStudioContexts()
	if contexts.pluginConnection.runtimeMirroringAvailable then
		runtimeMessage = "PluginConnectionService reported test connections, but this plugin is using local read fallback until a mirrored runtime responder is available."
	end

	local result = {
		at = isoNow(),
		contexts = contexts,
		editRemotes = editInventory,
		runtimeRemotes = runtimeInventory,
		runtimeMessage = runtimeMessage,
		setupRemotes = setup,
		expected = {
			union = tableKeysSorted(expectedUnion),
			unionCount = #tableKeysSorted(expectedUnion),
			setupOnly = setupOnly,
			inferredOnly = inferredOnly,
			setupCount = setup.remoteCount,
			inferredCount = editInventory.expectedCount,
		},
		comparison = {
			editActualCount = editInventory.actualCount,
			editActualRemoteCount = editInventory.actualRemoteCount,
			presentInEdit = presentInEdit,
			presentInEditCount = #presentInEdit,
			missingFromEdit = missingFromEdit,
			missingFromEditCount = #missingFromEdit,
			mismatched = editInventory.mismatched,
			mismatchedCount = editInventory.mismatchedCount,
		},
		blockers = {},
		warnings = {},
	}

	if not editInventory.folderExists then
		table.insert(result.blockers, "ReplicatedStorage.Remotes is missing.")
	end
	if #missingFromEdit > 0 then
		table.insert(result.blockers, tostring(#missingFromEdit) .. " expected remotes are missing from edit-time ReplicatedStorage.Remotes.")
	end
	if editInventory.mismatchedCount > 0 then
		table.insert(result.blockers, tostring(editInventory.mismatchedCount) .. " remotes have class conflicts.")
	end
	if not contexts.pluginConnection.runtimeMirroringAvailable then
		table.insert(result.warnings, "Separate test server/client remote inventory is not available in this Studio session.")
	end
	if setup.remoteCount == 0 then
		table.insert(result.warnings, "00_SetupRemotes did not expose a readable ALL_REMOTE_EVENTS list.")
	end

	result.missingForRepair = missingFromEdit
	result.repairBlueprint = V6.buildRemoteRepairBlueprint(result)
	result.repairPreview = previewBuildPlan({ blueprint = result.repairBlueprint })
	State.remoteDoctor = result
	if updateRuntimeLabel then
		updateRuntimeLabel()
	end
	return result
end

local function addValidationIssue(issues, severity, code, message, path, details)
	table.insert(issues, {
		severity = severity,
		code = code,
		message = message,
		path = path,
		details = details,
	})
end

local function countIssues(issues, severity)
	local count = 0
	for _, issue in ipairs(issues) do
		if issue.severity == severity then
			count += 1
		end
	end
	return count
end

local function validateRuleforgeProject(payload)
	payload = payload or {}
	local issues = {}
	local checkedPaths = {}

	for _, rule in ipairs(RULEFORGE_REQUIRED_PATHS) do
		local instance = resolvePath(rule.path)
		table.insert(checkedPaths, summarizeFolder(rule.path))
		if not instance then
			addValidationIssue(issues, rule.severity or "warning", "missingPath", "Missing expected Ruleforge path.", rule.path)
		elseif rule.className and instance.ClassName ~= rule.className then
			addValidationIssue(issues, "error", "classMismatch", "Path has the wrong class.", rule.path, {
				actual = instance.ClassName,
				expected = rule.className,
			})
		elseif instance:IsA("Folder") and #instance:GetChildren() == 0 and rule.severity ~= "error" then
			addValidationIssue(issues, "warning", "emptyFolder", "Expected Ruleforge folder is empty.", safeFullName(instance))
		end
	end

	local systemsFolder = resolvePath("ServerScriptService.Systems")
	if systemsFolder then
		for _, name in ipairs(RULEFORGE_SYSTEMS) do
			local child = systemsFolder:FindFirstChild(name)
			if not child then
				addValidationIssue(issues, "error", "missingSystem", "Missing expected Ruleforge system.", "ServerScriptService.Systems." .. name)
			elseif not child:IsA("LuaSourceContainer") then
				addValidationIssue(issues, "error", "systemClassMismatch", "Expected system is not script-like.", safeFullName(child), {
					className = child.ClassName,
				})
			end
		end
	end

	local diagnostics = runDiagnostic()
	for _, item in ipairs(diagnostics.disabledScripts or {}) do
		addValidationIssue(issues, "warning", "disabledScript", "Script is disabled.", item.path, item)
	end
	for _, item in ipairs(diagnostics.duplicateSiblingNames or {}) do
		addValidationIssue(issues, "warning", "duplicateSiblingName", "Duplicate sibling name detected.", item.parent, item)
	end

	local remoteInventory = getRemoteInventory(payload.remotePayload or {})
	if not remoteInventory.folderExists then
		addValidationIssue(issues, "error", "missingRemotesFolder", "ReplicatedStorage.Remotes does not exist.", "ReplicatedStorage.Remotes")
	end
	for index, item in ipairs(remoteInventory.missing or {}) do
		if index > 30 then
			addValidationIssue(issues, "warning", "missingRemoteOverflow", "More expected remotes are missing than shown.", "ReplicatedStorage.Remotes", {
				remaining = #remoteInventory.missing - 30,
			})
			break
		end
		addValidationIssue(issues, "warning", "missingExpectedRemote", "Expected remote inferred from source is not present.", "ReplicatedStorage.Remotes." .. item.name, item)
	end
	for _, item in ipairs(remoteInventory.mismatched or {}) do
		addValidationIssue(issues, "error", "remoteClassMismatch", item.message or "Remote has unexpected class.", item.actual and item.actual.path or "ReplicatedStorage.Remotes", item)
	end

	local v4Arena = {
		exists = resolvePath("Workspace.RuleforgeV4Arena") ~= nil,
		floor = resolvePath("Workspace.RuleforgeV4Arena.Floor") ~= nil,
		extractionPad = resolvePath("Workspace.RuleforgeV4Arena.ExtractionPad") ~= nil,
		spawns = resolvePath("Workspace.RuleforgeV4Arena.Spawns") ~= nil,
	}
	if v4Arena.exists and (not v4Arena.floor or not v4Arena.extractionPad or not v4Arena.spawns) then
		addValidationIssue(issues, "warning", "incompleteV4Arena", "RuleforgeV4Arena exists but is incomplete.", "Workspace.RuleforgeV4Arena", v4Arena)
	elseif not v4Arena.exists then
		addValidationIssue(issues, "info", "noV4Arena", "Optional RuleforgeV4Arena is not present.", "Workspace.RuleforgeV4Arena")
	end

	local result = {
		at = isoNow(),
		valid = countIssues(issues, "error") == 0,
		issues = issues,
		summary = {
			errors = countIssues(issues, "error"),
			warnings = countIssues(issues, "warning"),
			info = countIssues(issues, "info"),
			total = #issues,
			missingRemotes = remoteInventory.missingCount,
		},
		checkedPaths = checkedPaths,
		remoteInventory = {
			actualCount = remoteInventory.actualCount,
			expectedCount = remoteInventory.expectedCount,
			missingCount = remoteInventory.missingCount,
			mismatchedCount = remoteInventory.mismatchedCount,
		},
		diagnostics = {
			disabledScripts = #(diagnostics.disabledScripts or {}),
			duplicateSiblingNames = #(diagnostics.duplicateSiblingNames or {}),
			outputErrors = #(diagnostics.outputErrors or {}),
			scanned = diagnostics.scanned,
			truncated = diagnostics.truncated,
		},
		v4Arena = v4Arena,
	}
	State.ruleforgeValidation = result
	if updateRuntimeLabel then
		updateRuntimeLabel()
	end
	return result
end

local function getPlaytestReport(payload)
	payload = payload or {}
	local errors = getOutputErrors({ limit = payload.outputLimit or 100 })
	local traces = {}
	for index = #errors.entries, 1, -1 do
		if #traces >= 5 then
			break
		end
		local entry = errors.entries[index]
		table.insert(traces, {
			entry = entry,
			trace = traceOutputError({ text = entry.message, limit = 8 }),
		})
	end

	local report = {
		at = isoNow(),
		status = getRuntimeStatus(),
		snapshot = getRuntimeSnapshot(payload.snapshot or {}),
		remoteInventory = getRemoteInventory(payload.remotePayload or {}),
		validation = validateRuleforgeProject(payload.validation or {}),
		outputErrors = errors,
		traces = traces,
		buildStatus = State.buildStatus or {
			message = "No build plan has been applied in this Studio session.",
		},
	}
	State.playtestReport = report
	if updateRuntimeLabel then
		updateRuntimeLabel()
	end
	return report
end

function V6.isBridgeNoiseMessage(message)
	local lowered = tostring(message or ""):lower()
	return lowered:find("codexstudiobridge", 1, true) ~= nil
		or lowered:find("failed to load icon", 1, true) ~= nil
		or lowered:find("image failed to load", 1, true) ~= nil
		or lowered:find("bridge token", 1, true) ~= nil
		or lowered:find("studio request is missing a valid bridge token", 1, true) ~= nil
		or lowered:find("output upload failed", 1, true) ~= nil
		or lowered:find("bridge state upload failed", 1, true) ~= nil
		or lowered:find("httperror: connectfail", 1, true) ~= nil
		or lowered:find("datastore request was added to queue", 1, true) ~= nil
		or lowered:find("request queue fills", 1, true) ~= nil
end

function V6.clampScore(value)
	value = tonumber(value) or 0
	if value < 0 then
		return 0
	end
	if value > 100 then
		return 100
	end
	return math.floor(value + 0.5)
end

function V6.summarizeIssuesByCode(issues)
	local byCode = {}
	for _, issue in ipairs(issues or {}) do
		local code = tostring(issue.code or "unknown")
		byCode[code] = (byCode[code] or 0) + 1
	end
	return byCode
end

function V6.getScenarioCatalog()
	local scenarios = {}
	for _, scenario in ipairs(V6.SCENARIOS) do
		table.insert(scenarios, {
			name = scenario.name,
			title = scenario.title,
			file = scenario.file,
			description = scenario.description,
			safeToPreview = true,
			safeToApply = true,
			requiresApproval = true,
			previewCommand = "tools/bridge.cmd scenario " .. scenario.name .. " preview",
			applyCommand = "tools/bridge.cmd scenario " .. scenario.name .. " apply",
		})
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		scenarios = scenarios,
		count = #scenarios,
		notes = {
			"Preview is read-only.",
			"Apply runs through Full Trust using the blueprint/build-plan path.",
		},
	}
	State.scenarioCatalog = result
	return result
end

function V6.getRuleforgeHealthScore(payload)
	payload = payload or {}
	local contexts = V6.getStudioContexts()
	local remoteDoctor = V6.diagnoseRemoteSystem(payload.remotePayload or {})
	local validation = validateRuleforgeProject(payload.validation or {})
	local errors = getOutputErrors({ limit = payload.outputLimit or 100 })
	local catalog = V6.getScenarioCatalog()

	local nonBridgeErrorCount = 0
	for _, entry in ipairs(errors.entries or {}) do
		if not V6.isBridgeNoiseMessage(entry.message) then
			nonBridgeErrorCount += 1
		end
	end

	local contextScore = 50
	if contexts.pluginConnection.runtimeMirroringAvailable then
		contextScore = 100
	elseif contexts.localContextType == "testServer" or contexts.localContextType == "testClient" or contexts.localContextType == "runtime" then
		contextScore = 80
	elseif contexts.localContextType == "edit" then
		contextScore = 65
	end

	local remoteScore = V6.clampScore(100 - (remoteDoctor.comparison.missingFromEditCount * 3) - (remoteDoctor.comparison.mismatchedCount * 20))
	local systemErrors = 0
	local worldWarnings = 0
	for _, issue in ipairs(validation.issues or {}) do
		if issue.code == "missingSystem" or issue.code == "systemClassMismatch" then
			systemErrors += 1
		elseif tostring(issue.path or ""):find("^Workspace") then
			worldWarnings += 1
		end
	end
	local systemsScore = V6.clampScore(100 - (systemErrors * 18))
	local worldScore = V6.clampScore(100 - (worldWarnings * 8))
	local outputScore = V6.clampScore(100 - (nonBridgeErrorCount * 12))
	local scenarioScore = catalog.count > 0 and 100 or 0

	local blockers = {}
	local warnings = {}
	for _, blocker in ipairs(remoteDoctor.blockers or {}) do
		table.insert(blockers, blocker)
	end
	if not contexts.pluginConnection.runtimeMirroringAvailable then
		table.insert(blockers, "Separate edit/server/client context mirroring is unavailable; runtime reads are V5 fallback.")
	end
	if validation.summary and validation.summary.errors and validation.summary.errors > 0 then
		table.insert(blockers, tostring(validation.summary.errors) .. " Ruleforge validation errors.")
	end
	if nonBridgeErrorCount > 0 then
		table.insert(warnings, tostring(nonBridgeErrorCount) .. " recent non-bridge Output errors or warnings.")
	end
	for _, warning in ipairs(remoteDoctor.warnings or {}) do
		table.insert(warnings, warning)
	end

	local total = V6.clampScore(
		contextScore * 0.18
		+ remoteScore * 0.24
		+ systemsScore * 0.18
		+ worldScore * 0.14
		+ outputScore * 0.16
		+ scenarioScore * 0.10
	)
	local nextFix = "playtest-report"
	if remoteDoctor.comparison.missingFromEditCount > 0 or remoteDoctor.comparison.mismatchedCount > 0 then
		nextFix = "remote-repair preview"
	elseif validation.summary and validation.summary.errors and validation.summary.errors > 0 then
		nextFix = "ruleforge-validate"
	elseif nonBridgeErrorCount > 0 then
		nextFix = "bug-context"
	elseif not contexts.pluginConnection.runtimeMirroringAvailable then
		nextFix = "Start/refresh Play mode, then run contexts."
	end

	local result = {
		at = isoNow(),
		score = total,
		categories = {
			contexts = contextScore,
			remotes = remoteScore,
			systems = systemsScore,
			worldSetup = worldScore,
			outputErrors = outputScore,
			scenarioReadiness = scenarioScore,
		},
		blockers = blockers,
		warnings = warnings,
		nextRecommendedFix = nextFix,
		details = {
			contexts = {
				localContextType = contexts.localContextType,
				runtimeMirroringAvailable = contexts.pluginConnection.runtimeMirroringAvailable,
			},
			remotes = {
				missing = remoteDoctor.comparison.missingFromEditCount,
				mismatched = remoteDoctor.comparison.mismatchedCount,
				actual = remoteDoctor.comparison.editActualCount,
				expected = remoteDoctor.expected.unionCount,
			},
			validation = validation.summary,
			issueCodes = V6.summarizeIssuesByCode(validation.issues),
			output = {
				totalErrorOrWarningCount = errors.count,
				nonBridgeErrorOrWarningCount = nonBridgeErrorCount,
			},
			scenarios = catalog.count,
		},
	}
	State.healthScore = result
	if updateRuntimeLabel then
		updateRuntimeLabel()
	end
	return result
end

