function V7.array(value)
	if type(value) == "table" then
		return value
	end
	return {}
end

function V7.profileSummary(profile)
	profile = profile or V7.DEFAULT_PROFILE
	return {
		id = tostring(profile.id or "universal"),
		name = tostring(profile.name or profile.id or "Universal Roblox Project"),
		genre = tostring(profile.genre or "general"),
		description = tostring(profile.description or ""),
		scenarioCount = type(profile.scenarios) == "table" and #profile.scenarios or 0,
	}
end

function V7.profilesFromPayload(payload)
	payload = payload or {}
	if type(payload.profiles) == "table" and #payload.profiles > 0 then
		return payload.profiles
	end
	return { V7.DEFAULT_PROFILE }
end

function V7.profileFromPayload(payload)
	payload = payload or {}
	if type(payload.profile) == "table" then
		return payload.profile
	end
	if type(payload.activeProfile) == "table" then
		return payload.activeProfile
	end
	local profileId = tostring(payload.profileId or payload.activeProfileId or "")
	if profileId ~= "" then
		for _, profile in ipairs(V7.profilesFromPayload(payload)) do
			if tostring(profile.id or "") == profileId then
				return profile
			end
		end
	end
	for _, profile in ipairs(V7.profilesFromPayload(payload)) do
		if tostring(profile.id or "") == "universal" then
			return profile
		end
	end
	return V7.DEFAULT_PROFILE
end

function V7.expected(profile, key)
	local expected = type(profile.expected) == "table" and profile.expected or {}
	return V7.array(expected[key])
end

function V7.detectList(profile, key)
	local detection = type(profile.detection) == "table" and profile.detection or {}
	return V7.array(detection[key])
end

function V7.pathFromRule(rule)
	if type(rule) == "string" then
		return rule
	end
	if type(rule) == "table" then
		return tostring(rule.path or rule.name or "")
	end
	return ""
end

function V7.ruleSeverity(rule, fallback)
	if type(rule) == "table" and type(rule.severity) == "string" then
		return rule.severity
	end
	return fallback or "warning"
end

function V7.addIssue(issues, severity, code, message, path, details)
	table.insert(issues, {
		severity = severity,
		code = code,
		message = message,
		path = path,
		details = details,
	})
end

function V7.issueCounts(issues)
	local summary = {
		errors = 0,
		warnings = 0,
		info = 0,
		total = #issues,
		byCode = {},
	}
	for _, issue in ipairs(issues or {}) do
		if issue.severity == "error" then
			summary.errors += 1
		elseif issue.severity == "info" then
			summary.info += 1
		else
			summary.warnings += 1
		end
		local code = tostring(issue.code or "unknown")
		summary.byCode[code] = (summary.byCode[code] or 0) + 1
	end
	return summary
end

V7.GAME_OWNED_ROOTS = {
	Workspace = true,
	ReplicatedStorage = true,
	ServerScriptService = true,
	ServerStorage = true,
	StarterGui = true,
	StarterPlayer = true,
	ReplicatedFirst = true,
	Lighting = true,
	Teams = true,
	SoundService = true,
	MaterialService = true,
}

V7.CLEANUP_INTERNAL_ROOTS = {
	MemStorageService = true,
	PluginGuiService = true,
	CoreGui = true,
	Stats = true,
	GuiService = true,
	RunService = true,
	LogService = true,
}

function V7.rootNameFromPath(path)
	local text = tostring(path or "")
	return text:match("^([^%.]+)") or text
end

function V7.pathIsGameOwned(path)
	return V7.GAME_OWNED_ROOTS[V7.rootNameFromPath(path)] == true
end

function V7.pathIsCleanupInternal(path)
	return V7.CLEANUP_INTERNAL_ROOTS[V7.rootNameFromPath(path)] == true
end

function V7.isLegitRobloxDuplicate(parentPath, className)
	local parent = tostring(parentPath or "")
	local childClass = tostring(className or "")
	if parent:find("HumanoidDescription", 1, true) then
		return childClass == "BodyPartDescription" or childClass == "AccessoryDescription"
	end
	return false
end

function V7.cleanupSkipReason(parentPath, path, className)
	if V7.pathIsCleanupInternal(parentPath) or V7.pathIsCleanupInternal(path) then
		return "internal"
	end
	if V7.isLegitRobloxDuplicate(parentPath, className) then
		return "legitRobloxDuplicate"
	end
	if not V7.pathIsGameOwned(parentPath) and not V7.pathIsGameOwned(path) then
		return "nonGameRoot"
	end
	return nil
end

function V7.remoteFolder()
	return resolvePath("ReplicatedStorage.Remotes")
end

function V7.remoteExists(name)
	local folder = V7.remoteFolder()
	if not folder then
		return nil
	end
	return folder:FindFirstChild(tostring(name or ""))
end

function V7.findScriptByName(name)
	local result = searchInstances({ query = tostring(name or ""), maxResults = 20 }, true)
	for _, item in ipairs(result.results or {}) do
		if item.name == name then
			return resolveInstance(item.id or item.path), item
		end
	end
	local first = result.results and result.results[1]
	if first then
		return resolveInstance(first.id or first.path), first
	end
	return nil
end

function V7.detectProjectProfile(payload)
	payload = payload or {}
	local profiles = V7.profilesFromPayload(payload)
	local scored = {}
	local selected = nil

	for _, profile in ipairs(profiles) do
		local score = 0
		local maxScore = 0
		local matched = {}
		local missing = {}

		for _, path in ipairs(V7.detectList(profile, "paths")) do
			maxScore += 6
			if resolvePath(path) then
				score += 6
				table.insert(matched, "path:" .. tostring(path))
			else
				table.insert(missing, "path:" .. tostring(path))
			end
		end

		for _, name in ipairs(V7.detectList(profile, "scriptNames")) do
			maxScore += 7
			local instance = V7.findScriptByName(name)
			if instance then
				score += 7
				table.insert(matched, "script:" .. tostring(name))
			else
				table.insert(missing, "script:" .. tostring(name))
			end
		end

		for _, name in ipairs(V7.detectList(profile, "remoteNames")) do
			maxScore += 7
			if V7.remoteExists(name) then
				score += 7
				table.insert(matched, "remote:" .. tostring(name))
			else
				table.insert(missing, "remote:" .. tostring(name))
			end
		end

		for _, path in ipairs(V7.detectList(profile, "uiRoots")) do
			maxScore += 5
			if resolvePath(path) then
				score += 5
				table.insert(matched, "ui:" .. tostring(path))
			end
		end

		for _, name in ipairs(V7.detectList(profile, "workspaceNames")) do
			maxScore += 5
			if resolvePath("Workspace." .. tostring(name)) then
				score += 5
				table.insert(matched, "workspace:" .. tostring(name))
			end
		end

		for _, pattern in ipairs(V7.detectList(profile, "sourcePatterns")) do
			maxScore += 4
			local ok, result = pcall(function()
				return searchSource({ query = tostring(pattern), maxResults = 1, contextLines = 0 })
			end)
			if ok and result and tonumber(result.matchCount) and result.matchCount > 0 then
				score += 4
				table.insert(matched, "source:" .. tostring(pattern))
			end
		end

		if maxScore == 0 then
			maxScore = 1
			if tostring(profile.id or "") == "universal" then
				score = 1
			end
		end

		local entry = {
			profile = V7.profileSummary(profile),
			score = score,
			maxScore = maxScore,
			confidence = V6.clampScore((score / maxScore) * 100),
			matched = matched,
			missing = missing,
		}
		table.insert(scored, entry)
		if not selected or entry.score > selected.score or (entry.score == selected.score and entry.confidence > selected.confidence) then
			selected = entry
		end
	end

	table.sort(scored, function(a, b)
		if a.score == b.score then
			return a.confidence > b.confidence
		end
		return a.score > b.score
	end)

	if not selected then
		selected = {
			profile = V7.profileSummary(V7.DEFAULT_PROFILE),
			score = 1,
			maxScore = 1,
			confidence = 100,
			matched = { "fallback:universal" },
			missing = {},
		}
	end

	local result = {
		at = isoNow(),
		selected = selected.profile,
		selectedScore = selected.score,
		selectedConfidence = selected.confidence,
		profiles = scored,
		place = {
			name = game.Name,
			placeId = game.PlaceId,
			gameId = game.GameId,
			jobId = game.JobId,
		},
	}
	State.projectDetection = result
	State.projectProfile = selected.profile
	if updateRuntimeLabel then
		updateRuntimeLabel()
	end
	return result
end

function V7.getActiveProjectProfile(payload)
	payload = payload or {}
	local profile = V7.profileFromPayload(payload)
	local result = {
		at = isoNow(),
		activeProfile = V7.profileSummary(profile),
		mode = payload.memory and payload.memory.activeMode or "auto",
		placeKey = payload.placeKey,
		place = {
			name = game.Name,
			placeId = game.PlaceId,
			gameId = game.GameId,
			jobId = game.JobId,
		},
		detection = State.projectDetection,
	}
	State.projectProfile = result.activeProfile
	return result
end

function V7.validateProject(payload)
	payload = payload or {}
	local profile = V7.profileFromPayload(payload)
	local issues = {}
	local checked = {}

	for _, rule in ipairs(V7.expected(profile, "paths")) do
		local path = V7.pathFromRule(rule)
		local instance = resolvePath(path)
		table.insert(checked, path)
		if not instance then
			V7.addIssue(issues, V7.ruleSeverity(rule, "warning"), "missingPath", "Expected project path is missing.", path, rule)
		elseif type(rule) == "table" and rule.className and instance.ClassName ~= rule.className then
			V7.addIssue(issues, "error", "classMismatch", "Project path has the wrong class.", path, {
				actual = instance.ClassName,
				expected = rule.className,
			})
		elseif instance:IsA("Folder") and #instance:GetChildren() == 0 and V7.ruleSeverity(rule, "warning") ~= "error" then
			V7.addIssue(issues, "warning", "emptyFolder", "Expected project folder is empty.", safeFullName(instance), rule)
		end
	end

	for _, rule in ipairs(V7.expected(profile, "scripts")) do
		local path = V7.pathFromRule(rule)
		local instance = nil
		if path ~= "" and path:find(".", 1, true) then
			instance = resolvePath(path)
		else
			instance = V7.findScriptByName(path)
		end
		if not instance then
			V7.addIssue(issues, V7.ruleSeverity(rule, "error"), "missingScript", "Expected script is missing.", path, rule)
		elseif not instance:IsA("LuaSourceContainer") then
			V7.addIssue(issues, "error", "scriptClassMismatch", "Expected script path is not script-like.", safeFullName(instance), {
				actual = instance.ClassName,
			})
		else
			local ok, disabled = pcall(function()
				return instance.Disabled
			end)
			if ok and disabled then
				V7.addIssue(issues, "warning", "disabledScript", "Script is disabled.", safeFullName(instance), {
					className = instance.ClassName,
				})
			end
		end
	end

	local remoteFolder = V7.remoteFolder()
	if #V7.expected(profile, "remotes") > 0 and not remoteFolder then
		V7.addIssue(issues, "error", "missingRemotesFolder", "ReplicatedStorage.Remotes is missing.", "ReplicatedStorage.Remotes")
	end
	for _, rule in ipairs(V7.expected(profile, "remotes")) do
		local name = tostring(rule.name or rule.path or rule)
		local expectedClass = tostring(rule.className or "RemoteEvent")
		local remote = remoteFolder and remoteFolder:FindFirstChild(name) or nil
		if not remote then
			V7.addIssue(issues, "warning", "missingRemote", "Expected remote is missing.", "ReplicatedStorage.Remotes." .. name, rule)
		elseif remote.ClassName ~= expectedClass then
			V7.addIssue(issues, "error", "remoteClassMismatch", "Remote has the wrong class.", safeFullName(remote), {
				actual = remote.ClassName,
				expected = expectedClass,
			})
		end
	end

	for _, path in ipairs(V7.expected(profile, "uiRoots")) do
		if not resolvePath(path) then
			V7.addIssue(issues, "warning", "missingUiRoot", "Expected UI root is missing.", tostring(path))
		end
	end

	for _, path in ipairs(V7.expected(profile, "workspace")) do
		if not resolvePath(path) then
			V7.addIssue(issues, "warning", "missingWorldPath", "Expected world path is missing.", tostring(path))
		end
	end

	local diagnostics = runDiagnostic()
	local duplicateLimit = math.min(#(diagnostics.duplicateSiblingNames or {}), tonumber(payload.duplicateLimit) or 250)
	local shownDuplicates = 0
	local skippedDuplicates = {
		internal = 0,
		legitRobloxDuplicate = 0,
		nonGameRoot = 0,
	}
	for index = 1, #(diagnostics.duplicateSiblingNames or {}) do
		local item = diagnostics.duplicateSiblingNames[index]
		local skipReason = V7.cleanupSkipReason(item.parent, item.parent, item.className)
		if skipReason then
			skippedDuplicates[skipReason] = (skippedDuplicates[skipReason] or 0) + 1
		else
			shownDuplicates += 1
			if shownDuplicates > duplicateLimit then
				break
			end
			V7.addIssue(issues, "warning", "duplicateSiblingName", "Duplicate sibling name detected.", item.parent, item)
		end
	end
	local meaningfulDuplicateCount = shownDuplicates
	if meaningfulDuplicateCount > duplicateLimit then
		V7.addIssue(issues, "info", "duplicateSiblingOverflow", "More duplicate names exist than shown.", "game", {
			remaining = meaningfulDuplicateCount - duplicateLimit,
		})
	end

	local summary = V7.issueCounts(issues)
	summary.missingRemotes = summary.byCode.missingRemote or 0
	summary.duplicateSiblingNames = meaningfulDuplicateCount
	summary.rawDuplicateSiblingNames = #(diagnostics.duplicateSiblingNames or {})
	summary.skippedDuplicateSiblingNames = skippedDuplicates
	summary.disabledScripts = #(diagnostics.disabledScripts or {})

	local result = {
		at = isoNow(),
		profile = V7.profileSummary(profile),
		valid = summary.errors == 0,
		issues = issues,
		summary = summary,
		checkedPaths = checked,
		diagnostics = {
			disabledScripts = #(diagnostics.disabledScripts or {}),
			duplicateSiblingNames = #(diagnostics.duplicateSiblingNames or {}),
			outputErrors = #(diagnostics.outputErrors or {}),
			scanned = diagnostics.scanned,
			truncated = diagnostics.truncated,
		},
	}
	State.projectValidation = result
	if updateRuntimeLabel then
		updateRuntimeLabel()
	end
	return result
end

function V7.weight(profile, name, fallback)
	local health = type(profile.health) == "table" and profile.health or {}
	local weights = type(health.weights) == "table" and health.weights or {}
	return tonumber(weights[name]) or fallback
end

function V7.projectHealthScore(payload)
	payload = payload or {}
	local profile = V7.profileFromPayload(payload)
	local validation = V7.validateProject(payload)
	local contexts = V6.getStudioContexts()
	local errors = getOutputErrors({ limit = payload.outputLimit or 100 })
	local scenarios = V7.getProjectScenarioCatalog(payload)
	local nonBridgeErrorCount = 0
	for _, entry in ipairs(errors.entries or {}) do
		if not V6.isBridgeNoiseMessage(entry.message) then
			nonBridgeErrorCount += 1
		end
	end

	local byCode = validation.summary.byCode or {}
	local contextScore = 50
	if contexts.pluginConnection.runtimeMirroringAvailable then
		contextScore = 100
	elseif contexts.localContextType == "testServer" or contexts.localContextType == "testClient" or contexts.localContextType == "runtime" then
		contextScore = 80
	elseif contexts.localContextType == "edit" then
		contextScore = 65
	end
	local structureScore = V6.clampScore(100 - ((byCode.missingPath or 0) * 15) - ((byCode.classMismatch or 0) * 25))
	local scriptScore = V6.clampScore(100 - ((byCode.missingScript or 0) * 18) - ((byCode.scriptClassMismatch or 0) * 25) - ((byCode.disabledScript or 0) * 8))
	local remoteScore = V6.clampScore(100 - ((byCode.missingRemote or 0) * 12) - ((byCode.remoteClassMismatch or 0) * 25) - ((byCode.missingRemotesFolder or 0) * 30))
	local uiScore = V6.clampScore(100 - ((byCode.missingUiRoot or 0) * 20))
	local worldScore = V6.clampScore(100 - ((byCode.missingWorldPath or 0) * 10) - ((byCode.emptyFolder or 0) * 3))
	local outputScore = V6.clampScore(100 - (nonBridgeErrorCount * 12))
	local scenarioScore = scenarios.count > 0 and 100 or 70
	local totalWeight = V7.weight(profile, "contexts", 0.14)
		+ V7.weight(profile, "structure", 0.18)
		+ V7.weight(profile, "scripts", 0.16)
		+ V7.weight(profile, "remotes", 0.16)
		+ V7.weight(profile, "ui", 0.10)
		+ V7.weight(profile, "world", 0.10)
		+ V7.weight(profile, "output", 0.10)
		+ V7.weight(profile, "scenarios", 0.06)

	local weighted = (
		contextScore * V7.weight(profile, "contexts", 0.14)
		+ structureScore * V7.weight(profile, "structure", 0.18)
		+ scriptScore * V7.weight(profile, "scripts", 0.16)
		+ remoteScore * V7.weight(profile, "remotes", 0.16)
		+ uiScore * V7.weight(profile, "ui", 0.10)
		+ worldScore * V7.weight(profile, "world", 0.10)
		+ outputScore * V7.weight(profile, "output", 0.10)
		+ scenarioScore * V7.weight(profile, "scenarios", 0.06)
	) / math.max(totalWeight, 0.01)

	local blockers = {}
	local warnings = {}
	if validation.summary.errors > 0 then
		table.insert(blockers, tostring(validation.summary.errors) .. " project validation errors.")
	end
	if byCode.missingRemote and byCode.missingRemote > 0 then
		table.insert(warnings, tostring(byCode.missingRemote) .. " profile remotes are missing.")
	end
	if nonBridgeErrorCount > 0 then
		table.insert(warnings, tostring(nonBridgeErrorCount) .. " recent non-bridge Output errors or warnings.")
	end
	if not contexts.pluginConnection.runtimeMirroringAvailable then
		table.insert(warnings, "Separate edit/server/client context mirroring is unavailable; using local context fallback.")
	end

	local result = {
		at = isoNow(),
		profile = V7.profileSummary(profile),
		score = V6.clampScore(weighted),
		categories = {
			contexts = contextScore,
			structure = structureScore,
			scripts = scriptScore,
			remotes = remoteScore,
			ui = uiScore,
			world = worldScore,
			output = outputScore,
			scenarios = scenarioScore,
		},
		blockers = blockers,
		warnings = warnings,
		nextRecommendedFix = V7.nextActionFromValidation(validation, nonBridgeErrorCount, scenarios),
		details = {
			validation = validation.summary,
			contexts = {
				localContextType = contexts.localContextType,
				runtimeMirroringAvailable = contexts.pluginConnection.runtimeMirroringAvailable,
			},
			output = {
				totalErrorOrWarningCount = errors.count,
				nonBridgeErrorOrWarningCount = nonBridgeErrorCount,
			},
			scenarios = scenarios.count,
		},
	}
	State.projectHealth = result
	if updateRuntimeLabel then
		updateRuntimeLabel()
	end
	return result
end

V7.getProjectHealthScore = V7.projectHealthScore

function V7.nextActionFromValidation(validation, nonBridgeErrorCount, scenarios)
	local byCode = validation.summary and validation.summary.byCode or {}
	if validation.summary and validation.summary.errors and validation.summary.errors > 0 then
		return "project validate"
	end
	if byCode.missingRemote and byCode.missingRemote > 0 then
		return "template preview basic-lobby or project scenario preview"
	end
	if nonBridgeErrorCount and nonBridgeErrorCount > 0 then
		return "bug-context"
	end
	if byCode.duplicateSiblingName and byCode.duplicateSiblingName > 0 then
		return "project cleanup preview"
	end
	if scenarios and scenarios.count and scenarios.count > 0 then
		return "project scenarios"
	end
	return "project report"
end

function V7.getProjectNextActions(payload)
	payload = payload or {}
	local profile = V7.profileFromPayload(payload)
	local validation = V7.validateProject(payload)
	local health = V7.getProjectHealthScore(payload)
	local cleanup = V7.getProjectCleanupPlan(payload)
	local actions = {}
	local byCode = validation.summary.byCode or {}

	if validation.summary.errors > 0 then
		table.insert(actions, { priority = 1, title = "Fix project validation errors", command = "tools/bridge.cmd project validate", count = validation.summary.errors })
	end
	if byCode.missingRemote and byCode.missingRemote > 0 then
		table.insert(actions, { priority = 2, title = "Create missing profile remotes through a supervised project plan", command = "tools/bridge.cmd template preview basic-lobby", count = byCode.missingRemote })
	end
	if health.details.output.nonBridgeErrorOrWarningCount > 0 then
		table.insert(actions, { priority = 3, title = "Trace the latest real Output error", command = "tools/bridge.cmd bug-context", count = health.details.output.nonBridgeErrorOrWarningCount })
	end
	if cleanup.summary.renameActions > 0 then
		table.insert(actions, { priority = 4, title = "Preview duplicate-name cleanup", command = "tools/bridge.cmd project cleanup preview", count = cleanup.summary.renameActions })
	end
	if #actions == 0 then
		table.insert(actions, { priority = 5, title = "Run a project report or starter scenario", command = "tools/bridge.cmd project report", count = 0 })
	end

	return {
		at = isoNow(),
		profile = V7.profileSummary(profile),
		score = health.score,
		actions = actions,
	}
end

function V7.getProjectReport(payload)
	payload = payload or {}
	local report = {
		at = isoNow(),
		profile = V7.profileSummary(V7.profileFromPayload(payload)),
		activeProfile = V7.getActiveProjectProfile(payload),
		runtime = getRuntimeStatus(payload.runtime or {}),
		contexts = V6.getStudioContexts(),
		validation = V7.validateProject(payload),
		health = V7.getProjectHealthScore(payload),
		nextActions = V7.getProjectNextActions(payload),
		cleanup = V7.getProjectCleanupPlan(payload),
		outputErrors = getOutputErrors({ limit = payload.outputLimit or 100 }),
		scenarios = V7.getProjectScenarioCatalog(payload),
		buildStatus = State.buildStatus or {
			message = "No build plan has been applied in this Studio session.",
		},
	}
	State.projectReport = report
	if updateRuntimeLabel then
		updateRuntimeLabel()
	end
	return report
end

function V7.getProjectScenarioCatalog(payload)
	local profile = V7.profileFromPayload(payload)
	local scenarios = {}
	for _, scenario in ipairs(V7.array(profile.scenarios)) do
		table.insert(scenarios, {
			name = tostring(scenario.name or ""),
			title = tostring(scenario.title or scenario.name or ""),
			file = tostring(scenario.file or ""),
			description = tostring(scenario.description or ""),
			safeToPreview = true,
			safeToApply = true,
			requiresApproval = true,
			previewCommand = "tools/bridge.cmd project scenario " .. tostring(scenario.name or "") .. " preview",
			applyCommand = "tools/bridge.cmd project scenario " .. tostring(scenario.name or "") .. " apply",
		})
	end
	return {
		at = isoNow(),
		profile = V7.profileSummary(profile),
		scenarios = scenarios,
		count = #scenarios,
		notes = {
			"Preview is read-only.",
			"Apply runs through Full Trust using the blueprint/build-plan path.",
		},
	}
end

function V7.getTemplateCatalog(payload)
	payload = payload or {}
	local templates = {}
	for _, template in ipairs(V7.array(payload.templates)) do
		table.insert(templates, {
			id = tostring(template.id or ""),
			title = tostring(template.title or template.id or ""),
			genre = tostring(template.genre or ""),
			file = tostring(template.file or ""),
			safeToPreview = true,
			safeToApply = true,
			requiresApproval = true,
			previewCommand = "tools/bridge.cmd template preview " .. tostring(template.id or ""),
			applyCommand = "tools/bridge.cmd template apply " .. tostring(template.id or ""),
		})
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		templates = templates,
		count = #templates,
	}
	State.templateCatalog = result
	return result
end

function V7.keepEmptyPathSet(profile)
	local set = {}
	local cleanup = type(profile.cleanup) == "table" and profile.cleanup or {}
	for _, path in ipairs(V7.array(cleanup.keepEmptyPaths)) do
		set[tostring(path)] = true
	end
	for _, rule in ipairs(V7.expected(profile, "paths")) do
		local path = V7.pathFromRule(rule)
		if V7.ruleSeverity(rule, "warning") == "error" then
			set[path] = true
		end
	end
	return set
end

function V7.getProjectCleanupPlan(payload)
	payload = payload or {}
	local profile = V7.profileFromPayload(payload)
	local keepEmpty = V7.keepEmptyPathSet(profile)
	local suffix = "_Codex"
	if type(profile.cleanup) == "table" and type(profile.cleanup.duplicateRenameSuffix) == "string" then
		suffix = profile.cleanup.duplicateRenameSuffix
	end
	local actions = {}
	local scanned = 0
	local maxNodes = math.max(100, math.min(tonumber(payload.maxNodes) or 10000, 25000))
	local skipped = {
		internal = 0,
		legitRobloxDuplicate = 0,
		emptyFolderSuggestion = 0,
		nonGameRoot = 0,
	}

	local function addAction(action)
		if #actions < 500 then
			table.insert(actions, action)
		end
	end

	local function visit(instance)
		if scanned >= maxNodes then
			return
		end
		scanned += 1
		local children = instance:GetChildren()
		local seen = {}
		for _, child in ipairs(children) do
			local key = child.ClassName .. ":" .. child.Name
			local list = seen[key]
			if not list then
				list = {}
				seen[key] = list
			end
			table.insert(list, child)
		end
		for _, group in pairs(seen) do
			if #group > 1 then
				for index = 2, #group do
					local child = group[index]
					local parentPath = safeFullName(instance)
					local childPath = safeFullName(child)
					local skipReason = V7.cleanupSkipReason(parentPath, childPath, child.ClassName)
					if skipReason then
						skipped[skipReason] = (skipped[skipReason] or 0) + 1
					else
						addAction({
							type = "renameDuplicate",
							enabled = true,
							targetId = getInstanceId(child),
							path = childPath,
							parentPath = parentPath,
							oldName = child.Name,
							newName = child.Name .. suffix .. tostring(index),
							className = child.ClassName,
						})
					end
				end
			end
		end
		local instancePath = safeFullName(instance)
		if instance:IsA("Folder") and #children == 0 and not keepEmpty[instancePath] then
			if V7.pathIsCleanupInternal(instancePath) then
				skipped.internal += 1
			elseif not V7.pathIsGameOwned(instancePath) then
				skipped.nonGameRoot += 1
			else
				skipped.emptyFolderSuggestion += 1
				addAction({
					type = "deleteEmptyFolder",
					enabled = false,
					targetId = getInstanceId(instance),
					path = instancePath,
					className = instance.ClassName,
					message = "Preview only by default; set enabled true in a reviewed cleanup plan to delete.",
				})
			end
		end
		for _, child in ipairs(children) do
			visit(child)
			if scanned >= maxNodes then
				return
			end
		end
	end

	for _, root in ipairs(getPriorityRoots()) do
		visit(root)
		if scanned >= maxNodes then
			break
		end
	end

	local renameActions = 0
	local deleteSuggestions = 0
	local enabledActions = 0
	for _, action in ipairs(actions) do
		if action.type == "renameDuplicate" then
			renameActions += 1
		elseif action.type == "deleteEmptyFolder" then
			deleteSuggestions += 1
		end
		if action.enabled == true then
			enabledActions += 1
		end
	end

	local result = {
		at = isoNow(),
		profile = V7.profileSummary(profile),
		mode = "preview",
		actions = actions,
		summary = {
			actions = #actions,
			renameActions = renameActions,
			deleteSuggestions = deleteSuggestions,
			enabledActions = enabledActions,
			skipped = skipped,
			scanned = scanned,
			truncated = scanned >= maxNodes,
		},
		notes = {
			"Only game-owned duplicate renames are enabled by default.",
			"Studio/plugin internals and normal Roblox HumanoidDescription duplicates are skipped.",
			"Empty-folder deletes are preview-only unless a reviewed action explicitly enables them.",
		},
	}
	State.projectCleanupPlan = result
	return result
end

function V7.applyCleanupPlan(payload)
	payload = payload or {}
	local plan = payload.cleanupPlan or payload.plan or {}
	return withUndo("ApplyCleanupPlan", function()
		local result = {
			appliedAt = isoNow(),
			profile = V7.profileSummary(V7.profileFromPayload(payload)),
			renamed = {},
			deleted = {},
			skipped = {},
			failed = {},
		}
		for _, action in ipairs(V7.array(plan.actions)) do
			if action.enabled == true then
				local instance = resolveInstance(action.targetId or action.id or action.path)
				if not instance then
					table.insert(result.failed, { action = action, message = "Target no longer exists." })
				elseif action.type == "renameDuplicate" then
					local newName = tostring(action.newName or "")
					if newName == "" then
						table.insert(result.failed, { action = action, message = "Missing newName." })
					else
						local oldPath = safeFullName(instance)
						instance.Name = newName
						table.insert(result.renamed, {
							oldPath = oldPath,
							newPath = safeFullName(instance),
							newName = newName,
						})
					end
				elseif action.type == "deleteEmptyFolder" then
					if instance:IsA("Folder") and #instance:GetChildren() == 0 then
						local oldPath = safeFullName(instance)
						instance:Destroy()
						table.insert(result.deleted, { path = oldPath })
					else
						table.insert(result.failed, { action = action, message = "Target is not an empty Folder." })
					end
				else
					table.insert(result.skipped, { action = action, message = "Unsupported cleanup action type." })
				end
			else
				table.insert(result.skipped, { action = action, message = "Action disabled." })
			end
		end
		result.summary = {
			renamed = #result.renamed,
			deleted = #result.deleted,
			skipped = #result.skipped,
			failed = #result.failed,
		}
		stateDirty = true
		State.projectCleanupPlan = result
		return result
	end)
end

function V8.harnessPaths()
	return {
		"ReplicatedStorage.CodexTestHarness",
		"ServerScriptService.CodexTestHarness",
		"Workspace.CodexTestHarness",
	}
end

function V8.getHarnessStatus()
	local paths = {}
	local installedCount = 0
	for _, path in ipairs(V8.harnessPaths()) do
		local instance = resolvePath(path)
		local exists = instance ~= nil
		if exists then
			installedCount += 1
		end
		table.insert(paths, {
			path = path,
			exists = exists,
			id = instance and getInstanceId(instance) or nil,
			className = instance and instance.ClassName or nil,
			childCount = instance and #instance:GetChildren() or 0,
		})
	end
	local result = {
		at = isoNow(),
		installed = installedCount == #paths,
		partial = installedCount > 0 and installedCount < #paths,
		installedCount = installedCount,
		paths = paths,
	}
	State.harnessStatus = result
	return result
end

function V8.getRuntimeMirrorStatus(payload)
	payload = payload or {}
	local contexts = V6.getStudioContexts()
	local mode = "fallback"
	if contexts.pluginConnection and contexts.pluginConnection.runtimeMirroringAvailable then
		mode = "mirrored-probe"
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		mode = mode,
		localContextType = contexts.localContextType,
		localContextId = contexts.localContextId,
		contextCount = contexts.contextCount,
		contexts = contexts.contexts,
		pluginConnection = contexts.pluginConnection,
		protocol = {
			name = "codexRuntimeMirror",
			probeSent = contexts.pluginConnection and contexts.pluginConnection.connectionCount or 0,
			mirroredDataAvailable = false,
			message = mode == "fallback"
				and "Using local plugin fallback; separate server/client mirrors are unavailable in this Studio session."
				or "Plugin connections were probed; runtime mirror responders are reported separately when Studio exposes them.",
		},
		harness = V8.getHarnessStatus(),
	}
	State.runtimeMirrorStatus = result
	if updateRuntimeLabel then
		updateRuntimeLabel()
	end
	return result
end

function V8.toolSummary(container)
	local tools = {}
	if not container then
		return tools
	end
	for _, child in ipairs(container:GetChildren()) do
		if child:IsA("Tool") then
			table.insert(tools, {
				id = getInstanceId(child),
				name = child.Name,
				path = safeFullName(child),
				attributes = serializeAttributes(child),
			})
		end
	end
	return tools
end

function V8.getRuntimeActors(payload)
	payload = payload or {}
	local maxNpcs = math.max(0, math.min(tonumber(payload.maxNpcs) or 100, 500))
	local players = {}
	local playerCharacters = {}
	for _, player in ipairs(Players:GetPlayers()) do
		local characterSummary = summarizeCharacter(player)
		if player.Character then
			playerCharacters[player.Character] = true
		end
		table.insert(players, {
			userId = player.UserId,
			name = player.Name,
			displayName = player.DisplayName,
			team = player.Team and player.Team.Name or nil,
			attributes = serializeAttributes(player),
			backpackTools = V8.toolSummary(player:FindFirstChildOfClass("Backpack")),
			characterTools = V8.toolSummary(player.Character),
			character = characterSummary,
		})
	end

	local npcs = {}
	local scanned = 0
	for _, descendant in ipairs(workspace:GetDescendants()) do
		if #npcs >= maxNpcs then
			break
		end
		if descendant:IsA("Humanoid") then
			scanned += 1
			local model = descendant.Parent
			if model and model:IsA("Model") and not playerCharacters[model] then
				local root = model:FindFirstChild("HumanoidRootPart")
				table.insert(npcs, {
					id = getInstanceId(model),
					name = model.Name,
					path = safeFullName(model),
					health = descendant.Health,
					maxHealth = descendant.MaxHealth,
					state = serializeValue(descendant:GetState()),
					rootPosition = root and root:IsA("BasePart") and serializeValue(root.Position) or nil,
					attributes = serializeAttributes(model),
				})
			end
		end
	end

	local result = {
		at = isoNow(),
		contextType = V6.detectLocalContextType(),
		source = "localPlugin",
		players = players,
		playerCount = #players,
		npcs = npcs,
		npcCount = #npcs,
		npcScanCount = scanned,
		truncated = #npcs >= maxNpcs,
	}
	State.runtimeActors = result
	return result
end

function V8.vectorMin(a, b)
	return Vector3.new(math.min(a.X, b.X), math.min(a.Y, b.Y), math.min(a.Z, b.Z))
end

function V8.vectorMax(a, b)
	return Vector3.new(math.max(a.X, b.X), math.max(a.Y, b.Y), math.max(a.Z, b.Z))
end

function V8.getRuntimeWorldSummary(payload)
	payload = payload or {}
	local profile = V7.profileFromPayload(payload)
	local maxNodes = math.max(100, math.min(tonumber(payload.maxNodes) or 12000, 50000))
	local counts = {
		total = 0,
		baseParts = 0,
		anchoredParts = 0,
		unanchoredParts = 0,
		models = 0,
		folders = 0,
		spawnLocations = 0,
		luaSourceContainers = 0,
	}
	local classCounts = {}
	local spawnLocations = {}
	local majorFolders = {}
	local minBound = nil
	local maxBound = nil
	local truncated = false

	local function recordBounds(part)
		local half = part.Size / 2
		local low = part.Position - half
		local high = part.Position + half
		minBound = minBound and V8.vectorMin(minBound, low) or low
		maxBound = maxBound and V8.vectorMax(maxBound, high) or high
	end

	for _, descendant in ipairs(workspace:GetDescendants()) do
		if counts.total >= maxNodes then
			truncated = true
			break
		end
		counts.total += 1
		classCounts[descendant.ClassName] = (classCounts[descendant.ClassName] or 0) + 1
		if descendant:IsA("BasePart") then
			counts.baseParts += 1
			if descendant.Anchored then
				counts.anchoredParts += 1
			else
				counts.unanchoredParts += 1
			end
			recordBounds(descendant)
			if descendant:IsA("SpawnLocation") then
				counts.spawnLocations += 1
				if #spawnLocations < 50 then
					table.insert(spawnLocations, {
						id = getInstanceId(descendant),
						name = descendant.Name,
						path = safeFullName(descendant),
						position = serializeValue(descendant.Position),
					})
				end
			end
		elseif descendant:IsA("Model") then
			counts.models += 1
		elseif descendant:IsA("Folder") then
			counts.folders += 1
		elseif descendant:IsA("LuaSourceContainer") then
			counts.luaSourceContainers += 1
		end
	end

	for _, child in ipairs(workspace:GetChildren()) do
		if child:IsA("Folder") or child:IsA("Model") then
			table.insert(majorFolders, summarizeFolder(safeFullName(child)))
		end
	end

	local landmarks = {}
	for _, path in ipairs(V7.expected(profile, "workspace")) do
		table.insert(landmarks, summarizeFolder(path))
	end
	for _, name in ipairs(V7.detectList(profile, "workspaceNames")) do
		local path = "Workspace." .. tostring(name)
		if not resolvePath(path) then
			table.insert(landmarks, summarizeFolder(path))
		end
	end

	local result = {
		at = isoNow(),
		contextType = V6.detectLocalContextType(),
		source = "localPlugin",
		profile = V7.profileSummary(profile),
		counts = counts,
		classCounts = classCounts,
		bounds = minBound and maxBound and {
			min = serializeValue(minBound),
			max = serializeValue(maxBound),
			size = serializeValue(maxBound - minBound),
			center = serializeValue((maxBound + minBound) / 2),
		} or nil,
		terrain = {
			exists = workspace.Terrain ~= nil,
			path = workspace.Terrain and safeFullName(workspace.Terrain) or nil,
		},
		spawnLocations = spawnLocations,
		majorFolders = majorFolders,
		landmarks = landmarks,
		truncated = truncated,
	}
	State.runtimeWorldSummary = result
	return result
end

function V8.getRuntimeEvents(payload)
	payload = payload or {}
	local limit = math.max(1, math.min(tonumber(payload.limit) or 100, OUTPUT_LIMIT))
	local startIndex = math.max(1, #outputBuffer - limit + 1)
	local recentOutput = {}
	local harnessLogs = {}
	for index = startIndex, #outputBuffer do
		local entry = outputBuffer[index]
		table.insert(recentOutput, entry)
		local message = tostring(entry.message or "")
		if message:find("[CodexHarness]", 1, true) or message:find("[CodexScenario]", 1, true) then
			table.insert(harnessLogs, entry)
		end
	end
	local remoteInventory = getRemoteInventory({})
	local result = {
		at = isoNow(),
		contextType = V6.detectLocalContextType(),
		source = "localPlugin",
		recentOutput = recentOutput,
		outputCount = #recentOutput,
		errorSummary = getOutputErrors({ limit = limit }),
		harnessLogs = harnessLogs,
		harnessLogCount = #harnessLogs,
		players = {
			count = #Players:GetPlayers(),
		},
		remotes = {
			actualCount = remoteInventory.actualCount,
			expectedCount = remoteInventory.expectedCount,
			missingCount = remoteInventory.missingCount,
			mismatchedCount = remoteInventory.mismatchedCount,
		},
		harness = V8.getHarnessStatus(),
	}
	State.runtimeEvents = result
	return result
end

function V8.findScenario(profile, name)
	for _, scenario in ipairs(V7.array(profile.scenarios)) do
		if tostring(scenario.name or "") == tostring(name or "") then
			return scenario
		end
	end
	return nil
end

function V8.defaultScenarioChecks(profile, scenario)
	local name = tostring((scenario and scenario.name) or "")
	local checks = {}
	local function addRemote(remoteName)
		table.insert(checks, { type = "remote", name = remoteName, className = "RemoteEvent" })
	end
	local function addPath(path)
		table.insert(checks, { type = "path", path = path })
	end
	if name:find("combat", 1, true) then
		addRemote("CombatRequest")
		addRemote("CombatFX")
		addRemote("AbilityCooldown")
		addPath("ServerScriptService.Systems.CombatService")
	elseif name:find("extraction", 1, true) then
		addRemote("ExtractionTimer")
		addRemote("ExtractionFX")
		addPath("Workspace.ExtractionPad")
		addPath("Workspace.ExtractionZone")
	elseif name:find("loot", 1, true) then
		addRemote("LootOffer")
		addRemote("LootPick")
		addRemote("LootResult")
		addPath("Workspace.LootChests")
	elseif name:find("enemy", 1, true) then
		addPath("Workspace.EnemySpawns")
		addPath("Workspace.LiveEnemies")
		addPath("ServerScriptService.Systems.EnemyService")
	elseif name:find("vote", 1, true) then
		addRemote("StartVote")
		addRemote("CastVote")
		addRemote("VoteResult")
		addPath("ServerScriptService.Systems.VoteManager")
	else
		for _, path in ipairs(V7.expected(profile, "workspace")) do
			table.insert(checks, { type = "path", path = path })
			if #checks >= 5 then
				break
			end
		end
	end
	return checks
end

function V8.getScenarioRunPlan(payload)
	payload = payload or {}
	local profile = V7.profileFromPayload(payload)
	local scenarioName = tostring(payload.scenario or payload.name or "")
	local scenario = V8.findScenario(profile, scenarioName)
	if not scenario and scenarioName == "" then
		scenario = V7.array(profile.scenarios)[1]
		scenarioName = scenario and tostring(scenario.name or "") or ""
	end
	local checks = scenario and V7.array(scenario.checks) or {}
	if #checks == 0 then
		checks = V8.defaultScenarioChecks(profile, scenario or { name = scenarioName })
	end
	local result = {
		at = isoNow(),
		profile = V7.profileSummary(profile),
		scenario = scenario and {
			name = scenario.name,
			title = scenario.title,
			file = scenario.file,
			description = scenario.description,
		} or {
			name = scenarioName,
			title = scenarioName,
			missingFromProfile = true,
		},
		checks = checks,
		checkCount = #checks,
		requiresHarness = scenario and scenario.requiresHarness == true or false,
		harness = V8.getHarnessStatus(),
	}
	State.scenarioRunPlan = result
	return result
end

function V8.evaluateScenarioCheck(check)
	local checkType = tostring(check.type or "")
	if checkType == "path" then
		local instance = resolvePath(check.path)
		return {
			type = checkType,
			path = check.path,
			ok = instance ~= nil,
			className = instance and instance.ClassName or nil,
			message = instance and "Path exists." or "Path is missing.",
		}
	end
	if checkType == "remote" then
		local folder = V8.remoteFolder and V8.remoteFolder() or resolvePath("ReplicatedStorage.Remotes")
		local remote = folder and folder:FindFirstChild(tostring(check.name or ""))
		local expectedClass = tostring(check.className or "RemoteEvent")
		return {
			type = checkType,
			name = check.name,
			path = "ReplicatedStorage.Remotes." .. tostring(check.name or ""),
			ok = remote ~= nil and remote.ClassName == expectedClass,
			className = remote and remote.ClassName or nil,
			expectedClass = expectedClass,
			message = remote and (remote.ClassName == expectedClass and "Remote exists." or "Remote class mismatch.") or "Remote is missing.",
		}
	end
	if checkType == "outputPattern" then
		local pattern = tostring(check.pattern or "")
		local found = false
		for _, entry in ipairs(outputBuffer) do
			if tostring(entry.message or ""):find(pattern, 1, true) then
				found = true
				break
			end
		end
		return {
			type = checkType,
			pattern = pattern,
			ok = found,
			message = found and "Output pattern was found." or "Output pattern was not found.",
		}
	end
	return {
		type = checkType,
		ok = false,
		message = "Unsupported scenario check type.",
		check = check,
	}
end

function V8.runScenarioCheck(payload)
	payload = payload or {}
	local plan = V8.getScenarioRunPlan(payload)
	local results = {}
	local passed = 0
	local failed = 0
	for _, check in ipairs(plan.checks or {}) do
		local result = V8.evaluateScenarioCheck(check)
		table.insert(results, result)
		if result.ok then
			passed += 1
		else
			failed += 1
		end
	end
	local report = {
		at = isoNow(),
		profile = plan.profile,
		scenario = plan.scenario,
		contextType = V6.detectLocalContextType(),
		status = failed == 0 and "passed" or "failed",
		passed = passed,
		failed = failed,
		results = results,
		runtime = getRuntimeStatus({}),
		actors = V8.getRuntimeActors({ maxNpcs = 25 }),
		harness = V8.getHarnessStatus(),
	}
	State.scenarioRunReport = report
	if updateRuntimeLabel then
		updateRuntimeLabel()
	end
	return report
end

function V8.getScenarioRunReport(payload)
	if State.scenarioRunReport then
		return State.scenarioRunReport
	end
	return V8.runScenarioCheck(payload or {})
end

function V8.getTestWorkbenchReport(payload)
	payload = payload or {}
	local result = {
		at = isoNow(),
		profile = V7.profileSummary(V7.profileFromPayload(payload)),
		mirror = V8.getRuntimeMirrorStatus(payload),
		actors = V8.getRuntimeActors(payload.actors or {}),
		world = V8.getRuntimeWorldSummary(payload.world or payload),
		events = V8.getRuntimeEvents({ limit = payload.outputLimit or 100 }),
		project = {
			health = V7.getProjectHealthScore(payload),
			validation = V7.validateProject(payload),
			scenarios = V7.getProjectScenarioCatalog(payload),
		},
		scenarioRun = State.scenarioRunReport,
		harness = V8.getHarnessStatus(),
	}
	State.testWorkbenchReport = result
	if updateRuntimeLabel then
		updateRuntimeLabel()
	end
	return result
end

function V8.luaString(value)
	return tostring(value or ""):gsub("\\", "\\\\"):gsub("\"", "\\\""):gsub("\n", "\\n")
end

function V8.safeInstanceName(value)
	local text = tostring(value or "scenario")
	text = text:gsub("[%.%c/\\:<>|%?%*\"']", "_")
	if text == "" then
		text = "scenario"
	end
	return text
end

function V8.harnessBlueprint(profile)
	local profileId = tostring((profile and profile.id) or "universal")
	return {
		name = "Codex Test Harness",
		mode = "supervised",
		source = "installTestHarness",
		steps = {
			{ type = "ensureFolder", path = "ReplicatedStorage.CodexTestHarness" },
			{ type = "ensureFolder", path = "ServerScriptService.CodexTestHarness" },
			{ type = "ensureFolder", path = "Workspace.CodexTestHarness" },
			{ type = "ensureRemoteEvent", path = "ReplicatedStorage.CodexTestHarness.HarnessEvent" },
			{
				type = "writeScript",
				path = "ReplicatedStorage.CodexTestHarness.Manifest",
				className = "ModuleScript",
				source = "return { name = \"CodexTestHarness\", version = \"" .. VERSION .. "\", profile = \"" .. V8.luaString(profileId) .. "\" }\n",
			},
			{
				type = "writeScript",
				path = "ServerScriptService.CodexTestHarness.HarnessServer",
				className = "Script",
				source = "local ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal folder = ReplicatedStorage:WaitForChild(\"CodexTestHarness\")\nlocal event = folder:WaitForChild(\"HarnessEvent\")\nprint(\"[CodexHarness] server ready\")\nevent.OnServerEvent:Connect(function(player, marker)\n\tprint(\"[CodexHarness] event\", player and player.Name or \"unknown\", tostring(marker))\nend)\n",
			},
		},
	}
end

function V8.installTestHarness(payload)
	payload = payload or {}
	local profile = V7.profileFromPayload(payload)
	local blueprint = normalizeBlueprint(payload) or V8.harnessBlueprint(profile)
	local result = applyBuildPlan({ blueprint = blueprint })
	result.kind = "testHarnessInstall"
	result.profile = V7.profileSummary(profile)
	result.harness = V8.getHarnessStatus()
	return result
end

function V8.removeTestHarness(payload)
	payload = payload or {}
	local allowed = V8.harnessPaths()
	return withUndo("RemoveTestHarness", function()
		local result = {
			appliedAt = isoNow(),
			removed = {},
			missing = {},
			failed = {},
		}
		for _, path in ipairs(allowed) do
			local instance = resolvePath(path)
			if instance then
				local ok, err = pcall(function()
					instance:Destroy()
				end)
				if ok then
					table.insert(result.removed, { path = path })
				else
					table.insert(result.failed, { path = path, message = tostring(err) })
				end
			else
				table.insert(result.missing, { path = path })
			end
		end
		result.summary = {
			removed = #result.removed,
			missing = #result.missing,
			failed = #result.failed,
		}
		stateDirty = true
		result.harness = V8.getHarnessStatus()
		return result
	end)
end

function V8.scenarioHarnessBlueprint(payload)
	payload = payload or {}
	local profile = V7.profileFromPayload(payload)
	local scenarioName = V8.safeInstanceName(payload.scenario or payload.name or "scenario")
	return {
		name = "Codex Scenario Harness: " .. scenarioName,
		mode = "supervised",
		source = "applyScenarioHarness",
		steps = {
			{ type = "ensureFolder", path = "Workspace.CodexTestHarness" },
			{ type = "ensureFolder", path = "Workspace.CodexTestHarness.Scenarios" },
			{ type = "ensureFolder", path = "Workspace.CodexTestHarness.Scenarios." .. scenarioName },
			{
				type = "createPart",
				path = "Workspace.CodexTestHarness.Scenarios." .. scenarioName .. ".Marker",
				properties = {
					Anchored = true,
					CanCollide = false,
					Transparency = 0.35,
					Size = { __type = "Vector3", x = 6, y = 1, z = 6 },
					Position = { __type = "Vector3", x = 0, y = 2, z = 0 },
					Color = { __type = "Color3", mode = "rgb", r = 80, g = 200, b = 255 },
				},
			},
			{
				type = "writeScript",
				path = "Workspace.CodexTestHarness.Scenarios." .. scenarioName .. ".ScenarioManifest",
				className = "ModuleScript",
				source = "return { scenario = \"" .. V8.luaString(scenarioName) .. "\", profile = \"" .. V8.luaString(profile.id or "universal") .. "\", createdBy = \"Codex Studio Bridge " .. VERSION .. "\" }\n",
			},
		},
	}
end

function V8.applyScenarioHarness(payload)
	payload = payload or {}
	local profile = V7.profileFromPayload(payload)
	local blueprint = normalizeBlueprint(payload) or V8.scenarioHarnessBlueprint(payload)
	local result = applyBuildPlan({ blueprint = blueprint })
	result.kind = "scenarioHarness"
	result.profile = V7.profileSummary(profile)
	result.scenario = tostring(payload.scenario or payload.name or blueprint.name)
	result.harness = V8.getHarnessStatus()
	return result
end

function V9.memory(payload)
	payload = payload or {}
	if type(payload.memory) == "table" then
		return payload.memory
	end
	return {}
end

function V9.trimText(value, limit)
	local text = tostring(value or "")
	limit = tonumber(limit) or 120
	if #text > limit then
		return string.sub(text, 1, limit - 3) .. "..."
	end
	return text
end

function V9.bumpCount(counts, key)
	key = tostring(key or "unknown")
	counts[key] = (counts[key] or 0) + 1
end

function V9.sortedCounts(counts, limit)
	local rows = {}
	for name, count in pairs(counts or {}) do
		table.insert(rows, { name = tostring(name), count = count })
	end
	table.sort(rows, function(a, b)
		if a.count == b.count then
			return a.name < b.name
		end
		return a.count > b.count
	end)
	limit = math.max(1, tonumber(limit) or 20)
	while #rows > limit do
		table.remove(rows)
	end
	return rows
end

function V9.profileTable(profile, key)
	if type(profile) == "table" and type(profile[key]) == "table" then
		return profile[key]
	end
	return {}
end

function V9.memoryList(memory, key)
	local value = memory and memory[key]
	if type(value) == "table" then
		return value
	end
	return {}
end

function V9.focusText(payload)
	local memory = V9.memory(payload)
	return V9.trimText(memory.currentFocus or memory.focus or "", 160)
end

function V9.activeScriptSummary()
	local ok, service = pcall(function()
		return game:GetService("StudioService")
	end)
	if not ok or not service then
		return nil
	end
	local active = nil
	pcall(function()
		active = service.ActiveScript
	end)
	if not active then
		return nil
	end
	return {
		id = getInstanceId(active),
		name = active.Name,
		className = active.ClassName,
		path = safeFullName(active),
	}
end

function V9.cameraSummary()
	local camera = workspace.CurrentCamera
	if not camera then
		return nil
	end
	return {
		name = camera.Name,
		path = safeFullName(camera),
		cameraType = serializeValue(camera.CameraType),
		fieldOfView = camera.FieldOfView,
		cframe = serializeValue(camera.CFrame),
		position = serializeValue(camera.CFrame.Position),
		lookVector = serializeValue(camera.CFrame.LookVector),
	}
end

function V9.partBounds(part)
	local half = Vector3.new(part.Size.X / 2, part.Size.Y / 2, part.Size.Z / 2)
	return part.Position - half, part.Position + half
end

function V9.colorKey(color)
	local r = math.floor(color.R * 255 + 0.5)
	local g = math.floor(color.G * 255 + 0.5)
	local b = math.floor(color.B * 255 + 0.5)
	return tostring(r) .. "," .. tostring(g) .. "," .. tostring(b)
end

function V9.landmarkSummary(path)
	local instance = resolvePath(path)
	local summary = summarizeFolder(path)
	if not instance then
		return summary
	end
	if instance:IsA("BasePart") then
		summary.position = serializeValue(instance.Position)
		summary.size = serializeValue(instance.Size)
		summary.material = instance.Material.Name
		summary.color = serializeValue(instance.Color)
	elseif instance:IsA("Model") then
		local ok, cframe, size = pcall(function()
			return instance:GetBoundingBox()
		end)
		if ok then
			summary.boundingBox = {
				center = serializeValue(cframe.Position),
				size = serializeValue(size),
			}
		end
	end
	return summary
end

function V9.addLandmark(list, seen, path)
	path = tostring(path or "")
	if path == "" or seen[path] then
		return
	end
	seen[path] = true
	table.insert(list, V9.landmarkSummary(path))
end

function V9.getSceneMap(payload)
	payload = payload or {}
	local profile = V7.profileFromPayload(payload)
	local maxNodes = math.max(100, math.min(tonumber(payload.maxNodes) or 12000, 50000))
	local counts = {
		total = 0,
		baseParts = 0,
		anchoredParts = 0,
		unanchoredParts = 0,
		models = 0,
		folders = 0,
		spawnLocations = 0,
	}
	local materialCounts = {}
	local colorCounts = {}
	local classCounts = {}
	local majorParts = {}
	local rootChildren = {}
	local minBound = nil
	local maxBound = nil
	local truncated = false

	for _, child in ipairs(workspace:GetChildren()) do
		if child:IsA("Folder") or child:IsA("Model") or child:IsA("BasePart") then
			table.insert(rootChildren, {
				id = getInstanceId(child),
				name = child.Name,
				className = child.ClassName,
				path = safeFullName(child),
				childCount = #child:GetChildren(),
			})
		end
	end

	for _, descendant in ipairs(workspace:GetDescendants()) do
		if counts.total >= maxNodes then
			truncated = true
			break
		end
		counts.total += 1
		V9.bumpCount(classCounts, descendant.ClassName)
		if descendant:IsA("BasePart") then
			counts.baseParts += 1
			if descendant.Anchored then
				counts.anchoredParts += 1
			else
				counts.unanchoredParts += 1
			end
			local low, high = V9.partBounds(descendant)
			minBound = minBound and V8.vectorMin(minBound, low) or low
			maxBound = maxBound and V8.vectorMax(maxBound, high) or high
			V9.bumpCount(materialCounts, descendant.Material.Name)
			V9.bumpCount(colorCounts, V9.colorKey(descendant.Color))
			if descendant:IsA("SpawnLocation") then
				counts.spawnLocations += 1
			end
			if #majorParts < 100 then
				table.insert(majorParts, {
					id = getInstanceId(descendant),
					name = descendant.Name,
					className = descendant.ClassName,
					path = safeFullName(descendant),
					position = serializeValue(descendant.Position),
					size = serializeValue(descendant.Size),
					material = descendant.Material.Name,
					color = serializeValue(descendant.Color),
					volume = descendant.Size.X * descendant.Size.Y * descendant.Size.Z,
				})
			end
		elseif descendant:IsA("Model") then
			counts.models += 1
		elseif descendant:IsA("Folder") then
			counts.folders += 1
		end
	end

	table.sort(majorParts, function(a, b)
		return (a.volume or 0) > (b.volume or 0)
	end)
	while #majorParts > 25 do
		table.remove(majorParts)
	end

	local landmarks = {}
	local seenLandmarks = {}
	for _, path in ipairs(V7.array(V9.profileTable(profile, "visualLandmarks"))) do
		V9.addLandmark(landmarks, seenLandmarks, path)
	end
	for _, path in ipairs(V7.expected(profile, "workspace")) do
		V9.addLandmark(landmarks, seenLandmarks, V7.pathFromRule(path))
	end
	for _, name in ipairs(V7.detectList(profile, "workspaceNames")) do
		V9.addLandmark(landmarks, seenLandmarks, "Workspace." .. tostring(name))
	end

	local result = {
		at = isoNow(),
		version = VERSION,
		contextType = V6.detectLocalContextType(),
		profile = V7.profileSummary(profile),
		counts = counts,
		classCounts = V9.sortedCounts(classCounts, 30),
		materials = V9.sortedCounts(materialCounts, 20),
		colors = V9.sortedCounts(colorCounts, 20),
		rootChildren = rootChildren,
		majorParts = majorParts,
		landmarks = landmarks,
		bounds = minBound and maxBound and {
			min = serializeValue(minBound),
			max = serializeValue(maxBound),
			size = serializeValue(maxBound - minBound),
			center = serializeValue((maxBound + minBound) / 2),
		} or nil,
		camera = V9.cameraSummary(),
		selection = summarizeSelection(),
		activeScript = V9.activeScriptSummary(),
		truncated = truncated,
	}
	State.sceneMap = result
	return result
end

function V9.guiNode(instance, depth, maxDepth, state)
	state.count += 1
	V9.bumpCount(state.classCounts, instance.ClassName)
	local node = {
		id = getInstanceId(instance),
		name = instance.Name,
		className = instance.ClassName,
		path = safeFullName(instance),
		childCount = #instance:GetChildren(),
		properties = readCommonProperties(instance),
		children = {},
	}
	if instance:IsA("ScreenGui") then
		state.screenGuis += 1
	elseif instance:IsA("TextButton") or instance:IsA("ImageButton") then
		state.buttons += 1
	elseif instance:IsA("TextLabel") or instance:IsA("TextButton") or instance:IsA("TextBox") then
		state.textObjects += 1
		table.insert(state.textSamples, {
			path = safeFullName(instance),
			className = instance.ClassName,
			text = V9.trimText(instance.Text, 100),
		})
	elseif instance:IsA("GuiObject") then
		state.guiObjects += 1
	end
	if depth < maxDepth and state.count < state.maxNodes then
		for _, child in ipairs(instance:GetChildren()) do
			local childClass = child.ClassName
			if child:IsA("GuiBase") or child:IsA("GuiObject") or child:IsA("Folder") or string.sub(childClass, 1, 2) == "UI" then
				table.insert(node.children, V9.guiNode(child, depth + 1, maxDepth, state))
				if state.count >= state.maxNodes then
					state.truncated = true
					break
				end
			end
		end
	elseif #instance:GetChildren() > 0 then
		state.truncated = true
	end
	return node
end

function V9.getUiInventory(payload)
	payload = payload or {}
	local profile = V7.profileFromPayload(payload)
	local maxDepth = math.max(1, math.min(tonumber(payload.depth) or 10, 10))
	local state = {
		count = 0,
		maxNodes = math.max(50, math.min(tonumber(payload.maxNodes) or 3000, 5000)),
		truncated = false,
		screenGuis = 0,
		guiObjects = 0,
		buttons = 0,
		textObjects = 0,
		classCounts = {},
		textSamples = {},
	}
	local roots = {}
	local function addRoot(instance, source)
		if instance then
			table.insert(roots, {
				source = source,
				tree = V9.guiNode(instance, 0, maxDepth, state),
			})
		end
	end
	addRoot(game:GetService("StarterGui"), "StarterGui")
	for _, player in ipairs(Players:GetPlayers()) do
		addRoot(player:FindFirstChildOfClass("PlayerGui"), "PlayerGui:" .. player.Name)
	end
	while #state.textSamples > 40 do
		table.remove(state.textSamples)
	end

	local expectedRoots = {}
	local missingRoots = {}
	for _, path in ipairs(V7.expected(profile, "uiRoots")) do
		local rootPath = tostring(path)
		table.insert(expectedRoots, rootPath)
		if not resolvePath(rootPath) then
			table.insert(missingRoots, rootPath)
		end
	end
	for _, path in ipairs(V7.array(V9.profileTable(profile, "uiExpectations").roots)) do
		local rootPath = tostring(path)
		table.insert(expectedRoots, rootPath)
		if not resolvePath(rootPath) then
			table.insert(missingRoots, rootPath)
		end
	end

	local result = {
		at = isoNow(),
		contextType = V6.detectLocalContextType(),
		profile = V7.profileSummary(profile),
		roots = roots,
		stats = {
			nodes = state.count,
			screenGuis = state.screenGuis,
			guiObjects = state.guiObjects,
			buttons = state.buttons,
			textObjects = state.textObjects,
			classCounts = V9.sortedCounts(state.classCounts, 30),
			textSamples = state.textSamples,
			truncated = state.truncated,
		},
		expectations = V9.profileTable(profile, "uiExpectations"),
		expectedRoots = expectedRoots,
		missingExpectedRoots = missingRoots,
	}
	State.uiInventory = result
	return result
end

function V9.getAssetInventory(payload)
	payload = payload or {}
	local profile = V7.profileFromPayload(payload)
	local maxAssets = math.max(20, math.min(tonumber(payload.maxAssets) or 300, 2000))
	local roots = {
		game:GetService("Workspace"),
		game:GetService("ReplicatedStorage"),
		game:GetService("ServerStorage"),
		game:GetService("StarterGui"),
		game:GetService("StarterPack"),
		game:GetService("SoundService"),
		game:GetService("Lighting"),
	}
	local assetClasses = {
		Sound = true,
		Decal = true,
		Texture = true,
		MeshPart = true,
		SpecialMesh = true,
		Animation = true,
		Tool = true,
		ParticleEmitter = true,
		Beam = true,
		Trail = true,
		SurfaceAppearance = true,
		ImageLabel = true,
		ImageButton = true,
	}
	local assets = {}
	local classCounts = {}
	local truncated = false
	for _, root in ipairs(roots) do
		for _, descendant in ipairs(root:GetDescendants()) do
			if assetClasses[descendant.ClassName] then
				V9.bumpCount(classCounts, descendant.ClassName)
				if #assets < maxAssets then
					table.insert(assets, {
						id = getInstanceId(descendant),
						name = descendant.Name,
						className = descendant.ClassName,
						path = safeFullName(descendant),
						properties = readCommonProperties(descendant),
					})
				else
					truncated = true
				end
			end
		end
	end
	local result = {
		at = isoNow(),
		profile = V7.profileSummary(profile),
		categories = V9.profileTable(profile, "assetCategories"),
		assets = assets,
		count = #assets,
		classCounts = V9.sortedCounts(classCounts, 30),
		truncated = truncated,
	}
	State.assetInventory = result
	return result
end

function V9.getVisualSnapshot(payload)
	payload = payload or {}
	local result = {
		at = isoNow(),
		version = VERSION,
		contextType = V6.detectLocalContextType(),
		profile = V7.profileSummary(V7.profileFromPayload(payload)),
		scene = V9.getSceneMap(payload),
		ui = V9.getUiInventory(payload),
		assets = V9.getAssetInventory({ profile = V7.profileFromPayload(payload), maxAssets = 120 }),
		runtime = getRuntimeStatus({}),
		capture = {
			mode = "structuredFallback",
			message = "V9 returns structured scene and UI data. Raw screenshot capture is best-effort through approved harnesses only.",
		},
	}
	State.visualSnapshot = result
	if updateRuntimeLabel then
		updateRuntimeLabel()
	end
	return result
end

