function V9.getDesignAudit(payload)
	payload = payload or {}
	local scene = V9.getSceneMap(payload)
	local ui = V9.getUiInventory(payload)
	local assets = V9.getAssetInventory({ profile = V7.profileFromPayload(payload), maxAssets = 160 })
	local output = getOutputErrors({ limit = payload.outputLimit or 100 })
	local issues = {}
	local suggestions = {}
	if scene.counts.spawnLocations == 0 then
		table.insert(issues, { severity = "warning", code = "noSpawnLocation", message = "Workspace has no SpawnLocation." })
	end
	if ui.stats.screenGuis == 0 then
		table.insert(issues, { severity = "warning", code = "noScreenGui", message = "No ScreenGui was found in UI inventory." })
	end
	if #ui.missingExpectedRoots > 0 then
		table.insert(issues, { severity = "warning", code = "missingUiRoots", message = "Profile expected UI roots are missing.", paths = ui.missingExpectedRoots })
	end
	if assets.count == 0 then
		table.insert(issues, { severity = "info", code = "noAssets", message = "No reusable asset-like objects were detected." })
	end
	if output.count and output.count > 0 then
		table.insert(issues, { severity = "warning", code = "outputErrors", message = tostring(output.count) .. " recent Output errors/warnings were grouped." })
	end
	if scene.counts.baseParts < 10 then
		table.insert(suggestions, "Add a clearer playable world blockout with landmarks, spawn areas, and interaction zones.")
	end
	if ui.stats.buttons == 0 then
		table.insert(suggestions, "Add at least one visible HUD/menu button for repeated player workflows.")
	end
	local result = {
		at = isoNow(),
		profile = V7.profileSummary(V7.profileFromPayload(payload)),
		focus = V9.focusText(payload),
		issues = issues,
		issueCount = #issues,
		suggestions = suggestions,
		sceneSummary = {
			bounds = scene.bounds,
			counts = scene.counts,
			topMaterials = scene.materials,
		},
		uiSummary = ui.stats,
		assetSummary = {
			count = assets.count,
			classCounts = assets.classCounts,
		},
		outputSummary = output,
	}
	State.designAudit = result
	return result
end

function V9.intentSource(payload)
	local memory = V9.memory(payload)
	local focus = V9.focusText(payload)
	if focus ~= "" then
		return focus
	end
	local goals = V9.memoryList(memory, "goals")
	if #goals > 0 then
		local first = goals[#goals]
		if type(first) == "table" then
			return V9.trimText(first.text or first.goal or "", 160)
		end
		return V9.trimText(first, 160)
	end
	return "make the project easier for Codex and the creator to inspect, test, and continue building"
end

function V9.luaLiteral(value)
	return string.format("%q", tostring(value or ""))
end

function V9.autonomousBlueprint(payload, audit)
	payload = payload or {}
	audit = audit or V9.getDesignAudit(payload)
	local profile = V7.profileFromPayload(payload)
	local profileId = tostring(profile.id or "universal")
	local focus = V9.intentSource(payload)
	local steps = {
		{ type = "ensureFolder", path = "ReplicatedStorage.CodexBuilderBrain" },
		{
			type = "writeScript",
			path = "ReplicatedStorage.CodexBuilderBrain.ProjectIntent",
			className = "ModuleScript",
			source = "return {\n\tprofile = " .. V9.luaLiteral(profileId) .. ",\n\tfocus = " .. V9.luaLiteral(focus) .. ",\n\tcreatedBy = \"Codex Studio Bridge " .. VERSION .. "\"\n}\n",
		},
	}
	if audit.sceneSummary and audit.sceneSummary.counts and audit.sceneSummary.counts.spawnLocations == 0 then
		table.insert(steps, {
			type = "createSpawnLocation",
			path = "Workspace.CodexStarterSpawn",
			properties = {
				Anchored = true,
				Size = { __type = "Vector3", x = 8, y = 1, z = 8 },
				Position = { __type = "Vector3", x = 0, y = 4, z = 0 },
			},
		})
	end
	if audit.uiSummary and audit.uiSummary.screenGuis == 0 then
		table.insert(steps, { type = "ensureInstance", path = "StarterGui.CodexStarterHUD", className = "ScreenGui", properties = { ResetOnSpawn = false } })
		table.insert(steps, {
			type = "ensureInstance",
			path = "StarterGui.CodexStarterHUD.Status",
			className = "TextLabel",
			properties = {
				BackgroundTransparency = 0.35,
				BackgroundColor3 = { __type = "Color3", mode = "rgb", r = 20, g = 24, b = 32 },
				TextColor3 = { __type = "Color3", mode = "rgb", r = 235, g = 240, b = 255 },
				Text = "Codex starter HUD",
				TextScaled = true,
				Size = { __type = "UDim2", xScale = 0, xOffset = 260, yScale = 0, yOffset = 48 },
				Position = { __type = "UDim2", xScale = 0, xOffset = 20, yScale = 0, yOffset = 20 },
			},
		})
	end
	return {
		name = "Codex Autonomous Plan: " .. tostring(profile.name or profileId),
		mode = "supervised",
		source = "getAutonomousPlan",
		steps = steps,
	}
end

function V9.getAutonomousPlan(payload)
	payload = payload or {}
	local audit = V9.getDesignAudit(payload)
	local health = V7.getProjectHealthScore(payload)
	local blueprint = V9.autonomousBlueprint(payload, audit)
	local preview = previewBuildPlan({ blueprint = blueprint })
	local nextAction = "Review and apply the supervised autonomous comfort plan."
	if health.nextRecommendedFix and health.nextRecommendedFix ~= "" then
		nextAction = tostring(health.nextRecommendedFix)
	elseif #audit.suggestions > 0 then
		nextAction = audit.suggestions[1]
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		profile = V7.profileSummary(V7.profileFromPayload(payload)),
		focus = V9.intentSource(payload),
		projectScore = health.score,
		nextAction = nextAction,
		audit = audit,
		blueprint = blueprint,
		preview = preview,
		safety = {
			requiresStudioApproval = true,
			readCommandsMutate = false,
			protectedPaths = V9.memoryList(V9.memory(payload), "protectedPaths"),
		},
	}
	State.autonomousPlan = result
	if updateRuntimeLabel then
		updateRuntimeLabel()
	end
	return result
end

function V9.getBuildReadinessReport(payload)
	payload = payload or {}
	local brain = V9.getBuilderBrainStatus(payload)
	local visual = V9.getVisualSnapshot(payload)
	local audit = V9.getDesignAudit(payload)
	local score = tonumber(brain.projectScore) or 0
	if audit.issueCount > 0 then
		score = math.max(0, score - math.min(12, audit.issueCount * 3))
	end
	local result = {
		at = isoNow(),
		profile = brain.profile,
		score = V6.clampScore(score),
		category = score >= 85 and "ready" or (score >= 65 and "workable" or "needs-work"),
		brain = brain,
		visual = {
			sceneAt = visual.scene and visual.scene.at or nil,
			uiAt = visual.ui and visual.ui.at or nil,
			captureMode = visual.capture and visual.capture.mode or "structuredFallback",
		},
		audit = audit,
		lastBuildStatus = State.buildStatus and State.buildStatus.summary or nil,
		nextPlan = V9.getAutonomousPlan(payload),
	}
	State.buildReadinessReport = result
	return result
end

function V9.visualHarnessPaths()
	return {
		"ReplicatedStorage.CodexVisualHarness",
		"StarterGui.CodexVisualHarnessGui",
		"Workspace.CodexVisualHarness",
	}
end

function V9.getVisualHarnessStatus()
	local paths = {}
	local installedCount = 0
	for _, path in ipairs(V9.visualHarnessPaths()) do
		local instance = resolvePath(path)
		if instance then
			installedCount += 1
		end
		table.insert(paths, {
			path = path,
			exists = instance ~= nil,
			id = instance and getInstanceId(instance) or nil,
			className = instance and instance.ClassName or nil,
		})
	end
	return {
		at = isoNow(),
		installed = installedCount == #paths,
		partial = installedCount > 0 and installedCount < #paths,
		installedCount = installedCount,
		paths = paths,
	}
end

function V9.visualHarnessBlueprint(payload)
	payload = payload or {}
	local profile = V7.profileFromPayload(payload)
	return {
		name = "Codex Visual Harness",
		mode = "supervised",
		source = "installVisualHarness",
		steps = {
			{ type = "ensureFolder", path = "ReplicatedStorage.CodexVisualHarness" },
			{ type = "ensureRemoteEvent", path = "ReplicatedStorage.CodexVisualHarness.CaptureRequested" },
			{ type = "ensureFolder", path = "Workspace.CodexVisualHarness" },
			{ type = "ensureInstance", path = "StarterGui.CodexVisualHarnessGui", className = "ScreenGui", properties = { ResetOnSpawn = false, Enabled = true } },
			{
				type = "writeScript",
				path = "StarterGui.CodexVisualHarnessGui.VisualClient",
				className = "LocalScript",
				source = "local CaptureService = game:GetService(\"CaptureService\")\nprint(\"[CodexVisualHarness] client ready\")\nlocal ok = pcall(function()\n\tCaptureService:CaptureScreenshot(function(contentId)\n\t\tprint(\"[CodexVisualHarness] capture ready\", tostring(contentId))\n\tend)\nend)\nif not ok then\n\tprint(\"[CodexVisualHarness] capture unavailable; structured fallback remains active\")\nend\n",
			},
			{
				type = "writeScript",
				path = "ReplicatedStorage.CodexVisualHarness.Manifest",
				className = "ModuleScript",
				source = "return { name = \"CodexVisualHarness\", version = \"" .. VERSION .. "\", profile = \"" .. V8.luaString(profile.id or "universal") .. "\" }\n",
			},
		},
	}
end

function V9.installVisualHarness(payload)
	local blueprint = normalizeBlueprint(payload or {}) or V9.visualHarnessBlueprint(payload or {})
	local result = applyBuildPlan({ blueprint = blueprint })
	result.kind = "visualHarnessInstall"
	result.harness = V9.getVisualHarnessStatus()
	return result
end

function V9.removeVisualHarness(payload)
	return withUndo("RemoveVisualHarness", function()
		local result = { appliedAt = isoNow(), removed = {}, missing = {}, failed = {} }
		for _, path in ipairs(V9.visualHarnessPaths()) do
			local instance = resolvePath(path)
			if instance then
				local ok, err = pcall(function()
					instance:Destroy()
				end)
				if ok then
					table.insert(result.removed, { path = path })
				else
					table.insert(result.failed, { path = path, message = tostring(err) })
				end
			else
				table.insert(result.missing, { path = path })
			end
		end
		result.summary = { removed = #result.removed, missing = #result.missing, failed = #result.failed }
		stateDirty = true
		result.harness = V9.getVisualHarnessStatus()
		return result
	end)
end

function V9.applyAutonomousPlan(payload)
	local blueprint = normalizeBlueprint(payload or {}) or V9.autonomousBlueprint(payload or {})
	local result = applyBuildPlan({ blueprint = blueprint })
	result.kind = "autonomousPlan"
	return result
end

