function V10.profile(payload)
	return V7.profileFromPayload(payload or {})
end

function V10.profileId(profile)
	return tostring((profile and profile.id) or "universal")
end

function V10.addIssue(issues, code, message, severity, recommendation)
	table.insert(issues, {
		code = code,
		message = message,
		severity = severity or "warning",
		recommendation = recommendation or "",
	})
end

function V10.pathExists(path)
	return type(path) == "string" and path ~= "" and resolvePath(path) ~= nil
end

function V10.uiRootPath(profile)
	local forge = V9.profileTable(profile, "uiForge")
	if type(forge.root) == "string" and forge.root ~= "" then
		return forge.root
	end
	local roots = V7.array(forge.roots)
	if #roots > 0 then
		return tostring(roots[1])
	end
	return "StarterGui.CodexDirectorHUD"
end

function V10.uiBuildRootPath(profile)
	local forge = V9.profileTable(profile, "uiForge")
	if type(forge.buildRoot) == "string" and forge.buildRoot ~= "" then
		return forge.buildRoot
	end
	local root = V10.uiRootPath(profile)
	local existing = resolvePath(root)
	if existing and not existing:IsA("ScreenGui") then
		return root .. ".CodexDirectorHUD"
	end
	return root
end

function V10.profileStrings(value)
	local result = {}
	for _, item in ipairs(V7.array(value)) do
		table.insert(result, tostring(item))
	end
	return result
end

function V10.styleNotes(memory)
	local notes = {}
	for _, entry in ipairs(V9.memoryList(memory, "styleNotes")) do
		if type(entry) == "table" then
			table.insert(notes, V9.trimText(entry.text or entry.note or "", 180))
		else
			table.insert(notes, V9.trimText(entry, 180))
		end
	end
	for _, entry in ipairs(V9.memoryList(memory, "stylePreferences")) do
		if type(entry) == "table" then
			table.insert(notes, V9.trimText(entry.text or entry.preference or "", 180))
		else
			table.insert(notes, V9.trimText(entry, 180))
		end
	end
	return notes
end

