function V10.previewForBlueprint(blueprint)
	local ok, result = pcall(function()
		return previewBuildPlan({ blueprint = blueprint })
	end)
	if ok then
		return result
	end
	return {
		valid = false,
		errors = { tostring(result) },
	}
end

function V10.findRemoteByName(name)
	local remotes = resolvePath("ReplicatedStorage.Remotes")
	if not remotes then
		return nil
	end
	for _, descendant in ipairs(remotes:GetDescendants()) do
		if (descendant:IsA("RemoteEvent") or descendant:IsA("RemoteFunction")) and descendant.Name == name then
			return descendant
		end
	end
	return nil
end

function V10.hasUiText(ui, text)
	text = string.lower(tostring(text or ""))
	if text == "" then
		return false
	end
	local important = {}
	for token in string.gmatch(text, "[%w_]+") do
		local word = string.lower(token)
		if word ~= "text" and word ~= "status" and word ~= "feedback" and word ~= "prompt"
			and word ~= "controls" and word ~= "friendly" and word ~= "ui" and word ~= "hud" then
			table.insert(important, word)
		end
	end
	if #important == 0 then
		table.insert(important, text)
	end
	local stats = ui and ui.stats or {}
	for _, sample in ipairs(stats.textSamples or {}) do
		local sampleText = string.lower(tostring(sample.text or "") .. " " .. tostring(sample.name or "") .. " " .. tostring(sample.path or ""))
		for _, word in ipairs(important) do
			if sampleText:find(word, 1, true) then
				return true
			end
		end
	end
	return false
end

function V10.getUiForgeAudit(payload)
	payload = payload or {}
	local profile = V10.profile(payload)
	local ui = V9.getUiInventory(payload)
	local forge = V9.profileTable(profile, "uiForge")
	local expected = V9.profileTable(profile, "uiExpectations")
	local issues = {}
	local rootPath = V10.uiRootPath(profile)
	if not V10.pathExists(rootPath) then
		V10.addIssue(issues, "missingDirectorHud", "Profile-owned UI root is missing: " .. rootPath, "warning", "Preview and approve a UI Forge plan.")
	end
	if (ui.stats and ui.stats.screenGuis or 0) == 0 then
		V10.addIssue(issues, "noScreenGui", "No ScreenGui was found in StarterGui or PlayerGui.", "blocker", "Create a basic HUD/menu root.")
	end
	if (ui.stats and ui.stats.buttons or 0) == 0 then
		V10.addIssue(issues, "noButtons", "No player-facing UI buttons were found.", "warning", "Add at least one clear action/menu button.")
	end

	local required = V7.array(forge.required)
	if #required == 0 then
		required = V7.array(expected.patterns)
	end
	local missingPatterns = {}
	for _, requirement in ipairs(required) do
		local text = tostring(requirement)
		local lower = string.lower(text)
		local found = V10.hasUiText(ui, lower)
		if lower:find("hud", 1, true) and ((ui.stats and ui.stats.screenGuis or 0) > 0) then
			found = true
		end
		if not found then
			table.insert(missingPatterns, text)
		end
	end
	if #missingPatterns > 0 then
		V10.addIssue(issues, "missingUiPatterns", "Missing UI expectations: " .. table.concat(missingPatterns, ", "), "warning", "Use UI Forge to add a compact profile HUD.")
	end

	local result = {
		at = isoNow(),
		version = VERSION,
		profile = V7.profileSummary(profile),
		rootPath = rootPath,
		stats = ui.stats,
		expected = expected,
		uiForge = forge,
		missingPatterns = missingPatterns,
		issues = issues,
		issueCount = #issues,
		ready = #issues == 0,
	}
	State.uiForgeAudit = result
	return result
end

function V10.uiForgeBlueprint(payload, audit)
	payload = payload or {}
	local profile = V10.profile(payload)
	audit = audit or V10.getUiForgeAudit(payload)
	local root = V10.uiBuildRootPath(profile)
	local profileId = V10.profileId(profile)
	local title = tostring((profile and profile.name) or "Codex Director")
	local focus = V9.intentSource(payload)
	local accent = { __type = "Color3", mode = "rgb", r = 52, g = 112, b = 255 }
	local bg = { __type = "Color3", mode = "rgb", r = 13, g = 18, b = 24 }
	local fg = { __type = "Color3", mode = "rgb", r = 239, g = 244, b = 255 }
	local steps = {
		{ type = "ensureInstance", path = root, className = "ScreenGui", properties = { ResetOnSpawn = false, Enabled = true } },
		{
			type = "ensureInstance",
			path = root .. ".StatusPanel",
			className = "Frame",
			properties = {
				BackgroundColor3 = bg,
				BackgroundTransparency = 0.18,
				Size = { __type = "UDim2", xScale = 0, xOffset = 330, yScale = 0, yOffset = 118 },
				Position = { __type = "UDim2", xScale = 0, xOffset = 18, yScale = 0, yOffset = 18 },
			},
		},
		{
			type = "ensureInstance",
			path = root .. ".StatusPanel.Title",
			className = "TextLabel",
			properties = {
				BackgroundTransparency = 1,
				TextColor3 = fg,
				Text = title,
				TextScaled = true,
				TextXAlignment = "Left",
				Size = { __type = "UDim2", xScale = 1, xOffset = -24, yScale = 0, yOffset = 30 },
				Position = { __type = "UDim2", xScale = 0, xOffset = 12, yScale = 0, yOffset = 8 },
			},
		},
		{
			type = "ensureInstance",
			path = root .. ".StatusPanel.Objective",
			className = "TextLabel",
			properties = {
				BackgroundTransparency = 1,
				TextColor3 = { __type = "Color3", mode = "rgb", r = 208, g = 220, b = 236 },
				Text = "Objective: " .. V9.trimText(focus, 80),
				TextScaled = true,
				TextWrapped = true,
				TextXAlignment = "Left",
				Size = { __type = "UDim2", xScale = 1, xOffset = -24, yScale = 0, yOffset = 42 },
				Position = { __type = "UDim2", xScale = 0, xOffset = 12, yScale = 0, yOffset = 42 },
			},
		},
		{
			type = "ensureInstance",
			path = root .. ".ActionButton",
			className = "TextButton",
			properties = {
				BackgroundColor3 = accent,
				TextColor3 = fg,
				Text = "Ready",
				TextScaled = true,
				Size = { __type = "UDim2", xScale = 0, xOffset = 148, yScale = 0, yOffset = 44 },
				Position = { __type = "UDim2", xScale = 1, xOffset = -168, yScale = 1, yOffset = -64 },
			},
		},
		{
			type = "writeScript",
			path = root .. ".DirectorUiManifest",
			className = "ModuleScript",
			source = "return {\n\tname = \"CodexDirectorHUD\",\n\tprofile = " .. V9.luaLiteral(profileId) .. ",\n\tversion = " .. V9.luaLiteral(VERSION) .. ",\n\tpurpose = \"Supervised UI Forge output\"\n}\n",
			overwrite = false,
		},
	}
	return {
		name = "Codex UI Forge: " .. title,
		mode = "supervised",
		source = "getUiForgePlan",
		steps = steps,
	}
end

