function V10.loopPiece(name, ready, evidence, recommendation)
	return {
		name = name,
		ready = ready == true,
		evidence = evidence or "",
		recommendation = recommendation or "",
	}
end

function V10.getGameLoopReport(payload)
	payload = payload or {}
	local profile = V10.profile(payload)
	local scene = V9.getSceneMap(payload)
	local ui = State.uiForgeAudit or V10.getUiForgeAudit(payload)
	local loop = V9.profileTable(profile, "gameLoop")
	local remotes = {}
	local missing = {}
	for _, remoteName in ipairs(V7.array(loop.remotes)) do
		local remote = V10.findRemoteByName(tostring(remoteName))
		if remote then
			table.insert(remotes, { name = remote.Name, path = safeFullName(remote), className = remote.ClassName })
		else
			table.insert(missing, tostring(remoteName))
		end
	end
	local counts = scene.counts or {}
	local pieces = {
		V10.loopPiece("lobby", V10.pathExists(loop.lobbyPath or "Workspace.Lobby") or (counts.spawnLocations or 0) > 0, "spawn locations: " .. tostring(counts.spawnLocations or 0), "Create a clear lobby/spawn state."),
		V10.loopPiece("spawn", (counts.spawnLocations or 0) > 0, "spawn locations: " .. tostring(counts.spawnLocations or 0), "Create at least one SpawnLocation."),
		V10.loopPiece("start", #remotes > 0 or V10.findRemoteByName("MatchStart") ~= nil or V10.findRemoteByName("StartGame") ~= nil, "loop remotes found: " .. tostring(#remotes), "Create a start/match remote or setup object."),
		V10.loopPiece("objective", V10.hasUiText({ stats = ui.stats }, "objective") or V10.pathExists(loop.objectivePath or ""), "UI/objective path checked", "Expose the current objective to players."),
		V10.loopPiece("failWin", V10.findRemoteByName("MatchEnd") ~= nil or V10.findRemoteByName("RoundEnded") ~= nil, "end-state remotes checked", "Add win/fail feedback hooks."),
		V10.loopPiece("reward", V10.findRemoteByName("RewardGranted") ~= nil or V10.pathExists(loop.rewardPath or ""), "reward hooks checked", "Add reward feedback for completing the loop."),
		V10.loopPiece("replay", V10.findRemoteByName("ReplayRequested") ~= nil or V10.findRemoteByName("PlayAgain") ~= nil, "replay hooks checked", "Add a clear replay/return-to-lobby path."),
		V10.loopPiece("playerFeedback", (ui.stats and (ui.stats.textObjects or 0) or 0) > 0, "text UI objects: " .. tostring(ui.stats and ui.stats.textObjects or 0), "Add visible feedback for state changes."),
	}
	local missingPieces = {}
	for _, piece in ipairs(pieces) do
		if not piece.ready then
			table.insert(missingPieces, piece.name)
		end
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		profile = V7.profileSummary(profile),
		pieces = pieces,
		missingPieces = missingPieces,
		missingRemotes = missing,
		remoteEvidence = remotes,
		sceneSummary = {
			spawnLocations = counts.spawnLocations or 0,
			baseParts = counts.baseParts or 0,
			majorRootChildren = scene.rootChildren,
		},
		ready = #missingPieces == 0,
	}
	State.gameLoopReport = result
	return result
end

function V10.gameLoopBlueprint(payload, report)
	payload = payload or {}
	local profile = V10.profile(payload)
	report = report or V10.getGameLoopReport(payload)
	local profileId = V10.profileId(profile)
	local steps = {
		{ type = "ensureFolder", path = "ReplicatedStorage.CodexGameLoop" },
		{ type = "ensureRemoteEvent", path = "ReplicatedStorage.CodexGameLoop.LoopStateChanged" },
		{ type = "ensureRemoteEvent", path = "ReplicatedStorage.CodexGameLoop.ObjectiveChanged" },
		{ type = "ensureRemoteEvent", path = "ReplicatedStorage.CodexGameLoop.RewardGranted" },
		{ type = "ensureFolder", path = "Workspace.CodexGameLoop" },
		{
			type = "writeScript",
			path = "ReplicatedStorage.CodexGameLoop.LoopManifest",
			className = "ModuleScript",
			source = "return {\n\tprofile = " .. V9.luaLiteral(profileId) .. ",\n\tversion = " .. V9.luaLiteral(VERSION) .. ",\n\tmissingPieces = " .. V9.luaLiteral(table.concat(report.missingPieces or {}, ",")) .. "\n}\n",
			overwrite = false,
		},
	}
	if (report.sceneSummary and report.sceneSummary.spawnLocations or 0) == 0 then
		table.insert(steps, {
			type = "createSpawnLocation",
			path = "Workspace.CodexGameLoop.PlayerSpawn",
			properties = {
				Anchored = true,
				Size = { __type = "Vector3", x = 10, y = 1, z = 10 },
				Position = { __type = "Vector3", x = 0, y = 5, z = 0 },
			},
		})
	end
	return {
		name = "Codex Game Loop Director: " .. tostring((profile and profile.name) or profileId),
		mode = "supervised",
		source = "getGameLoopPlan",
		steps = steps,
	}
end

