function V10.hasAssetClass(inventory, className)
	for _, row in ipairs(inventory.classCounts or {}) do
		if row.name == className and (row.count or 0) > 0 then
			return true
		end
	end
	return false
end

function V10.getAssetStyleReport(payload)
	payload = payload or {}
	local profile = V10.profile(payload)
	local inventory = V9.getAssetInventory(payload)
	local needs = V7.array(profile.assetNeeds)
	local missing = {}
	for _, need in ipairs(needs) do
		if type(need) == "table" then
			local classes = V7.array(need.classes)
			local found = false
			for _, className in ipairs(classes) do
				if V10.hasAssetClass(inventory, tostring(className)) then
					found = true
					break
				end
			end
			if not found then
				table.insert(missing, {
					category = tostring(need.category or need.name or "asset"),
					classes = classes,
					purpose = tostring(need.purpose or ""),
				})
			end
		else
			table.insert(missing, { category = tostring(need), classes = {}, purpose = "" })
		end
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		profile = V7.profileSummary(profile),
		styleGuide = V10.getStyleGuide(payload),
		inventory = {
			count = inventory.count,
			classCounts = inventory.classCounts,
			categories = inventory.categories,
			truncated = inventory.truncated,
		},
		missingNeeds = missing,
		ready = #missing == 0,
	}
	State.assetStyleReport = result
	return result
end

function V10.styleAssetBlueprint(payload, report)
	payload = payload or {}
	local profile = V10.profile(payload)
	report = report or V10.getAssetStyleReport(payload)
	local profileId = V10.profileId(profile)
	local steps = {
		{ type = "ensureFolder", path = "ReplicatedStorage.CodexAssetDirection" },
		{ type = "ensureFolder", path = "ReplicatedStorage.Assets" },
		{
			type = "writeScript",
			path = "ReplicatedStorage.CodexAssetDirection.StyleManifest",
			className = "ModuleScript",
			source = "return {\n\tprofile = " .. V9.luaLiteral(profileId) .. ",\n\tversion = " .. V9.luaLiteral(VERSION) .. ",\n\tstyle = " .. V9.luaLiteral((report.styleGuide and report.styleGuide.guide and report.styleGuide.guide.tone) or "") .. "\n}\n",
			overwrite = false,
		},
	}
	local categories = V9.profileTable(profile, "assetCategories")
	for categoryName in pairs(categories) do
		table.insert(steps, { type = "ensureFolder", path = "ReplicatedStorage.Assets." .. tostring(categoryName) })
	end
	for _, missing in ipairs(report.missingNeeds or {}) do
		table.insert(steps, { type = "ensureFolder", path = "ReplicatedStorage.Assets." .. tostring(missing.category) })
	end
	return {
		name = "Codex Style and Asset Direction: " .. tostring((profile and profile.name) or profileId),
		mode = "supervised",
		source = "getAssetStyleReport",
		steps = steps,
	}
end

function V10.getVisualReview(payload)
	payload = payload or {}
	local scene = V9.getSceneMap(payload)
	local ui = V9.getUiInventory(payload)
	local assets = V9.getAssetInventory({ profile = V10.profile(payload), maxAssets = 160 })
	local audit = V9.getDesignAudit(payload)
	local output = getOutputErrors({ limit = 50 })
	local result = {
		at = isoNow(),
		version = VERSION,
		profile = V7.profileSummary(V10.profile(payload)),
		scene = scene,
		ui = ui,
		assets = assets,
		designAudit = audit,
		outputErrors = output,
		cameraBookmarks = V10.getCameraBookmarks(payload),
		styleGuide = V10.getStyleGuide(payload),
		summary = {
			parts = scene.counts and scene.counts.baseParts or 0,
			spawnLocations = scene.counts and scene.counts.spawnLocations or 0,
			screenGuis = ui.stats and ui.stats.screenGuis or 0,
			buttons = ui.stats and ui.stats.buttons or 0,
			assets = assets.count or 0,
			outputErrorGroups = output.summary and output.summary.errorGroups or #(output.groups or {}),
		},
	}
	State.visualReview = result
	if updateRuntimeLabel then
		updateRuntimeLabel()
	end
	return result
end

function V10.getDirectorReport(payload)
	payload = payload or {}
	local review = V10.getVisualReview(payload)
	local uiDirector = V11.getUiDirectorReport(payload)
	local loopReport = V10.getGameLoopReport(payload)
	local assetReport = V10.getAssetStyleReport(payload)
	local nextAction = uiDirector.nextAction or "Continue polishing the playable loop."
	if uiDirector.issueCount and uiDirector.issueCount > 0 then
		nextAction = uiDirector.nextAction
	elseif loopReport.missingPieces and #loopReport.missingPieces > 0 then
		nextAction = "Create the missing game-loop scaffolding: " .. table.concat(loopReport.missingPieces, ", ")
	elseif assetReport.missingNeeds and #assetReport.missingNeeds > 0 then
		nextAction = "Organize asset/style direction folders for missing feedback assets."
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		profile = review.profile,
		whatISee = {
			scene = review.summary,
			camera = review.scene and review.scene.camera or nil,
			selection = review.scene and review.scene.selection or nil,
		},
		missing = {
			uiIssues = {
				missingScreens = uiDirector.missingScreens,
				missingActions = uiDirector.missingActions,
				missingFlowStates = uiDirector.missingFlowStates,
				responsiveIssueCount = uiDirector.responsiveIssueCount,
			},
			gameLoop = loopReport.missingPieces,
			assetNeeds = assetReport.missingNeeds,
		},
		uiDirector = {
			richUi = uiDirector.richUi,
			summary = uiDirector.summary,
			nextAction = uiDirector.nextAction,
			issueCount = uiDirector.issueCount,
		},
		nextAction = nextAction,
	}
	State.directorReport = result
	if updateRuntimeLabel then
		updateRuntimeLabel()
	end
	return result
end

function V10.getStyleAssetPlan(payload)
	local report = V10.getAssetStyleReport(payload or {})
	local blueprint = normalizeBlueprint(payload or {}) or V10.styleAssetBlueprint(payload or {}, report)
	return {
		at = isoNow(),
		version = VERSION,
		profile = report.profile,
		report = report,
		blueprint = blueprint,
		preview = V10.previewForBlueprint(blueprint),
	}
end

function V10.getDirectorRoundPlan(payload)
	payload = payload or {}
	local profile = V10.profile(payload)
	local priorities = V7.array(profile.directorPriorities)
	if #priorities == 0 then
		priorities = { "ui", "loop", "assets", "autonomous" }
	end
	local uiPlan = V11.getUiPolishPlan(payload)
	local loopPlan = V10.getGameLoopPlan(payload)
	local assetPlan = V10.getStyleAssetPlan(payload)
	local selected = nil
	local reason = ""
	for _, priority in ipairs(priorities) do
		local key = tostring(priority)
		if key == "ui" and uiPlan.report and (uiPlan.report.issueCount or 0) > 0 then
			selected = { kind = "uiPolish", command = "applyUiPolishPlan", blueprint = uiPlan.blueprint, preview = uiPlan.preview }
			reason = "UI Director recommends targeted polish: " .. tostring(uiPlan.report.nextAction or "polish existing UI")
			break
		elseif key == "loop" and loopPlan.report and #(loopPlan.report.missingPieces or {}) > 0 then
			selected = { kind = "gameLoop", command = "applyGameLoopPlan", blueprint = loopPlan.blueprint, preview = loopPlan.preview }
			reason = "Game loop is missing: " .. table.concat(loopPlan.report.missingPieces or {}, ", ")
			break
		elseif key == "assets" and assetPlan.report and #(assetPlan.report.missingNeeds or {}) > 0 then
			selected = { kind = "styleAssets", command = "applyStyleAssetPlan", blueprint = assetPlan.blueprint, preview = assetPlan.preview }
			reason = "Asset direction has missing categories."
			break
		end
	end
	if not selected then
		local auto = V9.getAutonomousPlan(payload)
		selected = { kind = "autonomous", command = "applyDirectorRound", blueprint = auto.blueprint, preview = auto.preview }
		reason = "No blocker found, so continue with the general autonomous builder plan."
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		profile = V7.profileSummary(profile),
		selected = selected,
		blueprint = selected.blueprint,
		preview = selected.preview,
		reason = reason,
		inputs = {
			ui = {
				issueCount = uiPlan.report and uiPlan.report.issueCount or 0,
				richUi = uiPlan.report and uiPlan.report.richUi or false,
				missingFlowStates = uiPlan.report and uiPlan.report.missingFlowStates or {},
				missingActions = uiPlan.report and uiPlan.report.missingActions or {},
			},
			loop = { missingPieces = loopPlan.report and loopPlan.report.missingPieces or {} },
			assets = { missingNeeds = assetPlan.report and assetPlan.report.missingNeeds or {} },
		},
	}
	State.directorRoundPlan = result
	if updateRuntimeLabel then
		updateRuntimeLabel()
	end
	return result
end

function V10.applyBlueprintCommand(payload, fallbackBlueprint, kind)
	local blueprint = normalizeBlueprint(payload or {}) or fallbackBlueprint
	local result = applyBuildPlan({ blueprint = blueprint })
	result.kind = kind
