function V11.payloadWithDeepUiDefaults(payload)
	local options = {}
	for key, value in pairs(payload or {}) do
		options[key] = value
	end
	options.depth = tonumber(options.depth) or 10
	options.maxNodes = tonumber(options.maxNodes) or 3000
	return options
end

function V11.getDeepUiInventory(payload)
	local result = V9.getUiInventory(V11.payloadWithDeepUiDefaults(payload))
	result.kind = "deepUiInventory"
	State.deepUiInventory = result
	return result
end

function V11.walkUiNode(node, depth, callback)
	if type(node) ~= "table" then
		return
	end
	callback(node, depth or 0)
	for _, child in ipairs(node.children or {}) do
		V11.walkUiNode(child, (depth or 0) + 1, callback)
	end
end

function V11.nodeText(node)
	local properties = node and node.properties or {}
	return tostring(properties.Text or "")
end

function V11.searchText(node)
	return string.lower(tostring(node.name or "") .. " " .. tostring(node.path or "") .. " " .. V11.nodeText(node))
end

function V11.isTextClass(className)
	return className == "TextLabel" or className == "TextButton" or className == "TextBox"
end

function V11.isButtonClass(className)
	return className == "TextButton" or className == "ImageButton"
end

function V11.bump(map, key)
	key = tostring(key or "unknown")
	map[key] = (map[key] or 0) + 1
end

function V11.addLimited(list, value, limit)
	limit = tonumber(limit) or 80
	if #list < limit then
		table.insert(list, value)
	end
end

function V11.udim2Summary(value)
	if type(value) ~= "table" or value.__type ~= "UDim2" then
		return nil
	end
	return {
		xScale = tonumber(value.xScale) or 0,
		xOffset = tonumber(value.xOffset) or 0,
		yScale = tonumber(value.yScale) or 0,
		yOffset = tonumber(value.yOffset) or 0,
	}
end

function V11.collectScreen(screenNode)
	local screen = {
		id = screenNode.id,
		name = screenNode.name,
		path = screenNode.path,
		className = screenNode.className,
		childCount = screenNode.childCount,
		rootPanels = {},
		counts = {
			nodes = 0,
			buttons = 0,
			textObjects = 0,
			emptyText = 0,
			maxDepth = 0,
		},
		classCounts = {},
		buttons = {},
		labels = {},
		emptyTextPlaceholders = {},
		hasSafeArea = false,
		hasUiScale = false,
	}
	for _, child in ipairs(screenNode.children or {}) do
		table.insert(screen.rootPanels, {
			name = child.name,
			path = child.path,
			className = child.className,
			visible = child.properties and child.properties.Visible ~= false or true,
			childCount = child.childCount,
		})
	end
	V11.walkUiNode(screenNode, 0, function(node, depth)
		screen.counts.nodes += 1
		screen.counts.maxDepth = math.max(screen.counts.maxDepth, depth)
		V11.bump(screen.classCounts, node.className)
		local lower = V11.searchText(node)
		if lower:find("safearea", 1, true) then
			screen.hasSafeArea = true
		end
		if node.className == "UIScale" then
			screen.hasUiScale = true
		end
		if V11.isButtonClass(node.className) then
			screen.counts.buttons += 1
			V11.addLimited(screen.buttons, {
				name = node.name,
				path = node.path,
				className = node.className,
				text = V11.nodeText(node),
			}, 40)
		end
		if V11.isTextClass(node.className) then
			local text = V11.nodeText(node)
			screen.counts.textObjects += 1
			if text == "" then
				screen.counts.emptyText += 1
				V11.addLimited(screen.emptyTextPlaceholders, {
					name = node.name,
					path = node.path,
					className = node.className,
				}, 30)
			else
				V11.addLimited(screen.labels, {
					name = node.name,
					path = node.path,
					text = V9.trimText(text, 120),
				}, 60)
			end
		end
	end)
	return screen
end

function V11.getUiScreenMap(payload)
	payload = payload or {}
	local profile = V10.profile(payload)
	local inventory = V11.getDeepUiInventory(payload)
	local screens = {}
	local screenNames = {}
	for _, root in ipairs(inventory.roots or {}) do
		V11.walkUiNode(root.tree, 0, function(node)
			if node.className == "ScreenGui" then
				local screen = V11.collectScreen(node)
				table.insert(screens, screen)
				screenNames[string.lower(screen.name or "")] = true
				screenNames[string.lower(screen.path or "")] = true
			end
		end)
	end
	local expectedScreens = V7.array(profile.uiScreens)
	local missingScreens = {}
	for _, expected in ipairs(expectedScreens) do
		local expectedText = string.lower(tostring(expected))
		local found = false
		for _, screen in ipairs(screens) do
			local haystack = string.lower(tostring(screen.name or "") .. " " .. tostring(screen.path or ""))
			if haystack:find(expectedText, 1, true) then
				found = true
				break
			end
		end
		if not found then
			table.insert(missingScreens, tostring(expected))
		end
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		profile = V7.profileSummary(profile),
		stats = inventory.stats,
		screens = screens,
		screenCount = #screens,
		expectedScreens = expectedScreens,
		missingScreens = missingScreens,
		rootPath = V10.uiRootPath(profile),
	}
	State.uiScreenMap = result
	return result
end

function V11.actionDefinitions(profile)
	local defaults = {
		{ id = "play", keywords = { "play", "queue", "match" } },
		{ id = "vote", keywords = { "vote", "card", "select", "reality shift" } },
		{ id = "shop", keywords = { "shop", "buy", "store" } },
		{ id = "settings", keywords = { "setting", "settings", "options" } },
		{ id = "extraction", keywords = { "extract", "extraction" } },
		{ id = "replay", keywords = { "replay", "requeue", "again", "return" } },
		{ id = "ready", keywords = { "ready" } },
		{ id = "revive", keywords = { "revive", "downed" } },
		{ id = "mobile", keywords = { "mobile", "touch", "action" } },
	}
	local configured = V7.array(profile.uiActions)
	if #configured == 0 then
		return defaults
	end
	local actions = {}
	for _, action in ipairs(configured) do
		if type(action) == "table" then
			table.insert(actions, {
				id = tostring(action.id or action.name or "action"),
				keywords = V7.array(action.keywords),
			})
		else
			local id = tostring(action)
			table.insert(actions, { id = id, keywords = { id } })
		end
	end
	return actions
end

function V11.getUiInteractionMap(payload)
	payload = payload or {}
	local profile = V10.profile(payload)
	local inventory = V11.getDeepUiInventory(payload)
	local actions = V11.actionDefinitions(profile)
	local foundByAction = {}
	for _, action in ipairs(actions) do
		foundByAction[action.id] = {}
	end
	local buttons = {}
	local emptyButtons = {}
	for _, root in ipairs(inventory.roots or {}) do
		V11.walkUiNode(root.tree, 0, function(node)
			local lower = V11.searchText(node)
			if V11.isButtonClass(node.className) then
				local button = {
					name = node.name,
					path = node.path,
					className = node.className,
					text = V11.nodeText(node),
				}
				V11.addLimited(buttons, button, 120)
				if button.text == "" then
					V11.addLimited(emptyButtons, button, 80)
				end
			end
			for _, action in ipairs(actions) do
				for _, keyword in ipairs(action.keywords or {}) do
					local key = string.lower(tostring(keyword))
					if key ~= "" and lower:find(key, 1, true) then
						V11.addLimited(foundByAction[action.id], {
							name = node.name,
							path = node.path,
							className = node.className,
							text = V9.trimText(V11.nodeText(node), 100),
							matched = key,
						}, 20)
						break
					end
				end
			end
		end)
	end
	local missingActions = {}
	for _, action in ipairs(actions) do
		if #(foundByAction[action.id] or {}) == 0 then
			table.insert(missingActions, action.id)
		end
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		profile = V7.profileSummary(profile),
		actions = actions,
		foundByAction = foundByAction,
		missingActions = missingActions,
		buttons = buttons,
		emptyButtons = emptyButtons,
		buttonCount = #buttons,
	}
	State.uiInteractionMap = result
	return result
end

function V11.getUiResponsiveAudit(payload)
	payload = payload or {}
	local profile = V10.profile(payload)
	local screenMap = V11.getUiScreenMap(payload)
	local issues = {}
	local function issue(code, message, severity, path)
		V11.addLimited(issues, {
			code = code,
			message = message,
			severity = severity or "warning",
			path = path or "",
		}, 120)
	end
	for _, screen in ipairs(screenMap.screens or {}) do
		if not screen.hasSafeArea then
			issue("missingSafeArea", screen.name .. " has no obvious SafeArea container.", "warning", screen.path)
		end
		if not screen.hasUiScale then
			issue("missingUiScale", screen.name .. " has no UIScale descendant.", "info", screen.path)
		end
		if screen.counts.nodes > 220 then
			issue("denseScreen", screen.name .. " has " .. tostring(screen.counts.nodes) .. " UI nodes.", "info", screen.path)
		end
		for _, emptyButton in ipairs(screen.buttons or {}) do
			if tostring(emptyButton.text or "") == "" then
				issue("emptyButtonText", "Button has empty Text; ensure icon/tooltip/action mapping is clear.", "warning", emptyButton.path)
			end
		end
	end
	for _, root in ipairs((State.deepUiInventory or V11.getDeepUiInventory(payload)).roots or {}) do
		V11.walkUiNode(root.tree, 0, function(node)
			local props = node.properties or {}
			if V11.isTextClass(node.className) and props.TextScaled ~= true and tonumber(props.TextSize) and tonumber(props.TextSize) <= 10 then
				issue("tinyText", "Text object may be too small for mobile/readability.", "warning", node.path)
			end
			local size = V11.udim2Summary(props.Size)
			if size and ((size.xScale == 0 and size.xOffset > 520) or (size.yScale == 0 and size.yOffset > 520)) then
				issue("largeFixedSize", "Large fixed pixel size may need responsive constraints.", "info", node.path)
			end
		end)
	end
	local counts = {}
	for _, item in ipairs(issues) do
		V11.bump(counts, item.severity or "warning")
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		profile = V7.profileSummary(profile),
		screenCount = screenMap.screenCount,
		issues = issues,
		issueCount = #issues,
		counts = counts,
	}
	State.uiResponsiveAudit = result
	return result
end

function V11.flowDefinitions(profile)
	local configured = V7.array(profile.flowStates)
	if #configured > 0 then
		return configured
	end
	return {
		{ id = "menu", screens = { "MainMenu", "Menu" }, actions = { "play", "shop", "settings" } },
		{ id = "queue", patterns = { "queue", "searching" }, actions = { "play" } },
		{ id = "inMatchHud", screens = { "InGame", "HUD" }, patterns = { "health", "ammo", "objective", "rules" } },
		{ id = "vote", screens = { "Vote" }, patterns = { "vote", "reality shift" }, actions = { "vote" } },
		{ id = "extraction", patterns = { "extract", "extraction" }, actions = { "extraction" } },
		{ id = "endMatch", screens = { "End", "Result" }, patterns = { "victory", "defeat", "result" } },
		{ id = "reward", patterns = { "reward", "coins", "ink" } },
		{ id = "replay", patterns = { "replay", "requeue", "return" }, actions = { "replay" } },
	}
end

function V11.getUiGameFlowReport(payload)
	payload = payload or {}
	local profile = V10.profile(payload)
	local screenMap = V11.getUiScreenMap(payload)
	local interactions = V11.getUiInteractionMap(payload)
	local states = V11.flowDefinitions(profile)
	local flow = {}
	local missing = {}
	local allText = ""
	for _, screen in ipairs(screenMap.screens or {}) do
		allText = allText .. " " .. tostring(screen.name) .. " " .. tostring(screen.path)
		for _, label in ipairs(screen.labels or {}) do
			allText = allText .. " " .. tostring(label.text) .. " " .. tostring(label.name)
		end
	end
	allText = string.lower(allText)
	for _, state in ipairs(states) do
		local id = tostring(state.id or state.name or "state")
		local found = false
		local evidence = {}
		for _, screenName in ipairs(V7.array(state.screens)) do
			local key = string.lower(tostring(screenName))
			if key ~= "" and allText:find(key, 1, true) then
				found = true
				table.insert(evidence, "screen:" .. tostring(screenName))
			end
		end
		for _, pattern in ipairs(V7.array(state.patterns)) do
			local key = string.lower(tostring(pattern))
			if key ~= "" and allText:find(key, 1, true) then
				found = true
				table.insert(evidence, "pattern:" .. tostring(pattern))
			end
		end
		for _, action in ipairs(V7.array(state.actions)) do
			local matches = interactions.foundByAction and interactions.foundByAction[tostring(action)] or {}
			if #matches > 0 then
				found = true
				table.insert(evidence, "action:" .. tostring(action))
			end
		end
		table.insert(flow, {
			id = id,
			covered = found,
			evidence = evidence,
		})
		if not found then
			table.insert(missing, id)
		end
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		profile = V7.profileSummary(profile),
		flow = flow,
		missingFlowStates = missing,
		ready = #missing == 0,
	}
	State.uiGameFlowReport = result
	return result
end

function V11.getUiDirectorReport(payload)
	payload = payload or {}
	local profile = V10.profile(payload)
	local screenMap = V11.getUiScreenMap(payload)
	local interactions = V11.getUiInteractionMap(payload)
	local responsive = V11.getUiResponsiveAudit(payload)
	local flow = V11.getUiGameFlowReport(payload)
	local richUi = (screenMap.stats and (screenMap.stats.nodes or 0) or 0) >= 100 or (screenMap.screenCount or 0) >= 3
	local nextAction = "Polish the existing UI instead of creating a new HUD."
	if #flow.missingFlowStates > 0 then
		nextAction = "Add targeted UI polish for missing flow states: " .. table.concat(flow.missingFlowStates, ", ")
	elseif #interactions.missingActions > 0 then
		nextAction = "Add or label missing interaction affordances: " .. table.concat(interactions.missingActions, ", ")
	elseif responsive.issueCount > 0 then
		nextAction = "Tighten mobile/readability risks in the existing UI."
	end
	local issueCount = #(flow.missingFlowStates or {}) + #(interactions.missingActions or {}) + (responsive.issueCount or 0)
	local result = {
		at = isoNow(),
		version = VERSION,
		profile = V7.profileSummary(profile),
		richUi = richUi,
		summary = {
			nodes = screenMap.stats and screenMap.stats.nodes or 0,
			screenGuis = screenMap.stats and screenMap.stats.screenGuis or screenMap.screenCount,
			buttons = interactions.buttonCount,
			textObjects = screenMap.stats and screenMap.stats.textObjects or 0,
			screens = screenMap.screenCount,
		},
		screens = screenMap.screens,
		missingScreens = screenMap.missingScreens,
		missingActions = interactions.missingActions,
		missingFlowStates = flow.missingFlowStates,
		responsiveIssueCount = responsive.issueCount,
		responsiveIssues = responsive.issues,
		issueCount = issueCount,
		nextAction = nextAction,
	}
	State.uiDirectorReport = result
	return result
end

