				className = "TextButton",
				properties = {
					BackgroundColor3 = { __type = "Color3", mode = "rgb", r = 52, g = 112, b = 255 },
					TextColor3 = { __type = "Color3", mode = "rgb", r = 246, g = 248, b = 255 },
					Text = "Action",
					TextScaled = true,
					Size = { __type = "UDim2", xScale = 0, xOffset = 130, yScale = 0, yOffset = 46 },
					Position = { __type = "UDim2", xScale = 1, xOffset = -154, yScale = 1, yOffset = -72 },
				},
			},
			{
				type = "writeScript",
				path = root .. ".UiPolishManifest",
				className = "ModuleScript",
				source = "return {\n\tname = \"CodexUiPolish\",\n\tprofile = " .. V9.luaLiteral(profileId) .. ",\n\tversion = " .. V9.luaLiteral(VERSION) .. ",\n\tfocus = " .. V9.luaLiteral(focus) .. ",\n\tmissingFlowStates = " .. V9.luaLiteral(table.concat(report.missingFlowStates or {}, ",")) .. "\n}\n",
				overwrite = false,
			},
		},
	}
end

function V11.getUiPolishPlan(payload)
	payload = payload or {}
	local report = V11.getUiDirectorReport(payload)
	local blueprint = normalizeBlueprint(payload) or V11.uiPolishBlueprint(payload, report)
	local result = {
		at = isoNow(),
		version = VERSION,
		profile = report.profile,
		report = report,
		blueprint = blueprint,
		preview = V10.previewForBlueprint(blueprint),
	}
	State.uiPolishPlan = result
	return result
end

function V11.applyUiPolishPlan(payload)
	local plan = V11.getUiPolishPlan(payload or {})
	return V10.applyBlueprintCommand(payload or {}, plan.blueprint, "uiPolishPlan")
end

V12.last = {}

function V12.scriptRootServices()
	return {
		"ServerScriptService",
		"ReplicatedStorage",
		"StarterPlayer",
		"StarterGui",
		"Workspace",
		"ServerStorage",
		"ReplicatedFirst",
		"Lighting",
	}
end

function V12.safeService(name)
	local ok, service = pcall(function()
		return game:GetService(name)
	end)
	if ok then
		return service
	end
	return nil
end

function V12.serviceFromPath(path)
	return tostring(path or ""):match("^([^.]+)") or "Unknown"
end

function V12.profile(payload)
	payload = payload or {}
	if type(payload.profile) == "table" then
		return payload.profile
	end
	if type(payload.activeProfile) == "table" then
		return payload.activeProfile
	end
	return {}
end

function V12.profileList(profile, key)
	if type(profile) == "table" and type(profile[key]) == "table" then
		return profile[key]
	end
	return {}
end

function V12.disabledState(instance)
	local ok, value = pcall(function()
		return instance.Disabled
	end)
	if ok and type(value) == "boolean" then
		return value
	end
	return nil
end

function V12.scriptSystem(path, profile)
	path = tostring(path or "")
	local systems = V12.profileList(profile, "codeSystems")
	for _, system in ipairs(systems) do
		local root = tostring(system.root or system.path or "")
		if root ~= "" and (path == root or path:sub(1, #root + 1) == root .. ".") then
			return {
				id = tostring(system.id or system.name or root),
				name = tostring(system.name or system.id or root),
				root = root,
			}
		end
	end
	if path:sub(1, #"ServerScriptService.Systems") == "ServerScriptService.Systems" then
		return { id = "server-systems", name = "Server Systems", root = "ServerScriptService.Systems" }
	end
	if path:sub(1, #"ReplicatedStorage.Shared") == "ReplicatedStorage.Shared" then
		return { id = "shared", name = "Shared Modules", root = "ReplicatedStorage.Shared" }
	end
	if path:sub(1, #"StarterPlayer") == "StarterPlayer" then
		return { id = "client", name = "Client", root = "StarterPlayer" }
	end
	if path:sub(1, #"StarterGui") == "StarterGui" then
		return { id = "ui", name = "UI", root = "StarterGui" }
	end
	return { id = V12.serviceFromPath(path):lower(), name = V12.serviceFromPath(path), root = V12.serviceFromPath(path) }
end

function V12.collectScripts(payload, includeSource)
	payload = payload or {}
	local profile = V12.profile(payload)
	local maxScripts = math.max(1, math.min(tonumber(payload.maxScripts) or 1000, 2000))
	local scripts = {}
	local groups = {
		byService = {},
		bySystem = {},
		byClass = {},
	}
	local summary = {
		total = 0,
		scripts = 0,
		localScripts = 0,
		moduleScripts = 0,
		disabled = 0,
		readFailures = 0,
		truncated = false,
	}

	for _, serviceName in ipairs(V12.scriptRootServices()) do
		local root = V12.safeService(serviceName)
		if root then
			for _, instance in ipairs(root:GetDescendants()) do
				if #scripts >= maxScripts then
					summary.truncated = true
					break
				end
				if instance:IsA("LuaSourceContainer") then
					local path = safeFullName(instance)
					local disabled = V12.disabledState(instance)
					local source = nil
					local readError = nil
					local ok, sourceOrError = pcall(function()
						return readScriptSource(instance)
					end)
					if ok then
						source = sourceOrError or ""
					else
						readError = tostring(sourceOrError)
						summary.readFailures += 1
					end
					local system = V12.scriptSystem(path, profile)
					local record = {
						id = getInstanceId(instance),
						name = instance.Name,
						className = instance.ClassName,
						path = path,
						service = V12.serviceFromPath(path),
						system = system,
						disabled = disabled,
						lineCount = source and countLines(source) or nil,
						sourceHash = source and sourceHash(source) or nil,
						sourceLength = source and #source or nil,
						readable = source ~= nil,
						readError = readError,
					}
					if includeSource then
						record.source = source
					end
					table.insert(scripts, record)
					summary.total += 1
					if instance.ClassName == "Script" then
						summary.scripts += 1
					elseif instance.ClassName == "LocalScript" then
						summary.localScripts += 1
					elseif instance.ClassName == "ModuleScript" then
						summary.moduleScripts += 1
					end
					if disabled == true then
						summary.disabled += 1
					end
					groups.byService[record.service] = (groups.byService[record.service] or 0) + 1
					groups.bySystem[system.id] = (groups.bySystem[system.id] or 0) + 1
					groups.byClass[record.className] = (groups.byClass[record.className] or 0) + 1
				end
			end
		end
	end

	table.sort(scripts, function(a, b)
		return a.path < b.path
	end)
	return {
		at = isoNow(),
		version = VERSION,
		summary = summary,
		groups = groups,
		scripts = scripts,
	}
end

function V12.getScriptMap(payload)
	local result = V12.collectScripts(payload or {}, false)
	V12.last.scriptMap = {
		at = result.at,
		summary = result.summary,
	}
	return result
end

function V12.shortText(text, limit)
	text = tostring(text or "")
	limit = tonumber(limit) or 180
	if #text <= limit then
		return text
	end
	return text:sub(1, limit - 3) .. "..."
end

function V12.lineMatches(source, patterns)
	local matches = {}
	local lines = splitLines(source or "")
	for lineNumber, line in ipairs(lines) do
		for _, item in ipairs(patterns) do
			if line:find(item.pattern) then
				table.insert(matches, {
					line = lineNumber,
					kind = item.kind,
					text = V12.shortText(line, 220),
					value = item.extract and item.extract(line) or nil,
				})
			end
		end
	end
	return matches
end

function V12.requireMatches(source)
	local matches = {}
	local lines = splitLines(source or "")
	for lineNumber, line in ipairs(lines) do
		if line:find("require%s*%(") then
			local value = tostring(line:match("require%s*%((.*)") or line):gsub("^%s+", ""):gsub("%s+$", "")
			local quotedName = nil
			for name in line:gmatch("[\"']([^\"']+)[\"']") do
				quotedName = name
			end
			table.insert(matches, {
				line = lineNumber,
				raw = value,
				quotedName = quotedName,
				lastName = value:match("%.([%w_]+)%s*$") or value:match("([%w_]+)%s*$"),
				text = V12.shortText(line, 220),
			})
		end
	end
	return matches
end

function V12.serviceMatches(source)
	local services = {}
	for serviceName in tostring(source or ""):gmatch("game:GetService%s*%(%s*[\"']([^\"']+)[\"']") do
		services[serviceName] = (services[serviceName] or 0) + 1
	end
	local list = {}
	for name, count in pairs(services) do
		table.insert(list, { name = name, count = count })
	end
	table.sort(list, function(a, b)
		return a.name < b.name
	end)
	return list
end

function V12.moduleIndexes(scripts)
	local byName = {}
	local byPath = {}
	for _, script in ipairs(scripts or {}) do
		if script.className == "ModuleScript" then
			byName[script.name:lower()] = byName[script.name:lower()] or script
			byPath[script.path:lower()] = script
		end
	end
	return byName, byPath
end

function V12.resolveRequiredModule(match, byName, byPath)
	local target = match.quotedName or match.lastName or ""
	if target == "" then
		return nil
	end
	local lowered = target:lower()
	if byName[lowered] then
		return byName[lowered]
	end
	if byPath[lowered] then
		return byPath[lowered]
	end
	for path, script in pairs(byPath) do
		if path:sub(-#lowered) == lowered then
			return script
		end
	end
	return nil
end

function V12.getScriptDependencyGraph(payload)
	local map = V12.collectScripts(payload or {}, true)
	local byName, byPath = V12.moduleIndexes(map.scripts)
	local nodes = {}
	local edges = {}
	local unresolved = {}
	local serviceUsage = {}

	for _, script in ipairs(map.scripts) do
		table.insert(nodes, {
			id = script.id,
			path = script.path,
			name = script.name,
			className = script.className,
			system = script.system,
			lineCount = script.lineCount,
			sourceHash = script.sourceHash,
		})
		local services = V12.serviceMatches(script.source)
		for _, service in ipairs(services) do
			table.insert(serviceUsage, {
				scriptId = script.id,
				scriptPath = script.path,
				service = service.name,
				count = service.count,
			})
		end
		for _, match in ipairs(V12.requireMatches(script.source)) do
			local resolved = V12.resolveRequiredModule(match, byName, byPath)
			if resolved then
				table.insert(edges, {
					fromId = script.id,
					fromPath = script.path,
					toId = resolved.id,
					toPath = resolved.path,
					kind = "require",
					line = match.line,
					raw = match.raw,
				})
			else
				table.insert(unresolved, {
					scriptId = script.id,
					scriptPath = script.path,
					line = match.line,
					raw = match.raw,
					text = match.text,
				})
			end
		end
	end

	local result = {
		at = isoNow(),
		version = VERSION,
		summary = {
			scriptCount = #nodes,
			requireEdges = #edges,
			unresolvedRequires = #unresolved,
			serviceUsages = #serviceUsage,
		},
		nodes = nodes,
		edges = edges,
		unresolvedRequires = unresolved,
		serviceUsage = serviceUsage,
	}
	V12.last.dependencyGraph = result.summary
	return result
end

function V12.remoteInventory()
	local folder = resolveInstance("ReplicatedStorage.Remotes")
	local remotes = {}
	local byName = {}
	if folder then
		for _, child in ipairs(folder:GetChildren()) do
			if child:IsA("RemoteEvent") or child:IsA("RemoteFunction") then
				local item = {
					id = getInstanceId(child),
					name = child.Name,
					className = child.ClassName,
					path = safeFullName(child),
				}
				table.insert(remotes, item)
				byName[child.Name] = item
			end
		end
	end
	table.sort(remotes, function(a, b)
		return a.name < b.name
	end)
	return remotes, byName
end

function V12.remoteCandidatesFromSource(source)
	local candidates = {}
	local lines = splitLines(source or "")
	for lineNumber, line in ipairs(lines) do
		local lowered = line:lower()
		if lowered:find("remote", 1, true) or lowered:find("remotes", 1, true) then
			for name in line:gmatch("[Ww]aitForChild%s*%(%s*[\"']([^\"']+)[\"']") do
				candidates[name] = candidates[name] or { name = name, lines = {} }
				table.insert(candidates[name].lines, lineNumber)
			end
			for name in line:gmatch("[Ff]indFirstChild%s*%(%s*[\"']([^\"']+)[\"']") do
				candidates[name] = candidates[name] or { name = name, lines = {} }
				table.insert(candidates[name].lines, lineNumber)
			end
			for name in line:gmatch("getRemote[%w_]*%s*%(%s*[\"']([^\"']+)[\"']") do
				candidates[name] = candidates[name] or { name = name, lines = {} }
				table.insert(candidates[name].lines, lineNumber)
			end
		end
	end
	local list = {}
	for _, item in pairs(candidates) do
		table.insert(list, item)
	end
	table.sort(list, function(a, b)
		return a.name < b.name
	end)
	return list
end

function V12.remoteCallKinds(line)
	local kinds = {}
	if line:find(":FireServer%s*%(") then table.insert(kinds, "FireServer") end
	if line:find(":FireClient%s*%(") then table.insert(kinds, "FireClient") end
	if line:find(":FireAllClients%s*%(") then table.insert(kinds, "FireAllClients") end
	if line:find(":InvokeServer%s*%(") then table.insert(kinds, "InvokeServer") end
	if line:find(":InvokeClient%s*%(") then table.insert(kinds, "InvokeClient") end
	if line:find("%.OnServerEvent") then table.insert(kinds, "OnServerEvent") end
	if line:find("%.OnClientEvent") then table.insert(kinds, "OnClientEvent") end
	if line:find("%.OnServerInvoke") then table.insert(kinds, "OnServerInvoke") end
	if line:find("%.OnClientInvoke") then table.insert(kinds, "OnClientInvoke") end
	return kinds
end

function V12.remoteDirection(kind)
	if kind == "FireServer" or kind == "InvokeServer" then
		return "clientToServer"
	end
	if kind == "FireClient" or kind == "FireAllClients" or kind == "InvokeClient" then
		return "serverToClient"
	end
	if kind == "OnServerEvent" or kind == "OnServerInvoke" then
		return "serverReceives"
	end
	if kind == "OnClientEvent" or kind == "OnClientInvoke" then
		return "clientReceives"
	end
	return "unknown"
end

function V12.candidateNearLine(candidates, name, lineNumber, distance)
	distance = distance or 6
	for _, candidate in ipairs(candidates or {}) do
		if candidate.name == name then
			for _, candidateLine in ipairs(candidate.lines or {}) do
				if math.abs((tonumber(candidateLine) or 0) - lineNumber) <= distance then
					return true
				end
			end
		end
	end
	return false
end

function V12.expectedRemoteNames(payload, sourceCandidates)
	payload = payload or {}
	local expected = {}
	local profile = V12.profile(payload)
	if type(profile.expected) == "table" and type(profile.expected.remotes) == "table" then
		for _, remote in ipairs(profile.expected.remotes) do
			if type(remote) == "table" and remote.name then
				expected[tostring(remote.name)] = tostring(remote.className or "RemoteEvent")
			elseif type(remote) == "string" then
				expected[remote] = "RemoteEvent"
			end
		end
	end
	for _, remote in ipairs(V12.profileList(profile, "remoteExpectations")) do
		if type(remote) == "table" and remote.name then
			expected[tostring(remote.name)] = tostring(remote.className or "RemoteEvent")
		elseif type(remote) == "string" then
			expected[remote] = "RemoteEvent"
		end
	end
	for _, item in ipairs(sourceCandidates or {}) do
		if item.name and item.name ~= "Remotes" then
			expected[item.name] = expected[item.name] or "inferred"
		end
	end
	local list = {}
	for name, className in pairs(expected) do
		table.insert(list, { name = name, expectedClassName = className })
	end
	table.sort(list, function(a, b)
		return a.name < b.name
	end)
	return list
end

function V12.getRemoteUsageMap(payload)
	payload = payload or {}
	local map = V12.collectScripts(payload, true)
	local actualRemotes, actualByName = V12.remoteInventory()
	local usageByRemote = {}
	local usageByScript = {}
	local allCandidates = {}

	for _, script in ipairs(map.scripts) do
		local source = script.source or ""
		local scriptUsage = {}
		local candidates = V12.remoteCandidatesFromSource(source)
		for _, candidate in ipairs(candidates) do
			allCandidates[candidate.name] = allCandidates[candidate.name] or candidate
		end
		local lines = splitLines(source)
		for lineNumber, line in ipairs(lines) do
			local kinds = V12.remoteCallKinds(line)
			if #kinds > 0 then
				for _, remote in ipairs(actualRemotes) do
					if line:find(remote.name, 1, true) or V12.candidateNearLine(candidates, remote.name, lineNumber, 6) then
						for _, kind in ipairs(kinds) do
							local usage = {
								remoteName = remote.name,
								remoteClassName = remote.className,
								scriptId = script.id,
								scriptPath = script.path,
								scriptClassName = script.className,
								line = lineNumber,
								callStyle = kind,
								direction = V12.remoteDirection(kind),
								text = V12.shortText(line, 220),
								matchedInstance = true,
							}
							usageByRemote[remote.name] = usageByRemote[remote.name] or {}
							table.insert(usageByRemote[remote.name], usage)
							table.insert(scriptUsage, usage)
						end
					end
				end
				for _, candidate in ipairs(candidates) do
					if not actualByName[candidate.name] and (line:find(candidate.name, 1, true) or V12.candidateNearLine(candidates, candidate.name, lineNumber, 6)) then
						for _, kind in ipairs(kinds) do
							local usage = {
								remoteName = candidate.name,
								remoteClassName = "missing",
								scriptId = script.id,
								scriptPath = script.path,
								scriptClassName = script.className,
								line = lineNumber,
								callStyle = kind,
								direction = V12.remoteDirection(kind),
								text = V12.shortText(line, 220),
								matchedInstance = false,
							}
							usageByRemote[candidate.name] = usageByRemote[candidate.name] or {}
							table.insert(usageByRemote[candidate.name], usage)
							table.insert(scriptUsage, usage)
						end
					end
				end
			end
		end
		if #scriptUsage > 0 or #candidates > 0 then
			table.insert(usageByScript, {
				scriptId = script.id,
				scriptPath = script.path,
				scriptClassName = script.className,
				candidates = candidates,
				usages = scriptUsage,
			})
		end
	end

	local candidateList = {}
	for _, item in pairs(allCandidates) do
		table.insert(candidateList, item)
	end
	table.sort(candidateList, function(a, b)
		return a.name < b.name
	end)

	local expected = V12.expectedRemoteNames(payload, candidateList)
	local missing = {}
	local classConflicts = {}
	for _, item in ipairs(expected) do
		local actual = actualByName[item.name]
		if not actual then
			table.insert(missing, item)
		elseif item.expectedClassName ~= "inferred" and item.expectedClassName ~= actual.className then
			table.insert(classConflicts, {
				name = item.name,
				expectedClassName = item.expectedClassName,
				actualClassName = actual.className,
				path = actual.path,
			})
		end
	end

	local result = {
		at = isoNow(),
		version = VERSION,
		summary = {
			actualRemotes = #actualRemotes,
			expectedRemotes = #expected,
			missingExpected = #missing,
			classConflicts = #classConflicts,
			scriptsUsingRemotes = #usageByScript,
		},
		actualRemotes = actualRemotes,
		expectedRemotes = expected,
		missingExpected = missing,
		classConflicts = classConflicts,
		sourceInferredRemotes = candidateList,
		usageByRemote = usageByRemote,
		usageByScript = usageByScript,
	}
	V12.last.remoteUsage = result.summary
	return result
end

function V12.addRisk(risks, severity, code, message, data)
	table.insert(risks, {
		severity = severity,
		code = code,
		message = message,
		data = data or {},
	})
end

function V12.getCodeRiskAudit(payload)
	payload = payload or {}
	local map = V12.collectScripts(payload, true)
	local deps = V12.getScriptDependencyGraph(payload)
	local moduleReport = V13 and V13.getModuleResolutionReport and V13.getModuleResolutionReport(payload, map) or nil
	local remotes = V12.getRemoteUsageMap(payload)
	local risks = {}

	for _, script in ipairs(map.scripts) do
		if script.readError then
			V12.addRisk(risks, "warning", "sourceReadFailure", "Could not read source for " .. script.path, {
				path = script.path,
				error = script.readError,
			})
		end
		if script.disabled == true then
			V12.addRisk(risks, "info", "disabledScript", script.path .. " is disabled.", {
				path = script.path,
				className = script.className,
			})
		end
		if (script.lineCount or 0) > 900 then
			V12.addRisk(risks, "warning", "oversizedScript", script.path .. " is large and may be harder to maintain.", {
				path = script.path,
				lineCount = script.lineCount,
			})
		end
		if script.source and script.source:find("WaitForChild%s*%(%s*[\"'][^\"']+[\"']%s*%)") and not script.source:find("FindFirstChild%s*%(") then
			V12.addRisk(risks, "info", "unguardedWaitForChild", script.path .. " uses WaitForChild without nearby FindFirstChild guards.", {
				path = script.path,
			})
		end
	end

	if moduleReport then
		for _, item in ipairs(moduleReport.unresolvedRequirements or {}) do
			if item.severity == "warning" then
				V12.addRisk(risks, "warning", "unresolvedRequire", "Unresolved require in " .. item.scriptPath, item)
			end
		end
	else
		for _, item in ipairs(deps.unresolvedRequires or {}) do
			V12.addRisk(risks, "warning", "unresolvedRequire", "Unresolved require in " .. item.scriptPath, item)
		end
	end

	for _, remote in ipairs(remotes.missingExpected or {}) do
		V12.addRisk(risks, "warning", "missingExpectedRemote", "Expected remote is missing: " .. remote.name, remote)
	end

	for _, conflict in ipairs(remotes.classConflicts or {}) do
		V12.addRisk(risks, "warning", "remoteClassConflict", "Remote class mismatch: " .. conflict.name, conflict)
	end

	for name, usages in pairs(remotes.usageByRemote or {}) do
		if #usages == 0 then
			V12.addRisk(risks, "info", "unusedRemote", "Remote has no detected call usage: " .. name, { remoteName = name })
		end
	end

	local counts = {}
	for _, risk in ipairs(risks) do
		counts[risk.severity] = (counts[risk.severity] or 0) + 1
		counts[risk.code] = (counts[risk.code] or 0) + 1
	end
	table.sort(risks, function(a, b)
		local weights = { blocker = 4, error = 3, warning = 2, info = 1 }
		return (weights[a.severity] or 0) > (weights[b.severity] or 0)
	end)
	local nextFix = "No urgent code fix detected. Inspect the director report or patch a targeted script when you choose one."
	if counts.unresolvedRequire and counts.unresolvedRequire > 0 then
		nextFix = "Trace unresolved require warnings and repair the affected ModuleScript references."
	elseif counts.missingExpectedRemote and counts.missingExpectedRemote > 0 then
		nextFix = "Run remote diagnostics before editing code so script usage and remotes agree."
	elseif counts.sourceReadFailure and counts.sourceReadFailure > 0 then
		nextFix = "Inspect source read failures; some scripts may be protected or unavailable to the plugin."
	elseif counts.oversizedScript and counts.oversizedScript > 0 then
		nextFix = "Consider a supervised refactor plan for the largest script after backing it up."
	end

	local result = {
		at = isoNow(),
		version = VERSION,
		summary = {
			scriptCount = map.summary.total,
			riskCount = #risks,
			counts = counts,
			nextRecommendedFix = nextFix,
		},
		risks = risks,
	}
	V12.last.codeRiskAudit = result.summary
	return result
end

function V12.snippetForSource(source, lineNumber, contextLines)
	local lines = splitLines(source or "")
	lineNumber = math.max(1, math.min(tonumber(lineNumber) or 1, math.max(1, #lines)))
	contextLines = math.max(0, math.min(tonumber(contextLines) or 3, 8))
	local startLine = math.max(1, lineNumber - contextLines)
	local endLine = math.min(#lines, lineNumber + contextLines)
	local snippet = {}
	for index = startLine, endLine do
		table.insert(snippet, {
			line = index,
			text = lines[index],
			focus = index == lineNumber,
		})
	end
	return snippet
end

function V12.issueTerms(text)
	local terms = {}
	local seen = {}
	for token in tostring(text or ""):gmatch("[%w_]+") do
		if #token >= 5 then
			local lowered = token:lower()
			if not seen[lowered] then
				seen[lowered] = true
				table.insert(terms, token)
			end
		end
	end
	return terms
end

function V12.firstSourceLineWithTerms(source, terms)
	local lines = splitLines(source or "")
	for lineNumber, line in ipairs(lines) do
		local lowered = line:lower()
		for _, term in ipairs(terms or {}) do
			if lowered:find(term:lower(), 1, true) then
				return lineNumber
			end
		end
	end
	return 1
end

function V12.traceCodeIssue(payload)
	payload = payload or {}
	local text = tostring(payload.text or payload.message or payload.error or "")
	if text == "" then
		for index = #outputBuffer, 1, -1 do
			local entry = outputBuffer[index]
			if isErrorOrWarning(entry) and not V6.isBridgeNoiseMessage(entry.message) then
				text = tostring(entry.message or "")
				break
			end
		end
	end
	local map = V12.collectScripts(payload, true)
	local deps = V12.getScriptDependencyGraph(payload)
	local remotes = V12.getRemoteUsageMap(payload)
	local terms = V12.issueTerms(text)
	local loweredText = text:lower()
	local lineHint = tonumber(text:match(":(%d+):") or text:match("[Ll]ine%s+(%d+)"))
	local candidates = {}

	for _, script in ipairs(map.scripts) do
		local score = 0
		if loweredText ~= "" then
			if loweredText:find(script.path:lower(), 1, true) then score += 90 end
			if loweredText:find(script.name:lower(), 1, true) then score += 70 end
		end
		for _, term in ipairs(terms) do
			if script.source and script.source:lower():find(term:lower(), 1, true) then
				score += 5
			end
		end
		if score > 0 then
			local focusLine = lineHint or V12.firstSourceLineWithTerms(script.source, terms)
			table.insert(candidates, {
				id = script.id,
				name = script.name,
				className = script.className,
				path = script.path,
				score = score,
				line = focusLine,
				sourceHash = script.sourceHash,
				lineCount = script.lineCount,
				snippet = V12.snippetForSource(script.source, focusLine, payload.contextLines or 3),
			})
		end
	end

	table.sort(candidates, function(a, b)
		return a.score > b.score
	end)
	while #candidates > math.min(tonumber(payload.limit) or 8, 20) do
		table.remove(candidates)
	end

	local relatedDependencies = {}
	local candidatePaths = {}
	for _, candidate in ipairs(candidates) do
		candidatePaths[candidate.path] = true
	end
	for _, edge in ipairs(deps.edges or {}) do
		if candidatePaths[edge.fromPath] or candidatePaths[edge.toPath] then
			table.insert(relatedDependencies, edge)
		end
	end

	local relatedRemotes = {}
	for _, usage in ipairs(remotes.usageByScript or {}) do
		if candidatePaths[usage.scriptPath] then
			table.insert(relatedRemotes, usage)
		end
	end

	local result = {
		at = isoNow(),
		version = VERSION,
		issueText = text,
		lineHint = lineHint,
		candidates = candidates,
		relatedDependencies = relatedDependencies,
		relatedRemotes = relatedRemotes,
	}
	V12.last.traceCodeIssue = {
		at = result.at,
		candidates = #candidates,
	}
	return result
end

function V12.getCodeDirectorReport(payload)
	payload = payload or {}
	local map = V12.getScriptMap(payload)
	local deps = V12.getScriptDependencyGraph(payload)
	local remotes = V12.getRemoteUsageMap(payload)
	local risks = V12.getCodeRiskAudit(payload)
	local trace = V12.traceCodeIssue({
		profile = payload.profile,
		activeProfile = payload.activeProfile,
		limit = 3,
		contextLines = 2,
	})
	local nextAction = risks.summary.nextRecommendedFix
	if trace.issueText ~= "" and #trace.candidates > 0 then
		nextAction = "Trace the latest Output issue first: " .. trace.candidates[1].path
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		summary = {
			scripts = map.summary.total,
			moduleScripts = map.summary.moduleScripts,
			requireEdges = deps.summary.requireEdges,
			unresolvedRequires = deps.summary.unresolvedRequires,
			actualRemotes = remotes.summary.actualRemotes,
			missingRemotes = remotes.summary.missingExpected,
			risks = risks.summary.riskCount,
		},
		whatISee = {
			groups = map.groups,
			topRisks = risks.risks,
			latestIssueCandidates = trace.candidates,
		},
		nextAction = nextAction,
	}
	V12.last.codeDirectorReport = result.summary
	return result
end

function V12.getSafeFixPlan(payload)
	payload = payload or {}
	local targetText = tostring(payload.target or payload.text or payload.query or "")
	local trace = V12.traceCodeIssue({
		text = targetText,
		profile = payload.profile,
		activeProfile = payload.activeProfile,
		limit = payload.limit or 6,
		contextLines = payload.contextLines or 3,
	})
	local risks = V12.getCodeRiskAudit(payload)
	local targets = {}
	for _, candidate in ipairs(trace.candidates or {}) do
		table.insert(targets, {
			id = candidate.id,
			path = candidate.path,
			className = candidate.className,
			sourceHash = candidate.sourceHash,
			lineCount = candidate.lineCount,
			reason = "Matched supplied issue or script text.",
		})
	end
	if #targets == 0 then
		local map = V12.collectScripts(payload, false)
		for _, script in ipairs(map.scripts) do
			if targetText ~= "" and (script.name:lower() == targetText:lower() or script.path:lower():find(targetText:lower(), 1, true)) then
				table.insert(targets, {
					id = script.id,
					path = script.path,
					className = script.className,
					sourceHash = script.sourceHash,
					lineCount = script.lineCount,
					reason = "Matched script query.",
				})
				break
			end
		end
	end
	return {
		at = isoNow(),
		version = VERSION,
		mode = "readOnlyPlan",
		targetText = targetText,
		targets = targets,
		risks = risks.risks,
		steps = {
			"Read the target script source through Studio.",
			"Create a local snapshot under snapshots/.",
			"Prepare a patch payload with expectedSourceHash.",
			"Run applyCodePatchSet through Full Trust audit.",
			"Studio applies only if the source hash still matches.",
		},
		recommendedHelpers = {
			"tools\\bridge.cmd code patch preview <script> <new-source-file> [summary]",
			"tools\\bridge.cmd code patch apply <script> <new-source-file> [summary]",
		},
		approvalRequired = true,
	}
end

function V12.applyCodePatchSet(payload)
	payload = payload or {}
	local patches = payload.patches
	if type(patches) ~= "table" and type(payload.patchSet) == "table" then
		patches = payload.patchSet.patches
	end
	if type(patches) ~= "table" and type(payload.patch) == "table" then
		patches = { payload.patch }
	end
	if type(patches) ~= "table" or #patches == 0 then
		error("applyCodePatchSet requires payload.patches.")
	end

	return withUndo("ApplyCodePatchSet", function()
		local prepared = {}
		for index, patch in ipairs(patches) do
			if type(patch) ~= "table" then
				error("Patch " .. tostring(index) .. " must be a table.")
			end
			if type(patch.newSource) ~= "string" then
				error("Patch " .. tostring(index) .. " requires newSource.")
			end
			local instance = resolveInstance(patch.scriptId or patch.instanceId or patch.targetId or patch.path or patch.target)
			if not instance or not instance:IsA("LuaSourceContainer") then
				error("Patch " .. tostring(index) .. " target script was not found.")
			end
			local currentSource = readScriptSource(instance)
			local actualHash = sourceHash(currentSource)
			local expectedHash = tostring(patch.expectedSourceHash or "")
			if expectedHash == "" then
				error("Patch " .. tostring(index) .. " requires expectedSourceHash.")
			end
			if actualHash:lower() ~= expectedHash:lower() then
				error("Stale patch rejected for " .. safeFullName(instance) .. ". Current source hash is " .. actualHash .. ", expected " .. expectedHash .. ".")
			end
			table.insert(prepared, {
				instance = instance,
				currentSource = currentSource,
				actualHash = actualHash,
				patch = patch,
			})
		end

		local applied = {}
		for _, item in ipairs(prepared) do
			updateScriptSource(item.instance, item.patch.newSource)
			table.insert(applied, {
				id = getInstanceId(item.instance),
				path = safeFullName(item.instance),
				summary = item.patch.summary or "",
				backupPath = item.patch.backupPath or "",
				oldSourceHash = item.actualHash,
				newSourceHash = sourceHash(item.patch.newSource),
				diff = item.patch.diff or {
					oldLineCount = countLines(item.currentSource),
					newLineCount = countLines(item.patch.newSource),
					changedLineCount = changedLineCount(item.currentSource, item.patch.newSource),
				},
			})
		end
		stateDirty = true
		return {
			at = isoNow(),
			version = VERSION,
			summary = payload.summary or payload.name or "Code patch set",
			appliedCount = #applied,
			applied = applied,
			backups = payload.backups or {},
		}
	end)
end

V13.last = {}

function V13.quotedNames(text)
	local names = {}
	for name in tostring(text or ""):gmatch("[\"']([^\"']+)[\"']") do
		table.insert(names, name)
	end
	return names
end

function V13.scriptContext(script)
	if not script then
		return "unknown"
	end
	if script.className == "LocalScript" or tostring(script.path or ""):find("^StarterPlayer") or tostring(script.path or ""):find("^StarterGui") then
		return "client"
	end
	if tostring(script.path or ""):find("^ReplicatedStorage") then
		return "shared"
	end
	return "server"
end

function V13.resolveScript(payload, map)
	payload = payload or {}
	local query = tostring(payload.script or payload.path or payload.target or payload.query or payload.name or "")
	if query == "" and payload.scriptId then
		query = tostring(payload.scriptId)
	end
	local instance = nil
	if query ~= "" then
		instance = resolveInstance(query)
	end
	if instance and instance:IsA("LuaSourceContainer") then
		local ok, sourceOrError = pcall(function()
			return readScriptSource(instance)
		end)
		local source = ok and sourceOrError or nil
		return {
			id = getInstanceId(instance),
			name = instance.Name,
			className = instance.ClassName,
			path = safeFullName(instance),
			service = V12.serviceFromPath(safeFullName(instance)),
			system = V12.scriptSystem(safeFullName(instance), V12.profile(payload)),
			disabled = V12.disabledState(instance),
			lineCount = source and countLines(source) or nil,
			sourceHash = source and sourceHash(source) or nil,
			sourceLength = source and #source or nil,
			readable = source ~= nil,
			readError = ok and nil or tostring(sourceOrError),
			source = source,
		}
	end
	map = map or V12.collectScripts(payload, true)
	local lowered = query:lower()
	for _, script in ipairs(map.scripts or {}) do
		if lowered ~= "" and (script.id == query or script.name:lower() == lowered or script.path:lower() == lowered) then
			return script
		end
	end
	for _, script in ipairs(map.scripts or {}) do
		if lowered ~= "" and script.path:lower():find(lowered, 1, true) then
			return script
		end
	end
	return nil
end

function V13.functionMatches(source)
	local results = {}
	local lines = splitLines(source or "")
	for lineNumber, line in ipairs(lines) do
		local name = line:match("^%s*local%s+function%s+([%w_]+)")
			or line:match("^%s*function%s+([%w_%.:]+)")
		if name then
			table.insert(results, {
				name = name,
				line = lineNumber,
				text = V12.shortText(line, 180),
			})
		end
	end
	return results
end

function V13.eventMatches(source)
	local results = {}
	local lines = splitLines(source or "")
	for lineNumber, line in ipairs(lines) do
		if line:find(":Connect%s*%(") or line:find("%.Event:Connect%s*%(") then
			table.insert(results, {
				line = lineNumber,
				kind = "connect",
				text = V12.shortText(line, 180),
			})
		elseif line:find(":Once%s*%(") then
			table.insert(results, {
				line = lineNumber,
				kind = "once",
				text = V12.shortText(line, 180),
			})
		end
	end
	return results
end

function V13.resolveRequire(match, script, byName, byPath)
	local names = V13.quotedNames(match.text or match.raw or "")
	local targetName = names[#names] or match.quotedName or match.lastName or ""
	local raw = tostring(match.raw or "")
	local category = "lowConfidence"
	local confidence = 0.35
	if raw:match("^%s*%d+%s*%)?%s*$") or tostring(match.text or ""):match("require%s*%(%s*%d+") then
		category = "assetId"
		confidence = 0.95
	elseif targetName == "" and raw:find("script", 1, true) then
		category = "relativeUnknown"
		confidence = 0.45
	elseif targetName == "" then
		category = "dynamic"
		confidence = 0.3
	else
		category = "missing"
		confidence = 0.75
	end

	local resolved = nil
	if targetName ~= "" then
		resolved = V12.resolveRequiredModule({ quotedName = targetName, lastName = targetName }, byName, byPath)
	end
	if resolved then
		category = "resolved"
		confidence = resolved.name == targetName and 0.98 or 0.82
	end

	local severity = "info"
	if category == "missing" and confidence >= 0.7 then
		severity = "warning"
	elseif category == "relativeUnknown" then
		severity = "info"
	end

	return {
		scriptId = script.id,
		scriptPath = script.path,
		scriptClassName = script.className,
		line = match.line,
		raw = raw,
		text = match.text,
		targetName = targetName ~= "" and targetName or nil,
		status = resolved and "resolved" or "unresolved",
		category = category,
		confidence = confidence,
		severity = severity,
		resolvedId = resolved and resolved.id or nil,
		resolvedPath = resolved and resolved.path or nil,
		resolvedClassName = resolved and resolved.className or nil,
		contextType = V13.scriptContext(script),
	}
end

function V13.getModuleResolutionReport(payload, existingMap)
	payload = payload or {}
	local map = existingMap or V12.collectScripts(payload, true)
	local byName, byPath = V12.moduleIndexes(map.scripts)
	local resolved = {}
	local unresolved = {}
	local counts = {
		requireCount = 0,
		resolved = 0,
		unresolved = 0,
		missing = 0,
		dynamic = 0,
		assetId = 0,
		relativeUnknown = 0,
		lowConfidence = 0,
	}

	for _, script in ipairs(map.scripts or {}) do
		for _, match in ipairs(V12.requireMatches(script.source or "")) do
			local item = V13.resolveRequire(match, script, byName, byPath)
			counts.requireCount += 1
			if item.status == "resolved" then
				counts.resolved += 1
				table.insert(resolved, item)
			else
				counts.unresolved += 1
				counts[item.category] = (counts[item.category] or 0) + 1
				table.insert(unresolved, item)
			end
		end
	end

	local result = {
		at = isoNow(),
		version = VERSION,
		summary = counts,
		resolvedRequirements = resolved,
		unresolvedRequirements = unresolved,
	}
	V13.last.moduleResolution = result.summary
	return result
end

function V13.getCodeSmellReport(payload)
	payload = payload or {}
	local map = V12.collectScripts(payload, true)
	local profile = V12.profile(payload)
	local rules = type(profile.codeRiskRules) == "table" and profile.codeRiskRules or {}
	local lineLimit = tonumber(rules.oversizedScriptLineWarning) or 900
	local smells = {}
	local counts = {}
	for _, script in ipairs(map.scripts or {}) do
		local source = script.source or ""
		if (script.lineCount or 0) > lineLimit then
			table.insert(smells, { code = "oversizedScript", severity = "warning", path = script.path, lineCount = script.lineCount })
		end
		local todoCount = 0
		for _ in source:gmatch("[Tt][Oo][Dd][Oo]") do todoCount += 1 end
		for _ in source:gmatch("[Ff][Ii][Xx][Mm][Ee]") do todoCount += 1 end
		if todoCount > 0 then
			table.insert(smells, { code = "todoMarkers", severity = "info", path = script.path, count = todoCount })
		end
		local waitCount = 0
		for _ in source:gmatch("WaitForChild%s*%(") do waitCount += 1 end
		if waitCount >= 8 then
			table.insert(smells, { code = "manyWaitForChildCalls", severity = "info", path = script.path, count = waitCount })
		end
		local serviceCount = #V12.serviceMatches(source)
		if serviceCount >= 10 then
			table.insert(smells, { code = "manyServiceDependencies", severity = "info", path = script.path, count = serviceCount })
		end
		local remoteCount = #V12.remoteCandidatesFromSource(source)
		if remoteCount >= 10 then
			table.insert(smells, { code = "manyRemoteReferences", severity = "info", path = script.path, count = remoteCount })
		end
	end
	for _, smell in ipairs(smells) do
		counts[smell.severity] = (counts[smell.severity] or 0) + 1
		counts[smell.code] = (counts[smell.code] or 0) + 1
	end
	return {
		at = isoNow(),
		version = VERSION,
		summary = {
			scriptCount = map.summary.total,
			smellCount = #smells,
			counts = counts,
		},
		smells = smells,
	}
end

function V13.criticalPathSet(profile)
	local set = {}
	for _, path in ipairs(V12.profileList(profile, "criticalScripts")) do
		set[tostring(path)] = true
	end
	return set
end

function V13.getDeadCodeCandidates(payload)
	payload = payload or {}
	local map = V12.collectScripts(payload, false)
	local modules = V13.getModuleResolutionReport(payload)
	local remotes = V12.getRemoteUsageMap(payload)
	local profile = V12.profile(payload)
	local critical = V13.criticalPathSet(profile)
	local incoming = {}
	for _, edge in ipairs(modules.resolvedRequirements or {}) do
		if edge.resolvedPath then
			incoming[edge.resolvedPath] = (incoming[edge.resolvedPath] or 0) + 1
		end
	end
	local candidates = {}
	for _, script in ipairs(map.scripts or {}) do
		if script.className == "ModuleScript" and not critical[script.path] and not incoming[script.path] then
			table.insert(candidates, {
				kind = "moduleNoDetectedRequire",
				severity = "info",
				path = script.path,
				name = script.name,
				lineCount = script.lineCount,
				sourceHash = script.sourceHash,
			})
		end
		if script.disabled == true then
			table.insert(candidates, {
				kind = "disabledScript",
				severity = "info",
				path = script.path,
				name = script.name,
				className = script.className,
			})
		end
	end
	local usedRemotes = {}
	for name, usages in pairs(remotes.usageByRemote or {}) do
		if #usages > 0 then
			usedRemotes[name] = true
		end
	end
	for _, remote in ipairs(remotes.actualRemotes or {}) do
		if not usedRemotes[remote.name] then
			table.insert(candidates, {
				kind = "remoteNoDetectedUsage",
				severity = "info",
				name = remote.name,
				path = remote.path,
				className = remote.className,
			})
		end
	end
	return {
		at = isoNow(),
		version = VERSION,
		summary = {
			scriptCount = map.summary.total,
			candidateCount = #candidates,
		},
		candidates = candidates,
	}
end

function V13.getClientServerBoundaryAudit(payload)
	payload = payload or {}
	local map = V12.collectScripts(payload, true)
	local issues = {}
	local serverOnlyServices = {
		ServerStorage = true,
		ServerScriptService = true,
		DataStoreService = true,
		MessagingService = true,
	}
	local clientOnlyPatterns = {
		{ pattern = "Players%.LocalPlayer", code = "localPlayerUsage" },
		{ pattern = "UserInputService", code = "userInputUsage" },
		{ pattern = "ContextActionService", code = "contextActionUsage" },
		{ pattern = "RenderStepped", code = "renderSteppedUsage" },
		{ pattern = "CurrentCamera", code = "currentCameraUsage" },
	}
	for _, script in ipairs(map.scripts or {}) do
		local context = V13.scriptContext(script)
		local source = script.source or ""
		for _, service in ipairs(V12.serviceMatches(source)) do
			if context == "client" and serverOnlyServices[service.name] then
				table.insert(issues, {
					severity = "warning",
					code = "clientTouchesServerService",
					path = script.path,
					service = service.name,
				})
			elseif context == "shared" and serverOnlyServices[service.name] then
				table.insert(issues, {
					severity = "info",
					code = "sharedTouchesServerService",
					path = script.path,
					service = service.name,
				})
			end
		end
		for _, item in ipairs(clientOnlyPatterns) do
			if source:find(item.pattern) and context == "server" then
				table.insert(issues, {
					severity = "warning",
					code = "serverUsesClientApi",
					api = item.code,
					path = script.path,
				})
			elseif source:find(item.pattern) and context == "shared" then
				table.insert(issues, {
					severity = "info",
					code = "sharedUsesClientApi",
					api = item.code,
					path = script.path,
				})
			end
		end
		local calls = {}
		for _, line in ipairs(splitLines(source)) do
			for _, kind in ipairs(V12.remoteCallKinds(line)) do
				calls[kind] = true
			end
		end
		if context == "client" and (calls.FireClient or calls.FireAllClients or calls.InvokeClient or calls.OnServerEvent or calls.OnServerInvoke) then
			table.insert(issues, { severity = "warning", code = "clientUsesServerRemoteApi", path = script.path })
		end
		if context == "server" and (calls.FireServer or calls.InvokeServer or calls.OnClientEvent or calls.OnClientInvoke) then
			table.insert(issues, { severity = "warning", code = "serverUsesClientRemoteApi", path = script.path })
		end
	end
	local counts = {}
	for _, issue in ipairs(issues) do
		counts[issue.severity] = (counts[issue.severity] or 0) + 1
		counts[issue.code] = (counts[issue.code] or 0) + 1
	end
	return {
		at = isoNow(),
		version = VERSION,
		summary = {
			issueCount = #issues,
			counts = counts,
		},
		issues = issues,
	}
end

function V13.getRemoteContractReport(payload)
	payload = payload or {}
	local usage = V12.getRemoteUsageMap(payload)
	local contracts = {}
	local issues = {}
	for _, remote in ipairs(usage.actualRemotes or {}) do
		local usages = usage.usageByRemote[remote.name] or {}
		local contract = {
			name = remote.name,
			className = remote.className,
			path = remote.path,
			clientSends = 0,
			serverReceives = 0,
			serverSends = 0,
			clientReceives = 0,
			usages = usages,
		}
		for _, item in ipairs(usages) do
			if item.direction == "clientToServer" then contract.clientSends += 1 end
			if item.direction == "serverReceives" then contract.serverReceives += 1 end
			if item.direction == "serverToClient" then contract.serverSends += 1 end
			if item.direction == "clientReceives" then contract.clientReceives += 1 end
		end
		if contract.clientSends > 0 and contract.serverReceives == 0 then
			table.insert(issues, { severity = "warning", code = "clientSendWithoutServerHandler", remoteName = remote.name })
		end
		if contract.serverSends > 0 and contract.clientReceives == 0 then
			table.insert(issues, { severity = "warning", code = "serverSendWithoutClientListener", remoteName = remote.name })
		end
		if #usages == 0 then
			table.insert(issues, { severity = "info", code = "remoteNoDetectedUsage", remoteName = remote.name })
		end
		table.insert(contracts, contract)
	end
	local counts = {}
	for _, issue in ipairs(issues) do
		counts[issue.severity] = (counts[issue.severity] or 0) + 1
		counts[issue.code] = (counts[issue.code] or 0) + 1
	end
	return {
		at = isoNow(),
		version = VERSION,
		summary = {
			remoteCount = #contracts,
			issueCount = #issues,
			missingExpected = usage.summary.missingExpected,
			classConflicts = usage.summary.classConflicts,
			counts = counts,
		},
		contracts = contracts,
		issues = issues,
	}
end

function V13.explainScript(payload)
	payload = payload or {}
	local map = V12.collectScripts(payload, true)
	local script = V13.resolveScript(payload, map)
	if not script then
		error("Script was not found for explainScript.")
	end
	local moduleReport = V13.getModuleResolutionReport(payload, map)
	local remoteUsage = V12.getRemoteUsageMap(payload)
	local requires = {}
	local requiredBy = {}
	for _, item in ipairs(moduleReport.resolvedRequirements or {}) do
		if item.scriptPath == script.path then
			table.insert(requires, item)
		end
		if item.resolvedPath == script.path then
			table.insert(requiredBy, item)
		end
	end
	for _, item in ipairs(moduleReport.unresolvedRequirements or {}) do
		if item.scriptPath == script.path then
			table.insert(requires, item)
		end
	end
	local remotes = {}
	for _, item in ipairs(remoteUsage.usageByScript or {}) do
		if item.scriptPath == script.path then
			remotes = item.usages or {}
		end
	end
	return {
		at = isoNow(),
		version = VERSION,
		script = {
			id = script.id,
			name = script.name,
			className = script.className,
			path = script.path,
			contextType = V13.scriptContext(script),
			system = script.system,
			lineCount = script.lineCount,
			sourceHash = script.sourceHash,
			disabled = script.disabled,
		},
		services = V12.serviceMatches(script.source or ""),
		requires = requires,
		requiredBy = requiredBy,
		remotes = remotes,
		functions = V13.functionMatches(script.source or ""),
		events = V13.eventMatches(script.source or ""),
	}
end

function V13.getCodeFixDoctorReport(payload)
	payload = payload or {}
	local map = V12.getScriptMap(payload)
	local modules = V13.getModuleResolutionReport(payload)
	local smells = V13.getCodeSmellReport(payload)
	local dead = V13.getDeadCodeCandidates(payload)
	local boundaries = V13.getClientServerBoundaryAudit(payload)
	local contracts = V13.getRemoteContractReport(payload)
	local nextAction = "Codebase looks stable. Use code explain or code suggest-fix on the next specific issue."
	if modules.summary.missing and modules.summary.missing > 0 then
		nextAction = "Review missing module requires with code modules, then patch exact scripts if the require is truly broken."
	elseif boundaries.summary.issueCount > 0 then
		nextAction = "Check client/server boundary warnings before changing gameplay scripts."
	elseif contracts.summary.issueCount > 0 then
		nextAction = "Review remote contract gaps and confirm whether each remote is intentionally one-way."
	elseif smells.summary.smellCount > 0 then
		nextAction = "Use code smells to pick a small targeted cleanup."
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		summary = {
			scripts = map.summary.total,
			modules = modules.summary,
			smells = smells.summary,
			deadCandidates = dead.summary.candidateCount,
			boundaryIssues = boundaries.summary.issueCount,
			remoteContractIssues = contracts.summary.issueCount,
		},
		nextAction = nextAction,
		topModuleIssues = modules.unresolvedRequirements,
		topSmells = smells.smells,
		topBoundaryIssues = boundaries.issues,
		topRemoteIssues = contracts.issues,
	}
	V13.last.codeFixDoctorReport = result.summary
	return result
end

function V13.getCodeFixSuggestion(payload)
	payload = payload or {}
	local target = tostring(payload.target or payload.text or payload.query or payload.script or payload.path or "")
	local trace = V12.traceCodeIssue({
		text = target,
		profile = payload.profile,
		activeProfile = payload.activeProfile,
		limit = payload.limit or 5,
		contextLines = payload.contextLines or 3,
	})
	local explain = nil
	local ok, explainOrError = pcall(function()
		return V13.explainScript(payload)
	end)
	if ok then
		explain = explainOrError
	end
	local targets = {}
	if explain then
		table.insert(targets, {
			id = explain.script.id,
			path = explain.script.path,
			className = explain.script.className,
			sourceHash = explain.script.sourceHash,
			lineCount = explain.script.lineCount,
			reason = "Exact script explanation target.",
		})
	end
	for _, candidate in ipairs(trace.candidates or {}) do
		local exists = false
		for _, targetItem in ipairs(targets) do
			if targetItem.path == candidate.path then
				exists = true
			end
		end
		if not exists then
			table.insert(targets, {
				id = candidate.id,
				path = candidate.path,
				className = candidate.className,
				sourceHash = candidate.sourceHash,
				lineCount = candidate.lineCount,
				reason = "Matched issue text.",
			})
		end
	end
	return {
		at = isoNow(),
		version = VERSION,
		mode = "advisory",
		targetText = target,
		targets = targets,
		explanation = explain,
		trace = trace,
		steps = {
			"Inspect the target scripts and affected dependencies.",
			"Prepare changed source files locally.",
			"Run code patch-set preview with a JSON spec.",
			"Run code patch-set apply through Full Trust audit.",
			"Studio rejects stale patches if any expectedSourceHash no longer matches.",
		},
		recommendedHelpers = {
			"tools\\bridge.cmd code explain <script>",
			"tools\\bridge.cmd code patch-set preview <json-file>",
			"tools\\bridge.cmd code patch-set apply <json-file>",
		},
		approvalRequired = true,
	}
end

V14.last = {}

function V14.profile(payload)
	return V7.profileFromPayload(payload or {})
end

function V14.array(value)
	return V7.array(value)
end

function V14.profileTable(profile, key)
	if type(profile) == "table" and type(profile[key]) == "table" then
		return profile[key]
	end
	return {}
end

function V14.v3(x, y, z)
	return { __type = "Vector3", x = x, y = y, z = z }
end

function V14.color(r, g, b)
	return { __type = "Color3", mode = "rgb", r = r, g = g, b = b }
end

function V14.enum(enumType, name)
	return { __type = "EnumItem", enumType = enumType, name = name }
end

function V14.profileId(profile)
	return tostring((profile and profile.id) or "universal")
end

function V14.landmarkPaths(profile)
	local seen = {}
	local paths = {}
	local function add(path)
		path = tostring(path or "")
		if path ~= "" and not seen[path] then
			seen[path] = true
			table.insert(paths, path)
		end
	end
	for _, item in ipairs(V14.array(profile.landmarkExpectations)) do
		if type(item) == "table" then
			add(item.path)
		else
			add(item)
		end
	end
	for _, path in ipairs(V14.array(profile.visualLandmarks)) do
		add(path)
	end
	for _, path in ipairs(V7.expected(profile, "workspace")) do
		add(V7.pathFromRule(path))
	end
	return paths
end

function V14.pathPosition(path, fallback)
	local instance = resolvePath(path)
	if instance then
		if instance:IsA("BasePart") then
			return instance.Position
		elseif instance:IsA("Model") then
			local ok, cframe = pcall(function()
				return instance:GetBoundingBox()
			end)
			if ok and cframe then
				return cframe.Position
			end
		end
	end
	return fallback
end

function V14.boundsInfo(scene)
	if not scene or not scene.bounds or not scene.bounds.size then
		return nil
	end
	local size = scene.bounds.size
	return {
		x = tonumber(size.x) or 0,
		y = tonumber(size.y) or 0,
		z = tonumber(size.z) or 0,
	}
end

function V14.getWorldLandmarkReport(payload)
	payload = payload or {}
	local profile = V14.profile(payload)
	local present = {}
	local missing = {}
	for _, path in ipairs(V14.landmarkPaths(profile)) do
		local summary = V9.landmarkSummary(path)
		if summary.exists then
			table.insert(present, summary)
		else
			table.insert(missing, summary)
		end
	end
	return {
		at = isoNow(),
		version = VERSION,
		profile = V7.profileSummary(profile),
		present = present,
		missing = missing,
		summary = {
			expected = #present + #missing,
			present = #present,
			missing = #missing,
		},
	}
end

function V14.getBuildableAreaMap(payload)
	payload = payload or {}
	local profile = V14.profile(payload)
	local scene = V9.getSceneMap(payload)
	local areas = {}
	local center = scene.bounds and scene.bounds.center or V14.v3(0, 0, 0)
	local size = scene.bounds and scene.bounds.size or V14.v3(160, 20, 160)
	table.insert(areas, {
		id = "primary-build-zone",
		name = "Primary Build Zone",
		center = center,
		size = size,
		recommendedUse = "main playable space or blockout extension",
	})
	for _, landmark in ipairs(scene.landmarks or {}) do
		if landmark.exists and (landmark.position or landmark.boundingBox) then
			table.insert(areas, {
				id = "around-" .. tostring(landmark.name or "landmark"),
				name = "Around " .. tostring(landmark.name or landmark.path),
				center = landmark.position or (landmark.boundingBox and landmark.boundingBox.center),
				size = landmark.size or (landmark.boundingBox and landmark.boundingBox.size) or V14.v3(40, 10, 40),
				recommendedUse = "readability polish, props, signs, or encounter framing",
				sourcePath = landmark.path,
			})
		end
	end
	return {
		at = isoNow(),
		version = VERSION,
		profile = V7.profileSummary(profile),
		sceneSummary = scene.counts,
		bounds = scene.bounds,
		areas = areas,
	}
end

function V14.getWorldStyleReport(payload)
	payload = payload or {}
	local profile = V14.profile(payload)
	local scene = V9.getSceneMap(payload)
	local lighting = game:GetService("Lighting")
	local palette = V14.profileTable(profile, "materialPalette")
	local presets = V14.profileTable(profile, "lightingPresets")
	return {
		at = isoNow(),
		version = VERSION,
		profile = V7.profileSummary(profile),
		styleDefaults = V14.profileTable(profile, "styleDefaults"),
		materialPalette = palette,
		lightingPresets = presets,
		currentMaterials = scene.materials,
		currentColors = scene.colors,
		lighting = {
			ClockTime = lighting.ClockTime,
			Brightness = lighting.Brightness,
			Ambient = serializeValue(lighting.Ambient),
			OutdoorAmbient = serializeValue(lighting.OutdoorAmbient),
		},
	}
end

function V14.getAssetLibraryReport(payload)
	payload = payload or {}
	local profile = V14.profile(payload)
	local inventory = V9.getAssetInventory(payload)
	local categories = V14.profileTable(profile, "assetCategories")
	local grouped = {}
	local groupedCounts = {}
	local missingCategories = {}
	for category, classes in pairs(categories) do
		grouped[category] = {}
		groupedCounts[category] = 0
		local classSet = {}
		for _, className in ipairs(V14.array(classes)) do
			classSet[tostring(className)] = true
		end
		for _, asset in ipairs(inventory.assets or {}) do
			if classSet[asset.className] then
				groupedCounts[category] = groupedCounts[category] + 1
				if #grouped[category] < 25 then
					table.insert(grouped[category], {
						id = asset.id,
						path = asset.path,
						name = asset.name,
						className = asset.className,
						childCount = asset.childCount,
					})
				end
			end
		end
		if #grouped[category] == 0 then
			table.insert(missingCategories, category)
		end
	end
	return {
		at = isoNow(),
		version = VERSION,
		profile = V7.profileSummary(profile),
		assetCount = inventory.count,
		classCounts = inventory.classCounts,
		grouped = grouped,
		groupedCounts = groupedCounts,
		missingCategories = missingCategories,
		needs = V14.array(profile.assetNeeds),
		kits = V14.array(profile.propKits),
	}
end

function V14.getWorldDesignAudit(payload)
	payload = payload or {}
	local profile = V14.profile(payload)
	local scene = V9.getSceneMap(payload)
	local landmarks = V14.getWorldLandmarkReport(payload)
	local issues = {}
	local bounds = V14.boundsInfo(scene)
	if scene.counts.spawnLocations == 0 then
		table.insert(issues, { severity = "warning", code = "missingSpawnLocation", message = "No SpawnLocation detected in Workspace." })
	end
	if (scene.counts.baseParts or 0) < 20 then
		table.insert(issues, { severity = "info", code = "sparseWorld", message = "World has very few BaseParts for a playable space." })
	end
	if bounds and (bounds.x < 80 or bounds.z < 80) then
		table.insert(issues, { severity = "info", code = "smallPlayableBounds", message = "Playable bounds look small for a full game loop.", bounds = bounds })
	end
	if landmarks.summary.missing > 0 then
		table.insert(issues, { severity = "warning", code = "missingLandmarks", message = "Some profile landmarks are missing.", missing = landmarks.missing })
	end
	if (scene.counts.unanchoredParts or 0) > 0 then
		table.insert(issues, { severity = "info", code = "unanchoredParts", message = "Unanchored parts exist and may affect playtest stability.", count = scene.counts.unanchoredParts })
	end
	local counts = {}
	for _, issue in ipairs(issues) do
		counts[issue.severity] = (counts[issue.severity] or 0) + 1
		counts[issue.code] = (counts[issue.code] or 0) + 1
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		profile = V7.profileSummary(profile),
		scene = {
			counts = scene.counts,
			bounds = scene.bounds,
			materials = scene.materials,
			rootChildren = scene.rootChildren,
		},
		landmarks = landmarks,
		issues = issues,
		summary = {
			issueCount = #issues,
			counts = counts,
		},
		nextRecommendation = V14.profileId(profile) == "ruleforge"
			and "Preview world plan for extraction readability and arena landmark polish."
			or "Preview world plan for a safe blockout, spawn, objective, and landmark structure.",
	}
	V14.last.worldAudit = result.summary
	return result
end

function V14.basePart(path, name, position, size, color, material, extra)
	local properties = {
		Anchored = true,
		Position = position,
		Size = size,
		Color = color,
		Material = material or "SmoothPlastic",
	}
	for key, value in pairs(extra or {}) do
		properties[key] = value
	end
	return {
		type = "createPart",
		path = path,
		properties = properties,
	}
end

function V14.worldForgeBlueprint(payload, audit)
	payload = payload or {}
	local profile = V14.profile(payload)
	local profileId = V14.profileId(profile)
	local steps = {
		{ type = "ensureFolder", path = "Workspace.CodexWorldForge" },
	}
	if profileId == "ruleforge" then
		local pad = V14.pathPosition("Workspace.ExtractionPad", Vector3.new(0, 2, 0))
		table.insert(steps, { type = "ensureFolder", path = "Workspace.CodexWorldForge.RuleforgeArenaPolish" })
		table.insert(steps, V14.basePart("Workspace.CodexWorldForge.RuleforgeArenaPolish.ExtractionReadabilityPlate", "ExtractionReadabilityPlate", V14.v3(pad.X, math.max(0.2, pad.Y + 0.15), pad.Z), V14.v3(34, 0.25, 34), V14.color(35, 180, 255), "Neon", { Transparency = 0.55 }))
		table.insert(steps, V14.basePart("Workspace.CodexWorldForge.RuleforgeArenaPolish.ExtractionNorthBeacon", "ExtractionNorthBeacon", V14.v3(pad.X, pad.Y + 7, pad.Z - 22), V14.v3(2, 14, 2), V14.color(80, 220, 255), "Neon", { Transparency = 0.2 }))
		table.insert(steps, V14.basePart("Workspace.CodexWorldForge.RuleforgeArenaPolish.ExtractionSouthBeacon", "ExtractionSouthBeacon", V14.v3(pad.X, pad.Y + 7, pad.Z + 22), V14.v3(2, 14, 2), V14.color(80, 220, 255), "Neon", { Transparency = 0.2 }))
	else
		table.insert(steps, { type = "createSpawnLocation", path = "Workspace.CodexWorldForge.PlayerSpawn", properties = { Anchored = true, Position = V14.v3(0, 3, -42), Size = V14.v3(12, 1, 12), Neutral = true } })
		table.insert(steps, V14.basePart("Workspace.CodexWorldForge.BlockoutFloor", "BlockoutFloor", V14.v3(0, 0, 0), V14.v3(120, 1, 120), V14.color(90, 105, 110), "Concrete"))
		table.insert(steps, V14.basePart("Workspace.CodexWorldForge.ObjectiveMarker", "ObjectiveMarker", V14.v3(0, 5, 42), V14.v3(12, 10, 12), V14.color(255, 210, 90), "Neon", { Transparency = 0.25 }))
	end
	return {
		name = (profile.name or "Universal") .. " World Forge Plan",
		mode = "supervised",
		source = "V14.getWorldForgePlan",
		steps = steps,
	}
end

