	local kits = {
		{ id = "arena-combat-blockout", title = "Arena Combat Blockout", genre = "arena-combat", file = "blueprints/kits/arena-combat-blockout.json" },
		{ id = "obby-course-kit", title = "Obby Course Kit", genre = "obby", file = "blueprints/kits/obby-course-kit.json" },
		{ id = "simulator-plaza-kit", title = "Simulator Plaza Kit", genre = "simulator", file = "blueprints/kits/simulator-plaza-kit.json" },
		{ id = "horror-objective-house-kit", title = "Horror Objective House Kit", genre = "horror", file = "blueprints/kits/horror-objective-house-kit.json" },
		{ id = "ruleforge-arena-polish-kit", title = "Ruleforge Arena Polish Kit", genre = "arena-extraction", file = "blueprints/kits/ruleforge-arena-polish-kit.json" },
	}
	local seen = {}
	for _, kit in ipairs(kits) do
		seen[tostring(kit.id)] = true
	end
	for _, kit in ipairs(V14.array(profile.propKits)) do
		local id = tostring(kit.id or "")
		if id ~= "" and not seen[id] then
			seen[id] = true
			table.insert(kits, kit)
		end
	end
	return {
		at = isoNow(),
		version = VERSION,
		profile = V7.profileSummary(profile),
		kits = kits,
		count = #kits,
	}
end

