function V6.sourceSnippetForCandidate(candidate, contextLines)
	contextLines = math.max(0, math.min(tonumber(contextLines) or 3, 8))
	local instance = resolveInstance(candidate.id or candidate.path)
	if not instance or not instance:IsA("LuaSourceContainer") then
		return nil
	end
	local ok, sourceOrError = pcall(function()
		return readScriptSource(instance)
	end)
	if not ok then
		return {
			path = candidate.path,
			error = tostring(sourceOrError),
		}
	end
	local lines = splitLines(sourceOrError)
	local lineNumber = tonumber(candidate.line) or 1
	local startLine = math.max(1, lineNumber - contextLines)
	local endLine = math.min(#lines, lineNumber + contextLines)
	local snippet = {}
	for index = startLine, endLine do
		table.insert(snippet, {
			line = index,
			text = lines[index],
			focus = index == lineNumber,
		})
	end
	return {
		id = getInstanceId(instance),
		path = safeFullName(instance),
		line = candidate.line,
		snippet = snippet,
	}
end

function V6.getBugContext(payload)
	payload = payload or {}
	local text = tostring(payload.text or payload.message or "")
	if text == "" then
		for index = #outputBuffer, 1, -1 do
			local entry = outputBuffer[index]
			if isErrorOrWarning(entry) and not V6.isBridgeNoiseMessage(entry.message) then
				text = tostring(entry.message or "")
				break
			end
		end
	end
	local trace = traceOutputError({
		text = text,
		limit = payload.limit or 8,
	})
	local snippets = {}
	for index, candidate in ipairs(trace.candidates or {}) do
		if index > 5 then
			break
		end
		local snippet = V6.sourceSnippetForCandidate(candidate, payload.contextLines or 3)
		if snippet then
			table.insert(snippets, snippet)
		end
	end

	local remoteDoctor = V6.diagnoseRemoteSystem(payload.remotePayload or {})
	local relatedRemotes = {}
	local loweredText = text:lower()
	for _, name in ipairs(remoteDoctor.expected.union or {}) do
		if loweredText ~= "" and loweredText:find(name:lower(), 1, true) then
			table.insert(relatedRemotes, name)
		end
	end

	local result = {
		at = isoNow(),
		errorText = text,
		trace = trace,
		sourceSnippets = snippets,
		runtime = getRuntimeStatus(),
		snapshot = getRuntimeSnapshot({
			folderPaths = {
				"Workspace.LiveEnemies",
				"Workspace.RelicZones",
				"Workspace.ExtractionPad",
				"Workspace.ExtractionZone",
				"ReplicatedStorage.Remotes",
			},
		}),
		relatedRemotes = relatedRemotes,
		remoteSummary = {
			missing = remoteDoctor.comparison.missingFromEditCount,
			mismatched = remoteDoctor.comparison.mismatchedCount,
			runtimeMessage = remoteDoctor.runtimeMessage,
		},
	}
	State.bugContext = result
	return result
end

local function prepareScriptPatch(payload)
	local instance = resolveInstance(payload.instanceId or payload.scriptId or payload.targetId or payload.path or payload.target)
	local currentSource = readScriptSource(instance)
	local newSource = payload.newSource
	local diff = nil
	if type(newSource) == "string" then
		diff = {
			oldLineCount = countLines(currentSource),
			newLineCount = countLines(newSource),
			changedLineCount = changedLineCount(currentSource, newSource),
			oldLength = #currentSource,
			newLength = #newSource,
		}
	end

	return {
		id = getInstanceId(instance),
		name = instance.Name,
		className = instance.ClassName,
		path = safeFullName(instance),
		source = currentSource,
		sourceHash = sourceHash(currentSource),
		lineCount = countLines(currentSource),
		length = #currentSource,
		diff = diff,
	}
end

local BLUEPRINT_STEP_TYPES = {
	ensureFolder = true,
	ensureRemoteEvent = true,
	ensureRemoteFunction = true,
	ensureInstance = true,
	createInstance = true,
	createPart = true,
	createModel = true,
	createSpawnLocation = true,
	writeScript = true,
	setProperties = true,
	setLighting = true,
	fillTerrainBlock = true,
}

function normalizeBlueprint(payload)
	if type(payload) ~= "table" then
		return nil
	end
	if type(payload.blueprint) == "table" then
		return payload.blueprint
	end
	if type(payload.buildPlan) == "table" then
		return payload.buildPlan
	end
	if type(payload.steps) == "table" then
		return payload
	end
	return nil
end

local function supportedBlueprintStepTypes()
	local types = {}
	for stepType in pairs(BLUEPRINT_STEP_TYPES) do
		table.insert(types, stepType)
	end
	table.sort(types)
	return types
end

local function validateBlueprint(payload)
	local blueprint = normalizeBlueprint(payload)
	local errors = {}
	local warnings = {}

	if type(blueprint) ~= "table" then
		table.insert(errors, "Blueprint must be a JSON object with a steps array.")
		return {
			valid = false,
			errors = errors,
			warnings = warnings,
			supportedStepTypes = supportedBlueprintStepTypes(),
		}
	end

	if type(blueprint.name) ~= "string" or blueprint.name == "" then
		table.insert(warnings, "Blueprint has no name.")
	end
	if type(blueprint.steps) ~= "table" then
		table.insert(errors, "Blueprint steps must be an array.")
	else
		for index, step in ipairs(blueprint.steps) do
			if type(step) ~= "table" then
				table.insert(errors, "Step " .. tostring(index) .. " must be an object.")
			else
				local stepType = tostring(step.type or "")
				if not BLUEPRINT_STEP_TYPES[stepType] then
					table.insert(errors, "Step " .. tostring(index) .. " has unsupported type: " .. stepType)
				end

				if stepType ~= "setLighting" and stepType ~= "fillTerrainBlock" then
					if type(step.path) ~= "string" or step.path == "" then
						table.insert(errors, "Step " .. tostring(index) .. " requires a path.")
					end
				end

				if stepType == "writeScript" then
					local className = tostring(step.className or "Script")
					if className ~= "Script" and className ~= "LocalScript" and className ~= "ModuleScript" then
						table.insert(errors, "Step " .. tostring(index) .. " writeScript className must be Script, LocalScript, or ModuleScript.")
					end
					if type(step.source) ~= "string" then
						table.insert(errors, "Step " .. tostring(index) .. " writeScript requires source.")
					end
				end

				if stepType == "fillTerrainBlock" then
					if type(step.size) ~= "table" then
						table.insert(errors, "Step " .. tostring(index) .. " fillTerrainBlock requires size.")
					end
					if type(step.position) ~= "table" and type(step.cframe) ~= "table" then
						table.insert(errors, "Step " .. tostring(index) .. " fillTerrainBlock requires position or cframe.")
					end
				end
			end
		end
	end

	return {
		valid = #errors == 0,
		errors = errors,
		warnings = warnings,
		name = blueprint.name or "",
		mode = blueprint.mode or "supervised",
		stepCount = type(blueprint.steps) == "table" and #blueprint.steps or 0,
		supportedStepTypes = supportedBlueprintStepTypes(),
	}
end

local function pathSegments(path)
	return string.split(tostring(path or ""), ".")
end

local function getParentAndName(path, createFolders)
	local segments = pathSegments(path)
	if #segments < 2 then
		return nil, nil, "Path must include a service/root and child name."
	end

	local ok, current = pcall(function()
		return game:GetService(segments[1])
	end)
	if not ok or not current then
		current = game:FindFirstChild(segments[1])
	end
	if not current then
		return nil, nil, "Root not found: " .. tostring(segments[1])
	end

	for index = 2, #segments - 1 do
		local child = current:FindFirstChild(segments[index])
		if not child then
			if not createFolders then
				return nil, nil, "Parent segment not found: " .. table.concat(segments, ".", 1, index)
			end
			child = Instance.new("Folder")
			child.Name = segments[index]
			child.Parent = current
		end
		current = child
	end

	return current, segments[#segments], nil
end

local function ensureFolderPath(path)
	local segments = pathSegments(path)
	if #segments == 0 then
		return nil, "Path is empty."
	end

	local ok, current = pcall(function()
		return game:GetService(segments[1])
	end)
	if not ok or not current then
		current = game:FindFirstChild(segments[1])
	end
	if not current then
		return nil, "Root not found: " .. tostring(segments[1])
	end

	for index = 2, #segments do
		local child = current:FindFirstChild(segments[index])
		if not child then
			child = Instance.new("Folder")
			child.Name = segments[index]
			child.Parent = current
		elseif not child:IsA("Folder") then
			return nil, "Existing object is not a Folder: " .. table.concat(segments, ".", 1, index)
		end
		current = child
	end

	return current
end

local function classForStep(step)
	if step.type == "ensureFolder" then
		return "Folder"
	end
	if step.type == "ensureRemoteEvent" then
		return "RemoteEvent"
	end
	if step.type == "ensureRemoteFunction" then
		return "RemoteFunction"
	end
	if step.type == "createPart" then
		return "Part"
	end
	if step.type == "createModel" then
		return "Model"
	end
	if step.type == "createSpawnLocation" then
		return "SpawnLocation"
	end
	if step.type == "writeScript" then
		return tostring(step.className or "Script")
	end
	return tostring(step.className or "Folder")
end

local function vectorFromValue(value, fallback)
	if type(value) ~= "table" then
		return fallback
	end
	if value.__type then
		local converted = deserializeValue(value)
		if typeof(converted) == "Vector3" then
			return converted
		end
	end
	return Vector3.new(tonumber(value.x) or fallback.X, tonumber(value.y) or fallback.Y, tonumber(value.z) or fallback.Z)
end

local function cframeFromStep(step)
	if type(step.cframe) == "table" and step.cframe.__type == "CFrame" then
		local converted = deserializeValue(step.cframe)
		if typeof(converted) == "CFrame" then
			return converted
		end
	end
	local position = vectorFromValue(step.position, Vector3.new(0, 0, 0))
	return CFrame.new(position)
end

local function materialFromValue(value)
	if type(value) == "table" and value.__type == "EnumItem" then
		local converted = deserializeValue(value)
		if typeof(converted) == "EnumItem" then
			return converted
		end
	end
	if type(value) == "string" and Enum.Material[value] then
		return Enum.Material[value]
	end
	return Enum.Material.Grass
end

local function previewBlueprintStep(step, index)
	local stepType = tostring(step.type or "")
	local result = {
		index = index,
		type = stepType,
		path = step.path,
		status = "unknown",
		action = "none",
		message = "",
	}

	if stepType == "setLighting" then
		result.status = "ok"
		result.action = "wouldUpdate"
		result.path = "Lighting"
		return result
	end

	if stepType == "fillTerrainBlock" then
		result.status = "ok"
		result.action = "wouldFillTerrain"
		result.path = "Workspace.Terrain"
		return result
	end

	local existing = resolvePath(step.path)
	local expectedClass = classForStep(step)
	if existing then
		result.className = existing.ClassName
		if stepType == "setProperties" then
			result.status = "ok"
			result.action = "wouldUpdate"
		elseif stepType == "writeScript" then
			if not existing:IsA("LuaSourceContainer") then
				result.status = "failed"
				result.action = "classConflict"
				result.message = "Existing object is not script-like."
			elseif step.overwrite == true then
				result.status = "ok"
				result.action = "wouldUpdate"
			else
				result.status = "skipped"
				result.action = "exists"
				result.message = "Existing script skipped because overwrite is not true."
			end
		elseif existing.ClassName == expectedClass or (expectedClass == "Folder" and existing:IsA("Folder")) then
			if step.overwrite == true and step.properties then
				result.status = "ok"
				result.action = "wouldUpdate"
			else
				result.status = "skipped"
				result.action = "exists"
			end
		else
			result.status = "failed"
			result.action = "classConflict"
			result.message = "Existing " .. existing.ClassName .. " does not match expected " .. expectedClass .. "."
		end
	else
		result.status = "ok"
		result.action = "wouldCreate"
		result.className = expectedClass
	end

	return result
end

previewBuildPlan = function(payload)
	local validation = validateBlueprint(payload)
	local blueprint = normalizeBlueprint(payload)
	local steps = {}
	if validation.valid and blueprint then
		for index, step in ipairs(blueprint.steps or {}) do
			table.insert(steps, previewBlueprintStep(step, index))
		end
	end
	return {
		valid = validation.valid,
		name = validation.name,
		mode = validation.mode,
		errors = validation.errors,
		warnings = validation.warnings,
		stepCount = validation.stepCount,
		steps = steps,
	}
end

local function applyBlueprintStep(step, index, result)
	local stepType = tostring(step.type or "")
	local path = step.path
	local entry = {
		index = index,
		type = stepType,
		path = path,
		status = "unknown",
		action = "none",
	}

	local function finish(status, action, instance, message)
		entry.status = status
		entry.action = action
		entry.message = message or ""
		if instance then
			entry.id = getInstanceId(instance)
			entry.path = safeFullName(instance)
			entry.className = instance.ClassName
		end
		table.insert(result.steps, entry)
		if status == "created" then
			table.insert(result.created, entry)
		elseif status == "updated" then
			table.insert(result.updated, entry)
		elseif status == "skipped" then
			table.insert(result.skipped, entry)
		elseif status == "failed" then
			table.insert(result.failed, entry)
		end
		return entry
	end

	if stepType == "ensureFolder" then
		local existing = resolvePath(path)
		if existing then
			if existing:IsA("Folder") or existing == game then
				return finish("skipped", "exists", existing)
			end
			return finish("failed", "classConflict", existing, "Existing object is not a Folder.")
		end
		local folder, err = ensureFolderPath(path)
		if not folder then
			return finish("failed", "createFolder", nil, err)
		end
		return finish("created", "created", folder)
	end

	if stepType == "setLighting" then
		local lighting = game:GetService("Lighting")
		local failures = setProperties(lighting, step.properties or {})
		for _, failure in ipairs(failures) do
			table.insert(result.warnings, "setLighting: " .. failure)
		end
		return finish("updated", "setProperties", lighting)
	end

	if stepType == "fillTerrainBlock" then
		local size = vectorFromValue(step.size, Vector3.new(16, 4, 16))
		if size.X * size.Y * size.Z > 1000000 then
			return finish("failed", "terrainTooLarge", nil, "Terrain block is too large.")
		end
		local terrain = workspace.Terrain
		terrain:FillBlock(cframeFromStep(step), size, materialFromValue(step.material))
		return finish("updated", "fillTerrainBlock", terrain)
	end

	local existing = resolvePath(path)
	local className = classForStep(step)

	if stepType == "setProperties" then
		if not existing then
			return finish("failed", "missingTarget", nil, "Target not found.")
		end
		local failures = setProperties(existing, step.properties or {})
		for _, failure in ipairs(failures) do
			table.insert(result.warnings, tostring(path) .. ": " .. failure)
		end
		return finish("updated", "setProperties", existing)
	end

	if stepType == "writeScript" then
		if existing then
			if not existing:IsA("LuaSourceContainer") then
				return finish("failed", "classConflict", existing, "Existing object is not script-like.")
			end
			if step.overwrite ~= true then
				return finish("skipped", "exists", existing, "Existing script skipped because overwrite is not true.")
			end
			local currentSource = readScriptSource(existing)
			if type(step.expectedSourceHash) ~= "string" or step.expectedSourceHash == "" then
				return finish("failed", "missingHash", existing, "Overwriting scripts requires expectedSourceHash.")
			end
			local actualHash = sourceHash(currentSource)
			if actualHash:lower() ~= step.expectedSourceHash:lower() then
				return finish("failed", "staleHash", existing, "Current source hash is " .. actualHash .. ", expected " .. step.expectedSourceHash)
			end
			updateScriptSource(existing, step.source)
			if step.backupPath then
				table.insert(result.backups, { path = safeFullName(existing), backupPath = step.backupPath })
			end
			return finish("updated", "writeScript", existing)
		end
	end

	if existing and step.overwrite ~= true then
		return finish("skipped", "exists", existing)
	end

	local parent, name, parentErr = getParentAndName(path, true)
	if not parent then
		return finish("failed", "missingParent", nil, parentErr)
	end

	local instance = existing
	if not instance then
		local ok, createdOrErr = pcall(function()
			return Instance.new(className)
		end)
		if not ok then
			return finish("failed", "invalidClass", nil, tostring(createdOrErr))
		end
		instance = createdOrErr
		instance.Name = name
		instance.Parent = parent
	end

	if stepType == "writeScript" then
		updateScriptSource(instance, step.source or "")
	elseif step.properties then
		local failures = setProperties(instance, step.properties)
		for _, failure in ipairs(failures) do
			table.insert(result.warnings, tostring(path) .. ": " .. failure)
		end
	end

	if existing then
		return finish("updated", stepType, instance)
	end
	return finish("created", stepType, instance)
end

function applyBuildPlan(payload)
	local validation = validateBlueprint(payload)
	local blueprint = normalizeBlueprint(payload)
	if not validation.valid then
		error("Invalid blueprint: " .. table.concat(validation.errors, "; "))
	end

	return withUndo("ApplyBuildPlan", function()
		local result = {
			name = blueprint.name or "",
			appliedAt = isoNow(),
			created = {},
			updated = {},
			skipped = {},
			failed = {},
			warnings = validation.warnings or {},
			backups = {},
			steps = {},
		}

		for index, step in ipairs(blueprint.steps or {}) do
			local ok, stepResult = pcall(function()
				return applyBlueprintStep(step, index, result)
			end)
			if not ok then
				local failed = {
					index = index,
					type = tostring(step.type or ""),
					path = step.path,
					status = "failed",
					action = "exception",
					message = tostring(stepResult),
				}
				table.insert(result.steps, failed)
				table.insert(result.failed, failed)
			end
		end

		result.summary = {
			created = #result.created,
			updated = #result.updated,
			skipped = #result.skipped,
			failed = #result.failed,
			warnings = #result.warnings,
			backups = #result.backups,
		}
		State.buildStatus = result
		stateDirty = true
		return result
	end)
end

local function applyTestScenario(payload)
	local blueprint = normalizeBlueprint(payload)
	if not blueprint then
		error("applyTestScenario requires a blueprint, buildPlan, or steps payload.")
	end
	if type(blueprint.name) ~= "string" or blueprint.name == "" then
		blueprint.name = "Ruleforge Test Scenario"
	end
	local result = applyBuildPlan({ blueprint = blueprint })
	result.scenario = tostring(payload.scenario or blueprint.name)
	result.kind = "testScenario"
	return result
end

function V6.applyRemoteRepairPlan(payload)
	payload = payload or {}
	local doctor = V6.diagnoseRemoteSystem(payload.diagnostics or payload.remotePayload or {})
	local blueprint = normalizeBlueprint(payload)
	if not blueprint then
		blueprint = doctor.repairBlueprint
	end
	if not blueprint then
		error("applyRemoteRepairPlan could not build a repair blueprint.")
	end
	if type(blueprint.name) ~= "string" or blueprint.name == "" then
		blueprint.name = "Ruleforge Remote Repair"
	end
	local result = applyBuildPlan({ blueprint = blueprint })
	result.kind = "remoteRepairPlan"
	result.remoteDoctor = {
		missingBefore = doctor.comparison and doctor.comparison.missingFromEdit or {},
		missingBeforeCount = doctor.comparison and doctor.comparison.missingFromEditCount or 0,
		mismatchedBeforeCount = doctor.comparison and doctor.comparison.mismatchedCount or 0,
	}
	return result
end

function V6.applyScenario(payload)
	payload = payload or {}
	local blueprint = normalizeBlueprint(payload)
	if not blueprint then
		error("applyScenario requires a blueprint, buildPlan, or steps payload.")
	end
	if type(blueprint.name) ~= "string" or blueprint.name == "" then
		blueprint.name = tostring(payload.scenario or "Ruleforge Scenario")
	end
	local result = applyBuildPlan({ blueprint = blueprint })
	result.scenario = tostring(payload.scenario or payload.name or blueprint.name)
	result.kind = "scenario"
	return result
end

function V7.applyProjectPlan(payload)
	payload = payload or {}
	local blueprint = normalizeBlueprint(payload)
	if not blueprint then
		error("applyProjectPlan requires a blueprint, buildPlan, or steps payload.")
	end
	if type(blueprint.name) ~= "string" or blueprint.name == "" then
		blueprint.name = tostring(payload.template and payload.template.title or "Project Plan")
	end
	local result = applyBuildPlan({ blueprint = blueprint })
	result.kind = "projectPlan"
	result.profile = V7.profileSummary(V7.profileFromPayload(payload))
	if payload.template then
		result.template = payload.template
	end
	return result
end

function V7.applyProjectScenario(payload)
	payload = payload or {}
	local blueprint = normalizeBlueprint(payload)
	if not blueprint then
		error("applyProjectScenario requires a blueprint, buildPlan, or steps payload.")
	end
	if type(blueprint.name) ~= "string" or blueprint.name == "" then
		blueprint.name = tostring(payload.scenario or "Project Scenario")
	end
	local result = applyBuildPlan({ blueprint = blueprint })
	result.kind = "projectScenario"
	result.profile = V7.profileSummary(V7.profileFromPayload(payload))
	result.scenario = tostring(payload.scenario or payload.name or blueprint.name)
	return result
end

V15.last = {}

function V15.array(value)
	if type(value) == "table" then
		return value
	end
	return {}
end

function V15.clone(value)
	if type(value) ~= "table" then
		return value
	end
	local copy = {}
	for key, item in pairs(value) do
		copy[key] = V15.clone(item)
	end
	return copy
end

function V15.profile(payload)
	return V7.profileFromPayload(payload or {})
end

function V15.profileId(profile)
	return tostring((profile or {}).id or "universal")
end

function V15.featureId(feature)
	return tostring((feature or {}).id or (feature or {}).featureId or "")
end

