function V15.mergeTemplates(payload)
	payload = payload or {}
	local templates = {}
	local seen = {}
	local function add(template, source)
		if type(template) ~= "table" then
			return
		end
		local id = V15.featureId(template)
		if id == "" or seen[id] then
			return
		end
		if source == "profile" and type(template.contract) ~= "table" and type(template.blueprint) ~= "table" and type(template.steps) ~= "table" then
			return
		end
		local copy = V15.clone(template)
		copy.id = id
		copy.source = copy.source or source
		seen[id] = true
		table.insert(templates, copy)
	end
	for _, template in ipairs(V15.array(payload.systemTemplates or payload.featureTemplates or payload.features)) do
		add(template, "payload")
	end
	local profile = V15.profile(payload)
	for _, template in ipairs(V15.array(profile.gameplaySystems)) do
		add(template, "profile")
	end
	for _, template in ipairs(V15.array(profile.featureTemplates)) do
		add(template, "profile")
	end
	for _, template in ipairs(V15.defaultTemplates()) do
		add(template, "builtin")
	end
	table.sort(templates, function(a, b)
		return tostring(a.id) < tostring(b.id)
	end)
	return templates
end

function V15.templateAllowedForProfile(template, profileId)
	local profileIds = V15.array(template.profileIds)
	if #profileIds == 0 then
		return true
	end
	for _, id in ipairs(profileIds) do
		local text = tostring(id)
		if text == profileId or text == "universal" then
			return true
		end
	end
	return false
end

function V15.contract(template)
	return type((template or {}).contract) == "table" and template.contract or {}
end

function V15.findTemplate(payload)
	local templates = V15.mergeTemplates(payload or {})
	local requested = tostring((payload or {}).featureId or (payload or {}).feature or (payload or {}).id or (payload or {}).name or "")
	if requested == "" then
		local profile = V15.profile(payload or {})
		for _, id in ipairs(V15.array(profile.featurePriorities)) do
			if tostring(id) ~= "" then
				requested = tostring(id)
				break
			end
		end
	end
	for _, template in ipairs(templates) do
		if V15.featureId(template) == requested then
			return template, templates
		end
	end
	return templates[1], templates
end

function V15.remoteExists(remote)
	local remotesFolder = resolvePath("ReplicatedStorage.Remotes")
	if not remotesFolder then
		return false, nil
	end
	local name = type(remote) == "table" and tostring(remote.name or remote.path or "") or tostring(remote or "")
	local child = remotesFolder:FindFirstChild(name)
	return child ~= nil, child
end

function V15.pathStatus(path)
	local instance = resolvePath(path)
	return {
		path = tostring(path or ""),
		exists = instance ~= nil,
		className = instance and instance.ClassName or nil,
		id = instance and getInstanceId(instance) or nil,
	}
end

function V15.contractStatus(template)
	local contract = V15.contract(template)
	local status = {
		featureId = V15.featureId(template),
		title = tostring(template.title or template.name or V15.featureId(template)),
		folders = {},
		remotes = {},
		scripts = {},
		ui = {},
		world = {},
		tests = V15.array(contract.tests),
		missing = {},
		presentCount = 0,
		requiredCount = 0,
	}
	local function addPathGroup(key, paths)
		for _, path in ipairs(V15.array(paths)) do
			local item = V15.pathStatus(path)
			table.insert(status[key], item)
			status.requiredCount += 1
			if item.exists then
				status.presentCount += 1
			else
				table.insert(status.missing, { kind = key, path = tostring(path) })
			end
		end
	end
	addPathGroup("folders", contract.folders)
	addPathGroup("scripts", contract.scripts)
	addPathGroup("ui", contract.ui)
	addPathGroup("world", contract.world)
	for _, remote in ipairs(V15.array(contract.remotes)) do
		local exists, instance = V15.remoteExists(remote)
		local item = {
			name = type(remote) == "table" and tostring(remote.name or remote.path or "") or tostring(remote or ""),
			className = type(remote) == "table" and tostring(remote.className or "RemoteEvent") or "RemoteEvent",
			direction = type(remote) == "table" and tostring(remote.direction or "") or "",
			exists = exists,
			actualClassName = instance and instance.ClassName or nil,
			path = instance and safeFullName(instance) or ("ReplicatedStorage.Remotes." .. (type(remote) == "table" and tostring(remote.name or "") or tostring(remote or ""))),
		}
		table.insert(status.remotes, item)
		status.requiredCount += 1
		if exists and (item.className == "" or not instance or instance.ClassName == item.className) then
			status.presentCount += 1
		else
			table.insert(status.missing, { kind = "remotes", path = item.path, name = item.name, className = item.className })
		end
	end
	status.missingCount = #status.missing
	status.coverage = status.requiredCount > 0 and math.floor((status.presentCount / status.requiredCount) * 100 + 0.5) or 100
	return status
end

function V15.defaultBlueprintForFeature(template, profile)
	local id = V15.featureId(template)
	local title = tostring(template.title or id)
	local safeName = id:gsub("[^%w_]", "")
	if safeName == "" then
		safeName = "Feature"
	end
	local draftUiRoot = V15.profileId(profile) == "ruleforge" and "StarterGui.UIRoot.CodexDirectorHUD" or "StarterGui.CodexDirectorHUD"
	local steps = {
		{ type = "ensureFolder", path = "ReplicatedStorage.CodexSystems" },
		{ type = "ensureFolder", path = "ReplicatedStorage.CodexSystems." .. safeName },
		{ type = "ensureFolder", path = "ServerScriptService.CodexSystems" },
		{ type = "ensureFolder", path = "ServerScriptService.CodexSystems." .. safeName },
		{ type = "ensureFolder", path = draftUiRoot },
		{
			type = "writeScript",
			className = "ModuleScript",
			path = "ReplicatedStorage.CodexSystems." .. safeName .. ".Contract",
			source = "local Contract = {}\n\nContract.id = " .. string.format("%q", id) .. "\nContract.title = " .. string.format("%q", title) .. "\nContract.generatedBy = \"Codex Studio Bridge V15\"\n\nreturn Contract\n",
		},
	}
	for _, remote in ipairs(V15.array(V15.contract(template).remotes)) do
		local className = type(remote) == "table" and tostring(remote.className or "RemoteEvent") or "RemoteEvent"
		local name = type(remote) == "table" and tostring(remote.name or "") or tostring(remote or "")
		if name ~= "" then
			table.insert(steps, { type = className == "RemoteFunction" and "ensureRemoteFunction" or "ensureRemoteEvent", path = "ReplicatedStorage.Remotes." .. name })
		end
	end
	return {
		name = title .. " Feature Plan",
		mode = "supervised",
		source = "V15.defaultBlueprintForFeature",
		steps = steps,
	}
end

function V15.blueprintForTemplate(template, profile)
	if type(template.blueprint) == "table" then
		return V15.clone(template.blueprint)
	end
	if type(template.steps) == "table" then
		return {
			name = tostring(template.title or template.id or "Gameplay Feature") .. " Feature Plan",
			mode = "supervised",
			source = "V15.templateSteps",
			steps = V15.clone(template.steps),
		}
	end
	return V15.defaultBlueprintForFeature(template, profile)
end

function V15.patchSetForTemplate(template)
	if type(template.patchSet) == "table" then
		return V15.clone(template.patchSet)
	end
	if type(template.patches) == "table" then
		return { summary = tostring(template.title or template.id or "Gameplay feature patches"), patches = V15.clone(template.patches) }
	end
	return { summary = tostring(template.title or template.id or "Gameplay feature patches"), patches = {} }
end

function V15.getGameplaySystemCatalog(payload)
	payload = payload or {}
	local profile = V15.profile(payload)
	local profileId = V15.profileId(profile)
	local templates = {}
	for _, template in ipairs(V15.mergeTemplates(payload)) do
		table.insert(templates, {
			id = V15.featureId(template),
			title = tostring(template.title or template.name or V15.featureId(template)),
			genre = tostring(template.genre or ""),
			description = tostring(template.description or ""),
			source = tostring(template.source or ""),
			profileIds = V15.array(template.profileIds),
			loopStages = V15.array(template.loopStages),
			allowedForActiveProfile = V15.templateAllowedForProfile(template, profileId),
			previewCommand = "tools/bridge.cmd feature preview " .. V15.featureId(template),
			applyCommand = "tools/bridge.cmd feature apply " .. V15.featureId(template),
		})
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		profile = V7.profileSummary(profile),
		recommendedFeature = "reward-replay",
		count = #templates,
		templates = templates,
	}
	State.gameplaySystemCatalog = result
	return result
end

function V15.getGameplaySystemMap(payload)
	payload = payload or {}
	local profile = V15.profile(payload)
	local templates = V15.mergeTemplates(payload)
	local scriptMapOk, scriptMap = pcall(function()
		return V12.getScriptMap(payload)
	end)
	local remoteMapOk, remoteMap = pcall(function()
		return V12.getRemoteUsageMap(payload)
	end)
	local uiOk, uiFlow = pcall(function()
		return V11.getUiGameFlowReport(payload)
	end)
	local worldOk, landmarks = pcall(function()
		return V14.getWorldLandmarkReport(payload)
	end)
	local scenarioOk, scenarios = pcall(function()
		return V7.getProjectScenarioCatalog(payload)
	end)
	local features = {}
	for _, template in ipairs(templates) do
		if V15.templateAllowedForProfile(template, V15.profileId(profile)) then
			table.insert(features, V15.contractStatus(template))
		end
	end
	table.sort(features, function(a, b)
		if a.missingCount == b.missingCount then
			return tostring(a.featureId) < tostring(b.featureId)
		end
		return a.missingCount < b.missingCount
	end)
	local result = {
		at = isoNow(),
		version = VERSION,
		profile = V7.profileSummary(profile),
		summary = {
			scripts = scriptMapOk and scriptMap.summary and scriptMap.summary.total or (scriptMapOk and scriptMap.total or nil),
			remotesActual = remoteMapOk and remoteMap.actualCount or nil,
			remotesExpected = remoteMapOk and remoteMap.expectedCount or nil,
			uiMissingFlowStates = uiOk and uiFlow.missingFlowStates or {},
			worldMissingLandmarks = worldOk and landmarks.summary and landmarks.summary.missing or nil,
			scenarioCount = scenarioOk and scenarios.count or nil,
			featureCount = #features,
		},
		features = features,
		inputs = {
			scriptMapAvailable = scriptMapOk,
			remoteMapAvailable = remoteMapOk,
			uiFlowAvailable = uiOk,
			worldLandmarksAvailable = worldOk,
			scenarioCatalogAvailable = scenarioOk,
		},
	}
	State.gameplaySystemMap = result
	return result
end

function V15.getFeatureContractReport(payload)
	payload = payload or {}
	local template, templates = V15.findTemplate(payload)
	if not template then
		error("No gameplay feature template is available.")
	end
	local status = V15.contractStatus(template)
	return {
		at = isoNow(),
		version = VERSION,
		profile = V7.profileSummary(V15.profile(payload)),
		feature = {
			id = V15.featureId(template),
			title = tostring(template.title or template.name or V15.featureId(template)),
			genre = tostring(template.genre or ""),
			description = tostring(template.description or ""),
			loopStages = V15.array(template.loopStages),
		},
		contract = V15.contract(template),
		status = status,
		availableFeatureCount = #templates,
	}
end

function V15.getGameplayFeaturePlan(payload)
	payload = payload or {}
	local profile = V15.profile(payload)
	local template = V15.findTemplate(payload)
	if not template then
		error("No gameplay feature template is available.")
	end
	local blueprint = normalizeBlueprint(payload) or V15.blueprintForTemplate(template, profile)
	local patchSet = type(payload.patchSet) == "table" and payload.patchSet or V15.patchSetForTemplate(template)
	local preview = previewBuildPlan({ blueprint = blueprint })
	local contractReport = V15.getFeatureContractReport({
		profile = profile,
		systemTemplates = { template },
		featureId = V15.featureId(template),
	})
	local bundle = {
		featureId = V15.featureId(template),
		title = tostring(template.title or template.name or V15.featureId(template)),
		blueprint = blueprint,
		patchSet = patchSet,
		contract = V15.contract(template),
		verification = template.verification or { checks = V15.array(V15.contract(template).tests) },
		ownedRoots = V15.array(template.ownedRoots),
		protectedPaths = V15.array(template.protectedPaths),
	}
	local result = {
		at = isoNow(),
		version = VERSION,
		profile = V7.profileSummary(profile),
		feature = {
			id = bundle.featureId,
			title = bundle.title,
			genre = tostring(template.genre or ""),
			description = tostring(template.description or ""),
		},
		bundle = bundle,
		blueprint = blueprint,
		patchSetPreview = {
			summary = patchSet.summary,
			patchCount = type(patchSet.patches) == "table" and #patchSet.patches or 0,
		},
		preview = preview,
		contract = contractReport,
		approvalRequired = true,
	}
	State.gameplayFeaturePlan = result
	return result
end

function V15.validateGameplayFeaturePlan(payload)
	local plan = V15.getGameplayFeaturePlan(payload or {})
	local warnings = {}
	local protected = {}
	for _, path in ipairs(V15.array(plan.bundle.protectedPaths)) do
		protected[tostring(path)] = true
	end
	for _, step in ipairs(V15.array(plan.blueprint.steps)) do
		local path = tostring(step.path or "")
		if protected[path] then
			table.insert(warnings, "Blueprint targets protected path directly: " .. path)
		end
	end
	local patchCount = plan.patchSetPreview.patchCount or 0
	return {
		at = isoNow(),
		version = VERSION,
		valid = plan.preview.valid and #warnings == 0,
		feature = plan.feature,
		blueprint = plan.preview,
		patchCount = patchCount,
		warnings = warnings,
		queued = false,
		approvalRequired = true,
	}
end

function V15.getGameplayLoopMatrix(payload)
	payload = payload or {}
	local map = V15.getGameplaySystemMap(payload)
	local stages = { "menu", "lobby", "spawn", "start", "objective", "extraction", "fail", "reward", "replay", "feedback" }
	local rows = {}
	for _, stage in ipairs(stages) do
		local row = { stage = stage, features = {}, covered = false }
		for _, feature in ipairs(V15.mergeTemplates(payload)) do
			for _, featureStage in ipairs(V15.array(feature.loopStages)) do
				if tostring(featureStage) == stage then
					table.insert(row.features, V15.featureId(feature))
					row.covered = true
					break
				end
			end
		end
		table.insert(rows, row)
	end
	return {
		at = isoNow(),
		version = VERSION,
		profile = map.profile,
		rows = rows,
		systemSummary = map.summary,
	}
end

function V15.getSystemTestPlan(payload)
	local contract = V15.getFeatureContractReport(payload or {})
	local checks = {}
	for _, test in ipairs(V15.array(contract.contract.tests)) do
		table.insert(checks, { type = "manual", description = tostring(test), status = "planned" })
	end
	for _, remote in ipairs(V15.array(contract.status.remotes)) do
		table.insert(checks, { type = "remote", target = remote.path, description = "Verify remote exists: " .. tostring(remote.name), status = remote.exists and "ready" or "missing" })
	end
	for _, folder in ipairs(V15.array(contract.status.folders)) do
		table.insert(checks, { type = "path", target = folder.path, description = "Verify folder exists: " .. tostring(folder.path), status = folder.exists and "ready" or "missing" })
	end
	return {
		at = isoNow(),
		version = VERSION,
		profile = contract.profile,
		feature = contract.feature,
		checks = checks,
		checkCount = #checks,
		harness = {
			installCommand = "tools/bridge.cmd systems harness install",
			removeCommand = "tools/bridge.cmd systems harness remove",
			approvalRequired = true,
		},
	}
end

function V15.getSystemForgeReport(payload)
	payload = payload or {}
	local profile = V15.profile(payload)
	local map = V15.getGameplaySystemMap(payload)
	local loopOk, loopReport = pcall(function()
		return V10.getGameLoopReport(payload)
	end)
	local recommendation = "reward-replay"
	if loopOk and type(loopReport.missingPieces) == "table" then
		for _, piece in ipairs(loopReport.missingPieces) do
			if tostring(piece) == "replay" or tostring(piece) == "reward" then
				recommendation = "reward-replay"
				break
			end
		end
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		profile = V7.profileSummary(profile),
		recommendedFeature = recommendation,
		nextAction = "Preview gameplay feature plan: " .. recommendation,
		systemMap = {
			summary = map.summary,
			topFeatures = { map.features[1], map.features[2], map.features[3] },
		},
		gameLoop = loopOk and {
			missingPieces = loopReport.missingPieces or {},
			readyPieces = loopReport.readyPieces or {},
		} or nil,
	}
	State.systemForgeReport = result
	return result
end

function V15.verifyPatchSet(patches)
	local prepared = {}
	for index, patch in ipairs(V15.array(patches)) do
		if type(patch) ~= "table" then
			error("Patch " .. tostring(index) .. " must be a table.")
		end
		if type(patch.newSource) ~= "string" then
			error("Patch " .. tostring(index) .. " requires newSource.")
		end
		local instance = resolveInstance(patch.scriptId or patch.instanceId or patch.targetId or patch.path or patch.target)
		if not instance or not instance:IsA("LuaSourceContainer") then
			error("Patch " .. tostring(index) .. " target script was not found.")
		end
		local currentSource = readScriptSource(instance)
		local actualHash = sourceHash(currentSource)
		local expectedHash = tostring(patch.expectedSourceHash or "")
		if expectedHash == "" then
			error("Patch " .. tostring(index) .. " requires expectedSourceHash.")
		end
		if actualHash:lower() ~= expectedHash:lower() then
			error("Stale gameplay feature patch rejected for " .. safeFullName(instance) .. ". Current source hash is " .. actualHash .. ", expected " .. expectedHash .. ".")
		end
		table.insert(prepared, {
			instance = instance,
			currentSource = currentSource,
			actualHash = actualHash,
			patch = patch,
		})
	end
	return prepared
end

function V15.applyBlueprintInsideUndo(blueprint)
	local validation = validateBlueprint({ blueprint = blueprint })
	if not validation.valid then
		error("Invalid gameplay feature blueprint: " .. table.concat(validation.errors, "; "))
	end
	local result = {
		name = blueprint.name or "",
		appliedAt = isoNow(),
		created = {},
		updated = {},
		skipped = {},
		failed = {},
		warnings = validation.warnings or {},
		backups = {},
		steps = {},
	}
	for index, step in ipairs(blueprint.steps or {}) do
		local ok, stepResult = pcall(function()
			return applyBlueprintStep(step, index, result)
		end)
		if not ok then
			local failed = {
				index = index,
				type = tostring(step.type or ""),
				path = step.path,
				status = "failed",
				action = "exception",
				message = tostring(stepResult),
			}
			table.insert(result.steps, failed)
			table.insert(result.failed, failed)
		end
	end
	result.summary = {
		created = #result.created,
		updated = #result.updated,
		skipped = #result.skipped,
		failed = #result.failed,
		warnings = #result.warnings,
		backups = #result.backups,
	}
	State.buildStatus = result
	return result
end

function V15.applyGameplayFeaturePlan(payload)
	payload = payload or {}
	local plan = type(payload.bundle) == "table" and payload.bundle or type(payload.plan) == "table" and payload.plan or V15.getGameplayFeaturePlan(payload).bundle
	local blueprint = normalizeBlueprint(plan) or plan.blueprint
	if type(blueprint) ~= "table" then
		error("applyGameplayFeaturePlan requires a blueprint in the feature bundle.")
	end
	local patchSet = type(plan.patchSet) == "table" and plan.patchSet or type(payload.patchSet) == "table" and payload.patchSet or { patches = {} }
	local validation = validateBlueprint({ blueprint = blueprint })
	if not validation.valid then
		error("Invalid gameplay feature blueprint: " .. table.concat(validation.errors, "; "))
	end
	return withUndo("ApplyGameplayFeaturePlan", function()
		local preparedPatches = V15.verifyPatchSet(patchSet.patches or {})
		local appliedPatches = {}
		for _, item in ipairs(preparedPatches) do
			updateScriptSource(item.instance, item.patch.newSource)
			table.insert(appliedPatches, {
				id = getInstanceId(item.instance),
				path = safeFullName(item.instance),
				summary = item.patch.summary or "",
				backupPath = item.patch.backupPath or "",
				oldSourceHash = item.actualHash,
				newSourceHash = sourceHash(item.patch.newSource),
				diff = item.patch.diff or {
					oldLineCount = countLines(item.currentSource),
					newLineCount = countLines(item.patch.newSource),
					changedLineCount = changedLineCount(item.currentSource, item.patch.newSource),
				},
			})
		end
		local build = V15.applyBlueprintInsideUndo(blueprint)
		stateDirty = true
		return {
			at = isoNow(),
			version = VERSION,
			kind = "gameplayFeaturePlan",
			featureId = tostring(plan.featureId or payload.featureId or payload.feature or ""),
			title = tostring(plan.title or blueprint.name or "Gameplay Feature"),
			build = build,
			appliedPatches = appliedPatches,
			patchCount = #appliedPatches,
			backups = patchSet.backups or payload.backups or {},
			verification = plan.verification,
			summary = {
				created = build.summary.created,
				updated = build.summary.updated,
				skipped = build.summary.skipped,
				failed = build.summary.failed,
				patches = #appliedPatches,
				warnings = build.summary.warnings,
			},
		}
	end)
end

