function V15.applySystemTestHarness(payload)
	local blueprint = normalizeBlueprint(payload or {}) or V15.systemHarnessBlueprint(payload or {})
	local result = applyBuildPlan({ blueprint = blueprint })
	result.kind = "systemTestHarness"
	return result
end

function V15.removeSystemTestHarness(payload)
	local paths = {
		"ReplicatedStorage.CodexSystemHarness",
		"ServerScriptService.CodexSystemHarness",
		"Workspace.CodexSystemHarness",
	}
	return withUndo("RemoveSystemTestHarness", function()
		local removed = {}
		local skipped = {}
		for _, path in ipairs(paths) do
			local instance = resolvePath(path)
			if instance then
				table.insert(removed, { path = safeFullName(instance), className = instance.ClassName })
				instance:Destroy()
			else
				table.insert(skipped, { path = path, reason = "missing" })
			end
		end
		stateDirty = true
		return {
			at = isoNow(),
			version = VERSION,
			kind = "removeSystemTestHarness",
			removed = removed,
			skipped = skipped,
			summary = {
				removed = #removed,
				skipped = #skipped,
			},
		}
	end)
end

