function V16.milestoneAllowedForProfile(milestone, profileId)
	local profileIds = V16.array(milestone.profileIds)
	if #profileIds == 0 then
		return true
	end
	for _, id in ipairs(profileIds) do
		local text = tostring(id)
		if text == profileId or text == "universal" then
			return true
		end
	end
	return false
end

function V16.mergeMilestones(payload)
	payload = payload or {}
	local milestones = {}
	local seen = {}
	local function add(milestone, source)
		if type(milestone) ~= "table" then
			return
		end
		local id = V16.milestoneId(milestone)
		if id == "" then
			return
		end
		if seen[id] then
			local existing = seen[id]
			for key, value in pairs(milestone) do
				if existing[key] == nil then
					existing[key] = V16.clone(value)
				end
			end
			return
		end
		local copy = V16.clone(milestone)
		copy.id = id
		copy.source = copy.source or source
		seen[id] = copy
		table.insert(milestones, copy)
	end
	for _, milestone in ipairs(V16.array(payload.milestones or payload.milestoneTemplates)) do
		add(milestone, "payload")
	end
	local profile = V16.profile(payload)
	for _, milestone in ipairs(V16.array(profile.milestones)) do
		add(milestone, "profile")
	end
	for _, milestone in ipairs(V16.defaultMilestones()) do
		add(milestone, "builtin")
	end
	table.sort(milestones, function(a, b)
		local aPriority = tonumber(a.priority) or 100
		local bPriority = tonumber(b.priority) or 100
		if aPriority == bPriority then
			return tostring(a.id) < tostring(b.id)
		end
		return aPriority < bPriority
	end)
	return milestones
end

function V16.findMilestone(payload)
	payload = payload or {}
	local milestones = V16.mergeMilestones(payload)
	local requested = tostring(payload.milestoneId or payload.id or payload.name or "")
	if requested == "" and type(payload.milestone) == "table" then
		requested = V16.milestoneId(payload.milestone)
	elseif requested == "" then
		requested = tostring(payload.milestone or "")
	end
	local profile = V16.profile(payload)
	local profileId = V16.profileId(profile)
	if requested == "" then
		requested = tostring(payload.defaultMilestoneId or "prototype-core-loop")
	end
	if requested ~= "" then
		for _, milestone in ipairs(milestones) do
			if V16.milestoneId(milestone) == requested then
				return milestone, milestones
			end
		end
	end
	for _, milestone in ipairs(milestones) do
		if V16.milestoneAllowedForProfile(milestone, profileId) then
			return milestone, milestones
		end
	end
	return milestones[1], milestones
end

function V16.outputSummary()
	local errors = 0
	local warnings = 0
	local recent = {}
	for index = #outputBuffer, math.max(1, #outputBuffer - 49), -1 do
		local message = outputBuffer[index]
		if message then
			local kind = tostring(message.type or "")
			local text = tostring(message.message or "")
			if kind == "Error" or text:lower():find("error", 1, true) then
				errors += 1
			elseif kind == "Warning" or text:lower():find("warn", 1, true) then
				warnings += 1
			end
			table.insert(recent, 1, {
				at = message.at,
				type = message.type,
				message = V9.trimText(text, 180),
				source = message.source,
			})
		end
	end
	return {
		totalBuffered = #outputBuffer,
		errorCount = errors,
		warningCount = warnings,
		recent = recent,
	}
end

function V16.contractChecks(contract)
	local checks = {}
	local function addPaths(paths, kind)
		for _, path in ipairs(V16.array(paths)) do
			table.insert(checks, {
				type = "path",
				path = tostring(path),
				kind = kind,
				label = "Required " .. kind .. ": " .. tostring(path),
			})
		end
	end
	addPaths(contract.folders, "folder")
	addPaths(contract.scripts, "script")
	addPaths(contract.ui, "ui")
	addPaths(contract.world, "world")
	for _, remote in ipairs(V16.array(contract.remotes)) do
		local name = type(remote) == "table" and tostring(remote.name or remote.path or "") or tostring(remote)
		if name ~= "" then
			table.insert(checks, {
				type = "remote",
				name = name,
				className = type(remote) == "table" and tostring(remote.className or "RemoteEvent") or "RemoteEvent",
				label = "Required remote: " .. name,
			})
		end
	end
	return checks
end

function V16.checksForMilestone(milestone, featurePlan)
	local checks = {}
	for _, check in ipairs(V16.array(milestone.checks)) do
		table.insert(checks, V16.clone(check))
	end
	if featurePlan and featurePlan.bundle and type(featurePlan.bundle.contract) == "table" then
		for _, check in ipairs(V16.contractChecks(featurePlan.bundle.contract)) do
			table.insert(checks, check)
		end
	end
	local hasOutputCheck = false
	local hasScoreCheck = false
	for _, check in ipairs(checks) do
		if tostring(check.type) == "outputErrors" then
			hasOutputCheck = true
		elseif tostring(check.type) == "projectScore" then
			hasScoreCheck = true
		end
	end
	local regression = type(milestone.regression) == "table" and milestone.regression or {}
	if not hasOutputCheck then
		table.insert(checks, { type = "outputErrors", maxNewErrors = 0, label = "No new Output errors" })
	end
	if not hasScoreCheck and regression.minProjectScore then
		table.insert(checks, { type = "projectScore", minScore = regression.minProjectScore, maxDrop = regression.maxScoreDrop or 5, label = "Project score does not regress" })
	end
	return checks
end

function V16.evaluateCheck(check, baseline)
	baseline = baseline or {}
	local checkType = tostring((check or {}).type or "path")
	if checkType == "path" then
		local path = tostring(check.path or check.target or "")
		local instance = resolvePath(path)
		local expectedClass = tostring(check.className or "")
		local passed = instance ~= nil and (expectedClass == "" or instance.ClassName == expectedClass)
		return {
			type = checkType,
			label = tostring(check.label or path),
			target = path,
			expectedClassName = expectedClass ~= "" and expectedClass or nil,
			actualClassName = instance and instance.ClassName or nil,
			passed = passed,
			status = passed and "passed" or "failed",
			message = passed and "Path exists." or "Path is missing or class does not match.",
		}
	end
	if checkType == "remote" then
		local name = tostring(check.name or check.path or check.target or "")
		local expectedClass = tostring(check.className or "RemoteEvent")
		local remotesFolder = resolvePath("ReplicatedStorage.Remotes")
		local instance = remotesFolder and remotesFolder:FindFirstChild(name) or nil
		local passed = instance ~= nil and (expectedClass == "" or instance.ClassName == expectedClass)
		return {
			type = checkType,
			label = tostring(check.label or name),
			target = "ReplicatedStorage.Remotes." .. name,
			expectedClassName = expectedClass,
			actualClassName = instance and instance.ClassName or nil,
			passed = passed,
			status = passed and "passed" or "failed",
			message = passed and "Remote exists." or "Remote is missing or class does not match.",
		}
	end
	if checkType == "outputErrors" then
		local summary = V16.outputSummary()
		local baselineErrors = baseline.output and tonumber(baseline.output.errorCount) or summary.errorCount
		local maxNew = tonumber(check.maxNewErrors) or 0
		local newErrors = math.max(0, summary.errorCount - baselineErrors)
		local passed = newErrors <= maxNew
		return {
			type = checkType,
			label = tostring(check.label or "Output errors"),
			passed = passed,
			status = passed and "passed" or "failed",
			errorCount = summary.errorCount,
			baselineErrorCount = baselineErrors,
			newErrors = newErrors,
			maxNewErrors = maxNew,
			message = passed and "No unexpected new Output errors." or "Output has new errors.",
		}
	end
	if checkType == "projectScore" then
		local healthPayload = baseline.payload or { profile = baseline.profile or {} }
		local ok, health = pcall(function()
			return V7.getProjectHealthScore(healthPayload)
		end)
		local score = ok and tonumber(health.score) or nil
		local baselineScore = baseline.projectHealth and tonumber(baseline.projectHealth.score) or score
		local minScore = tonumber(check.minScore) or 0
		local maxDrop = tonumber(check.maxDrop) or 999
		local passed = score ~= nil and score >= minScore and (baselineScore == nil or score >= baselineScore - maxDrop)
		return {
			type = checkType,
			label = tostring(check.label or "Project score"),
			passed = passed,
			status = passed and "passed" or "failed",
			score = score,
			baselineScore = baselineScore,
			minScore = minScore,
			maxDrop = maxDrop,
			message = passed and "Project score is within the expected range." or "Project score regressed or is below the required minimum.",
		}
	end
	return {
		type = checkType,
		label = tostring(check.label or checkType),
		passed = true,
		status = "informational",
		message = "Informational/manual check.",
	}
end

function V16.evaluateChecks(checks, baseline)
	local results = {}
	local passed = 0
	local failed = 0
	for _, check in ipairs(V16.array(checks)) do
		local ok, result = pcall(function()
			return V16.evaluateCheck(check, baseline)
		end)
		if not ok then
			result = {
				type = tostring((check or {}).type or "unknown"),
				label = tostring((check or {}).label or "Check"),
				passed = false,
				status = "failed",
				message = tostring(result),
			}
		end
		if result.passed then
			passed += 1
		else
			failed += 1
		end
		table.insert(results, result)
	end
	return {
		checks = results,
		summary = {
			total = #results,
			passed = passed,
			failed = failed,
			status = failed == 0 and "passed" or "failed",
		},
	}
end

function V16.getMilestoneCatalog(payload)
	payload = payload or {}
	local profile = V16.profile(payload)
	local profileId = V16.profileId(profile)
	local milestones = {}
	for _, milestone in ipairs(V16.mergeMilestones(payload)) do
		table.insert(milestones, {
			id = V16.milestoneId(milestone),
			title = tostring(milestone.title or milestone.name or V16.milestoneId(milestone)),
			description = tostring(milestone.description or ""),
			source = tostring(milestone.source or ""),
			profileIds = V16.array(milestone.profileIds),
			featureId = milestone.featureId,
			hasBlueprint = type(milestone.blueprint) == "table",
			acceptance = V16.array(milestone.acceptance),
			allowedForActiveProfile = V16.milestoneAllowedForProfile(milestone, profileId),
			previewCommand = "tools/bridge.cmd milestone preview " .. V16.milestoneId(milestone),
			applyCommand = "tools/bridge.cmd milestone apply " .. V16.milestoneId(milestone),
		})
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		profile = V7.profileSummary(profile),
		recommendedMilestone = "prototype-core-loop",
		note = "Ruleforge milestones are explicit test fixtures; generic milestones stay the default.",
		count = #milestones,
		milestones = milestones,
	}
	V16.last.milestoneCatalog = result
	return result
end

function V16.getMilestonePlan(payload)
	payload = payload or {}
	local milestone = V16.findMilestone(payload)
	if not milestone then
		error("No milestone template is available.")
	end
	local profile = V16.profile(payload)
	local planType = "none"
	local mutation = nil
	local blueprint = nil
	local preview = nil
	local featurePlan = nil
	if milestone.featureId then
		featurePlan = V15.getGameplayFeaturePlan({
			profile = profile,
			activeProfile = profile,
			systemTemplates = payload.systemTemplates,
			featureId = milestone.featureId,
		})
		planType = "gameplayFeature"
		mutation = {
			commandType = "applyGameplayFeaturePlan",
			bundle = featurePlan.bundle,
		}
		blueprint = featurePlan.blueprint
		preview = featurePlan.preview
	elseif type(milestone.blueprint) == "table" then
		planType = "blueprint"
		blueprint = V16.clone(milestone.blueprint)
		preview = previewBuildPlan({ blueprint = blueprint })
		mutation = {
			commandType = "applyBuildPlan",
			blueprint = blueprint,
		}
	else
		preview = { valid = true, warnings = { "Milestone is read-only; no apply plan is defined." }, errors = {}, stepCount = 0 }
	end
	local verificationChecks = V16.checksForMilestone(milestone, featurePlan)
	local result = {
		at = isoNow(),
		version = VERSION,
		profile = V7.profileSummary(profile),
		milestone = {
			id = V16.milestoneId(milestone),
			title = tostring(milestone.title or milestone.name or V16.milestoneId(milestone)),
			description = tostring(milestone.description or ""),
			featureId = milestone.featureId,
			source = tostring(milestone.source or ""),
			acceptance = V16.array(milestone.acceptance),
		},
		planType = planType,
		blueprint = blueprint,
		preview = preview,
		mutation = mutation,
		featurePlan = featurePlan and {
			feature = featurePlan.feature,
			patchSetPreview = featurePlan.patchSetPreview,
			contract = featurePlan.contract,
		} or nil,
		verificationPlan = {
			checks = verificationChecks,
			checkCount = #verificationChecks,
			runCommand = "tools/bridge.cmd verify run " .. V16.milestoneId(milestone),
		},
		approvalRequired = mutation ~= nil,
	}
	V16.last.milestonePlan = result
	return result
end

function V16.validateMilestonePlan(payload)
	local plan = V16.getMilestonePlan(payload or {})
	local valid = true
	local warnings = {}
	if plan.preview and plan.preview.valid == false then
		valid = false
	end
	if not plan.mutation then
		table.insert(warnings, "Milestone has no mutation plan; verification only.")
	end
	return {
		at = isoNow(),
		version = VERSION,
		valid = valid,
		milestone = plan.milestone,
		planType = plan.planType,
		preview = plan.preview,
		verificationPlan = plan.verificationPlan,
		warnings = warnings,
		queued = false,
		approvalRequired = plan.approvalRequired,
	}
end

function V16.getPreflightReport(payload)
	payload = payload or {}
	local plan = V16.getMilestonePlan(payload)
	local output = V16.outputSummary()
	local healthOk, health = pcall(function()
		return V7.getProjectHealthScore(payload)
	end)
	local checks = V16.evaluateChecks(plan.verificationPlan.checks, {
		output = output,
		projectHealth = healthOk and health or nil,
		profile = payload.profile,
		payload = payload,
	})
	local report = {
		at = isoNow(),
		version = VERSION,
		kind = "preflight",
		profile = plan.profile,
		milestone = plan.milestone,
		queuedCommands = #commandOrder,
		output = output,
		projectHealth = healthOk and health or nil,
		preview = plan.preview,
		currentChecks = checks,
		readiness = (plan.preview and plan.preview.valid == false) and "blocked" or "readyForApproval",
		nextCommand = "tools/bridge.cmd milestone apply " .. tostring(plan.milestone.id),
	}
	V16.last.preflightReport = report
	return report
end

function V16.getPostApplyVerificationPlan(payload)
	local plan = V16.getMilestonePlan(payload or {})
	return {
		at = isoNow(),
		version = VERSION,
		milestone = plan.milestone,
		verificationPlan = plan.verificationPlan,
		baseline = payload and payload.baseline or V16.last.preflightReport,
		nextCommand = "tools/bridge.cmd verify run " .. tostring(plan.milestone.id),
	}
end

function V16.runVerificationChecks(payload)
	payload = payload or {}
	local plan = V16.getMilestonePlan(payload)
	local baseline = payload.baseline or V16.last.preflightReport or {}
	if type(baseline) == "table" and not baseline.payload then
		baseline.payload = payload
	end
	local results = V16.evaluateChecks(plan.verificationPlan.checks, baseline)
	local report = {
		at = isoNow(),
		version = VERSION,
		kind = "verification",
		profile = plan.profile,
		milestone = plan.milestone,
		results = results.checks,
		summary = results.summary,
		lastBuildStatus = State.buildStatus and State.buildStatus.summary or nil,
		nextRecommendation = results.summary.failed == 0 and "Run regression report, then continue to the next milestone." or "Review failed checks before applying another build round.",
	}
	V16.last.verificationReport = report
	V16.last.milestoneReport = report
	return report
end

function V16.getRegressionReport(payload)
	payload = payload or {}
	local healthOk, health = pcall(function()
		return V7.getProjectHealthScore(payload)
	end)
	local remotesOk, remotes = pcall(function()
		return getRemoteInventory()
	end)
	local output = V16.outputSummary()
	local score = healthOk and tonumber(health.score) or nil
	local baselineScore = V16.last.preflightReport and V16.last.preflightReport.projectHealth and tonumber(V16.last.preflightReport.projectHealth.score) or score
	local scoreDrop = score and baselineScore and (baselineScore - score) or 0
	local blockers = {}
	if output.errorCount > (V16.last.preflightReport and V16.last.preflightReport.output and V16.last.preflightReport.output.errorCount or output.errorCount) then
		table.insert(blockers, "New Output errors appeared after the last preflight.")
	end
	if score and baselineScore and scoreDrop > 5 then
		table.insert(blockers, "Project score dropped by more than 5 points.")
	end
	local report = {
		at = isoNow(),
		version = VERSION,
		kind = "regression",
		projectHealth = healthOk and health or nil,
		remoteInventory = remotesOk and {
			actualCount = remotes.actualCount,
			expectedCount = remotes.expectedCount,
			missingCount = remotes.missingCount,
		} or nil,
		output = output,
		scoreDrop = scoreDrop,
		blockers = blockers,
		status = #blockers == 0 and "passed" or "failed",
		lastVerification = V16.last.verificationReport and {
			at = V16.last.verificationReport.at,
			milestone = V16.last.verificationReport.milestone,
			summary = V16.last.verificationReport.summary,
		} or nil,
	}
	V16.last.regressionReport = report
	return report
end

function V16.getMilestoneReport(payload)
	payload = payload or {}
	local preflight = V16.getPreflightReport(payload)
	local verification = V16.last.verificationReport
	local regression = V16.getRegressionReport(payload)
	local report = {
		at = isoNow(),
		version = VERSION,
		milestone = preflight.milestone,
		profile = preflight.profile,
		preflight = {
			readiness = preflight.readiness,
			queuedCommands = preflight.queuedCommands,
			currentCheckSummary = preflight.currentChecks.summary,
		},
		verification = verification and {
			at = verification.at,
			summary = verification.summary,
		} or nil,
		regression = {
			status = regression.status,
			blockers = regression.blockers,
			scoreDrop = regression.scoreDrop,
		},
		nextAction = verification and verification.summary and verification.summary.failed == 0 and "Continue to the next milestone." or preflight.nextCommand,
	}
	V16.last.milestoneReport = report
	return report
end

function V16.getBuilderRoundHistory(payload)
	payload = payload or {}
	local memory = type(payload.memory) == "table" and payload.memory or {}
	local history = V16.array(memory.builderRounds or memory.directorRounds)
	local result = {
		at = isoNow(),
		version = VERSION,
		count = #history,
		history = history,
		lastMilestonePlan = V16.last.milestonePlan and {
			at = V16.last.milestonePlan.at,
			milestone = V16.last.milestonePlan.milestone,
			planType = V16.last.milestonePlan.planType,
		} or nil,
		lastVerification = V16.last.verificationReport and {
			at = V16.last.verificationReport.at,
			milestone = V16.last.verificationReport.milestone,
			summary = V16.last.verificationReport.summary,
		} or nil,
		lastRegression = V16.last.regressionReport and {
			at = V16.last.regressionReport.at,
			status = V16.last.regressionReport.status,
			blockers = V16.last.regressionReport.blockers,
		} or nil,
	}
	V16.last.builderRoundHistory = result
	return result
end

function V16.applyMilestonePlan(payload)
	payload = payload or {}
	local mutation = payload.mutation or (payload.planSummary and payload.planSummary.mutation) or nil
	if not mutation then
		local generated = V16.getMilestonePlan(payload)
		mutation = generated.mutation
	end
	if type(mutation) ~= "table" then
		error("applyMilestonePlan requires a mutation plan.")
	end
	local commandType = tostring(mutation.commandType or "")
	local result
	if commandType == "applyGameplayFeaturePlan" then
		result = V15.applyGameplayFeaturePlan({ bundle = mutation.bundle or payload.bundle or payload.plan })
	elseif commandType == "applyBuildPlan" then
		result = applyBuildPlan({ blueprint = mutation.blueprint or payload.blueprint })
	else
		error("Unsupported milestone mutation command: " .. commandType)
	end
	local milestone = payload.milestone or (payload.planSummary and payload.planSummary.milestone) or nil
	if type(milestone) ~= "table" then
		milestone = { id = payload.milestoneId or payload.milestone or "" }
	end
	local report = {
		at = isoNow(),
		version = VERSION,
		kind = "milestoneApply",
		milestone = milestone,
		commandType = commandType,
		result = result,
		verificationHint = "Run tools/bridge.cmd verify run " .. tostring(milestone.id or payload.milestoneId or ""),
	}
	V16.last.milestoneReport = report
	return report
end

function V16.verificationHarnessBlueprint(payload)
	local profile = V16.profile(payload or {})
	return {
		name = "Codex Verification Harness",
		mode = "supervised",
		source = "V16.verificationHarnessBlueprint",
		steps = {
			{ type = "ensureFolder", path = "ReplicatedStorage.CodexVerificationHarness" },
			{ type = "ensureFolder", path = "ServerScriptService.CodexVerificationHarness" },
			{ type = "ensureFolder", path = "Workspace.CodexVerificationHarness" },
			{
				type = "ensureInstance",
				className = "StringValue",
				path = "ReplicatedStorage.CodexVerificationHarness.Profile",
				properties = { Value = V16.profileId(profile) },
			},
			{
				type = "ensureInstance",
				className = "StringValue",
				path = "ReplicatedStorage.CodexVerificationHarness.Purpose",
				properties = { Value = "Stores approved verification markers only; no arbitrary code execution." },
			},
		},
	}
end

function V16.harnessStatus()
	local roots = {
		"ReplicatedStorage.CodexVerificationHarness",
		"ServerScriptService.CodexVerificationHarness",
		"Workspace.CodexVerificationHarness",
	}
	local installed = {}
	local missing = {}
	for _, path in ipairs(roots) do
		local instance = resolvePath(path)
		if instance then
			table.insert(installed, { path = safeFullName(instance), className = instance.ClassName })
		else
			table.insert(missing, path)
		end
	end
	local status = {
		at = isoNow(),
		version = VERSION,
		installed = #missing == 0,
		installedCount = #installed,
		missingCount = #missing,
		installedRoots = installed,
		missingRoots = missing,
	}
	V16.last.verificationHarnessStatus = status
	return status
end

function V16.installVerificationHarness(payload)
	local blueprint = normalizeBlueprint(payload or {}) or V16.verificationHarnessBlueprint(payload or {})
	local result = applyBuildPlan({ blueprint = blueprint })
	V16.last.verificationHarnessStatus = V16.harnessStatus()
	return {
		at = isoNow(),
		version = VERSION,
		kind = "installVerificationHarness",
		build = result,
		status = V16.last.verificationHarnessStatus,
	}
end

function V16.removeVerificationHarness(payload)
	local paths = {
		"ReplicatedStorage.CodexVerificationHarness",
		"ServerScriptService.CodexVerificationHarness",
		"Workspace.CodexVerificationHarness",
	}
	return withUndo("RemoveVerificationHarness", function()
		local removed = {}
		local skipped = {}
		for _, path in ipairs(paths) do
			local instance = resolvePath(path)
			if instance then
				table.insert(removed, { path = safeFullName(instance), className = instance.ClassName })
				instance:Destroy()
			else
				table.insert(skipped, { path = path, reason = "missing" })
			end
		end
		stateDirty = true
		V16.last.verificationHarnessStatus = V16.harnessStatus()
		return {
			at = isoNow(),
			version = VERSION,
			kind = "removeVerificationHarness",
			removed = removed,
			skipped = skipped,
			status = V16.last.verificationHarnessStatus,
			summary = {
				removed = #removed,
				skipped = #skipped,
			},
		}
	end)
end

V17.last = {}

function V17.array(value)
	return V15.array(value)
end

function V17.profile(payload)
	return V7.profileFromPayload(payload or {})
end

function V17.profileId(profile)
	return tostring((profile or {}).id or "universal")
end

function V17.defaultExpectedLoop()
	return {
		{ id = "join", title = "Join", evidence = { "playerJoined", "playerPresent" } },
		{ id = "spawn", title = "Spawn", evidence = { "characterSpawned", "characterPresent" } },
		{ id = "understandObjective", title = "Understand Objective", evidence = { "objectivePath", "objectiveOutput", "objectiveSignal" } },
		{ id = "interactPlay", title = "Interact / Play", evidence = { "interactionOutput", "combatOutput", "scenarioMarker" } },
		{ id = "receiveFeedback", title = "Receive Feedback", evidence = { "feedbackOutput", "remoteFeedback", "harnessLog" } },
		{ id = "failWin", title = "Fail / Win", evidence = { "death", "matchEndOutput", "successSignal", "failureSignal" } },
		{ id = "reward", title = "Reward", evidence = { "rewardOutput", "rewardSignal" } },
		{ id = "replayReturn", title = "Replay / Return", evidence = { "replayOutput", "replaySignal" } },
	}
end

function V17.expectedLoop(profile)
	local configured = V17.array((profile or {}).expectedLoop)
	if #configured > 0 then
		return configured
	end
	return V17.defaultExpectedLoop()
end

function V17.objectivePaths(profile)
	local paths = {}
	for _, path in ipairs(V17.array((profile or {}).objectivePaths)) do
		table.insert(paths, tostring(path))
	end
	local gameLoop = type((profile or {}).gameLoop) == "table" and profile.gameLoop or {}
	if type(gameLoop.objectivePath) == "string" then
		table.insert(paths, gameLoop.objectivePath)
	end
	for _, item in ipairs(V17.array((profile or {}).landmarkExpectations)) do
		if type(item) == "table" and type(item.path) == "string" then
			table.insert(paths, item.path)
		end
	end
	if #paths == 0 then
		table.insert(paths, "Workspace")
	end
	return paths
end

function V17.signalList(profile, key, fallback)
	local values = {}
	for _, item in ipairs(V17.array((profile or {})[key])) do
		if type(item) == "string" then
			table.insert(values, item)
		elseif type(item) == "table" then
			table.insert(values, tostring(item.pattern or item.keyword or item.id or item.name or ""))
		end
	end
	if #values == 0 then
		for _, item in ipairs(fallback or {}) do
			table.insert(values, item)
		end
	end
	return values
end

function V17.addTimeline(kind, message, data)
	local entry = {
		at = isoNow(),
		kind = tostring(kind or "event"),
		message = tostring(message or ""),
		data = data or {},
	}
	if V17.session and V17.session.startedClock then
		entry.relativeSeconds = math.floor((os.clock() - V17.session.startedClock) * 100) / 100
	end
	table.insert(V17.timeline, entry)
	while #V17.timeline > 1000 do
		table.remove(V17.timeline, 1)
	end
	return entry
end

function V17.disconnectQa()
	for _, connection in ipairs(V17.connections) do
		pcall(function()
			connection:Disconnect()
		end)
	end
	V17.connections = {}
end

function V17.addConnection(connection)
	if connection then
		table.insert(V17.connections, connection)
	end
end

function V17.watchCharacter(player, character)
	if not character then
		return
	end
	V17.addTimeline("characterSpawned", tostring(player.Name) .. " character spawned", {
		player = player.Name,
		userId = player.UserId,
		character = safeFullName(character),
	})
	local humanoid = character:FindFirstChildOfClass("Humanoid")
	if humanoid then
		V17.addConnection(humanoid.Died:Connect(function()
			V17.addTimeline("death", tostring(player.Name) .. " died", {
				player = player.Name,
				userId = player.UserId,
				character = safeFullName(character),
			})
		end))
	end
end

function V17.watchPlayer(player)
	V17.addTimeline("playerPresent", tostring(player.Name) .. " present", {
		player = player.Name,
		userId = player.UserId,
	})
	V17.addConnection(player.CharacterAdded:Connect(function(character)
		V17.watchCharacter(player, character)
	end))
	if player.Character then
		V17.watchCharacter(player, player.Character)
	end
end

function V17.startWatchers()
	V17.disconnectQa()
	V17.addConnection(Players.PlayerAdded:Connect(function(player)
		V17.addTimeline("playerJoined", tostring(player.Name) .. " joined", {
			player = player.Name,
			userId = player.UserId,
		})
		V17.watchPlayer(player)
	end))
	V17.addConnection(Players.PlayerRemoving:Connect(function(player)
		V17.addTimeline("playerLeft", tostring(player.Name) .. " left", {
			player = player.Name,
			userId = player.UserId,
		})
	end))
	for _, player in ipairs(Players:GetPlayers()) do
		V17.watchPlayer(player)
	end
end

function V17.harnessStatus()
	local roots = {
		"ReplicatedStorage.CodexQaHarness",
		"ServerScriptService.CodexQaHarness",
		"Workspace.CodexQaHarness",
	}
	local installed = {}
	local missing = {}
	for _, path in ipairs(roots) do
		local instance = resolvePath(path)
		if instance then
			table.insert(installed, { path = safeFullName(instance), className = instance.ClassName })
		else
			table.insert(missing, path)
		end
	end
	local status = {
		at = isoNow(),
		version = VERSION,
		installed = #missing == 0,
		installedCount = #installed,
		missingCount = #missing,
		installedRoots = installed,
		missingRoots = missing,
	}
	V17.last.qaHarnessStatus = status
	return status
end

-- V17 Playtest QA: read-only session/timeline reporting plus Full Trust harness helpers.
function V17.beginPlaytestQaSession(payload)
	payload = payload or {}
	V17.disconnectQa()
	V17.timeline = {}
	V17.session = {
		id = tostring(payload.sessionId or HttpService:GenerateGUID(false)),
		name = tostring(payload.name or payload.sessionName or "playtest-qa"),
		startedAt = isoNow(),
		startedClock = os.clock(),
		startOutputIndex = #outputBuffer + 1,
		profile = V7.profileSummary(V17.profile(payload)),
		baselineRuntime = getRuntimeStatus({}),
	}
	V17.addTimeline("sessionStarted", "QA session started: " .. V17.session.name, {
		sessionId = V17.session.id,
		mode = V17.session.baselineRuntime and V17.session.baselineRuntime.mode or nil,
	})
	V17.startWatchers()
	return V17.getPlaytestQaStatus(payload)
end

function V17.endPlaytestQaSession(payload)
	payload = payload or {}
	if V17.session then
		V17.addTimeline("sessionEnded", "QA session ended: " .. tostring(V17.session.name), {
			sessionId = V17.session.id,
		})
		V17.session.endedAt = isoNow()
		V17.session.active = false
	end
	V17.disconnectQa()
	local report = V17.getPlaytestQaReport(payload)
	return {
		at = isoNow(),
		version = VERSION,
		ended = V17.session ~= nil,
		session = V17.session,
		report = report,
	}
end

function V17.getOutputTimelineEntries(limit)
	local entries = {}
	local startIndex = V17.session and V17.session.startOutputIndex or math.max(1, #outputBuffer - (limit or 100) + 1)
	for index = startIndex, #outputBuffer do
		local entry = outputBuffer[index]
		if entry then
			table.insert(entries, {
				at = entry.at,
				kind = "output",
				message = V9.trimText(tostring(entry.message or ""), 240),
				data = {
					type = entry.type,
					source = entry.source,
				},
			})
		end
	end
	return entries
end

function V17.getPlaytestTimeline(payload)
	payload = payload or {}
	local limit = math.max(10, math.min(tonumber(payload.limit) or 200, 1000))
	local entries = {}
	for _, entry in ipairs(V17.timeline) do
		table.insert(entries, entry)
	end
	for _, entry in ipairs(V17.getOutputTimelineEntries(limit)) do
		table.insert(entries, entry)
	end
	table.sort(entries, function(a, b)
		return tostring(a.at or "") < tostring(b.at or "")
	end)
	while #entries > limit do
		table.remove(entries, 1)
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		session = V17.session,
		active = V17.session ~= nil and V17.session.endedAt == nil,
		count = #entries,
		entries = entries,
	}
	V17.last.playtestTimeline = result
	return result
end

function V17.countTimelineKinds(timeline)
	local counts = {}
	for _, entry in ipairs(timeline.entries or {}) do
		local kind = tostring(entry.kind or "event")
		counts[kind] = (counts[kind] or 0) + 1
	end
	return counts
end

function V17.getPlaytestQaStatus(payload)
	payload = payload or {}
	local runtime = getRuntimeStatus({})
	local timeline = V17.getPlaytestTimeline({ limit = 50 })
	local status = {
		at = isoNow(),
		version = VERSION,
		active = V17.session ~= nil and V17.session.endedAt == nil,
		session = V17.session,
		runtime = runtime,
		timeline = {
			count = timeline.count,
			kindCounts = V17.countTimelineKinds(timeline),
		},
		sources = {
			output = true,
			runtimeSnapshot = true,
			players = true,
			characters = true,
			worldSummary = true,
			harness = V17.harnessStatus(),
		},
	}
	V17.last.playtestQaStatus = status
	return status
end

function V17.timelineContainsAny(timeline, patterns)
	for _, entry in ipairs(timeline.entries or {}) do
		local haystack = tostring(entry.kind or ""):lower() .. " " .. tostring(entry.message or ""):lower()
		for _, pattern in ipairs(patterns or {}) do
			local needle = tostring(pattern or ""):lower()
			if needle ~= "" and haystack:find(needle, 1, true) then
				return true, entry
			end
		end
	end
	return false, nil
end

function V17.getPlayerFlowReport(payload)
	payload = payload or {}
	local timeline = V17.getPlaytestTimeline({ limit = payload.limit or 250 })
	local counts = V17.countTimelineKinds(timeline)
	local actors = V8.getRuntimeActors({ maxNpcs = 50 })
	local spawnedPlayers = 0
	for _, player in ipairs(actors.players or {}) do
		if player.character then
			spawnedPlayers += 1
		end
	end
	local report = {
		at = isoNow(),
		version = VERSION,
		session = V17.session,
		status = actors.playerCount > 0 and "observing" or "waitingForPlayers",
		playerCount = actors.playerCount,
		spawnedPlayers = spawnedPlayers,
		joinedEvents = counts.playerJoined or 0,
		leftEvents = counts.playerLeft or 0,
		characterSpawnEvents = counts.characterSpawned or 0,
		deathEvents = counts.death or 0,
		players = actors.players,
		findings = {},
	}
	if actors.playerCount == 0 then
		table.insert(report.findings, { severity = "info", code = "noPlayers", message = "No players are currently visible to the plugin context." })
	end
	if actors.playerCount > 0 and spawnedPlayers == 0 then
		table.insert(report.findings, { severity = "warning", code = "noCharacterSpawn", message = "Players are present, but no character is currently spawned." })
	end
	V17.last.playerFlowReport = report
	return report
end

function V17.getDeathSpawnReport(payload)
	payload = payload or {}
	local timeline = V17.getPlaytestTimeline({ limit = payload.limit or 250 })
	local counts = V17.countTimelineKinds(timeline)
	local actors = V8.getRuntimeActors({ maxNpcs = 100 })
	local world = V8.getRuntimeWorldSummary(payload)
	local lowHealth = {}
	for _, player in ipairs(actors.players or {}) do
		local humanoid = player.character and player.character.humanoid
		if humanoid and tonumber(humanoid.health) and tonumber(humanoid.maxHealth) and humanoid.health > 0 and humanoid.health <= math.max(1, humanoid.maxHealth * 0.25) then
			table.insert(lowHealth, { player = player.name, health = humanoid.health, maxHealth = humanoid.maxHealth })
		end
	end
	local report = {
		at = isoNow(),
		version = VERSION,
		session = V17.session,
		deathEvents = counts.death or 0,
		characterSpawnEvents = counts.characterSpawned or 0,
		spawnLocations = world.counts and world.counts.spawnLocations or 0,
		lowHealthPlayers = lowHealth,
		npcCount = actors.npcCount,
		findings = {},
	}
	if report.spawnLocations == 0 then
		table.insert(report.findings, { severity = "warning", code = "noSpawnLocations", message = "No SpawnLocation objects were found in Workspace." })
	end
	if #lowHealth > 0 then
		table.insert(report.findings, { severity = "info", code = "lowHealthPlayers", message = tostring(#lowHealth) .. " players are at low health." })
	end
	V17.last.deathSpawnReport = report
	return report
end

function V17.getObjectiveFlowReport(payload)
	payload = payload or {}
	local profile = V17.profile(payload)
	local timeline = V17.getPlaytestTimeline({ limit = payload.limit or 250 })
	local paths = {}
	local existing = 0
	for _, path in ipairs(V17.objectivePaths(profile)) do
		local instance = resolvePath(path)
		if instance then
			existing += 1
		end
		table.insert(paths, {
			path = path,
			exists = instance ~= nil,
			className = instance and instance.ClassName or nil,
		})
	end
	local objectivePatterns = V17.signalList(profile, "qaSignals", { "objective", "quest", "checkpoint", "extract", "reward", "score" })
	local foundSignal, signalEntry = V17.timelineContainsAny(timeline, objectivePatterns)
	local report = {
		at = isoNow(),
		version = VERSION,
		profile = V7.profileSummary(profile),
		session = V17.session,
		objectivePaths = paths,
		existingObjectivePathCount = existing,
		objectiveSignalSeen = foundSignal,
		objectiveSignalEntry = signalEntry,
		findings = {},
	}
	if existing == 0 then
		table.insert(report.findings, { severity = "warning", code = "noObjectiveLandmark", message = "No expected objective path is currently present." })
	end
	if not foundSignal then
		table.insert(report.findings, { severity = "info", code = "noObjectiveSignal", message = "No objective-like Output or QA signal was observed in the current session." })
	end
	V17.last.objectiveFlowReport = report
	return report
end

function V17.stageEvidence(stage, timeline, objectiveReport, playerFlow)
	local id = tostring(stage.id or stage.name or stage)
	if id == "join" then
		return (playerFlow.playerCount or 0) > 0 or (playerFlow.joinedEvents or 0) > 0, "player count/join events"
	end
	if id == "spawn" then
		return (playerFlow.spawnedPlayers or 0) > 0 or (playerFlow.characterSpawnEvents or 0) > 0, "character spawn evidence"
	end
	if id == "understandObjective" or id == "objective" then
		return (objectiveReport.existingObjectivePathCount or 0) > 0 or objectiveReport.objectiveSignalSeen == true, "objective path or signal"
	end
	if id == "interactPlay" or id == "interact" or id == "play" then
		return V17.timelineContainsAny(timeline, { "interact", "request", "click", "combat", "start", "play", "checkpoint", "vote" })
	end
	if id == "receiveFeedback" or id == "feedback" then
		return V17.timelineContainsAny(timeline, { "feedback", "toast", "fx", "updated", "score", "warning", "reward", "damage" })
	end
	if id == "failWin" or id == "fail" or id == "win" then
		return V17.timelineContainsAny(timeline, { "death", "win", "victory", "defeat", "match end", "failed", "success" })
	end
	if id == "reward" then
		return V17.timelineContainsAny(timeline, { "reward", "coins", "currency", "summary", "loot", "xp" })
	end
	if id == "replayReturn" or id == "replay" or id == "return" then
		return V17.timelineContainsAny(timeline, { "replay", "return", "again", "requeue", "restart" })
	end
	local evidence = type(stage) == "table" and stage.evidence or nil
	return V17.timelineContainsAny(timeline, V17.array(evidence))
end

function V17.getExpectedLoopComparison(payload)
	payload = payload or {}
	local profile = V17.profile(payload)
	local timeline = V17.getPlaytestTimeline({ limit = payload.limit or 300 })
	local playerFlow = V17.getPlayerFlowReport(payload)
	local objective = V17.getObjectiveFlowReport(payload)
	local stages = {}
	local covered = 0
	local missing = {}
	for _, stage in ipairs(V17.expectedLoop(profile)) do
		local ok, evidence = V17.stageEvidence(stage, timeline, objective, playerFlow)
		local id = tostring(type(stage) == "table" and (stage.id or stage.name) or stage)
		if ok then
			covered += 1
		else
			table.insert(missing, id)
		end
		table.insert(stages, {
			id = id,
			title = tostring(type(stage) == "table" and (stage.title or stage.id or stage.name) or stage),
			covered = ok == true,
			evidence = type(evidence) == "table" and evidence.message or evidence,
		})
	end
	local report = {
		at = isoNow(),
		version = VERSION,
		profile = V7.profileSummary(profile),
		session = V17.session,
		coverage = #stages > 0 and math.floor((covered / #stages) * 100 + 0.5) or 100,
		covered = covered,
		total = #stages,
		missing = missing,
		stages = stages,
	}
	V17.last.expectedLoopComparison = report
	return report
end

function V17.getPlaytestBugReport(payload)
	payload = payload or {}
	local outputErrors = getOutputErrors({ limit = payload.outputLimit or 100 })
	local loop = V17.getExpectedLoopComparison(payload)
	local deaths = V17.getDeathSpawnReport(payload)
	local objective = V17.getObjectiveFlowReport(payload)
	local bugs = {}
	for _, group in ipairs(outputErrors.groups or {}) do
		table.insert(bugs, {
			severity = "error",
			code = "outputError",
			title = "Output issue: " .. V9.trimText(tostring(group.key or group.message or "Output error"), 80),
			count = group.count,
			traceCommand = "tools/bridge.cmd code trace-error " .. string.format("%q", tostring(group.key or group.message or "")),
		})
	end
	for _, stage in ipairs(loop.missing or {}) do
		table.insert(bugs, {
			severity = "warning",
			code = "missingLoopStage",
			title = "Expected loop stage not observed: " .. tostring(stage),
			suggestedCommand = "tools/bridge.cmd qa compare-loop",
		})
	end
	for _, finding in ipairs(deaths.findings or {}) do
		table.insert(bugs, finding)
	end
	for _, finding in ipairs(objective.findings or {}) do
		table.insert(bugs, finding)
	end
	local report = {
		at = isoNow(),
		version = VERSION,
		session = V17.session,
		bugCount = #bugs,
		bugs = bugs,
		output = {
			count = outputErrors.count,
			groups = outputErrors.groups,
		},
		loop = {
			coverage = loop.coverage,
			missing = loop.missing,
		},
	}
	V17.last.playtestBugReport = report
	return report
end

function V17.getQaFixSuggestions(payload)
	payload = payload or {}
	local bugs = V17.getPlaytestBugReport(payload)
	local suggestions = {}
	if bugs.output and bugs.output.count and bugs.output.count > 0 then
		table.insert(suggestions, { priority = 1, title = "Trace the latest Output issue", command = "tools/bridge.cmd code trace-error", reason = "Output errors are the strongest QA signal." })
	end
	if bugs.loop and type(bugs.loop.missing) == "table" then
		for _, stage in ipairs(bugs.loop.missing) do
			if tostring(stage) == "spawn" then
				table.insert(suggestions, { priority = 2, title = "Check spawn setup", command = "tools/bridge.cmd world map", reason = "The spawn stage was not observed." })
			elseif tostring(stage) == "understandObjective" or tostring(stage) == "objective" then
				table.insert(suggestions, { priority = 2, title = "Audit objective readability", command = "tools/bridge.cmd world landmarks", reason = "The objective stage was not observed." })
			elseif tostring(stage) == "reward" or tostring(stage) == "replayReturn" then
				table.insert(suggestions, { priority = 3, title = "Preview a reward/replay system", command = "tools/bridge.cmd feature preview reward-replay", reason = "The end-of-loop stage was not observed." })
			end
		end
	end
	if not V17.harnessStatus().installed then
		table.insert(suggestions, { priority = 5, title = "Install QA harness for richer markers", command = "tools/bridge.cmd qa harness install", reason = "Harness installation is optional and runs under Full Trust audit." })
	end
	table.sort(suggestions, function(a, b)
		return (tonumber(a.priority) or 99) < (tonumber(b.priority) or 99)
	end)
	local report = {
		at = isoNow(),
		version = VERSION,
		session = V17.session,
		suggestions = suggestions,
		count = #suggestions,
	}
	V17.last.qaFixSuggestions = report
	return report
end

function V17.getPlaytestQaReport(payload)
	payload = payload or {}
	local report = {
		at = isoNow(),
		version = VERSION,
		profile = V7.profileSummary(V17.profile(payload)),
		status = V17.getPlaytestQaStatus(payload),
		timeline = V17.getPlaytestTimeline({ limit = payload.limit or 200 }),
		playerFlow = V17.getPlayerFlowReport(payload),
		deathSpawn = V17.getDeathSpawnReport(payload),
		objectives = V17.getObjectiveFlowReport(payload),
		loopComparison = V17.getExpectedLoopComparison(payload),
		bugs = V17.getPlaytestBugReport(payload),
		fixSuggestions = V17.getQaFixSuggestions(payload),
	}
	V17.last.playtestQaReport = report
	return report
end

function V17.qaHarnessBlueprint(payload)
	local profile = V17.profile(payload or {})
	return {
		name = "Codex QA Harness",
		mode = "supervised",
		source = "V17.qaHarnessBlueprint",
		steps = {
			{ type = "ensureFolder", path = "ReplicatedStorage.CodexQaHarness" },
			{ type = "ensureFolder", path = "ServerScriptService.CodexQaHarness" },
			{ type = "ensureFolder", path = "Workspace.CodexQaHarness" },
			{ type = "ensureFolder", path = "Workspace.CodexQaHarness.ScenarioMarkers" },
			{
				type = "ensureInstance",
				className = "StringValue",
				path = "ReplicatedStorage.CodexQaHarness.Profile",
				properties = { Value = V17.profileId(profile) },
			},
			{
				type = "ensureInstance",
				className = "StringValue",
				path = "ReplicatedStorage.CodexQaHarness.Purpose",
				properties = { Value = "Approved QA markers only. Read commands stay non-mutating." },
			},
		},
	}
end

function V17.installQaHarness(payload)
	local blueprint = normalizeBlueprint(payload or {}) or V17.qaHarnessBlueprint(payload or {})
	local result = applyBuildPlan({ blueprint = blueprint })
	V17.last.qaHarnessStatus = V17.harnessStatus()
	return {
		at = isoNow(),
		version = VERSION,
		kind = "installQaHarness",
		build = result,
		status = V17.last.qaHarnessStatus,
	}
end

function V17.removeQaHarness(payload)
	local paths = {
		"ReplicatedStorage.CodexQaHarness",
		"ServerScriptService.CodexQaHarness",
		"Workspace.CodexQaHarness",
	}
	return withUndo("RemoveQaHarness", function()
		local removed = {}
		local skipped = {}
		for _, path in ipairs(paths) do
			local instance = resolvePath(path)
			if instance then
				table.insert(removed, { path = safeFullName(instance), className = instance.ClassName })
				instance:Destroy()
			else
				table.insert(skipped, { path = path, reason = "missing" })
			end
		end
		stateDirty = true
		V17.last.qaHarnessStatus = V17.harnessStatus()
		return {
			at = isoNow(),
			version = VERSION,
			kind = "removeQaHarness",
			removed = removed,
			skipped = skipped,
			status = V17.last.qaHarnessStatus,
			summary = {
				removed = #removed,
				skipped = #skipped,
			},
		}
	end)
end

function V17.applyQaScenarioMarkers(payload)
	payload = payload or {}
	local scenario = tostring(payload.scenario or payload.name or "manual")
	local markerName = scenario:gsub("[^%w_]", "_")
	if markerName == "" then
		markerName = "manual"
	end
	local blueprint = normalizeBlueprint(payload) or {
		name = "Codex QA Scenario Markers",
		mode = "supervised",
		source = "V17.applyQaScenarioMarkers",
		steps = {
			{ type = "ensureFolder", path = "Workspace.CodexQaHarness" },
			{ type = "ensureFolder", path = "Workspace.CodexQaHarness.ScenarioMarkers" },
			{
				type = "ensureInstance",
				className = "StringValue",
				path = "Workspace.CodexQaHarness.ScenarioMarkers." .. markerName,
				properties = { Value = "QA scenario marker: " .. scenario },
			},
		},
	}
	local result = applyBuildPlan({ blueprint = blueprint })
	return {
		at = isoNow(),
		version = VERSION,
		kind = "applyQaScenarioMarkers",
		scenario = scenario,
		build = result,
	}
end

-- V19 Production Refactor: conservative target discovery, impact reports, and hash-checked apply plans.
function V19.array(value)
	if type(value) == "table" then
		return value
	end
	return {}
end

function V19.profile(payload)
	return V7.profileFromPayload(payload or {})
end

function V19.shortGuid()
	return string.sub(HttpService:GenerateGUID(false), 1, 8)
end

function V19.planId(payload)
	return tostring((payload or {}).planId or ("refactor-" .. tostring(os.time()) .. "-" .. V19.shortGuid()))
end

function V19.targetRecord(instance)
	if not instance then
		return nil
	end
	local parent = instance.Parent
	return {
		id = getInstanceId(instance),
		name = instance.Name,
		className = instance.ClassName,
		path = safeFullName(instance),
		parentId = parent and getInstanceId(parent) or nil,
		parentPath = parent and safeFullName(parent) or nil,
		childCount = #instance:GetChildren(),
		hasSource = instance:IsA("LuaSourceContainer"),
	}
end

function V19.resolveTarget(payload)
	payload = payload or {}
	return resolveInstance(payload.targetId or payload.instanceId or payload.id or payload.path or payload.target or payload.module or payload.oldModule)
end

function V19.isProtectedPath(path, profile, allowProtected)
	if allowProtected == true then
		return false
	end
	path = tostring(path or "")
	for _, protected in ipairs(V19.array((profile or {}).protectedPaths)) do
		protected = tostring(protected)
		if protected ~= "" and (path == protected or path:sub(1, #protected + 1) == protected .. ".") then
			return true, protected
		end
	end
	return false, nil
end

function V19.defaultSkipReason(record)
	if not record then
		return "missing"
	end
	return V7.cleanupSkipReason(record.parentPath, record.path, record.className)
end

function V19.targetMatches(record, query)
	query = tostring(query or ""):lower()
	if query == "" then
		return true
	end
	return tostring(record.name or ""):lower():find(query, 1, true)
		or tostring(record.path or ""):lower():find(query, 1, true)
		or tostring(record.className or ""):lower():find(query, 1, true)
end

function V19.getRefactorTargetMap(payload)
	payload = payload or {}
	local query = tostring(payload.query or "")
	local includeInternal = payload.includeInternal == true
	local maxTargets = math.max(1, math.min(tonumber(payload.maxTargets) or 800, 3000))
	local interesting = {
		Folder = true,
		Model = true,
		Script = true,
		LocalScript = true,
		ModuleScript = true,
		RemoteEvent = true,
		RemoteFunction = true,
		BindableEvent = true,
		BindableFunction = true,
		ScreenGui = true,
		Tool = true,
	}
	local targets = {}
	local counts = {}
	local skipped = {
		internal = 0,
		legitRobloxDuplicate = 0,
		nonGameRoot = 0,
		missing = 0,
	}
	local truncated = false
	local function consider(instance)
		if #targets >= maxTargets then
			truncated = true
			return
		end
		if interesting[instance.ClassName] then
			local record = V19.targetRecord(instance)
			local skipReason = includeInternal and nil or V19.defaultSkipReason(record)
			if skipReason then
				skipped[skipReason] = (skipped[skipReason] or 0) + 1
			elseif record and V19.targetMatches(record, query) then
				table.insert(targets, record)
				counts[record.className] = (counts[record.className] or 0) + 1
			end
		end
	end
	local roots = {}
	if includeInternal then
		for _, root in ipairs(game:GetChildren()) do
			table.insert(roots, root)
		end
	else
		roots = getPriorityRoots()
	end
	for _, root in ipairs(roots) do
		consider(root)
		for _, instance in ipairs(root:GetDescendants()) do
			if truncated then
				break
			end
			consider(instance)
		end
		if truncated then
			break
		end
	end
	table.sort(targets, function(a, b)
		return a.path < b.path
	end)
	local result = {
		at = isoNow(),
		version = VERSION,
		query = query,
		includeInternal = includeInternal,
		summary = {
			targetCount = #targets,
			truncated = truncated,
			classCounts = counts,
			skipped = skipped,
		},
		targets = targets,
	}
	V19.last.targetMap = result.summary
	return result
end

function V19.referenceLinesForText(text, payload)
	text = tostring(text or "")
	local result = {
		text = text,
		count = 0,
		truncated = false,
		references = {},
	}
	if text == "" then
		return result
	end
	local maxReferences = math.max(1, math.min(tonumber((payload or {}).maxReferences) or 160, 1000))
	local map = V12.collectScripts(payload or {}, true)
	for _, script in ipairs(map.scripts or {}) do
		if script.source and script.source:find(text, 1, true) then
			for lineNumber, line in ipairs(splitLines(script.source)) do
				if line:find(text, 1, true) then
					result.count += 1
					if #result.references < maxReferences then
						table.insert(result.references, {
							scriptId = script.id,
							scriptPath = script.path,
							scriptClassName = script.className,
							sourceHash = script.sourceHash,
							line = lineNumber,
							text = V12.shortText(line, 240),
						})
					else
						result.truncated = true
					end
				end
			end
		end
	end
	return result
end

function V19.escapePattern(text)
	return tostring(text or ""):gsub("([%%%^%$%(%)%.%[%]%*%+%-%?])", "%%%1")
end

function V19.escapeReplacement(text)
	return tostring(text or ""):gsub("%%", "%%%%")
end

function V19.lineCanRewrite(line, context)
	line = tostring(line or "")
	if context == "require" then
		return line:find("require%s*%(") ~= nil
	end
	return line:find("WaitForChild%s*%(")
		or line:find("FindFirstChild%s*%(")
		or line:find("require%s*%(")
		or line:lower():find("remote", 1, true)
		or line:find("getRemote")
end

function V19.rewriteQuotedReferences(source, oldText, newText, context)
	local lines = splitLines(source or "")
	local escaped = V19.escapePattern(oldText)
	local replacement = V19.escapeReplacement(newText)
	local changedLines = 0
	for index, line in ipairs(lines) do
		if line:find(oldText, 1, true) and V19.lineCanRewrite(line, context) then
			local newLine = line:gsub("\"" .. escaped .. "\"", "\"" .. replacement .. "\"")
			newLine = newLine:gsub("'" .. escaped .. "'", "'" .. replacement .. "'")
			if newLine ~= line then
				lines[index] = newLine
				changedLines += 1
			end
		end
	end
	return table.concat(lines, "\n"), changedLines
end

function V19.scriptPatchesForQuotedRewrite(payload, oldText, newText, context, summary)
	local patches = {}
	if tostring(oldText or "") == "" or tostring(newText or "") == "" or oldText == newText then
		return patches
	end
	local map = V12.collectScripts(payload or {}, true)
	for _, script in ipairs(map.scripts or {}) do
		local newSource, changed = V19.rewriteQuotedReferences(script.source or "", oldText, newText, context)
		if changed > 0 then
			table.insert(patches, {
				scriptId = script.id,
				path = script.path,
				className = script.className,
				expectedSourceHash = script.sourceHash,
				newSource = newSource,
				summary = summary or ("Rewrite " .. oldText .. " to " .. newText),
				diff = {
					oldLineCount = script.lineCount,
					newLineCount = countLines(newSource),
					changedLineCount = changed,
				},
			})
		end
	end
	return patches
end

function V19.summarizePatches(patches)
	local summary = {
		patchCount = #(patches or {}),
		changedLineCount = 0,
	}
	for _, patch in ipairs(patches or {}) do
		if type(patch.diff) == "table" then
			summary.changedLineCount += tonumber(patch.diff.changedLineCount) or 0
		end
	end
	return summary
end

function V19.getRenameImpactReport(payload)
	payload = payload or {}
	local profile = V19.profile(payload)
	local target = V19.resolveTarget(payload)
	local newName = tostring(payload.newName or payload.name or "")
	local blockers = {}
	local warnings = {}
	if not target then
		table.insert(blockers, "Target instance was not found.")
	end
	if newName == "" then
		table.insert(blockers, "New name is required.")
	end
	local targetRecord = V19.targetRecord(target)
	if targetRecord then
		local protected, protectedRoot = V19.isProtectedPath(targetRecord.path, profile, payload.allowProtected)
		if protected then
			table.insert(blockers, "Target is under protected path: " .. tostring(protectedRoot))
		end
		local parent = target.Parent
		local conflict = parent and parent:FindFirstChild(newName)
		if conflict and conflict ~= target then
			table.insert(blockers, "A sibling named " .. newName .. " already exists under " .. safeFullName(parent) .. ".")
		end
	end
	local references = targetRecord and V19.referenceLinesForText(targetRecord.name, payload) or { count = 0, references = {} }
	local patches = {}
	if targetRecord and payload.updateReferences ~= false and #blockers == 0 then
		patches = V19.scriptPatchesForQuotedRewrite(payload, targetRecord.name, newName, "name", "Rename references for " .. targetRecord.name)
		if references.count > #patches then
			table.insert(warnings, "Some references are review-only because V19 rewrites only quoted WaitForChild/FindFirstChild/remote/require references.")
		end
	end
	return {
		at = isoNow(),
		version = VERSION,
		kind = "renameImpact",
		target = targetRecord,
		newName = newName,
		blockers = blockers,
		warnings = warnings,
		references = references,
		scriptPatchSummary = V19.summarizePatches(patches),
		scriptPatches = patches,
	}
end

function V19.getMoveModuleImpactReport(payload)
	payload = payload or {}
	local profile = V19.profile(payload)
	local target = V19.resolveTarget(payload)
	local newParent = resolveInstance(payload.newParentId or payload.newParentPath or payload.parentPath or payload.parent)
	local blockers = {}
	local warnings = {}
	if not target then
		table.insert(blockers, "Module target was not found.")
	elseif not target:IsA("ModuleScript") then
		table.insert(blockers, "Move-module refactors require a ModuleScript target.")
	end
	if not newParent then
		table.insert(blockers, "New parent was not found.")
	end
	local targetRecord = V19.targetRecord(target)
	if targetRecord then
		local protected, protectedRoot = V19.isProtectedPath(targetRecord.path, profile, payload.allowProtected)
		if protected then
			table.insert(blockers, "Target is under protected path: " .. tostring(protectedRoot))
		end
	end
	if target and newParent then
		local conflict = newParent:FindFirstChild(target.Name)
		if conflict and conflict ~= target then
			table.insert(blockers, "New parent already contains " .. target.Name .. ".")
		end
	end
	local modules = V13.getModuleResolutionReport(payload)
	local requireReferences = {}
	if targetRecord then
		for _, item in ipairs(modules.resolvedRequirements or {}) do
			if item.resolvedPath == targetRecord.path then
				table.insert(requireReferences, item)
			end
		end
	end
	if #requireReferences > 0 then
		table.insert(warnings, "Move preview lists require call sites, but automatic path rewriting is limited to explicit require-rewrite plans.")
	end
	return {
		at = isoNow(),
		version = VERSION,
		kind = "moveModuleImpact",
		target = targetRecord,
		newParent = V19.targetRecord(newParent),
		blockers = blockers,
		warnings = warnings,
		requireReferenceCount = #requireReferences,
		requireReferences = requireReferences,
	}
end

function V19.getReferenceRewritePlan(payload)
	payload = payload or {}
	local oldText = tostring(payload.oldText or payload.oldName or payload.oldReference or "")
	local newText = tostring(payload.newText or payload.newName or payload.newReference or "")
	local context = tostring(payload.context or "name")
	local patches = V19.scriptPatchesForQuotedRewrite(payload, oldText, newText, context, "Rewrite " .. oldText .. " to " .. newText)
	local blockers = {}
	if oldText == "" or newText == "" then
		table.insert(blockers, "oldText and newText are required.")
	end
	return {
		at = isoNow(),
		version = VERSION,
		kind = "referenceRewritePlan",
		oldText = oldText,
		newText = newText,
		context = context,
		blockers = blockers,
		scriptPatchSummary = V19.summarizePatches(patches),
		scriptPatches = patches,
	}
end

function V19.getRequireRewritePlan(payload)
	payload = payload or {}
	local oldTarget = resolveInstance(payload.oldModule or payload.oldPath or payload.oldTarget)
	local newTarget = resolveInstance(payload.newModule or payload.newPath or payload.newTarget)
	local blockers = {}
	if not oldTarget then
		table.insert(blockers, "Old module target was not found.")
	end
	if not newTarget then
		table.insert(blockers, "New module target was not found.")
	end
	local oldName = oldTarget and oldTarget.Name or tostring(payload.oldName or payload.oldModule or "")
	local newName = newTarget and newTarget.Name or tostring(payload.newName or payload.newModule or "")
	local rewrite = V19.getReferenceRewritePlan({
		profile = payload.profile,
		oldText = oldName,
		newText = newName,
		context = "require",
		maxScripts = payload.maxScripts,
	})
	for _, blocker in ipairs(blockers) do
		table.insert(rewrite.blockers, blocker)
	end
	rewrite.kind = "requireRewritePlan"
	rewrite.oldModule = oldTarget and V19.targetRecord(oldTarget) or nil
	rewrite.newModule = newTarget and V19.targetRecord(newTarget) or nil
	return rewrite
end

function V19.getProductionRefactorPlan(payload)
	payload = payload or {}
	local kind = tostring(payload.refactorKind or payload.kind or payload.type or "rename")
	local planId = V19.planId(payload)
	local blockers = {}
	local warnings = {}
	local instanceActions = {}
	local scriptPatches = {}
	if kind == "rename" then
		local impact = V19.getRenameImpactReport(payload)
		blockers = impact.blockers
		warnings = impact.warnings
		scriptPatches = impact.scriptPatches or {}
		if impact.target then
			table.insert(instanceActions, {
				kind = "rename",
				targetId = impact.target.id,
				path = impact.target.path,
				expectedPath = impact.target.path,
				expectedName = impact.target.name,
				expectedClassName = impact.target.className,
				expectedParentPath = impact.target.parentPath,
				newName = impact.newName,
			})
		end
	elseif kind == "move-module" or kind == "moveModule" then
		local impact = V19.getMoveModuleImpactReport(payload)
		blockers = impact.blockers
		warnings = impact.warnings
		if impact.target and impact.newParent then
			table.insert(instanceActions, {
				kind = "move",
				targetId = impact.target.id,
				path = impact.target.path,
				expectedPath = impact.target.path,
				expectedName = impact.target.name,
				expectedClassName = impact.target.className,
				expectedParentPath = impact.target.parentPath,
				newParentId = impact.newParent.id,
				newParentPath = impact.newParent.path,
			})
		end
	elseif kind == "require-rewrite" or kind == "requireRewrite" then
		local rewrite = V19.getRequireRewritePlan(payload)
		blockers = rewrite.blockers
		scriptPatches = rewrite.scriptPatches or {}
	else
		table.insert(blockers, "Unsupported refactor kind: " .. kind)
	end
	local plan = {
		at = isoNow(),
		version = VERSION,
		planId = planId,
		refactorKind = kind,
		summary = payload.summary or ("Production refactor: " .. kind),
		blockers = blockers,
		warnings = warnings,
		instanceActions = instanceActions,
		scriptPatches = scriptPatches,
		scriptPatchSummary = V19.summarizePatches(scriptPatches),
		verificationChecks = {
			{ type = "instanceActionsApplied", count = #instanceActions },
			{ type = "scriptPatchesApplied", count = #scriptPatches },
			{ type = "runProjectScore" },
			{ type = "runCodeDoctor" },
		},
		approvalRequired = true,
	}
	V19.last.plan = {
		at = plan.at,
		planId = plan.planId,
		refactorKind = plan.refactorKind,
		instanceActions = #instanceActions,
		scriptPatches = #scriptPatches,
		blockers = #blockers,
	}
	return plan
end

function V19.validateProductionRefactorPlan(payload)
	payload = payload or {}
	local plan = payload.plan or payload.refactorPlan or payload
	local profile = V19.profile(plan)
	local blockers = {}
	local warnings = {}
	for index, action in ipairs(V19.array(plan.instanceActions)) do
		local instance = resolveInstance(action.targetId or action.instanceId or action.path or action.target)
		if not instance then
			table.insert(blockers, "Instance action " .. index .. " target was not found.")
		else
			local path = safeFullName(instance)
			if action.expectedPath and path ~= action.expectedPath then
				table.insert(blockers, "Instance action " .. index .. " path is stale: " .. path)
			end
			if action.expectedClassName and instance.ClassName ~= action.expectedClassName then
				table.insert(blockers, "Instance action " .. index .. " class mismatch.")
			end
			if action.expectedName and instance.Name ~= action.expectedName then
				table.insert(blockers, "Instance action " .. index .. " name is stale.")
			end
			local protected, protectedRoot = V19.isProtectedPath(path, profile, action.allowProtected or plan.allowProtected)
			if protected then
				table.insert(blockers, "Instance action " .. index .. " targets protected path: " .. tostring(protectedRoot))
			end
			if action.kind == "rename" then
				local newName = tostring(action.newName or "")
				if newName == "" then
					table.insert(blockers, "Instance action " .. index .. " missing newName.")
				elseif instance.Parent then
					local conflict = instance.Parent:FindFirstChild(newName)
					if conflict and conflict ~= instance then
						table.insert(blockers, "Instance action " .. index .. " has duplicate sibling target name.")
					end
				end
			elseif action.kind == "move" then
				local parent = resolveInstance(action.newParentId or action.newParentPath or action.parentPath)
				if not parent then
					table.insert(blockers, "Instance action " .. index .. " new parent was not found.")
				elseif parent:FindFirstChild(instance.Name) and parent:FindFirstChild(instance.Name) ~= instance then
					table.insert(blockers, "Instance action " .. index .. " new parent already contains target name.")
				end
			else
				table.insert(blockers, "Instance action " .. index .. " has unsupported kind: " .. tostring(action.kind))
			end
		end
	end
	for index, patch in ipairs(V19.array(plan.scriptPatches)) do
		local instance = resolveInstance(patch.scriptId or patch.instanceId or patch.targetId or patch.path or patch.target)
		if not instance or not instance:IsA("LuaSourceContainer") then
			table.insert(blockers, "Script patch " .. index .. " target script was not found.")
		elseif type(patch.newSource) ~= "string" then
			table.insert(blockers, "Script patch " .. index .. " is missing newSource.")
		else
			local expectedHash = tostring(patch.expectedSourceHash or "")
			if expectedHash == "" then
				table.insert(blockers, "Script patch " .. index .. " missing expectedSourceHash.")
			else
				local actualHash = sourceHash(readScriptSource(instance))
				if actualHash:lower() ~= expectedHash:lower() then
					table.insert(blockers, "Script patch " .. index .. " is stale for " .. safeFullName(instance) .. ".")
				end
			end
		end
	end
	if #(plan.instanceActions or {}) == 0 and #(plan.scriptPatches or {}) == 0 then
		table.insert(warnings, "Plan has no instance actions or script patches.")
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		planId = plan.planId,
		valid = #blockers == 0,
		blockers = blockers,
		warnings = warnings,
		summary = {
			blockers = #blockers,
			warnings = #warnings,
			instanceActions = #(plan.instanceActions or {}),
			scriptPatches = #(plan.scriptPatches or {}),
		},
	}
	V19.last.validation = result.summary
	return result
end

function V19.getRefactorSafetyReport(payload)
	payload = payload or {}
	local plan = payload.plan or payload.refactorPlan or V19.getProductionRefactorPlan(payload)
	local validation = V19.validateProductionRefactorPlan(plan)
	local codeDoctor = nil
	local ok, doctorOrError = pcall(function()
		return V13.getCodeFixDoctorReport(payload)
	end)
	if ok then
		codeDoctor = doctorOrError.summary
	end
	return {
		at = isoNow(),
		version = VERSION,
		planId = plan.planId,
		valid = validation.valid,
		validation = validation,
		codeDoctor = codeDoctor,
		safety = {
			approvalRequired = true,
			undoable = true,
			hashChecksRequired = true,
			deletesAllowed = false,
		},
	}
end

function V19.getRefactorVerificationPlan(payload)
	payload = payload or {}
	local plan = payload.plan or payload.refactorPlan or V19.last.appliedPlan or V19.last.plan or {}
	return {
		at = isoNow(),
		version = VERSION,
		planId = payload.planId or plan.planId,
		checks = {
			"Run tools/bridge.cmd project score",
			"Run tools/bridge.cmd code doctor",
			"Run tools/bridge.cmd refactor history",
			"Confirm Studio undo can revert the approved refactor.",
		},
		lastApplied = V19.last.applied,
	}
end

function V19.getRefactorHistory(payload)
	return {
		at = isoNow(),
		version = VERSION,
		count = #V19.history,
		history = V19.history,
		lastPlan = V19.last.plan,
		lastValidation = V19.last.validation,
		lastApplied = V19.last.applied,
	}
end

function V19.applyProductionRefactorPlan(payload)
	payload = payload or {}
	local plan = payload.plan or payload.refactorPlan or payload
	local validation = V19.validateProductionRefactorPlan(plan)
	if not validation.valid then
		error("Production refactor rejected: " .. table.concat(validation.blockers, " | "))
	end
	return withUndo("ProductionRefactor", function()
		local preparedActions = {}
		for _, action in ipairs(V19.array(plan.instanceActions)) do
			local instance = resolveInstance(action.targetId or action.instanceId or action.path or action.target)
			local parent = nil
			if action.kind == "move" then
				parent = resolveInstance(action.newParentId or action.newParentPath or action.parentPath)
			end
			table.insert(preparedActions, { action = action, instance = instance, parent = parent })
		end
		local preparedPatches = {}
		for _, patch in ipairs(V19.array(plan.scriptPatches)) do
			local instance = resolveInstance(patch.scriptId or patch.instanceId or patch.targetId or patch.path or patch.target)
			local currentSource = readScriptSource(instance)
			local actualHash = sourceHash(currentSource)
			if actualHash:lower() ~= tostring(patch.expectedSourceHash or ""):lower() then
				error("Stale script patch rejected for " .. safeFullName(instance) .. ".")
			end
			table.insert(preparedPatches, {
				instance = instance,
				currentSource = currentSource,
				actualHash = actualHash,
				patch = patch,
			})
		end
		local renamed = {}
		local moved = {}
		for _, item in ipairs(preparedActions) do
			if item.action.kind == "rename" then
				local oldPath = safeFullName(item.instance)
				item.instance.Name = tostring(item.action.newName)
				table.insert(renamed, {
					id = getInstanceId(item.instance),
					oldPath = oldPath,
					newPath = safeFullName(item.instance),
					newName = item.instance.Name,
				})
			elseif item.action.kind == "move" then
				local oldPath = safeFullName(item.instance)
				item.instance.Parent = item.parent
				table.insert(moved, {
					id = getInstanceId(item.instance),
					oldPath = oldPath,
					newPath = safeFullName(item.instance),
					newParentPath = safeFullName(item.parent),
				})
			end
		end
		local patched = {}
		for _, item in ipairs(preparedPatches) do
			updateScriptSource(item.instance, item.patch.newSource)
			table.insert(patched, {
				id = getInstanceId(item.instance),
				path = safeFullName(item.instance),
				summary = item.patch.summary or "",
				backupPath = item.patch.backupPath or "",
				oldSourceHash = item.actualHash,
				newSourceHash = sourceHash(item.patch.newSource),
				diff = item.patch.diff or {
					oldLineCount = countLines(item.currentSource),
					newLineCount = countLines(item.patch.newSource),
					changedLineCount = changedLineCount(item.currentSource, item.patch.newSource),
				},
			})
		end
		stateDirty = true
		local result = {
			at = isoNow(),
			version = VERSION,
			planId = plan.planId,
			summary = plan.summary or "Production refactor",
			refactorKind = plan.refactorKind,
			renamed = renamed,
			moved = moved,
			patched = patched,
			backups = plan.backups or payload.backups or {},
			counts = {
				renamed = #renamed,
				moved = #moved,
				patched = #patched,
			},
		}
		V19.last.applied = {
			at = result.at,
			planId = result.planId,
			counts = result.counts,
		}
		V19.last.appliedPlan = plan
		table.insert(V19.history, 1, V19.last.applied)
		while #V19.history > 30 do
			table.remove(V19.history)
		end
		return result
	end)
end

-- V20 Creator Dashboard: tool-health scoring plus separate game-readiness recommendations.
function V20.clampScore(value, floor, ceiling)
	value = tonumber(value) or 0
	floor = tonumber(floor) or 0
	ceiling = tonumber(ceiling) or 100
	if value < floor then
		return floor
	end
	if value > ceiling then
		return ceiling
	end
	return math.floor(value + 0.5)
end

function V20.safeReport(name, callback)
	local ok, result = pcall(callback)
	if ok then
		return { ok = true, name = name, result = result }
	end
	return { ok = false, name = name, error = tostring(result) }
end

function V20.statusForScore(score)
	score = tonumber(score) or 0
	if score >= 90 then
		return "excellent"
	end
	if score >= 75 then
		return "good"
	end
	if score >= 55 then
		return "needs-attention"
	end
	return "blocked"
end

function V20.issueScore(issueCount, penalty, floor)
	return V20.clampScore(100 - (tonumber(issueCount) or 0) * (tonumber(penalty) or 5), floor or 0)
end

function V20.category(id, title, score, command, report, notes)
	notes = notes or {}
	local warnings = notes.warnings or {}
	local blockers = notes.blockers or {}
	if report and report.ok == false then
		table.insert(blockers, tostring(report.error or "Report failed."))
		score = math.min(tonumber(score) or 0, 40)
	end
	return {
		id = id,
		title = title,
		score = V20.clampScore(score),
		status = V20.statusForScore(score),
		command = command,
		blockers = blockers,
		warnings = warnings,
		nextAction = notes.nextAction,
		reportOk = report and report.ok == true or false,
	}
end

function V20.mergeList(target, values, limit)
	limit = limit or 8
	for _, value in ipairs(values or {}) do
		if #target >= limit then
			return
		end
		table.insert(target, value)
	end
end

function V20.scoreReportHealth(report)
	if not report.ok then
		return 35
	end
	return 100
end

function V20.scoreCode(report)
	if not report.ok then
		return 35
	end
	local summary = report.result.summary or {}
	local scripts = tonumber(summary.scripts) or 0
	if scripts <= 0 then
		return 60
	end
	-- Tool health means "can Codex inspect and reason about code", not
	-- "the game's code has no remaining refactor/design recommendations".
	-- Missing/dynamic modules stay visible in game readiness and Code Doctor.
	return 100
end

function V20.scoreCodeReadiness(report)
	if not report.ok then
		return 35
	end
	local summary = report.result.summary or {}
	local modules = summary.modules or {}
	local smells = summary.smells or {}
	local issueCount = (tonumber(modules.missing) or 0) * 2
		+ (tonumber(summary.boundaryIssues) or 0)
		+ (tonumber(summary.remoteContractIssues) or 0)
		+ math.min(10, tonumber(smells.smellCount) or 0)
	return V20.issueScore(issueCount, 5, 35)
end

function V20.scoreUi(report)
	if not report.ok then
		return 35
	end
	local summary = report.result.summary or {}
	if tonumber(summary.nodes) == 0 and tonumber(summary.screens) == 0 then
		return 75
	end
	return 100
end

function V20.scoreUiReadiness(report)
	if not report.ok then
		return 35
	end
	return V20.issueScore(report.result.issueCount or 0, 5, 40)
end

function V20.scoreWorld(report)
	if not report.ok then
		return 35
	end
	local result = report.result or {}
	if not result.scene and not result.landmarks then
		return 75
	end
	return 100
end

function V20.scoreWorldReadiness(report)
	if not report.ok then
		return 35
	end
	local summary = report.result.summary or {}
	return V20.issueScore(summary.issueCount or 0, 7, 40)
end

function V20.scorePlaytest(report)
	if not report.ok then
		return 35
	end
	local result = report.result or {}
	local status = result.status or {}
	local sources = status.sources or {}
	local sourceCount = 0
	for _, key in ipairs({ "output", "runtimeSnapshot", "players", "characters", "worldSummary" }) do
		if sources[key] == true then
			sourceCount += 1
		end
	end
	if sourceCount >= 4 then
		return 100
	end
	return V20.clampScore(55 + sourceCount * 9)
end

function V20.scorePlaytestReadiness(report)
	if not report.ok then
		return 35
	end
	local result = report.result or {}
	local coverage = result.loopComparison and tonumber(result.loopComparison.coverage)
	local bugCount = result.bugs and tonumber(result.bugs.bugCount) or 0
	local base = coverage or (result.status and result.status.active and 70 or 60)
	return V20.clampScore(base - math.min(30, bugCount * 3))
end

function V20.scoreSystems(report)
	return V20.scoreReportHealth(report)
end

function V20.scoreBuilderReadiness(report)
	return V20.scoreReportHealth(report)
end

function V20.scoreSystemsReadiness(report)
	if not report.ok then
		return 35
	end
	local result = report.result or {}
	local recommendation = tostring(result.recommendation or result.nextAction or "")
	if recommendation ~= "" then
		return 82
	end
	return 88
end

function V20.scoreReadiness(report)
	if not report.ok then
		return 35
	end
	local result = report.result or {}
	if result.score then
		return V20.clampScore(result.score)
	end
	return 75
end

function V20.scoreRefactor(report)
	if not report.ok then
		return 35
	end
	local result = report.result or {}
	local validation = result.lastValidation or {}
	local blockers = tonumber(validation.blockers) or 0
	if blockers > 0 then
		return V20.issueScore(blockers, 20, 50)
	end
	return 100
end

function V20.gameCategory(id, title, score, command, nextAction)
	return {
		id = id,
		title = title,
		score = V20.clampScore(score),
		status = V20.statusForScore(score),
		command = command,
		nextAction = nextAction,
	}
end

function V20.averageScore(categories)
	local total = 0
	for _, category in ipairs(categories or {}) do
		total += tonumber(category.score) or 0
	end
	return V20.clampScore(total / math.max(1, #(categories or {})))
end

function V20.addRecommendation(recommendations, category, title, command, rationale, score, priority)
	if tostring(rationale or "") == "" then
		return
	end
	table.insert(recommendations, {
		category = category,
		title = title,
		command = command,
		rationale = rationale,
		score = score,
		priority = priority or 50,
	})
end

function V20.collectGameWarnings(reports)
	local warnings = {}
	if reports.project.ok then
		for _, warning in ipairs(reports.project.result.warnings or {}) do
			V20.mergeList(warnings, { tostring(warning) }, 12)
		end
	end
	if reports.ui.ok and tonumber(reports.ui.result.issueCount) and tonumber(reports.ui.result.issueCount) > 0 then
		V20.mergeList(warnings, { tostring(reports.ui.result.issueCount) .. " UI polish/readability findings." }, 12)
	end
	if reports.code.ok then
		local summary = reports.code.result.summary or {}
		local remoteIssues = tonumber(summary.remoteContractIssues) or 0
		if remoteIssues > 0 then
			V20.mergeList(warnings, { tostring(remoteIssues) .. " remote contract review items." }, 12)
		end
	end
	if reports.playtest.ok then
		local missing = reports.playtest.result.loopComparison and reports.playtest.result.loopComparison.missing or {}
		if #missing > 0 then
			V20.mergeList(warnings, { "Playtest loop evidence missing: " .. table.concat(missing, ", ") }, 12)
		end
	end
	return warnings
end

function V20.collectRecommendations(reports, gameCategories)
	local recommendations = {}
	if reports.code.ok then
		V20.addRecommendation(recommendations, "code", "Review Code Doctor guidance", "tools/bridge.cmd code doctor",
			reports.code.result.nextAction, nil, 20)
	end
	if reports.ui.ok then
		V20.addRecommendation(recommendations, "ui", "Polish UI flow/readability", "tools/bridge.cmd ui director",
			reports.ui.result.nextAction, nil, 25)
	end
	if reports.world.ok then
		V20.addRecommendation(recommendations, "world", "Review world polish", "tools/bridge.cmd world audit",
			reports.world.result.nextRecommendation, nil, 35)
	end
	if reports.systems.ok then
		V20.addRecommendation(recommendations, "systems", "Preview gameplay system plan", "tools/bridge.cmd systems report",
			reports.systems.result.nextAction or reports.systems.result.recommendation, nil, 15)
	end
	if reports.playtest.ok then
		local loop = reports.playtest.result.loopComparison or {}
		local missing = loop.missing or {}
		if #missing > 0 then
			V20.addRecommendation(recommendations, "playtest", "Run a focused QA session", "tools/bridge.cmd qa report",
				"Missing play-flow evidence: " .. table.concat(missing, ", "), nil, 10)
		end
	end
	if reports.project.ok then
		V20.addRecommendation(recommendations, "project", "Review project health", "tools/bridge.cmd project score",
			reports.project.result.nextRecommendedFix, nil, 30)
	end
	table.sort(recommendations, function(a, b)
		if (tonumber(a.priority) or 50) == (tonumber(b.priority) or 50) then
			return tostring(a.category or "") < tostring(b.category or "")
		end
		return (tonumber(a.priority) or 50) < (tonumber(b.priority) or 50)
	end)
	return recommendations
end

function V20.gameReadinessCategories(reports)
	local projectScore = reports.project.ok and tonumber(reports.project.result.score) or 35
	return {
		V20.gameCategory("project", "Project Readiness", projectScore, "tools/bridge.cmd project score",
			reports.project.ok and reports.project.result.nextRecommendedFix or nil),
		V20.gameCategory("code", "Code Readiness", V20.scoreCodeReadiness(reports.code), "tools/bridge.cmd code doctor",
			reports.code.ok and reports.code.result.nextAction or nil),
		V20.gameCategory("ui", "UI Readiness", V20.scoreUiReadiness(reports.ui), "tools/bridge.cmd ui director",
			reports.ui.ok and reports.ui.result.nextAction or nil),
		V20.gameCategory("world", "World Readiness", V20.scoreWorldReadiness(reports.world), "tools/bridge.cmd world audit",
			reports.world.ok and reports.world.result.nextRecommendation or nil),
		V20.gameCategory("playtest", "Playtest Readiness", V20.scorePlaytestReadiness(reports.playtest), "tools/bridge.cmd qa report",
			"Run a focused QA session, then compare the expected loop."),
		V20.gameCategory("build", "Build Readiness", V20.scoreReadiness(reports.readiness), "tools/bridge.cmd brain report",
			reports.readiness.ok and reports.readiness.result.nextPlan and reports.readiness.result.nextPlan.nextAction or nil),
		V20.gameCategory("systems", "Gameplay System Readiness", V20.scoreSystemsReadiness(reports.systems), "tools/bridge.cmd systems report",
			reports.systems.ok and (reports.systems.result.nextAction or reports.systems.result.recommendation) or nil),
	}
end

function V20.remainingWorkFromCompletion(gameCategories, recommendations, gameWarnings)
	local work = {}
	for _, category in ipairs(gameCategories or {}) do
		if (tonumber(category.score) or 0) < 95 then
			table.insert(work, {
				category = category.id,
				title = category.title,
				score = category.score,
				command = category.command,
				reason = category.nextAction,
			})
		end
	end
	for _, recommendation in ipairs(recommendations or {}) do
		table.insert(work, {
			category = recommendation.category,
			title = recommendation.title,
			command = recommendation.command,
			reason = recommendation.rationale,
			priority = recommendation.priority,
		})
	end
	for _, warning in ipairs(gameWarnings or {}) do
		table.insert(work, {
			category = "game",
			title = "Game follow-up",
			reason = warning,
		})
	end
	return work
end

function V20.bridgeCategory()
	local score = paired and 100 or 35
	if not running then
		score = 20
	end
	local warnings = {}
	if not paired then
		table.insert(warnings, "Studio is not paired with the local bridge.")
	end
	if State.snapshotStats and State.snapshotStats.truncated then
		table.insert(warnings, "Explorer snapshot hit the node cap; targeted reads may be better.")
	end
	return V20.category("bridge", "Bridge", score, "tools/bridge.cmd health", { ok = true }, {
		warnings = warnings,
		nextAction = paired and "Bridge is connected." or "Pair Studio with the bridge.",
	})
end

function V20.pickNextStep(categories, recommendations)
	local sorted = {}
	for _, category in ipairs(categories or {}) do
		if (tonumber(category.score) or 0) < 95 then
			table.insert(sorted, category)
		end
	end
	table.sort(sorted, function(a, b)
		return (tonumber(a.score) or 0) < (tonumber(b.score) or 0)
	end)
	local weakest = sorted[1]
	if weakest then
		local rationale = weakest.nextAction or ("Fix " .. tostring(weakest.title or weakest.id))
		return {
			category = weakest.id,
			title = "Fix " .. tostring(weakest.title or weakest.id),
			command = weakest.command,
			rationale = rationale,
			score = weakest.score,
			kind = "toolHealth",
		}
	end
	if recommendations and recommendations[1] then
		local recommendation = recommendations[1]
		return {
			category = recommendation.category,
			title = recommendation.title,
			command = recommendation.command,
			rationale = recommendation.rationale,
			score = recommendation.score,
			kind = "gameRecommendation",
		}
	end
	return {
		command = "tools/bridge.cmd dashboard",
		title = "Run dashboard",
		rationale = "Tool is healthy; review the full dashboard for optional next work.",
		kind = "toolHealth",
	}
end

function V20.getCreatorDashboard(payload)
	payload = payload or {}
	local full = payload.full == true or payload.mode == "full"
	local reliability = V21.getBridgeSelfTest({
		expectedVersion = VERSION,
		source = "dashboard",
		skipDashboardCheck = true,
	})
	local reports = {
		project = V20.safeReport("project", function()
			return V7.getProjectHealthScore(payload)
		end),
		code = V20.safeReport("code", function()
			return V13.getCodeFixDoctorReport(payload)
		end),
		ui = V20.safeReport("ui", function()
			return V11.getUiDirectorReport(payload)
		end),
		world = V20.safeReport("world", function()
			return V14.getWorldDesignAudit(payload)
		end),
		assets = V20.safeReport("assets", function()
			return V14.getAssetLibraryReport(payload)
		end),
		playtest = V20.safeReport("playtest", function()
			return V17.getPlaytestQaReport(payload)
		end),
		readiness = V20.safeReport("readiness", function()
			return V9.getBuildReadinessReport(payload)
		end),
		systems = V20.safeReport("systems", function()
			return V15.getSystemForgeReport(payload)
		end),
		refactor = V20.safeReport("refactor", function()
			return V19.getRefactorHistory(payload)
		end),
	}

	local categories = {
		V20.category("project", "Project Report", V20.scoreReportHealth(reports.project), "tools/bridge.cmd project score", reports.project, {
			nextAction = "Project report is healthy.",
		}),
		V20.category("code", "Code Intelligence", V20.scoreCode(reports.code), "tools/bridge.cmd code doctor", reports.code, {
			nextAction = "Code intelligence reports are healthy.",
		}),
		V20.category("ui", "UI Intelligence", V20.scoreUi(reports.ui), "tools/bridge.cmd ui director", reports.ui, {
			nextAction = "Deep UI reports are healthy.",
		}),
		V20.category("world", "World Intelligence", V20.scoreWorld(reports.world), "tools/bridge.cmd world audit", reports.world, {
			nextAction = "World reports are healthy.",
		}),
		V20.category("playtest", "Playtest QA", V20.scorePlaytest(reports.playtest), "tools/bridge.cmd qa report", reports.playtest, {
			nextAction = "Playtest QA sources are available.",
		}),
		V20.category("readiness", "Builder Brain", V20.scoreBuilderReadiness(reports.readiness), "tools/bridge.cmd brain report", reports.readiness, {
			nextAction = "Builder brain reports are healthy.",
		}),
		V20.category("systems", "Gameplay System Intelligence", V20.scoreSystems(reports.systems), "tools/bridge.cmd systems report", reports.systems, {
			nextAction = "Gameplay system reports are healthy.",
		}),
		V20.category("refactor", "Refactor Safety", V20.scoreRefactor(reports.refactor), "tools/bridge.cmd refactor history", reports.refactor, {
			nextAction = "Refactor safety reports are healthy.",
		}),
		V20.bridgeCategory(),
	}
	local gameCategories = V20.gameReadinessCategories(reports)
	local gameRecommendations = V20.collectRecommendations(reports, gameCategories)
	local gameCompletionWarnings = V20.collectGameWarnings(reports)
	local remainingWork = V20.remainingWorkFromCompletion(gameCategories, gameRecommendations, gameCompletionWarnings)

	local total = 0
	for _, category in ipairs(categories) do
		total += tonumber(category.score) or 0
	end
	local overallScore = V20.clampScore(total / math.max(1, #categories))
	local builderConfidenceScore = V20.averageScore(categories)
	local gameCompletionScore = V20.averageScore(gameCategories)
	table.sort(categories, function(a, b)
		return a.id < b.id
	end)
	table.sort(gameCategories, function(a, b)
		return a.id < b.id
	end)
	local weakest = nil
	for _, category in ipairs(categories) do
		if (tonumber(category.score) or 0) < 95 and (not weakest or category.score < weakest.score) then
			weakest = category
		end
	end
	local blockers = {}
	local toolWarnings = {}
	for _, category in ipairs(categories) do
		for _, blocker in ipairs(category.blockers or {}) do
			V20.mergeList(blockers, { category.title .. ": " .. tostring(blocker) }, 10)
		end
		for _, warning in ipairs(category.warnings or {}) do
			V20.mergeList(toolWarnings, { category.title .. ": " .. tostring(warning) }, 10)
		end
	end
	local nextStep = V20.pickNextStep(categories, gameRecommendations)
	local profile = V7.profileSummary(V7.profileFromPayload(payload))
	local result = {
		at = isoNow(),
		version = VERSION,
		profile = profile,
		scoreMode = "toolHealth",
		readinessMode = "builderConfidence",
		toolHealthScore = overallScore,
		builderConfidenceScore = builderConfidenceScore,
		gameReadinessScore = builderConfidenceScore,
		gameCompletionScore = gameCompletionScore,
		overallScore = overallScore,
		status = V20.statusForScore(overallScore),
		weakestCategory = weakest and {
			id = weakest.id,
			title = weakest.title,
			score = weakest.score,
		} or nil,
		categories = categories,
		gameCategories = gameCategories,
		recommendations = gameRecommendations,
		gameRecommendations = gameRecommendations,
		remainingWork = remainingWork,
		blockers = blockers,
		toolWarnings = toolWarnings,
		gameWarnings = {},
		gameCompletionWarnings = gameCompletionWarnings,
		warnings = toolWarnings,
		nextStep = nextStep,
		reliability = V21.compactSelfTest(reliability),
		bridge = {
			paired = paired,
			bridgeUrl = bridgeUrl,
			pendingCommands = #commandOrder,
			snapshot = State.snapshotStats,
			reliability = V21.compactSelfTest(reliability),
		},
		mode = full and "full" or "compact",
	}
	if full then
		result.reports = reports
	end
	V20.last.dashboard = {
		at = result.at,
		overallScore = result.overallScore,
		toolHealthScore = result.toolHealthScore,
		gameReadinessScore = result.gameReadinessScore,
		builderConfidenceScore = result.builderConfidenceScore,
		gameCompletionScore = result.gameCompletionScore,
		scoreMode = result.scoreMode,
		readinessMode = result.readinessMode,
		status = result.status,
		weakestCategory = result.weakestCategory,
		nextStep = result.nextStep,
		profile = result.profile,
		reliability = result.reliability,
	}
	table.insert(V20.history, 1, V20.last.dashboard)
	while #V20.history > 30 do
		table.remove(V20.history)
	end
	if updateRuntimeLabel then
		updateRuntimeLabel()
	end
	return result
end

