		lastDashboard = V20.last.dashboard,
	}
end

-- V21 Self-Test + Recovery Center. This stays read-only and reports tool reliability,
-- command audit history, and install hints without touching the open place.
function V21.addCheck(checks, id, title, status, message, recoveryCommand, details)
	table.insert(checks, {
		id = id,
		title = title,
		status = status,
		message = message,
		recoveryCommand = recoveryCommand,
		details = details or {},
	})
end

function V21.checkCounts(checks)
	local counts = { pass = 0, warn = 0, fail = 0 }
	for _, check in ipairs(checks or {}) do
		local status = tostring(check.status or "warn")
		if counts[status] == nil then
			counts.warn += 1
		else
			counts[status] += 1
		end
	end
	return counts
end

function V21.scoreChecks(checks)
	local counts = V21.checkCounts(checks)
	local score = 100 - (counts.fail * 25) - (counts.warn * 5)
	if score < 0 then
		score = 0
	end
	return math.floor(score + 0.5), counts
end

function V21.failedChecks(checks)
	local failed = {}
	for _, check in ipairs(checks or {}) do
		if check.status == "fail" then
			table.insert(failed, {
				id = check.id,
				title = check.title,
				message = check.message,
				recoveryCommand = check.recoveryCommand,
			})
		end
	end
	return failed
end

function V21.recoverySteps(checks)
	local steps = {}
	for _, check in ipairs(checks or {}) do
		if check.status ~= "pass" then
			table.insert(steps, {
				checkId = check.id,
				title = check.title,
				message = check.message,
				command = check.recoveryCommand or "tools/bridge.cmd doctor full",
			})
		end
	end
	if #steps == 0 then
		table.insert(steps, {
			checkId = "healthy",
			title = "Everything reachable",
			message = "Bridge, plugin, snapshots, Output, and command safety are healthy.",
			command = "tools/bridge.cmd dashboard",
		})
	end
	return steps
end

function V21.compactSelfTest(selfTest)
	if not selfTest then
		return nil
	end
	return {
		at = selfTest.at,
		version = selfTest.version,
		score = selfTest.score,
		status = selfTest.status,
		failedCount = selfTest.counts and selfTest.counts.fail or 0,
		warningCount = selfTest.counts and selfTest.counts.warn or 0,
		failedChecks = selfTest.failedChecks,
		recoveryCommand = selfTest.recoveryCommand,
		lastSuccessfulSnapshotAt = selfTest.lastSuccessfulSnapshotAt,
		lastSuccessfulOutputAt = selfTest.lastSuccessfulOutputAt,
		lastCommandAt = selfTest.lastCommandAt,
	}
end

function V21.resultSummary(result)
	if result == nil then
		return nil
	end
	if type(result) ~= "table" then
		return tostring(result)
	end
	local summary = {}
	local copied = 0
	for _, key in ipairs({ "message", "status", "score", "overallScore", "toolHealthScore", "builderConfidenceScore", "mode", "count", "created", "updated", "skipped", "failed" }) do
		if result[key] ~= nil then
			summary[key] = result[key]
			copied += 1
		end
	end
	if copied == 0 then
		summary.kind = "table"
	end
	return summary
end

function V21.addAuditRecord(record)
	record = record or {}
	local safe = {
		at = record.at or isoNow(),
		id = record.id,
		shortId = record.id and shortId(record.id) or nil,
		type = record.type,
		status = record.status,
		requiresApproval = record.requiresApproval == true,
		approvalState = record.approvalState,
		resultSummary = record.resultSummary,
		error = record.error and tostring(record.error) or nil,
		preview = record.preview,
	}
	table.insert(V21.audit, 1, safe)
	while #V21.audit > 100 do
		table.remove(V21.audit)
	end
	V21.last.commandAuditAt = safe.at
end

function V21.getBridgeSelfTest(payload)
	payload = payload or {}
	local expectedVersion = tostring(payload.expectedVersion or VERSION)
	local checks = {}
	V21.addCheck(checks, "bridgeProcess", "Bridge Process", running and "pass" or "fail",
		running and "Plugin polling loops are running." or "Plugin polling loops have stopped.",
		"Run tools\\bridge.cmd connect, then tools\\bridge.cmd always-on repair if recovery is still needed.",
		{ bridgeUrl = bridgeUrl, running = running })
	V21.addCheck(checks, "pairing", "Studio Pairing", (paired and sessionToken ~= nil and sessionToken ~= "") and "pass" or "fail",
		(paired and sessionToken ~= nil and sessionToken ~= "") and "Studio has an active bridge token." or "Studio is not paired with the bridge.",
		"Run tools\\bridge.cmd connect, open the plugin panel, and enter the pairing code.",
		{ paired = paired, hasStoredToken = sessionToken ~= nil and sessionToken ~= "" })
	V21.addCheck(checks, "pluginVersion", "Plugin Version", VERSION == expectedVersion and "pass" or "warn",
		VERSION == expectedVersion and ("Plugin version matches " .. VERSION .. ".") or ("Plugin is " .. VERSION .. ", expected " .. expectedVersion .. "."),
		"Run scripts/install-plugin.ps1, then reload Roblox Studio.",
		{ pluginVersion = VERSION, expectedVersion = expectedVersion })
	V21.addCheck(checks, "commandQueue", "Command Queue", #commandOrder <= 10 and "pass" or "warn",
		#commandOrder == 0 and "No manual fallback commands are waiting." or (tostring(#commandOrder) .. " command(s) are in the manual fallback queue."),
		"Run tools/bridge.cmd trust status; use trust on or emergency-stop depending on intent.",
		{ pendingCommands = #commandOrder })
	V21.addCheck(checks, "outputUpload", "Output Upload", paired and "pass" or "warn",
		paired and "Output capture is buffered and ready to upload." or "Output upload waits until Studio is paired.",
		"Pair Studio with the bridge, then run tools/bridge.cmd output 20.",
		{ outputBuffered = #outputBuffer, outputQueued = #outputQueue, lastOutputSentAt = State.lastOutputSentAt, lastOutputError = State.lastOutputError })
	V21.addCheck(checks, "snapshotFreshness", "Snapshot Freshness", State.snapshotStats and "pass" or "warn",
		State.snapshotStats and "Explorer snapshot data is available." or "No Explorer snapshot has been uploaded yet.",
		"Run tools/bridge.cmd tree Workspace 2 or press Force Full Snapshot in the plugin.",
		{ snapshot = State.snapshotStats, lastStateSentAt = State.lastStateSentAtIso })
	V21.addCheck(checks, "helperJson", "Helper/Profile JSON", "pass",
		"Local JSON validation is checked by tools/bridge.cmd doctor full.",
		"Run tools/bridge.cmd doctor full.",
		{ checkedBy = "helper" })
	V21.addCheck(checks, "fullTrustSafety", "Full Trust Safety", "pass",
		"Full Trust Autopilot runs local StudioBridge mutations directly and keeps external/account-level blockers.",
		"Use tools/bridge.cmd trust audit to inspect recent auto-run decisions.",
		{ pendingCommands = #commandOrder })
	if payload.skipDashboardCheck == true then
		V21.addCheck(checks, "dashboard", "Dashboard", "pass",
			"Dashboard is running this reliability check now.",
			"Run tools/bridge.cmd dashboard.",
			{ lastDashboardAt = V20.last.dashboard and V20.last.dashboard.at or nil })
	else
		V21.addCheck(checks, "dashboard", "Dashboard", "pass",
			V20.last.dashboard and "Dashboard has a recent Studio-side report." or "Dashboard command is available; no report has been requested yet this session.",
			"Run tools/bridge.cmd dashboard.",
			{ lastDashboardAt = V20.last.dashboard and V20.last.dashboard.at or nil })
	end

	local score, counts = V21.scoreChecks(checks)
	local failed = V21.failedChecks(checks)
	local result = {
		at = isoNow(),
		version = VERSION,
		score = score,
		status = V20.statusForScore(score),
		checks = checks,
		counts = counts,
		failedChecks = failed,
		recovery = V21.recoverySteps(checks),
		recoveryCommand = #failed > 0 and "tools/bridge.cmd doctor recovery" or "tools/bridge.cmd dashboard",
		pairing = {
			paired = paired,
			hasStoredToken = sessionToken ~= nil and sessionToken ~= "",
			bridgeUrl = bridgeUrl,
		},
		queue = {
			pendingCommands = #commandOrder,
			recentAuditCount = #V21.audit,
		},
		lastSuccessfulSnapshotAt = State.lastStateSentAtIso or (State.snapshotStats and State.snapshotStats.capturedAt or nil),
		lastSuccessfulOutputAt = State.lastOutputSentAt,
		lastCommandAt = V21.audit[1] and V21.audit[1].at or nil,
		dashboard = V20.last.dashboard and {
			at = V20.last.dashboard.at,
			overallScore = V20.last.dashboard.overallScore,
			status = V20.last.dashboard.status,
		} or nil,
	}
	V21.last.selfTest = result
	return result
end

function V21.getRecoveryStatus(payload)
	local selfTest = V21.getBridgeSelfTest(payload or {})
	return {
