-- V22 Fast Flow + Report Cache. These commands are read-only helpers that make
-- day-to-day status checks fast without changing the Roblox place.
function V22.compactDashboard(dashboard)
	if not dashboard then
		return nil
	end
	return {
		at = dashboard.at,
		version = dashboard.version or VERSION,
		scoreMode = dashboard.scoreMode,
		readinessMode = dashboard.readinessMode,
		toolHealthScore = dashboard.toolHealthScore or dashboard.overallScore,
		builderConfidenceScore = dashboard.builderConfidenceScore or dashboard.gameReadinessScore,
		gameReadinessScore = dashboard.gameReadinessScore,
		gameCompletionScore = dashboard.gameCompletionScore,
		overallScore = dashboard.overallScore,
		status = dashboard.status,
		weakestCategory = dashboard.weakestCategory,
		nextStep = dashboard.nextStep,
		reliability = dashboard.reliability,
	}
end

function V22.addTiming(command, status)
	local started = tonumber(command._studioReceivedClock)
	local totalMs = started and math.floor((os.clock() - started) * 1000 + 0.5) or nil
	local record = {
		at = isoNow(),
		id = command.id,
		shortId = shortId(command.id),
		type = command.type,
		status = status,
		requiresApproval = command.requiresApproval == true,
		totalMs = totalMs,
	}
	table.insert(V22.timings, 1, record)
	while #V22.timings > 100 do
		table.remove(V22.timings)
	end
	V22.last.lastCommandTiming = record
	return record
end

function V22.timingSummary(limit)
	limit = math.max(1, math.min(tonumber(limit) or 20, 100))
	local recent = {}
	local slow = {}
	local total = 0
	local counted = 0
	for index = 1, math.min(limit, #V22.timings) do
		local record = V22.timings[index]
		table.insert(recent, record)
		if tonumber(record.totalMs) then
			total += record.totalMs
			counted += 1
			if record.totalMs >= 5000 and #slow < 10 then
				table.insert(slow, record)
			end
		end
	end
	return {
		recent = recent,
		slowCommands = slow,
		averageMs = counted > 0 and math.floor(total / counted + 0.5) or nil,
		counted = counted,
	}
end

function V22.getFastDashboard(payload)
	payload = payload or {}
	local reliability = V21.compactSelfTest(V21.last.selfTest or V21.getBridgeSelfTest({
		expectedVersion = VERSION,
		source = "fastDashboard",
		skipDashboardCheck = true,
	}))
	local dashboard = V22.compactDashboard(V20.last.dashboard)
	local result
	if dashboard then
		result = {
			at = isoNow(),
			version = VERSION,
			cacheMiss = false,
			mode = "fast",
			dashboard = dashboard,
			reliability = reliability,
			nextCommand = "tools/bridge.cmd dashboard refresh",
			message = "Returned the latest Studio-side dashboard summary.",
		}
	else
		result = {
			at = isoNow(),
			version = VERSION,
			cacheMiss = true,
			mode = "fast",
			dashboard = nil,
			reliability = reliability,
			nextCommand = "tools/bridge.cmd dashboard refresh",
			message = "No dashboard summary has been computed in this Studio session yet.",
		}
	end
	V22.last.fastDashboard = result
	return result
end

function V22.getBridgePerformanceStatus(payload)
	payload = payload or {}
	local summary = V22.timingSummary(payload.limit)
	return {
		at = isoNow(),
		version = VERSION,
		paired = paired,
		pendingCommands = #commandOrder,
		outputBuffered = #outputBuffer,
		outputQueued = #outputQueue,
		lastSuccessfulSnapshotAt = State.lastSuccessfulSnapshotAt,
		lastSuccessfulOutputAt = State.lastOutputSentAt,
		lastHeavyDashboardAt = V20.last.dashboard and V20.last.dashboard.at or nil,
		lastFastDashboardAt = V22.last.fastDashboard and V22.last.fastDashboard.at or nil,
		averageCommandMs = summary.averageMs,
		slowCommands = summary.slowCommands,
		recentCommands = summary.recent,
	}
end

function V22.getCommandFlowStatus(payload)
	payload = payload or {}
	local limit = math.max(1, math.min(tonumber(payload.limit) or 25, 100))
	local pending = {}
	for _, commandId in ipairs(commandOrder) do
		local command = pendingCommands[commandId]
		if command then
			table.insert(pending, {
				id = command.id,
				shortId = shortId(command.id),
				type = command.type,
				requiresApproval = command.requiresApproval == true,
				preview = tostring(command.type or "command") .. "\n" .. shortId(command.id),
			})
		end
	end
	local audit = {}
	for index = 1, math.min(limit, #V21.audit) do
		table.insert(audit, V21.audit[index])
	end
	local timing = V22.timingSummary(limit)
	return {
		at = isoNow(),
		version = VERSION,
		pendingCount = #pending,
		pendingCommands = pending,
		audit = audit,
		averageCommandMs = timing.averageMs,
		slowCommands = timing.slowCommands,
		recentTimings = timing.recent,
	}
end

function V22.getReportCacheStatus(payload)
	payload = payload or {}
	local fast = V22.last.fastDashboard
	local dashboard = V20.last.dashboard
	return {
		at = isoNow(),
		version = VERSION,
		mode = "studio-local",
		entries = {
			{
				id = "fastDashboard",
				available = fast ~= nil,
				at = fast and fast.at or nil,
				cacheMiss = fast and fast.cacheMiss or nil,
			},
			{
				id = "creatorDashboard",
				available = dashboard ~= nil,
				at = dashboard and dashboard.at or nil,
				score = dashboard and dashboard.overallScore or nil,
			},
			{
				id = "selfTest",
				available = V21.last.selfTest ~= nil,
				at = V21.last.selfTest and V21.last.selfTest.at or nil,
				score = V21.last.selfTest and V21.last.selfTest.score or nil,
			},
		},
		nextCommand = dashboard and "tools/bridge.cmd dashboard quick" or "tools/bridge.cmd dashboard refresh",
	}
end

