function V23.findPaletteGroup(goal)
	goal = string.lower(tostring(goal or ""))
	if goal == "" then
		return nil
	end
	for _, group in ipairs(V23.commandPalette()) do
		if group.id == goal then
			return group
		end
		if string.find(string.lower(group.title), goal, 1, true) then
			return group
		end
	end
	if goal == "build" then
		return V23.findPaletteGroup("systems")
	end
	if goal == "launch" or goal == "launch-qa" or goal == "test" then
		return V23.findPaletteGroup("qa")
	end
	if goal == "patch" or goal == "patching" then
		return V23.findPaletteGroup("code")
	end
	return nil
end

function V23.getCommandPalette(payload)
	payload = payload or {}
	local goal = payload.goal or payload.query or payload.category
	local group = V23.findPaletteGroup(goal)
	local result = {
		at = isoNow(),
		version = VERSION,
		goal = goal,
		groups = group and { group } or V23.commandPalette(),
		nextCommand = group and group.commands[1] or "tools/bridge.cmd next",
	}
	V23.last.palette = result
	return result
end

function V23.getNextBestCommand(payload)
	payload = payload or {}
	local fast = V22.getFastDashboard(payload)
	local flow = V22.getCommandFlowStatus({ limit = 10 })
	local nextStep = fast.dashboard and fast.dashboard.nextStep or nil
	local command = nextStep and nextStep.command or fast.nextCommand or "tools/bridge.cmd dashboard refresh"
	local title = nextStep and nextStep.title or "Refresh dashboard"
	local rationale = nextStep and nextStep.rationale or fast.message or "Refresh the dashboard so later commands can use fast cached context."
	if flow.pendingCount and flow.pendingCount > 0 then
		command = "tools/bridge.cmd commands flow"
		title = "Review pending commands"
		rationale = tostring(flow.pendingCount) .. " command(s) are waiting or recently active."
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		command = command,
		title = title,
		rationale = rationale,
		source = fast.cacheMiss and "fastDashboardMiss" or "fastDashboard",
		flow = {
			pendingCount = flow.pendingCount,
			averageCommandMs = flow.averageCommandMs,
		},
	}
	V23.last.next = result
	return result
end

function V23.topProfilePaths(profile)
	local paths = {}
	local expected = profile and profile.expected or {}
	for _, item in ipairs(expected.paths or {}) do
		if #paths >= 12 then
			return paths
		end
		table.insert(paths, tostring(item.path or item))
	end
	for _, path in ipairs(expected.uiRoots or {}) do
		if #paths >= 12 then
			return paths
		end
		table.insert(paths, tostring(path))
	end
	for _, path in ipairs(expected.workspace or {}) do
		if #paths >= 12 then
			return paths
		end
		table.insert(paths, tostring(path))
	end
	return paths
end

function V23.compactAudit(records, limit)
	limit = limit or 20
	local compact = {}
	local seen = {}
	for _, record in ipairs(records or {}) do
		local id = record and record.id
		if id and not seen[id] then
			seen[id] = true
			table.insert(compact, record)
			if #compact >= limit then
				break
			end
		end
	end
	return compact
end

function V23.getHandoffPack(payload)
	payload = payload or {}
	local profile = V7.profileFromPayload(payload)
	local profileSummary = V7.profileSummary(profile)
	local fast = V22.getFastDashboard(payload)
	local selfTest = V21.compactSelfTest(V21.last.selfTest or V21.getBridgeSelfTest({
		expectedVersion = VERSION,
		skipDashboardCheck = true,
	}))
	local outputErrors = getOutputErrors({ limit = payload.full and 30 or 10 })
	local flow = V22.getCommandFlowStatus({ limit = payload.full and 30 or 12 })
	local recentCommands = V23.compactAudit(flow.audit, payload.full and 30 or 12)
	local cache = V22.getReportCacheStatus(payload)
	local next = V23.getNextBestCommand(payload)
	local pack = {
		at = isoNow(),
		version = VERSION,
		mode = payload.full and "full" or "compact",
		place = {
			name = game.Name,
			placeId = game.PlaceId,
			gameId = game.GameId,
			jobId = game.JobId,
		},
		bridge = {
			bridgeUrl = bridgeUrl,
			paired = paired,
			hasStoredToken = sessionToken ~= nil and sessionToken ~= "",
			contextId = contextId,
		},
		profile = profileSummary,
		memory = {
			currentFocus = payload.memory and payload.memory.currentFocus or nil,
			activeProfileId = payload.memory and payload.memory.activeProfileId or nil,
			activeMode = payload.memory and payload.memory.activeMode or nil,
		},
		dashboard = fast.dashboard,
		reliability = selfTest,
		next = next,
		topPaths = V23.topProfilePaths(profile),
		recentOutputErrors = outputErrors.groups or outputErrors.errors or {},
		commandFlow = {
			pendingCount = flow.pendingCount,
			averageCommandMs = flow.averageCommandMs,
			recent = recentCommands,
			slowCommands = flow.slowCommands,
		},
		cache = cache,
		safetyRules = {
			"Reads run automatically; Studio mutations require plugin approval.",
			"No V23 command mutates the Roblox place.",
			"Script edits require backups and expected source hashes.",
			"Local handoff/session exports are written only under .codex-studio/.",
		},
		recommendedCommands = {
			next.command,
			"tools/bridge.cmd dashboard quick",
			"tools/bridge.cmd palette",
			"tools/bridge.cmd session summary",
		},
	}
	if payload.full then
		pack.palette = V23.commandPalette()
		pack.session = V23.getSessionSummary(payload)
	end
	V23.last.handoff = {
		at = pack.at,
		mode = pack.mode,
		nextCommand = next.command,
		profile = profileSummary,
	}
	return pack
end

function V23.getSessionSummary(payload)
	payload = payload or {}
	local flow = V22.getCommandFlowStatus({ limit = payload.limit or 30 })
	local recentCommands = V23.compactAudit(flow.audit, payload.limit or 30)
	local statusCounts = {}
	for _, record in ipairs(recentCommands) do
		local status = tostring(record.status or "unknown")
		statusCounts[status] = (statusCounts[status] or 0) + 1
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		pendingCount = flow.pendingCount,
		statusCounts = statusCounts,
		recentCommands = recentCommands,
		slowCommands = flow.slowCommands,
		averageCommandMs = flow.averageCommandMs,
		cache = V22.getReportCacheStatus(payload),
		performance = V22.getBridgePerformanceStatus(payload),
		next = V23.getNextBestCommand(payload),
	}
	V23.last.session = result
	return result
end

function V23.getWorkflowGuide(payload)
	payload = payload or {}
	local goal = payload.goal or payload.query or "health"
	local group = V23.findPaletteGroup(goal) or V23.findPaletteGroup("health")
	local steps = {}
	for index, command in ipairs(group.commands or {}) do
		table.insert(steps, {
			step = index,
			command = command,
		})
	end
	return {
		at = isoNow(),
		version = VERSION,
		goal = goal,
		title = group.title,
		steps = steps,
		firstCommand = group.commands and group.commands[1] or "tools/bridge.cmd next",
		safety = "Preview/read commands are automatic; apply/build/patch commands run under Full Trust and are audited.",
	}
end

-- V24 Project Package + Migration Kit. Read-only Studio summaries that helper
-- commands combine with local .codex-studio package import/export workflows.
function V24.safeReport(name, callback)
	local ok, result = pcall(callback)
	if ok then
		return {
			ok = true,
			name = name,
			result = result,
		}
	end
	return {
		ok = false,
		name = name,
		error = tostring(result),
	}
end

function V24.countArray(value)
	if type(value) == "table" then
		return #value
	end
	return 0
end

function V24.catalogSummary(payload)
	payload = payload or {}
	return {
		templates = V24.countArray(payload.templates or payload.templateCatalog),
		kits = V24.countArray(payload.kits or payload.kitCatalog),
		systems = V24.countArray(payload.systems or payload.systemCatalog),
		milestones = V24.countArray(payload.milestones or payload.milestoneCatalog),
		profiles = V24.countArray(payload.profiles),
	}
end

function V24.profileIds(payload)
	local ids = {}
	for _, profile in ipairs(V7.profilesFromPayload(payload)) do
		table.insert(ids, tostring(profile.id or "unknown"))
	end
	return ids
end

function V24.summaryFromReport(report, keys)
	if not report or not report.ok or type(report.result) ~= "table" then
		return {
			ok = report and report.ok == true or false,
			error = report and report.error or nil,
		}
	end
	local result = {
		ok = true,
	}
	for _, key in ipairs(keys or {}) do
		result[key] = report.result[key]
	end
	return result
end

function V24.getProjectImportScan(payload)
	payload = payload or {}
	local profile = V7.profileFromPayload(payload)
	local detection = V24.safeReport("detectProjectProfile", function()
		return V7.detectProjectProfile(payload)
	end)
	local health = V24.safeReport("getProjectHealthScore", function()
		return V7.getProjectHealthScore(payload)
	end)
	local scripts = V24.safeReport("getScriptMap", function()
		return V12.getScriptMap(payload)
	end)
	local ui = V24.safeReport("getDeepUiInventory", function()
		return V11.getDeepUiInventory({ depth = 10, maxNodes = 3000 })
	end)
	local world = V24.safeReport("getRuntimeWorldSummary", function()
		return V8.getRuntimeWorldSummary(payload)
	end)
	local nextCommand = V23.getNextBestCommand(payload)
	local result = {
		at = isoNow(),
		version = VERSION,
		place = {
			name = game.Name,
			placeId = game.PlaceId,
			gameId = game.GameId,
			jobId = game.JobId,
		},
		activeProfile = V7.profileSummary(profile),
		detection = detection.ok and detection.result or detection,
		summaries = {
			explorer = {
				ok = true,
				nodeCount = State.snapshotStats and State.snapshotStats.nodeCount or nil,
				scriptCount = State.snapshotStats and State.snapshotStats.scriptCount or nil,
				truncated = State.snapshotStats and State.snapshotStats.truncated or nil,
				capturedAt = State.snapshotStats and State.snapshotStats.capturedAt or nil,
			},
			project = V24.summaryFromReport(health, { "score", "status", "nextRecommendedFix", "blockers", "warnings" }),
			scripts = V24.summaryFromReport(scripts, { "scriptCount", "totalScripts", "moduleCount", "disabledCount", "groups" }),
			ui = V24.summaryFromReport(ui, { "nodeCount", "screenCount", "rootCount", "maxDepth", "issues" }),
			world = V24.summaryFromReport(world, { "contextType", "bounds", "counts", "landmarks", "issues" }),
		},
		catalogs = V24.catalogSummary(payload),
		firstCommands = {
			nextCommand.command,
			"tools/bridge.cmd dashboard quick",
			"tools/bridge.cmd project score",
			"tools/bridge.cmd palette",
			"tools/bridge.cmd handoff markdown",
		},
		next = nextCommand,
		safety = "Read-only import scan. No Roblox Studio objects are changed.",
	}
	V24.last.importScan = result
	return result
end

function V24.getProjectPackageStatus(payload)
	payload = payload or {}
	local memory = type(payload.memory) == "table" and payload.memory or {}
	local result = {
		at = isoNow(),
		version = VERSION,
		placeKey = payload.placeKey,
		activeProfile = V7.profileSummary(V7.profileFromPayload(payload)),
		memory = {
			available = next(memory) ~= nil,
			activeProfileId = memory.activeProfileId,
			activeMode = memory.activeMode,
			currentFocus = memory.currentFocus,
			goalCount = V24.countArray(memory.goals),
			styleNoteCount = V24.countArray(memory.styleNotes or memory.stylePreferences),
			protectedPathCount = V24.countArray(memory.protectedPaths),
			knownIssueCount = V24.countArray(memory.knownIssues),
			recentDecisionCount = V24.countArray(memory.recentDecisions),
		},
		catalogs = V24.catalogSummary(payload),
		cache = V22.getReportCacheStatus(payload),
		lastHandoff = V23.last.handoff,
		lastImportScan = V24.last.importScan and {
			at = V24.last.importScan.at,
			profile = V24.last.importScan.activeProfile,
		} or nil,
		safety = {
			"V24 pack commands write local .codex-studio files only.",
			"V24 adds no Roblox Studio mutation command.",
			"Existing apply/build/patch commands run directly under Full Trust and remain audited.",
		},
	}
	V24.last.packageStatus = result
	return result
end

