function V24.getProfileMigrationGuide(payload)
	payload = payload or {}
	local profiles = V7.profilesFromPayload(payload)
	local sourceId = tostring(payload.sourceProfileId or "ruleforge")
	local source = nil
	local targets = {}
	for _, profile in ipairs(profiles) do
		if tostring(profile.id or "") == sourceId then
			source = profile
		else
			table.insert(targets, profile)
		end
	end
	local suggestions = {}
	for _, profile in ipairs(targets) do
		local missing = {}
		if type(profile.expectedLoop) ~= "table" then
			table.insert(missing, "expectedLoop")
		end
		if type(profile.uiActions) ~= "table" then
			table.insert(missing, "uiActions")
		end
		if type(profile.featureTemplates) ~= "table" or #profile.featureTemplates == 0 then
			table.insert(missing, "featureTemplates")
		end
		if type(profile.styleGuide) ~= "table" then
			table.insert(missing, "styleGuide")
		end
		table.insert(suggestions, {
			profile = V7.profileSummary(profile),
			missingOrThinFields = missing,
			recommendation = #missing > 0 and "Add portable defaults inspired by proven stress-test fields." or "Profile already has the core V24 portability fields.",
		})
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		sourceProfile = source and V7.profileSummary(source) or nil,
		profiles = V24.profileIds(payload),
		suggestions = suggestions,
		output = "Suggestion-only. Helper save writes under .codex-studio/profile-suggestions/.",
	}
	V24.last.profileMigration = result
	return result
end

function V24.getTemplateRecommendationReport(payload)
	payload = payload or {}
	local profile = V7.profileFromPayload(payload)
	local genre = string.lower(tostring(profile.genre or "general"))
	local profileId = string.lower(tostring(profile.id or "universal"))
	local recommendations = {}
	for _, item in ipairs(payload.templates or payload.templateCatalog or {}) do
		local itemGenre = string.lower(tostring(item.genre or "general"))
		local score = 20
		if itemGenre == genre or string.find(genre, itemGenre, 1, true) or string.find(itemGenre, profileId, 1, true) then
			score = 100
		elseif itemGenre == "general" or itemGenre == "universal" then
			score = 80
		elseif profileId == "universal" then
			score = 70
		end
		table.insert(recommendations, {
			id = item.id,
			title = item.title,
			genre = item.genre,
			file = item.file,
			score = score,
		})
	end
	table.sort(recommendations, function(a, b)
		if a.score == b.score then
			return tostring(a.id) < tostring(b.id)
		end
		return a.score > b.score
	end)
	local result = {
		at = isoNow(),
		version = VERSION,
		activeProfile = V7.profileSummary(profile),
		recommendations = recommendations,
		topRecommendation = recommendations[1],
		kitsAvailable = V24.countArray(payload.kits or payload.kitCatalog),
		systemsAvailable = V24.countArray(payload.systems or payload.systemCatalog),
		nextCommand = recommendations[1] and ("tools/bridge.cmd template preview " .. tostring(recommendations[1].id)) or "tools/bridge.cmd template list",
	}
	V24.last.templateRecommendation = result
	return result
end

-- V25 Live Test Vision Harness. Structured "what the player sees" reports are
-- read-only; harness install/capture requests run under Full Trust with audit logging.
function V25.liveHarnessPaths()
	return {
		"ReplicatedStorage.CodexLiveVisionHarness",
		"ReplicatedStorage.CodexLiveVisionHarness.CaptureRequested",
		"ReplicatedStorage.CodexLiveVisionHarness.LastCaptureRequest",
		"StarterPlayer.StarterPlayerScripts.CodexLiveVisionClient",
		"ServerScriptService.CodexLiveVisionRelay",
		"StarterGui.CodexLiveVisionOverlay",
	}
end

function V25.getHarnessStatus()
	local paths = {}
	local installedCount = 0
	for _, path in ipairs(V25.liveHarnessPaths()) do
		local instance = resolvePath(path)
		if instance then
			installedCount += 1
		end
		table.insert(paths, {
			path = path,
			exists = instance ~= nil,
			id = instance and getInstanceId(instance) or nil,
			className = instance and instance.ClassName or nil,
		})
	end
	return {
		at = isoNow(),
		installed = installedCount == #paths,
		partial = installedCount > 0 and installedCount < #paths,
		installedCount = installedCount,
		paths = paths,
	}
end

function V25.captureMarkers(limit)
	limit = math.max(1, math.min(tonumber(limit) or 30, 100))
	local markers = {}
	for index = #outputBuffer, 1, -1 do
		local entry = outputBuffer[index]
		local message = tostring(entry and entry.message or "")
		if string.find(message, "[CodexLiveVisionHarness]", 1, true) or string.find(message, "[CodexLiveVision]", 1, true) then
			table.insert(markers, entry)
			if #markers >= limit then
				break
			end
		end
	end
	return markers
end

