function V25.readGuiMetric(instance, propertyName)
	local ok, value = pcall(function()
		return instance[propertyName]
	end)
	if ok then
		return serializeValue(value)
	end
	return nil
end

function V25.visibleGuiElements(payload)
	payload = payload or {}
	local maxElements = math.max(20, math.min(tonumber(payload.maxElements) or 120, 500))
	local roots = {}
	local function addRoot(instance, source)
		if instance then
			table.insert(roots, { instance = instance, source = source })
		end
	end
	addRoot(game:GetService("StarterGui"), "StarterGui")
	for _, player in ipairs(Players:GetPlayers()) do
		addRoot(player:FindFirstChildOfClass("PlayerGui"), "PlayerGui:" .. player.Name)
	end

	local elements = {}
	local counts = {
		roots = #roots,
		screenGuis = 0,
		guiObjects = 0,
		buttons = 0,
		textObjects = 0,
		images = 0,
		visible = 0,
		hidden = 0,
	}
	for _, root in ipairs(roots) do
		for _, descendant in ipairs(root.instance:GetDescendants()) do
			if descendant:IsA("ScreenGui") then
				counts.screenGuis += 1
			end
			if descendant:IsA("GuiObject") then
				counts.guiObjects += 1
				local visible = true
				pcall(function()
					visible = descendant.Visible
				end)
				if visible then
					counts.visible += 1
				else
					counts.hidden += 1
				end
				if descendant:IsA("TextButton") or descendant:IsA("ImageButton") then
					counts.buttons += 1
				end
				if descendant:IsA("TextLabel") or descendant:IsA("TextButton") or descendant:IsA("TextBox") then
					counts.textObjects += 1
				end
				if descendant:IsA("ImageLabel") or descendant:IsA("ImageButton") then
					counts.images += 1
				end
				if visible and #elements < maxElements then
					local text = nil
					if descendant:IsA("TextLabel") or descendant:IsA("TextButton") or descendant:IsA("TextBox") then
						pcall(function()
							text = V9.trimText(descendant.Text, 120)
						end)
					end
					table.insert(elements, {
						id = getInstanceId(descendant),
						source = root.source,
						name = descendant.Name,
						className = descendant.ClassName,
						path = safeFullName(descendant),
						text = text,
						visible = true,
						position = V25.readGuiMetric(descendant, "Position"),
						size = V25.readGuiMetric(descendant, "Size"),
						absolutePosition = V25.readGuiMetric(descendant, "AbsolutePosition"),
						absoluteSize = V25.readGuiMetric(descendant, "AbsoluteSize"),
						zIndex = V25.readGuiMetric(descendant, "ZIndex"),
					})
				end
			end
		end
	end
	return elements, counts
end

function V25.getVisibleUiReport(payload)
	payload = payload or {}
	local elements, counts = V25.visibleGuiElements(payload)
	local deep = V11.getDeepUiInventory({
