end

function V25.nearbyWorldObjects(camera, payload)
	payload = payload or {}
	local maxObjects = math.max(10, math.min(tonumber(payload.maxObjects) or 80, 300))
	local maxDistance = math.max(50, math.min(tonumber(payload.maxDistance) or 500, 3000))
	local objects = {}
	if not camera then
		return objects
	end
	local origin = camera.CFrame.Position
	local look = camera.CFrame.LookVector
	for _, descendant in ipairs(workspace:GetDescendants()) do
		if descendant:IsA("BasePart") then
			local offset = descendant.Position - origin
			local distance = offset.Magnitude
			if distance <= maxDistance then
				local dot = 0
				if distance > 0 then
					dot = look:Dot(offset.Unit)
				end
				if dot > -0.15 then
					table.insert(objects, {
						id = getInstanceId(descendant),
						name = descendant.Name,
						className = descendant.ClassName,
						path = safeFullName(descendant),
						distance = math.floor(distance + 0.5),
						inFrontScore = dot,
						position = serializeValue(descendant.Position),
						size = serializeValue(descendant.Size),
						material = serializeValue(descendant.Material),
						color = serializeValue(descendant.Color),
					})
				end
			end
		end
	end
	table.sort(objects, function(a, b)
		if a.inFrontScore == b.inFrontScore then
			return a.distance < b.distance
		end
		return a.inFrontScore > b.inFrontScore
	end)
	while #objects > maxObjects do
		table.remove(objects)
	end
	return objects
end

