end

function V25.getScreenCompositionReport(payload)
	payload = payload or {}
	local awareness = V27 and V27.bridgeGet and V27.bridgeGet("/codex/awareness") or nil
	local pulse = awareness and (awareness.latest or awareness.latestAny) or nil
	local freshLive = awareness and awareness.status and awareness.status.fresh == true
		and pulse and pulse.contextType and string.find(string.lower(tostring(pulse.contextType)), "client", 1, true) ~= nil
	if freshLive and (pulse.ui or pulse.camera) then
		local ui = pulse.ui or {}
		local clickTargets = type(ui.clickTargets) == "table" and ui.clickTargets or {}
		local result = {
			at = isoNow(),
			version = VERSION,
			contextType = pulse.contextType or "testClient",
			source = "realtimeAwareness",
			camera = pulse.camera,
			nearbyWorld = pulse.world and pulse.world.nearby or {},
			visibleUi = {
				counts = {
					screenCount = ui.screenCount or 0,
					visible = ui.visibleObjects or 0,
					buttons = ui.buttons or #clickTargets,
					textObjects = ui.textObjects or 0,
				},
				elements = clickTargets,
				texts = ui.texts,
			},
			actors = {
				playerCount = pulse.player and 1 or 0,
				players = pulse.player and { pulse.player } or {},
				npcCount = 0,
			},
			warnings = {},
			summary = {
				uiVisibleCount = ui.visibleObjects or 0,
				nearbyWorldCount = pulse.world and type(pulse.world.nearby) == "table" and #pulse.world.nearby or 0,
				playerCount = pulse.player and 1 or 0,
				warningCount = 0,
			},
		}
		V25.last.screen = result
		return result
	end
	local camera = V25.getCameraViewReport(payload)
	local ui = V25.getVisibleUiReport(payload)
	local actors = V8.getRuntimeActors({ maxNpcs = 30 })
	local warnings = {}
	if not camera.camera then
		table.insert(warnings, "No active camera was available.")
	end
	if actors.playerCount == 0 then
		table.insert(warnings, "No players are visible to this plugin context.")
	end
	if ui.counts.visible == 0 then
		table.insert(warnings, "No visible GuiObject elements were found.")
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		contextType = V6.detectLocalContextType(),
		camera = camera.camera,
		nearbyWorld = camera.nearbyWorld,
		visibleUi = {
			counts = ui.counts,
			elements = ui.elements,
		},
		actors = {
			playerCount = actors.playerCount,
			players = actors.players,
			npcCount = actors.npcCount,
		},
		warnings = warnings,
		summary = {
			uiVisibleCount = ui.counts.visible,
			nearbyWorldCount = #camera.nearbyWorld,
			playerCount = actors.playerCount,
			warningCount = #warnings,
		},
	}
	V25.last.screen = result
	return result
end

function V25.getVisionQaReport(payload)
	payload = payload or {}
	local profile = V7.profileFromPayload(payload)
	local screen = V25.getScreenCompositionReport(payload)
	local haystack = ""
	for _, element in ipairs(screen.visibleUi.elements or {}) do
		haystack = haystack .. " " .. string.lower(tostring(element.name or "") .. " " .. tostring(element.text or "") .. " " .. tostring(element.path or ""))
	end
	local checks = {}
	local function addCheck(id, title, passed, command)
		table.insert(checks, {
			id = id,
			title = title,
			passed = passed,
			command = command,
		})
	end
	addCheck("camera", "Camera context available", screen.camera ~= nil, "tools/bridge.cmd live-vision camera")
	addCheck("visibleUi", "Visible UI can be inspected", screen.visibleUi.counts.visible > 0, "tools/bridge.cmd live-vision ui")
	addCheck("players", "Player/runtime actors visible", screen.actors.playerCount > 0, "tools/bridge.cmd actors")
	addCheck("objectiveText", "Objective-like UI is visible", haystack:find("objective", 1, true) ~= nil or haystack:find("quest", 1, true) ~= nil, "tools/bridge.cmd ui flow")
	addCheck("rewardReplayText", "Reward/replay feedback is visible", haystack:find("reward", 1, true) ~= nil or haystack:find("replay", 1, true) ~= nil or haystack:find("again", 1, true) ~= nil, "tools/bridge.cmd live-vision screen")
	local failed = {}
	for _, check in ipairs(checks) do
		if not check.passed then
			table.insert(failed, check)
		end
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		profile = V7.profileSummary(profile),
		status = #failed == 0 and "good" or "needsEvidence",
		checks = checks,
		failed = failed,
		screenSummary = screen.summary,
		nextCommand = failed[1] and failed[1].command or "tools/bridge.cmd live-vision snapshot",
		message = #failed == 0 and "Live vision has enough UI/game evidence for this pass." or "Live vision is missing some player-facing evidence.",
	}
	V25.last.qa = result
	return result
end

