function V25.liveVisionClientSource()
	return "local ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal Workspace = game:GetService(\"Workspace\")\nlocal CaptureService = game:GetService(\"CaptureService\")\nlocal folder = ReplicatedStorage:WaitForChild(\"CodexLiveVisionHarness\", 10)\nlocal remote = folder and folder:FindFirstChild(\"CaptureRequested\")\nlocal requestValue = folder and folder:FindFirstChild(\"LastCaptureRequest\")\nlocal lastRequest = \"\"\nlocal function cameraLine(prefix)\n\tlocal camera = Workspace.CurrentCamera\n\tif camera then\n\t\tprint(\"[CodexLiveVisionHarness] \" .. prefix .. \" camera\", tostring(camera.CFrame.Position), tostring(camera.FieldOfView), tostring(camera.ViewportSize))\n\telse\n\t\tprint(\"[CodexLiveVisionHarness] \" .. prefix .. \" camera unavailable\")\n\tend\nend\nprint(\"[CodexLiveVisionHarness] client ready\")\ncameraLine(\"ready\")\nlocal function capture(requestId, source)\n\trequestId = tostring(requestId or \"\")\n\tif requestId == \"\" then return end\n\tif requestId == lastRequest and source ~= \"remote\" then return end\n\tlastRequest = requestId\n\tprint(\"[CodexLiveVisionHarness] capture requested\", requestId, tostring(source or \"unknown\"))\n\tcameraLine(\"capture\")\n\tlocal ok = pcall(function()\n\t\tCaptureService:TakeScreenshotCaptureAsync(function(result, screenshotCapture)\n\t\t\tprint(\"[CodexLiveVisionHarness] capture result\", tostring(result), tostring(screenshotCapture))\n\t\tend, { UICaptureMode = Enum.UICaptureMode.All })\n\tend)\n\tif not ok then\n\t\tlocal fallbackOk = pcall(function()\n\t\t\tCaptureService:CaptureScreenshot(function(contentId)\n\t\t\t\tprint(\"[CodexLiveVisionHarness] capture fallback\", tostring(contentId))\n\t\t\tend)\n\t\tend)\n\t\tif not fallbackOk then\n\t\t\tprint(\"[CodexLiveVisionHarness] capture unavailable; structured fallback remains active\")\n\t\tend\n\tend\nend\nif remote then\n\tremote.OnClientEvent:Connect(function(requestId)\n\t\tcapture(requestId, \"remote\")\n\tend)\nelse\n\tprint(\"[CodexLiveVisionHarness] CaptureRequested remote missing\")\nend\nif requestValue then\n\trequestValue:GetPropertyChangedSignal(\"Value\"):Connect(function()\n\t\tcapture(requestValue.Value, \"value\")\n\tend)\n\ttask.spawn(function()\n\t\twhile true do\n\t\t\ttask.wait(1)\n\t\t\tcapture(requestValue.Value, \"poll\")\n\t\tend\n\tend)\nelse\n\tprint(\"[CodexLiveVisionHarness] LastCaptureRequest value missing\")\nend\n"
end

function V25.liveVisionRelaySource()
	return "local HttpService = game:GetService(\"HttpService\")\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal folder = ReplicatedStorage:WaitForChild(\"CodexLiveVisionHarness\", 10)\nlocal remote = folder and folder:FindFirstChild(\"CaptureRequested\")\nlocal requestValue = folder and folder:FindFirstChild(\"LastCaptureRequest\")\nlocal lastRequest = \"\"\nlocal endpoint = \"http://127.0.0.1:28123/runtime/live-vision/capture-requests\"\nlocal warnedHttp = false\nlocal function send(requestId, source)\n\trequestId = tostring(requestId or \"\")\n\tif requestId == \"\" or requestId == lastRequest then return end\n\tif not remote or not remote:IsA(\"RemoteEvent\") then\n\t\tprint(\"[CodexLiveVisionHarness] relay missing CaptureRequested remote\")\n\t\treturn\n\tend\n\tlastRequest = requestId\n\tprint(\"[CodexLiveVisionHarness] relay capture\", requestId, tostring(source or \"unknown\"))\n\tremote:FireAllClients(requestId)\nend\nlocal function relayValue(source)\n\tif requestValue then\n\t\tsend(requestValue.Value, source or \"value\")\n\tend\nend\nlocal function pollBridge()\n\tlocal ok, bodyOrErr = pcall(function()\n\t\treturn HttpService:GetAsync(endpoint, false)\n\tend)\n\tif not ok then\n\t\tif not warnedHttp then\n\t\t\twarnedHttp = true\n\t\t\tprint(\"[CodexLiveVisionHarness] bridge poll unavailable\", tostring(bodyOrErr))\n\t\tend\n\t\treturn\n\tend\n\tlocal decodedOk, data = pcall(function()\n\t\treturn HttpService:JSONDecode(bodyOrErr)\n\tend)\n\tif decodedOk and type(data) == \"table\" and type(data.latest) == \"table\" then\n\t\tsend(data.latest.requestId, \"bridge\")\n\tend\nend\nprint(\"[CodexLiveVisionHarness] relay ready\")\nif requestValue then\n\trequestValue:GetPropertyChangedSignal(\"Value\"):Connect(function()\n\t\trelayValue(\"changed\")\n\tend)\nend\ntask.spawn(function()\n\twhile true do\n\t\ttask.wait(1)\n\t\trelayValue(\"poll\")\n\t\tpollBridge()\n\tend\nend)\n"
end

function V25.scriptWriteStep(path, className, source)
	local step = {
		type = "writeScript",
		path = path,
		className = className,
		source = source,
		overwrite = true,
	}
	local existing = resolvePath(path)
	if existing and existing:IsA("LuaSourceContainer") then
		step.expectedSourceHash = sourceHash(readScriptSource(existing))
	end
	return step
end

function V25.liveVisionHarnessBlueprint(payload)
	payload = payload or {}
	local profile = V7.profileFromPayload(payload)
	return {
		name = "Codex Live Vision Harness",
		mode = "supervised",
		source = "installLiveVisionHarness",
		steps = {
			{ type = "ensureFolder", path = "ReplicatedStorage.CodexLiveVisionHarness" },
			{ type = "ensureRemoteEvent", path = "ReplicatedStorage.CodexLiveVisionHarness.CaptureRequested" },
			{ type = "ensureInstance", path = "ReplicatedStorage.CodexLiveVisionHarness.LastCaptureRequest", className = "StringValue", properties = { Value = "" } },
			{ type = "ensureInstance", path = "StarterGui.CodexLiveVisionOverlay", className = "ScreenGui", properties = { ResetOnSpawn = false, Enabled = false } },
			V25.scriptWriteStep("StarterPlayer.StarterPlayerScripts.CodexLiveVisionClient", "LocalScript", V25.liveVisionClientSource()),
			V25.scriptWriteStep("ServerScriptService.CodexLiveVisionRelay", "Script", V25.liveVisionRelaySource()),
			{
				type = "writeScript",
				path = "ReplicatedStorage.CodexLiveVisionHarness.Manifest",
				className = "ModuleScript",
				source = "return { name = \"CodexLiveVisionHarness\", version = \"" .. VERSION .. "\", profile = \"" .. V8.luaString(profile.id or "universal") .. "\" }\n",
				overwrite = true,
				expectedSourceHash = (function()
					local existing = resolvePath("ReplicatedStorage.CodexLiveVisionHarness.Manifest")
					if existing and existing:IsA("LuaSourceContainer") then
						return sourceHash(readScriptSource(existing))
					end
					return nil
				end)(),
			},
		},
	}
end

function V25.installLiveVisionHarness(payload)
	local blueprint = normalizeBlueprint(payload or {}) or V25.liveVisionHarnessBlueprint(payload or {})
	local result = applyBuildPlan({ blueprint = blueprint })
	result.kind = "liveVisionHarnessInstall"
	result.harness = V25.getHarnessStatus()
	return result
end

function V25.removeLiveVisionHarness(payload)
	return withUndo("RemoveLiveVisionHarness", function()
		local result = { appliedAt = isoNow(), removed = {}, missing = {}, failed = {} }
		local roots = {
			"ReplicatedStorage.CodexLiveVisionHarness",
			"StarterPlayer.StarterPlayerScripts.CodexLiveVisionClient",
			"ServerScriptService.CodexLiveVisionRelay",
			"StarterGui.CodexLiveVisionOverlay",
		}
		for _, path in ipairs(roots) do
			local instance = resolvePath(path)
			if instance then
				local ok, err = pcall(function()
					instance:Destroy()
				end)
				if ok then
					table.insert(result.removed, { path = path })
				else
					table.insert(result.failed, { path = path, message = tostring(err) })
				end
			else
				table.insert(result.missing, { path = path })
			end
		end
		result.summary = { removed = #result.removed, missing = #result.missing, failed = #result.failed }
		stateDirty = true
		result.harness = V25.getHarnessStatus()
		return result
	end)
end

function V25.requestLiveVisionCapture(payload)
	payload = payload or {}
	return withUndo("RequestLiveVisionCapture", function()
		local folder = resolvePath("ReplicatedStorage.CodexLiveVisionHarness")
		if not folder then
			error("CodexLiveVisionHarness is not installed. Run live-vision harness install first.")
		end
		local requestId = tostring(payload.requestId or HttpService:GenerateGUID(false))
		local value = folder:FindFirstChild("LastCaptureRequest")
		if not value then
			value = Instance.new("StringValue")
			value.Name = "LastCaptureRequest"
			value.Parent = folder
		end
		value.Value = requestId
		local result = {
			at = isoNow(),
			requestId = requestId,
			recorded = true,
			message = "Capture request approved. The live vision relay will poll the bridge and forward it to clients during Play mode.",
		}
		V25.last.captureRequest = result
		addOutput("[CodexLiveVision] capture request " .. requestId .. " approved for bridge relay", "Info", "CodexStudioBridge")
		return result
	end)
end

function V26.statusEntry(id, title, installed, status)
	return {
		id = id,
		title = title,
		installed = installed == true,
		status = status or (installed and "installed" or "missing"),
	}
end

function V26.setupStatuses()
	local test = V8.getHarnessStatus() or { installed = false, status = "missing" }
	local verification = V16.harnessStatus() or { installed = false, status = "missing" }
	local qa = V17.harnessStatus() or { installed = false, status = "missing" }
	local liveVision = V25.getHarnessStatus() or { installed = false, status = "missing" }
	local realtime = V27.getHarnessStatus() or { installed = false, status = "missing" }
	local actionBridge = V32.getActionBridgeStatus and V32.getActionBridgeStatus({ shallow = true }) or { installed = false, status = "missing" }
	local camera = V36.getCameraNavigatorStatus and V36.getCameraNavigatorStatus({ shallow = true }) or { installed = false, status = "missing" }
	local screenControl = V38.getScreenControlStatus and V38.getScreenControlStatus({ shallow = true }) or { installed = false, status = "missing" }
	local vfxWorkbench = V39.getVfxPreviewStatus and V39.getVfxPreviewStatus({ shallow = true }) or { installed = false, status = "missing" }
	local animationWorkbench = V40.getAnimationPreviewStatus and V40.getAnimationPreviewStatus({ shallow = true }) or { installed = false, status = "missing" }
	local abilityForge = V44.getAbilityPreviewStatus and V44.getAbilityPreviewStatus({ shallow = true }) or { installed = false, status = "missing" }
	local testPilot = V45.getTestPilotStatus and V45.getTestPilotStatus({ shallow = true }) or { installed = false, status = "missing" }
	local awareness = V27.bridgeGet and V27.bridgeGet("/codex/awareness") or nil
	local awarenessFresh = awareness and awareness.status and awareness.status.fresh == true
	if awarenessFresh and realtime.status == "missing" then
		realtime.installed = true
		realtime.status = "running"
	end
	return {
		V26.statusEntry("testHarness", "Codex Test Harness", test.installed, test.installed and "installed" or "missing"),
		V26.statusEntry("verificationHarness", "Codex Verification Harness", verification.installed, verification.installed and "installed" or "missing"),
		V26.statusEntry("qaHarness", "Codex QA Harness", qa.installed, qa.installed and "installed" or "missing"),
		V26.statusEntry("liveVisionHarness", "Codex Live Vision Harness", liveVision.installed, liveVision.installed and "installed" or "missing"),
		V26.statusEntry("realtimeAwarenessHarness", "Codex Realtime Awareness Harness", realtime.installed, realtime.status or (realtime.installed and "installed" or "missing")),
		V26.statusEntry("smartWatch", "Codex Smart Watch", realtime.installed, realtime.status or (realtime.installed and "installed" or "missing")),
		V26.statusEntry("actionBridgeHarness", "Codex Action Bridge Harness", actionBridge.installed, actionBridge.status or (actionBridge.installed and "installed" or "missing")),
		V26.statusEntry("cameraNavigatorHarness", "Codex Camera Navigator Harness", camera.installed, camera.status or (camera.installed and "installed" or "missing")),
		V26.statusEntry("screenControlHarness", "Codex Screen Control Harness", screenControl.installed, screenControl.status or (screenControl.installed and "installed" or "missing")),
		V26.statusEntry("vfxWorkbenchHarness", "Codex VFX Workbench Harness", vfxWorkbench.installed, vfxWorkbench.status or (vfxWorkbench.installed and "installed" or "missing")),
		V26.statusEntry("animationWorkbenchHarness", "Codex Animation Workbench Harness", animationWorkbench.installed, animationWorkbench.status or (animationWorkbench.installed and "installed" or "missing")),
		V26.statusEntry("abilityForgeHarness", "Codex Ability Forge Harness", abilityForge.installed, abilityForge.status or (abilityForge.installed and "installed" or "missing")),
		V26.statusEntry("testPilotHarness", "Codex Test Pilot Harness", testPilot.installed, testPilot.status or (testPilot.installed and "installed" or "missing")),
	}
end

function V26.missingSetup(statuses)
	local missing = {}
	for _, item in ipairs(statuses or {}) do
		if not item.installed or item.status == "outdated" then
			table.insert(missing, item)
		end
	end
	return missing
end

function V26.lastOutputMatching(patterns)
	for index = #outputBuffer, 1, -1 do
		local entry = outputBuffer[index]
		local message = tostring(entry and entry.message or "")
		for _, pattern in ipairs(patterns) do
			if string.find(message, pattern, 1, true) then
				return entry
			end
		end
	end
	return nil
end

function V26.getHttpReadinessStatus(payload)
	payload = payload or {}
	local success = V26.lastOutputMatching({
		"[CodexLiveVisionHarness] capture result Enum.ScreenshotCaptureResult.Success",
		"[CodexLiveVisionHarness] capture result",
	})
	local relayed = V26.lastOutputMatching({
		"[CodexLiveVisionHarness] relay capture",
		"[CodexLiveVisionHarness] capture requested",
	})
	local blocked = V26.lastOutputMatching({
		"HTTP requests are not enabled",
		"Allow HTTP requests",
		"bridge poll unavailable",
	})
	local status = "needsPlayTest"
	local ready = false
	local message = "Start Play, approve a live-vision capture request, and verify the relay/capture markers."
	local evidence = nil
	if success then
		status = "verified"
		ready = true
		message = "HTTP/live vision relay is verified by a successful client capture marker."
		evidence = success
	elseif relayed then
		status = "relayVerified"
		ready = true
		message = "HTTP/live vision relay reached the client; screenshot capture result was not the latest marker."
		evidence = relayed
	elseif blocked then
		status = "blocked"
		message = "Enable Game Settings > Security > Allow HTTP Requests, then restart Play."
		evidence = blocked
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		status = status,
		ready = ready,
		required = true,
		message = message,
		evidence = evidence and {
			at = evidence.at,
			type = evidence.type,
			message = evidence.message,
			source = evidence.source,
		} or nil,
		recoveryCommand = ready and "tools/bridge.cmd live-vision capture status" or "Game Settings > Security > Allow HTTP Requests",
	}
	V26.last.http = result
	return result
end

function V26.isOwnedSetupPath(path)
	local value = tostring(path or "")
	return string.sub(value, 1, #"ReplicatedStorage.Codex") == "ReplicatedStorage.Codex"
		or string.sub(value, 1, #"ServerScriptService.Codex") == "ServerScriptService.Codex"
		or string.sub(value, 1, #"Workspace.Codex") == "Workspace.Codex"
		or string.sub(value, 1, #"StarterPlayer.StarterPlayerScripts.Codex") == "StarterPlayer.StarterPlayerScripts.Codex"
		or string.sub(value, 1, #"StarterGui.Codex") == "StarterGui.Codex"
end

function V26.prepareOwnedSetupStep(step)
	if type(step) ~= "table" then
		return step
	end
	local copy = {}
	for key, value in pairs(step) do
		copy[key] = value
	end
	if copy.type ~= "writeScript" or not V26.isOwnedSetupPath(copy.path) then
		return copy
	end
	local existing = resolvePath(copy.path)
	if existing and existing:IsA("LuaSourceContainer") and type(copy.source) == "string" then
		local ok, currentSource = pcall(function()
			return readScriptSource(existing)
		end)
		if ok then
			copy.expectedSourceHash = sourceHash(currentSource)
		end
		if ok and currentSource ~= copy.source then
			copy.overwrite = true
		end
	end
	return copy
end

function V26.setupBlueprint(payload)
	payload = payload or {}
	local profile = V7.profileFromPayload(payload)
	local blueprints = {
		V8.harnessBlueprint(profile),
		V16.verificationHarnessBlueprint(payload),
		V17.qaHarnessBlueprint(payload),
		V25.liveVisionHarnessBlueprint(payload),
		V27.realtimeHarnessBlueprint(payload),
		V32.actionBridgeHarnessBlueprint(payload),
		V36.cameraHarnessBlueprint(payload),
		V38.screenControlBlueprint(payload),
		V39.vfxWorkbenchBlueprint(payload),
		V40.animationWorkbenchBlueprint(payload),
		V44.harnessBlueprint(payload),
		V45.harnessBlueprint(payload),
	}
	local steps = {}
	for _, blueprint in ipairs(blueprints) do
		for _, step in ipairs(blueprint.steps or {}) do
			table.insert(steps, V26.prepareOwnedSetupStep(step))
		end
	end
	return {
		name = "Codex Ready Setup",
		mode = "fullTrustAutoSync",
		source = "applyCodexReadySetup",
		fullTrust = true,
		ownedRootsOnly = true,
		steps = steps,
	}
end

function V26.stepSummary(step)
	return {
		type = step.type,
		path = step.path,
		className = step.className,
		overwrite = step.overwrite == true,
		hasSource = type(step.source) == "string" and step.source ~= "",
	}
end

function V26.getCodexReadyPlan(payload)
	payload = payload or {}
	local blueprint = V26.setupBlueprint(payload)
	local stepSummaries = {}
	for _, step in ipairs(blueprint.steps or {}) do
		table.insert(stepSummaries, V26.stepSummary(step))
	end
	local statuses = V26.setupStatuses()
	local missing = V26.missingSetup(statuses)
	local result = {
		at = isoNow(),
		version = VERSION,
		name = blueprint.name,
		status = #missing == 0 and "installed" or "needsFullTrustSync",
		requiresApproval = false,
		fullTrustAutopilot = true,
		command = "tools/bridge.cmd ready bootstrap",
		applyCommand = "tools/bridge.cmd ready apply",
		setupStatuses = statuses,
		missingSetup = missing,
		summary = {
			steps = #stepSummaries,
			missingSetupCount = #missing,
			ownedRootsOnly = true,
			behavior = "Pair Auto Sync, connect, and ready bootstrap run applyCodexReadySetup automatically under Full Trust when Codex-owned setup is missing or stale.",
		},
		steps = stepSummaries,
	}
	V26.last.plan = result
	return result
end

function V26.getCodexReadyStatus(payload)
	payload = payload or {}
	local selfTest = V21.getBridgeSelfTest(payload)
	local setupStatuses = V26.setupStatuses()
	local missing = V26.missingSetup(setupStatuses)
	local http = V26.getHttpReadinessStatus(payload)
	local setupInstalled = #missing == 0
	local selfTestGood = (tonumber(selfTest.score) or 0) >= 100
	local codexReady = setupInstalled and selfTestGood and http.ready == true
	local status = "ready"
	if not setupInstalled then
		status = "needsSetup"
	elseif not http.ready then
		status = "needsHttpVerification"
	elseif not selfTestGood then
		status = "needsBridgeHealth"
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		status = status,
		codexReady = codexReady,
		score = codexReady and 100 or (setupInstalled and 85 or 65),
		setupStatuses = setupStatuses,
		missingSetup = missing,
		httpReadiness = http,
		selfTest = V21.compactSelfTest(selfTest),
		nextCommand = (not setupInstalled and "tools/bridge.cmd ready bootstrap")
			or (not http.ready and "tools/bridge.cmd live-vision capture request")
			or (not selfTestGood and "tools/bridge.cmd doctor")
			or "tools/bridge.cmd dashboard quick",
		message = codexReady and "Codex Ready is complete for this place." or "Codex Ready needs one more setup or verification step. Missing Codex-owned setup is synced automatically under Full Trust.",
		summary = {
			missingSetupCount = #missing,
			httpStatus = http.status,
			selfTestScore = selfTest.score,
			fullTrustAutoSync = true,
			toolkitInstalled = setupInstalled,
		},
	}
	V26.last.status = result
	return result
end

function V26.getPairBootstrapReport(payload)
	payload = payload or {}
	local status = V26.getCodexReadyStatus(payload)
	local plan = V26.getCodexReadyPlan(payload)
	local result = {
		at = isoNow(),
		version = VERSION,
		pairId = payload.pairId,
		status = status,
		plan = {
			status = plan.status,
			stepCount = plan.summary.steps,
			missingSetupCount = plan.summary.missingSetupCount,
		},
		autoQueuedSetup = status.status == "needsSetup",
		nextCommand = status.nextCommand,
	}
	V26.last.bootstrap = result
	return result
end

function V26.applyCodexReadySetup(payload)
	payload = payload or {}
	if RunService:IsRunning() and payload.allowPlaySetup ~= true then
		local status = V26.getCodexReadyStatus(payload)
		local result = {
			at = isoNow(),
			version = VERSION,
			kind = "applyCodexReadySetup",
			status = "deferred",
			deferred = true,
			setupDeferredReason = "playMode",
			runtimeMode = "play",
			message = "Codex Ready heavy toolkit setup is deferred while Play/Test is running to keep the StudioBridge plugin heartbeat alive. Stop Play; the bridge will auto-sync in Edit mode.",
			currentStatus = status,
			nextCommand = "Stop Play in Roblox Studio, then run tools\\bridge.cmd ready verify.",
		}
		V26.last.applied = result
		V26.last.status = status
		return result
	end
	local blueprint = V26.setupBlueprint(payload)
	local result = applyBuildPlan({ blueprint = blueprint })
	V26.last.applied = {
		at = isoNow(),
		version = VERSION,
		result = result,
	}
	V26.last.status = V26.getCodexReadyStatus(payload)
	return {
		at = isoNow(),
		version = VERSION,
		kind = "applyCodexReadySetup",
		build = result,
		status = V26.last.status,
	}
end

-- V27 Realtime Awareness / Fast Pulse Layer. This keeps a compact, safe,
-- near-realtime model of what Studio or the current playtest is doing.
function V27.harnessPaths()
	return {
		"ReplicatedStorage.CodexRealtimeAwareness",
		"ReplicatedStorage.CodexRealtimeAwareness.PulseEvent",
		"StarterPlayer.StarterPlayerScripts.CodexRealtimeAwarenessClient",
		"ServerScriptService.CodexRealtimeAwarenessRelay",
		"ReplicatedStorage.CodexRealtimeAwareness.Manifest",
	}
end

function V27.getHarnessStatus()
	local paths = {}
	local installed = 0
	for _, path in ipairs(V27.harnessPaths()) do
		local instance = resolvePath(path)
		if instance then
			installed += 1
			table.insert(paths, { path = path, exists = true, className = instance.ClassName, id = getInstanceId(instance) })
		else
			table.insert(paths, { path = path, exists = false })
		end
	end
	local manifest = resolvePath("ReplicatedStorage.CodexRealtimeAwareness.Manifest")
	local versionCurrent = false
	if manifest and manifest:IsA("LuaSourceContainer") then
		local source = readScriptSource(manifest)
		versionCurrent = string.find(source, "version = \"" .. VERSION .. "\"", 1, true) ~= nil
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		installed = installed == #paths,
		partial = installed > 0 and installed < #paths,
		installedCount = installed,
		missingCount = #paths - installed,
		versionCurrent = versionCurrent,
		status = installed == #paths and (versionCurrent and "installed" or "outdated") or "missing",
		paths = paths,
	}
	V27.last.harness = result
	return result
end

function V27.vectorTable(vector)
	if typeof(vector) ~= "Vector3" then
		return nil
	end
	return { x = vector.X, y = vector.Y, z = vector.Z }
end

function V27.selectionSummary()
	local selection = {}
	for index, instance in ipairs(Selection:Get()) do
		if index > 20 then
			break
		end
		table.insert(selection, {
			id = getInstanceId(instance),
			path = safeFullName(instance),
			name = instance.Name,
			className = instance.ClassName,
		})
	end
	return selection
end

function V27.recentOutputSummary(limit)
	limit = limit or 8
	local messages = {}
	local errors = 0
	local warnings = 0
	for index = math.max(1, #outputBuffer - limit + 1), #outputBuffer do
		local entry = outputBuffer[index]
		if entry then
			local typeText = tostring(entry.type or "")
			if string.find(string.lower(typeText), "error", 1, true) then
				errors += 1
			elseif string.find(string.lower(typeText), "warning", 1, true) then
				warnings += 1
			end
			table.insert(messages, {
				at = entry.at,
				type = entry.type,
				source = entry.source,
				message = V9.trimText(entry.message, 180),
			})
		end
	end
	return {
		totalBuffered = #outputBuffer,
		recentCount = #messages,
		recentErrors = errors,
		recentWarnings = warnings,
		messages = messages,
	}
end

function V27.editPulse()
	local pulse = {
		id = "edit-" .. tostring(os.clock()),
		source = "pluginEdit",
		contextType = "edit",
		at = isoNow(),
		version = VERSION,
		placeId = game.PlaceId,
		placeName = game.Name,
		mode = RunService:IsRunning() and "play" or "edit",
		selection = V27.selectionSummary(),
		output = V27.recentOutputSummary(8),
		commands = {
			pendingCount = #commandOrder,
			lastSummary = State.commandSummary,
			lastResult = State.lastCommandResult,
			lastError = State.lastCommandError,
		},
		snapshot = {
			stats = State.snapshotStats,
			lastSentAt = State.lastSuccessfulSnapshotAt,
			dirty = stateDirty,
		},
	}
	V27.last.editPulse = pulse
	return pulse
end

function V27.bridgeGet(path)
	local response, err = request("GET", path, nil, true)
	if response then
		return response
	end
	return { ok = false, version = VERSION, at = isoNow(), error = tostring(err) }
end

function V27.bridgePostPulse(pulse)
	local response, err = request("POST", "/runtime/awareness", {
		source = "pluginEdit",
		pulse = pulse,
	}, true)
	if response then
		V27.last.postedEditPulseAt = isoNow()
		return response
	end
	V27.last.postError = tostring(err)
	return nil
end

function V27.sendEditPulse()
	if not paired then
		return
	end
	local pulse = V27.editPulse()
	V27.bridgePostPulse(pulse)
end

