function V27.getRealtimeAwarenessReport(payload)
	payload = payload or {}
	local result = {
		at = isoNow(),
		version = VERSION,
		status = V27.getRealtimeAwarenessStatus(payload),
		pulse = V27.getRealtimePulse(payload),
		ui = V27.getRealtimeUiPulse(payload),
		world = V27.getRealtimeWorldPulse(payload),
		edit = V27.getRealtimeEditPulse(payload),
		perf = V27.getRealtimePerfStatus(payload),
	}
	V27.last.report = result
	return result
end

function V27.clientSource()
	return "local Players = game:GetService(\"Players\")\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal RunService = game:GetService(\"RunService\")\nlocal Workspace = game:GetService(\"Workspace\")\nlocal player = Players.LocalPlayer\nlocal folder = ReplicatedStorage:WaitForChild(\"CodexRealtimeAwareness\", 10)\nlocal remote = folder and folder:FindFirstChild(\"PulseEvent\")\nlocal seq = 0\nlocal lastSent = 0\nlocal lastPosition = nil\nlocal lastUiKey = \"\"\nlocal function vec(v)\n\tif typeof(v) == \"Vector3\" then return { x = v.X, y = v.Y, z = v.Z } end\n\tif typeof(v) == \"Vector2\" then return { x = v.X, y = v.Y } end\n\treturn nil\nend\nlocal function pathOf(instance)\n\tlocal ok, path = pcall(function() return instance:GetFullName() end)\n\treturn ok and path or tostring(instance)\nend\nlocal function characterSummary()\n\tlocal character = player.Character\n\tlocal root = character and character:FindFirstChild(\"HumanoidRootPart\")\n\tlocal humanoid = character and character:FindFirstChildOfClass(\"Humanoid\")\n\tlocal position = root and root.Position or nil\n\tlocal delta = nil\n\tif position and lastPosition then\n\t\tdelta = (position - lastPosition).Magnitude\n\tend\n\tif position then lastPosition = position end\n\treturn {\n\t\tname = character and character.Name or nil,\n\t\tposition = vec(position),\n\t\tdelta = delta,\n\t\thealth = humanoid and humanoid.Health or nil,\n\t\tmaxHealth = humanoid and humanoid.MaxHealth or nil,\n\t\tstate = humanoid and tostring(humanoid:GetState()) or nil,\n\t}\nend\nlocal function uiSummary()\n\tlocal playerGui = player:FindFirstChildOfClass(\"PlayerGui\")\n\tlocal result = { screenCount = 0, visibleObjects = 0, buttons = 0, textObjects = 0, texts = {} }\n\tif not playerGui then return result end\n\tfor _, descendant in ipairs(playerGui:GetDescendants()) do\n\t\tif descendant:IsA(\"ScreenGui\") and descendant.Enabled then\n\t\t\tresult.screenCount += 1\n\t\telseif descendant:IsA(\"GuiObject\") and descendant.Visible then\n\t\t\tresult.visibleObjects += 1\n\t\t\tif descendant:IsA(\"TextButton\") or descendant:IsA(\"ImageButton\") then result.buttons += 1 end\n\t\t\tif descendant:IsA(\"TextLabel\") or descendant:IsA(\"TextButton\") or descendant:IsA(\"TextBox\") then\n\t\t\t\tresult.textObjects += 1\n\t\t\t\tlocal text = tostring(descendant.Text or \"\")\n\t\t\t\tif text ~= \"\" and #result.texts < 10 then\n\t\t\t\t\ttable.insert(result.texts, { path = pathOf(descendant), text = string.sub(text, 1, 120) })\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend\n\treturn result\nend\nlocal function worldSummary(origin)\n\tlocal result = { nearby = {}, scanned = 0, truncated = false }\n\tif not origin then return result end\n\tlocal character = player.Character\n\tfor _, descendant in ipairs(Workspace:GetDescendants()) do\n\t\tif descendant:IsA(\"BasePart\") and not (character and descendant:IsDescendantOf(character)) then\n\t\t\tresult.scanned += 1\n\t\t\tif result.scanned > 350 then result.truncated = true break end\n\t\t\tlocal distance = (descendant.Position - origin).Magnitude\n\t\t\tif distance <= 160 and #result.nearby < 14 then\n\t\t\t\ttable.insert(result.nearby, { path = pathOf(descendant), name = descendant.Name, className = descendant.ClassName, distance = math.floor(distance), position = vec(descendant.Position) })\n\t\t\tend\n\t\tend\n\tend\n\treturn result\nend\nlocal function cameraSummary()\n\tlocal camera = Workspace.CurrentCamera\n\tif not camera then return { available = false } end\n\treturn { available = true, position = vec(camera.CFrame.Position), lookVector = vec(camera.CFrame.LookVector), fieldOfView = camera.FieldOfView, viewportSize = vec(camera.ViewportSize) }\nend\nlocal function pulse(moment)\n\tif not remote then return end\n\tseq += 1\n\tlocal camera = cameraSummary()\n\tlocal character = characterSummary()\n\tlocal ui = uiSummary()\n\tlocal uiKey = tostring(ui.screenCount) .. \":\" .. tostring(ui.visibleObjects) .. \":\" .. tostring(ui.buttons) .. \":\" .. tostring(ui.textObjects)\n\tlocal moments = { moment or \"tick\" }\n\tif character.delta and character.delta > 1 then table.insert(moments, \"moved\") end\n\tif uiKey ~= lastUiKey then table.insert(moments, \"uiChanged\") lastUiKey = uiKey end\n\tremote:FireServer({\n\t\tid = \"client-\" .. tostring(seq),\n\t\tsource = \"clientHarness\",\n\t\tatClock = os.clock(),\n\t\tcontextType = \"testClient\",\n\t\tplayer = { name = player.Name, userId = player.UserId },\n\t\tcamera = camera,\n\t\tcharacter = character,\n\t\tui = ui,\n\t\tworld = worldSummary(camera.position and Vector3.new(camera.position.x, camera.position.y, camera.position.z) or nil),\n\t\tmoments = moments,\n\t})\nend\nprint(\"[CodexRealtimeAwareness] client ready\")\nif not remote then\n\tprint(\"[CodexRealtimeAwareness] PulseEvent missing\")\nelse\n\tpulse(\"spawned\")\n\tRunService.RenderStepped:Connect(function()\n\t\tlocal now = os.clock()\n\t\tif now - lastSent >= 0.35 then\n\t\t\tlastSent = now\n\t\t\tpulse(\"tick\")\n\t\tend\n\tend)\n\tplayer.CharacterAdded:Connect(function()\n\t\tlastPosition = nil\n\t\ttask.wait(0.5)\n\t\tpulse(\"spawned\")\n\tend)\nend\n"
end

function V27.relaySource()
	return "local HttpService = game:GetService(\"HttpService\")\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal folder = ReplicatedStorage:WaitForChild(\"CodexRealtimeAwareness\", 10)\nlocal remote = folder and folder:FindFirstChild(\"PulseEvent\")\nlocal endpoint = \"http://127.0.0.1:28123/runtime/awareness\"\nlocal queue = {}\nlocal sent = 0\nlocal warnedHttp = false\nlocal function enqueue(player, pulse)\n\tif type(pulse) ~= \"table\" then return end\n\tpulse.playerName = player and player.Name or pulse.playerName\n\tpulse.playerUserId = player and player.UserId or pulse.playerUserId\n\ttable.insert(queue, pulse)\n\twhile #queue > 60 do table.remove(queue, 1) end\nend\nif remote and remote:IsA(\"RemoteEvent\") then\n\tremote.OnServerEvent:Connect(enqueue)\nelse\n\tprint(\"[CodexRealtimeAwareness] PulseEvent missing\")\nend\nlocal function postBatch(batch)\n\tlocal body = HttpService:JSONEncode({ source = \"realtimeRelay\", placeId = game.PlaceId, jobId = game.JobId, pulses = batch })\n\tlocal ok, result = pcall(function()\n\t\treturn HttpService:RequestAsync({ Url = endpoint, Method = \"POST\", Headers = { [\"Content-Type\"] = \"application/json\" }, Body = body })\n\tend)\n\tif not ok then\n\t\tif not warnedHttp then\n\t\t\twarnedHttp = true\n\t\t\tprint(\"[CodexRealtimeAwareness] bridge post unavailable\", tostring(result))\n\t\tend\n\t\treturn false\n\tend\n\tif type(result) == \"table\" and result.Success == false then\n\t\tif not warnedHttp then\n\t\t\twarnedHttp = true\n\t\t\tprint(\"[CodexRealtimeAwareness] bridge post failed\", tostring(result.StatusCode), tostring(result.StatusMessage))\n\t\tend\n\t\treturn false\n\tend\n\tsent += #batch\n\tif sent % 40 < #batch then\n\t\tprint(\"[CodexRealtimeAwareness] posted pulses\", tostring(sent))\n\tend\n\treturn true\nend\nprint(\"[CodexRealtimeAwareness] relay ready\")\ntask.spawn(function()\n\twhile true do\n\t\ttask.wait(0.4)\n\t\tif #queue > 0 then\n\t\t\tlocal batch = queue\n\t\t\tqueue = {}\n\t\t\tpostBatch(batch)\n\t\tend\n\tend\nend)\n"
end

function V27.realtimeHarnessBlueprint(payload)
	payload = payload or {}
	local profile = V7.profileFromPayload(payload)
	return {
		name = "Codex Realtime Awareness Harness",
		mode = "supervised",
		source = "installRealtimeAwarenessHarness",
		steps = {
			{ type = "ensureFolder", path = "ReplicatedStorage.CodexRealtimeAwareness" },
			{ type = "ensureRemoteEvent", path = "ReplicatedStorage.CodexRealtimeAwareness.PulseEvent" },
			V25.scriptWriteStep("StarterPlayer.StarterPlayerScripts.CodexRealtimeAwarenessClient", "LocalScript", V27.clientSource()),
			V25.scriptWriteStep("ServerScriptService.CodexRealtimeAwarenessRelay", "Script", V27.relaySource()),
			V25.scriptWriteStep("ReplicatedStorage.CodexRealtimeAwareness.Manifest", "ModuleScript", "return { name = \"CodexRealtimeAwareness\", version = \"" .. VERSION .. "\", watchVersion = \"" .. VERSION .. "\", profile = \"" .. V8.luaString(profile.id or "universal") .. "\" }\n"),
		},
	}
end

function V27.installRealtimeAwarenessHarness(payload)
	local blueprint = normalizeBlueprint(payload or {}) or V27.realtimeHarnessBlueprint(payload or {})
	local result = applyBuildPlan({ blueprint = blueprint })
	result.kind = "realtimeAwarenessHarnessInstall"
	result.harness = V27.getHarnessStatus()
	return result
end

function V27.removeRealtimeAwarenessHarness(payload)
	return withUndo("RemoveRealtimeAwarenessHarness", function()
		local result = { appliedAt = isoNow(), removed = {}, missing = {}, failed = {} }
		local roots = {
			"ReplicatedStorage.CodexRealtimeAwareness",
			"StarterPlayer.StarterPlayerScripts.CodexRealtimeAwarenessClient",
			"ServerScriptService.CodexRealtimeAwarenessRelay",
		}
		for _, path in ipairs(roots) do
			local instance = resolvePath(path)
			if instance then
				local ok, err = pcall(function()
					instance:Destroy()
				end)
				if ok then
					table.insert(result.removed, { path = path })
				else
					table.insert(result.failed, { path = path, message = tostring(err) })
				end
			else
				table.insert(result.missing, { path = path })
			end
		end
		result.summary = { removed = #result.removed, missing = #result.missing, failed = #result.failed }
		stateDirty = true
		result.harness = V27.getHarnessStatus()
		return result
	end)
end

function V27.clientSource()
	return [==[
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")
local Workspace = game:GetService("Workspace")
local player = Players.LocalPlayer
local folder = ReplicatedStorage:WaitForChild("CodexRealtimeAwareness", 10)
local remote = folder and folder:FindFirstChild("PulseEvent")
local seq = 0
local lastSent = 0
local lastPosition = nil
local lastUiKey = ""

local function vec(v)
	if typeof(v) == "Vector3" then return { x = v.X, y = v.Y, z = v.Z } end
	if typeof(v) == "Vector2" then return { x = v.X, y = v.Y } end
	return nil
end

local function pathOf(instance)
	local ok, path = pcall(function() return instance:GetFullName() end)
	return ok and path or tostring(instance)
end

local function safeRead(instance, property)
	local ok, value = pcall(function() return instance[property] end)
	if ok then return value end
	return nil
end

local function attr(instance, name)
	local ok, value = pcall(function() return instance:GetAttribute(name) end)
	if ok then return value end
	return nil
end

local function registrySnapshot()
	local actionBridge = ReplicatedStorage:FindFirstChild("CodexActionBridge")
	local registryModule = actionBridge and actionBridge:FindFirstChild("Registry")
	if not (registryModule and registryModule:IsA("ModuleScript")) then return {} end
	local ok, registry = pcall(require, registryModule)
	if not (ok and type(registry) == "table" and type(registry.List) == "function") then return {} end
	local listOk, entries = pcall(function() return registry.List() end)
	if not (listOk and type(entries) == "table") then return {} end
	local byId = {}
	for _, entry in ipairs(entries) do
		if type(entry) == "table" and entry.id then
			byId[tostring(entry.id)] = entry
		end
	end
	return byId
end

local function stableId(kind, path, ordinal)
	local text = tostring(kind or "target") .. ":" .. tostring(path or "") .. ":" .. tostring(ordinal or 1)
	local hash = 0
	for index = 1, #text do
		hash = (hash * 31 + string.byte(text, index)) % 1000000007
	end
	return tostring(kind or "target") .. "-" .. tostring(hash) .. "-" .. tostring(ordinal or 1)
end

local function findScreenGui(instance)
	local current = instance
	while current do
		if current:IsA("ScreenGui") then return current end
		current = current.Parent
	end
	return nil
end

local function rootUnderScreen(instance, screen)
	local current = instance
	local child = instance
	while current and current ~= screen do
		child = current
		current = current.Parent
	end
	return child
end

local function characterSummary()
	local character = player.Character
	local root = character and character:FindFirstChild("HumanoidRootPart")
	local humanoid = character and character:FindFirstChildOfClass("Humanoid")
	local position = root and root.Position or nil
	local delta = nil
	if position and lastPosition then
		delta = (position - lastPosition).Magnitude
	end
	if position then lastPosition = position end
	return {
		name = character and character.Name or nil,
		position = vec(position),
		delta = delta,
		health = humanoid and humanoid.Health or nil,
		maxHealth = humanoid and humanoid.MaxHealth or nil,
		state = humanoid and tostring(humanoid:GetState()) or nil,
	}
end

local function uiSummary()
	local playerGui = player:FindFirstChildOfClass("PlayerGui")
	local result = { screenCount = 0, visibleObjects = 0, buttons = 0, textObjects = 0, texts = {}, clickTargets = {} }
	if not playerGui then return result end
	local seenPathCounts = {}
	local registeredActions = registrySnapshot()
	for _, descendant in ipairs(playerGui:GetDescendants()) do
		if descendant:IsA("ScreenGui") and descendant.Enabled then
			result.screenCount += 1
		elseif descendant:IsA("GuiObject") and descendant.Visible then
			result.visibleObjects += 1
			local text = ""
			if descendant:IsA("TextLabel") or descendant:IsA("TextButton") or descendant:IsA("TextBox") then
				result.textObjects += 1
				text = tostring(descendant.Text or "")
				if text ~= "" and #result.texts < 20 then
					table.insert(result.texts, { path = pathOf(descendant), text = string.sub(text, 1, 160) })
				end
			end
			if descendant:IsA("TextButton") or descendant:IsA("ImageButton") then
				result.buttons += 1
				if #result.clickTargets < 120 then
					local path = pathOf(descendant)
					seenPathCounts[path] = (seenPathCounts[path] or 0) + 1
					local ordinal = seenPathCounts[path]
					local screen = findScreenGui(descendant)
					local root = screen and rootUnderScreen(descendant, screen) or nil
					local actionId = attr(descendant, "CodexActionId")
					local actionLabel = attr(descendant, "CodexActionLabel")
					local actionSafe = attr(descendant, "CodexActionSafe") == true
					local actionRequiresApproval = attr(descendant, "CodexActionRequiresApproval")
					local registered = actionId and registeredActions[tostring(actionId)] or nil
					local registeredSafe = registered and registered.safe == true
					table.insert(result.clickTargets, {
						id = stableId("ui", path, ordinal),
						path = path,
						name = descendant.Name,
						text = text ~= "" and string.sub(text, 1, 160) or nil,
						className = descendant.ClassName,
						visible = descendant.Visible,
						active = safeRead(descendant, "Active"),
						selectable = safeRead(descendant, "Selectable"),
						interactable = safeRead(descendant, "Interactable"),
						enabled = safeRead(descendant, "Enabled"),
						screenGui = screen and pathOf(screen) or nil,
						root = root and pathOf(root) or nil,
						absolutePosition = vec(descendant.AbsolutePosition),
						absoluteSize = vec(descendant.AbsoluteSize),
						position = tostring(descendant.Position),
						size = tostring(descendant.Size),
						zIndex = descendant.ZIndex,
						displayOrder = screen and screen.DisplayOrder or nil,
						playerName = player.Name,
						contextType = "testClient",
						actionId = actionId,
						actionLabel = actionLabel,
						actionSafe = actionSafe,
						actionRequiresApproval = actionRequiresApproval ~= false,
						registeredAction = registered ~= nil,
						registeredActionSafe = registeredSafe,
						actionMode = registered and (actionSafe or registeredSafe) and "registeredAction" or "manualOnly",
					})
				end
			end
		end
	end
	return result
end

local function worldSummary(origin)
	local result = { nearby = {}, scanned = 0, truncated = false }
	if not origin then return result end
	local character = player.Character
	for _, descendant in ipairs(Workspace:GetDescendants()) do
		if descendant:IsA("BasePart") and not (character and descendant:IsDescendantOf(character)) then
			result.scanned += 1
			if result.scanned > 350 then result.truncated = true break end
			local distance = (descendant.Position - origin).Magnitude
			if distance <= 160 and #result.nearby < 14 then
				table.insert(result.nearby, { path = pathOf(descendant), name = descendant.Name, className = descendant.ClassName, distance = math.floor(distance), position = vec(descendant.Position) })
			end
		end
	end
	return result
end

local function cameraSummary()
	local camera = Workspace.CurrentCamera
	if not camera then return { available = false } end
	return { available = true, position = vec(camera.CFrame.Position), lookVector = vec(camera.CFrame.LookVector), fieldOfView = camera.FieldOfView, viewportSize = vec(camera.ViewportSize) }
end

local function pulse(moment)
	if not remote then return end
	seq += 1
	local camera = cameraSummary()
	local character = characterSummary()
	local ui = uiSummary()
	local uiKey = tostring(ui.screenCount) .. ":" .. tostring(ui.visibleObjects) .. ":" .. tostring(ui.buttons) .. ":" .. tostring(ui.textObjects)
	local moments = { moment or "tick" }
	if character.delta and character.delta > 1 then table.insert(moments, "moved") end
	if uiKey ~= lastUiKey then table.insert(moments, "uiChanged") lastUiKey = uiKey end
	remote:FireServer({
		id = "client-" .. tostring(seq),
		source = "clientHarness",
		atClock = os.clock(),
		contextType = "testClient",
		player = { name = player.Name, userId = player.UserId },
		playerName = player.Name,
		playerUserId = player.UserId,
		camera = camera,
		character = character,
		ui = ui,
		world = worldSummary(camera.position and Vector3.new(camera.position.x, camera.position.y, camera.position.z) or nil),
		moments = moments,
	})
end

print("[CodexRealtimeAwareness] client ready v32.3")
if not remote then
	print("[CodexRealtimeAwareness] PulseEvent missing")
else
	pulse("spawned")
	RunService.RenderStepped:Connect(function()
		local now = os.clock()
		if now - lastSent >= 0.35 then
			lastSent = now
			pulse("tick")
		end
	end)
	player.CharacterAdded:Connect(function()
		lastPosition = nil
		task.wait(0.5)
		pulse("spawned")
	end)
end
]==]
end

-- V28 Smart Watch Mode. These commands are read-only wrappers over the bridge's
-- compact watch summaries derived from the V27 realtime awareness feed.
function V28.bridgeGet(path)
	local result = V27.bridgeGet(path)
	V28.last.bridge = result
	return result
end

function V28.getWatchNow(payload)
	local result = V28.bridgeGet("/codex/watch")
	V28.last.now = result
	return result
end

function V28.getWatchMoments(payload)
	payload = payload or {}
	local limit = tonumber(payload.limit) or 40
	local result = V28.bridgeGet("/codex/watch/moments?limit=" .. tostring(limit))
	V28.last.moments = result
	return result
end

function V28.getWatchSummary(payload)
	local result = V28.bridgeGet("/codex/watch/summary")
	V28.last.summary = result
	return result
end

function V28.getSmartWatchStatus(payload)
	local now = V28.getWatchNow(payload)
	local result = {
		at = isoNow(),
		version = VERSION,
		mode = "smartWatch",
		fresh = now.status and now.status.fresh == true,
		watch = now,
		config = V28.getWatchConfig(payload),
		nextCommand = now.nextCommand or "tools/bridge.cmd watch now",
	}
	V28.last.status = result
	return result
end

function V28.getWatchUiChanges(payload)
	payload = payload or {}
	local moments = V28.getWatchMoments({ limit = tonumber(payload.limit) or 80 })
	local changes = {}
	for _, moment in ipairs(moments.moments or {}) do
		local labels = moment.labels or {}
		local include = false
		for _, label in ipairs(labels) do
			if label == "uiChanged" or label == "textChanged" or label == "objectiveChanged" then
				include = true
				break
			end
		end
		if include then
			table.insert(changes, moment)
		end
		if #changes >= (tonumber(payload.maxResults) or 20) then
			break
		end
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		changes = changes,
		total = #changes,
		current = V28.getWatchNow(payload).current,
	}
	V28.last.ui = result
	return result
end

function V28.getWatchLoopState(payload)
	local now = V28.getWatchNow(payload)
	local result = {
		at = isoNow(),
		version = VERSION,
		loop = now.loop,
		recentMoments = now.recentMoments,
		nextCommand = "tools/bridge.cmd watch moments",
	}
	V28.last.loop = result
	return result
end

function V28.getWatchErrors(payload)
	local now = V28.getWatchNow(payload)
	local useBaseline = not (payload and payload.raw == true)
	local output = useBaseline and V31.getOutputSinceBaseline({
		limit = tonumber(payload and payload.limit) or 100,
		includeBridgeNoise = false,
	}) or V27.bridgeGet("/codex/output?limit=" .. tostring(tonumber(payload and payload.limit) or 100))
	local issues = {}
	local suppressed = {}
	for index = #(output.messages or {}), 1, -1 do
		local entry = output.messages[index]
		local message = tostring(entry.message or "")
		local typeText = tostring(entry.type or "")
		local lower = string.lower(message)
		if not string.find(lower, "missing a valid bridge token", 1, true)
			and not string.find(lower, "paired with codex studio bridge", 1, true)
			and not V6.isBridgeNoiseMessage(message)
			and (string.find(string.lower(typeText), "error", 1, true)
				or string.find(string.lower(typeText), "warn", 1, true)
				or string.find(lower, "error", 1, true)
				or string.find(lower, "failed", 1, true)
				or string.find(lower, "unable", 1, true)) then
			table.insert(issues, entry)
		elseif V6.isBridgeNoiseMessage(message) then
			table.insert(suppressed, {
				at = entry.at,
				type = entry.type,
				source = entry.source,
				message = V9.trimText(message, 220),
				reason = "nonBlockingBridgeOrStudioNoise",
			})
		end
		if #issues >= 20 then
			break
		end
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		source = useBaseline and "outputBaseline" or "recentOutput",
		baselineIndex = output.baselineIndex,
		baselineAt = output.baselineAt,
		latestOutputIssue = now.latestOutputIssue,
		issues = issues,
		total = #issues,
		suppressed = suppressed,
		suppressedCount = #suppressed,
		message = #issues == 0 and "No fresh actionable Output errors/warnings found. Old bridge/DataStore queue noise is suppressed by default." or "Fresh actionable Output issues found.",
	}
	V28.last.errors = result
	return result
end

function V28.getWatchConfig(payload)
	return {
		at = isoNow(),
		version = VERSION,
		mode = "smartWatch",
		source = "V27 realtime awareness",
		preferContext = "testClient",
		automaticSetup = "applyCodexReadySetup",
		readOnly = true,
		commands = {
			"tools/bridge.cmd watch now",
			"tools/bridge.cmd watch moments",
			"tools/bridge.cmd watch ui",
			"tools/bridge.cmd watch loop",
			"tools/bridge.cmd watch errors",
			"tools/bridge.cmd watch summary",
		},
	}
end

-- V29 Zero-Friction Project Start. These commands are read-only and compose
-- the existing ready/watch/dashboard/template reports into one starter view.
function V29.addChecklistItem(items, id, title, ok, detail)
	table.insert(items, {
		id = id,
		title = title,
		ok = ok == true,
		detail = detail,
	})
end

function V29.countReady(items)
	local count = 0
	for _, item in ipairs(items or {}) do
		if item.ok then
			count += 1
		end
	end
	return count
end

function V29.cacheAvailable(cache, id)
	for _, entry in ipairs((cache and cache.entries) or {}) do
		if entry.id == id and entry.available == true then
			return true
		end
	end
	return false
end

function V29.getProjectStartChecklist(payload)
	payload = payload or {}
	local selfTest = V21.getBridgeSelfTest({
		expectedVersion = payload.expectedVersion or VERSION,
		source = "projectStartChecklist",
		skipDashboardCheck = true,
	})
	local ready = V26.getCodexReadyStatus(payload)
	local watch = V28.getSmartWatchStatus(payload)
	local flow = V22.getCommandFlowStatus({ limit = 12 })
	local cache = V22.getReportCacheStatus(payload)
	local template = V24.getTemplateRecommendationReport(payload)
	local setupInstalled = ready.summary and tonumber(ready.summary.missingSetupCount or 0) == 0
	local httpReady = ready.summary and tostring(ready.summary.httpStatus or "") == "ready"
	local dashboardCached = V29.cacheAvailable(cache, "creatorDashboard") or V29.cacheAvailable(cache, "fastDashboard")
	local items = {}
	V29.addChecklistItem(items, "paired", "Studio paired", paired, paired and "Plugin has a stored session token." or "Enter the bridge pairing code.")
	V29.addChecklistItem(items, "pluginVersion", "Plugin version", VERSION == tostring(payload.expectedVersion or VERSION), "Plugin " .. VERSION)
	V29.addChecklistItem(items, "selfTest", "Bridge self-test", tonumber(selfTest.score or 0) >= 100, "Score " .. tostring(selfTest.score or "?"))
	V29.addChecklistItem(items, "codexReadySetup", "Codex Ready setup", setupInstalled, setupInstalled and "Full owned toolkit installed." or "Pair Auto Sync or ready bootstrap will run applyCodexReadySetup under Full Trust.")
	V29.addChecklistItem(items, "httpReadiness", "HTTP readiness", httpReady, ready.summary and tostring(ready.summary.httpStatus or "unknown") or "unknown")
	V29.addChecklistItem(items, "smartWatch", "Smart Watch", watch.fresh == true or watch.watch ~= nil, watch.fresh and "Fresh watch feed." or "Watch available; waiting for fresh pulse.")
	V29.addChecklistItem(items, "commandQueue", "Command queue calm", tonumber(flow.pendingCount or 0) == 0, tostring(flow.pendingCount or 0) .. " pending command(s).")
	V29.addChecklistItem(items, "dashboardCache", "Dashboard cache", dashboardCached, dashboardCached and "Fast dashboard available." or "Run start warm.")
	V29.addChecklistItem(items, "templateRecommendation", "Template recommendation", template.topRecommendation ~= nil, template.topRecommendation and tostring(template.topRecommendation.id) or "No recommendation yet.")
	V29.addChecklistItem(items, "projectProfile", "Project profile", V7.profileFromPayload(payload) ~= nil, tostring((V7.profileFromPayload(payload) or {}).id or "universal"))
	local readyCount = V29.countReady(items)
	local result = {
		at = isoNow(),
		version = VERSION,
		mode = "zeroFrictionStart",
		readyCount = readyCount,
		total = #items,
		score = math.floor((readyCount / math.max(1, #items)) * 100 + 0.5),
		items = items,
		ready = {
			status = ready.status,
			score = ready.score,
			codexReady = ready.codexReady,
			missingSetupCount = ready.summary and ready.summary.missingSetupCount or nil,
			httpStatus = ready.summary and ready.summary.httpStatus or nil,
		},
		watch = {
			fresh = watch.fresh,
			nextCommand = watch.nextCommand,
		},
		flow = {
			pendingCount = flow.pendingCount,
			averageCommandMs = flow.averageCommandMs,
		},
	}
	V29.last.checklist = result
	return result
end

function V29.getProjectStartTemplateMenu(payload)
	payload = payload or {}
	local recommendation = V24.getTemplateRecommendationReport(payload)
	local result = {
		at = isoNow(),
		version = VERSION,
		mode = "zeroFrictionStart",
		activeProfile = recommendation.activeProfile,
		recommendations = recommendation.recommendations,
		topRecommendation = recommendation.topRecommendation,
		nextCommand = recommendation.nextCommand,
		safety = "Preview is read-only. Applying a template runs under Full Trust and is audited.",
	}
	V29.last.templates = result
	return result
end

function V29.getProjectStartNextStep(payload)
	payload = payload or {}
	local checklist = V29.getProjectStartChecklist(payload)
	local ready = checklist.ready or {}
	local flow = checklist.flow or {}
	local templates = V29.last.templates or V29.getProjectStartTemplateMenu(payload)
	local command = "tools/bridge.cmd start warm"
	local rationale = "Warm the starter dashboard, profile, and template context."
	if not paired then
		command = "Pair the plugin with the bridge code shown by /health."
		rationale = "The plugin is not paired yet."
	elseif tonumber(flow.pendingCount or 0) > 0 then
		command = "tools/bridge.cmd commands"
		rationale = "A manual fallback or blocked external-risk command is waiting for inspection."
	elseif tonumber(ready.missingSetupCount or 0) > 0 or ready.status == "needsSetup" then
		command = "tools/bridge.cmd ready bootstrap"
		rationale = "Codex Ready setup is missing and Full Trust should sync Codex-owned toolkit objects now."
	elseif tostring(ready.httpStatus or "") ~= "ready" then
		command = "tools/bridge.cmd live-vision capture request"
		rationale = "HTTP/live-vision readiness still needs Play/Test verification."
	elseif checklist.score < 100 then
		command = "tools/bridge.cmd start warm"
		rationale = "The bridge works; warming fills the remaining local start checklist."
	elseif templates.topRecommendation then
		command = "tools/bridge.cmd template preview " .. tostring(templates.topRecommendation.id)
		rationale = "Everything is connected; preview the best starter direction without mutating Studio."
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		command = command,
		rationale = rationale,
		checklistScore = checklist.score,
	}
	V29.last.next = result
	return result
end

function V29.getProjectStartStatus(payload)
	payload = payload or {}
	local checklist = V29.getProjectStartChecklist(payload)
	local nextStep = V29.getProjectStartNextStep(payload)
	local watch = V28.getWatchSummary(payload)
	local result = {
		at = isoNow(),
		version = VERSION,
