		place = {
			name = game.Name,
			placeId = game.PlaceId,
			gameId = game.GameId,
			jobId = game.JobId,
		},
		activeProfile = V7.profileSummary(V7.profileFromPayload(payload)),
		checklist = checklist,
		watch = watch,
		next = nextStep,
		firstCommands = {
			"tools/bridge.cmd start",
			"tools/bridge.cmd ready verify",
			"tools/bridge.cmd watch now",
			"tools/bridge.cmd start templates",
			nextStep.command,
		},
		safety = "Read-only start report. Studio mutations run under Full Trust and are audited.",
	}
	V29.last.status = result
