-- V30 One-Command Game Session Orchestrator. Read-only routing that decides
-- which existing bridge command best matches the current work mode.
function V30.goalHas(goal, pattern)
	return string.find(string.lower(tostring(goal or "")), pattern) ~= nil
end

function V30.normalizeMode(mode)
	mode = string.lower(tostring(mode or "auto"))
	local allowed = {
		auto = true,
		build = true,
		debug = true,
		playtest = true,
		ui = true,
		code = true,
		world = true,
		["ship-check"] = true,
	}
	return allowed[mode] and mode or "auto"
end

function V30.inferMode(payload)
	payload = payload or {}
	local requested = V30.normalizeMode(payload.mode or payload.requestedMode)
	local goal = tostring(payload.goal or "")
	if requested ~= "auto" then
		return { mode = requested, confidence = 100, reason = "Mode was explicitly set to " .. requested .. "." }
	end
	if V30.goalHas(goal, "ship") or V30.goalHas(goal, "publish") or V30.goalHas(goal, "release") then
		return { mode = "ship-check", confidence = 92, reason = "Goal asks for shipping readiness." }
	end
	if V30.goalHas(goal, "ui") or V30.goalHas(goal, "hud") or V30.goalHas(goal, "menu") or V30.goalHas(goal, "button") then
		return { mode = "ui", confidence = 90, reason = "Goal is UI oriented." }
	end
	if V30.goalHas(goal, "code") or V30.goalHas(goal, "script") or V30.goalHas(goal, "module") or V30.goalHas(goal, "remote") then
		return { mode = "code", confidence = 90, reason = "Goal is code oriented." }
	end
	if V30.goalHas(goal, "world") or V30.goalHas(goal, "map") or V30.goalHas(goal, "terrain") or V30.goalHas(goal, "asset") then
		return { mode = "world", confidence = 88, reason = "Goal is world or asset oriented." }
	end
	if V30.goalHas(goal, "debug") or V30.goalHas(goal, "bug") or V30.goalHas(goal, "error") or V30.goalHas(goal, "fix") then
		return { mode = "debug", confidence = 88, reason = "Goal asks for debugging." }
	end
	if V30.goalHas(goal, "play") or V30.goalHas(goal, "test") or V30.goalHas(goal, "check now") or V30.goalHas(goal, "live") then
		return { mode = "playtest", confidence = 84, reason = "Goal asks for live playtest awareness." }
	end
	if V28.last.summary and V28.last.summary.mode and tostring(V28.last.summary.mode) ~= "edit" then
		return { mode = "playtest", confidence = 84, reason = "Recent watch summary is from a runtime context." }
	end
	if V28.last.errors and tonumber(V28.last.errors.total or 0) > 0 then
		return { mode = "debug", confidence = 82, reason = "Recent actionable Output issue is present." }
	end
	return { mode = "build", confidence = 70, reason = "No narrower active signal is stronger." }
end

function V30.route(payload)
	payload = payload or {}
	local mode = V30.inferMode(payload)
	local startNext = V29.getProjectStartNextStep(payload)
	local command = startNext.command
	local rationale = startNext.rationale
	local source = "start-readiness"
	if paired and command ~= "tools/bridge.cmd ready bootstrap" and not string.find(command, "Approve", 1, true) then
		if mode.mode == "playtest" then
			command = "tools/bridge.cmd watch now"
			rationale = "Read compact live playtest state first."
		elseif mode.mode == "debug" then
			command = "tools/bridge.cmd watch errors"
			rationale = "Surface current actionable Output issues first."
		elseif mode.mode == "ui" then
			command = "tools/bridge.cmd ui director"
			rationale = "Inspect real UI flow and responsive risks."
		elseif mode.mode == "code" then
			command = "tools/bridge.cmd code doctor"
			rationale = "Map code health before suggesting patches."
		elseif mode.mode == "world" then
			command = "tools/bridge.cmd world audit"
			rationale = "Inspect map, landmarks, assets, and buildable areas."
		elseif mode.mode == "ship-check" then
			command = "tools/bridge.cmd dashboard full"
			rationale = "Use the full creator dashboard for readiness."
		else
			command = "tools/bridge.cmd start templates"
			rationale = "Choose a safe previewable build direction."
		end
		source = "session-route"
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		mode = mode.mode,
		goal = payload.goal,
		command = command,
		rationale = rationale,
		source = source,
		confidence = mode.confidence,
		modeReason = mode.reason,
	}
	V30.last.route = result
	return result
end

function V30.getGameSessionChecklist(payload)
	payload = payload or {}
	local start = V29.getProjectStartChecklist(payload)
	local route = V30.route(payload)
	local watch = V28.getWatchSummary(payload)
	local mode = V30.inferMode(payload)
	local items = {
		{ id = "startReady", title = "Start context", ok = start.score >= 75, detail = "Start checklist " .. tostring(start.readyCount) .. "/" .. tostring(start.total) },
		{ id = "modeSelected", title = "Session mode", ok = mode.mode ~= nil, detail = mode.mode .. ": " .. mode.reason },
		{ id = "routeReady", title = "Next route", ok = route.command ~= nil, detail = route.command },
		{ id = "watchAvailable", title = "Watch summary", ok = watch ~= nil, detail = watch.text or "No watch text yet." },
		{ id = "queueCalm", title = "Queue calm", ok = #commandOrder == 0, detail = tostring(#commandOrder) .. " pending command(s)." },
	}
	local readyCount = V29.countReady(items)
	local result = {
		at = isoNow(),
		version = VERSION,
		mode = mode.mode,
		score = math.floor((readyCount / #items) * 100 + 0.5),
		readyCount = readyCount,
		total = #items,
		items = items,
		route = route,
	}
	V30.last.checklist = result
	return result
end

