	}
	V30.last.plan = result
	return result
end

-- V31 Universal Launch QA Center. These are read-only reports that pull the
-- existing bridge powers into one game-agnostic QA surface.
function V31.serviceRootNames()
	return {
		"Workspace",
		"ReplicatedStorage",
		"ServerScriptService",
		"ServerStorage",
		"StarterGui",
		"StarterPlayer",
		"ReplicatedFirst",
		"Lighting",
		"SoundService",
		"Teams",
	}
end

function V31.classCounter(rootNames)
	local counts = {}
	local total = 0
	for _, rootName in ipairs(rootNames or V31.serviceRootNames()) do
		local ok, root = pcall(function()
			return game:GetService(rootName)
		end)
		if ok and root then
			for _, instance in ipairs(root:GetDescendants()) do
				total += 1
				counts[instance.ClassName] = (counts[instance.ClassName] or 0) + 1
			end
		end
	end
	return counts, total
end

function V31.attributeSummary(instance)
	if not instance then
		return nil
	end
	local attributes = {}
	local ok, raw = pcall(function()
		return instance:GetAttributes()
	end)
	if ok and type(raw) == "table" then
		for key, value in pairs(raw) do
			attributes[key] = serializeValue(value)
		end
	end
	return {
		name = instance.Name,
		className = instance.ClassName,
		path = safeFullName(instance),
		id = getInstanceId(instance),
		attributes = attributes,
	}
end

function V31.getStudioControlReport(payload)
	payload = payload or {}
	local runtime = getRuntimeStatus()
	local watch = V28.getWatchNow({})
	local awareness = watch and watch.status or {}
	local activeContext = tostring(awareness.activeContextType or watch.mode or runtime.contextType or "")
	local livePlayEvidence = awareness.fresh == true and (string.find(string.lower(activeContext), "client", 1, true) ~= nil
		or string.find(string.lower(activeContext), "server", 1, true) ~= nil
		or string.find(string.lower(activeContext), "play", 1, true) ~= nil)
	local effectiveMode = livePlayEvidence and "play" or runtime.mode
	local result = {
		at = isoNow(),
		version = VERSION,
		mode = effectiveMode,
		runtimeMode = runtime.mode,
		contextType = runtime.contextType,
		runService = runtime.runService,
		livePlayEvidence = livePlayEvidence,
		awareness = {
			fresh = awareness.fresh,
			activeContextType = awareness.activeContextType,
			activeSource = awareness.activeSource,
			latestAgeMs = awareness.latestAgeMs,
		},
		playControl = {
			startStopSupported = false,
			status = "manualOnly",
			message = "Roblox Studio does not expose a safe public plugin API here for silently pressing Play/Stop. The bridge detects mode and tells you when to press Play.",
		},
		scriptLoadReadiness = {
			status = State.snapshotStats and "snapshotAvailable" or "needsSnapshot",
			scriptCount = State.snapshotStats and State.snapshotStats.scriptCount or nil,
			lastSnapshotAt = State.lastStateSentAtIso,
		},
		outputBaseline = {
			baselineIndex = V31.outputBaselineIndex,
			baselineAt = V31.outputBaselineAt,
			buffered = #outputBuffer,
			nextCommand = "tools/bridge.cmd baseline mark",
		},
		nextCommand = effectiveMode == "edit" and "Press Play in Roblox Studio, then run tools/bridge.cmd launch-qa full" or "tools/bridge.cmd launch-qa full",
	}
	V31.last.control = result
	return result
end

function V31.markOutputBaseline(payload)
	payload = payload or {}
	V31.outputBaselineIndex = #outputBuffer + 1
	V31.outputBaselineAt = isoNow()
	local result = {
		at = V31.outputBaselineAt,
		version = VERSION,
		baselineIndex = V31.outputBaselineIndex,
		buffered = #outputBuffer,
		message = "Output baseline marked. Future baseline reads show only newer messages.",
	}
	V31.last.outputBaseline = result
	return result
end

function V31.clearOutputBaseline(payload)
	payload = payload or {}
	V31.outputBaselineIndex = nil
	V31.outputBaselineAt = nil
	local result = {
		at = isoNow(),
		version = VERSION,
		message = "Output baseline cleared.",
		buffered = #outputBuffer,
	}
	V31.last.outputBaseline = result
	return result
end

function V31.getOutputSinceBaseline(payload)
	payload = payload or {}
	local limit = tonumber(payload.limit) or 100
	local includeBridgeNoise = payload.includeBridgeNoise == true
	local startIndex = V31.outputBaselineIndex or math.max(1, #outputBuffer - limit + 1)
	local messages = {}
	local errors = {}
	local suppressed = {}
	for index = startIndex, #outputBuffer do
		local entry = outputBuffer[index]
		if entry then
			local isNoise = V6.isBridgeNoiseMessage(entry.message)
			if isNoise and not includeBridgeNoise then
				table.insert(suppressed, {
					at = entry.at,
					type = entry.type,
					source = entry.source,
					message = V9.trimText(tostring(entry.message or ""), 220),
					reason = "nonBlockingBridgeOrStudioNoise",
				})
			else
				table.insert(messages, entry)
			end
			if isErrorOrWarning(entry) and (includeBridgeNoise or not isNoise) then
				table.insert(errors, entry)
			end
			if #messages >= limit then
				break
			end
		end
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		baselineIndex = V31.outputBaselineIndex,
		baselineAt = V31.outputBaselineAt,
		totalNew = math.max(0, #outputBuffer - (V31.outputBaselineIndex or #outputBuffer + 1) + 1),
		returned = #messages,
		errorOrWarningCount = #errors,
		suppressedCount = #suppressed,
		messages = messages,
		errors = errors,
		suppressed = suppressed,
		message = #errors == 0 and "No fresh actionable Output errors/warnings since baseline." or "Fresh actionable Output errors/warnings found since baseline.",
	}
	V31.last.outputSinceBaseline = result
	return result
end

function V31.normalizeOutputMode(mode)
	local value = tostring(mode or "current"):lower():gsub("[^%a]", "")
	if value == "history" or value == "all" or value == "recent" or value == "errors" or value == "warnings" or value == "current" then
		return value
	end
	return "current"
end

function V31.outputPreview(text, limit)
	local value = tostring(text or "")
	local maxLength = tonumber(limit) or 320
	if #value > maxLength then
		return string.sub(value, 1, maxLength) .. "..."
	end
	return value
end

function V31.isOutputIssue(entry)
	local kind = tostring(entry and entry.type or ""):lower()
	local text = tostring(entry and entry.message or ""):lower()
	return kind:find("error", 1, true) ~= nil
		or kind:find("warn", 1, true) ~= nil
		or text:find("error", 1, true) ~= nil
		or text:find("failed", 1, true) ~= nil
		or text:find("unable", 1, true) ~= nil
		or text:find("exception", 1, true) ~= nil
end

function V31.getOutputFreshnessReport(payload)
	payload = payload or {}
	local mode = V31.normalizeOutputMode(payload.mode)
	local limit = math.max(1, math.min(tonumber(payload.limit) or 50, OUTPUT_LIMIT))
	local includeNoise = payload.includeNoise == true or mode == "all"
	local hasBaseline = tonumber(V31.outputBaselineIndex) ~= nil
	local baselineIndex = hasBaseline and math.max(1, math.min(#outputBuffer + 1, tonumber(V31.outputBaselineIndex))) or nil
	local historyIncluded = mode == "history" or mode == "all" or mode == "recent"
	local startIndex = 1
	if mode == "recent" then
		startIndex = math.max(1, #outputBuffer - limit + 1)
	elseif not historyIncluded then
		startIndex = baselineIndex or math.max(1, #outputBuffer - limit + 1)
	end
	local messages = {}
	local suppressed = {}
	local staleHistory = {}
	local groupsByMessage = {}
	local latestActionable = nil
	local matchingCount = 0
	for index = startIndex, #outputBuffer do
		local entry = outputBuffer[index]
		if entry then
			local text = tostring(entry.message or "")
			local kind = tostring(entry.type or "")
			local loweredKind = kind:lower()
			local loweredText = text:lower()
			local isStale = hasBaseline and index < baselineIndex
			local isNoise = V6.isBridgeNoiseMessage(text)
			local isError = loweredKind:find("error", 1, true) ~= nil or loweredText:find("error", 1, true) ~= nil or loweredText:find("failed", 1, true) ~= nil or loweredText:find("unable", 1, true) ~= nil
			local isWarning = loweredKind:find("warn", 1, true) ~= nil or loweredText:find("warning", 1, true) ~= nil
			if isStale then
				table.insert(staleHistory, {
					at = entry.at,
					type = entry.type,
					source = entry.source,
					message = V31.outputPreview(text, 220),
					reason = "beforeActiveOutputBaseline",
				})
			end
			if isNoise and not includeNoise then
				table.insert(suppressed, {
					at = entry.at,
					type = entry.type,
					source = entry.source,
					message = V31.outputPreview(text, 220),
					reason = "nonBlockingBridgeOrStudioNoise",
				})
			elseif (mode ~= "errors" or isError) and (mode ~= "warnings" or isWarning) then
				matchingCount += 1
				local compact = {
					id = entry.id,
					at = entry.at,
					type = entry.type,
					source = entry.source,
					message = V31.outputPreview(text, 320),
					stale = isStale,
				}
				table.insert(messages, compact)
				if V31.isOutputIssue(entry) and not isStale then
					latestActionable = compact
				end
				local groupKey = text:gsub("%s+", " ")
				if #groupKey > 180 then
					groupKey = string.sub(groupKey, 1, 180)
				end
				if groupKey ~= "" then
					local group = groupsByMessage[groupKey] or {
						message = groupKey,
						count = 0,
						firstAt = entry.at,
						lastAt = entry.at,
						type = entry.type,
						staleCount = 0,
					}
					group.count += 1
					group.lastAt = entry.at
					if isStale then group.staleCount += 1 end
					groupsByMessage[groupKey] = group
				end
			end
		end
	end
	while #messages > limit do
		table.remove(messages, 1)
	end
	local groups = {}
	for _, group in pairs(groupsByMessage) do
		table.insert(groups, group)
	end
	table.sort(groups, function(a, b) return a.count > b.count end)
	while #groups > math.min(40, limit) do
		table.remove(groups)
	end
	local result = {
		ok = true,
		at = isoNow(),
		version = VERSION,
		mode = mode,
		source = "pluginOutputBuffer",
		baselineIndex = V31.outputBaselineIndex,
		baselineAt = V31.outputBaselineAt,
		isFresh = V31.outputBaselineAt ~= nil and not historyIncluded,
		historyIncluded = historyIncluded,
		totalStored = #outputBuffer,
		startIndex = startIndex,
		returned = #messages,
		matchingCount = matchingCount,
		truncated = matchingCount > #messages,
		suppressedNoiseCount = #suppressed,
		staleHistoryCount = #staleHistory,
		latestActionable = latestActionable,
		messages = messages,
		groups = groups,
		suppressed = suppressed,
		staleHistory = historyIncluded and staleHistory or {},
		message = latestActionable and "Fresh actionable Output issues found." or (historyIncluded and "Output history returned; stale messages are labeled." or "No fresh actionable Output errors/warnings since the active baseline."),
	}
	V31.last.outputFreshnessReport = result
	return result
end

