function V31.getUniversalMapQualityAudit(payload)
	payload = payload or {}
	local workspace = game:GetService("Workspace")
	local counts = {
		parts = 0,
		models = 0,
		unanchoredParts = 0,
		spawns = 0,
		proximityPrompts = 0,
		clickDetectors = 0,
		billboards = 0,
		surfaceGuis = 0,
		hugeParts = 0,
	}
	local examples = {
		unanchored = {},
		hugeParts = {},
		interactables = {},
		labels = {},
	}
	for _, instance in ipairs(workspace:GetDescendants()) do
		if instance:IsA("BasePart") then
			counts.parts += 1
			if instance:IsA("SpawnLocation") then
				counts.spawns += 1
			end
			if not instance.Anchored then
				counts.unanchoredParts += 1
				if #examples.unanchored < 10 then
					table.insert(examples.unanchored, { path = safeFullName(instance), name = instance.Name, size = serializeValue(instance.Size), position = serializeValue(instance.Position) })
				end
			end
			local size = instance.Size
			if size.X > 300 or size.Y > 300 or size.Z > 300 then
				counts.hugeParts += 1
				if #examples.hugeParts < 8 then
					table.insert(examples.hugeParts, { path = safeFullName(instance), size = serializeValue(size) })
				end
			end
		elseif instance:IsA("Model") then
			counts.models += 1
		elseif instance:IsA("ProximityPrompt") then
			counts.proximityPrompts += 1
			if #examples.interactables < 12 then
				table.insert(examples.interactables, { path = safeFullName(instance), actionText = instance.ActionText, objectText = instance.ObjectText })
			end
		elseif instance:IsA("ClickDetector") then
			counts.clickDetectors += 1
		elseif instance:IsA("BillboardGui") then
			counts.billboards += 1
			if #examples.labels < 10 then
				table.insert(examples.labels, { path = safeFullName(instance), size = serializeValue(instance.Size) })
			end
		elseif instance:IsA("SurfaceGui") then
			counts.surfaceGuis += 1
		end
	end
	local issues = {}
	if counts.spawns == 0 then
		table.insert(issues, { severity = "warning", code = "noSpawnLocation", message = "No SpawnLocation found in Workspace." })
	end
	if counts.unanchoredParts > 50 then
		table.insert(issues, { severity = "warning", code = "manyUnanchoredParts", message = "Many unanchored parts may cause physics/performance noise." })
	end
	if counts.hugeParts > 0 then
		table.insert(issues, { severity = "info", code = "hugeParts", message = "Very large parts exist; verify scale and camera blocking." })
	end
	local world = V14.getWorldDesignAudit(payload)
	local result = {
		at = isoNow(),
		version = VERSION,
		counts = counts,
		examples = examples,
		issues = issues,
		worldDesignAudit = world,
		nextCommand = #issues > 0 and "tools/bridge.cmd world audit" or "tools/bridge.cmd launch-qa performance",
	}
	V31.last.mapQuality = result
	return result
end

function V31.getUniversalPerformanceAudit(payload)
	payload = payload or {}
	local counts, total = V31.classCounter(V31.serviceRootNames())
	local riskyScripts = {}
	for _, rootName in ipairs({ "ServerScriptService", "StarterPlayer", "StarterGui", "ReplicatedStorage" }) do
		local ok, root = pcall(function()
			return game:GetService(rootName)
		end)
		if ok and root then
			for _, instance in ipairs(root:GetDescendants()) do
				if instance:IsA("LuaSourceContainer") then
					local source = tostring(readScriptSource(instance) or "")
					local flags = {}
					if string.find(source, "while true do", 1, true) then
						table.insert(flags, "while true do")
					end
					if string.find(source, "RenderStepped", 1, true) then
						table.insert(flags, "RenderStepped")
					end
					if string.find(source, "Heartbeat", 1, true) then
						table.insert(flags, "Heartbeat")
					end
					if #flags > 0 and #riskyScripts < 20 then
						table.insert(riskyScripts, { path = safeFullName(instance), className = instance.ClassName, flags = flags })
					end
				end
			end
		end
	end
	local warnings = {}
	local lights = (counts.PointLight or 0) + (counts.SpotLight or 0) + (counts.SurfaceLight or 0)
	local particles = (counts.ParticleEmitter or 0) + (counts.Beam or 0) + (counts.Trail or 0)
	if (counts.BasePart or 0) + (counts.Part or 0) + (counts.MeshPart or 0) > 5000 then
		table.insert(warnings, { code = "highPartCount", message = "High part count; consider streaming/merging/LOD." })
	end
	if lights > 80 then
		table.insert(warnings, { code = "manyLights", message = "Many lights can hurt low-end devices." })
	end
	if particles > 120 then
		table.insert(warnings, { code = "manyVfx", message = "Many particles/beams/trails can hurt mobile performance." })
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		totalScanned = total,
		counts = {
			baseParts = (counts.BasePart or 0) + (counts.Part or 0) + (counts.MeshPart or 0) + (counts.UnionOperation or 0),
			models = counts.Model or 0,
			scripts = (counts.Script or 0) + (counts.LocalScript or 0) + (counts.ModuleScript or 0),
			lights = lights,
			particlesAndVfx = particles,
			sounds = counts.Sound or 0,
			constraints = (counts.WeldConstraint or 0) + (counts.Motor6D or 0) + (counts.HingeConstraint or 0),
		},
		rawClassCounts = counts,
		riskyScripts = riskyScripts,
		warnings = warnings,
		fpsMemory = {
			status = "runtimeHarnessRequired",
			message = "Roblox FPS/memory counters are not safely exposed to this edit plugin; use live playtest plus Output/microprofiler if needed.",
		},
		nextCommand = #warnings > 0 and "tools/bridge.cmd world audit" or "tools/bridge.cmd dashboard quick",
	}
	V31.last.performance = result
	return result
end

function V31.getLiveAttributeWatchReport(payload)
	payload = payload or {}
	local players = {}
	for _, player in ipairs(Players:GetPlayers()) do
		local item = V31.attributeSummary(player)
		item.leaderstats = {}
		local leaderstats = player:FindFirstChild("leaderstats")
		if leaderstats then
			for _, value in ipairs(leaderstats:GetChildren()) do
				if value:IsA("ValueBase") then
					table.insert(item.leaderstats, { name = value.Name, className = value.ClassName, value = serializeValue(value.Value) })
				end
			end
		end
		if player.Character then
			item.character = V31.attributeSummary(player.Character)
			local humanoid = player.Character:FindFirstChildOfClass("Humanoid")
			if humanoid then
				item.humanoid = { health = humanoid.Health, maxHealth = humanoid.MaxHealth, state = tostring(humanoid:GetState()) }
			end
		end
		table.insert(players, item)
	end
	local selected = {}
	for index, instance in ipairs(Selection:Get()) do
		if index > 20 then
			break
		end
		table.insert(selected, V31.attributeSummary(instance))
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		mode = getRuntimeStatus().mode,
		workspace = V31.attributeSummary(game:GetService("Workspace")),
		players = players,
		selected = selected,
		watch = V28.getWatchNow(payload),
		nextCommand = "tools/bridge.cmd watch moments",
	}
	V31.last.attributes = result
	return result
end

