		{ id = "shop-qa", title = "Shop QA", goal = "shop buttons, prices, currency feedback", commands = { "tools/bridge.cmd ui interactions", "tools/bridge.cmd attributes watch", "tools/bridge.cmd watch ui" } },
		{ id = "prompt-qa", title = "Prompt QA", goal = "prompt/interactable visibility and accessibility", commands = { "tools/bridge.cmd launch-qa map", "tools/bridge.cmd watch now", "tools/bridge.cmd launch-qa attributes" } },
		{ id = "save-load-qa", title = "Save/Load QA", goal = "leaderstats/data feedback and Output errors", commands = { "tools/bridge.cmd baseline mark", "tools/bridge.cmd launch-qa attributes", "tools/bridge.cmd baseline new" } },
		{ id = "first-10-minutes", title = "First 10 Minutes QA", goal = "join, spawn, objective clarity, feedback, reward, replay", commands = { "tools/bridge.cmd qa start first-10-minutes", "tools/bridge.cmd watch summary", "tools/bridge.cmd qa report" } },
		{ id = "performance-qa", title = "Performance QA", goal = "parts, scripts, lights, VFX, risky loops", commands = { "tools/bridge.cmd launch-qa performance", "tools/bridge.cmd code risks", "tools/bridge.cmd world audit" } },
