function V31.getAutomationRecipeCatalog(payload)
	payload = payload or {}
	local result = {
		at = isoNow(),
		version = VERSION,
		recipes = V31.recipeCatalog(),
		nextCommand = "tools/bridge.cmd launch-qa full",
	}
	V31.last.recipes = result
	return result
end

function V31.findRecipe(recipeId)
	recipeId = tostring(recipeId or "full-launch")
	for _, recipe in ipairs(V31.recipeCatalog()) do
		if recipe.id == recipeId then
			return recipe
		end
	end
	return V31.recipeCatalog()[1]
end

function V31.getAutomationRecipePlan(payload)
	payload = payload or {}
	local recipe = V31.findRecipe(payload.recipeId or payload.id)
	local result = {
		at = isoNow(),
		version = VERSION,
		recipe = recipe,
		safety = {
			mutatesStudio = false,
			requiresApproval = false,
			note = "This plan runs read-only checks. Any setup/build/patch commands it recommends still go through existing approval gates.",
		},
		steps = recipe.commands,
		nextCommand = recipe.commands[1],
	}
	V31.last.recipePlan = result
	return result
end

function V31.runAutomationRecipeCheck(payload)
	payload = payload or {}
	local recipe = V31.findRecipe(payload.recipeId or payload.id)
	local checks = {
		control = V31.getStudioControlReport(payload),
		output = V31.getOutputSinceBaseline({ limit = payload.outputLimit or 80 }),
		watch = V28.getWatchNow(payload),
	}
	if recipe.id == "mobile-qa" then
		checks.device = V31.getDeviceEmulationReport(payload)
		checks.ui = V31.getUniversalUiQaReport(payload)
	elseif recipe.id == "performance-qa" then
		checks.performance = V31.getUniversalPerformanceAudit(payload)
		checks.map = V31.getUniversalMapQualityAudit(payload)
	elseif recipe.id == "shop-qa" or recipe.id == "save-load-qa" then
		checks.ui = V31.getUniversalUiQaReport(payload)
		checks.attributes = V31.getLiveAttributeWatchReport(payload)
	elseif recipe.id == "prompt-qa" then
		checks.map = V31.getUniversalMapQualityAudit(payload)
		checks.attributes = V31.getLiveAttributeWatchReport(payload)
	else
		checks.ui = V31.getUniversalUiQaReport(payload)
		checks.map = V31.getUniversalMapQualityAudit(payload)
		checks.performance = V31.getUniversalPerformanceAudit(payload)
		checks.attributes = V31.getLiveAttributeWatchReport(payload)
		checks.screenshot = V31.getScreenshotVisionReport(payload)
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		recipe = recipe,
		checks = checks,
		nextCommand = "tools/bridge.cmd baseline new",
	}
	V31.last.recipeCheck = result
	return result
end

function V31.getFullLaunchQaReport(payload)
	payload = payload or {}
	local report = {
		at = isoNow(),
		version = VERSION,
		title = "Universal Full Launch QA",
		safety = "Read-only report. It does not click, patch, build, publish, or mutate Studio.",
		capabilities = V31.getUniversalBridgeCapabilityReport(payload),
		control = V31.getStudioControlReport(payload),
		output = V31.getOutputSinceBaseline({ limit = payload.outputLimit or 120 }),
		watch = V28.getWatchNow(payload),
		ui = V31.getUniversalUiQaReport(payload),
		map = V31.getUniversalMapQualityAudit(payload),
		performance = V31.getUniversalPerformanceAudit(payload),
		attributes = V31.getLiveAttributeWatchReport(payload),
		device = V31.getDeviceEmulationReport(payload),
		screenshot = V31.getScreenshotVisionReport(payload),
		recipes = V31.getAutomationRecipeCatalog(payload),
	}
	local blockers = {}
	if report.output.errorOrWarningCount and report.output.errorOrWarningCount > 0 then
		table.insert(blockers, "New Output errors/warnings since baseline.")
	end
	if report.control.mode == "edit" and not report.control.livePlayEvidence then
		table.insert(blockers, "Play mode is not running; live gameplay checks are structured/edit-only.")
	end
	report.blockers = blockers
	report.pass = #blockers == 0
	report.nextCommand = #blockers > 0 and "tools/bridge.cmd baseline new" or "tools/bridge.cmd dashboard quick"
	V31.last.fullLaunchQa = report
	return report
end

