function V32.clientSource()
	return [==[
local HttpService = game:GetService("HttpService")
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Workspace = game:GetService("Workspace")
local player = Players.LocalPlayer
local folder = ReplicatedStorage:WaitForChild("CodexActionBridge", 10)
local requestRemote = folder and folder:FindFirstChild("ActionRequested")
local resultRemote = folder and folder:FindFirstChild("ActionResult")
local registry = nil

local function pathOf(instance)
	local ok, path = pcall(function() return instance:GetFullName() end)
	return ok and path or tostring(instance)
end

local function attr(instance, name)
	local ok, value = pcall(function() return instance:GetAttribute(name) end)
	if ok then return value end
	return nil
end

local function stableId(kind, path, ordinal)
	local text = tostring(kind or "target") .. ":" .. tostring(path or "") .. ":" .. tostring(ordinal or 1)
	local hash = 0
	for index = 1, #text do
		hash = (hash * 31 + string.byte(text, index)) % 1000000007
	end
	return tostring(kind or "target") .. "-" .. tostring(hash) .. "-" .. tostring(ordinal or 1)
end

local function resolvePath(path)
	path = tostring(path or "")
	if path == "" then return nil end
	local parts = string.split(path, ".")
	local current = game
	if parts[1] == "game" then table.remove(parts, 1) end
	if parts[1] == "PlayerGui" then
		current = player:FindFirstChildOfClass("PlayerGui")
		table.remove(parts, 1)
	elseif parts[1] == "Workspace" or parts[1] == "ReplicatedStorage" then
		current = game:GetService(parts[1])
		table.remove(parts, 1)
	end
	for _, part in ipairs(parts) do
		if current then current = current:FindFirstChild(part) end
	end
	return current
end

local function targetMatches(instance, target)
	target = target or {}
	if target.path and pathOf(instance) == tostring(target.path) then return true end
	if target.name and instance.Name == tostring(target.name) then return true end
	if target.text and (instance:IsA("TextButton") or instance:IsA("TextLabel") or instance:IsA("TextBox")) then
		local itemText = string.lower(tostring(instance.Text or ""))
		local wantedText = string.lower(tostring(target.text))
		return itemText == wantedText or string.find(itemText, wantedText, 1, true) ~= nil
	end
	return false
end

local function isGuiVisible(instance)
	if not (instance and instance:IsA("GuiObject")) then return false end
	if instance.Visible == false then return false end
	local current = instance.Parent
	while current do
		if current:IsA("GuiObject") and current.Visible == false then
			return false
		end
		if current:IsA("ScreenGui") and current.Enabled == false then
			return false
		end
		current = current.Parent
	end
	return true
end

local function isActionableButton(instance)
	if not (instance and instance:IsA("GuiButton")) then return false end
	if not isGuiVisible(instance) then return false end
	if instance.Active == false then return false end
	return true
end

local function targetCenter(instance)
	if not (instance and instance:IsA("GuiObject")) then return nil end
	local pos = instance.AbsolutePosition
	local size = instance.AbsoluteSize
	return {
		x = pos.X + (size.X / 2),
		y = pos.Y + (size.Y / 2),
		absolutePosition = { x = pos.X, y = pos.Y },
		absoluteSize = { x = size.X, y = size.Y },
	}
end

local function loadRegistry()
	if registry ~= nil then return registry end
	local module = folder and folder:FindFirstChild("Registry")
	if not (module and module:IsA("ModuleScript")) then
		registry = false
		return nil
	end
	local ok, loaded = pcall(require, module)
	if ok and type(loaded) == "table" then
		registry = loaded
	else
		registry = false
	end
	return registry or nil
end

local function highlightTarget(instance)
	local playerGui = player:FindFirstChildOfClass("PlayerGui")
	local center = targetCenter(instance)
	if not (playerGui and center) then return { center = center } end
	local gui = playerGui:FindFirstChild("CodexActionBridgeHighlight")
	if gui then gui:Destroy() end
	gui = Instance.new("ScreenGui")
	gui.Name = "CodexActionBridgeHighlight"
	gui.ResetOnSpawn = false
	gui.IgnoreGuiInset = true
	gui.DisplayOrder = 100000
	gui.Parent = playerGui
	local frame = Instance.new("Frame")
	frame.Name = "Target"
	frame.BackgroundTransparency = 1
	frame.BorderSizePixel = 0
	frame.Position = UDim2.fromOffset(center.absolutePosition.x, center.absolutePosition.y)
	frame.Size = UDim2.fromOffset(math.max(8, center.absoluteSize.x), math.max(8, center.absoluteSize.y))
	frame.Parent = gui
	local okStroke = pcall(function()
		local stroke = Instance.new("UIStroke")
		stroke.Thickness = 3
		stroke.Color = Color3.fromRGB(255, 214, 80)
		stroke.Parent = frame
	end)
	if not okStroke then
		frame.BorderSizePixel = 3
		frame.BorderColor3 = Color3.fromRGB(255, 214, 80)
	end
	local label = Instance.new("TextLabel")
	label.Name = "Label"
	label.BackgroundTransparency = 0.2
	label.BackgroundColor3 = Color3.fromRGB(12, 16, 24)
	label.TextColor3 = Color3.fromRGB(255, 242, 180)
	label.Text = "Codex target"
	label.TextSize = 14
	label.Font = Enum.Font.SourceSansBold
	label.Size = UDim2.fromOffset(120, 24)
	label.Position = UDim2.fromOffset(0, -28)
	label.Parent = frame
	task.delay(8, function()
		if gui and gui.Parent then gui:Destroy() end
	end)
	return { center = center, overlayPath = pathOf(gui) }
end

local function findGui(target)
	local playerGui = player:FindFirstChildOfClass("PlayerGui")
	local matches = {}
	local exact = target and target.path and resolvePath(target.path)
	if exact and isActionableButton(exact) then return { exact } end
	if playerGui then
		local seenPathCounts = {}
		for _, descendant in ipairs(playerGui:GetDescendants()) do
			if isActionableButton(descendant) then
				local path = pathOf(descendant)
				seenPathCounts[path] = (seenPathCounts[path] or 0) + 1
				local id = stableId("ui", path, seenPathCounts[path])
				if target and target.id and id == tostring(target.id) then
					table.insert(matches, descendant)
				elseif targetMatches(descendant, target) then
					table.insert(matches, descendant)
				end
				if #matches > 10 then break end
			end
		end
	end
	return matches
end

local function findPrompt(target)
	local matches = {}
	local exact = target and target.path and resolvePath(target.path)
	if exact and exact:IsA("ProximityPrompt") then return { exact } end
	local seenPathCounts = {}
	for _, descendant in ipairs(Workspace:GetDescendants()) do
		if descendant:IsA("ProximityPrompt") then
			local path = pathOf(descendant)
			seenPathCounts[path] = (seenPathCounts[path] or 0) + 1
			local id = stableId("prompt", path, seenPathCounts[path])
			local text = tostring(descendant.ActionText or "") .. " " .. tostring(descendant.ObjectText or "")
			if (target and target.id and id == tostring(target.id))
				or targetMatches(descendant, target)
				or (target and target.text and string.find(string.lower(text), string.lower(tostring(target.text)), 1, true)) then
				table.insert(matches, descendant)
				if #matches > 10 then break end
			end
		end
	end
	return matches
end

local function summarizeTarget(instance)
	if not instance then return nil end
	local text = nil
	if instance:IsA("TextButton") or instance:IsA("TextLabel") or instance:IsA("TextBox") then
		text = tostring(instance.Text or "")
	end
	local center = targetCenter(instance)
	local actionId = attr(instance, "CodexActionId")
	local actionSafe = attr(instance, "CodexActionSafe") == true
	return {
		path = pathOf(instance),
		name = instance.Name,
		text = text,
		className = instance.ClassName,
		visible = instance:IsA("GuiObject") and isGuiVisible(instance) or nil,
		active = instance:IsA("GuiObject") and instance.Active or nil,
		selectable = instance:IsA("GuiObject") and instance.Selectable or nil,
		absolutePosition = center and center.absolutePosition or nil,
		absoluteSize = center and center.absoluteSize or nil,
		center = center and { x = center.x, y = center.y } or nil,
		zIndex = instance:IsA("GuiObject") and instance.ZIndex or nil,
		actionId = actionId,
		actionLabel = attr(instance, "CodexActionLabel"),
		actionSafe = actionSafe,
		actionRequiresApproval = attr(instance, "CodexActionRequiresApproval") ~= false,
	}
end

local function executeRegisteredAction(instance, action)
	local target = summarizeTarget(instance)
	local actionId = (action.target and action.target.actionId) or target.actionId
	if not actionId or tostring(actionId) == "" then return nil end
	local reg = loadRegistry()
	if not (reg and type(reg.Execute) == "function") then
		return nil
	end
	local attributeSafe = target.actionSafe == true or (action.target and action.target.actionSafe == true)
	local ok, success, result = pcall(function()
		return reg.Execute(tostring(actionId), {
			actionId = tostring(actionId),
			button = instance,
			target = target,
			requestedTarget = action.target,
			approved = true,
			source = "CodexActionBridge",
		}, { attributeSafe = attributeSafe })
	end)
	if not ok then
		return { status = "failed", detail = { target = target, actionId = tostring(actionId), reason = tostring(success) } }
	end
	if success == true then
		return { status = "registeredActionExecuted", detail = { target = target, actionId = tostring(actionId), result = result } }
	end
	return { status = "manualRequired", detail = { target = target, actionId = tostring(actionId), reason = tostring(result or "registered action is missing or not marked safe") } }
end

local function respond(actionId, status, detail)
	if resultRemote then
		resultRemote:FireServer({ actionId = actionId, status = status, detail = detail or {}, clientAt = os.clock() })
	end
	print("[CodexActionBridge] result", tostring(actionId), tostring(status), HttpService:JSONEncode(detail or {}))
end

local function handleUiClick(action)
	local matches = findGui(action.target or {})
	if #matches == 0 then return respond(action.id, "notFound", { reason = "No matching visible/interactable UI button.", requestedTarget = action.target }) end
	if #matches > 1 then
		local candidates = {}
		for _, item in ipairs(matches) do table.insert(candidates, summarizeTarget(item)) end
		return respond(action.id, "ambiguous", { candidates = candidates, requestedTarget = action.target, recommendedSelector = "Use --id <target-id> or exact --path." })
	end
	local target = matches[1]
	local registered = executeRegisteredAction(target, action)
	local registryFallback = nil
	if registered and (registered.status == "registeredActionExecuted" or registered.status == "failed") then
		return respond(action.id, registered.status, registered.detail)
	elseif registered then
		registryFallback = registered.detail
	end
	local highlight = highlightTarget(target)
	return respond(action.id, "manualRequired", {
		target = summarizeTarget(target),
		requestedTarget = action.target,
		reason = "physical click simulation unavailable and no registered safe action is available",
		suggestedManualAction = "Click the highlighted/reported button manually, then run tools/bridge.cmd action ui watch-after-click.",
		safeActivationAvailable = false,
		highlight = highlight,
		registryFallback = registryFallback,
	})
end

local function handlePrompt(action)
	local matches = findPrompt(action.target or {})
	if #matches == 0 then return respond(action.id, "notFound", { reason = "No matching ProximityPrompt." }) end
	if #matches > 1 then
		local candidates = {}
		for _, item in ipairs(matches) do table.insert(candidates, summarizeTarget(item)) end
		return respond(action.id, "ambiguous", { candidates = candidates })
	end
	local prompt = matches[1]
	local ok, err = pcall(function()
		prompt:InputHoldBegin()
		task.wait(math.max(0.05, tonumber(prompt.HoldDuration) or 0))
		prompt:InputHoldEnd()
	end)
	if ok then return respond(action.id, "triggered", { target = summarizeTarget(prompt) }) end
	return respond(action.id, "manualRequired", { target = summarizeTarget(prompt), reason = tostring(err) })
end

local function handleRemote(action)
	local remote = resolvePath(action.remotePath or action.path)
	local payload = action.payload
	if remote and remote:IsA("RemoteEvent") then
		local ok, err = pcall(function() remote:FireServer(payload) end)
		return respond(action.id, ok and "fired" or "failed", { target = summarizeTarget(remote), error = ok and nil or tostring(err) })
	end
	if remote and remote:IsA("RemoteFunction") then
		local ok, result = pcall(function() return remote:InvokeServer(payload) end)
		return respond(action.id, ok and "invoked" or "failed", { target = summarizeTarget(remote), resultType = typeof(result), error = ok and nil or tostring(result) })
	end
	return respond(action.id, "notFound", { reason = "RemoteEvent/RemoteFunction not found." })
end

local function handle(action)
	if type(action) ~= "table" then return end
	if action.type == "uiClick" then return handleUiClick(action) end
	if action.type == "promptTrigger" then return handlePrompt(action) end
	if action.type == "testRemote" then return handleRemote(action) end
	respond(action.id, "unsupported", { type = tostring(action.type) })
end

print("[CodexActionBridge] client ready")
if requestRemote then
	requestRemote.OnClientEvent:Connect(handle)
else
	print("[CodexActionBridge] ActionRequested remote missing")
end
]==]
end

function V32.registrySource()
	return [==[
local Registry = {}
local entries = {}

local function normalizeOptions(options)
	options = type(options) == "table" and options or {}
	return {
		label = options.label,
		safe = options.safe == true,
		requiresApproval = options.requiresApproval ~= false,
		source = options.source or "game",
	}
end

function Registry.Register(actionId, callback, options)
	assert(type(actionId) == "string" and actionId ~= "", "Codex action id must be a non-empty string")
	assert(type(callback) == "function", "Codex action callback must be a function")
	local normalized = normalizeOptions(options)
	entries[actionId] = {
		id = actionId,
		callback = callback,
		label = normalized.label,
		safe = normalized.safe,
		requiresApproval = normalized.requiresApproval,
		source = normalized.source,
	}
	return entries[actionId]
end

function Registry.BindButton(button, actionId, callback, options)
	local entry = Registry.Register(actionId, callback, options)
	if typeof(button) == "Instance" then
		button:SetAttribute("CodexActionId", actionId)
		if entry.label then button:SetAttribute("CodexActionLabel", entry.label) end
		button:SetAttribute("CodexActionSafe", entry.safe == true)
		button:SetAttribute("CodexActionRequiresApproval", entry.requiresApproval ~= false)
	end
	return entry
end

function Registry.List()
	local list = {}
	for id, entry in pairs(entries) do
		table.insert(list, {
			id = id,
			label = entry.label,
			safe = entry.safe == true,
			requiresApproval = entry.requiresApproval ~= false,
			source = entry.source,
		})
	end
	table.sort(list, function(a, b) return tostring(a.id) < tostring(b.id) end)
	return list
end

function Registry.Execute(actionId, context, options)
	local entry = entries[tostring(actionId or "")]
	if not entry then
		return false, "action is not registered"
	end
	local attributeSafe = type(options) == "table" and options.attributeSafe == true
	if entry.safe ~= true and attributeSafe ~= true then
		return false, "action is not marked safe"
	end
	local ok, result = pcall(entry.callback, context or {})
	if not ok then
		return false, tostring(result)
	end
	return true, result
end

return Registry
]==]
end

function V32.relaySource()
	return [==[
local HttpService = game:GetService("HttpService")
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Workspace = game:GetService("Workspace")
local folder = ReplicatedStorage:WaitForChild("CodexActionBridge", 10)
local requestRemote = folder and folder:FindFirstChild("ActionRequested")
local resultRemote = folder and folder:FindFirstChild("ActionResult")
local requestValue = folder and folder:FindFirstChild("LastActionRequest")
local resultValue = folder and folder:FindFirstChild("LastActionResult")
local lastRequest = ""

local function pathOf(instance)
	local ok, path = pcall(function() return instance:GetFullName() end)
	return ok and path or tostring(instance)
end

local function resolvePath(path)
	path = tostring(path or "")
	if path == "" then return nil end
	local parts = string.split(path, ".")
	local current = game
	if parts[1] == "game" then table.remove(parts, 1) end
	if parts[1] == "Workspace" or parts[1] == "ReplicatedStorage" or parts[1] == "Players" then
		current = game:GetService(parts[1])
		table.remove(parts, 1)
	end
	for _, part in ipairs(parts) do
		if current then current = current:FindFirstChild(part) end
	end
	return current
end

local function writeResult(actionId, status, detail)
	local payload = { actionId = actionId, status = status, detail = detail or {}, serverAt = os.clock() }
	if resultValue then resultValue.Value = HttpService:JSONEncode(payload) end
	print("[CodexActionBridge] result", tostring(actionId), tostring(status), HttpService:JSONEncode(detail or {}))
end

local function teleportNearPrompt(action)
	local target = resolvePath(action.target and action.target.path)
	if not (target and target:IsA("ProximityPrompt")) then
		return writeResult(action.id, "notFound", { reason = "Prompt path not found." })
	end
	local player = Players:FindFirstChild(tostring(action.playerName or "")) or Players:GetPlayers()[1]
	local root = player and player.Character and player.Character:FindFirstChild("HumanoidRootPart")
	local parentPart = target.Parent and target.Parent:IsA("BasePart") and target.Parent or target:FindFirstAncestorWhichIsA("BasePart")
	if not (root and parentPart) then
		return writeResult(action.id, "failed", { reason = "Player root or prompt part missing." })
	end
	root.CFrame = parentPart.CFrame + Vector3.new(0, 3, 0)
	writeResult(action.id, "teleported", { player = player.Name, target = pathOf(target), position = tostring(root.Position) })
end

local function forward(action)
	if action.type == "teleportNearPrompt" then return teleportNearPrompt(action) end
	if requestRemote then
		requestRemote:FireAllClients(action)
		print("[CodexActionBridge] forwarded", tostring(action.id), tostring(action.type))
	else
		writeResult(action.id, "failed", { reason = "ActionRequested remote missing." })
	end
end

if resultRemote then
	resultRemote.OnServerEvent:Connect(function(player, result)
		if type(result) ~= "table" then return end
		result.playerName = player.Name
		if resultValue then resultValue.Value = HttpService:JSONEncode(result) end
		print("[CodexActionBridge] client result", tostring(result.actionId), tostring(result.status), tostring(player.Name))
	end)
end

print("[CodexActionBridge] relay ready")
task.spawn(function()
	while true do
		task.wait(0.25)
		if requestValue and requestValue.Value ~= "" and requestValue.Value ~= lastRequest then
			lastRequest = requestValue.Value
			local ok, action = pcall(function() return HttpService:JSONDecode(lastRequest) end)
			if ok and type(action) == "table" then forward(action) end
		end
	end
end)
]==]
end

function V32.actionBridgeHarnessBlueprint(payload)
	payload = payload or {}
	local profile = V7.profileFromPayload(payload)
	return {
		name = "Codex Action Bridge Harness",
		mode = "supervised",
		source = "installActionBridgeHarness",
		steps = {
			{ type = "ensureFolder", path = "ReplicatedStorage.CodexActionBridge" },
			{ type = "ensureRemoteEvent", path = "ReplicatedStorage.CodexActionBridge.ActionRequested" },
			{ type = "ensureRemoteEvent", path = "ReplicatedStorage.CodexActionBridge.ActionResult" },
			{ type = "createInstance", className = "StringValue", path = "ReplicatedStorage.CodexActionBridge.LastActionRequest", properties = { Value = "" } },
			{ type = "createInstance", className = "StringValue", path = "ReplicatedStorage.CodexActionBridge.LastActionResult", properties = { Value = "" } },
			V25.scriptWriteStep("ReplicatedStorage.CodexActionBridge.Registry", "ModuleScript", V32.registrySource()),
			V25.scriptWriteStep("StarterPlayer.StarterPlayerScripts.CodexActionBridgeClient", "LocalScript", V32.clientSource()),
			V25.scriptWriteStep("ServerScriptService.CodexActionBridgeRelay", "Script", V32.relaySource()),
			V25.scriptWriteStep("ReplicatedStorage.CodexActionBridge.Manifest", "ModuleScript", "return { name = \"CodexActionBridge\", version = \"" .. VERSION .. "\", profile = \"" .. V8.luaString(profile.id or "universal") .. "\" }\n"),
		},
	}
end

function V32.getActionBridgeStatus(payload)
	payload = payload or {}
	local paths = {}
	local installed = 0
	for _, path in ipairs(V32.actionBridgePaths()) do
		local instance = resolvePath(path)
		if instance then
			installed += 1
			table.insert(paths, { path = path, exists = true, className = instance.ClassName, id = getInstanceId(instance) })
		else
			table.insert(paths, { path = path, exists = false })
		end
	end
	local manifest = resolvePath("ReplicatedStorage.CodexActionBridge.Manifest")
	local versionCurrent = false
	if manifest and manifest:IsA("LuaSourceContainer") then
		versionCurrent = string.find(tostring(readScriptSource(manifest) or ""), "version = \"" .. VERSION .. "\"", 1, true) ~= nil
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		installed = installed == #paths,
		partial = installed > 0 and installed < #paths,
		status = installed == #paths and (versionCurrent and "installed" or "outdated") or "missing",
		versionCurrent = versionCurrent,
		installedCount = installed,
		missingCount = #paths - installed,
		paths = payload.shallow and nil or paths,
		nextCommand = installed == #paths and "tools/bridge.cmd action ui list" or "tools/bridge.cmd ready apply",
	}
	V32.last.actionBridgeStatus = result
	return result
end

function V32.installActionBridgeHarness(payload)
	return applyBuildPlan({ blueprint = V32.actionBridgeHarnessBlueprint(payload or {}) })
end

function V32.removeActionBridgeHarness(payload)
	payload = payload or {}
	return withUndo("RemoveActionBridgeHarness", function()
		local removed = {}
		for _, path in ipairs({
			"ReplicatedStorage.CodexActionBridge",
			"StarterPlayer.StarterPlayerScripts.CodexActionBridgeClient",
			"ServerScriptService.CodexActionBridgeRelay",
		}) do
			local instance = resolvePath(path)
			if instance then
				table.insert(removed, { path = safeFullName(instance), className = instance.ClassName })
				instance:Destroy()
			end
		end
		stateDirty = true
		return { at = isoNow(), version = VERSION, removed = removed, count = #removed }
	end)
end

function V32.guiSources()
	local sources = {}
	local starterGui = game:GetService("StarterGui")
	table.insert(sources, { label = "StarterGui", root = starterGui, contextType = "edit" })
	for _, player in ipairs(Players:GetPlayers()) do
		local playerGui = player:FindFirstChildOfClass("PlayerGui")
		if playerGui then
			table.insert(sources, { label = "PlayerGui:" .. player.Name, root = playerGui, contextType = "testClient", playerName = player.Name })
		end
	end
	return sources
end

function V32.vectorComponent(value, key)
	if typeof(value) == "Vector2" then
		return key == "x" and value.X or value.Y
	end
	if type(value) == "table" then
		return tonumber(value[key])
			or tonumber(value[string.upper(key)])
			or (key == "x" and tonumber(value[1]) or tonumber(value[2]))
	end
	if type(value) == "string" then
		local first, second = string.match(value, "([%-%.%d]+)%D+([%-%.%d]+)")
		return key == "x" and tonumber(first) or tonumber(second)
	end
	return nil
end

function V32.centerFromTarget(target)
	target = target or {}
	local pos = target.absolutePosition
	local size = target.absoluteSize
	local x = V32.vectorComponent(pos, "x")
	local y = V32.vectorComponent(pos, "y")
	local w = V32.vectorComponent(size, "x")
	local h = V32.vectorComponent(size, "y")
	if not (x and y and w and h) then return nil end
	return {
		x = x + (w / 2),
		y = y + (h / 2),
		absolutePosition = { x = x, y = y },
		absoluteSize = { x = w, y = h },
	}
end

function V32.createVirtualInput()
	local okService, inputService = pcall(function() return game:GetService("UserInputService") end)
	if not okService or not inputService then
		return nil, "UserInputService unavailable"
	end
	local okCreate, virtualInput = pcall(function() return inputService:CreateVirtualInput() end)
	if not okCreate or not virtualInput then
		return nil, tostring(virtualInput or "UserInputService:CreateVirtualInput unavailable")
	end
	return virtualInput, nil
end

function V32.virtualInputCapability()
	local cached = V32.last.virtualInputCapability
	if cached and cached.checkedAt and os.clock() - cached.checkedAt < 30 then
		return cached
	end
	local virtualInput, reason = V32.createVirtualInput()
	local result = {
		available = virtualInput ~= nil,
		method = "UserInputService:CreateVirtualInput",
		reason = reason,
		checkedAt = os.clock(),
	}
	V32.last.virtualInputCapability = result
	return result
end

function V32.decorateUiTarget(item)
	item = item or {}
	item.center = item.center or V32.centerFromTarget(item)
	item.directClickable = V32.virtualInputCapability().available == true
	item.registeredAction = item.registeredAction == true and (item.actionSafe == true or item.registeredActionSafe == true)
	item.actionMode = item.registeredAction and "registeredAction" or (item.directClickable and "directClickable" or "manualOnly")
	return item
end

function V32.uiTargetSummary(instance, source)
	local actionId = instance:GetAttribute("CodexActionId")
	local actionSafe = instance:GetAttribute("CodexActionSafe") == true
	local item = {
		id = getInstanceId(instance),
		path = safeFullName(instance),
		name = instance.Name,
		className = instance.ClassName,
		source = source and source.label or nil,
		contextType = source and source.contextType or nil,
		playerName = source and source.playerName or nil,
		visible = instance:IsA("GuiObject") and instance.Visible or nil,
		text = (instance:IsA("TextButton") or instance:IsA("TextLabel") or instance:IsA("TextBox")) and tostring(instance.Text or "") or nil,
		size = instance:IsA("GuiObject") and serializeValue(instance.Size) or nil,
		position = instance:IsA("GuiObject") and serializeValue(instance.Position) or nil,
		absoluteSize = instance:IsA("GuiObject") and serializeValue(instance.AbsoluteSize) or nil,
		absolutePosition = instance:IsA("GuiObject") and serializeValue(instance.AbsolutePosition) or nil,
		zIndex = instance:IsA("GuiObject") and instance.ZIndex or nil,
		actionId = actionId,
		actionLabel = instance:GetAttribute("CodexActionLabel"),
		actionSafe = actionSafe,
		actionRequiresApproval = instance:GetAttribute("CodexActionRequiresApproval") ~= false,
		registeredAction = false,
	}
	return V32.decorateUiTarget(item)
end

-- kept for older call-sites that expect a compact target table
function V32.legacyUiTargetSummary(instance, source)
	return {
		id = getInstanceId(instance),
		path = safeFullName(instance),
		name = instance.Name,
		className = instance.ClassName,
		source = source and source.label or nil,
		contextType = source and source.contextType or nil,
		playerName = source and source.playerName or nil,
		visible = instance:IsA("GuiObject") and instance.Visible or nil,
		text = (instance:IsA("TextButton") or instance:IsA("TextLabel") or instance:IsA("TextBox")) and tostring(instance.Text or "") or nil,
		size = instance:IsA("GuiObject") and serializeValue(instance.Size) or nil,
		position = instance:IsA("GuiObject") and serializeValue(instance.Position) or nil,
		absoluteSize = instance:IsA("GuiObject") and serializeValue(instance.AbsoluteSize) or nil,
		absolutePosition = instance:IsA("GuiObject") and serializeValue(instance.AbsolutePosition) or nil,
		zIndex = instance:IsA("GuiObject") and instance.ZIndex or nil,
	}
end

function V32.targetMatchesSelector(item, payload)
	payload = payload or {}
	if payload.id and tostring(item.id or "") == tostring(payload.id) then return true end
	if payload.path and tostring(item.path or "") == tostring(payload.path) then return true end
	if payload.name and tostring(item.name or "") == tostring(payload.name) then return true end
	if payload.text then
		local itemText = string.lower(tostring(item.text or ""))
		local wantedText = string.lower(tostring(payload.text))
		if itemText == wantedText or string.find(itemText, wantedText, 1, true) then
			return true
		end
	end
	local query = string.lower(tostring(payload.query or ""))
	if query ~= "" then
		local haystack = string.lower(tostring(item.id or "") .. " " .. tostring(item.path or "") .. " " .. tostring(item.name or "") .. " " .. tostring(item.text or ""))
		return string.find(haystack, query, 1, true) ~= nil
	end
	return false
end

function V32.selectorIsSpecific(payload)
	payload = payload or {}
	return payload.id ~= nil or payload.path ~= nil or payload.name ~= nil or payload.text ~= nil or tostring(payload.query or "") ~= ""
end

function V32.recommendedSelector(item)
	if not item then return nil end
	if item.id then return "--id " .. tostring(item.id) end
	if item.path then return "--path " .. tostring(item.path) end
	return nil
end

function V32.latestLiveUiTargets(payload)
	payload = payload or {}
	local bridge = V27.bridgeGet("/codex/awareness")
	local categories = bridge and bridge.latestByCategory
	local pulseCandidates = {
		bridge and bridge.latest,
		categories and categories.testClient,
		categories and categories.ui,
		bridge and bridge.latestAny,
	}
	local pulse = nil
	for _, candidate in ipairs(pulseCandidates) do
		if candidate and candidate.ui and type(candidate.ui.clickTargets) == "table" and #candidate.ui.clickTargets > 0 then
			pulse = candidate
			break
		end
	end
	pulse = pulse or (bridge and (bridge.latest or bridge.latestAny))
	local rawTargets = pulse and pulse.ui and pulse.ui.clickTargets
	local targets = {}
	if type(rawTargets) == "table" then
		for index, raw in ipairs(rawTargets) do
			local item = {
				id = raw.id or ("ui-live-" .. tostring(index)),
				path = raw.path,
				name = raw.name,
				text = raw.text,
				className = raw.className,
				visible = raw.visible,
				active = raw.active,
				selectable = raw.selectable,
				interactable = raw.interactable,
				enabled = raw.enabled,
				screenGui = raw.screenGui,
				root = raw.root,
				absolutePosition = raw.absolutePosition,
				absoluteSize = raw.absoluteSize,
				position = raw.position,
				size = raw.size,
				zIndex = raw.zIndex,
				displayOrder = raw.displayOrder,
				playerName = raw.playerName or (pulse.player and pulse.player.name) or pulse.playerName,
				contextType = raw.contextType or pulse.contextType or "testClient",
				source = "realtimeAwareness",
				receivedAt = pulse.receivedAt or pulse.at,
				actionId = raw.actionId,
				actionLabel = raw.actionLabel,
				actionSafe = raw.actionSafe == true,
				actionRequiresApproval = raw.actionRequiresApproval ~= false,
				registeredAction = raw.registeredAction == true,
				registeredActionSafe = raw.registeredActionSafe == true,
				actionMode = raw.actionMode,
			}
			table.insert(targets, V32.decorateUiTarget(item))
		end
	end
	return targets, bridge, pulse
end

function V32.getUiActionTargets(payload)
	payload = payload or {}
	local query = string.lower(tostring(payload.query or ""))
	local specific = V32.selectorIsSpecific(payload)
	local targets = {}
	local liveTargets, bridge, pulse = V32.latestLiveUiTargets(payload)
	for _, item in ipairs(liveTargets) do
		table.insert(targets, item)
	end
	local usedLive = #targets > 0
	if #targets == 0 then
		for _, source in ipairs(V32.guiSources()) do
			for _, instance in ipairs(source.root:GetDescendants()) do
				if instance:IsA("TextButton") or instance:IsA("ImageButton") or instance:IsA("GuiButton") then
					local item = V32.uiTargetSummary(instance, source)
					table.insert(targets, item)
				end
			end
		end
	end
	local matches = {}
	if specific then
		for _, item in ipairs(targets) do
			if V32.targetMatchesSelector(item, payload) then
				table.insert(matches, item)
			end
		end
	end
	local returnedTargets = specific and matches or targets
	local ambiguous = specific and #matches > 1 or false
	local result = {
		at = isoNow(),
		version = VERSION,
		query = query ~= "" and query or nil,
		selector = { id = payload.id, path = payload.path, name = payload.name, text = payload.text },
		count = #targets,
		targets = returnedTargets,
		candidates = ambiguous and matches or nil,
		totalUnfiltered = #targets,
		ambiguous = ambiguous,
		source = usedLive and "realtimeAwareness" or "pluginScan",
		liveAwareness = bridge and bridge.status or nil,
		livePulseAt = pulse and (pulse.receivedAt or pulse.at) or nil,
		recommendedSelector = returnedTargets[1] and V32.recommendedSelector(returnedTargets[1]) or nil,
		nextCommand = ambiguous and "tools/bridge.cmd action ui click --id <target-id>" or "tools/bridge.cmd action ui click --path <path>",
	}
	V32.last.uiTargets = result
	return result
end

function V32.firstPlayerRoot()
	for _, player in ipairs(Players:GetPlayers()) do
		local root = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
		if root then
			return player, root
		end
	end
	return nil, nil
end

function V32.stableTargetId(kind, path, ordinal)
	local text = tostring(kind or "target") .. ":" .. tostring(path or "") .. ":" .. tostring(ordinal or 1)
	local hash = 0
	for index = 1, #text do
		hash = (hash * 31 + string.byte(text, index)) % 1000000007
	end
	return tostring(kind or "target") .. "-" .. tostring(hash) .. "-" .. tostring(ordinal or 1)
end

function V32.promptSummary(instance, playerRoot, ordinal)
	local part = instance.Parent and instance.Parent:IsA("BasePart") and instance.Parent or instance:FindFirstAncestorWhichIsA("BasePart")
	local distance = nil
	if part and playerRoot then
		distance = (part.Position - playerRoot.Position).Magnitude
	end
	local path = safeFullName(instance)
	return {
		id = V32.stableTargetId("prompt", path, ordinal or 1),
		path = path,
		name = instance.Name,
		className = instance.ClassName,
		actionText = instance.ActionText,
		objectText = instance.ObjectText,
		text = tostring(instance.ActionText or "") .. " " .. tostring(instance.ObjectText or ""),
		enabled = instance.Enabled,
		holdDuration = instance.HoldDuration,
		maxActivationDistance = instance.MaxActivationDistance,
		parentPath = instance.Parent and safeFullName(instance.Parent) or nil,
		distanceFromPlayer = distance and math.floor(distance * 10) / 10 or nil,
		playerTooFar = distance and distance > instance.MaxActivationDistance or nil,
		duplicateOrdinal = ordinal or 1,
	}
end

function V32.getPromptActionTargets(payload)
	payload = payload or {}
	local query = string.lower(tostring(payload.query or ""))
	local _, root = V32.firstPlayerRoot()
	local prompts = {}
	local matches = {}
	local specific = V32.selectorIsSpecific(payload)
	local pathCounts = {}
	for _, instance in ipairs(game:GetService("Workspace"):GetDescendants()) do
		if instance:IsA("ProximityPrompt") then
			local path = safeFullName(instance)
			pathCounts[path] = (pathCounts[path] or 0) + 1
			local item = V32.promptSummary(instance, root, pathCounts[path])
			table.insert(prompts, item)
			if specific and V32.targetMatchesSelector(item, payload) then
				table.insert(matches, item)
			end
		end
	end
	local returnedTargets = specific and matches or prompts
	local ambiguous = specific and #matches > 1 or false
	local result = {
		at = isoNow(),
		version = VERSION,
		query = query ~= "" and query or nil,
		selector = { id = payload.id, path = payload.path, name = payload.name, text = payload.text },
		count = #prompts,
		targets = returnedTargets,
		candidates = ambiguous and matches or nil,
		totalUnfiltered = #prompts,
		ambiguous = ambiguous,
		recommendedSelector = returnedTargets[1] and V32.recommendedSelector(returnedTargets[1]) or nil,
		nextCommand = ambiguous and "tools/bridge.cmd action prompt trigger --id <target-id>" or "tools/bridge.cmd action prompt trigger --path <path>",
	}
	V32.last.promptTargets = result
	return result
end

function V32.getInteractableMap(payload)
	payload = payload or {}
	local promptReport = V32.getPromptActionTargets(payload)
	local clickDetectors = {}
	local pads = {}
	for _, instance in ipairs(game:GetService("Workspace"):GetDescendants()) do
		if instance:IsA("ClickDetector") then
			table.insert(clickDetectors, {
				id = getInstanceId(instance),
				path = safeFullName(instance),
				parentPath = instance.Parent and safeFullName(instance.Parent) or nil,
				maxActivationDistance = instance.MaxActivationDistance,
			})
		elseif instance:IsA("BasePart") then
			local name = string.lower(instance.Name)
			if string.find(name, "pad", 1, true) or string.find(name, "button", 1, true) or string.find(name, "checkpoint", 1, true) or string.find(name, "claim", 1, true) then
				table.insert(pads, { id = getInstanceId(instance), path = safeFullName(instance), name = instance.Name, size = serializeValue(instance.Size), position = serializeValue(instance.Position) })
				if #pads >= 80 then
					break
				end
			end
		end
	end
	return {
		at = isoNow(),
		version = VERSION,
		prompts = promptReport.targets,
		promptCount = promptReport.count,
		clickDetectors = clickDetectors,
		clickDetectorCount = #clickDetectors,
		likelyTouchPads = pads,
		likelyTouchPadCount = #pads,
		nextCommand = "tools/bridge.cmd action prompt list",
	}
end

function V32.remoteSummary(instance)
	return {
		id = getInstanceId(instance),
		path = safeFullName(instance),
		name = instance.Name,
		className = instance.ClassName,
		parentPath = instance.Parent and safeFullName(instance.Parent) or nil,
	}
end

function V32.getRemoteTraceReport(payload)
	payload = payload or {}
	local remotes = {}
	local bindables = {}
	for _, rootName in ipairs({ "ReplicatedStorage", "Workspace", "ServerScriptService", "StarterPlayer", "StarterGui" }) do
		local ok, root = pcall(function() return game:GetService(rootName) end)
		if ok and root then
			for _, instance in ipairs(root:GetDescendants()) do
				if instance:IsA("RemoteEvent") or instance:IsA("RemoteFunction") then
					table.insert(remotes, V32.remoteSummary(instance))
				elseif instance:IsA("BindableEvent") or instance:IsA("BindableFunction") then
					table.insert(bindables, V32.remoteSummary(instance))
				end
			end
		end
	end
	local output = V31.getOutputSinceBaseline({ limit = payload.limit or 100 })
	local markers = {}
	for _, entry in ipairs(output.messages or {}) do
		local message = tostring(entry.message or "")
		if string.find(message, "[CodexActionBridge]", 1, true) or string.find(string.lower(message), "remote", 1, true) then
			table.insert(markers, entry)
		end
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		remotes = remotes,
		remoteCount = #remotes,
		bindables = bindables,
		bindableCount = #bindables,
		traceMarkers = markers,
		note = "Remote payload tracing is summary-only. Test invocation is blocked for external-risk safety unless explicitly handled manually.",
		nextCommand = "tools/bridge.cmd action remote trace",
	}
	V32.last.remoteTrace = result
	return result
end

function V32.classifyViewport(width, height)
	width = tonumber(width) or 0
	height = tonumber(height) or 0
	local orientation = width >= height and "landscape" or "portrait"
	local kind = "desktop"
	if math.min(width, height) <= 480 then
		kind = orientation == "portrait" and "phone-portrait" or "phone-landscape"
	elseif math.min(width, height) <= 900 and math.max(width, height) <= 1280 then
		kind = "tablet"
	end
	return kind, orientation
end

function V32.getDeviceViewportStatus(payload)
	payload = payload or {}
	local camera = V25.getCameraViewReport(payload)
	local viewport = camera.camera and camera.camera.viewportSize
	local width = viewport and viewport.x or nil
	local height = viewport and viewport.y or nil
	local kind, orientation = V32.classifyViewport(width, height)
	local targets = {
		["phone-portrait"] = { w = 390, h = 844, tolerance = 80 },
		["phone-landscape"] = { w = 844, h = 390, tolerance = 80 },
		tablet = { w = 1024, h = 768, tolerance = 120 },
		desktop = { w = 1366, h = 768, tolerance = 220 },
	}
	local targetId = tostring(payload.target or payload.device or "")
	local target = targets[targetId]
	local matches = false
	if target and width and height then
		matches = math.abs(width - target.w) <= target.tolerance and math.abs(height - target.h) <= target.tolerance
	end
	return {
		at = isoNow(),
		version = VERSION,
		width = width,
		height = height,
		classification = kind,
		orientation = orientation,
		target = targetId ~= "" and targetId or nil,
		targetMatches = target and matches or nil,
		targets = targets,
		canSwitchAutomatically = false,
		manualSteps = "Use Roblox Studio's device emulator/resolution controls, then rerun tools/bridge.cmd device verify " .. (targetId ~= "" and targetId or "<target>") .. ".",
		nextCommand = target and (matches and "tools/bridge.cmd launch-qa mobile-qa report" or "tools/bridge.cmd device verify " .. targetId) or "tools/bridge.cmd device report",
		camera = camera.camera,
	}
end

function V32.actionSnapshot(label)
	return {
		label = label,
		at = isoNow(),
		output = V31.getOutputSinceBaseline({ limit = 80 }),
		watch = V28.getWatchNow({}),
		attributes = V31.getLiveAttributeWatchReport({}),
		ui = V25.getVisibleUiReport({}),
		world = V8.getRuntimeWorldSummary({}),
		remotes = V32.getRemoteTraceReport({ limit = 80 }),
	}
end

function V32.summarizeDiff(before, after)
	local changed = {}
	local unchanged = {}
	local beforeOutput = before.output and before.output.errorOrWarningCount or 0
	local afterOutput = after.output and after.output.errorOrWarningCount or 0
	if beforeOutput ~= afterOutput then
		table.insert(changed, { field = "outputErrors", before = beforeOutput, after = afterOutput })
	else
		table.insert(unchanged, "outputErrors")
	end
	local beforeUi = before.ui and before.ui.counts and before.ui.counts.visible or 0
	local afterUi = after.ui and after.ui.counts and after.ui.counts.visible or 0
	if beforeUi ~= afterUi then
		table.insert(changed, { field = "visibleUi", before = beforeUi, after = afterUi })
	else
		table.insert(unchanged, "visibleUi")
	end
	return { changed = changed, unchanged = unchanged }
end

function V32.writeActionRequest(action)
	local folder = resolvePath("ReplicatedStorage.CodexActionBridge")
	local requestValue = resolvePath("ReplicatedStorage.CodexActionBridge.LastActionRequest")
	if not folder or not requestValue then
		error("Codex Action Bridge is not installed. Run tools/bridge.cmd ready apply.")
	end
	local encoded = encodeJson(action)
	if not encoded then
		error("Failed to encode action request.")
	end
	requestValue.Value = encoded
	return requestValue
end

function V32.waitForActionResult(actionId, timeoutSeconds)
	local resultValue = resolvePath("ReplicatedStorage.CodexActionBridge.LastActionResult")
	local deadline = os.clock() + (tonumber(timeoutSeconds) or 3)
	while resultValue and os.clock() < deadline do
		local decoded = decodeJson(resultValue.Value)
		if decoded and tostring(decoded.actionId or "") == tostring(actionId) then
			return decoded
		end
		task.wait(0.15)
	end
	return nil
end

function V32.normalizeActionStatus(actionType, status)
	status = tostring(status or "timeout")
	if actionType == "uiClick" and status == "activated" then
		return "clicked"
	end
	if actionType == "uiClick" and (status == "ambiguous" or status == "notFound" or status == "timeout" or status == "unsupported") then
		return "failed"
	end
	return status
end

function V32.tryPhysicalUiClick(action)
	if not action or action.type ~= "uiClick" then return nil end
	local target = action.target or {}
	local center = target.center or V32.centerFromTarget(target)
	if not (center and center.x and center.y) then
		return {
			status = "unavailable",
			reason = "target center coordinates are unavailable",
			target = target,
		}
	end
	local virtualInput, reason = V32.createVirtualInput()
	if not virtualInput then
		return {
			status = "unavailable",
			reason = reason or "UserInputService:CreateVirtualInput unavailable",
			target = target,
			center = { x = center.x, y = center.y },
			method = "UserInputService:CreateVirtualInput",
		}
	end
	local position = Vector2.new(center.x, center.y)
	local ok, err = pcall(function()
		virtualInput:SendMousePosition(position)
		task.wait(0.03)
		virtualInput:SendMouseButton(position, Enum.UserInputType.MouseButton1, true, 1)
		task.wait(0.08)
		virtualInput:SendMouseButton(position, Enum.UserInputType.MouseButton1, false, 1)
	end)
	if not ok then
		return {
			status = "unavailable",
			reason = tostring(err),
			target = target,
			center = { x = center.x, y = center.y },
			method = "VirtualInput:SendMouseButton",
		}
	end
	return {
		actionId = action.id,
		status = "clicked",
		detail = {
			target = target,
			center = { x = center.x, y = center.y },
			method = "VirtualInput:SendMouseButton",
			inputDispatched = true,
			effectObserved = false,
		},
		pluginAt = os.clock(),
	}
end

function V32.applyAction(actionType, payload)
	payload = payload or {}
	local actionId = HttpService:GenerateGUID(false)
	local action = {
		id = actionId,
		type = actionType,
		target = payload.target or { id = payload.id, path = payload.path, text = payload.text, name = payload.name },
		remotePath = payload.remotePath or payload.path,
		payload = payload.remotePayload or payload.payload,
		playerName = payload.playerName,
		createdAt = isoNow(),
		version = VERSION,
	}
	local before = V32.actionSnapshot("before")
	local harnessResult = nil
	if actionType == "uiClick" then
		local physical = V32.tryPhysicalUiClick(action)
		if physical and physical.status == "clicked" then
			harnessResult = physical
		else
			action.physicalInputAttempt = physical
		end
	end
	if not harnessResult then
		V32.writeActionRequest(action)
		harnessResult = V32.waitForActionResult(actionId, payload.waitSeconds or 3)
	end
	if actionType == "uiClick" then
		task.wait(0.25)
	end
	local after = V32.actionSnapshot("after")
	local diff = V32.summarizeDiff(before, after)
	local status = V32.normalizeActionStatus(actionType, harnessResult and harnessResult.status or "timeout")
	if harnessResult then
		harnessResult.normalizedStatus = status
		if harnessResult.detail then
			harnessResult.detail.effectObserved = #diff.changed > 0
		end
	end
	local warnings = {}
	if not harnessResult then
		table.insert(warnings, "No action result was observed before timeout; check Play mode and harness status.")
	elseif status == "manualRequired" then
		table.insert(warnings, "Physical UI click simulation is unavailable through supported Roblox harness APIs; use the suggested manual action and rerun baseline/watch.")
	elseif status == "ambiguous" then
		table.insert(warnings, "Multiple matches exist; rerun with an exact path.")
	end
	local cleanOutcome = status == "clicked"
		or status == "registeredActionExecuted"
		or status == "triggered"
		or status == "fired"
		or status == "invoked"
		or status == "teleported"
		or (actionType == "uiClick" and status == "manualRequired")
	local blockingOutcome = status == "ambiguous" or status == "notFound" or status == "failed" or status == "timeout"
	local result = {
		at = isoNow(),
		version = VERSION,
		action = action,
		clickedTarget = harnessResult and harnessResult.detail and harnessResult.detail.target or nil,
		pass = cleanOutcome,
		status = status,
		harnessResult = harnessResult,
		before = before,
		after = after,
		evidence = {
			target = harnessResult and harnessResult.detail and harnessResult.detail.target or action.target,
			requestedTarget = action.target,
			resultStatus = status,
			inputDispatched = harnessResult and harnessResult.detail and harnessResult.detail.inputDispatched or nil,
			effectObserved = harnessResult and harnessResult.detail and harnessResult.detail.effectObserved or (#diff.changed > 0),
			physicalInputAttempt = action.physicalInputAttempt,
			suggestedManualAction = harnessResult and harnessResult.detail and harnessResult.detail.suggestedManualAction or nil,
			beforeOutput = before.output,
			afterOutput = after.output,
			beforeUi = before.watch and before.watch.current and before.watch.current.ui or nil,
			afterUi = after.watch and after.watch.current and after.watch.current.ui or nil,
			beforeAttributes = before.attributes,
			afterAttributes = after.attributes,
			remoteTrace = after.remotes,
		},
		changed = diff.changed,
		unchanged = diff.unchanged,
		warnings = warnings,
		blockers = blockingOutcome and { "Action did not complete." } or {},
		nextActions = status == "manualRequired"
			and { harnessResult and harnessResult.detail and harnessResult.detail.suggestedManualAction or "Click the reported UI target manually, then rerun tools/bridge.cmd watch now." }
			or (warnings[1] and { "Use exact target path or verify Play mode/harness status." } or { "Review changed evidence and continue QA." }),
	}
	V32.last.actionResult = result
	V32.last.actionBefore = before
	V32.last.action = action
	return result
end

