function V32.getActionFollowupReport(payload)
	payload = payload or {}
	local waitSeconds = math.min(math.max(tonumber(payload.seconds) or 0, 0), 10)
	if waitSeconds > 0 then
		task.wait(waitSeconds)
	end
	local before = V32.last.actionBefore
	local action = V32.last.action
	if not before or not action then
		return {
			at = isoNow(),
			version = VERSION,
			ok = false,
			status = "noPriorAction",
			message = "No prior approved action snapshot is available in this Studio session.",
			nextCommand = "tools/bridge.cmd action ui click --id <target-id>",
		}
	end
	local after = V32.actionSnapshot("manualFollowup")
	local diff = V32.summarizeDiff(before, after)
	local result = {
		at = isoNow(),
		version = VERSION,
		ok = true,
		status = #diff.changed > 0 and "changed" or "unchanged",
		action = action,
		lastResult = V32.last.actionResult,
		before = before,
		after = after,
		changed = diff.changed,
		unchanged = diff.unchanged,
		evidence = {
			target = action.target,
			beforeOutput = before.output,
			afterOutput = after.output,
			beforeUi = before.watch and before.watch.current and before.watch.current.ui or nil,
			afterUi = after.watch and after.watch.current and after.watch.current.ui or nil,
			beforeAttributes = before.attributes,
			afterAttributes = after.attributes,
			remoteTrace = after.remotes,
		},
		nextCommand = "tools/bridge.cmd watch now",
	}
	V32.last.actionFollowup = result
	return result
end

function V32.recipeCatalog()
	local base = V31.recipeCatalog()
	local extra = {
		{ id = "ui-qa", title = "UI QA", goal = "screen inventory, interactions, responsive issues", readOnly = true },
		{ id = "world-layout-qa", title = "World Layout QA", goal = "spawns, landmarks, scale, clutter, interactables", readOnly = true },
		{ id = "monetization-safety-qa", title = "Monetization Safety QA", goal = "purchases/remotes/economy safety warnings", requiresApproval = false },
		{ id = "multiplayer-qa", title = "Multiplayer QA", goal = "players, teams, remotes, replicated state", readOnly = true },
		{ id = "private-server-qa", title = "Private Server QA", goal = "server identity, player flow, reserved/private server assumptions", readOnly = true },
		{ id = "respawn-checkpoint-qa", title = "Respawn / Checkpoint QA", goal = "spawns, checkpoints, deaths, respawn flow", readOnly = true },
		{ id = "combat-qa", title = "Combat QA", goal = "weapons, damage, health, teams, respawn", readOnly = true },
		{ id = "economy-qa", title = "Economy QA", goal = "leaderstats, currency, shops, rewards, save/load evidence", readOnly = true },
		{ id = "tutorial-onboarding-qa", title = "Tutorial / Onboarding QA", goal = "first objective clarity and early guidance", readOnly = true },
	}
	for _, item in ipairs(extra) do
		item.commands = item.commands or { "tools/bridge.cmd baseline mark", "tools/bridge.cmd launch-qa " .. item.id .. " report" }
		table.insert(base, item)
	end
	return base
end

function V32.getLaunchQaRecipeCatalog(payload)
	return {
		at = isoNow(),
		version = VERSION,
		recipes = V32.recipeCatalog(),
		nextCommand = "tools/bridge.cmd launch-qa full-launch report",
	}
end

function V32.findRecipe(recipeId)
	recipeId = tostring(recipeId or "full-launch")
	for _, recipe in ipairs(V32.recipeCatalog()) do
		if recipe.id == recipeId then
			return recipe
		end
	end
	return V32.recipeCatalog()[1]
end

function V32.getLaunchQaRecipePlan(payload)
	payload = payload or {}
	local recipe = V32.findRecipe(payload.recipeId or payload.id)
	return {
		at = isoNow(),
		version = VERSION,
		recipe = recipe,
		mode = "preview",
		mutatesStudio = false,
		requiresApprovalForApply = true,
		steps = recipe.commands or {},
		evidence = { "Output baseline", "UI/world/performance/action reports", "watch/attribute snapshots" },
		nextCommand = "tools/bridge.cmd launch-qa " .. recipe.id .. " report",
	}
end

function V32.getLaunchQaRecipeReport(payload)
	payload = payload or {}
	local recipe = V32.findRecipe(payload.recipeId or payload.id)
	local wants = {}
	for _, commandName in ipairs(recipe.commands or {}) do
		wants[commandName] = true
	end
	if recipe.id == "full-launch" then
		wants.ui = true
		wants.map = true
		wants.performance = true
		wants.attributes = true
		wants.device = true
		wants.screenshot = true
	end
	local checks = {
		control = V31.getStudioControlReport(payload),
		output = V31.getOutputSinceBaseline({ limit = payload.outputLimit or 120 }),
	}
	if wants.ui then
		checks.ui = V31.getUniversalUiQaReport(payload)
	end
	if wants.map or wants.world then
		checks.map = V31.getUniversalMapQualityAudit(payload)
	end
	if wants.performance then
		checks.performance = V31.getUniversalPerformanceAudit(payload)
	end
	if wants.attributes then
		checks.attributes = V31.getLiveAttributeWatchReport(payload)
	end
	if wants.device then
		checks.device = V32.getDeviceViewportStatus(payload)
	end
	if wants.screenshot then
		checks.screenshot = V31.getScreenshotVisionReport(payload)
	end
	if wants.prompts then
		checks.prompts = V32.getPromptActionTargets(payload)
	end
	if wants.remotes then
		checks.remotes = V32.getRemoteTraceReport(payload)
	end
	if wants.watch then
		checks.watch = V28.getWatchNow(payload)
	end
	if wants.actions then
		checks.actionBridge = V32.getActionBridgeStatus(payload)
	end
	local recipeCheck = {
		at = isoNow(),
		version = VERSION,
		recipe = recipe,
		checks = checks,
	}
	local output = checks.output or {}
	local result = {
		at = isoNow(),
		version = VERSION,
		recipe = recipe,
		report = recipeCheck,
		pass = not (output.errorOrWarningCount and output.errorOrWarningCount > 0),
		blockers = {},
		warnings = {},
		evidence = {
			output = output,
			watch = checks.watch,
			ui = checks.ui,
			map = checks.map,
			performance = checks.performance,
			attributes = checks.attributes,
		},
		nextActions = { "Review evidence, then run an exact Full Trust action if needed." },
	}
	if output.errorOrWarningCount and output.errorOrWarningCount > 0 then
		table.insert(result.blockers, "New Output errors/warnings since baseline.")
	end
	return result
end

function V32.applyLaunchQaActionPlan(payload)
	payload = payload or {}
	local recipe = V32.findRecipe(payload.recipeId or payload.id)
	V31.markOutputBaseline({})
	return {
		at = isoNow(),
		version = VERSION,
		recipe = recipe,
		status = "approvedBaselineMarked",
		pass = true,
		message = "Launch QA action plan approval recorded and Output baseline marked. Exact UI/prompt/remote actions remain separate approvals.",
		nextCommand = "tools/bridge.cmd launch-qa " .. recipe.id .. " report",
	}
end

