local function executeCommand(command)
	local payload = command.payload or {}
	local commandType = command.type

	if commandType == "refreshState" then
		sendState(true)
		return { message = "State refreshed." }
	end

	if commandType == "getTree" then
		local root = resolveInstance(payload.path or payload.root or payload.instanceId or payload.targetId or payload.target)
		if not root then
			error("getTree target was not found.")
		end
		local options = makeTraversalOptions(payload)
		local tree = collectTree(root, options)
		return {
			root = {
				id = getInstanceId(root),
				name = root.Name,
				className = root.ClassName,
				path = safeFullName(root),
			},
			depth = options.depth,
			maxNodes = options.maxNodes,
			nodes = tree.nodes,
			scripts = tree.scripts,
			nodeCount = tree.nodeCount,
			scriptCount = tree.scriptCount,
			classCounts = tree.classCounts,
			truncated = tree.truncated,
			freshness = {
				at = isoNow(),
				source = "Studio plugin live tree scan",
				bounded = true,
				maxNodes = options.maxNodes,
				depth = options.depth,
			},
		}
	end

	if commandType == "searchInstances" then
		return searchInstances(payload, false)
	end

	if commandType == "searchScripts" then
		return searchInstances(payload, true)
	end

	if commandType == "searchSource" then
		return searchSource(payload)
	end

	if commandType == "getOutputDiagnostics" then
		return getOutputDiagnostics(payload)
	end

	if commandType == "getOutputFreshnessReport" then
		return V31.getOutputFreshnessReport(payload)
	end

	if commandType == "getToolContractAudit" then
		return V31.getToolContractAudit(payload)
	end

	if commandType == "getBridgeSettings" then
		return getBridgeSettings()
	end

	if commandType == "getBridgeSelfTest" then
		return V21.getBridgeSelfTest(payload)
	end

	if commandType == "getRecoveryStatus" then
		return V21.getRecoveryStatus(payload)
	end

	if commandType == "getCommandAudit" then
		return V21.getCommandAudit(payload)
	end

	if commandType == "getInstallStatus" then
		return V21.getInstallStatus(payload)
	end

	if commandType == "getFastDashboard" then
		return V22.getFastDashboard(payload)
	end

	if commandType == "getBridgePerformanceStatus" then
		return V22.getBridgePerformanceStatus(payload)
	end

	if commandType == "getCommandFlowStatus" then
		return V22.getCommandFlowStatus(payload)
	end

	if commandType == "getReportCacheStatus" then
		return V22.getReportCacheStatus(payload)
	end

	if commandType == "getHandoffPack" then
		return V23.getHandoffPack(payload)
	end

	if commandType == "getCommandPalette" then
		return V23.getCommandPalette(payload)
	end

	if commandType == "getNextBestCommand" then
		return V23.getNextBestCommand(payload)
	end

	if commandType == "getSessionSummary" then
		return V23.getSessionSummary(payload)
	end

	if commandType == "getWorkflowGuide" then
		return V23.getWorkflowGuide(payload)
	end

	if commandType == "getProjectImportScan" then
		return V24.getProjectImportScan(payload)
	end

