	end

	if commandType == "openScript" then
		local instance = resolveInstance(payload.instanceId or payload.targetId or payload.path or payload.target)
		if not instance or not instance:IsA("LuaSourceContainer") then
			error("Target script was not found.")
		end
		local ok, err = pcall(function()
			ScriptEditorService:OpenScriptDocumentAsync(instance)
		end)
		if not ok then
			error("Could not open script: " .. tostring(err))
		end
		return { id = getInstanceId(instance), path = safeFullName(instance) }
	end

	if commandType == "readScriptSource" then
		local instance = resolveInstance(payload.instanceId or payload.targetId or payload.path or payload.target)
		local source = readScriptSource(instance)
		return {
			id = getInstanceId(instance),
			name = instance.Name,
			className = instance.ClassName,
			path = safeFullName(instance),
			source = source,
		}
	end

	if commandType == "updateScriptSource" then
		return withUndo("UpdateScriptSource", function()
			local instance = resolveInstance(payload.instanceId or payload.targetId or payload.path or payload.target)
			if not instance then
				error("Target script was not found.")
			end
			updateScriptSource(instance, payload.source or "")
			stateDirty = true
			return { id = getInstanceId(instance), path = safeFullName(instance), sourceLength = #(payload.source or "") }
		end)
	end

	if commandType == "applyScriptPatch" then
		return withUndo("ApplyScriptPatch", function()
			local instance = resolveInstance(payload.scriptId or payload.instanceId or payload.targetId or payload.path or payload.target)
			if not instance then
				error("Target script was not found.")
			end
			if type(payload.newSource) ~= "string" then
				error("applyScriptPatch requires payload.newSource.")
			end

			local currentSource = readScriptSource(instance)
			local actualHash = sourceHash(currentSource)
			local expectedHash = tostring(payload.expectedSourceHash or "")
			if expectedHash == "" then
				error("applyScriptPatch requires payload.expectedSourceHash.")
			end
			if actualHash:lower() ~= expectedHash:lower() then
				error("Stale patch rejected. Current source hash is " .. actualHash .. ", expected " .. expectedHash .. ".")
			end

			updateScriptSource(instance, payload.newSource)
			stateDirty = true
			return {
				id = getInstanceId(instance),
				path = safeFullName(instance),
				summary = payload.summary or "",
				backupPath = payload.backupPath or "",
				oldSourceHash = actualHash,
				newSourceHash = sourceHash(payload.newSource),
				diff = payload.diff or {
					oldLineCount = countLines(currentSource),
					newLineCount = countLines(payload.newSource),
					changedLineCount = changedLineCount(currentSource, payload.newSource),
				},
			}
		end)
	end

