	if commandType == "createInstance" then
		return withUndo("CreateInstance", function()
			local className = tostring(payload.className or "Part")
			local parent = getParentFromPayload(payload)
			local instance = Instance.new(className)
			if payload.name then
				instance.Name = tostring(payload.name)
			end
			local failures = setProperties(instance, payload.properties or {})
			instance.Parent = parent
			Selection:Set({ instance })
			stateDirty = true
			return {
				id = getInstanceId(instance),
				path = safeFullName(instance),
				className = instance.ClassName,
				propertyFailures = failures,
			}
		end)
	end

	if commandType == "setProperties" then
		return withUndo("SetProperties", function()
			local instances = resolveInstances(payload)
			local failures = {}
			for _, instance in ipairs(instances) do
				local instanceFailures = setProperties(instance, payload.properties or {})
				if #instanceFailures > 0 then
					failures[getInstanceId(instance)] = instanceFailures
				end
			end
			stateDirty = true
			return { changed = #instances, failures = failures }
		end)
	end

	if commandType == "moveInstances" then
		return withUndo("MoveInstances", function()
			local instances = resolveInstances(payload)
			local parent = getParentFromPayload(payload)
			for _, instance in ipairs(instances) do
				instance.Parent = parent
			end
			stateDirty = true
			return { moved = #instances, parent = safeFullName(parent) }
		end)
	end

	if commandType == "deleteInstances" then
		return withUndo("DeleteInstances", function()
			local instances = resolveInstances(payload)
			for _, instance in ipairs(instances) do
				instance:Destroy()
			end
			stateDirty = true
			return { deleted = #instances }
		end)
	end

	if commandType == "duplicateInstances" then
		return withUndo("DuplicateInstances", function()
			local instances = resolveInstances(payload)
			local parent = getParentFromPayload(payload)
			local clones = {}
			for _, instance in ipairs(instances) do
				local clone = instance:Clone()
				clone.Parent = parent
				table.insert(clones, clone)
			end
			Selection:Set(clones)
			stateDirty = true
			local result = {}
			for _, clone in ipairs(clones) do
				table.insert(result, { id = getInstanceId(clone), path = safeFullName(clone), className = clone.ClassName })
			end
			return { duplicated = #clones, clones = result }
		end)
	end

	if commandType == "insertAsset" then
		return withUndo("InsertAsset", function()
			local assetId = tonumber(payload.assetId or payload.id)
			if not assetId then
				error("insertAsset requires numeric assetId.")
			end
			local parent = getParentFromPayload(payload)
			local model = InsertService:LoadAsset(assetId)
			model.Parent = parent
			Selection:Set({ model })
			stateDirty = true
			return { id = getInstanceId(model), path = safeFullName(model), assetId = assetId }
		end)
	end

	if commandType == "runDiagnostic" then
		return runDiagnostic()
	end

	error("Unsupported command type: " .. tostring(commandType))
end

