function V33.normalizeMode(mode)
	mode = tostring(mode or "off")
	if V33.validModes[mode] then
		return mode
	end
	return "off"
end

function V33.getMode()
	local ok, value = pcall(function()
		return plugin:GetSetting(V33.settingKey)
	end)
	if ok then
		local mode = V33.normalizeMode(value)
		if mode == "fullTrust" then
			local okExpiry, expiry = pcall(function()
				return tonumber(plugin:GetSetting(V33.fullTrustExpiryKey))
			end)
			if not okExpiry or not expiry or expiry <= os.time() then
				pcall(function()
					plugin:SetSetting(V33.settingKey, "off")
					plugin:SetSetting(V33.fullTrustExpiryKey, nil)
				end)
				V33.last.mode = "off"
				V33.last.fullTrustExpiredAt = isoNow()
				return "off"
			end
		end
		return mode
	end
	return "off"
end

function V33.setMode(mode)
	mode = V33.normalizeMode(mode)
	pcall(function()
		plugin:SetSetting(V33.settingKey, mode)
		if mode == "fullTrust" then
			plugin:SetSetting(V33.fullTrustExpiryKey, os.time() + V33.fullTrustSeconds)
		else
			plugin:SetSetting(V33.fullTrustExpiryKey, nil)
		end
	end)
	V33.last.mode = mode
	V33.last.modeChangedAt = isoNow()
	V33.last.fullTrustExpiresAt = mode == "fullTrust" and os.date("!%Y-%m-%dT%H:%M:%SZ", os.time() + V33.fullTrustSeconds) or nil
	return mode
end

function V33.nextMode(mode)
	mode = V33.normalizeMode(mode)
	for index, value in ipairs(V33.modeOrder) do
		if value == mode then
			return V33.modeOrder[(index % #V33.modeOrder) + 1]
		end
	end
	return "off"
end

-- V41 Full Trust Autopilot: local no-approval workflow. Command implementations
-- still return manualRequired when Roblox itself requires creator confirmation.
V41.enabledKey = "V41FullTrustEnabled"
V41.emergencyKey = "V41EmergencyStop"
V41.pausedKey = "V41Paused"
V41.blockedTypes = {}

function V41.getBoolSetting(key, defaultValue)
	local ok, value = pcall(function()
		return plugin:GetSetting(key)
	end)
	if not ok or value == nil then
		return defaultValue
	end
	return value == true
end

function V41.setBoolSetting(key, value)
	pcall(function()
		plugin:SetSetting(key, value == true)
	end)
end

function V41.isEnabled()
	return V41.getBoolSetting(V41.enabledKey, true) and not V41.getBoolSetting(V41.emergencyKey, false) and not V41.getBoolSetting(V41.pausedKey, false)
end

function V41.setMode(mode)
	mode = tostring(mode or "on")
	if mode == "off" then
		V41.setBoolSetting(V41.enabledKey, false)
		V41.setBoolSetting(V41.pausedKey, false)
		V41.setBoolSetting(V41.emergencyKey, false)
	elseif mode == "pause" or mode == "paused" then
		V41.setBoolSetting(V41.enabledKey, true)
		V41.setBoolSetting(V41.pausedKey, true)
		V41.setBoolSetting(V41.emergencyKey, false)
	elseif mode == "emergency-stop" or mode == "emergency" then
		V41.setBoolSetting(V41.enabledKey, true)
		V41.setBoolSetting(V41.pausedKey, true)
		V41.setBoolSetting(V41.emergencyKey, true)
	else
		V41.setBoolSetting(V41.enabledKey, true)
		V41.setBoolSetting(V41.pausedKey, false)
		V41.setBoolSetting(V41.emergencyKey, false)
	end
	V41.last.modeChangedAt = isoNow()
	V41.last.mode = V41.mode()
	return V41.last.mode
end

function V41.mode()
	if V41.getBoolSetting(V41.emergencyKey, false) then
		return "emergencyStop"
	end
	if not V41.getBoolSetting(V41.enabledKey, true) then
		return "off"
	end
	if V41.getBoolSetting(V41.pausedKey, false) then
		return "paused"
	end
	return "fullTrustAutopilot"
end

function V41.deletePayloadIsCodexOwned(command)
	local payload = command and command.payload or {}
	local values = {}
	local function collect(value)
		if type(value) == "string" then
			table.insert(values, value)
		elseif type(value) == "table" then
			for _, child in pairs(value) do
				collect(child)
			end
		end
	end
	collect(payload.paths)
	collect(payload.path)
	collect(payload.targetPath)
	if #values == 0 then
		return false, "delete command has no explicit paths"
	end
	for _, value in ipairs(values) do
		if V33.isGamePath(value) and not V33.isCodexOwnedPath(value) then
			return false, "delete path is not Codex-owned: " .. tostring(value)
		end
	end
	return true, "delete paths are Codex-owned"
end

function V41.externalRisk(command)
	if not command then
		return nil
	end
	-- Full Trust means the bridge does not block local Studio actions merely
	-- because payload text contains words like DataStoreService, publish, or
	-- monetization. Those words often appear in source code being edited.
	-- Actual external/account flows are handled by their command implementations
	-- and should report manualRequired when Roblox/creator confirmation is needed.
	return nil
end

function V41.shouldRunImmediately(command)
	if not commandRequiresApproval or not commandRequiresApproval(command) then
		return { allowed = false, mode = V41.mode(), rule = "readOnly", reason = "Command does not require autopilot." }
	end
	local mode = V41.mode()
	if mode ~= "fullTrustAutopilot" then
		return { allowed = false, mode = mode, rule = "notEnabled", reason = "Full Trust Autopilot is not active." }
	end
	local risk = V41.externalRisk(command)
	if risk then
		return { allowed = false, blocked = true, mode = mode, rule = "blockedExternalRisk", reason = risk }
	end
	return { allowed = true, mode = mode, rule = "fullTrustAutopilot", reason = "Full Trust Autopilot runs local StudioBridge mutations immediately." }
end

function V41.addAuditRecord(command, status, decision)
	local record = {
		at = isoNow(),
		id = command and command.id or nil,
		type = command and command.type or nil,
		status = status,
		mode = decision and decision.mode or V41.mode(),
		rule = decision and decision.rule or nil,
		reason = decision and decision.reason or nil,
		payloadSummary = command and V21.payloadSummary and V21.payloadSummary(command.payload or {}) or nil,
	}
	table.insert(V41.audit, 1, record)
	while #V41.audit > 200 do
		table.remove(V41.audit)
	end
	V41.last.lastAudit = record
	if status == "autoRunQueued" or status == "autoRunExecuted" then
		V41.last.lastAutoRun = record
	elseif status == "blockedExternalRisk" then
		V41.last.lastBlocked = record
	end
	return record
end

function V41.getStatus(payload)
	payload = payload or {}
	return {
		at = isoNow(),
		version = VERSION,
		mode = V41.mode(),
		enabled = V41.isEnabled(),
		defaultEnabled = true,
		emergencyStop = V41.getBoolSetting(V41.emergencyKey, false),
		paused = V41.getBoolSetting(V41.pausedKey, false),
		pendingCount = #commandOrder,
		lastAutoRun = V41.last.lastAutoRun,
		lastBlocked = V41.last.lastBlocked,
		blockedTerms = {},
		message = V41.isEnabled() and "Full Trust Autopilot is ON. Local StudioBridge mutations run without Approve/Reject or payload word blocks." or "Full Trust Autopilot is paused/off; old approval fallback may appear.",
		externalAccountNote = "Publishing/uploading and other Roblox account prompts are handled by their command implementations and may return manualRequired instead of being blocked by Full Trust policy.",
		nextCommand = V41.isEnabled() and "tools\\bridge.cmd start" or "tools\\bridge.cmd trust on",
	}
end

function V41.getAudit(payload)
	payload = payload or {}
	local limit = math.max(1, math.min(tonumber(payload.limit or 50) or 50, 200))
	local records = {}
	for index = 1, math.min(limit, #V41.audit) do
		table.insert(records, V41.audit[index])
	end
	return {
		at = isoNow(),
		version = VERSION,
		mode = V41.mode(),
		count = #V41.audit,
		records = records,
		lastAutoRun = V41.last.lastAutoRun,
		lastBlocked = V41.last.lastBlocked,
	}
end

function V41.setAutopilot(payload)
	payload = payload or {}
	local mode = V41.setMode(payload.mode or payload.state or "on")
	addOutput("Full Trust Autopilot set to " .. tostring(mode) .. ".", mode == "emergencyStop" and "Warning" or "Info", "CodexStudioBridge")
	return V41.getStatus(payload)
end

function V33.payloadText(command)
	local ok, text = pcall(function()
		return HttpService:JSONEncode(command and command.payload or {})
	end)
	if ok then
		return tostring(command and command.type or "") .. " " .. text
	end
	return tostring(command and command.type or "")
end

function V33.hasHardBlockedTerm(command)
	local text = string.lower(V33.payloadText(command))
	for _, term in ipairs(V33.hardBlockedTerms) do
		if string.find(text, term, 1, true) then
			return term
		end
	end
	return nil
end

function V33.isGamePath(value)
	if type(value) ~= "string" then
		return false
	end
	local root = string.match(value, "^([^%.]+)")
	return root ~= nil and V33.serviceRoots[root] == true
end

function V33.isCodexOwnedPath(value)
	if type(value) ~= "string" then
		return false
	end
	for _, prefix in ipairs(V33.codexOwnedPrefixes) do
		if string.sub(value, 1, #prefix) == prefix then
			return true
		end
	end
	return false
end

function V33.collectPathValues(value, output, depth)
	if type(value) ~= "table" or depth > 8 then
		return
	end
	for key, child in pairs(value) do
		local keyText = string.lower(tostring(key))
		if type(child) == "string" then
			if keyText == "path"
				or keyText == "parentpath"
				or keyText == "targetpath"
				or keyText == "newparentpath"
				or keyText == "scriptpath"
				or keyText == "rootpath"
				or keyText == "remotepath"
				or string.sub(keyText, -4) == "path" then
				table.insert(output, child)
			end
		elseif type(child) == "table" then
			V33.collectPathValues(child, output, depth + 1)
		end
	end
end

function V33.codexOwnedPayloadCheck(command)
	local paths = {}
	V33.collectPathValues(command.payload or {}, paths, 0)
	local gamePathCount = 0
	for _, path in ipairs(paths) do
		if V33.isGamePath(path) then
			gamePathCount += 1
			if not V33.isCodexOwnedPath(path) then
				return false, "nonCodexPath", path
			end
		end
	end
	if gamePathCount == 0 then
		return false, "noCodexOwnedPath", nil
	end
	return true, "codexOwnedPath", tostring(gamePathCount)
end

function V33.patchListFromPayload(command)
	local payload = command and command.payload or {}
	if command and command.type == "applyScriptPatch" then
		return { payload }
	end
	if type(payload.patches) == "table" then
		return payload.patches
	end
	if type(payload.patchSet) == "table" and type(payload.patchSet.patches) == "table" then
		return payload.patchSet.patches
	end
	return {}
end

function V33.patchPayloadHasSafety(command)
	local patches = V33.patchListFromPayload(command)
	if #patches == 0 then
		return false, "noPatches", nil
	end
	for index, patch in ipairs(patches) do
		if type(patch) ~= "table" then
			return false, "invalidPatch", tostring(index)
		end
		if not patch.expectedSourceHash or tostring(patch.expectedSourceHash) == "" then
			return false, "missingExpectedSourceHash", tostring(index)
		end
		if not patch.backupPath or tostring(patch.backupPath) == "" then
			return false, "missingBackupPath", tostring(index)
		end
		if type(patch.diff) ~= "table" then
			return false, "missingDiff", tostring(index)
		end
	end
	return true, "hashBackupDiff", tostring(#patches)
end

function V33.patchPayloadCodexOwned(command)
	local patches = V33.patchListFromPayload(command)
	if #patches == 0 then
		return false, "noPatches", nil
	end
	for index, patch in ipairs(patches) do
		local path = tostring(patch.path or patch.scriptPath or "")
		if path == "" or not V33.isCodexOwnedPath(path) then
			return false, "nonCodexPatchPath", path ~= "" and path or tostring(index)
		end
	end
	return true, "codexOwnedPatchPath", tostring(#patches)
end

function V33.addAuditRecord(command, status, decision)
	local dedupeKey = tostring(command and command.id or "") .. "|" .. tostring(command and command.type or "")
		.. "|" .. tostring(status or "") .. "|" .. tostring(decision and decision.rule or "")
	if V33.last.auditDedupeKey == dedupeKey and V33.audit[1] then
		local record = V33.audit[1]
		record.lastAt = isoNow()
		record.repeatCount = (tonumber(record.repeatCount) or 1) + 1
		if status == "autoApproved" then
			V33.last.lastAutoApproved = record
		elseif status == "blocked" then
			V33.last.lastBlocked = record
		end
		return record
	end
	local record = {
		at = isoNow(),
		id = command and command.id or nil,
		type = command and command.type or nil,
		status = status,
		mode = decision and decision.mode or V33.getMode(),
		rule = decision and decision.rule or nil,
		reason = decision and decision.reason or nil,
		detail = decision and decision.detail or nil,
		repeatCount = 1,
	}
	table.insert(V33.audit, 1, record)
	while #V33.audit > 100 do
		table.remove(V33.audit)
	end
	V33.last.auditRecord = record
	if status == "autoApproved" then
		V33.last.lastAutoApproved = record
	elseif status == "blocked" then
		V33.last.lastBlocked = record
	end
	V33.last.auditDedupeKey = dedupeKey
	return record
end

function V33.shouldAutoApprove(command)
	local mode = V33.getMode()
	if mode == "off" then
		return { allowed = false, mode = mode, rule = "off", reason = "Auto Approve is off." }
	end
	if not commandRequiresApproval or not commandRequiresApproval(command) then
		return { allowed = false, mode = mode, rule = "readOnly", reason = "Command is read-only and does not need Full Trust mutation handling." }
	end
	if V33.hardBlockedTypes[command.type] then
		return { allowed = false, blocked = true, mode = mode, rule = "hardBlockedType", reason = "This command type always requires manual review.", detail = command.type }
	end
	local blockedTerm = V33.hasHardBlockedTerm(command)
	if blockedTerm then
		return { allowed = false, blocked = true, mode = mode, rule = "legacyHardBlockedPayload", reason = "Legacy Auto Approve payload word rule matched. Full Trust Autopilot does not use this payload word blocker.", detail = blockedTerm }
	end
	if command.type == "applyScriptPatch" or command.type == "applyCodePatchSet" then
		local safe, safeRule, safeDetail = V33.patchPayloadHasSafety(command)
		if not safe then
			return { allowed = false, blocked = true, mode = mode, rule = safeRule, reason = "Script patch auto-approval requires backup path, expected source hash, and diff metadata.", detail = safeDetail }
		end
		local owned, ownedRule, ownedDetail = V33.patchPayloadCodexOwned(command)
		if mode == "codexOwnedBuild" and owned then
			return { allowed = true, mode = mode, rule = ownedRule, reason = "Hash-backed script patch targets only Codex-owned paths.", detail = ownedDetail }
		end
		if mode == "codexOwnedBuild" then
			return { allowed = false, mode = mode, rule = ownedRule, reason = "Codex-Owned Build only auto-approves script patches under Codex-owned paths.", detail = ownedDetail }
		end
		if mode == "fullTrust" then
			return { allowed = true, mode = mode, rule = safeRule, reason = "Full Trust Session allows hash-backed script patches with backup and diff metadata.", detail = safeDetail }
		end
		return { allowed = false, mode = mode, rule = "scriptPatchManual", reason = "Script patches need Codex-Owned Build or Full Trust auto-approval." }
	end
	if V33.testAutomationTypes[command.type] then
		return { allowed = true, mode = mode, rule = "testAutomation", reason = "Trusted test automation command." }
	end
	if mode == "testAutomation" then
		return { allowed = false, mode = mode, rule = "outsideTestAutomation", reason = "Command is outside Test Automation scope." }
	end
	if V33.codexOwnedBuildTypes[command.type] then
		local ok, rule, detail = V33.codexOwnedPayloadCheck(command)
		if ok then
			return { allowed = true, mode = mode, rule = rule, reason = "All game paths are Codex-owned draft/setup paths.", detail = detail }
		end
		if mode == "codexOwnedBuild" then
			return { allowed = false, mode = mode, rule = rule, reason = "Codex-Owned Build requires all game paths to be Codex-owned.", detail = detail }
		end
	end
	if mode == "fullTrust" then
		return { allowed = true, mode = mode, rule = "fullTrust", reason = "Full Trust Session is enabled and no hard blocker matched." }
	end
	return { allowed = false, mode = mode, rule = "manualRequired", reason = "Command does not match an auto-approve allow rule." }
end

function V33.getAutoApprovePolicy(payload)
	payload = payload or {}
	return {
		at = isoNow(),
		version = VERSION,
		defaultMode = "fullTrustAutopilot",
		mode = V33.getMode(),
		fullTrustAutopilot = V41.getStatus(payload),
		fullTrustExpiresAt = V33.last.fullTrustExpiresAt,
		fullTrustSeconds = V33.fullTrustSeconds,
		modes = {
			{ id = "fullTrustAutopilot", label = "Full Trust Autopilot", description = "Default local workflow: StudioBridge mutations run immediately with audit logging and no payload word blockers." },
			{ id = "paused", label = "Pause Autopilot", description = "Pauses Full Trust and falls back to the old approval queue." },
			{ id = "emergencyStop", label = "Emergency Stop", description = "Stops new autopilot mutations until trust is turned on again." },
			{ id = "legacyAutoApprove", label = "Legacy Auto Approve", description = "Old V33 scoped modes remain available as fallback policy controls." },
		},
		codexOwnedPrefixes = V33.codexOwnedPrefixes,
		hardBlockedTerms = {},
		legacyHardBlockedTerms = V33.hardBlockedTerms,
		patchSafety = "Full Trust runs local patch/refactor/build/test commands immediately and audits them. Payload text such as DataStoreService no longer blocks local Studio edits.",
	}
end

function V33.getAutoApproveAudit(payload)
	payload = payload or {}
	local limit = math.max(1, math.min(tonumber(payload.limit or 50) or 50, 100))
	local records = {}
	for index = 1, math.min(limit, #V33.audit) do
		table.insert(records, V33.audit[index])
	end
	return {
		at = isoNow(),
		version = VERSION,
		mode = V33.getMode(),
		count = #V33.audit,
		records = records,
		lastAutoApproved = V33.last.lastAutoApproved,
		lastBlocked = V33.last.lastBlocked,
	}
end

function V33.detectStudioPlayMethods()
	local okService, studioService = pcall(function()
		return game:GetService("StudioService")
	end)
	local startCandidates = {}
	local stopCandidates = {}
	local function addCandidate(targetName, target, methodName, output)
		if not target then
			return
		end
		local ok, method = pcall(function()
			return target[methodName]
		end)
		if ok and type(method) == "function" then
			table.insert(output, { targetName = targetName, methodName = methodName })
		end
	end
	if okService and studioService then
		for _, methodName in ipairs({ "StartPlaySolo", "StartPlay", "PlaySolo" }) do
			addCandidate("StudioService", studioService, methodName, startCandidates)
		end
		for _, methodName in ipairs({ "StopPlaySolo", "StopPlay", "EndPlay" }) do
			addCandidate("StudioService", studioService, methodName, stopCandidates)
		end
	end
	for _, methodName in ipairs({ "StartPlaySolo", "StartPlay", "PlaySolo" }) do
		addCandidate("Plugin", plugin, methodName, startCandidates)
	end
	for _, methodName in ipairs({ "StopPlaySolo", "StopPlay", "EndPlay" }) do
		addCandidate("Plugin", plugin, methodName, stopCandidates)
	end
	return startCandidates, stopCandidates
end

function V33.getStudioPlayControlStatus(payload)
	payload = payload or {}
	local flags = V6.getRunServiceSnapshot()
	local startCandidates, stopCandidates = V33.detectStudioPlayMethods()
	local result = {
		at = isoNow(),
		version = VERSION,
		contextType = V6.detectLocalContextType(flags),
		runService = flags,
		mode = flags.isRunning and "play" or "edit",
		isRunning = flags.isRunning == true,
		canStartPlay = #startCandidates > 0,
		canStopPlay = #stopCandidates > 0,
		startMethods = startCandidates,
		stopMethods = stopCandidates,
		status = (#startCandidates > 0 or #stopCandidates > 0) and "featureDetected" or "manualRequired",
		manualStart = "Press Play in Roblox Studio, then run tools\\bridge.cmd play status.",
		manualStop = "Press Stop in Roblox Studio, then run tools\\bridge.cmd play status.",
		autoApproveMode = V33.getMode(),
	}
	V33.last.playControlStatus = result
	return result
end

function V33.invokeStudioPlayMethod(kind)
	local okService, studioService = pcall(function()
		return game:GetService("StudioService")
	end)
	local specs = {}
	local names = kind == "start" and { "StartPlaySolo", "StartPlay", "PlaySolo" } or { "StopPlaySolo", "StopPlay", "EndPlay" }
	if okService and studioService then
		for _, name in ipairs(names) do
			table.insert(specs, { targetName = "StudioService", target = studioService, methodName = name })
		end
	end
	for _, name in ipairs(names) do
		table.insert(specs, { targetName = "Plugin", target = plugin, methodName = name })
	end
	local attempts = {}
	for _, spec in ipairs(specs) do
		local okMethod, method = pcall(function()
			return spec.target[spec.methodName]
		end)
		if okMethod and type(method) == "function" then
			local okCall, result = pcall(function()
				return method(spec.target)
			end)
			table.insert(attempts, {
				targetName = spec.targetName,
				methodName = spec.methodName,
				ok = okCall,
				error = okCall and nil or tostring(result),
			})
			if okCall then
				return true, attempts, spec
			end
		end
	end
	return false, attempts, nil
end

function V33.requestPlayControl(kind, payload)
	payload = payload or {}
	local before = V33.getStudioPlayControlStatus(payload)
	if kind == "start" and before.isRunning then
		return { at = isoNow(), version = VERSION, action = kind, status = "alreadyRunning", before = before, after = before, message = "Studio is already in Play/Test mode." }
	end
	if kind == "stop" and not before.isRunning then
		return { at = isoNow(), version = VERSION, action = kind, status = "alreadyStopped", before = before, after = before, message = "Studio is already in Edit mode." }
	end
	if not V34.allowProgrammaticPlayControl(payload) then
		return V34.manualWatchPlayResult(kind, before, payload)
	end
	local ok, attempts, spec = V33.invokeStudioPlayMethod(kind)
	task.wait(0.9)
	local after = V33.getStudioPlayControlStatus(payload)
	local expected = kind == "start" and after.isRunning or not after.isRunning
	local status = "manualRequired"
	local message = kind == "start" and before.manualStart or before.manualStop
	if ok and expected then
		status = kind == "start" and "started" or "stopped"
		message = "Studio Play state changed through a feature-detected Studio/plugin API."
	elseif ok then
		status = "requested"
		message = "A feature-detected API accepted the request, but the Play state has not changed yet. Recheck play status."
	elseif #attempts > 0 then
		status = "failed"
		message = "Feature-detected Play API calls failed; use the manual Studio Play/Stop button."
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		action = kind,
		status = status,
		method = spec and { targetName = spec.targetName, methodName = spec.methodName } or nil,
		attempts = attempts,
		before = before,
		after = after,
		message = message,
		manualRequired = status == "manualRequired" or status == "failed",
		nextCommand = "tools\\bridge.cmd play status",
	}
	V33.last.playControlResult = result
	return result
end

function V33.requestStartPlay(payload)
	return V33.requestPlayControl("start", payload)
end

function V33.requestStopPlay(payload)
	return V33.requestPlayControl("stop", payload)
end

function V33.requestRestartPlay(payload)
	local stopResult = nil
	if RunService:IsRunning() then
		stopResult = V33.requestStopPlay(payload)
		if stopResult.manualRequired then
			return { at = isoNow(), version = VERSION, action = "restart", status = "manualRequired", stop = stopResult, message = "Stop Play manually, then run tools\\bridge.cmd play start." }
		end
		task.wait(0.75)
	end
	local startResult = V33.requestStartPlay(payload)
	local status = startResult.status == "started" and "restarted" or startResult.status
	local result = {
		at = isoNow(),
		version = VERSION,
		action = "restart",
		status = status,
		stop = stopResult,
		start = startResult,
		message = status == "restarted" and "Studio Play restarted." or startResult.message,
		nextCommand = "tools\\bridge.cmd play status",
	}
	V33.last.playControlResult = result
	return result
end

