		lastPlayControlResult = V33.last.playControlResult,
		nextCommand = RunService:IsRunning() and "tools\\bridge.cmd play stop" or "tools\\bridge.cmd play start",
	}
end

function V33.getAutonomyStatus(payload)
	payload = payload or {}
	local mode = V33.getMode()
	local pending = {}
	for _, commandId in ipairs(commandOrder) do
		local command = pendingCommands[commandId]
		if command then
			table.insert(pending, { id = command.id, type = command.type })
		end
	end
	return {
		at = isoNow(),
		version = VERSION,
		mode = mode,
		label = V33.modeLabels[mode] or mode,
		enabled = V41.isEnabled() or mode ~= "off",
		fullTrust = V41.getStatus(payload),
		pendingCount = #commandOrder,
		pending = pending,
		lastAutoApproved = V33.last.lastAutoApproved,
		lastAutoRun = V41.last.lastAutoRun,
		lastBlocked = V33.last.lastBlocked,
		lastExternalRiskBlock = V41.last.lastBlocked,
		lastPlayControlResult = V33.last.playControlResult,
		policy = V33.getAutoApprovePolicy(payload),
		nextCommand = V41.isEnabled() and "tools\\bridge.cmd start" or "tools\\bridge.cmd trust on",
	}
end

function V33.getPowerModeStatus(payload)
	return V33.getAutonomyStatus(payload)
end

-- V34 Capability Brain + Real Test Runner + Autonomy Polish
function V34.safeCall(label, callback)
	local ok, result = pcall(callback)
	if ok then
		return true, result
	end
	return false, tostring(result or label)
end

function V34.getStudioTestService()
	local ok, service = pcall(function()
		return game:GetService("StudioTestService")
	end)
	if ok then
		return service
	end
	return nil
end

function V34.methodAvailable(target, methodName)
	if not target then
		return false
	end
	local ok, value = pcall(function()
		return target[methodName]
	end)
	return ok and type(value) == "function"
end

function V34.methodList(target, names)
	local output = {}
	for _, name in ipairs(names) do
		table.insert(output, { methodName = name, available = V34.methodAvailable(target, name) })
	end
	return output
end

function V34.availableMethodNames(target, names)
	local output = {}
	for _, name in ipairs(names) do
		if V34.methodAvailable(target, name) then
			table.insert(output, name)
		end
	end
	return output
end

function V34.getStudioTestServiceStatus(payload)
	payload = payload or {}
	local service = V34.getStudioTestService()
	local flags = V6.getRunServiceSnapshot()
	local startNames = { "ExecutePlayModeAsync", "ExecuteRunModeAsync", "ExecuteMultiplayerTestAsync" }
	local stopNames = { "EndTest", "LeaveTest" }
	local legacyStart, legacyStop = V33.detectStudioPlayMethods()
	local result = {
		at = isoNow(),
		version = VERSION,
		serviceAvailable = service ~= nil,
		contextType = V6.detectLocalContextType(flags),
		runService = flags,
		mode = flags.isRunning and "play" or "edit",
		isRunning = flags.isRunning == true,
		studioTestService = service and {
			startMethods = V34.methodList(service, startNames),
			stopMethods = V34.methodList(service, stopNames),
			canPlay = V34.methodAvailable(service, "ExecutePlayModeAsync"),
			canRun = V34.methodAvailable(service, "ExecuteRunModeAsync"),
			canMultiplayer = V34.methodAvailable(service, "ExecuteMultiplayerTestAsync"),
			canEndTest = V34.methodAvailable(service, "EndTest"),
			canLeaveTest = V34.methodAvailable(service, "LeaveTest"),
		} or nil,
		legacy = {
			startMethods = legacyStart,
			stopMethods = legacyStop,
		},
		activeTestSession = V34.activeTestSession,
		status = service and "studioTestServiceDetected" or ((#legacyStart > 0 or #legacyStop > 0) and "legacyDetected" or "manualRequired"),
		manualStart = "Press Play in Roblox Studio, then run tools\\bridge.cmd play status.",
		manualStop = "Press Stop in Roblox Studio, then run tools\\bridge.cmd play status.",
		nextCommand = flags.isRunning and "tools\\bridge.cmd play stop" or "tools\\bridge.cmd play start",
		programmaticControlDefault = "manualWatch",
		apiControlAvailableButDisabledByDefault = true,
		apiOverrideCommand = flags.isRunning and "tools\\bridge.cmd play stop-api" or "tools\\bridge.cmd play start-api",
		apiOverridePayload = { allowStudioTestServiceApi = true },
		apiSafetyReason = "This Studio session has shown plugin heartbeat loss after programmatic Play/Stop transitions. Manual-watch mode keeps StudioBridge connected while Codex observes Play state.",
	}
	V34.last.studioTestServiceStatus = result
	return result
end

function V34.allowProgrammaticPlayControl(payload)
	payload = payload or {}
	return payload.allowStudioTestServiceApi == true
		or payload.allowProgrammaticPlay == true
		or payload.forceApi == true
		or payload.unsafeApi == true
end

function V34.manualWatchPlayResult(action, before, payload)
	payload = payload or {}
	local runningNow = before and before.isRunning == true
	local instruction = action == "stop" and "Press Stop in Roblox Studio, then run tools\\bridge.cmd play status or tools\\bridge.cmd watch now."
		or action == "restart" and "Press Stop, then Play in Roblox Studio. StudioBridge will keep watching; run tools\\bridge.cmd play status after each transition."
		or "Press Play in Roblox Studio, then run tools\\bridge.cmd play status or tools\\bridge.cmd watch now."
	local result = {
		at = isoNow(),
		version = VERSION,
		action = action,
		status = "manualRequired",
		manualRequired = true,
		controlMode = "manualWatch",
		before = before,
		after = before,
		runtimeAlreadyMatches = (action == "start" and runningNow) or (action == "stop" and not runningNow) or false,
		reason = "Programmatic Studio Play/Stop APIs are disabled by default because they can suspend the plugin heartbeat in this Studio session.",
		message = instruction,
		apiOverride = {
			available = true,
			command = action == "stop" and "tools\\bridge.cmd play stop-api" or action == "restart" and "tools\\bridge.cmd play restart-api" or "tools\\bridge.cmd play start-api",
			payload = { allowStudioTestServiceApi = true },
			warning = "Use only for debugging; if the plugin disconnects, use manual-watch mode.",
		},
		nextCommand = "tools\\bridge.cmd play status",
	}
	V33.last.playControlResult = result
	V34.last.playControlResult = result
	return result
end

function V34.launchStudioTest(mode, payload)
	payload = payload or {}
	mode = tostring(mode or payload.mode or "play")
	local service = V34.getStudioTestService()
	local methodName = mode == "run" and "ExecuteRunModeAsync"
		or (mode == "multiplayer" and "ExecuteMultiplayerTestAsync" or "ExecutePlayModeAsync")
	if not service or not V34.methodAvailable(service, methodName) then
		return nil, "manualRequired", "StudioTestService " .. methodName .. " is unavailable in this Studio session."
	end
	local sessionId = HttpService:GenerateGUID(false)
	local args = {
		source = "CodexStudioBridge",
		version = VERSION,
		mode = mode,
		sessionId = sessionId,
		createdAt = isoNow(),
		label = payload.label or payload.testName or "Codex StudioBridge test",
	}
	V34.activeTestSession = {
		id = sessionId,
		mode = mode,
		methodName = methodName,
		startedAt = isoNow(),
		status = "starting",
		players = tonumber(payload.players or payload.playerCount or 1) or 1,
	}
	task.spawn(function()
		local ok, result = pcall(function()
			if methodName == "ExecuteMultiplayerTestAsync" then
				return service:ExecuteMultiplayerTestAsync(math.max(1, math.min(tonumber(payload.players or payload.playerCount or 2) or 2, 8)), args)
			end
			return service[methodName](service, args)
		end)
		if V34.activeTestSession and V34.activeTestSession.id == sessionId then
			V34.activeTestSession.finishedAt = isoNow()
			V34.activeTestSession.status = ok and "completed" or "failed"
			V34.activeTestSession.result = ok and result or nil
			V34.activeTestSession.error = ok and nil or tostring(result)
		end
	end)
	return V34.activeTestSession, "requested", "StudioTestService launch was requested through " .. methodName .. "."
end

function V34.stopStudioTest(payload)
	payload = payload or {}
	local service = V34.getStudioTestService()
	if not service then
		return false, "manualRequired", "StudioTestService is unavailable in this Studio session.", {}
	end
	local attempts = {}
	for _, methodName in ipairs({ "EndTest", "LeaveTest" }) do
		if V34.methodAvailable(service, methodName) then
			local ok, result = pcall(function()
				if methodName == "EndTest" then
					return service:EndTest({
						source = "CodexStudioBridge",
						version = VERSION,
						reason = payload.reason or "Codex requested stop",
						at = isoNow(),
					})
				end
				return service:LeaveTest()
			end)
			table.insert(attempts, { methodName = methodName, ok = ok, error = ok and nil or tostring(result) })
			if ok then
				if V34.activeTestSession then
					V34.activeTestSession.stopRequestedAt = isoNow()
					V34.activeTestSession.stopMethod = methodName
				end
				return true, "requested", "StudioTestService stop was requested through " .. methodName .. ".", attempts
			end
		end
	end
	return false, #attempts > 0 and "failed" or "manualRequired", "No supported StudioTestService stop method succeeded; use Studio Stop manually.", attempts
end

function V34.requestStartPlay(payload)
	payload = payload or {}
	local mode = tostring(payload.mode or "play")
	local before = V34.getStudioTestServiceStatus(payload)
	if before.isRunning then
		return { at = isoNow(), version = VERSION, action = "start", requestedMode = mode, status = "alreadyRunning", before = before, after = before, message = "Studio is already in Play/Test mode." }
	end
	if not V34.allowProgrammaticPlayControl(payload) then
		return V34.manualWatchPlayResult("start", before, payload)
	end
	local session, status, message = V34.launchStudioTest(mode, payload)
	task.wait(0.35)
	local after = V34.getStudioTestServiceStatus(payload)
	if session and session.status == "failed" then
		status = "failed"
		message = tostring(session.error or message)
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		action = "start",
		requestedMode = mode,
		status = after.isRunning and "started" or status,
		session = session,
		before = before,
		after = after,
		message = after.isRunning and "Studio entered Play/Test mode through StudioTestService." or message,
		manualRequired = status == "manualRequired" or status == "failed",
		nextCommand = "tools\\bridge.cmd play status",
	}
	V33.last.playControlResult = result
	V34.last.playControlResult = result
	return result
end

function V34.requestStopPlay(payload)
	payload = payload or {}
	local before = V34.getStudioTestServiceStatus(payload)
	if not before.isRunning then
		return { at = isoNow(), version = VERSION, action = "stop", status = "alreadyStopped", before = before, after = before, message = "Studio is already in Edit mode." }
	end
	if not V34.allowProgrammaticPlayControl(payload) then
		return V34.manualWatchPlayResult("stop", before, payload)
	end
	local ok, status, message, attempts = V34.stopStudioTest(payload)
	task.wait(0.35)
	local after = V34.getStudioTestServiceStatus(payload)
	local result = {
		at = isoNow(),
		version = VERSION,
		action = "stop",
		status = not after.isRunning and "stopped" or status,
		attempts = attempts,
		before = before,
		after = after,
		message = not after.isRunning and "Studio left Play/Test mode." or message,
		manualRequired = status == "manualRequired" or status == "failed",
		nextCommand = "tools\\bridge.cmd play status",
	}
	V33.last.playControlResult = result
	V34.last.playControlResult = result
	return result
end

function V34.requestRestartPlay(payload)
	payload = payload or {}
	local before = V34.getStudioTestServiceStatus(payload)
	if not V34.allowProgrammaticPlayControl(payload) then
		return V34.manualWatchPlayResult("restart", before, payload)
	end
	local stopResult = nil
	if RunService:IsRunning() then
		stopResult = V34.requestStopPlay(payload)
		if stopResult.manualRequired then
			return { at = isoNow(), version = VERSION, action = "restart", status = "manualRequired", stop = stopResult, message = "Stop Play manually, then run tools\\bridge.cmd play start." }
		end
		task.wait(0.75)
	end
	local startResult = V34.requestStartPlay(payload)
	local status = startResult.status == "started" and "restarted" or startResult.status
	local result = {
		at = isoNow(),
		version = VERSION,
		action = "restart",
		status = status,
		stop = stopResult,
		start = startResult,
		message = status == "restarted" and "Studio Play restarted." or startResult.message,
		nextCommand = "tools\\bridge.cmd play status",
	}
	V33.last.playControlResult = result
	V34.last.playControlResult = result
	return result
end

