function V34.getPluginCodeHealthReport(payload)
	payload = payload or {}
	local timing = V22.timingSummary and V22.timingSummary(20) or {}
	local pending = {}
	for _, commandId in ipairs(commandOrder) do
		local command = pendingCommands[commandId]
		if command then
			table.insert(pending, { id = command.id, type = command.type })
		end
	end
	local warnings = {}
	if #pending > 10 then
		table.insert(warnings, "Large pending command queue.")
	end
	if V33.last.lastBlocked and (tonumber(V33.last.lastBlocked.repeatCount) or 0) > 3 then
		table.insert(warnings, "Repeated auto-approve block collapsed in audit.")
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		status = #warnings == 0 and "healthy" or "watch",
		checks = {
			{ id = "version", status = "pass", detail = "Plugin running " .. VERSION },
			{ id = "pendingQueue", status = #pending <= 10 and "pass" or "warn", detail = tostring(#pending) .. " pending commands." },
			{ id = "outputBuffer", status = #outputBuffer <= OUTPUT_LIMIT and "pass" or "warn", detail = tostring(#outputBuffer) .. " output messages buffered." },
			{ id = "snapshot", status = State.snapshotStats and "pass" or "warn", detail = State.snapshotStats and (tostring(State.snapshotStats.nodeCount) .. " nodes indexed.") or "No snapshot stats yet." },
			{ id = "panel", status = "pass", detail = "Panel uses compact status labels and does not run full Explorer snapshots every pulse." },
		},
		pending = pending,
		slowCommands = timing.slowCommands or {},
		audit = {
			count = #V33.audit,
			lastAutoApproved = V33.last.lastAutoApproved,
			lastBlocked = V33.last.lastBlocked,
		},
		warnings = warnings,
		localFileMetrics = "Run tools\\bridge.cmd plugin-health for local file size, BOM, and node syntax checks.",
		nextCommand = "tools\\bridge.cmd doctor",
	}
	V34.last.pluginHealth = result
	return result
end

function V34.getAutoApproveDryRun(payload)
	payload = payload or {}
	local command = payload.command or payload
	if not command.type then
		return {
			at = isoNow(),
			version = VERSION,
			ok = false,
			error = "Provide a command object with type and optional payload.",
			example = { type = "applyCodexReadySetup", payload = {}, requiresApproval = true },
		}
	end
	command.payload = command.payload or {}
	if command.requiresApproval == nil then
		command.requiresApproval = mutatingTypes and mutatingTypes[command.type] == true or true
	end
	local trustDecision = V41.shouldRunImmediately(command)
	local legacyDecision = V33.shouldAutoApprove(command)
	return {
		at = isoNow(),
		version = VERSION,
		command = {
			id = command.id,
			type = command.type,
			requiresApproval = command.requiresApproval,
		},
		mode = V41.mode(),
		decision = (trustDecision.allowed or trustDecision.blocked) and trustDecision or legacyDecision,
		fullTrustDecision = trustDecision,
		legacyAutoApproveDecision = legacyDecision,
		wouldAutoApprove = trustDecision.allowed == true or legacyDecision.allowed == true,
		wouldBlock = trustDecision.blocked == true or legacyDecision.blocked == true,
		policy = V33.getAutoApprovePolicy(payload),
	}
end

