function V35.shortState(payload)
	payload = payload or {}
	local play = V34.getStudioTestServiceStatus(payload)
	local autonomy = V33.getAutonomyStatus(payload)
	local ready = V26.last.status
	local watch = V28.last.status
	return {
		at = isoNow(),
		version = VERSION,
		place = {
			placeId = game.PlaceId,
			gameId = game.GameId,
			name = game.Name,
		},
		profile = State.projectProfile and {
			id = State.projectProfile.id,
			name = State.projectProfile.name,
			genre = State.projectProfile.genre,
		} or nil,
		runtime = {
			mode = play.mode,
			contextType = play.contextType,
			isRunning = play.isRunning,
			playStatus = play.status,
			canPlay = play.studioTestService and play.studioTestService.canPlay or false,
			canRun = play.studioTestService and play.studioTestService.canRun or false,
			canMultiplayer = play.studioTestService and play.studioTestService.canMultiplayer or false,
		},
		autonomy = {
			mode = autonomy.mode,
			label = autonomy.label,
			pendingCount = autonomy.pendingCount,
			lastAutoApproved = autonomy.lastAutoApproved and autonomy.lastAutoApproved.type or nil,
			lastBlocked = autonomy.lastBlocked and autonomy.lastBlocked.type or nil,
		},
		readiness = {
			status = ready and ready.status or "unknown",
			score = ready and ready.score or nil,
			httpStatus = ready and ready.summary and ready.summary.httpStatus or nil,
			watch = watch and (watch.fresh and "fresh" or "stale") or "unknown",
		},
		output = {
			buffered = #outputBuffer,
			latest = outputBuffer[#outputBuffer] and {
				type = outputBuffer[#outputBuffer].type,
				message = V9.trimText(tostring(outputBuffer[#outputBuffer].message or ""), 180),
				at = outputBuffer[#outputBuffer].at,
			} or nil,
		},
		pendingCommands = #commandOrder,
	}
end

