function V35.getCodexChatBootstrap(payload)
	payload = payload or {}
	local context = V35.getCodexAutoloadContext(payload)
	local state = context.state
	local nextCommand = "tools\\bridge.cmd start"
	if state.runtime.isRunning then
		nextCommand = "tools\\bridge.cmd codex-context"
	elseif state.readiness.status == "needsHttpVerification" then
		nextCommand = "tools\\bridge.cmd watch now"
	elseif state.autonomy.pendingCount and state.autonomy.pendingCount > 0 then
		nextCommand = "tools\\bridge.cmd commands"
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		title = "Codex StudioBridge New Chat Bootstrap",
		summary = "StudioBridge is a universal Roblox Studio bridge. Use this bootstrap before deciding what to inspect/build/test.",
		state = state,
		requiredFirstMoves = {
			"Read this bootstrap.",
			"Run tools\\bridge.cmd start for current project readiness.",
			"Run tools\\bridge.cmd tools or tools\\bridge.cmd codex-context when unsure what the bridge can do next.",
			"Use tools\\bridge.cmd manual or capabilities when uncertain.",
		},
		bestNextCommand = nextCommand,
		commandGroups = V35.commandGroups(),
		safety = context.usageHints.safety,
	}
	V35.last.bootstrap = result
	return result
end

function V35.getNewChatHandoff(payload)
	payload = payload or {}
	local bootstrap = V35.getCodexChatBootstrap(payload)
	local lines = {
		"# Codex StudioBridge New Chat Handoff",
		"",
		"- Version: " .. VERSION,
		"- Place: " .. tostring(bootstrap.state.place.name or "unknown") .. " (" .. tostring(bootstrap.state.place.placeId or "?") .. ")",
		"- Runtime: " .. tostring(bootstrap.state.runtime.mode or "?") .. " / " .. tostring(bootstrap.state.runtime.contextType or "?"),
		"- Full Trust: " .. tostring((bootstrap.state.autonomy.fullTrust and bootstrap.state.autonomy.fullTrust.mode) or bootstrap.state.autonomy.mode or "unknown"),
		"- Readiness: " .. tostring(bootstrap.state.readiness.status or "unknown") .. " score " .. tostring(bootstrap.state.readiness.score or "?"),
		"- Best next command: `" .. tostring(bootstrap.bestNextCommand) .. "`",
		"",
		"Start commands:",
		"- `tools\\bridge.cmd bootstrap`",
		"- `tools\\bridge.cmd start`",
		"- `tools\\bridge.cmd capabilities`",
		"- `tools\\bridge.cmd manual`",
		"- `tools\\bridge.cmd tools`",
		"- `tools\\bridge.cmd codex-context`",
		"- `tools\\bridge.cmd trust status`",
		"",
		"Safety: reads run automatically; Full Trust Autopilot runs local Studio mutations directly and audits them; never silently publish, change monetization, mutate saves/economy, or broad-delete production work.",
	}
	return {
		at = isoNow(),
		version = VERSION,
		bootstrap = bootstrap,
		markdown = table.concat(lines, "\n"),
	}
end

