function V46.flattenTools(categories)
	local entries = {}
	for _, category in ipairs(categories or V46.toolCategories()) do
		for _, command in ipairs(category.commands or {}) do
			table.insert(entries, {
				categoryId = category.id,
				categoryTitle = category.title,
				command = command.command,
				example = command.example,
				bestFor = command.bestFor,
				safety = category.safety,
			})
		end
	end
	return entries
end

function V46.getCodexToolManifest(payload)
	payload = payload or {}
	local categoryId = payload.category or payload.categoryId
	local categories = {}
	for _, category in ipairs(V46.toolCategories()) do
		if not categoryId or category.id == categoryId then
			table.insert(categories, category)
		end
	end
	local allCategories = V46.toolCategories()
	local flattened = V46.flattenTools(allCategories)
	local aliases = {}
	for _, alias in ipairs(V46.directAliases()) do
		table.insert(aliases, {
			command = "tools\\bridge.cmd " .. alias,
			studioCommand = alias,
			safetyLevel = mutatingTypes and mutatingTypes[alias] and "fullTrustAuditedMutation" or "readOnly",
		})
	end
	local result = {
		ok = true,
		at = isoNow(),
		version = VERSION,
		mode = "toolExposure",
		categoryCount = #allCategories,
		helperCommandCount = #flattened,
		directAliases = aliases,
		categories = categories,
		quickStart = {
			"tools\\bridge.cmd bootstrap",
			"tools\\bridge.cmd tools",
			"tools\\bridge.cmd codex-context",
			"tools\\bridge.cmd start",
			"tools\\bridge.cmd trust status",
		},
		bestNextCommand = "tools\\bridge.cmd codex-context",
		safety = {
			fullTrustName = "fullTrustAutopilot",
			default = "Local StudioBridge mutations run directly and are audited.",
			hardBlockers = { "Emergency Stop pauses new mutations", "Roblox/account confirmation can still return manualRequired where APIs require creator action" },
		},
		note = "Bridge endpoint /codex/tools?full=1 exposes the exhaustive server-side command catalog.",
	}
	V46.last.manifest = result
	return result
end

function V46.getCodexToolSearchIndex(payload)
	payload = payload or {}
	local query = string.lower(tostring(payload.query or payload.q or ""))
	local results = {}
	for _, entry in ipairs(V46.flattenTools(V46.toolCategories())) do
		local haystack = string.lower(table.concat({
			tostring(entry.categoryId or ""),
			tostring(entry.categoryTitle or ""),
			tostring(entry.command or ""),
			tostring(entry.example or ""),
			tostring(entry.bestFor or ""),
			tostring(entry.safety or ""),
		}, " "))
		if query == "" or string.find(haystack, query, 1, true) then
			table.insert(results, entry)
		end
	end
	for _, alias in ipairs(V46.directAliases()) do
		local command = "tools\\bridge.cmd " .. alias
		if query == "" or string.find(string.lower(command), query, 1, true) then
			table.insert(results, {
				categoryId = "directAlias",
				categoryTitle = "Direct Tool Alias",
				command = command,
				example = command,
				bestFor = "Direct StudioBridge tool-style alias.",
				safety = mutatingTypes and mutatingTypes[alias] and "fullTrustAuditedMutation" or "readOnly",
			})
		end
	end
	return {
		ok = true,
		at = isoNow(),
		version = VERSION,
		query = payload.query or payload.q or "",
		count = #results,
		results = results,
		nextCommand = results[1] and results[1].example or "tools\\bridge.cmd tools",
	}
end

function V46.getCodexToolReadinessMatrix(payload)
	payload = payload or {}
	local ready = V26.getCodexReadyStatus(payload)
	local watch = V28.getSmartWatchStatus(payload)
	local play = V34.getStudioTestServiceStatus(payload)
	local toolkitInstalled = ready and ready.summary and tonumber(ready.summary.missingSetupCount or 0) == 0
	local httpCaptureVerified = ready and ready.summary and ready.summary.httpStatus == "ready"
	return {
		ok = true,
		at = isoNow(),
		version = VERSION,
		toolkitInstalled = toolkitInstalled == true,
		httpCaptureVerified = httpCaptureVerified == true,
		captureVerificationRequiredForScreenshotsOnly = true,
		readyStatus = ready and ready.status or "unknown",
		categories = {
			codexReadySetup = { ok = toolkitInstalled == true, detail = ready and ready.summary or nil },
			httpCapture = { ok = httpCaptureVerified == true, detail = ready and ready.summary and ready.summary.httpStatus or "unknown" },
			realtimeWatch = { ok = watch and watch.fresh == true, detail = watch and watch.summary or "No watch status." },
			playControl = { ok = play and play.status ~= "unavailable", detail = play and play.mode or "unknown" },
			fullTrust = { ok = V41.mode() == "fullTrustAutopilot", detail = V41.mode() },
		},
		wording = "Toolkit installed means Codex-owned harness/setup roots are present. HTTP capture verified only affects screenshot/capture relay confidence.",
		nextCommand = toolkitInstalled and "tools\\bridge.cmd codex-context" or "tools\\bridge.cmd ready bootstrap",
	}
end

function V46.getCodexLiveContext(payload)
	payload = payload or {}
	local state = V35.shortState(payload)
	local watch = V28.getWatchNow(payload)
	local readiness = V46.getCodexToolReadinessMatrix(payload)
	local flow = V22.getCommandFlowStatus(payload)
	local issue = watch and watch.latestOutputIssue or state.output.latest
	local nextCommand = "tools\\bridge.cmd start"
	local reason = "Use zero-friction project start routing."
	if not readiness.toolkitInstalled then
		nextCommand = "tools\\bridge.cmd ready bootstrap"
		reason = "Codex Ready toolkit is not fully installed."
	elseif issue then
		nextCommand = "tools\\bridge.cmd watch errors"
		reason = "There is a current actionable Output issue."
	elseif state.runtime and state.runtime.isRunning then
		nextCommand = "tools\\bridge.cmd test snapshot"
		reason = "Play/Test context is active; capture a structured test snapshot."
	elseif state.readiness and state.readiness.watch == "fresh" then
		nextCommand = "tools\\bridge.cmd watch now"
		reason = "Realtime watch is fresh."
	end
	local result = {
		ok = true,
		at = isoNow(),
		version = VERSION,
		mode = "fastLiveContext",
		connection = {
			paired = true,
			studioConnected = true,
			pluginVersion = VERSION,
			place = state.place,
		},
		fullTrustAutopilot = {
			enabled = V41.mode() == "fullTrustAutopilot",
			command = "tools\\bridge.cmd trust status",
			externalRisksBlocked = true,
		},
		state = state,
		watch = watch,
		readiness = {
			toolkitInstalled = readiness.toolkitInstalled,
			httpCaptureVerified = readiness.httpCaptureVerified,
			readyStatus = readiness.readyStatus,
		},
		commandFlow = flow,
		freshness = {
			source = state.runtime and state.runtime.contextType or "plugin",
			fresh = state.readiness and state.readiness.watch == "fresh",
			staleReason = state.readiness and state.readiness.watch == "fresh" and nil or "No fresh preferred realtime pulse in plugin memory.",
			preferred = "testClient awareness for Play, edit pulse for selection/output/command state",
		},
		summary = watch and watch.summary or "No live watch summary yet.",
		nextAction = {
			command = nextCommand,
			reason = reason,
		},
	}
	V46.last.context = result
	return result
end

