-- V36 Camera Navigator + Map Scout
function V36.vectorFromPayload(value, fallback)
	if type(value) == "table" then
		local x = tonumber(value.x or value.X or value[1])
		local y = tonumber(value.y or value.Y or value[2])
		local z = tonumber(value.z or value.Z or value[3])
		if x and y and z then
			return Vector3.new(x, y, z)
		end
	end
	return fallback
end

function V36.currentCameraSummary()
	local camera = workspace.CurrentCamera
	local summary = V9.cameraSummary()
	if not camera or not summary then
		return summary
	end
	summary.focus = serializeValue(camera.Focus)
	summary.viewportSize = V25.readGuiMetric(camera, "ViewportSize")
	return summary
end

function V36.getCameraNavigatorStatus(payload)
	payload = payload or {}
	local camera = workspace.CurrentCamera
	local live = V25.getCameraViewReport(payload)
	local awareness = V27 and V27.bridgeGet and V27.bridgeGet("/codex/awareness") or nil
	local pulse = awareness and (awareness.latest or awareness.latestAny) or nil
	local harness = {
		remote = resolvePath("ReplicatedStorage.CodexCameraNavigator.CameraCommand") ~= nil,
		client = resolvePath("StarterPlayer.StarterPlayerScripts.CodexCameraNavigatorClient") ~= nil,
		manifest = resolvePath("ReplicatedStorage.CodexCameraNavigator.Manifest") ~= nil,
	}
	local installed = harness.remote and harness.client and harness.manifest
	local versionCurrent = false
	local manifest = resolvePath("ReplicatedStorage.CodexCameraNavigator.Manifest")
	if manifest and manifest:IsA("LuaSourceContainer") then
		local ok, source = pcall(function()
			return readScriptSource(manifest)
		end)
		versionCurrent = ok and string.find(source, "version = \"" .. VERSION .. "\"", 1, true) ~= nil
	end
	return {
		at = isoNow(),
		version = VERSION,
		contextType = V6.detectLocalContextType(),
		cameraAvailable = camera ~= nil,
		currentCamera = V36.currentCameraSummary(),
		liveClientCamera = pulse and pulse.camera or nil,
		playMode = RunService:IsRunning(),
		harness = harness,
		installed = installed,
		versionCurrent = versionCurrent,
		status = installed and (versionCurrent and "installed" or "outdated") or "missing",
		editViewportControl = camera ~= nil,
		clientCameraControl = installed,
		message = installed and "Camera navigator harness is installed; Play-mode camera moves can be requested with approval." or "Camera scouting works read-only now; install the Codex-owned camera harness for Play-mode camera moves.",
		nextCommand = installed and "tools\\bridge.cmd camera scout" or "tools\\bridge.cmd camera harness install",
		liveView = live,
	}
end

function V36.getCameraScoutReport(payload)
	payload = payload or {}
	local camera = V25.getCameraViewReport(payload)
	local screen = V25.getScreenCompositionReport(payload)
	local scene = V9.getSceneMap({
		maxNodes = tonumber(payload.maxNodes) or 3000,
		profile = payload.profile,
		activeProfile = payload.activeProfile,
		profiles = payload.profiles,
	})
	local route = V36.getMapScoutRoute(payload)
	local blockers = {}
	if not camera.camera then
		table.insert(blockers, "No camera is available in this context.")
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		status = #blockers == 0 and "ready" or "limited",
		camera = camera.camera,
		nearbyWorld = camera.nearbyWorld,
		screen = {
			contextType = screen.contextType,
			summary = screen.summary,
			visibleUi = screen.visibleUi,
			warnings = screen.warnings,
		},
		scene = {
			stats = scene.stats,
			bounds = scene.bounds,
			landmarks = scene.landmarks,
			major = scene.major,
		},
		route = route,
		blockers = blockers,
		nextCommand = "tools\\bridge.cmd camera path",
	}
	V36.last.scout = result
	return result
end

function V36.routePoint(id, title, position, lookAt, reason)
	return {
		id = id,
		title = title,
		position = serializeValue(position),
		lookAt = serializeValue(lookAt),
		reason = reason,
		command = "tools\\bridge.cmd camera move --x " .. tostring(math.floor(position.X + 0.5))
			.. " --y " .. tostring(math.floor(position.Y + 0.5))
			.. " --z " .. tostring(math.floor(position.Z + 0.5))
			.. " --look-x " .. tostring(math.floor(lookAt.X + 0.5))
			.. " --look-y " .. tostring(math.floor(lookAt.Y + 0.5))
			.. " --look-z " .. tostring(math.floor(lookAt.Z + 0.5)),
	}
end

function V36.getMapScoutRoute(payload)
	payload = payload or {}
	local scene = V9.getSceneMap({ maxNodes = tonumber(payload.maxNodes) or 2500, profile = payload.profile, activeProfile = payload.activeProfile, profiles = payload.profiles })
	local bounds = scene.bounds or {}
	local center = V36.vectorFromPayload(bounds.center, Vector3.new(0, 0, 0))
	local size = V36.vectorFromPayload(bounds.size, Vector3.new(120, 60, 120))
	local radius = math.max(size.X, size.Z, 80)
	local height = math.max(size.Y + 40, 80)
	local points = {
		V36.routePoint("overview", "High Overview", center + Vector3.new(0, height, radius), center, "See the whole map layout and major landmarks."),
		V36.routePoint("north", "North Angle", center + Vector3.new(0, height * 0.55, radius), center, "Check front/back depth and labels from one side."),
		V36.routePoint("east", "East Angle", center + Vector3.new(radius, height * 0.55, 0), center, "Check side readability, paths, and object density."),
		V36.routePoint("spawn", "Spawn / Start", center + Vector3.new(-radius * 0.45, height * 0.35, -radius * 0.45), center, "Inspect likely first-player-view area."),
	}
	return {
		at = isoNow(),
		version = VERSION,
		center = serializeValue(center),
		size = serializeValue(size),
		points = points,
		count = #points,
		nextCommand = points[1].command,
	}
end

function V36.getCameraMovePlan(payload)
	payload = payload or {}
	local target = V36.vectorFromPayload(payload.position or payload.cameraPosition, nil)
	local lookAt = V36.vectorFromPayload(payload.lookAt or payload.focus or payload.targetPosition, Vector3.new(0, 0, 0))
	if not target then
		local route = V36.getMapScoutRoute(payload)
		local first = route.points and route.points[1]
		return {
			at = isoNow(),
			version = VERSION,
			status = "needsTarget",
			message = "No camera position was supplied; use a route point or provide x/y/z.",
			route = route,
			recommended = first,
		}
	end
	return {
		at = isoNow(),
		version = VERSION,
		status = "ready",
		position = serializeValue(target),
		lookAt = serializeValue(lookAt),
		cframe = serializeValue(CFrame.lookAt(target, lookAt)),
		requiresApproval = true,
		nextCommand = "tools\\bridge.cmd camera move --x <x> --y <y> --z <z> --look-x <x> --look-y <y> --look-z <z>",
	}
end

function V36.getCameraBookmarkReport(payload)
	payload = payload or {}
	return {
		at = isoNow(),
		version = VERSION,
		currentCamera = V36.currentCameraSummary(),
		bookmarks = V10.getCameraBookmarks(payload),
		route = V36.getMapScoutRoute(payload),
		nextCommand = "tools\\bridge.cmd camera remember <name>",
	}
end

function V36.applyCameraBookmark(payload)
	payload = payload or {}
	local name = tostring(payload.name or "CodexCameraBookmark")
	local camera = workspace.CurrentCamera
	if not camera then
		return { at = isoNow(), version = VERSION, status = "failed", error = "No CurrentCamera is available." }
	end
	local folder = resolvePath("Workspace.CodexCameraBookmarks")
	if not folder then
		folder = Instance.new("Folder")
		folder.Name = "CodexCameraBookmarks"
		folder.Parent = workspace
	end
	local marker = folder:FindFirstChild(name)
	if not marker then
		marker = Instance.new("Part")
		marker.Name = name
		marker.Anchored = true
		marker.CanCollide = false
		marker.Transparency = 0.65
		marker.Size = Vector3.new(2, 2, 2)
		marker.Parent = folder
	end
	marker.CFrame = camera.CFrame
	marker:SetAttribute("CodexCameraBookmark", true)
	marker:SetAttribute("LookVector", tostring(camera.CFrame.LookVector))
	stateDirty = true
	return {
		at = isoNow(),
		version = VERSION,
		status = "bookmarked",
		path = safeFullName(marker),
		name = name,
		camera = V36.currentCameraSummary(),
	}
end

function V36.cameraHarnessPaths()
	return {
		"ReplicatedStorage.CodexCameraNavigator",
		"ReplicatedStorage.CodexCameraNavigator.CameraCommand",
		"ReplicatedStorage.CodexCameraNavigator.Manifest",
		"StarterPlayer.StarterPlayerScripts.CodexCameraNavigatorClient",
	}
end

function V36.cameraNavigatorClientSource()
	return [=[
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local TweenService = game:GetService("TweenService")
local Workspace = game:GetService("Workspace")

local player = Players.LocalPlayer
local folder = ReplicatedStorage:WaitForChild("CodexCameraNavigator", 10)
local remote = folder and folder:FindFirstChild("CameraCommand")
local activeTween = nil

local function vec(t)
	if type(t) == "table" then
		return Vector3.new(tonumber(t.x or 0), tonumber(t.y or 0), tonumber(t.z or 0))
	end
	return nil
end

local function report(status, message)
	print("[CodexCameraNavigator]", tostring(status), tostring(message or ""))
end

local function camera()
	return Workspace.CurrentCamera
end

local function releaseCamera(label)
	local cam = camera()
	if activeTween then
		pcall(function()
			activeTween:Cancel()
		end)
		activeTween = nil
	end
	if not cam then
		report("failed", "no CurrentCamera")
		return false
	end
	local humanoid = player.Character and player.Character:FindFirstChildOfClass("Humanoid")
	pcall(function()
		if humanoid then
			cam.CameraSubject = humanoid
		end
	end)
	pcall(function()
		cam.CameraType = Enum.CameraType.Custom
	end)
	report("released", tostring(label or "camera returned to player control"))
	return true
end

local function setView(position, lookAt, duration, label)
	local cam = camera()
	if not cam then
		report("failed", "no CurrentCamera")
		return false
	end
	if not position or not lookAt then
		report("manualRequired", "position/lookAt missing")
		return false
	end
	cam.CameraType = Enum.CameraType.Scriptable
	local target = CFrame.lookAt(position, lookAt)
	local seconds = math.clamp(tonumber(duration or 0) or 0, 0, 12)
	if activeTween then
		pcall(function()
			activeTween:Cancel()
		end)
		activeTween = nil
	end
	if seconds > 0.03 then
		local tween = TweenService:Create(cam, TweenInfo.new(seconds, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), { CFrame = target })
		activeTween = tween
		tween:Play()
		local ok = pcall(function()
			tween.Completed:Wait()
		end)
		if activeTween == tween then
			activeTween = nil
		end
		report(ok and "movedSmooth" or "movedSmoothInterrupted", tostring(label or "") .. " " .. tostring(position) .. " -> " .. tostring(lookAt))
	else
		cam.CFrame = target
		report("moved", tostring(label or "") .. " " .. tostring(position) .. " -> " .. tostring(lookAt))
	end
	return true
end

if not remote then
	report("missing", "CameraCommand remote missing")
	return
end

report("ready", "client camera navigator ready")
remote.OnClientEvent:Connect(function(command)
	if type(command) ~= "table" then return end
	local kind = tostring(command.kind or "move")
	if kind == "release" or kind == "free" or kind == "followPlayer" then
		releaseCamera(kind)
		return
	end
	local lookAt = vec(command.lookAt)
	local position = vec(command.position)
	if kind == "orbit" and lookAt then
		local radius = tonumber(command.radius or 80)
		local height = tonumber(command.height or 45)
		local angle = math.rad(tonumber(command.angleDegrees or 45))
		position = lookAt + Vector3.new(math.cos(angle) * radius, height, math.sin(angle) * radius)
	end
	if kind == "path" then
		local waypoints = type(command.waypoints) == "table" and command.waypoints or {}
		report("pathStart", tostring(#waypoints) .. " waypoint(s)")
		for index, waypoint in ipairs(waypoints) do
			local wpPosition = vec(waypoint.position)
			local wpLookAt = vec(waypoint.lookAt)
			local duration = tonumber(waypoint.duration or command.duration or 1.1) or 1.1
			if not setView(wpPosition, wpLookAt, duration, waypoint.id or index) then
				report("pathStopped", "failed at waypoint " .. tostring(index))
				return
			end
			task.wait(math.clamp(tonumber(command.pause or 0.15) or 0.15, 0, 3))
		end
		report("pathComplete", tostring(#waypoints) .. " waypoint(s)")
		return
	end
	local duration = tonumber(command.duration or 0) or 0
	if kind == "smoothMove" and duration <= 0 then
		duration = 1.1
	end
	setView(position, lookAt, duration, kind)
end)
]=]
end

function V36.cameraHarnessBlueprint(payload)
	return {
		name = "Codex Camera Navigator Harness",
		mode = "supervised",
		source = "installCameraNavigatorHarness",
		steps = {
			{ type = "ensureFolder", path = "ReplicatedStorage.CodexCameraNavigator" },
			{ type = "ensureRemoteEvent", path = "ReplicatedStorage.CodexCameraNavigator.CameraCommand" },
			{
				type = "writeScript",
				path = "ReplicatedStorage.CodexCameraNavigator.Manifest",
				className = "ModuleScript",
				source = "return { name = \"CodexCameraNavigator\", version = \"" .. VERSION .. "\", purpose = \"approved camera scouting/navigation\" }\n",
			},
			{
				type = "writeScript",
				path = "StarterPlayer.StarterPlayerScripts.CodexCameraNavigatorClient",
				className = "LocalScript",
				source = V36.cameraNavigatorClientSource(),
			},
		},
	}
end

function V36.installCameraNavigatorHarness(payload)
	local blueprint = normalizeBlueprint(payload or {}) or V36.cameraHarnessBlueprint(payload or {})
	local result = applyBuildPlan({ blueprint = blueprint })
	result.kind = "cameraNavigatorInstall"
	result.status = V36.getCameraNavigatorStatus(payload)
	return result
end

function V36.removeCameraNavigatorHarness(payload)
	return withUndo("RemoveCameraNavigatorHarness", function()
		local result = { appliedAt = isoNow(), removed = {}, missing = {}, failed = {} }
		for _, path in ipairs(V36.cameraHarnessPaths()) do
			local instance = resolvePath(path)
			if instance then
				local ok, err = pcall(function()
					instance:Destroy()
				end)
				if ok then
					table.insert(result.removed, { path = path })
				else
					table.insert(result.failed, { path = path, message = tostring(err) })
				end
			else
				table.insert(result.missing, { path = path })
			end
		end
		stateDirty = true
		result.summary = { removed = #result.removed, missing = #result.missing, failed = #result.failed }
		return result
	end)
end

function V36.fireCameraCommand(command)
	local remote = resolvePath("ReplicatedStorage.CodexCameraNavigator.CameraCommand")
	if not remote or not remote:IsA("RemoteEvent") then
		return false, "CodexCameraNavigator CameraCommand remote is missing. Install the camera harness first."
	end
	local players = Players:GetPlayers()
	if #players == 0 then
		return false, "No Play-mode players are available for client camera control."
	end
	for _, player in ipairs(players) do
		remote:FireClient(player, command)
	end
	return true, "Sent camera command to " .. tostring(#players) .. " client(s)."
end

function V36.requestCameraMove(payload)
	payload = payload or {}
	local plan = V36.getCameraMovePlan(payload)
	if plan.status ~= "ready" then
		return plan
	end
	local ok, message = V36.fireCameraCommand({
		kind = "move",
		position = plan.position,
		lookAt = plan.lookAt,
		source = "CodexStudioBridge",
		version = VERSION,
	})
	return {
		at = isoNow(),
		version = VERSION,
		status = ok and "requested" or "manualRequired",
		message = message,
		plan = plan,
		after = V25.getCameraViewReport(payload),
		nextCommand = "tools\\bridge.cmd camera release",
	}
end

function V36.requestCameraOrbit(payload)
	payload = payload or {}
	local lookAt = V36.vectorFromPayload(payload.lookAt or payload.focus or payload.targetPosition, Vector3.new(0, 0, 0))
	local command = {
		kind = "orbit",
		lookAt = serializeValue(lookAt),
		radius = tonumber(payload.radius or 80) or 80,
		height = tonumber(payload.height or 45) or 45,
		angleDegrees = tonumber(payload.angleDegrees or payload.angle or 45) or 45,
		source = "CodexStudioBridge",
		version = VERSION,
	}
	local ok, message = V36.fireCameraCommand(command)
	return {
		at = isoNow(),
		version = VERSION,
		status = ok and "requested" or "manualRequired",
		message = message,
		command = command,
		after = V25.getCameraViewReport(payload),
		nextCommand = "tools\\bridge.cmd camera release",
	}
end

function V36.requestCameraRelease(payload)
	payload = payload or {}
	local editReleased = false
	local editError = nil
	local camera = workspace.CurrentCamera
	if camera and payload.edit ~= false then
		local ok, err = pcall(function()
			camera.CameraType = Enum.CameraType.Custom
		end)
		editReleased = ok
		editError = ok and nil or tostring(err)
	end
	local ok, message = V36.fireCameraCommand({
		kind = "release",
		source = "CodexStudioBridge",
		version = VERSION,
	})
	local status = ok and "requested" or (editReleased and "releasedEditCamera" or "manualRequired")
	return {
		at = isoNow(),
		version = VERSION,
		status = status,
		message = ok and message or (editReleased and "Released the Studio/edit camera locally; no Play-mode client was available." or message),
		editReleased = editReleased,
		editError = editError,
		nextCommand = "tools\\bridge.cmd camera status",
		note = "This returns the client camera from Scriptable mode back to normal player/creator control.",
	}
end

-- V37 Smooth Camera Director + View-Guided Builder
function V37.numberOr(value, fallback)
	local number = tonumber(value)
	if number == nil then
		return fallback
	end
	return number
end

function V37.pathWaypoints(payload)
	payload = payload or {}
	local duration = math.clamp(V37.numberOr(payload.duration, 1.15), 0, 12)
	local route = V36.getMapScoutRoute(payload)
	local waypoints = {}
	for _, point in ipairs(route.points or {}) do
		table.insert(waypoints, {
			id = point.id,
			title = point.title,
			reason = point.reason,
			position = point.position,
			lookAt = point.lookAt,
			duration = duration,
		})
	end
	return waypoints, route
end

function V37.getCameraPathPlan(payload)
	payload = payload or {}
	local waypoints, route = V37.pathWaypoints(payload)
	local totalDuration = 0
	for _, waypoint in ipairs(waypoints) do
		totalDuration += V37.numberOr(waypoint.duration, 1.15) + V37.numberOr(payload.pause, 0.15)
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		status = #waypoints > 0 and "ready" or "limited",
		style = tostring(payload.style or "smoothMapScout"),
		requiresApproval = true,
		waypoints = waypoints,
		route = route,
		estimatedSeconds = math.floor(totalDuration * 10 + 0.5) / 10,
		nextCommand = "tools\\bridge.cmd camera path-run",
		message = "Smooth camera path for scouting the map from multiple useful creator angles.",
	}
	V37.last.pathPlan = result
	return result
end

function V37.getCameraCoverageReport(payload)
	payload = payload or {}
	local scout = V36.getCameraScoutReport(payload)
	local route = V36.getMapScoutRoute(payload)
	local coverage = {}
	for _, point in ipairs(route.points or {}) do
		table.insert(coverage, {
			id = point.id,
			title = point.title,
			status = "planned",
			reason = point.reason,
			command = point.command,
		})
	end
	local stats = scout.scene and scout.scene.stats or {}
	local result = {
		at = isoNow(),
		version = VERSION,
		status = scout.status,
		cameraAvailable = scout.camera ~= nil,
		mapStats = stats,
		coverage = coverage,
		coverageCount = #coverage,
		warnings = scout.blockers,
		nextCommand = "tools\\bridge.cmd camera path-run",
		message = "Coverage is based on structured scene bounds and route points; run path-run in Play mode for an actual smooth scout pass.",
	}
	V37.last.coverage = result
	return result
end

function V37.getCameraViewBuildContext(payload)
	payload = payload or {}
	local scout = V36.getCameraScoutReport(payload)
	local okWorld, worldAudit = pcall(function()
		return V14.getWorldDesignAudit(payload)
	end)
	local suggestions = {}
	local screenSummary = scout.screen and scout.screen.summary or {}
	local visibleUi = scout.screen and scout.screen.visibleUi or {}
	if tonumber(screenSummary.visibleObjects or 0) > 80 then
		table.insert(suggestions, { type = "ui", priority = "medium", title = "Check UI readability from this view", command = "tools\\bridge.cmd ui responsive" })
	end
	if scout.scene and scout.scene.stats and tonumber(scout.scene.stats.partCount or 0) == 0 then
		table.insert(suggestions, { type = "world", priority = "high", title = "Create a first blockout", command = "tools\\bridge.cmd template recommend" })
	end
	table.insert(suggestions, { type = "camera", priority = "normal", title = "Scout the map with a smooth path", command = "tools\\bridge.cmd camera path-run" })
	table.insert(suggestions, { type = "build", priority = "normal", title = "Use this view to choose the next build action", command = "tools\\bridge.cmd director plan" })
	local result = {
		at = isoNow(),
		version = VERSION,
		currentCamera = V36.currentCameraSummary(),
		nearbyWorld = scout.nearbyWorld,
		visibleUi = visibleUi,
		scene = scout.scene,
		worldAudit = okWorld and worldAudit or nil,
		suggestions = suggestions,
		nextCommand = suggestions[1] and suggestions[1].command or "tools\\bridge.cmd camera scout",
		message = "View-guided build context for deciding what Codex should create, polish, or inspect from the current camera angle.",
	}
	V37.last.buildContext = result
	return result
end

function V37.getCameraDirectorReport(payload)
	payload = payload or {}
	local status = V36.getCameraNavigatorStatus(payload)
	local coverage = V37.getCameraCoverageReport(payload)
	local context = V37.getCameraViewBuildContext(payload)
	local pathPlan = V37.getCameraPathPlan(payload)
	local nextCommand = status.installed and "tools\\bridge.cmd camera path-run" or "tools\\bridge.cmd ready apply"
	local result = {
		at = isoNow(),
		version = VERSION,
		status = status.installed and "ready" or "needsHarness",
		navigator = {
			installed = status.installed,
			contextType = status.contextType,
			playMode = status.playMode,
			currentCamera = status.currentCamera,
			liveClientCamera = status.liveClientCamera,
		},
		coverage = {
			status = coverage.status,
			count = coverage.coverageCount,
			points = coverage.coverage,
		},
		viewBuildContext = {
			nextCommand = context.nextCommand,
			suggestions = context.suggestions,
		},
		path = {
			status = pathPlan.status,
			waypointCount = #pathPlan.waypoints,
			estimatedSeconds = pathPlan.estimatedSeconds,
		},
		nextCommand = nextCommand,
		message = status.installed and "Camera Director is ready: scout, smooth path, and build from view are available." or "Install/update Codex Ready setup to enable Play-mode camera movement.",
	}
	V37.last.director = result
	return result
end

function V37.requestCameraSmoothMove(payload)
	payload = payload or {}
	local plan = V36.getCameraMovePlan(payload)
	if plan.status ~= "ready" then
		return plan
	end
	local duration = math.clamp(V37.numberOr(payload.duration, 1.15), 0, 12)
	local ok, message = V36.fireCameraCommand({
		kind = "smoothMove",
		position = plan.position,
		lookAt = plan.lookAt,
		duration = duration,
		source = "CodexStudioBridge",
		version = VERSION,
	})
	return {
		at = isoNow(),
		version = VERSION,
		status = ok and "requested" or "manualRequired",
		message = message,
		duration = duration,
		plan = plan,
		after = V25.getCameraViewReport(payload),
		nextCommand = "tools\\bridge.cmd camera release",
	}
end

function V37.requestCameraPath(payload)
	payload = payload or {}
	local plan = payload.plan
	if type(plan) ~= "table" or type(plan.waypoints) ~= "table" then
		plan = V37.getCameraPathPlan(payload)
	end
	if type(plan.waypoints) ~= "table" or #plan.waypoints == 0 then
		return {
			at = isoNow(),
			version = VERSION,
			status = "failed",
			error = "No camera path waypoints are available.",
			plan = plan,
		}
	end
	local ok, message = V36.fireCameraCommand({
		kind = "path",
		waypoints = plan.waypoints,
		duration = V37.numberOr(payload.duration, nil),
		pause = V37.numberOr(payload.pause, 0.15),
		source = "CodexStudioBridge",
		version = VERSION,
	})
	return {
		at = isoNow(),
		version = VERSION,
		status = ok and "requested" or "manualRequired",
		message = message,
		waypointCount = #plan.waypoints,
		plan = plan,
		nextCommand = "tools\\bridge.cmd camera director",
	}
end

function V37.applyCameraViewMarkers(payload)
	payload = payload or {}
	return withUndo("ApplyCameraViewMarkers", function()
		local plan = V37.getCameraPathPlan(payload)
		local folder = resolvePath("Workspace.CodexCameraViewMarkers")
		if not folder then
			folder = Instance.new("Folder")
			folder.Name = "CodexCameraViewMarkers"
			folder.Parent = workspace
		end
		local created = {}
		for index, waypoint in ipairs(plan.waypoints or {}) do
			local position = V36.vectorFromPayload(waypoint.position, nil)
			if position then
				local name = tostring(waypoint.id or ("View" .. tostring(index)))
				local marker = folder:FindFirstChild(name)
				if not marker then
					marker = Instance.new("Part")
					marker.Name = name
					marker.Anchored = true
					marker.CanCollide = false
					marker.Shape = Enum.PartType.Ball
					marker.Size = Vector3.new(3, 3, 3)
					marker.Material = Enum.Material.Neon
					marker.Color = Color3.fromRGB(80, 180, 255)
					marker.Transparency = 0.25
					marker.Parent = folder
				end
				marker.Position = position
				marker:SetAttribute("CodexCameraViewMarker", true)
				marker:SetAttribute("Reason", tostring(waypoint.reason or ""))
				table.insert(created, { path = safeFullName(marker), title = waypoint.title, position = waypoint.position })
			end
		end
		stateDirty = true
		return {
			at = isoNow(),
			version = VERSION,
			status = "marked",
			count = #created,
			markers = created,
			nextCommand = "tools\\bridge.cmd camera path-run",
		}
	end)
end

-- V38 Screen Control / Visible Guidance Layer. This controls the Roblox play
-- screen through Codex-owned overlays and safe client-side guidance only.
function V38.harnessPaths()
	return {
		"ReplicatedStorage.CodexScreenControl",
		"ReplicatedStorage.CodexScreenControl.ScreenCommand",
		"ReplicatedStorage.CodexScreenControl.ScreenResult",
		"ReplicatedStorage.CodexScreenControl.LastScreenCommand",
		"ReplicatedStorage.CodexScreenControl.LastScreenResult",
		"ReplicatedStorage.CodexScreenControl.Manifest",
		"StarterPlayer.StarterPlayerScripts.CodexScreenControlClient",
		"ServerScriptService.CodexScreenControlRelay",
	}
end

function V38.clientSource()
	return [==[
local HttpService = game:GetService("HttpService")
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local player = Players.LocalPlayer
local folder = ReplicatedStorage:WaitForChild("CodexScreenControl", 10)
local commandRemote = folder and folder:FindFirstChild("ScreenCommand")
local resultRemote = folder and folder:FindFirstChild("ScreenResult")
local currentGui = nil

local function pathOf(instance)
	local ok, path = pcall(function() return instance:GetFullName() end)
	return ok and path or tostring(instance)
end

local function stableId(kind, path, ordinal)
	local text = tostring(kind or "target") .. ":" .. tostring(path or "") .. ":" .. tostring(ordinal or 1)
	local hash = 0
	for index = 1, #text do
		hash = (hash * 31 + string.byte(text, index)) % 1000000007
	end
	return tostring(kind or "target") .. "-" .. tostring(hash) .. "-" .. tostring(ordinal or 1)
end

local function playerGui()
	return player:FindFirstChildOfClass("PlayerGui")
end

local function clearOverlay()
	if currentGui and currentGui.Parent then
		currentGui:Destroy()
	end
	currentGui = nil
	local gui = playerGui()
	if gui then
		local existing = gui:FindFirstChild("CodexScreenControlOverlay")
		if existing then existing:Destroy() end
	end
end

local function ensureOverlay()
	local gui = playerGui()
	if not gui then return nil end
	if currentGui and currentGui.Parent then return currentGui end
	local existing = gui:FindFirstChild("CodexScreenControlOverlay")
	if existing then existing:Destroy() end
	local screen = Instance.new("ScreenGui")
	screen.Name = "CodexScreenControlOverlay"
	screen.ResetOnSpawn = false
	screen.IgnoreGuiInset = true
	screen.DisplayOrder = 1000000
	screen.Parent = gui
	currentGui = screen
	return screen
end

local function respond(status, detail)
	detail = detail or {}
	if resultRemote then
		resultRemote:FireServer({ status = status, detail = detail, clientAt = os.clock() })
	end
	print("[CodexScreenControl]", tostring(status), HttpService:JSONEncode(detail))
end

local function isVisible(instance)
	if not (instance and instance:IsA("GuiObject")) then return false end
	if instance.Visible == false then return false end
	local current = instance.Parent
	while current do
		if current:IsA("GuiObject") and current.Visible == false then return false end
		if current:IsA("ScreenGui") and current.Enabled == false then return false end
		current = current.Parent
	end
	return true
end

local function resolveByPath(path)
	path = tostring(path or "")
	if path == "" then return nil end
	local pg = playerGui()
	if not pg then return nil end
	for _, descendant in ipairs(pg:GetDescendants()) do
		if pathOf(descendant) == path then return descendant end
	end
	if pathOf(pg) == path then return pg end
	return nil
end

local function targetText(instance)
	if instance and (instance:IsA("TextButton") or instance:IsA("TextLabel") or instance:IsA("TextBox")) then
		return tostring(instance.Text or "")
	end
	return ""
end

local function findTarget(selector)
	selector = selector or {}
	local pg = playerGui()
	if not pg then return {}, "PlayerGui unavailable" end
	local exact = selector.path and resolveByPath(selector.path)
	if exact and exact:IsA("GuiObject") and isVisible(exact) then return { exact } end
	local matches = {}
	local seen = {}
	for _, descendant in ipairs(pg:GetDescendants()) do
		if descendant:IsA("GuiObject") and isVisible(descendant) then
			local path = pathOf(descendant)
			seen[path] = (seen[path] or 0) + 1
			local id = stableId("ui", path, seen[path])
			local text = targetText(descendant)
			if selector.id and id == tostring(selector.id) then
				table.insert(matches, descendant)
			elseif selector.name and string.lower(descendant.Name) == string.lower(tostring(selector.name)) then
				table.insert(matches, descendant)
			elseif selector.text and string.find(string.lower(text), string.lower(tostring(selector.text)), 1, true) then
				table.insert(matches, descendant)
			end
			if #matches > 20 then break end
		end
	end
	return matches
end

local function summarize(instance)
	if not instance then return nil end
	local pos = instance:IsA("GuiObject") and instance.AbsolutePosition or Vector2.zero
	local size = instance:IsA("GuiObject") and instance.AbsoluteSize or Vector2.zero
	return {
		path = pathOf(instance),
		name = instance.Name,
		className = instance.ClassName,
		text = targetText(instance),
		absolutePosition = { x = pos.X, y = pos.Y },
		absoluteSize = { x = size.X, y = size.Y },
		center = { x = pos.X + size.X / 2, y = pos.Y + size.Y / 2 },
		visible = instance:IsA("GuiObject") and isVisible(instance) or nil,
		zIndex = instance:IsA("GuiObject") and instance.ZIndex or nil,
	}
end

local function drawBanner(message, tone, duration)
	local overlay = ensureOverlay()
	if not overlay then return nil end
	local banner = Instance.new("TextLabel")
	banner.Name = "Guide"
	banner.AnchorPoint = Vector2.new(0.5, 0)
	banner.Position = UDim2.new(0.5, 0, 0, 18)
	banner.Size = UDim2.new(0, 620, 0, 44)
	banner.BackgroundTransparency = 0.08
	banner.BackgroundColor3 = tone == "warn" and Color3.fromRGB(80, 42, 10) or Color3.fromRGB(12, 18, 30)
	banner.BorderSizePixel = 0
	banner.TextColor3 = Color3.fromRGB(255, 255, 255)
	banner.TextWrapped = true
	banner.TextScaled = true
	banner.Font = Enum.Font.SourceSansBold
	banner.Text = tostring(message or "Codex screen guide")
	banner.Parent = overlay
	local corner = Instance.new("UICorner")
	corner.CornerRadius = UDim.new(0, 8)
	corner.Parent = banner
	if tonumber(duration or 0) and tonumber(duration or 0) > 0 then
		task.delay(math.clamp(tonumber(duration), 1, 60), function()
			if banner and banner.Parent then banner:Destroy() end
		end)
	end
	return banner
end

local function drawTarget(instance, labelText)
	local overlay = ensureOverlay()
	if not (overlay and instance and instance:IsA("GuiObject")) then return nil end
	local pos = instance.AbsolutePosition
	local size = instance.AbsoluteSize
	local box = Instance.new("Frame")
	box.Name = "TargetHighlight"
	box.BackgroundTransparency = 1
	box.BorderSizePixel = 0
	box.Position = UDim2.fromOffset(pos.X, pos.Y)
	box.Size = UDim2.fromOffset(math.max(8, size.X), math.max(8, size.Y))
	box.Parent = overlay
	local stroke = Instance.new("UIStroke")
	stroke.Thickness = 4
	stroke.Color = Color3.fromRGB(88, 210, 255)
	stroke.Parent = box
	local label = Instance.new("TextLabel")
	label.Name = "TargetLabel"
	label.BackgroundTransparency = 0.08
	label.BackgroundColor3 = Color3.fromRGB(8, 18, 32)
	label.TextColor3 = Color3.fromRGB(215, 245, 255)
	label.Text = tostring(labelText or "Codex target")
	label.TextSize = 16
	label.Font = Enum.Font.SourceSansBold
	label.Size = UDim2.fromOffset(180, 26)
	label.Position = UDim2.fromOffset(0, -30)
	label.Parent = box
	return box
end

local function handle(command)
	if type(command) ~= "table" then return end
	local kind = tostring(command.kind or "guide")
	if kind == "clear" then
		clearOverlay()
		return respond("cleared", { kind = kind })
	end
	if kind == "guide" then
		if command.clearFirst ~= false then clearOverlay() end
		drawBanner(command.message or command.text or "Codex is guiding this screen.", command.tone, command.duration or 8)
		return respond("guided", { message = command.message or command.text, duration = command.duration or 8 })
	end
	if kind == "highlight" or kind == "focus" then
		if command.clearFirst ~= false then clearOverlay() end
		local matches, reason = findTarget(command.target or {})
		if #matches == 0 then
			drawBanner(command.message or "Codex target was not found on this screen.", "warn", command.duration or 8)
			return respond("notFound", { requestedTarget = command.target, reason = reason or "No matching visible UI target." })
		end
		if #matches > 1 then
			local candidates = {}
			for index, item in ipairs(matches) do
				if index <= 8 then table.insert(candidates, summarize(item)) end
			end
			drawBanner("Codex found multiple matching screen targets. Use --id or exact --path.", "warn", command.duration or 10)
			return respond("ambiguous", { requestedTarget = command.target, candidates = candidates })
		end
		local target = matches[1]
		local label = command.label or command.message or ("Focus: " .. target.Name)
		drawTarget(target, label)
		drawBanner(command.message or ("Codex is focusing " .. target.Name), command.tone, command.duration or 10)
		return respond(kind == "focus" and "focused" or "highlighted", { target = summarize(target), message = command.message })
	end
	respond("unsupported", { kind = kind })
end

print("[CodexScreenControl] client ready")
if commandRemote then
	commandRemote.OnClientEvent:Connect(handle)
else
	print("[CodexScreenControl] ScreenCommand remote missing")
end
]==]
end

function V38.relaySource()
	return [==[
local HttpService = game:GetService("HttpService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local folder = ReplicatedStorage:WaitForChild("CodexScreenControl", 10)
local resultRemote = folder and folder:FindFirstChild("ScreenResult")
local lastResult = folder and folder:FindFirstChild("LastScreenResult")

if resultRemote then
	resultRemote.OnServerEvent:Connect(function(player, result)
		local encoded = "{}"
		pcall(function()
			encoded = HttpService:JSONEncode({
				player = player and player.Name or "unknown",
				result = result,
				serverAt = os.time(),
			})
		end)
		if lastResult and lastResult:IsA("StringValue") then
			lastResult.Value = encoded
		end
		print("[CodexScreenControl] result", tostring(player and player.Name or "unknown"), encoded)
	end)
else
	print("[CodexScreenControl] ScreenResult remote missing")
end
print("[CodexScreenControl] relay ready")
]==]
end

function V38.screenControlBlueprint(payload)
	return {
		name = "Codex Screen Control Harness",
		mode = "supervised",
		source = "installScreenControlHarness",
		steps = {
			{ type = "ensureFolder", path = "ReplicatedStorage.CodexScreenControl" },
			{ type = "ensureRemoteEvent", path = "ReplicatedStorage.CodexScreenControl.ScreenCommand" },
			{ type = "ensureRemoteEvent", path = "ReplicatedStorage.CodexScreenControl.ScreenResult" },
			{ type = "createInstance", className = "StringValue", path = "ReplicatedStorage.CodexScreenControl.LastScreenCommand", properties = { Value = "" } },
			{ type = "createInstance", className = "StringValue", path = "ReplicatedStorage.CodexScreenControl.LastScreenResult", properties = { Value = "" } },
			V25.scriptWriteStep("StarterPlayer.StarterPlayerScripts.CodexScreenControlClient", "LocalScript", V38.clientSource()),
			V25.scriptWriteStep("ServerScriptService.CodexScreenControlRelay", "Script", V38.relaySource()),
			V25.scriptWriteStep("ReplicatedStorage.CodexScreenControl.Manifest", "ModuleScript", "return { name = \"CodexScreenControl\", version = \"" .. VERSION .. "\", purpose = \"visible screen guidance/highlight/control overlay\" }\n"),
		},
	}
end

function V38.getScreenControlStatus(payload)
	payload = payload or {}
	local paths = {}
	local installed = 0
	for _, path in ipairs(V38.harnessPaths()) do
		local instance = resolvePath(path)
		if instance then
			installed += 1
			table.insert(paths, { path = path, exists = true, className = instance.ClassName, id = getInstanceId(instance) })
		else
			table.insert(paths, { path = path, exists = false })
		end
	end
	local manifest = resolvePath("ReplicatedStorage.CodexScreenControl.Manifest")
	local versionCurrent = false
	if manifest and manifest:IsA("LuaSourceContainer") then
		local ok, source = pcall(function()
			return readScriptSource(manifest)
		end)
		versionCurrent = ok and string.find(source, "version = \"" .. VERSION .. "\"", 1, true) ~= nil
	end
	local lastResult = resolvePath("ReplicatedStorage.CodexScreenControl.LastScreenResult")
	local decoded = nil
	if lastResult and lastResult:IsA("StringValue") and lastResult.Value ~= "" then
		local ok, value = pcall(function()
			return HttpService:JSONDecode(lastResult.Value)
		end)
		if ok then
			decoded = value
		end
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		installed = installed == #paths,
		partial = installed > 0 and installed < #paths,
		installedCount = installed,
		missingCount = #paths - installed,
		versionCurrent = versionCurrent,
		status = installed == #paths and (versionCurrent and "installed" or "outdated") or "missing",
		paths = paths,
		lastResult = decoded,
		playMode = RunService:IsRunning(),
		nextCommand = installed == #paths and "tools\\bridge.cmd screen guide \"Codex is watching this screen\"" or "tools\\bridge.cmd ready apply",
		message = "Screen Control uses a Codex-owned PlayerGui overlay for visible guidance, target focus, and manual-action support.",
	}
	V38.last.status = result
	return result
end

