function V38.fireScreenCommand(command)
	local remote = resolvePath("ReplicatedStorage.CodexScreenControl.ScreenCommand")
	if not remote or not remote:IsA("RemoteEvent") then
		return false, "CodexScreenControl ScreenCommand remote is missing. Run tools\\bridge.cmd ready apply."
	end
	local encoded = nil
	pcall(function()
		encoded = HttpService:JSONEncode(command)
	end)
	local lastCommand = resolvePath("ReplicatedStorage.CodexScreenControl.LastScreenCommand")
	if lastCommand and lastCommand:IsA("StringValue") and encoded then
		lastCommand.Value = encoded
	end
	local players = Players:GetPlayers()
	if #players == 0 then
		return false, "No Play-mode players are available for screen control."
	end
	for _, player in ipairs(players) do
		remote:FireClient(player, command)
	end
	return true, "Sent screen command to " .. tostring(#players) .. " client(s)."
end

