function V38.installScreenControlHarness(payload)
	local blueprint = normalizeBlueprint(payload or {}) or V38.screenControlBlueprint(payload or {})
	local result = applyBuildPlan({ blueprint = blueprint })
	result.kind = "screenControlInstall"
	result.status = V38.getScreenControlStatus(payload)
	return result
end

function V38.removeScreenControlHarness(payload)
	return withUndo("RemoveScreenControlHarness", function()
		local result = { appliedAt = isoNow(), removed = {}, missing = {}, failed = {} }
		for _, path in ipairs(V38.harnessPaths()) do
			local instance = resolvePath(path)
			if instance then
				local ok, err = pcall(function()
					instance:Destroy()
				end)
				if ok then
					table.insert(result.removed, { path = path })
				else
					table.insert(result.failed, { path = path, message = tostring(err) })
				end
			else
				table.insert(result.missing, { path = path })
			end
		end
		stateDirty = true
		result.summary = { removed = #result.removed, missing = #result.missing, failed = #result.failed }
		return result
	end)
end

