		Trail = { "Enabled", "Texture", "TextureLength", "TextureMode", "Color", "Transparency", "Lifetime", "MinLength", "WidthScale", "FaceCamera", "LightEmission", "LightInfluence", "Attachment0", "Attachment1" },
		Attachment = { "CFrame", "Position", "Orientation", "Visible", "WorldCFrame", "WorldPosition" },
