function V39.isVfx(instance)
	return instance and V39.classMap()[instance.ClassName] == true
end

function V39.root(payload)
	payload = payload or {}
	return resolvePath(payload.path or payload.root or payload.target or "") or workspace
end

function V39.tags(instance)
	local okService, collectionService = pcall(function()
		return game:GetService("CollectionService")
	end)
	if not okService or not collectionService then
		return {}
	end
	local ok, tags = pcall(function()
		return collectionService:GetTags(instance)
	end)
	return ok and tags or {}
end

function V39.readProperties(instance)
	local props = {}
	for _, propertyName in ipairs(V39.propertyMap()[instance.ClassName] or {}) do
		readProperty(instance, propertyName, props)
	end
	return props
end

function V39.assetId(raw)
	local value = tostring(raw or "")
	if value == "" then return nil end
	local id = value:match("rbxassetid://(%d+)") or value:match("[?&]id=(%d+)") or value:match("(%d+)")
	if not id then return value end
	return "rbxassetid://" .. tostring(id)
end

function V39.assetFields(instance)
	local fields = {}
	local map = {
		ParticleEmitter = { "Texture" },
		Beam = { "Texture" },
		Trail = { "Texture" },
		Decal = { "Texture" },
		Texture = { "Texture" },
		MeshPart = { "MeshId", "TextureID" },
		SpecialMesh = { "MeshId", "TextureId" },
		Sound = { "SoundId" },
	}
	for _, propertyName in ipairs(map[instance.ClassName] or {}) do
		local ok, value = pcall(function()
			return instance[propertyName]
		end)
		local normalized = ok and V39.assetId(value) or nil
		if normalized then
			table.insert(fields, { property = propertyName, assetId = normalized, raw = tostring(value or "") })
		end
	end
	return fields
end

function V39.objectSummary(instance)
	return {
		id = getInstanceId(instance),
		name = instance.Name,
		className = instance.ClassName,
		path = safeFullName(instance),
		parentPath = instance.Parent and safeFullName(instance.Parent) or nil,
		tags = V39.tags(instance),
		attributes = serializeAttributes(instance),
		properties = V39.readProperties(instance),
		assets = V39.assetFields(instance),
		childCount = #instance:GetChildren(),
		descendantCount = #instance:GetDescendants(),
	}
end

function V39.collect(payload)
	payload = payload or {}
	local root = V39.root(payload)
	local maxNodes = tonumber(payload.maxNodes or payload.limit or 1500) or 1500
	local query = string.lower(tostring(payload.query or ""))
	local found = {}
	local scanned = 0
	local classCounts = {}
	local function visit(instance)
		if scanned >= maxNodes then return end
		scanned += 1
		local isVfx = V39.isVfx(instance)
		local haystack = string.lower(instance.Name .. " " .. instance.ClassName .. " " .. safeFullName(instance))
		if isVfx and (query == "" or string.find(haystack, query, 1, true)) then
			classCounts[instance.ClassName] = (classCounts[instance.ClassName] or 0) + 1
			table.insert(found, V39.objectSummary(instance))
		end
		for _, child in ipairs(instance:GetChildren()) do
			visit(child)
			if scanned >= maxNodes then break end
		end
	end
	visit(root)
	return root, found, scanned, classCounts, scanned >= maxNodes
end

function V39.getVfxInventory(payload)
	local root, found, scanned, classCounts, truncated = V39.collect(payload)
	local result = {
		at = isoNow(),
		version = VERSION,
		root = root and { path = safeFullName(root), className = root.ClassName, id = getInstanceId(root) } or nil,
		count = #found,
		scanned = scanned,
		truncated = truncated,
		classCounts = classCounts,
		items = found,
		nextCommand = "tools\\bridge.cmd vfx catalog " .. tostring(root and safeFullName(root) or "Workspace"),
	}
	V39.last.inventory = result
	return result
end

function V39.getVfxAssetCatalog(payload)
	local root, found = V39.collect(payload)
	local byAsset = {}
	local assets = {}
	for _, item in ipairs(found) do
		for _, asset in ipairs(item.assets or {}) do
			local key = asset.assetId
			if not byAsset[key] then
				byAsset[key] = { assetId = key, usageCount = 0, usages = {}, usageTypes = {} }
				table.insert(assets, byAsset[key])
			end
			local entry = byAsset[key]
			entry.usageCount += 1
			entry.usageTypes[item.className] = true
			table.insert(entry.usages, { path = item.path, name = item.name, className = item.className, property = asset.property })
		end
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		root = root and safeFullName(root) or nil,
		assetCount = #assets,
		objectCount = #found,
		assets = assets,
		luaCatalog = "return " .. V8.luaString(HttpService:JSONEncode(assets)) .. "\n",
		nextCommand = "tools\\bridge.cmd vfx perf",
	}
	V39.last.catalog = result
	return result
end

function V39.getVfxObjectReport(payload)
	payload = payload or {}
	local target = resolvePath(payload.path or payload.target or "") or resolveInstance(payload.instanceId or payload.id)
	if not target then
		return { at = isoNow(), version = VERSION, status = "notFound", error = "VFX target was not found.", requested = payload.path or payload.target or payload.id }
	end
	local descendants = {}
	local classCounts = {}
	for _, descendant in ipairs(target:GetDescendants()) do
		if V39.isVfx(descendant) then
			classCounts[descendant.ClassName] = (classCounts[descendant.ClassName] or 0) + 1
			if #descendants < tonumber(payload.maxDescendants or 80) then
				table.insert(descendants, V39.objectSummary(descendant))
			end
		end
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		status = V39.isVfx(target) and "vfxObject" or (#descendants > 0 and "vfxContainer" or "nonVfxTarget"),
		target = V39.isVfx(target) and V39.objectSummary(target) or { id = getInstanceId(target), name = target.Name, className = target.ClassName, path = safeFullName(target), properties = readCommonProperties(target), attributes = serializeAttributes(target), tags = V39.tags(target) },
		vfxDescendantCount = #descendants,
		classCounts = classCounts,
		descendants = descendants,
		nextCommand = "tools\\bridge.cmd vfx preview \"" .. safeFullName(target) .. "\"",
	}
	V39.last.objectReport = result
	return result
end

function V39.getVfxPerformanceAudit(payload)
	local inventory = V39.getVfxInventory(payload or {})
	local warnings = {}
	local totals = {
		emitters = inventory.classCounts.ParticleEmitter or 0,
		beams = inventory.classCounts.Beam or 0,
		trails = inventory.classCounts.Trail or 0,
		lights = (inventory.classCounts.PointLight or 0) + (inventory.classCounts.SpotLight or 0) + (inventory.classCounts.SurfaceLight or 0),
		sounds = inventory.classCounts.Sound or 0,
		maxParticles = 0,
		rate = 0,
	}
	for _, item in ipairs(inventory.items or {}) do
		if item.className == "ParticleEmitter" then
			totals.maxParticles += tonumber(item.properties.MaxParticles or 0) or 0
			totals.rate += tonumber(item.properties.Rate or 0) or 0
		end
	end
	local function warn(id, message, severity)
		table.insert(warnings, { id = id, message = message, severity = severity or "warning" })
	end
	if totals.emitters > 60 then warn("manyEmitters", "Large emitter count may hurt low-end clients.", "warning") end
	if totals.rate > 2500 then warn("highParticleRate", "Total particle Rate is high: " .. tostring(math.floor(totals.rate)), "warning") end
	if totals.maxParticles > 15000 then warn("highMaxParticles", "Total MaxParticles is high: " .. tostring(totals.maxParticles), "warning") end
	if totals.lights > 40 then warn("manyLights", "Many dynamic lights can be expensive, especially on mobile.", "warning") end
	local result = {
		at = isoNow(),
		version = VERSION,
		score = math.max(0, 100 - (#warnings * 12)),
		totals = totals,
		classCounts = inventory.classCounts,
		warnings = warnings,
		nextCommand = #warnings > 0 and "tools\\bridge.cmd vfx report" or "tools\\bridge.cmd vfx preview <path>",
	}
	V39.last.performance = result
	return result
end

function V39.paths()
	return {
		"ReplicatedStorage.CodexVfxWorkbench",
		"ReplicatedStorage.CodexVfxWorkbench.VfxCommand",
		"ReplicatedStorage.CodexVfxWorkbench.VfxResult",
		"ReplicatedStorage.CodexVfxWorkbench.LastVfxCommand",
		"ReplicatedStorage.CodexVfxWorkbench.LastVfxResult",
		"ReplicatedStorage.CodexVfxWorkbench.Manifest",
		"StarterPlayer.StarterPlayerScripts.CodexVfxWorkbenchClient",
		"ServerScriptService.CodexVfxWorkbench",
		"ServerScriptService.CodexVfxWorkbench.Relay",
	}
end

function V39.clientSource()
	return [==[
local HttpService = game:GetService("HttpService")
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Workspace = game:GetService("Workspace")
local okCaptureService, CaptureService = pcall(function()
	return game:GetService("CaptureService")
end)
if not okCaptureService then
	CaptureService = nil
end

local player = Players.LocalPlayer
local folder = ReplicatedStorage:WaitForChild("CodexVfxWorkbench", 10)
local commandRemote = folder and folder:FindFirstChild("VfxCommand")
local resultRemote = folder and folder:FindFirstChild("VfxResult")

local function pathOf(instance)
	local ok, path = pcall(function() return instance:GetFullName() end)
	return ok and path or tostring(instance)
end

local function resolvePath(path)
	path = tostring(path or "")
	if path == "" then return nil end
	local parts = string.split(path:gsub("^game%.", ""), ".")
	local current = nil
	pcall(function() current = game:GetService(parts[1]) end)
	current = current or game:FindFirstChild(parts[1])
	for index = 2, #parts do
		current = current and current:FindFirstChild(parts[index])
	end
	return current
end

local function emitTarget(instance, count)
	local emitted = 0
	local sounds = 0
	local function visit(item)
		if item:IsA("ParticleEmitter") then
			pcall(function() item:Emit(count or math.max(1, math.floor(item.Rate / 4))) end)
			emitted += 1
		elseif item:IsA("Sound") then
			pcall(function() item:Play() end)
			sounds += 1
		end
		for _, child in ipairs(item:GetChildren()) do
			visit(child)
		end
	end
	if instance then visit(instance) end
	return emitted, sounds
end

local function respond(status, detail)
	detail = detail or {}
	if resultRemote then
		resultRemote:FireServer({ status = status, detail = detail, clientAt = os.clock() })
	end
	print("[CodexVfxWorkbench]", tostring(status), HttpService:JSONEncode(detail))
end

local function handle(command)
	if type(command) ~= "table" then return end
	local kind = tostring(command.kind or "play")
	local target = resolvePath(command.path or command.targetPath or "")
	if kind == "capture" then
		if not CaptureService then
			return respond("captureUnavailable", { reason = "CaptureService unavailable in this client context", structuredFallback = true })
		end
		local ok, err = pcall(function()
			CaptureService:TakeScreenshotCaptureAsync(function(result, capture)
				respond("captureResult", { result = tostring(result), capture = tostring(capture), path = command.path })
			end, { UICaptureMode = Enum.UICaptureMode.All })
		end)
		if not ok then
			return respond("captureUnavailable", { reason = tostring(err), structuredFallback = true })
		end
		return respond("captureRequested", { path = command.path })
	end
	if not target then
		return respond("notFound", { path = command.path or command.targetPath })
	end
	if kind == "stress" then
		local count = math.clamp(tonumber(command.count or 10) or 10, 1, 200)
		local emitted = 0
		local sounds = 0
		for _ = 1, count do
			local e, s = emitTarget(target, tonumber(command.emitCount or 10) or 10)
			emitted += e
			sounds += s
			task.wait(0.03)
		end
		return respond("stressComplete", { path = pathOf(target), iterations = count, emittersTouched = emitted, soundsPlayed = sounds })
	end
	local emitted, sounds = emitTarget(target, tonumber(command.emitCount or 20) or 20)
	return respond("played", { path = pathOf(target), emittersTouched = emitted, soundsPlayed = sounds })
end

print("[CodexVfxWorkbench] client ready")
if commandRemote then
	commandRemote.OnClientEvent:Connect(handle)
else
	print("[CodexVfxWorkbench] VfxCommand remote missing")
end
]==]
end

function V39.relaySource()
	return [==[
local HttpService = game:GetService("HttpService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local folder = ReplicatedStorage:WaitForChild("CodexVfxWorkbench", 10)
local resultRemote = folder and folder:FindFirstChild("VfxResult")
local lastResult = folder and folder:FindFirstChild("LastVfxResult")

if resultRemote then
	resultRemote.OnServerEvent:Connect(function(player, result)
		local encoded = "{}"
		pcall(function()
			encoded = HttpService:JSONEncode({ player = player and player.Name or "unknown", result = result, serverAt = os.time() })
		end)
		if lastResult and lastResult:IsA("StringValue") then
			lastResult.Value = encoded
		end
		print("[CodexVfxWorkbench] result", tostring(player and player.Name or "unknown"), encoded)
	end)
end
print("[CodexVfxWorkbench] relay ready")
]==]
end

function V39.vfxWorkbenchBlueprint(payload)
	return {
		name = "Codex VFX Workbench Harness",
		mode = "supervised",
		source = "installVfxWorkbenchHarness",
		steps = {
			{ type = "ensureFolder", path = "ReplicatedStorage.CodexVfxWorkbench" },
			{ type = "ensureFolder", path = "ReplicatedStorage.CodexVfxWorkbench.Assets" },
			{ type = "ensureFolder", path = "ReplicatedStorage.CodexVfxWorkbench.Presets" },
			{ type = "ensureFolder", path = "ReplicatedStorage.CodexVfxWorkbench.Runtime" },
			{ type = "ensureRemoteEvent", path = "ReplicatedStorage.CodexVfxWorkbench.VfxCommand" },
			{ type = "ensureRemoteEvent", path = "ReplicatedStorage.CodexVfxWorkbench.VfxResult" },
			{ type = "createInstance", className = "StringValue", path = "ReplicatedStorage.CodexVfxWorkbench.LastVfxCommand", properties = { Value = "" } },
			{ type = "createInstance", className = "StringValue", path = "ReplicatedStorage.CodexVfxWorkbench.LastVfxResult", properties = { Value = "" } },
			{ type = "ensureFolder", path = "ServerScriptService.CodexVfxWorkbench" },
			V25.scriptWriteStep("StarterPlayer.StarterPlayerScripts.CodexVfxWorkbenchClient", "LocalScript", V39.clientSource()),
			V25.scriptWriteStep("ServerScriptService.CodexVfxWorkbench.Relay", "Script", V39.relaySource()),
			V25.scriptWriteStep("ReplicatedStorage.CodexVfxWorkbench.Manifest", "ModuleScript", "return { name = \"CodexVfxWorkbench\", version = \"" .. VERSION .. "\", purpose = \"universal VFX preview/playback/capture workbench\" }\n"),
		},
	}
end

function V39.getVfxPreviewStatus(payload)
	local paths = {}
	local installed = 0
	for _, path in ipairs(V39.paths()) do
		local instance = resolvePath(path)
		if instance then
			installed += 1
			table.insert(paths, { path = path, exists = true, className = instance.ClassName, id = getInstanceId(instance) })
		else
			table.insert(paths, { path = path, exists = false })
		end
	end
	local manifest = resolvePath("ReplicatedStorage.CodexVfxWorkbench.Manifest")
	local versionCurrent = false
	if manifest and manifest:IsA("LuaSourceContainer") then
		local ok, source = pcall(function() return readScriptSource(manifest) end)
		versionCurrent = ok and string.find(source, "version = \"" .. VERSION .. "\"", 1, true) ~= nil
	end
	local lastResult = resolvePath("ReplicatedStorage.CodexVfxWorkbench.LastVfxResult")
	local resultText = lastResult and lastResult:IsA("StringValue") and lastResult.Value or ""
	local result = {
		at = isoNow(),
		version = VERSION,
		installed = installed == #paths,
		status = installed == #paths and (versionCurrent and "installed" or "outdated") or "missing",
		installedCount = installed,
		missingCount = #paths - installed,
		versionCurrent = versionCurrent,
		paths = paths,
		lastResult = V9.trimText(resultText, 500),
		previewStage = resolvePath("Workspace.CodexVfxPreviewStage") ~= nil,
		nextCommand = installed == #paths and "tools\\bridge.cmd vfx report" or "tools\\bridge.cmd ready apply",
	}
	V39.last.status = result
	return result
end

function V39.getVfxPreviewPlan(payload)
	payload = payload or {}
	local target = resolvePath(payload.path or payload.target or "") or V39.root(payload)
	local report = target and V39.getVfxObjectReport({ path = safeFullName(target) }) or nil
	return {
		at = isoNow(),
		version = VERSION,
		target = target and { path = safeFullName(target), className = target.ClassName, id = getInstanceId(target) } or nil,
		objectReport = report,
		strategies = {
			{ id = "studioCapture", status = "bestEffort", description = "Use StudioCaptureService if plugin permission/API is available." },
			{ id = "clientCapture", status = "bestEffort", description = "Use client CaptureService through the Full Trust live/VFX harness during Play." },
			{ id = "previewStage", status = "available", description = "Create Workspace.CodexVfxPreviewStage with neutral lighting and scale markers." },
			{ id = "structuredFallback", status = "always", description = "Return hierarchy/properties/assets/performance data even when images are blocked." },
		},
		requiresApprovalForStage = true,
		nextCommand = target and ("tools\\bridge.cmd vfx stage \"" .. safeFullName(target) .. "\"") or "tools\\bridge.cmd vfx inventory Workspace",
	}
end

function V39.getVfxCaptureReport(payload)
	local okService, service = pcall(function() return game:GetService("StudioCaptureService") end)
	local canCapture = false
	if okService and service then
		pcall(function()
			canCapture = service:CanCaptureScreenshot()
		end)
	end
	local live = V25.getVisualCaptureReport and V25.getVisualCaptureReport(payload or {}) or nil
	local result = {
		at = isoNow(),
		version = VERSION,
		studioCapture = { serviceAvailable = okService and service ~= nil, canCaptureScreenshot = canCapture },
		clientCapture = live,
		fallback = "Use vfx preview/stage plus structured VFX data when screenshot APIs are unavailable.",
		nextCommand = canCapture and "tools\\bridge.cmd vfx capture <path>" or "tools\\bridge.cmd vfx preview <path>",
	}
	V39.last.capture = result
	return result
end

function V39.stageBlueprint(payload)
	payload = payload or {}
	return {
		name = "Codex VFX Preview Stage",
		mode = "supervised",
		source = "applyVfxPreviewStage",
		steps = {
			{ type = "ensureFolder", path = "Workspace.CodexVfxPreviewStage" },
			{ type = "createPart", path = "Workspace.CodexVfxPreviewStage.NeutralBase", properties = { Anchored = true, CanCollide = false, Size = { __type = "Vector3", x = 48, y = 1, z = 48 }, Position = { __type = "Vector3", x = 0, y = 2, z = 0 }, Color = { __type = "Color3", mode = "rgb", r = 32, g = 36, b = 42 }, Material = "SmoothPlastic" } },
			{ type = "createPart", path = "Workspace.CodexVfxPreviewStage.ScaleMarker", properties = { Anchored = true, CanCollide = false, Size = { __type = "Vector3", x = 2, y = 8, z = 2 }, Position = { __type = "Vector3", x = -18, y = 6, z = -18 }, Color = { __type = "Color3", mode = "rgb", r = 80, g = 180, b = 255 }, Material = "Neon" } },
			{ type = "ensureInstance", path = "Workspace.CodexVfxPreviewStage.NeutralBase.PreviewAttachment", className = "Attachment", properties = { Position = { __type = "Vector3", x = 0, y = 5, z = 0 } } },
			{ type = "ensureInstance", path = "Workspace.CodexVfxPreviewStage.NeutralBase.KeyLight", className = "PointLight", properties = { Enabled = true, Brightness = 2.5, Range = 40, Color = { __type = "Color3", mode = "rgb", r = 190, g = 220, b = 255 } } },
		},
	}
end

function V39.applyVfxPreviewStage(payload)
	local result = applyBuildPlan({ blueprint = V39.stageBlueprint(payload or {}) })
	result.kind = "vfxPreviewStage"
	result.previewPlan = V39.getVfxPreviewPlan(payload or {})
	return result
end

function V39.safeName(value, fallback)
	local text = tostring(value or fallback or "VfxPreset"):gsub("[^%w_%-]", "_")
	if text == "" then text = "VfxPreset" end
	return text
end

function V39.presetBlueprint(payload)
	payload = payload or {}
	local preset = payload.preset or payload
	local name = V39.safeName(preset.name or payload.name, "CodexVfxPreset")
	local basePath = "ReplicatedStorage.CodexVfxWorkbench.Presets." .. name
	local stageAnchor = "Workspace.CodexVfxPreviewStage." .. name .. "Anchor"
	local steps = {
		{ type = "ensureFolder", path = "ReplicatedStorage.CodexVfxWorkbench" },
		{ type = "ensureFolder", path = "ReplicatedStorage.CodexVfxWorkbench.Presets" },
		{ type = "ensureFolder", path = basePath },
		{ type = "ensureFolder", path = "Workspace.CodexVfxPreviewStage" },
		{ type = "createPart", path = stageAnchor, properties = { Anchored = true, CanCollide = false, CanQuery = false, Size = { __type = "Vector3", x = 2, y = 2, z = 2 }, Position = { __type = "Vector3", x = 0, y = 7, z = 0 }, Transparency = 1 } },
		{ type = "ensureInstance", path = stageAnchor .. ".PreviewAttachment", className = "Attachment", properties = { Position = { __type = "Vector3", x = 0, y = 0, z = 0 } } },
		V25.scriptWriteStep(basePath .. ".Manifest", "ModuleScript", "return { name = " .. V8.luaString(name) .. ", version = \"" .. VERSION .. "\", json = " .. V8.luaString(HttpService:JSONEncode(preset)) .. " }\n"),
	}
	for index, layer in ipairs(preset.layers or preset.steps or {}) do
		local className = tostring(layer.className or layer.type or "ParticleEmitter")
		local layerName = V39.safeName(layer.name or (className .. tostring(index)), className .. tostring(index))
		local parentPath = tostring(layer.parentPath or layer.parent or "")
		if parentPath == "" then
			if className == "ParticleEmitter" or className == "Beam" or className == "Trail" then
				parentPath = stageAnchor .. ".PreviewAttachment"
			elseif className == "PointLight" or className == "SpotLight" or className == "SurfaceLight" or className == "Sound" or className == "Highlight" then
				parentPath = stageAnchor
			else
				parentPath = basePath
			end
		end
		table.insert(steps, { type = "createInstance", className = className, path = parentPath .. "." .. layerName, properties = layer.properties or {} })
	end
	return { name = "Codex VFX Preset: " .. name, mode = "supervised", source = "applyVfxPresetPlan", steps = steps }
end

function V39.applyVfxPresetPlan(payload)
	local blueprint = normalizeBlueprint(payload or {}) or V39.presetBlueprint(payload or {})
	local result = applyBuildPlan({ blueprint = blueprint })
	result.kind = "vfxPresetPlan"
	result.previewStatus = V39.getVfxPreviewStatus(payload)
	return result
end

function V39.fireWorkbench(command)
	local remote = resolvePath("ReplicatedStorage.CodexVfxWorkbench.VfxCommand")
	if not remote or not remote:IsA("RemoteEvent") then
		return false, "CodexVfxWorkbench VfxCommand remote is missing. Run tools\\bridge.cmd ready apply."
	end
	local encoded = nil
	pcall(function() encoded = HttpService:JSONEncode(command) end)
	local lastCommand = resolvePath("ReplicatedStorage.CodexVfxWorkbench.LastVfxCommand")
	if lastCommand and lastCommand:IsA("StringValue") and encoded then
		lastCommand.Value = encoded
	end
	local players = Players:GetPlayers()
	if #players == 0 then
		return false, "No Play-mode players are available for VFX client preview."
	end
	for _, player in ipairs(players) do
		remote:FireClient(player, command)
	end
	return true, "Sent VFX command to " .. tostring(#players) .. " client(s)."
end

function V39.requestVfxPlayback(payload)
	payload = payload or {}
	local path = tostring(payload.path or payload.target or payload.preset or "")
	local ok, message = V39.fireWorkbench({ kind = "play", path = path, emitCount = tonumber(payload.emitCount or 20) or 20, version = VERSION })
	return { at = isoNow(), version = VERSION, status = ok and "requested" or "manualRequired", message = message, path = path, nextCommand = "tools\\bridge.cmd vfx report" }
end

function V39.requestVfxStressTest(payload)
	payload = payload or {}
	local path = tostring(payload.path or payload.target or payload.preset or "")
	local count = math.clamp(tonumber(payload.count or 10) or 10, 1, 200)
	local ok, message = V39.fireWorkbench({ kind = "stress", path = path, count = count, emitCount = tonumber(payload.emitCount or 10) or 10, version = VERSION })
	return { at = isoNow(), version = VERSION, status = ok and "requested" or "manualRequired", message = message, path = path, count = count, performance = V39.getVfxPerformanceAudit({ path = payload.root or "Workspace" }) }
end

function V39.requestVfxPreviewCapture(payload)
	payload = payload or {}
	local okService, service = pcall(function() return game:GetService("StudioCaptureService") end)
	if okService and service then
		local canCapture = false
		pcall(function() canCapture = service:CanCaptureScreenshot() end)
		if canCapture then
			local okCapture, capture = pcall(function()
				return service:CaptureScreenshot({})
			end)
			if okCapture then
				return { at = isoNow(), version = VERSION, status = "studioCaptureRequested", capture = tostring(capture), report = V39.getVfxCaptureReport(payload) }
			end
		end
	end
	local liveResult = V25.requestLiveVisionCapture and V25.requestLiveVisionCapture(payload) or nil
	local ok, message = V39.fireWorkbench({ kind = "capture", path = payload.path or payload.target, version = VERSION })
	return { at = isoNow(), version = VERSION, status = ok and "clientCaptureRequested" or "structuredFallback", message = message, liveVision = liveResult, report = V39.getVfxCaptureReport(payload) }
end

function V39.installVfxWorkbenchHarness(payload)
	local blueprint = normalizeBlueprint(payload or {}) or V39.vfxWorkbenchBlueprint(payload or {})
	local result = applyBuildPlan({ blueprint = blueprint })
	result.kind = "vfxWorkbenchInstall"
	result.status = V39.getVfxPreviewStatus(payload)
	return result
end

function V39.removeVfxWorkbenchHarness(payload)
	return withUndo("RemoveVfxWorkbenchHarness", function()
		local result = { appliedAt = isoNow(), removed = {}, missing = {}, failed = {} }
		for _, path in ipairs({
			"ReplicatedStorage.CodexVfxWorkbench",
			"StarterPlayer.StarterPlayerScripts.CodexVfxWorkbenchClient",
			"ServerScriptService.CodexVfxWorkbench",
			"Workspace.CodexVfxPreviewStage",
		}) do
			local instance = resolvePath(path)
			if instance then
				local ok, err = pcall(function() instance:Destroy() end)
				if ok then table.insert(result.removed, { path = path }) else table.insert(result.failed, { path = path, message = tostring(err) }) end
			else
				table.insert(result.missing, { path = path })
			end
		end
		stateDirty = true
		result.summary = { removed = #result.removed, missing = #result.missing, failed = #result.failed }
		return result
	end)
end

function V39.getVfxWorkbenchReport(payload)
	return {
		at = isoNow(),
		version = VERSION,
		status = V39.getVfxPreviewStatus(payload or {}),
		inventory = V39.getVfxInventory(payload or {}),
		assets = V39.getVfxAssetCatalog(payload or {}),
		performance = V39.getVfxPerformanceAudit(payload or {}),
		capture = V39.getVfxCaptureReport(payload or {}),
		nextCommand = "tools\\bridge.cmd vfx preview <path>",
	}
end

-- V43 Universal VFX Composer + Asset Library
function V43.lower(value)
	return string.lower(tostring(value or ""))
end

function V43.v3(x, y, z)
	return { __type = "Vector3", x = x, y = y, z = z }
end

function V43.v2(x, y)
	return { __type = "Vector2", x = x, y = y }
end

function V43.color(r, g, b)
	return { __type = "Color3", mode = "rgb", r = r, g = g, b = b }
end

function V43.numberRange(minValue, maxValue)
	return { __type = "NumberRange", min = minValue, max = maxValue or minValue }
end

function V43.numberSequence(points)
	local keypoints = {}
	for _, point in ipairs(points or {}) do
		table.insert(keypoints, { time = point[1] or point.time or 0, value = point[2] or point.value or 0, envelope = point[3] or point.envelope or 0 })
	end
	return { __type = "NumberSequence", keypoints = keypoints }
end

function V43.colorSequence(colors)
	local keypoints = {}
	for _, point in ipairs(colors or {}) do
		table.insert(keypoints, { time = point.time or point[1] or 0, color = point.color or point[2] or V43.color(255, 255, 255) })
	end
	return { __type = "ColorSequence", keypoints = keypoints }
end

