			{ id = "healing", description = "Gentle upward motes, rings, and warm highlight." },
			{ id = "smoke", description = "Soft expanding opaque/faded particles." },
			{ id = "dust", description = "Ground-level puffs and motion streaks." },
			{ id = "magicCircle", description = "Ground or hand circle with rings, glyph placeholder, and pulses." },
			{ id = "weaponEnchant", description = "Weapon handle aura, sparks, trail, and highlight." },
			{ id = "handCharge", description = "Palm/hand charge with growing light and orbiting sparks." },
			{ id = "pickup", description = "Small collect sparkle and upward burst." },
			{ id = "portal", description = "Looping ring, inward motes, and glow." },
			{ id = "shield", description = "Bubble/ring shimmer with impact flashes." },
			{ id = "shockwave", description = "Expanding neon ring and dust burst." },
			{ id = "ambientLoop", description = "Subtle looping environmental particles and lights." },
		},
		nextCommand = "tools\\bridge.cmd vfx plan \"purple hand aura that charges and fires a projectile\"",
	}
	V43.last.styles = result
	return result
end

function V43.styleDefinitions()
	local styles = {}
	for _, item in ipairs(V43.getVfxStyleCatalog({}).styles or {}) do
		styles[item.id] = item
	end
	return styles
end

function V43.effectKeywords()
	return {
		{ id = "projectile", words = { "projectile", "fireball", "blast", "shoot", "launch", "bullet", "orb" } },
		{ id = "beam", words = { "beam", "laser", "ray", "kamehameha" } },
		{ id = "slashTrail", words = { "slash", "sword", "trail", "cut", "swipe", "weapon arc" } },
		{ id = "hitBurst", words = { "hit", "impact", "punch", "strike", "contact" } },
		{ id = "explosion", words = { "explosion", "explode", "boom", "blast radius" } },
		{ id = "wind", words = { "wind", "gust", "tornado", "air" } },
		{ id = "lightning", words = { "lightning", "electric", "spark", "zap" } },
		{ id = "healing", words = { "heal", "healing", "life", "revive" } },
		{ id = "smoke", words = { "smoke", "mist", "fog" } },
		{ id = "dust", words = { "dust", "sand", "ground puff" } },
		{ id = "magicCircle", words = { "circle", "rune", "glyph", "magic circle" } },
		{ id = "weaponEnchant", words = { "weapon enchant", "weapon aura", "blade", "handle" } },
		{ id = "handCharge", words = { "hand", "palm", "charge", "charging" } },
		{ id = "pickup", words = { "pickup", "collect", "coin", "reward" } },
		{ id = "portal", words = { "portal", "gate", "rift" } },
		{ id = "shield", words = { "shield", "barrier", "bubble" } },
		{ id = "shockwave", words = { "shockwave", "wave", "ring burst" } },
		{ id = "ambientLoop", words = { "ambient", "loop", "environment", "idle vfx" } },
		{ id = "aura", words = { "aura", "glow", "power up" } },
	}
end

function V43.inferEffectType(intent)
	local text = V43.lower(intent)
	for _, entry in ipairs(V43.effectKeywords()) do
		for _, word in ipairs(entry.words) do
			if string.find(text, word, 1, true) then
				return entry.id
			end
		end
	end
	return "aura"
end

function V43.inferStyle(intent)
	local text = V43.lower(intent)
	local styles = V43.styleDefinitions()
	for id, style in pairs(styles) do
		for _, word in ipairs(style.keywords or {}) do
			if string.find(text, V43.lower(word), 1, true) then
				return id
			end
		end
	end
	return "arcanePurple"
end

function V43.palette(styleId)
	local palettes = {
		arcanePurple = { V43.color(139, 92, 246), V43.color(34, 211, 238), V43.color(245, 208, 254) },
		fire = { V43.color(255, 122, 24), V43.color(255, 209, 102), V43.color(255, 45, 45) },
		ice = { V43.color(167, 243, 255), V43.color(96, 165, 250), V43.color(255, 255, 255) },
		electric = { V43.color(253, 224, 71), V43.color(56, 189, 248), V43.color(255, 255, 255) },
		toxic = { V43.color(163, 230, 53), V43.color(34, 197, 94), V43.color(6, 78, 59) },
		holy = { V43.color(253, 230, 138), V43.color(255, 255, 255), V43.color(147, 197, 253) },
		shadow = { V43.color(17, 24, 39), V43.color(124, 58, 237), V43.color(244, 114, 182) },
		wind = { V43.color(186, 230, 253), V43.color(224, 242, 254), V43.color(255, 255, 255) },
		tech = { V43.color(34, 211, 238), V43.color(20, 184, 166), V43.color(224, 242, 254) },
		healing = { V43.color(134, 239, 172), V43.color(255, 255, 255), V43.color(253, 230, 138) },
	}
	return palettes[styleId] or palettes.arcanePurple
end

function V43.assetReadMap()
	return {
		ParticleEmitter = { "Texture" },
		Beam = { "Texture" },
		Trail = { "Texture" },
		Decal = { "Texture" },
		Texture = { "Texture" },
		MeshPart = { "MeshId", "TextureID" },
		SpecialMesh = { "MeshId", "TextureId" },
		Sound = { "SoundId" },
		ImageLabel = { "Image" },
		ImageButton = { "Image" },
	}
end

function V43.assetCategory(instance, propertyName, assetId)
	local haystack = V43.lower((instance and safeFullName(instance) or "") .. " " .. tostring(propertyName or "") .. " " .. tostring(assetId or ""))
	if instance and instance:IsA("Sound") or propertyName == "SoundId" then return "sound" end
	if propertyName == "MeshId" or propertyName == "TextureID" or propertyName == "TextureId" then return "mesh" end
	if instance and (instance:IsA("ImageLabel") or instance:IsA("ImageButton")) then return "icon" end
	if string.find(haystack, "smoke", 1, true) or string.find(haystack, "cloud", 1, true) or string.find(haystack, "mist", 1, true) then return "smoke" end
	if string.find(haystack, "dust", 1, true) or string.find(haystack, "sand", 1, true) then return "dust" end
	if string.find(haystack, "spark", 1, true) or string.find(haystack, "lightning", 1, true) or string.find(haystack, "bolt", 1, true) then return "spark" end
	if string.find(haystack, "slash", 1, true) or string.find(haystack, "trail", 1, true) or string.find(haystack, "streak", 1, true) then return "slash" end
	if string.find(haystack, "circle", 1, true) or string.find(haystack, "ring", 1, true) or string.find(haystack, "rune", 1, true) then return "circle" end
	if string.find(haystack, "glow", 1, true) or string.find(haystack, "flare", 1, true) or string.find(haystack, "light", 1, true) then return "glow" end
	if string.find(haystack, "noise", 1, true) or string.find(haystack, "soft", 1, true) then return "noise" end
	return "texture"
end

function V43.textureRoots(payload)
	payload = payload or {}
	local requested = payload.path or payload.root
	if requested and tostring(requested) ~= "" then
		local root = resolvePath(requested)
		return root and { root } or {}
	end
	local roots = {}
	for _, serviceName in ipairs({ "ReplicatedStorage", "StarterGui", "Workspace", "StarterPlayer", "ServerStorage" }) do
		local ok, service = pcall(function()
			return game:GetService(serviceName)
		end)
		if ok and service then table.insert(roots, service) end
	end
	return roots
end

function V43.getVfxTextureLibrary(payload)
	payload = payload or {}
	local maxNodes = tonumber(payload.maxNodes or 3500) or 3500
	local query = V43.lower(payload.query or "")
	local readMap = V43.assetReadMap()
	local byAsset = {}
	local assets = {}
	local categories = {}
	local scanned = 0
	local truncated = false
	local function addAsset(instance, propertyName, rawValue)
		local normalized = V39.assetId(rawValue)
		if not normalized then return end
		local haystack = V43.lower(safeFullName(instance) .. " " .. instance.ClassName .. " " .. propertyName .. " " .. normalized)
		if query ~= "" and not string.find(haystack, query, 1, true) then return end
		local category = V43.assetCategory(instance, propertyName, normalized)
		local entry = byAsset[normalized]
		if not entry then
			entry = { assetId = normalized, category = category, usageCount = 0, usages = {}, categories = {}, scoreHints = {} }
			byAsset[normalized] = entry
			table.insert(assets, entry)
		end
		entry.usageCount += 1
		entry.categories[category] = true
		categories[category] = (categories[category] or 0) + 1
		if #entry.usages < 25 then
			table.insert(entry.usages, { path = safeFullName(instance), name = instance.Name, className = instance.ClassName, property = propertyName, category = category })
		end
	end
	local function visit(instance)
		if scanned >= maxNodes then truncated = true; return end
		scanned += 1
		for _, propertyName in ipairs(readMap[instance.ClassName] or {}) do
			local ok, value = pcall(function()
				return instance[propertyName]
			end)
			if ok then addAsset(instance, propertyName, value) end
		end
		for _, child in ipairs(instance:GetChildren()) do
			visit(child)
			if truncated then break end
		end
	end
	for _, root in ipairs(V43.textureRoots(payload)) do
		visit(root)
		if truncated then break end
	end
	table.sort(assets, function(a, b)
		if a.usageCount == b.usageCount then
			return tostring(a.assetId) < tostring(b.assetId)
		end
		return a.usageCount > b.usageCount
	end)
	local result = {
		at = isoNow(),
		version = VERSION,
		root = payload.path or payload.root or "ReplicatedStorage/StarterGui/Workspace",
		assetCount = #assets,
		categories = categories,
		scanned = scanned,
		truncated = truncated,
		assets = assets,
		nextCommand = "tools\\bridge.cmd vfx recommend-textures \"purple hand aura\"",
	}
	V43.last.textureLibrary = result
	return result
end

function V43.copyAsset(asset)
	local clone = {}
	for key, value in pairs(asset or {}) do
		clone[key] = value
	end
	return clone
end

function V43.scoreTexture(asset, intent, effectType, styleId)
	local score = tonumber(asset.usageCount or 0) or 0
	local text = V43.lower(intent .. " " .. effectType .. " " .. styleId)
	local categories = asset.categories or {}
	local function has(category)
		return categories[category] == true or asset.category == category
	end
	if string.find(text, "spark", 1, true) or effectType == "lightning" then if has("spark") or has("glow") then score += 20 end end
	if string.find(text, "smoke", 1, true) or effectType == "smoke" then if has("smoke") or has("noise") then score += 20 end end
	if effectType == "dust" then if has("dust") or has("smoke") then score += 20 end end
	if effectType == "slashTrail" then if has("slash") or has("trail") then score += 22 end end
	if effectType == "magicCircle" or effectType == "portal" or effectType == "shield" or effectType == "shockwave" then if has("circle") or has("glow") then score += 18 end end
	if effectType == "pickup" or effectType == "aura" or effectType == "handCharge" or effectType == "weaponEnchant" then if has("glow") or has("spark") then score += 18 end end
	if has("sound") and (string.find(text, "sound", 1, true) or effectType == "explosion" or effectType == "hitBurst") then score += 12 end
	return score
end

function V43.getVfxTextureRecommendations(payload)
	payload = payload or {}
	local intent = tostring(payload.intent or payload.text or payload.prompt or payload.query or "")
	local effectType = tostring(payload.effectType or V43.inferEffectType(intent))
	local styleId = tostring(payload.style or V43.inferStyle(intent))
	local library = payload.library or V43.getVfxTextureLibrary({ path = payload.path or payload.root or "ReplicatedStorage", maxNodes = payload.maxNodes or 3500 })
	local ranked = {}
	for _, asset in ipairs(library.assets or {}) do
		local clone = V43.copyAsset(asset)
		clone.score = V43.scoreTexture(asset, intent, effectType, styleId)
		table.insert(ranked, clone)
	end
	table.sort(ranked, function(a, b)
		if a.score == b.score then return tostring(a.assetId) < tostring(b.assetId) end
		return a.score > b.score
	end)
	local top = {}
	for index, asset in ipairs(ranked) do
		if index > tonumber(payload.limit or 12) then break end
		table.insert(top, asset)
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		intent = intent,
		effectType = effectType,
		style = styleId,
		libraryAssetCount = library.assetCount or #ranked,
		top = top,
		nextCommand = "tools\\bridge.cmd vfx plan \"" .. V9.trimText(intent ~= "" and intent or "purple hand aura", 80) .. "\"",
	}
	V43.last.textureRecommendations = result
	return result
end

function V43.targetRole(instance)
	local name = V43.lower(instance and instance.Name or "")
	if string.find(name, "right", 1, true) and (string.find(name, "hand", 1, true) or string.find(name, "arm", 1, true)) then return "rightHand" end
	if string.find(name, "left", 1, true) and (string.find(name, "hand", 1, true) or string.find(name, "arm", 1, true)) then return "leftHand" end
	if string.find(name, "hand", 1, true) then return "hand" end
	if string.find(name, "handle", 1, true) or string.find(name, "weapon", 1, true) or string.find(name, "blade", 1, true) then return "weapon" end
	if string.find(name, "root", 1, true) or string.find(name, "torso", 1, true) then return "body" end
	if instance and instance:IsA("Attachment") then return "attachment" end
	if instance and instance:IsA("BasePart") then return "worldPart" end
	return "object"
end

function V43.getVfxAttachmentTargets(payload)
	payload = payload or {}
	local root = resolvePath(payload.path or payload.root or payload.rigPath or payload.target or "")
	local targets = {}
	local seen = {}
	local function add(instance, role, reason, score)
		if not instance then return end
		local path = safeFullName(instance)
		local key = path .. ":" .. tostring(role or "")
		if seen[key] then return end
		seen[key] = true
		table.insert(targets, {
			id = "vfxTarget:" .. tostring(getInstanceId(instance)) .. ":" .. tostring(role or V43.targetRole(instance)),
			path = path,
			name = instance.Name,
			className = instance.ClassName,
			role = role or V43.targetRole(instance),
			kind = instance:IsA("Attachment") and "attachment" or (instance:IsA("BasePart") and "part" or instance.ClassName),
			reason = reason,
			score = score or 50,
		})
	end
	if not root then
		for _, item in ipairs(Selection:Get()) do
			add(item, V43.targetRole(item), "current Studio selection", 80)
		end
	end
	root = root or Selection:Get()[1] or workspace
	add(root, V43.targetRole(root), "requested root", 60)
	local scanned = 0
	local maxNodes = tonumber(payload.maxNodes or 1800) or 1800
	local function visit(instance)
		if scanned >= maxNodes then return end
		scanned += 1
		if instance:IsA("Attachment") then
			add(instance, V43.targetRole(instance), "attachment", 85)
		elseif instance:IsA("Tool") then
			add(instance, "tool", "tool container", 70)
			add(instance:FindFirstChild("Handle"), "weapon", "tool handle", 90)
		elseif instance:IsA("BasePart") then
			local role = V43.targetRole(instance)
			if role ~= "worldPart" or string.find(V43.lower(instance.Name), "part", 1, true) == nil then
				add(instance, role, "named part", role == "weapon" and 88 or 75)
			end
		end
		for _, child in ipairs(instance:GetChildren()) do
			visit(child)
			if scanned >= maxNodes then break end
		end
	end
	visit(root)
	local stageAttachment = resolvePath("Workspace.CodexVfxPreviewStage.NeutralBase.PreviewAttachment")
	if stageAttachment then add(stageAttachment, "previewStage", "Codex preview stage", 95) end
	table.sort(targets, function(a, b)
		if a.score == b.score then return tostring(a.path) < tostring(b.path) end
		return a.score > b.score
	end)
	local result = {
		at = isoNow(),
		version = VERSION,
		root = root and safeFullName(root) or nil,
		count = #targets,
		targets = targets,
		recommended = targets[1],
		nextCommand = targets[1] and ("tools\\bridge.cmd vfx attach <presetPath> \"" .. targets[1].path .. "\"") or "tools\\bridge.cmd vfx stage Workspace",
	}
	V43.last.targets = result
	return result
end

function V43.textureFor(recommendations, categories)
	for _, category in ipairs(categories or {}) do
		for _, asset in ipairs(recommendations.top or {}) do
			if asset.category == category or (asset.categories and asset.categories[category]) then
				return asset.assetId
			end
		end
	end
	local top = recommendations.top and recommendations.top[1]
	return top and top.assetId or nil
end

function V43.baseProperties(styleId, textureId)
	local palette = V43.palette(styleId)
	local props = {
		Enabled = false,
		Rate = 55,
		Lifetime = V43.numberRange(0.45, 0.9),
		Speed = V43.numberRange(4, 10),
		SpreadAngle = V43.v2(360, 360),
		Size = V43.numberSequence({ { 0, 0.25 }, { 0.3, 1.4 }, { 1, 0.15 } }),
		Transparency = V43.numberSequence({ { 0, 0.15 }, { 0.65, 0.25 }, { 1, 1 } }),
		Color = V43.colorSequence({ { 0, palette[1] }, { 0.6, palette[2] }, { 1, palette[3] } }),
		LightEmission = 0.85,
		LightInfluence = 0.1,
		Acceleration = V43.v3(0, 7, 0),
		Drag = 2,
		MaxParticles = 220,
	}
	if textureId then props.Texture = textureId end
	return props
end

function V43.intentName(intent, effectType, styleId)
	local text = tostring(intent or "")
	local words = {}
	for word in string.gmatch(text, "[%w]+") do
		table.insert(words, word)
		if #words >= 5 then break end
	end
	local base = #words > 0 and table.concat(words, "_") or (styleId .. "_" .. effectType)
	return V39.safeName("Codex_" .. base, "CodexVfxPreset")
end

function V43.timeline(effectType)
	local timeline = {
		{ time = 0, marker = "Anticipation", action = "soft pre-glow / target highlight" },
		{ time = 0.18, marker = "ChargeStart", action = "start aura or charge particles" },
		{ time = 0.48, marker = "Fire", action = "launch/emit main burst" },
		{ time = 0.62, marker = "VFXBurst", action = "peak visual intensity" },
		{ time = 0.72, marker = "Impact", action = "impact flash, sparks, sound cue" },
		{ time = 1.05, marker = "Recovery", action = "fade and cleanup" },
	}
	if effectType == "ambientLoop" or effectType == "aura" or effectType == "weaponEnchant" then
		timeline = {
			{ time = 0, marker = "LoopStart", action = "enable sustained particles and glow" },
			{ time = 0.45, marker = "Pulse", action = "soft pulse accent" },
			{ time = 1.2, marker = "LoopBlend", action = "return to base loop" },
		}
	elseif effectType == "hitBurst" or effectType == "explosion" or effectType == "shockwave" then
		timeline = {
			{ time = 0, marker = "Impact", action = "instant burst and flash" },
			{ time = 0.08, marker = "VFXBurst", action = "peak particle emission" },
			{ time = 0.18, marker = "SoundCue", action = "impact sound window" },
			{ time = 0.55, marker = "Recovery", action = "smoke and fade" },
		}
	end
	return timeline
end

function V43.layerSet(intent, effectType, styleId, recommendations, name)
	local palette = V43.palette(styleId)
	local sparkTexture = V43.textureFor(recommendations, { "spark", "glow", "texture" })
	local smokeTexture = V43.textureFor(recommendations, { "smoke", "dust", "noise", "texture" })
	local slashTexture = V43.textureFor(recommendations, { "slash", "glow", "texture" })
	local circleTexture = V43.textureFor(recommendations, { "circle", "glow", "texture" })
	local soundId = V43.textureFor(recommendations, { "sound" })
	local stageAnchor = "Workspace.CodexVfxPreviewStage." .. name .. "Anchor"
	local layers = {}
	local function add(className, layerName, properties, parentPath)
		table.insert(layers, { className = className, name = layerName, parentPath = parentPath, properties = properties or {} })
	end
	add("ParticleEmitter", "CoreMotes", V43.baseProperties(styleId, sparkTexture))
	add("PointLight", "PulseLight", { Enabled = true, Brightness = 4, Range = 20, Color = palette[1], Shadows = false })
	add("Highlight", "TargetHighlight", { Enabled = true, FillColor = palette[1], FillTransparency = 0.75, OutlineColor = palette[2], OutlineTransparency = 0.25 })
	if effectType == "projectile" or effectType == "beam" or effectType == "handCharge" then
		add("ParticleEmitter", "ChargeSparks", V43.baseProperties(styleId, sparkTexture))
		layers[#layers].properties.Rate = 120
		layers[#layers].properties.Speed = V43.numberRange(1, 4)
		layers[#layers].properties.Acceleration = V43.v3(0, 2, 0)
		add("ParticleEmitter", "LaunchBurst", V43.baseProperties(styleId, sparkTexture))
		layers[#layers].properties.Rate = 0
		layers[#layers].properties.MaxParticles = 120
	elseif effectType == "slashTrail" or effectType == "weaponEnchant" then
		add("ParticleEmitter", "SlashSparks", V43.baseProperties(styleId, slashTexture))
		layers[#layers].properties.Rate = 95
		layers[#layers].properties.Lifetime = V43.numberRange(0.18, 0.45)
		add("Part", "NeonSlashArc", { Anchored = true, CanCollide = false, CanQuery = false, Shape = "Cylinder", Size = V43.v3(7, 0.12, 0.8), Position = V43.v3(0, 7.2, 0), Color = palette[1], Material = "Neon", Transparency = 0.35 }, stageAnchor)
	elseif effectType == "explosion" or effectType == "hitBurst" or effectType == "shockwave" then
		add("ParticleEmitter", "ImpactSparks", V43.baseProperties(styleId, sparkTexture))
		layers[#layers].properties.Rate = 0
		layers[#layers].properties.MaxParticles = 350
		add("ParticleEmitter", "SmokeFade", V43.baseProperties(styleId, smokeTexture))
		layers[#layers].properties.Rate = 0
		layers[#layers].properties.Color = V43.colorSequence({ { 0, palette[2] }, { 1, V43.color(80, 80, 90) } })
		layers[#layers].properties.Lifetime = V43.numberRange(0.8, 1.8)
		add("Part", "ShockwaveRing", { Anchored = true, CanCollide = false, CanQuery = false, Shape = "Cylinder", Size = V43.v3(8, 0.12, 8), Position = V43.v3(0, 6, 0), Color = palette[1], Material = "Neon", Transparency = 0.5 }, stageAnchor)
	elseif effectType == "smoke" or effectType == "dust" or effectType == "wind" then
		add("ParticleEmitter", "Wisps", V43.baseProperties(styleId, smokeTexture))
		layers[#layers].properties.Rate = 90
		layers[#layers].properties.Speed = V43.numberRange(2, 8)
		layers[#layers].properties.Acceleration = V43.v3(4, 2, 0)
	elseif effectType == "magicCircle" or effectType == "portal" or effectType == "shield" then
		add("ParticleEmitter", "GlyphMotes", V43.baseProperties(styleId, circleTexture))
		layers[#layers].properties.Rate = 80
		add("Part", "MagicRing", { Anchored = true, CanCollide = false, CanQuery = false, Shape = "Cylinder", Size = V43.v3(10, 0.08, 10), Position = V43.v3(0, 5.8, 0), Color = palette[1], Material = "Neon", Transparency = 0.45 }, stageAnchor)
	elseif effectType == "healing" or effectType == "pickup" then
		add("ParticleEmitter", "RisingBlessing", V43.baseProperties(styleId, sparkTexture))
		layers[#layers].properties.Rate = 85
		layers[#layers].properties.Acceleration = V43.v3(0, 12, 0)
		layers[#layers].properties.Speed = V43.numberRange(1, 4)
	end
	if soundId then
		add("Sound", "SoundCue", { SoundId = soundId, Volume = 0.45, PlaybackSpeed = 1, Looped = effectType == "ambientLoop" })
	end
	return layers
end

function V43.composePreset(payload)
	payload = payload or {}
	local intent = tostring(payload.intent or payload.text or payload.prompt or payload.description or "beautiful arcane aura")
	local effectType = tostring(payload.effectType or V43.inferEffectType(intent))
	local styleId = tostring(payload.style or V43.inferStyle(intent))
	local name = V39.safeName(payload.name or V43.intentName(intent, effectType, styleId), "CodexVfxPreset")
	local recommendations = V43.getVfxTextureRecommendations({ intent = intent, path = payload.assetRoot or payload.textureRoot or "ReplicatedStorage", maxNodes = payload.maxNodes or 2500 })
	local target = payload.target or payload.targetPath or payload.attachmentTarget or "Workspace.CodexVfxPreviewStage.NeutralBase.PreviewAttachment"
	local layers = V43.layerSet(intent, effectType, styleId, recommendations, name)
	local preset = {
		name = name,
		version = VERSION,
		intent = intent,
		effectType = effectType,
		style = styleId,
		palette = V43.palette(styleId),
		target = target,
		layers = layers,
		timeline = V43.timeline(effectType),
		textureChoices = recommendations.top,
		qualityTier = tostring(payload.qualityTier or "balanced"),
		cleanup = { mode = "timed", lifetimeSeconds = tonumber(payload.lifetimeSeconds or 4) or 4, removeOnlyCodexRuntime = true },
		syncMarkers = { "Anticipation", "ChargeStart", "Fire", "Impact", "VFXBurst", "SoundCue", "Recovery" },
	}
	return preset, { intent = intent, effectType = effectType, style = styleId, recommendations = recommendations }
end

function V43.runtimeAnimatorSource()
	return [==[
local TweenService = game:GetService("TweenService")
local module = {}

function module.Play(root, options)
	options = options or {}
	if not root then return { status = "notFound" } end
	local emitCount = tonumber(options.emitCount or 35) or 35
	local touched = { emitters = 0, sounds = 0, tweens = 0 }
	for _, item in ipairs(root:GetDescendants()) do
		if item:IsA("ParticleEmitter") then
			pcall(function() item:Emit(emitCount) end)
			touched.emitters += 1
		elseif item:IsA("Sound") then
			pcall(function() item:Play() end)
			touched.sounds += 1
		elseif item:IsA("BasePart") and item.Name:lower():find("ring", 1, true) then
			local startSize = item.Size
			local startTransparency = item.Transparency
			item.Transparency = math.min(startTransparency, 0.45)
			local tween = TweenService:Create(item, TweenInfo.new(0.55, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
				Size = startSize * 1.35,
				Transparency = 1,
			})
			tween:Play()
			touched.tweens += 1
			task.delay(0.7, function()
				if item then
					item.Size = startSize
					item.Transparency = startTransparency
				end
			end)
		end
	end
	return { status = "played", touched = touched }
end

return module
]==]
end

function V43.composerBlueprint(payload)
	payload = payload or {}
	local preset = payload.preset or payload.plan and payload.plan.preset or nil
	if not preset then
		preset = V43.composePreset(payload)
	end
	local blueprint = V39.presetBlueprint({ preset = preset })
	blueprint.source = "V43.applyVfxComposerPlan"
	local name = V39.safeName(preset.name, "CodexVfxPreset")
	local basePath = "ReplicatedStorage.CodexVfxWorkbench.Presets." .. name
	table.insert(blueprint.steps, V25.scriptWriteStep(basePath .. ".RuntimeAnimator", "ModuleScript", V43.runtimeAnimatorSource()))
	table.insert(blueprint.steps, V25.scriptWriteStep(basePath .. ".TimelineManifest", "ModuleScript", "return { json = " .. V8.luaString(HttpService:JSONEncode({
		name = name,
		intent = preset.intent,
		effectType = preset.effectType,
		timeline = preset.timeline,
		syncMarkers = preset.syncMarkers,
	})) .. " }\n"))
	return blueprint
end

function V43.getVfxIntentPlan(payload)
	local preset, meta = V43.composePreset(payload or {})
	local result = {
		at = isoNow(),
		version = VERSION,
		intent = preset.intent,
		effectType = preset.effectType,
		style = preset.style,
		palette = preset.palette,
		layerCount = #preset.layers,
		timeline = preset.timeline,
		textureRecommendations = meta.recommendations,
		target = preset.target,
		nextCommand = "tools\\bridge.cmd vfx generate \"" .. V9.trimText(preset.intent, 100) .. "\"",
	}
	V43.last.intentPlan = result
	return result
end

function V43.getVfxComposerPlan(payload)
	local preset, meta = V43.composePreset(payload or {})
	local blueprint = V43.composerBlueprint({ preset = preset })
	local audit = V43.getVfxQualityAudit({ preset = preset })
	local result = {
		at = isoNow(),
		version = VERSION,
		status = "planned",
		preset = preset,
		blueprint = blueprint,
		textureRecommendations = meta.recommendations,
		quality = audit,
		previewPlan = {
			stagePath = "Workspace.CodexVfxPreviewStage." .. V39.safeName(preset.name, "CodexVfxPreset") .. "Anchor",
			camera = "Frame the preview stage anchor from 18-26 studs away, slightly above the effect, with the primary color against a neutral background.",
			screenGuide = "Use tools\\bridge.cmd screen guide after generation to point the creator at the generated effect.",
			capture = "Best-effort: tools\\bridge.cmd vfx capture <generatedPresetPath>.",
		},
		nextCommand = "tools\\bridge.cmd vfx generate \"" .. V9.trimText(preset.intent, 100) .. "\"",
	}
	V43.last.composerPlan = result
	return result
end

function V43.generatedPresetPath(name)
	return "ReplicatedStorage.CodexVfxWorkbench.Presets." .. V39.safeName(name, "CodexVfxPreset")
end

function V43.getVfxQualityAudit(payload)
	payload = payload or {}
	local preset = payload.preset or payload.plan and payload.plan.preset or nil
	local score = 100
	local warnings = {}
	local strengths = {}
	local classCounts = {}
	local layerCount = 0
	if preset then
		layerCount = #(preset.layers or {})
		for _, layer in ipairs(preset.layers or {}) do
			classCounts[layer.className or layer.type or "Unknown"] = (classCounts[layer.className or layer.type or "Unknown"] or 0) + 1
		end
	else
		local path = tostring(payload.path or payload.target or payload.presetPath or "")
		local target = resolvePath(path)
		local report = target and V39.getVfxObjectReport({ path = path }) or nil
		if report then
			classCounts = report.classCounts or {}
			layerCount = report.vfxDescendantCount or 0
		end
	end
	local function has(className)
		return (classCounts[className] or 0) > 0
	end
	if layerCount < 3 then score -= 18; table.insert(warnings, "Layer count is low; professional VFX usually needs core, accent, light, and cleanup layers.") else table.insert(strengths, "Layered construction is present.") end
	if not has("ParticleEmitter") then score -= 20; table.insert(warnings, "No ParticleEmitter layer detected.") else table.insert(strengths, "Particle motion layer present.") end
	if not (has("PointLight") or has("SpotLight") or has("SurfaceLight") or has("Highlight")) then score -= 12; table.insert(warnings, "No lighting/highlight layer detected.") end
	if not (has("Part") or has("MeshPart") or has("Beam") or has("Trail")) then score -= 8; table.insert(warnings, "No shape/trail/geometry accent detected.") end
	if preset then
		if #(preset.timeline or {}) < 3 then score -= 10; table.insert(warnings, "Timeline markers are sparse.") end
		if #(preset.textureChoices or {}) == 0 then score -= 8; table.insert(warnings, "No reusable texture candidates were selected; generated preset will rely on geometry/light fallback.") end
		if not preset.cleanup then score -= 8; table.insert(warnings, "Cleanup behavior is not described.") end
	end
	local perf = V39.getVfxPerformanceAudit({ path = payload.perfRoot or "Workspace.CodexVfxPreviewStage" })
	if perf.score and perf.score < 75 then score -= 10; table.insert(warnings, "Preview/workspace VFX performance audit has warnings.") end
	local result = {
		at = isoNow(),
		version = VERSION,
		score = math.max(0, math.min(100, score)),
		layerCount = layerCount,
		classCounts = classCounts,
		strengths = strengths,
		warnings = warnings,
		performance = perf,
		nextCommand = score < 90 and "tools\\bridge.cmd vfx plan <intent>" or "tools\\bridge.cmd vfx play <presetPath>",
	}
	V43.last.qualityAudit = result
	return result
end

function V43.getVfxAnimationSyncPlan(payload)
	payload = payload or {}
	local animationPath = tostring(payload.animationPath or payload.animation or "")
	local timeline = animationPath ~= "" and V40.getAnimationTimelineManifest({ path = animationPath, animationPath = animationPath }) or nil
	local sync = {}
	for _, marker in ipairs((timeline and timeline.markers) or {}) do
		local name = tostring(marker.name or marker.marker or "")
		local lower = V43.lower(name)
		local action = "accent"
		if string.find(lower, "charge", 1, true) or string.find(lower, "anticipation", 1, true) then action = "enable charge/aura layers" end
		if string.find(lower, "fire", 1, true) or string.find(lower, "burst", 1, true) then action = "emit launch/burst particles" end
		if string.find(lower, "impact", 1, true) or string.find(lower, "damage", 1, true) then action = "play hit burst, sound, and shockwave" end
		if string.find(lower, "recovery", 1, true) then action = "fade and cleanup runtime layers" end
		table.insert(sync, { marker = name, time = marker.time, action = action })
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		animationPath = animationPath ~= "" and animationPath or nil,
		markerCount = #sync,
		sync = sync,
		nextCommand = "tools\\bridge.cmd vfx animate <presetPath> \"" .. (animationPath ~= "" and animationPath or "<animationPath>") .. "\"",
	}
	V43.last.syncPlan = result
	return result
end

function V43.getVfxDirectorReport(payload)
	payload = payload or {}
	local status = V39.getVfxPreviewStatus(payload)
	local library = V43.getVfxTextureLibrary({ path = payload.path or "ReplicatedStorage", maxNodes = 1500 })
	local performance = V39.getVfxPerformanceAudit({ path = payload.perfRoot or "Workspace" })
	local result = {
		at = isoNow(),
		version = VERSION,
		status = status,
		styleCatalog = V43.getVfxStyleCatalog(payload),
		textureLibrarySummary = { assetCount = library.assetCount, categories = library.categories, truncated = library.truncated },
		performance = performance,
		last = V43.last,
		recommended = {
			"tools\\bridge.cmd vfx plan \"heavy purple hand aura that charges then fires a projectile\"",
			"tools\\bridge.cmd vfx generate \"electric sword slash trail with hit sparks\"",
			"tools\\bridge.cmd vfx targets \"Workspace.Rig\"",
		},
		nextCommand = "tools\\bridge.cmd vfx plan \"heavy purple hand aura that charges then fires a projectile\"",
	}
	V43.last.director = result
	return result
end

function V43.generateVfxFromIntent(payload)
	local plan = V43.getVfxComposerPlan(payload or {})
	local result = applyBuildPlan({ blueprint = plan.blueprint })
	result.kind = "vfxComposerGenerate"
	result.presetPath = V43.generatedPresetPath(plan.preset.name)
	result.stagePath = "Workspace.CodexVfxPreviewStage." .. V39.safeName(plan.preset.name, "CodexVfxPreset") .. "Anchor"
	result.quality = plan.quality
	result.textureChoices = plan.preset.textureChoices
	result.nextCommand = "tools\\bridge.cmd vfx play \"" .. result.stagePath .. "\""
	V43.last.generated = result
	return result
end

function V43.applyVfxComposerPlan(payload)
	payload = payload or {}
	local plan = payload.plan or V43.getVfxComposerPlan(payload)
	local blueprint = payload.blueprint or plan.blueprint or V43.composerBlueprint({ preset = plan.preset })
	local result = applyBuildPlan({ blueprint = blueprint })
	result.kind = "vfxComposerPlan"
	result.presetPath = plan.preset and V43.generatedPresetPath(plan.preset.name) or nil
	result.quality = plan.preset and V43.getVfxQualityAudit({ preset = plan.preset }) or nil
	V43.last.appliedPlan = result
	return result
end

function V43.attachVfxPreset(payload)
	payload = payload or {}
	local presetPath = tostring(payload.presetPath or payload.preset or payload.path or "")
	local targetPath = tostring(payload.targetPath or payload.target or payload.attachmentTarget or "")
	if presetPath == "" or targetPath == "" then
		return { at = isoNow(), version = VERSION, status = "failed", error = "attachVfxPreset requires presetPath and targetPath." }
	end
	local presetName = V39.safeName(presetPath:match("([^%.]+)$") or "Preset", "Preset")
	local target = resolvePath(targetPath)
	if not target then
		return { at = isoNow(), version = VERSION, status = "notFound", error = "Target path was not found.", targetPath = targetPath }
	end
	local mountPath = targetPath .. ".CodexVfxMount_" .. presetName
	local className = target:IsA("BasePart") and "Attachment" or "Folder"
	local blueprint = {
		name = "Attach Codex VFX Preset",
		mode = "fullTrust",
		source = "attachVfxPreset",
		steps = {
			{ type = "ensureInstance", className = className, path = mountPath, properties = className == "Attachment" and { Position = V43.v3(0, 0, 0) } or {} },
			V25.scriptWriteStep(mountPath .. ".CodexVfxAttachmentManifest", "ModuleScript", "return { presetPath = " .. V8.luaString(presetPath) .. ", targetPath = " .. V8.luaString(targetPath) .. ", version = \"" .. VERSION .. "\", attachedAt = " .. V8.luaString(isoNow()) .. " }\n"),
		},
	}
	local result = applyBuildPlan({ blueprint = blueprint })
	result.kind = "vfxAttach"
	result.presetPath = presetPath
	result.targetPath = targetPath
	result.mountPath = mountPath
	result.nextCommand = "tools\\bridge.cmd vfx play \"" .. presetPath .. "\""
	V43.last.attached = result
	return result
end

function V43.animateVfxPreset(payload)
	payload = payload or {}
	local presetPath = tostring(payload.presetPath or payload.preset or payload.path or "")
	local animationPath = tostring(payload.animationPath or payload.animation or "")
	if presetPath == "" or animationPath == "" then
		return { at = isoNow(), version = VERSION, status = "failed", error = "animateVfxPreset requires presetPath and animationPath." }
	end
	local presetName = V39.safeName(presetPath:match("([^%.]+)$") or "Preset", "Preset")
	local syncPlan = V43.getVfxAnimationSyncPlan({ animationPath = animationPath })
	local syncPath = "ReplicatedStorage.CodexVfxWorkbench.Presets." .. presetName .. ".AnimationSync"
	local blueprint = {
		name = "Sync Codex VFX Preset To Animation",
		mode = "fullTrust",
		source = "animateVfxPreset",
		steps = {
			{ type = "ensureFolder", path = "ReplicatedStorage.CodexVfxWorkbench" },
			{ type = "ensureFolder", path = "ReplicatedStorage.CodexVfxWorkbench.Presets" },
			{ type = "ensureFolder", path = "ReplicatedStorage.CodexVfxWorkbench.Presets." .. presetName },
			V25.scriptWriteStep(syncPath, "ModuleScript", "return { version = \"" .. VERSION .. "\", presetPath = " .. V8.luaString(presetPath) .. ", animationPath = " .. V8.luaString(animationPath) .. ", json = " .. V8.luaString(HttpService:JSONEncode(syncPlan)) .. " }\n"),
		},
	}
	local result = applyBuildPlan({ blueprint = blueprint })
	result.kind = "vfxAnimationSync"
	result.syncPlan = syncPlan
	result.syncPath = syncPath
	V43.last.animated = result
	return result
end

function V43.applyVfxCleanup(payload)
	payload = payload or {}
	local name = tostring(payload.name or payload.presetName or "")
	local removed = {}
	local skipped = {}
	return withUndo("CodexVfxCleanup", function()
		local roots = {}
		if name ~= "" then
			table.insert(roots, "Workspace.CodexVfxPreviewStage." .. V39.safeName(name, name) .. "Anchor")
		else
			table.insert(roots, "Workspace.CodexVfxPreviewStage.CodexVfxRuntime")
		end
		for _, path in ipairs(roots) do
			local instance = resolvePath(path)
			if instance and string.find(safeFullName(instance), "Codex", 1, true) then
				local ok, err = pcall(function() instance:Destroy() end)
				if ok then table.insert(removed, path) else table.insert(skipped, { path = path, error = tostring(err) }) end
			else
				table.insert(skipped, { path = path, reason = "missing or not Codex-owned" })
			end
		end
		stateDirty = true
		local result = { at = isoNow(), version = VERSION, status = "cleaned", removed = removed, skipped = skipped, note = "Cleanup only removes Codex-owned runtime/preview objects." }
		V43.last.cleanup = result
		return result
	end)
end

-- V51 Pro VFX Art Director + PDS Kit Adapter
function V51.defaultKitRoot()
	local preferred = "Workspace.PDS' Particles & Models Kit"
	if resolvePath(preferred) then return preferred end
	for _, fallback in ipairs({ "ReplicatedStorage", "Workspace", "StarterGui" }) do
		if resolvePath(fallback) then return fallback end
	end
	return "Workspace"
end

