function V51.inferProEffectType(intent)
	local lower = V43.lower(intent)
	if lower:find("ultimate", 1, true) or lower:find("cinematic", 1, true) then return "ultimate" end
	if lower:find("hand", 1, true) and lower:find("charge", 1, true) then return "handCharge" end
	if lower:find("weapon", 1, true) or lower:find("blade", 1, true) or lower:find("sword", 1, true) then
		if lower:find("slash", 1, true) or lower:find("trail", 1, true) then return "slashTrail" end
		return "weaponEnchant"
	end
	return V43.inferEffectType(intent)
end

function V51.assetRolesFor(asset)
	local roles = {}
	local haystack = V43.lower(tostring(asset.assetId or "") .. " " .. tostring(asset.category or ""))
	for _, usage in ipairs(asset.usages or {}) do
		haystack ..= " " .. V43.lower((usage.path or "") .. " " .. (usage.name or "") .. " " .. (usage.className or "") .. " " .. (usage.property or "") .. " " .. (usage.category or ""))
	end
	local categories = asset.categories or {}
	for role, words in pairs(V51.roleKeywords()) do
		local matched = categories[role] == true or asset.category == role
		for _, word in ipairs(words) do
			if haystack:find(word, 1, true) then matched = true; break end
		end
		if matched then table.insert(roles, role) end
	end
	if #roles == 0 then
		if categories.mesh or asset.category == "mesh" then table.insert(roles, "meshCore") else table.insert(roles, "unknown") end
	end
	table.sort(roles)
	return roles
end

function V51.getVfxKitInventory(payload)
	payload = payload or {}
	local rootPath = tostring(payload.path or payload.root or V51.defaultKitRoot())
	local library = V43.getVfxTextureLibrary({ path = rootPath, maxNodes = payload.maxNodes or 6500 })
	local roles = {}
	local assets = {}
	for _, asset in ipairs(library.assets or {}) do
		local entry = V43.copyAsset(asset)
		entry.roles = V51.assetRolesFor(asset)
		for _, role in ipairs(entry.roles) do
			roles[role] = roles[role] or { count = 0, top = {} }
			roles[role].count += 1
			if #roles[role].top < 10 then table.insert(roles[role].top, { assetId = entry.assetId, usageCount = entry.usageCount, category = entry.category }) end
		end
		table.insert(assets, entry)
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		root = rootPath,
		assetCount = #assets,
		scanned = library.scanned,
		truncated = library.truncated,
		categories = library.categories,
		roles = roles,
		assets = assets,
		nextCommand = "tools\\bridge.cmd vfx kit-recommend \"purple hand beam\" \"" .. rootPath .. "\"",
	}
	V51.last.kitInventory = result
	return result
end

function V51.getVfxKitAssetRoles(payload)
	local inventory = V51.getVfxKitInventory(payload or {})
	local roleList = {}
	for role, value in pairs(inventory.roles or {}) do
		table.insert(roleList, { role = role, count = value.count, top = value.top })
	end
	table.sort(roleList, function(a, b)
		if a.count == b.count then return tostring(a.role) < tostring(b.role) end
		return a.count > b.count
	end)
	local result = {
		at = isoNow(),
		version = VERSION,
		root = inventory.root,
		roleCount = #roleList,
		roles = roleList,
		nextCommand = "tools\\bridge.cmd vfx kit-recommend \"dark purple impact burst\" \"" .. inventory.root .. "\"",
	}
	V51.last.kitRoles = result
	return result
end

function V51.scoreAssetForRole(asset, desiredRoles, intent)
	local score = tonumber(asset.usageCount or 0) or 0
	local roleSet = {}
	for _, role in ipairs(asset.roles or V51.assetRolesFor(asset)) do roleSet[role] = true end
	for _, role in ipairs(desiredRoles or {}) do
		if roleSet[role] then score += 45 end
	end
	local text = V43.lower(intent)
	for _, usage in ipairs(asset.usages or {}) do
		local haystack = V43.lower((usage.path or "") .. " " .. (usage.name or ""))
		for word in string.gmatch(text, "%w+") do
			if #word >= 4 and haystack:find(word, 1, true) then score += 4 end
		end
	end
	return score
end

function V51.getVfxKitRecommendations(payload)
	payload = payload or {}
	local intent = tostring(payload.intent or payload.query or payload.text or "pro aura")
	local rootPath = tostring(payload.path or payload.root or payload.assetRoot or V51.defaultKitRoot())
	local effectType = tostring(payload.effectType or V51.inferProEffectType(intent))
	local profile = V51.effectProfiles()[effectType] or V51.effectProfiles().aura
	local inventory = V51.getVfxKitInventory({ path = rootPath, maxNodes = payload.maxNodes or 6500 })
	local ranked = {}
	for _, asset in ipairs(inventory.assets or {}) do
		local copy = V43.copyAsset(asset)
		copy.roles = asset.roles or V51.assetRolesFor(asset)
		copy.proScore = V51.scoreAssetForRole(copy, profile.roles, intent)
		table.insert(ranked, copy)
	end
	table.sort(ranked, function(a, b)
		if a.proScore == b.proScore then return tostring(a.assetId) < tostring(b.assetId) end
		return a.proScore > b.proScore
	end)
	local top = {}
	for index, asset in ipairs(ranked) do
		if index > tonumber(payload.limit or 18) then break end
		table.insert(top, asset)
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		intent = intent,
		root = rootPath,
		effectType = effectType,
		desiredRoles = profile.roles,
		top = top,
		nextCommand = "tools\\bridge.cmd vfx pro-plan \"" .. V9.trimText(intent, 100) .. "\"",
	}
	V51.last.kitRecommendations = result
	return result
end

function V51.roleAsset(recommendations, role)
	for _, asset in ipairs((recommendations and recommendations.top) or {}) do
		for _, assetRole in ipairs(asset.roles or {}) do
			if assetRole == role then return asset.assetId end
		end
	end
	return nil
end

function V51.timingPlan(effectType, styleId)
	local profile = V51.effectProfiles()[effectType] or V51.effectProfiles().aura
	local phaseDurations = {
		anticipation = 0.18, buildup = 0.28, charge = 0.55, action = 0.2, release = 0.12,
		travel = 0.48, impact = 0.12, bloom = 0.32, residue = 0.8, recovery = 0.36,
		cleanup = 0.12, loop = 1.2, rise = 0.5, pull = 0.7, fade = 0.45, variation = 1.0,
	}
	local time = 0
	local phases = {}
	for _, phase in ipairs(profile.phases or { "buildup", "bloom", "residue" }) do
		local duration = phaseDurations[phase] or 0.3
		table.insert(phases, {
			id = phase,
			start = time,
			finish = time + duration,
			duration = duration,
			marker = phase:sub(1, 1):upper() .. phase:sub(2),
		})
		time += duration
	end
	return {
		effectType = effectType,
		style = styleId,
		totalDuration = time,
		phases = phases,
		markers = { "Anticipation", "ChargeStart", "Release", "Travel", "Impact", "Bloom", "Residue", "Recovery", "Cleanup" },
	}
end

function V51.proLayerSet(intent, effectType, styleId, recommendations, name)
	local palette = V43.palette(styleId)
	local layers = {}
	local function add(className, layerName, properties, parentPath, timing, role)
		properties = properties or {}
		table.insert(layers, {
			className = className,
			name = layerName,
			parentPath = parentPath,
			properties = properties,
			timing = timing,
			role = role,
			proLayer = true,
		})
	end
	local spark = V51.roleAsset(recommendations, "spark") or V51.roleAsset(recommendations, "glow")
	local glow = V51.roleAsset(recommendations, "glow") or spark
	local smoke = V51.roleAsset(recommendations, "smoke") or V51.roleAsset(recommendations, "fog") or V51.roleAsset(recommendations, "dust")
	local slash = V51.roleAsset(recommendations, "slash") or V51.roleAsset(recommendations, "trail") or glow
	local ring = V51.roleAsset(recommendations, "ring") or glow
	local coreMesh = V51.roleAsset(recommendations, "projectileCore") or V51.roleAsset(recommendations, "meshCore")
	local sound = V51.roleAsset(recommendations, "sound")
	local base = V43.baseProperties(styleId, glow or spark)
	base.Rate = 35
	base.Lifetime = V43.numberRange(0.35, 0.9)
	base.Speed = V43.numberRange(1.5, 5)
	add("ParticleEmitter", "01_CoreGlow_Motes", base, nil, { phase = "buildup", start = 0, finish = 0.9, emit = 18 }, "glow")
	add("PointLight", "02_KeyLight_Pulse", { Brightness = 2.5, Range = 14, Color = palette[1], Shadows = false }, nil, { phase = "charge", start = 0.08, finish = 0.95 }, "glow")
	if effectType == "beam" or effectType == "projectile" or effectType == "handCharge" or effectType == "ultimate" then
		local chargeProps = V43.baseProperties(styleId, spark or glow)
		chargeProps.Rate = 120
		chargeProps.Speed = V43.numberRange(0.5, 2.4)
		chargeProps.Lifetime = V43.numberRange(0.18, 0.55)
		chargeProps.Size = V43.numberSequence({ { 0, 0.18 }, { 0.45, 0.65 }, { 1, 0 } })
		add("ParticleEmitter", "10_Charge_OrbitSparks", chargeProps, nil, { phase = "charge", start = 0.1, finish = 0.65, emit = 42 }, "spark")
	end
	if effectType == "slashTrail" or effectType == "weaponEnchant" then
		local slashProps = V43.baseProperties(styleId, slash)
		slashProps.Rate = 180
		slashProps.Lifetime = V43.numberRange(0.12, 0.32)
		slashProps.Speed = V43.numberRange(8, 18)
		add("ParticleEmitter", "20_Slash_Streaks", slashProps, nil, { phase = "action", start = 0.18, finish = 0.4, emit = 55 }, "slash")
		add("Trail", "21_Blade_TrailHint", { Color = V43.colorSequence({ { 0, palette[1] }, { 1, palette[3] } }), Lifetime = 0.22, Transparency = V43.numberSequence({ { 0, 0.2 }, { 1, 1 } }) }, nil, { phase = "action" }, "trail")
	end
	if effectType == "beam" or effectType == "ultimate" then
		add("Beam", "30_Beam_CoreLine", { Texture = glow or "", Width0 = 1.8, Width1 = 1.1, Brightness = 3, Color = V43.colorSequence({ { 0, palette[1] }, { 0.5, palette[2] }, { 1, palette[3] } }), Transparency = V43.numberSequence({ { 0, 0.05 }, { 1, 0.35 } }) }, nil, { phase = "release", start = 0.62, finish = 1.05 }, "beam")
	end
	if effectType == "projectile" or effectType == "ultimate" then
		add("MeshPart", "31_Projectile_CoreMesh", { Anchored = true, CanCollide = false, CanQuery = false, MeshId = coreMesh or "", Size = V43.v3(1.6, 1.6, 1.6), Position = V43.v3(0, 7.2, -6), Color = palette[1], Material = "Neon", Transparency = 0.12 }, nil, { phase = "travel", start = 0.65, finish = 1.2 }, "projectileCore")
	end
	if effectType == "explosion" or effectType == "hitBurst" or effectType == "beam" or effectType == "projectile" or effectType == "ultimate" then
		local impactProps = V43.baseProperties(styleId, spark or glow)
		impactProps.Rate = 0
		impactProps.Lifetime = V43.numberRange(0.25, 0.75)
		impactProps.Speed = V43.numberRange(14, 32)
		impactProps.Size = V43.numberSequence({ { 0, 0.28 }, { 0.2, 1.6 }, { 1, 0.08 } })
		add("ParticleEmitter", "40_Impact_SparkBurst", impactProps, nil, { phase = "impact", start = 1.05, finish = 1.32, emit = 85 }, "impact")
		add("Part", "41_Impact_ShockwaveRing", { Anchored = true, CanCollide = false, CanQuery = false, Shape = "Cylinder", Size = V43.v3(1.5, 0.08, 1.5), Position = V43.v3(0, 6, -8), Color = palette[2], Material = "Neon", Transparency = 0.45 }, nil, { phase = "impact", tween = "expandFade", start = 1.05, finish = 1.65 }, "ring")
	end
	if effectType == "wind" or effectType == "portal" or effectType == "shield" or effectType == "healing" then
		local swirlProps = V43.baseProperties(styleId, ring or smoke or glow)
		swirlProps.Rate = 70
		swirlProps.Lifetime = V43.numberRange(0.8, 1.8)
		swirlProps.Speed = V43.numberRange(2, 7)
		add("ParticleEmitter", "50_Swirl_MotionLayer", swirlProps, nil, { phase = "loop", start = 0.15, finish = 1.6, emit = 35 }, "swirl")
	end
	if smoke then
		local smokeProps = V43.baseProperties(styleId, smoke)
		smokeProps.Rate = 28
		smokeProps.Lifetime = V43.numberRange(0.9, 1.9)
		smokeProps.Speed = V43.numberRange(1, 5)
		smokeProps.Transparency = V43.numberSequence({ { 0, 0.55 }, { 0.5, 0.72 }, { 1, 1 } })
		add("ParticleEmitter", "90_Residue_SmokeFade", smokeProps, nil, { phase = "residue", start = 1.1, finish = 2.2, emit = 18 }, "smoke")
	end
	if sound then
		add("Sound", "95_SoundCue_Impact", { SoundId = sound, Volume = 0.5, PlaybackSpeed = 1, Looped = false }, nil, { phase = "impact", start = 1.05 }, "sound")
	end
	return layers
end

function V51.versionedName(baseName, payload)
	local base = V39.safeName(baseName, "ProVfxPreset")
	if payload and payload.versionName then return V39.safeName(payload.versionName, base .. "_v001") end
	local root = resolvePath("ReplicatedStorage.CodexVfxWorkbench.Presets")
	local highest = 0
	if root then
		for _, child in ipairs(root:GetChildren()) do
			local number = tostring(child.Name):match("^" .. base .. "_v(%d+)$")
			if number then highest = math.max(highest, tonumber(number) or 0) end
		end
	end
	return string.format("%s_v%03d", base, highest + 1)
end

function V51.composeProPreset(payload)
	payload = payload or {}
	local intent = tostring(payload.intent or payload.text or payload.prompt or "professional arcane aura")
	local effectType = tostring(payload.effectType or V51.inferProEffectType(intent))
	local styleId = tostring(payload.style or V43.inferStyle(intent))
	local rootPath = tostring(payload.assetRoot or payload.kitRoot or payload.textureRoot or V51.defaultKitRoot())
	local baseName = payload.name or V43.intentName(intent, effectType, styleId)
	local name = V51.versionedName(baseName, payload)
	local recommendations = V51.getVfxKitRecommendations({ intent = intent, path = rootPath, effectType = effectType, maxNodes = payload.maxNodes or 6500, limit = payload.limit or 18 })
	local timing = V51.timingPlan(effectType, styleId)
	local layers = V51.proLayerSet(intent, effectType, styleId, recommendations, name)
	local preset = {
		name = name,
		version = VERSION,
		authoring = "V51 Pro VFX Art Director",
		intent = intent,
		effectType = effectType,
		style = styleId,
		palette = V43.palette(styleId),
		target = payload.target or payload.targetPath or payload.attachmentTarget or "Workspace.CodexVfxPreviewStage.NeutralBase.PreviewAttachment",
		layers = layers,
		timeline = timing.phases,
		timing = timing,
		textureChoices = recommendations.top,
		assetRoleMap = { root = rootPath, desiredRoles = recommendations.desiredRoles, chosen = recommendations.top },
		qualityTier = tostring(payload.qualityTier or "pro-balanced"),
		cleanup = { mode = "timed", lifetimeSeconds = tonumber(payload.lifetimeSeconds or math.max(3, timing.totalDuration + 1)) or 4, removeOnlyCodexRuntime = true },
		syncMarkers = timing.markers,
	}
	return preset, { recommendations = recommendations, timing = timing, root = rootPath }
end

function V51.proBlueprint(payload)
	payload = payload or {}
	local preset = payload.preset or payload.plan and payload.plan.preset or nil
	local meta = payload.meta
	if not preset then
		preset, meta = V51.composeProPreset(payload)
	end
	meta = meta or { timing = preset.timing, recommendations = { top = preset.textureChoices } }
	local blueprint = V39.presetBlueprint({ preset = preset })
	blueprint.source = "V51.applyProVfxPlan"
	local basePath = V43.generatedPresetPath(preset.name)
	local audit = V51.getProVfxQualityAudit({ preset = preset, skipPerf = true })
	table.insert(blueprint.steps, V25.scriptWriteStep(basePath .. ".ProVfxManifest", "ModuleScript", "return { json = " .. V8.luaString(HttpService:JSONEncode({
		name = preset.name,
		version = VERSION,
		intent = preset.intent,
		effectType = preset.effectType,
		style = preset.style,
		qualityTier = preset.qualityTier,
		cleanup = preset.cleanup,
	})) .. " }\n"))
	table.insert(blueprint.steps, V25.scriptWriteStep(basePath .. ".AssetRoleMap", "ModuleScript", "return { json = " .. V8.luaString(HttpService:JSONEncode(preset.assetRoleMap or {})) .. " }\n"))
	table.insert(blueprint.steps, V25.scriptWriteStep(basePath .. ".TimingManifest", "ModuleScript", "return { json = " .. V8.luaString(HttpService:JSONEncode(meta.timing or preset.timing or {})) .. " }\n"))
	table.insert(blueprint.steps, V25.scriptWriteStep(basePath .. ".QualityAudit", "ModuleScript", "return { json = " .. V8.luaString(HttpService:JSONEncode(audit)) .. " }\n"))
	table.insert(blueprint.steps, V25.scriptWriteStep(basePath .. ".SourceIntent", "ModuleScript", "return { intent = " .. V8.luaString(preset.intent) .. ", generatedAt = " .. V8.luaString(isoNow()) .. ", version = " .. V8.luaString(VERSION) .. " }\n"))
	table.insert(blueprint.steps, V25.scriptWriteStep(basePath .. ".RuntimeAnimator", "ModuleScript", V43.runtimeAnimatorSource()))
	return blueprint
end

