function V51.getProVfxQualityAudit(payload)
	payload = payload or {}
	local preset = payload.preset or payload.plan and payload.plan.preset
	local base = V43.getVfxQualityAudit({ preset = preset, path = payload.path or payload.presetPath, perfRoot = payload.perfRoot or "Workspace.CodexVfxPreviewStage" })
	local score = tonumber(base.score or 0) or 0
	local warnings = {}
	local strengths = {}
	local layerCount = tonumber(base.layerCount or 0) or 0
	if preset then
		if #(preset.textureChoices or {}) >= 4 then score += 6; table.insert(strengths, "PDS/kit texture choices are present.") else score -= 10; table.insert(warnings, "Few kit texture choices were selected.") end
		if preset.timing and #(preset.timing.phases or {}) >= 4 then score += 8; table.insert(strengths, "Professional timing phases are mapped.") else score -= 12; table.insert(warnings, "Timing phases are sparse.") end
		if layerCount >= 7 then score += 8; table.insert(strengths, "Layer count supports pro readability.") else score -= 8; table.insert(warnings, "Add more support layers for pro quality.") end
		local roles = {}
		for _, layer in ipairs(preset.layers or {}) do roles[layer.role or "unknown"] = true end
		for _, needed in ipairs((V51.effectProfiles()[preset.effectType or "aura"] or V51.effectProfiles().aura).roles or {}) do
			if not roles[needed] then score -= 4; table.insert(warnings, "Missing role layer: " .. needed) end
		end
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		score = math.max(0, math.min(100, math.floor(score + 0.5))),
		baseScore = base.score,
		layerCount = layerCount,
		classCounts = base.classCounts,
		strengths = strengths,
		warnings = warnings,
		baseAudit = base,
		nextCommand = "tools\\bridge.cmd vfx polish <presetPath>",
	}
	V51.last.qualityAudit = result
	return result
end

function V51.getProVfxPolishPlan(payload)
	payload = payload or {}
	local path = tostring(payload.path or payload.presetPath or "")
	local target = path ~= "" and resolvePath(path) or nil
	local intent = tostring(payload.intent or (target and target.Name) or "polished pro VFX")
	local preset, meta = V51.composeProPreset({
		intent = intent .. " polished stronger readability timing impact",
		assetRoot = payload.assetRoot or V51.defaultKitRoot(),
		qualityTier = "pro-polished",
	})
	local result = {
		at = isoNow(),
		version = VERSION,
		sourcePresetPath = path ~= "" and path or nil,
		status = target and "ready" or "newVersionFromIntent",
		preset = preset,
		blueprint = V51.proBlueprint({ preset = preset, meta = meta }),
		quality = V51.getProVfxQualityAudit({ preset = preset }),
		nextCommand = "tools\\bridge.cmd vfx polish \"" .. (path ~= "" and path or "<presetPath>") .. "\"",
	}
	V51.last.polishPlan = result
	return result
end

function V51.getProVfxCompareReport(payload)
	payload = payload or {}
	local a = tostring(payload.presetA or payload.a or payload.pathA or "")
	local b = tostring(payload.presetB or payload.b or payload.pathB or "")
	local auditA = a ~= "" and V51.getProVfxQualityAudit({ path = a, presetPath = a }) or nil
	local auditB = b ~= "" and V51.getProVfxQualityAudit({ path = b, presetPath = b }) or nil
	local result = {
		at = isoNow(),
		version = VERSION,
		presetA = a ~= "" and a or nil,
		presetB = b ~= "" and b or nil,
		auditA = auditA,
		auditB = auditB,
		winner = auditA and auditB and ((auditB.score or 0) >= (auditA.score or 0) and "presetB" or "presetA") or "unknown",
		reason = auditA and auditB and "Higher pro quality score wins; inspect warnings for remaining polish." or "Both preset paths are needed for a direct comparison.",
		nextCommand = "tools\\bridge.cmd vfx audit <presetPath>",
	}
	V51.last.compare = result
	return result
end

