function V51.generateProVfxFromIntent(payload)
	payload = payload or {}
	local preset, meta = V51.composeProPreset(payload)
	local blueprint = V51.proBlueprint({ preset = preset, meta = meta })
	local result = applyBuildPlan({ blueprint = blueprint })
	result.kind = "proVfxGenerate"
	result.presetPath = V43.generatedPresetPath(preset.name)
	result.quality = V51.getProVfxQualityAudit({ preset = preset })
	result.timing = preset.timing
	result.textureChoices = preset.textureChoices
	result.nextCommand = "tools\\bridge.cmd vfx preview-pro \"" .. result.presetPath .. "\""
	V51.last.generated = result
	return result
end

function V51.applyProVfxPlan(payload)
	payload = payload or {}
	local plan = payload.plan or V51.getProVfxIntentPlan(payload)
	local preset, meta = V51.composeProPreset(payload)
	if payload.preset then preset = payload.preset end
	local blueprint = payload.blueprint or V51.proBlueprint({ preset = preset, meta = meta })
	local result = applyBuildPlan({ blueprint = blueprint })
	result.kind = "proVfxPlan"
	result.presetPath = V43.generatedPresetPath(preset.name)
	result.quality = V51.getProVfxQualityAudit({ preset = preset })
	V51.last.appliedPlan = result
	return result
end

function V51.polishVfxPreset(payload)
	local plan = V51.getProVfxPolishPlan(payload or {})
	local result = applyBuildPlan({ blueprint = plan.blueprint })
	result.kind = "proVfxPolish"
	result.sourcePresetPath = plan.sourcePresetPath
	result.presetPath = V43.generatedPresetPath(plan.preset.name)
	result.quality = plan.quality
	V51.last.polished = result
	return result
end

function V51.retimeVfxPreset(payload)
	payload = payload or {}
	local presetPath = tostring(payload.presetPath or payload.path or "")
	local scale = tonumber(payload.scale or payload.factor or 1) or 1
	local presetName = V39.safeName(presetPath:match("([^%.]+)$") or "Preset", "Preset")
	local manifestPath = "ReplicatedStorage.CodexVfxWorkbench.Presets." .. presetName .. ".RetimeManifest"
	local manifest = { presetPath = presetPath, scale = scale, retimedAt = isoNow(), version = VERSION }
	local blueprint = {
		name = "Retime Pro VFX Preset",
		mode = "fullTrust",
		source = "retimeVfxPreset",
		steps = {
			{ type = "ensureFolder", path = "ReplicatedStorage.CodexVfxWorkbench" },
			{ type = "ensureFolder", path = "ReplicatedStorage.CodexVfxWorkbench.Presets" },
			{ type = "ensureFolder", path = "ReplicatedStorage.CodexVfxWorkbench.Presets." .. presetName },
			V25.scriptWriteStep(manifestPath, "ModuleScript", "return { json = " .. V8.luaString(HttpService:JSONEncode(manifest)) .. " }\n"),
		},
	}
	local result = applyBuildPlan({ blueprint = blueprint })
	result.kind = "proVfxRetime"
	result.manifestPath = manifestPath
	result.scale = scale
	V51.last.retimed = result
	return result
end

