function V52.performanceBudgets()
	return {
		mobileLow = { label = "Low-end mobile", maxEmitters = 10, maxTotalRate = 420, maxEstimatedLiveParticles = 260, maxLights = 3, maxBeams = 4, maxTrails = 4, maxSounds = 3, maxRuntimeParts = 12 },
		mobileBalanced = { label = "Balanced mobile", maxEmitters = 16, maxTotalRate = 760, maxEstimatedLiveParticles = 520, maxLights = 5, maxBeams = 6, maxTrails = 6, maxSounds = 5, maxRuntimeParts = 22 },
		desktop = { label = "Desktop", maxEmitters = 28, maxTotalRate = 1500, maxEstimatedLiveParticles = 1100, maxLights = 8, maxBeams = 12, maxTrails = 10, maxSounds = 8, maxRuntimeParts = 42 },
		cinematic = { label = "Cinematic preview", maxEmitters = 44, maxTotalRate = 2600, maxEstimatedLiveParticles = 1900, maxLights = 12, maxBeams = 18, maxTrails = 16, maxSounds = 12, maxRuntimeParts = 70 },
	}
end

function V52.numberRangeMax(value)
	if typeof(value) == "NumberRange" then
		return value.Max
	end
	local ok, maxValue = pcall(function()
		return value.Max
	end)
	if ok and type(maxValue) == "number" then
		return maxValue
	end
	return 0
end

function V52.safeNumberProperty(instance, property, fallback)
	local ok, value = pcall(function()
		return instance[property]
	end)
	if ok and type(value) == "number" then return value end
	return fallback or 0
end

function V52.safeStringProperty(instance, property)
	local ok, value = pcall(function()
		return instance[property]
	end)
	if ok then return tostring(value or "") end
	return ""
end

function V52.scanVfxPath(path)
	local targetPath = tostring(path or "Workspace.CodexVfxPreviewStage")
	local target = resolvePath(targetPath)
	local stats = {
		at = isoNow(),
		version = VERSION,
		path = targetPath,
		exists = target ~= nil,
		classCounts = {},
		totalInstances = 0,
		particleEmitterCount = 0,
		totalRate = 0,
		estimatedLiveParticles = 0,
		lightCount = 0,
		beamCount = 0,
		trailCount = 0,
		soundCount = 0,
		runtimePartCount = 0,
		highRateEmitters = {},
		expensiveLights = {},
		textureIds = {},
		warnings = {},
	}
	if not target then
		table.insert(stats.warnings, "VFX path was not found.")
		return stats
	end
	local instances = { target }
	for _, descendant in ipairs(target:GetDescendants()) do
		table.insert(instances, descendant)
	end
	for _, instance in ipairs(instances) do
		stats.totalInstances += 1
		stats.classCounts[instance.ClassName] = (stats.classCounts[instance.ClassName] or 0) + 1
		if instance:IsA("ParticleEmitter") then
			stats.particleEmitterCount += 1
			local rate = V52.safeNumberProperty(instance, "Rate", 0)
			local lifetimeMax = 0
			pcall(function()
				lifetimeMax = V52.numberRangeMax(instance.Lifetime)
			end)
			local estimated = rate * math.max(0.05, lifetimeMax)
			stats.totalRate += rate
			stats.estimatedLiveParticles += estimated
			local texture = V52.safeStringProperty(instance, "Texture")
			if texture ~= "" then stats.textureIds[texture] = true end
			if rate >= 90 or estimated >= 120 then
				table.insert(stats.highRateEmitters, {
					path = safeFullName(instance),
					name = instance.Name,
					rate = rate,
					lifetimeMax = lifetimeMax,
					estimatedLiveParticles = math.floor(estimated + 0.5),
					texture = texture,
				})
			end
		elseif instance:IsA("PointLight") or instance:IsA("SpotLight") or instance:IsA("SurfaceLight") then
			stats.lightCount += 1
			local brightness = V52.safeNumberProperty(instance, "Brightness", 0)
			local range = V52.safeNumberProperty(instance, "Range", 0)
			if brightness >= 4 or range >= 28 then
				table.insert(stats.expensiveLights, { path = safeFullName(instance), className = instance.ClassName, brightness = brightness, range = range })
			end
		elseif instance:IsA("Beam") then
			stats.beamCount += 1
			local texture = V52.safeStringProperty(instance, "Texture")
			if texture ~= "" then stats.textureIds[texture] = true end
		elseif instance:IsA("Trail") then
			stats.trailCount += 1
			local texture = V52.safeStringProperty(instance, "Texture")
			if texture ~= "" then stats.textureIds[texture] = true end
		elseif instance:IsA("Sound") then
			stats.soundCount += 1
		elseif instance:IsA("BasePart") then
			stats.runtimePartCount += 1
		end
	end
	local textureList = {}
	for id in pairs(stats.textureIds) do table.insert(textureList, id) end
	table.sort(textureList)
	stats.textureIds = textureList
	stats.totalRate = math.floor(stats.totalRate + 0.5)
	stats.estimatedLiveParticles = math.floor(stats.estimatedLiveParticles + 0.5)
	return stats
end

function V52.compareToBudget(stats, tier)
	local budgets = V52.performanceBudgets()
	local budget = budgets[tier] or budgets.mobileBalanced
	local score = 100
	local warnings = {}
	local blockers = {}
	local function check(label, actual, limit, severity)
		if actual > limit then
			local over = actual - limit
			local message = label .. " exceeds " .. tostring(limit) .. " by " .. tostring(math.floor(over + 0.5)) .. "."
			if severity == "blocker" then
				table.insert(blockers, message)
				score -= 20
			else
				table.insert(warnings, message)
				score -= 10
			end
		end
	end
	check("Particle emitter count", stats.particleEmitterCount or 0, budget.maxEmitters, "warn")
	check("Total particle rate", stats.totalRate or 0, budget.maxTotalRate, "blocker")
	check("Estimated live particles", stats.estimatedLiveParticles or 0, budget.maxEstimatedLiveParticles, "warn")
	check("Light count", stats.lightCount or 0, budget.maxLights, "warn")
	check("Beam count", stats.beamCount or 0, budget.maxBeams, "warn")
	check("Trail count", stats.trailCount or 0, budget.maxTrails, "warn")
	check("Sound count", stats.soundCount or 0, budget.maxSounds, "warn")
	check("Runtime part count", stats.runtimePartCount or 0, budget.maxRuntimeParts, "warn")
	for _, emitter in ipairs(stats.highRateEmitters or {}) do
		table.insert(warnings, "High-rate emitter: " .. tostring(emitter.path) .. " at Rate " .. tostring(emitter.rate) .. ".")
		score -= 2
	end
	for _, light in ipairs(stats.expensiveLights or {}) do
		table.insert(warnings, "Expensive light: " .. tostring(light.path) .. " brightness/range " .. tostring(light.brightness) .. "/" .. tostring(light.range) .. ".")
		score -= 2
	end
	return {
		tier = tier,
		budget = budget,
		score = math.max(0, math.min(100, math.floor(score + 0.5))),
		warnings = warnings,
		blockers = blockers,
		status = #blockers > 0 and "overBudget" or (#warnings > 0 and "needsPolish" or "withinBudget"),
	}
end

function V52.getVfxPerformanceBudget(payload)
	payload = payload or {}
	local path = tostring(payload.path or payload.presetPath or payload.target or "Workspace.CodexVfxPreviewStage")
	local tier = tostring(payload.tier or payload.qualityTier or "mobileBalanced")
	local stats = V52.scanVfxPath(path)
	local budget = V52.compareToBudget(stats, tier)
	local result = {
		at = isoNow(),
		version = VERSION,
		path = path,
		tier = tier,
		stats = stats,
		budget = budget,
		budgets = V52.performanceBudgets(),
		nextCommand = budget.status == "withinBudget" and "tools\\bridge.cmd vfx audit <presetPath>" or ("tools\\bridge.cmd vfx optimize \"" .. path .. "\" " .. tier),
	}
	V52.last.budget = result
	return result
end

function V52.optimizationSteps(path, stats, budget)
	local steps = {}
	local notes = {}
	local tierBudget = budget.budget or V52.performanceBudgets().mobileBalanced
	local rateScale = 1
	if (stats.totalRate or 0) > tierBudget.maxTotalRate and (stats.totalRate or 0) > 0 then
		rateScale = math.max(0.25, tierBudget.maxTotalRate / stats.totalRate)
	end
	for _, emitter in ipairs(stats.highRateEmitters or {}) do
		if string.find(emitter.path or "", "Codex", 1, true) then
			local newRate = math.max(1, math.floor((emitter.rate or 0) * rateScale + 0.5))
			table.insert(steps, { type = "setProperties", path = emitter.path, properties = { Rate = newRate } })
			table.insert(notes, "Reduce " .. tostring(emitter.path) .. " Rate to " .. tostring(newRate) .. ".")
		else
			table.insert(notes, "Skipped non-Codex emitter " .. tostring(emitter.path) .. ".")
		end
	end
	for _, light in ipairs(stats.expensiveLights or {}) do
		if string.find(light.path or "", "Codex", 1, true) then
			table.insert(steps, { type = "setProperties", path = light.path, properties = { Brightness = math.min(3, light.brightness or 3), Range = math.min(24, light.range or 24) } })
			table.insert(notes, "Clamp " .. tostring(light.path) .. " brightness/range for mobile readability.")
		else
			table.insert(notes, "Skipped non-Codex light " .. tostring(light.path) .. ".")
		end
	end
	local presetName = V39.safeName(path:match("([^%.]+)$") or "Preset", "Preset")
	local manifestPath = "ReplicatedStorage.CodexVfxWorkbench.Presets." .. presetName .. ".PerformanceBudget"
	table.insert(steps, { type = "ensureFolder", path = "ReplicatedStorage.CodexVfxWorkbench" })
	table.insert(steps, { type = "ensureFolder", path = "ReplicatedStorage.CodexVfxWorkbench.Presets" })
	table.insert(steps, { type = "ensureFolder", path = "ReplicatedStorage.CodexVfxWorkbench.Presets." .. presetName })
	table.insert(steps, V25.scriptWriteStep(manifestPath, "ModuleScript", "return { json = " .. V8.luaString(HttpService:JSONEncode({ version = VERSION, path = path, budget = budget, stats = stats, optimizedAt = isoNow() })) .. " }\n"))
	return steps, notes, manifestPath
end

function V52.getProVfxOptimizationPlan(payload)
	payload = payload or {}
	local path = tostring(payload.path or payload.presetPath or payload.target or "Workspace.CodexVfxPreviewStage")
	local tier = tostring(payload.tier or payload.qualityTier or "mobileBalanced")
	local budgetReport = V52.getVfxPerformanceBudget({ path = path, tier = tier })
	local steps, notes, manifestPath = V52.optimizationSteps(path, budgetReport.stats, budgetReport.budget)
	local blueprint = {
		name = "Optimize Pro VFX Budget",
		mode = "fullTrust",
		source = "V52.optimizeVfxPreset",
		steps = steps,
	}
	local result = {
		at = isoNow(),
		version = VERSION,
		path = path,
		tier = tier,
		status = budgetReport.budget.status,
		score = budgetReport.budget.score,
		notes = notes,
		manifestPath = manifestPath,
		blueprint = blueprint,
		nextCommand = "tools\\bridge.cmd vfx optimize \"" .. path .. "\" " .. tier,
	}
	V52.last.optimizationPlan = result
	return result
end

function V52.getProVfxPresetManifest(payload)
	payload = payload or {}
	local path = tostring(payload.path or payload.presetPath or "")
	local target = path ~= "" and resolvePath(path) or nil
	if not target then
		return { at = isoNow(), version = VERSION, status = "notFound", path = path, nextCommand = "tools\\bridge.cmd vfx pro-generate <intent>" }
	end
	local manifests = {}
	for _, child in ipairs(target:GetChildren()) do
		if child:IsA("ModuleScript") and (child.Name:find("Manifest", 1, true) or child.Name == "QualityAudit" or child.Name == "AssetRoleMap" or child.Name == "PerformanceBudget" or child.Name == "SourceIntent") then
			local sourceLength = 0
			pcall(function() sourceLength = #child.Source end)
			table.insert(manifests, { name = child.Name, path = safeFullName(child), className = child.ClassName, sourceLength = sourceLength })
		end
	end
	table.sort(manifests, function(a, b) return a.name < b.name end)
	local result = {
		at = isoNow(),
		version = VERSION,
		status = "ok",
		path = safeFullName(target),
		manifestCount = #manifests,
		manifests = manifests,
		budget = V52.getVfxPerformanceBudget({ path = path }),
		nextCommand = "tools\\bridge.cmd vfx audit \"" .. safeFullName(target) .. "\"",
	}
	V52.last.manifest = result
	return result
end

function V52.getProVfxRecipeCatalog(payload)
	payload = payload or {}
	local recipes = {}
	for effectType, profile in pairs(V51.effectProfiles()) do
		local timing = V51.timingPlan(effectType, tostring(payload.style or "arcanePurple"))
		table.insert(recipes, {
			id = effectType,
			roles = profile.roles,
			phases = profile.phases,
			timing = timing,
			bestCommand = "tools\\bridge.cmd vfx pro-plan \"" .. effectType .. " " .. table.concat(profile.roles or {}, " ") .. "\"",
		})
	end
	table.sort(recipes, function(a, b) return a.id < b.id end)
	return { at = isoNow(), version = VERSION, count = #recipes, recipes = recipes, nextCommand = "tools\\bridge.cmd vfx pro-plan <intent>" }
end

function V52.getProVfxExposureGuide(payload)
	return {
		at = isoNow(),
		version = VERSION,
		title = "V52 Pro VFX workflow",
		workflow = {
			"1. vfx kit <kitPath> - scan available reusable assets.",
			"2. vfx kit-recommend <intent> [kitPath] - pick textures/models/sounds by role.",
			"3. vfx pro-plan <intent> - compose layers and timing.",
			"4. generate_pro_vfx <intent> - create versioned Codex-owned preset.",
