	}
end

function V52.optimizeVfxPreset(payload)
	local plan = V52.getProVfxOptimizationPlan(payload or {})
	local result = applyBuildPlan({ blueprint = plan.blueprint })
	result.kind = "proVfxOptimize"
	result.path = plan.path
	result.tier = plan.tier
	result.scoreBefore = plan.score
	result.manifestPath = plan.manifestPath
	result.notes = plan.notes
	V52.last.optimized = result
	return result
end

function V52.bakeVfxBudgetManifest(payload)
	local plan = V52.getProVfxOptimizationPlan(payload or {})
	local manifestOnly = { name = "Bake Pro VFX Budget Manifest", mode = "fullTrust", source = "V52.bakeVfxBudgetManifest", steps = {} }
	for _, step in ipairs(plan.blueprint.steps or {}) do
		if step.type == "ensureFolder" or (step.path and tostring(step.path):find("PerformanceBudget", 1, true)) then
			table.insert(manifestOnly.steps, step)
		end
	end
	local result = applyBuildPlan({ blueprint = manifestOnly })
	result.kind = "proVfxBudgetManifest"
	result.path = plan.path
	result.tier = plan.tier
	result.manifestPath = plan.manifestPath
	V52.last.budgetManifest = result
	return result
end

-- V44 Universal Ability Forge
function V44.lower(value)
	return string.lower(tostring(value or ""))
end

function V44.safeName(value, fallback)
	return V39.safeName(value, fallback or "CodexAbility")
end

function V44.abilityRoots()
	return {
		"ReplicatedStorage.CodexAbilityForge",
		"ReplicatedStorage.CodexAbilityForge.Abilities",
		"ReplicatedStorage.CodexAbilityForge.Shared",
		"ServerScriptService.CodexAbilityForge",
		"StarterPlayer.StarterPlayerScripts.CodexAbilityForgeClient",
	}
end

function V44.getAbilityStyleCatalog(payload)
	local result = {
		at = isoNow(),
		version = VERSION,
		abilityTypes = {
			{ id = "beamAttack", name = "Beam Attack", keywords = { "beam", "laser", "kamehameha", "ray" }, defaultRange = 95, hitbox = "ray", animationHint = "projectile cast", vfxHint = "beam projectile impact" },
			{ id = "projectile", name = "Projectile", keywords = { "projectile", "fireball", "orb", "blast", "shoot" }, defaultRange = 80, hitbox = "sphereCast", animationHint = "projectile cast", vfxHint = "projectile trail impact burst" },
			{ id = "meleeSlash", name = "Melee Slash", keywords = { "slash", "sword", "melee", "weapon", "blade" }, defaultRange = 12, hitbox = "arc", animationHint = "combat slash", vfxHint = "slash trail hit sparks" },
			{ id = "areaBurst", name = "Area Burst", keywords = { "explosion", "burst", "shockwave", "aoe", "ground slam" }, defaultRange = 24, hitbox = "sphere", animationHint = "ability charge", vfxHint = "shockwave explosion impact" },
			{ id = "auraBuff", name = "Aura / Buff", keywords = { "aura", "buff", "power up", "shield", "enchant" }, defaultRange = 10, hitbox = "self", animationHint = "ability charge", vfxHint = "aura weapon enchant shield" },
			{ id = "healSupport", name = "Heal / Support", keywords = { "heal", "revive", "support", "blessing" }, defaultRange = 35, hitbox = "sphere", animationHint = "emote", vfxHint = "healing aura rising motes" },
			{ id = "trapInteractable", name = "Trap / Interactable", keywords = { "trap", "mine", "pickup", "pad", "interactable" }, defaultRange = 18, hitbox = "box", animationHint = "idle", vfxHint = "pickup ambient loop trigger burst" },
			{ id = "emoteEffect", name = "Emote With Effects", keywords = { "emote", "pose", "celebrate", "dance" }, defaultRange = 0, hitbox = "none", animationHint = "emote", vfxHint = "ambient aura loop" },
		},
		styles = V42.getAnimationStyleCatalog({}).styles,
		vfxStyles = V43.getVfxStyleCatalog({}).styles,
		nextCommand = "tools\\bridge.cmd ability plan \"heavy purple beam attack with charge fire impact and recovery\"",
	}
	V44.last.styles = result
	return result
end

function V44.inferAbilityType(intent)
	local text = V44.lower(intent)
	for _, ability in ipairs(V44.getAbilityStyleCatalog({}).abilityTypes or {}) do
		for _, word in ipairs(ability.keywords or {}) do
			if string.find(text, V44.lower(word), 1, true) then
				return ability
			end
		end
	end
	return V44.getAbilityStyleCatalog({}).abilityTypes[2]
end

function V44.inferStyle(intent)
	local text = V44.lower(intent)
	if string.find(text, "anime", 1, true) then return "anime" end
	if string.find(text, "heavy", 1, true) then return "heavy" end
	if string.find(text, "snappy", 1, true) or string.find(text, "quick", 1, true) then return "snappy" end
	if string.find(text, "cartoon", 1, true) or string.find(text, "cartoony", 1, true) then return "cartoony" end
	if string.find(text, "robot", 1, true) then return "robotic" end
	if string.find(text, "cinematic", 1, true) then return "cinematic" end
	return "snappy"
end

function V44.baseAbilityName(intent, abilityType)
	local words = {}
	for word in string.gmatch(tostring(intent or ""), "[%w]+") do
		table.insert(words, word)
		if #words >= 5 then break end
	end
	local base = #words > 0 and table.concat(words, "_") or tostring(abilityType or "Ability")
	return V44.safeName("CodexAbility_" .. base, "CodexAbility")
end

function V44.abilityFolder()
	local replicatedStorage = game:GetService("ReplicatedStorage")
	local root = replicatedStorage:FindFirstChild("CodexAbilityForge")
	local abilities = root and root:FindFirstChild("Abilities") or nil
	return abilities
end

function V44.nextAbilityName(baseName)
	baseName = V44.safeName(baseName, "CodexAbility")
	local folder = V44.abilityFolder()
	local index = 1
	while true do
		local candidate = string.format("%s_v%03d", baseName, index)
		if not folder or not folder:FindFirstChild(candidate) then return candidate end
		index += 1
	end
end

function V44.timeline(abilityType)
	local length = abilityType == "meleeSlash" and 0.9 or (abilityType == "auraBuff" and 1.25 or 1.45)
	return {
		{ time = 0, marker = "Start", action = "ability begins" },
		{ time = math.floor(length * 0.12 * 100 + 0.5) / 100, marker = "Anticipation", action = "wind-up pose and pre-glow" },
		{ time = math.floor(length * 0.26 * 100 + 0.5) / 100, marker = "ChargeStart", action = "enable charge VFX and sound swell" },
		{ time = math.floor(length * 0.48 * 100 + 0.5) / 100, marker = "DamageWindowStart", action = "begin hitbox window" },
		{ time = math.floor(length * 0.56 * 100 + 0.5) / 100, marker = "Fire", action = "launch or main hit moment" },
		{ time = math.floor(length * 0.62 * 100 + 0.5) / 100, marker = "Impact", action = "impact VFX, camera, sound" },
		{ time = math.floor(length * 0.72 * 100 + 0.5) / 100, marker = "DamageWindowEnd", action = "end hitbox window" },
		{ time = math.floor(length * 0.88 * 100 + 0.5) / 100, marker = "Recovery", action = "fade and return to control" },
	}
end

function V44.hitboxFor(ability, payload)
	local kind = tostring(ability and ability.hitbox or "sphere")
	local range = tonumber(payload.range or ability.defaultRange or 35) or 35
	if kind == "ray" then
		return { type = "ray", range = range, radius = tonumber(payload.radius or 4) or 4, origin = "casterRootOrHand", direction = "cameraOrForward" }
	elseif kind == "arc" then
		return { type = "arc", range = range, angleDegrees = tonumber(payload.angleDegrees or 105) or 105, height = tonumber(payload.height or 7) or 7 }
	elseif kind == "box" then
		return { type = "box", range = range, size = { 8, 6, 8 }, center = "targetOrWorldPoint" }
	elseif kind == "self" then
		return { type = "self", range = 0, affected = "caster" }
	elseif kind == "none" then
		return { type = "none", range = 0 }
	end
	return { type = "sphere", range = range, radius = tonumber(payload.radius or math.max(6, range * 0.25)) or 10, center = "impactPoint" }
end

function V44.damageWindows(timeline)
	local startTime = 0.45
	local endTime = 0.72
	for _, entry in ipairs(timeline or {}) do
		if entry.marker == "DamageWindowStart" then startTime = entry.time end
		if entry.marker == "DamageWindowEnd" then endTime = entry.time end
	end
	return { { id = "primary", startTime = startTime, endTime = endTime, damageType = "testOnly", notes = "Metadata only; production damage is not wired by V44." } }
end

function V44.manifestFromPath(path)
	local root = resolvePath(path or "")
	if not root then return nil, "notFound" end
	local value = root:FindFirstChild("AbilityManifestJson")
	if value and value:IsA("StringValue") then
		local decoded = decodeJson(value.Value)
		if decoded then return decoded, "stringValue" end
	end
	return nil, "missingManifestJson"
end

function V44.composePlan(payload)
	payload = payload or {}
	local intent = tostring(payload.intent or payload.text or payload.prompt or payload.description or "heavy purple beam attack with charge, fire, impact, and recovery")
	local ability = V44.inferAbilityType(intent)
	local abilityType = tostring(payload.abilityType or ability.id)
	local style = tostring(payload.style or V44.inferStyle(intent))
	local vfxStyle = tostring(payload.vfxStyle or V43.inferStyle(intent))
	local baseName = V44.baseAbilityName(intent, abilityType)
	local versionName = payload.name and V44.safeName(payload.name, baseName) or V44.nextAbilityName(baseName)
	local abilityPath = "ReplicatedStorage.CodexAbilityForge.Abilities." .. versionName
	local timeline = V44.timeline(abilityType)
	local target = tostring(payload.target or payload.targetPath or payload.rigPath or "Codex preview stage")
	local animationIntent = tostring(payload.animationIntent or (style .. " " .. tostring(ability.animationHint or abilityType) .. " for " .. intent))
	local vfxIntent = tostring(payload.vfxIntent or (vfxStyle .. " " .. tostring(ability.vfxHint or abilityType) .. " for " .. intent))
	local animationPlan = V42.getAnimationIntentPlan({ intent = animationIntent, rigPath = payload.rigPath, style = style, animationType = payload.animationType })
	local vfxPlan = V43.getVfxComposerPlan({ intent = vfxIntent, target = payload.targetPath, style = vfxStyle })
	local manifest = {
		name = versionName,
		intent = intent,
		abilityType = abilityType,
		style = style,
		target = target,
		animationPath = payload.animationPath or nil,
		vfxPresetPath = payload.vfxPresetPath or (vfxPlan.preset and V43.generatedPresetPath(vfxPlan.preset.name) or nil),
		cooldown = tonumber(payload.cooldown or (abilityType == "beamAttack" and 6 or 3)) or 3,
		range = tonumber(payload.range or ability.defaultRange or 35) or 35,
		hitbox = V44.hitboxFor(ability, payload),
		timeline = timeline,
		markers = timeline,
		damageWindows = V44.damageWindows(timeline),
		soundCues = { { marker = "SoundCue", time = 0.62, role = "primary ability sound" } },
		cameraCues = { { marker = "Impact", time = 0.62, type = "shake", intensity = abilityType == "beamAttack" and 0.65 or 0.35 } },
		qualityTier = tostring(payload.qualityTier or "balanced"),
		safety = {
			codexOwned = true,
			productionScriptsEdited = false,
			publishBlocked = true,
			economySaveMutation = false,
			damageIsMetadataOnly = true,
		},
		testPlan = {
			"Verify animation markers exist.",
			"Play VFX preset or structured fallback.",
			"Check hitbox metadata window and range.",
			"Inspect Output since baseline for bridge/game errors.",
			"Use production integration later through explicit project code patches only.",
		},
	}
	return {
		at = isoNow(),
		version = VERSION,
		status = "planned",
		intent = intent,
		abilityType = abilityType,
		style = style,
		vfxStyle = vfxStyle,
		name = versionName,
		abilityPath = abilityPath,
		manifest = manifest,
		animationPlan = animationPlan,
		vfxPlan = vfxPlan,
		nextCommand = "tools\\bridge.cmd ability generate \"" .. V9.trimText(intent, 100) .. "\"",
	}
end

