function V44.getAbilityQualityAudit(payload)
	payload = payload or {}
	local manifest = payload.manifest
	local source = "payload"
	if not manifest and (payload.path or payload.abilityPath) then
		manifest, source = V44.manifestFromPath(payload.path or payload.abilityPath)
	end
	if not manifest then
		local plan = payload.plan or V44.composePlan(payload)
		manifest = plan.manifest
		source = "plan"
	end
	local score = 100
	local blockers = {}
	local warnings = {}
	local strengths = {}
	local function requireField(field, points)
		if manifest[field] == nil or manifest[field] == "" then
			score -= points
			table.insert(blockers, "Missing " .. field .. ".")
		else
			table.insert(strengths, field .. " present.")
		end
	end
	requireField("name", 10)
	requireField("intent", 8)
	requireField("abilityType", 8)
	requireField("hitbox", 10)
	requireField("timeline", 10)
	requireField("damageWindows", 8)
	if not manifest.animationPath then score -= 10; table.insert(warnings, "Animation path is not linked yet.") end
	if not manifest.vfxPresetPath then score -= 10; table.insert(warnings, "VFX preset path is not linked yet.") end
	if #(manifest.timeline or {}) < 5 then score -= 10; table.insert(warnings, "Ability timeline is sparse.") end
	if #(manifest.testPlan or {}) < 3 then score -= 6; table.insert(warnings, "Test plan is thin.") end
	if manifest.safety and manifest.safety.productionScriptsEdited == false then table.insert(strengths, "No production script edit required.") else score -= 10; table.insert(warnings, "Safety metadata is incomplete.") end
	local result = {
		at = isoNow(),
		version = VERSION,
		status = #blockers == 0 and "ok" or "needsFix",
		score = math.max(0, math.min(100, score)),
		source = source,
		manifest = manifest,
		blockers = blockers,
		warnings = warnings,
		strengths = strengths,
		nextCommand = "tools\\bridge.cmd ability preview <abilityPath>",
	}
	V44.last.qualityAudit = result
	return result
end

