		for _, path in ipairs({ "ReplicatedStorage.CodexAbilityForge.Runtime", "ServerScriptService.CodexAbilityForge", "StarterPlayer.StarterPlayerScripts.CodexAbilityForgeClient" }) do
			local instance = resolvePath(path)
			if instance then
				local ok, err = pcall(function() instance:Destroy() end)
				if ok then table.insert(removed, path) else table.insert(skipped, { path = path, error = tostring(err) }) end
			else
				table.insert(skipped, { path = path, reason = "missing" })
			end
		end
		stateDirty = true
		local result = { at = isoNow(), version = VERSION, status = "removed", removed = removed, skipped = skipped }
		V44.last.removed = result
		return result
	end)
