function V44.generateAbilityFromIntent(payload)
	payload = payload or {}
	local plan = V44.getAbilityPackagePlan(payload)
	local animationIntent = plan.intent
	if plan.animationPlan and plan.animationPlan.animation and plan.animationPlan.animation.intent then
		animationIntent = plan.animationPlan.animation.intent
	end
	local vfxIntent = plan.intent
	if plan.vfxPlan and plan.vfxPlan.preset and plan.vfxPlan.preset.intent then
		vfxIntent = plan.vfxPlan.preset.intent
	end
	local animationResult = V42.generateAnimationFromIntent({ intent = animationIntent, rigPath = payload.rigPath, style = plan.style })
	local vfxResult = V43.generateVfxFromIntent({ intent = vfxIntent, targetPath = payload.targetPath, style = plan.vfxStyle })
	plan.manifest.animationPath = animationResult.path
	plan.manifest.vfxPresetPath = vfxResult.presetPath
	plan.manifest.vfxStagePath = vfxResult.stagePath
	local finalPlan = V44.getAbilityPackagePlan({
		intent = plan.intent,
		name = plan.name,
		abilityType = plan.abilityType,
		style = plan.style,
		target = plan.manifest.target,
		animationPath = animationResult.path,
		vfxPresetPath = vfxResult.presetPath,
		cooldown = plan.manifest.cooldown,
		range = plan.manifest.range,
		rigPath = payload.rigPath,
	})
	finalPlan.manifest.vfxStagePath = vfxResult.stagePath
	local manifestJson = HttpService:JSONEncode(finalPlan.manifest)
	for _, step in ipairs(finalPlan.blueprint.steps or {}) do
		if step.path == finalPlan.abilityPath .. ".AbilityManifestJson" then
			step.properties = { Value = manifestJson }
		elseif step.path == finalPlan.abilityPath .. ".AbilityManifest" then
			step.source = "return { format = \"codex-ability-v1\", version = " .. V8.luaString(VERSION) .. ", json = " .. V8.luaString(manifestJson) .. " }\n"
		elseif step.path == finalPlan.abilityPath .. ".AbilityConfig" then
			step.source = "return { json = " .. V8.luaString(manifestJson) .. " }\n"
		end
	end
	local packageResult = applyBuildPlan({ blueprint = finalPlan.blueprint })
	local result = {
		at = isoNow(),
		version = VERSION,
		status = "generated",
		kind = "abilityPackage",
		abilityPath = finalPlan.abilityPath,
		manifest = finalPlan.manifest,
		animation = animationResult,
		vfx = vfxResult,
		package = packageResult,
		quality = V44.getAbilityQualityAudit({ manifest = finalPlan.manifest }),
		nextCommand = "tools\\bridge.cmd ability preview \"" .. finalPlan.abilityPath .. "\"",
	}
	V44.last.generated = result
	return result
end

function V44.applyAbilityPackagePlan(payload)
	payload = payload or {}
	local plan = payload.plan or V44.getAbilityPackagePlan(payload)
	local result = applyBuildPlan({ blueprint = payload.blueprint or plan.blueprint })
	result.kind = "abilityPackagePlan"
	result.abilityPath = plan.abilityPath
	result.quality = V44.getAbilityQualityAudit({ manifest = plan.manifest })
	V44.last.appliedPlan = result
	return result
end

function V44.previewAbilityPackage(payload)
	payload = payload or {}
	local abilityPath = tostring(payload.abilityPath or payload.path or "")
	local manifest = payload.manifest
	if not manifest and abilityPath ~= "" then manifest = V44.manifestFromPath(abilityPath) end
	if not manifest then
		return { at = isoNow(), version = VERSION, status = "notFound", error = "Ability manifest was not found.", abilityPath = abilityPath }
	end
	local vfx = nil
	if manifest.vfxStagePath or manifest.vfxPresetPath then
		vfx = V39.requestVfxPlayback({ path = manifest.vfxStagePath or manifest.vfxPresetPath })
	end
	local animation = nil
	if payload.rigPath and manifest.animationPath then
		animation = V40.previewAnimation({ rigPath = payload.rigPath, animationPath = manifest.animationPath })
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		status = "previewed",
		abilityPath = abilityPath,
		manifest = manifest,
		vfx = vfx,
		animation = animation,
		watch = V28.getWatchNow and V28.getWatchNow({}) or nil,
		nextCommand = "tools\\bridge.cmd ability test \"" .. abilityPath .. "\"",
	}
	V44.last.preview = result
	return result
end

function V44.testAbilityPackage(payload)
	payload = payload or {}
	local abilityPath = tostring(payload.abilityPath or payload.path or "")
	local manifest = payload.manifest
	if not manifest and abilityPath ~= "" then manifest = V44.manifestFromPath(abilityPath) end
	if not manifest then
		return { at = isoNow(), version = VERSION, status = "notFound", error = "Ability manifest was not found.", abilityPath = abilityPath }
	end
	local output = nil
	if V31.getOutputSinceBaseline then
		output = V31.getOutputSinceBaseline({ limit = 30 })
	elseif getOutputDiagnostics then
		output = getOutputDiagnostics({ limit = 30 })
	end
	local runtime = nil
	if getRuntimeStatus then
		runtime = getRuntimeStatus({})
	elseif V8.getRuntimeStatus then
		runtime = V8.getRuntimeStatus({})
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		status = "tested",
		abilityPath = abilityPath,
		pass = true,
		evidence = {
			manifest = manifest,
			quality = V44.getAbilityQualityAudit({ manifest = manifest }),
			previewStatus = V44.getAbilityPreviewStatus(payload),
			output = output,
			runtime = runtime,
			watch = V28.getWatchNow and V28.getWatchNow({}) or nil,
		},
		blockers = {},
		warnings = { "V44 test uses metadata and Codex-owned preview evidence only; production damage/remotes are not fired." },
		nextActions = { "tools\\bridge.cmd ability audit \"" .. abilityPath .. "\"", "Integrate into production gameplay only through an explicit safe patch/refactor plan." },
	}
	V44.last.test = result
	return result
end

function V44.attachAbilityToTool(payload)
	payload = payload or {}
	local abilityPath = tostring(payload.abilityPath or payload.path or payload.ability or "")
	local targetPath = tostring(payload.targetPath or payload.target or "")
	if abilityPath == "" or targetPath == "" then
		return { at = isoNow(), version = VERSION, status = "failed", error = "attachAbilityToTool requires abilityPath and targetPath." }
	end
	local target = resolvePath(targetPath)
	if not target then
		return { at = isoNow(), version = VERSION, status = "notFound", error = "Target path was not found.", targetPath = targetPath }
	end
	local abilityName = V44.safeName(abilityPath:match("([^%.]+)$") or "Ability", "Ability")
	local mountPath = targetPath .. ".CodexAbilityMount_" .. abilityName
	local blueprint = {
		name = "Attach Codex Ability",
		mode = "fullTrust",
		source = "attachAbilityToTool",
		steps = {
			{ type = "ensureFolder", path = mountPath },
			V25.scriptWriteStep(mountPath .. ".AbilityMountManifest", "ModuleScript", "return { version = \"" .. VERSION .. "\", abilityPath = " .. V8.luaString(abilityPath) .. ", targetPath = " .. V8.luaString(targetPath) .. ", productionScriptsEdited = false }\n"),
		},
	}
	local result = applyBuildPlan({ blueprint = blueprint })
	result.kind = "abilityAttach"
	result.abilityPath = abilityPath
	result.targetPath = targetPath
	result.mountPath = mountPath
	V44.last.attached = result
	return result
end

function V44.applyAbilityCleanup(payload)
	payload = payload or {}
	local abilityName = tostring(payload.name or payload.abilityName or "")
	return withUndo("CodexAbilityCleanup", function()
		local removed = {}
		local skipped = {}
		local roots = {}
		if abilityName ~= "" then
			table.insert(roots, "ReplicatedStorage.CodexAbilityForge.Abilities." .. V44.safeName(abilityName, abilityName))
		else
			table.insert(roots, "ReplicatedStorage.CodexAbilityForge.Runtime")
		end
		for _, path in ipairs(roots) do
			local instance = resolvePath(path)
			if instance and string.find(safeFullName(instance), "Codex", 1, true) then
				local ok, err = pcall(function() instance:Destroy() end)
				if ok then table.insert(removed, path) else table.insert(skipped, { path = path, error = tostring(err) }) end
			else
				table.insert(skipped, { path = path, reason = "missing or not Codex-owned" })
			end
		end
		stateDirty = true
		local result = { at = isoNow(), version = VERSION, status = "cleaned", removed = removed, skipped = skipped }
		V44.last.cleanup = result
		return result
	end)
end

