-- V45 Universal Game Test Pilot + Interaction Runner
function V45.paths()
	return {
		"ReplicatedStorage.CodexTestPilot",
		"ReplicatedStorage.CodexTestPilot.TestPilotRequest",
		"ReplicatedStorage.CodexTestPilot.TestPilotResult",
		"ReplicatedStorage.CodexTestPilot.LastTestPilotRequest",
		"ReplicatedStorage.CodexTestPilot.LastTestPilotResult",
		"ReplicatedStorage.CodexTestPilot.Manifest",
		"StarterPlayer.StarterPlayerScripts.CodexTestPilotClient",
		"ServerScriptService.CodexTestPilotRelay",
	}
end

function V45.clientSource()
	return [==[
local Players = game:GetService("Players")
local player = Players.LocalPlayer
print("[CodexTestPilot] client ready", player and player.Name or "unknown")
]==]
end

function V45.relaySource()
	return [==[
local HttpService = game:GetService("HttpService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local folder = ReplicatedStorage:WaitForChild("CodexTestPilot", 10)
local requestValue = folder and folder:FindFirstChild("LastTestPilotRequest")
local resultValue = folder and folder:FindFirstChild("LastTestPilotResult")
local requestRemote = folder and folder:FindFirstChild("TestPilotRequest")
local resultRemote = folder and folder:FindFirstChild("TestPilotResult")

local function record(result)
	if resultValue then
		resultValue.Value = HttpService:JSONEncode(result)
	end
	if resultRemote then
		resultRemote:FireAllClients(result)
	end
	print("[CodexTestPilot] result", tostring(result.actionId or ""), tostring(result.status or "ok"))
end

if requestValue then
	requestValue:GetPropertyChangedSignal("Value"):Connect(function()
		local decoded = nil
		pcall(function() decoded = HttpService:JSONDecode(requestValue.Value) end)
		record({ actionId = decoded and decoded.id or nil, status = "observed", request = decoded, serverAt = os.clock() })
	end)
end

if requestRemote then
	requestRemote.OnServerEvent:Connect(function(player, request)
		record({ actionId = request and request.id or nil, status = "clientSignal", player = player and player.Name or nil, request = request, serverAt = os.clock() })
	end)
end

print("[CodexTestPilot] relay ready")
]==]
end

function V45.harnessBlueprint(payload)
	return {
		name = "Codex Test Pilot Harness",
		mode = "fullTrust",
		source = "installTestPilotHarness",
		steps = {
			{ type = "ensureFolder", path = "ReplicatedStorage.CodexTestPilot" },
			{ type = "ensureRemoteEvent", path = "ReplicatedStorage.CodexTestPilot.TestPilotRequest" },
			{ type = "ensureRemoteEvent", path = "ReplicatedStorage.CodexTestPilot.TestPilotResult" },
			{ type = "createInstance", className = "StringValue", path = "ReplicatedStorage.CodexTestPilot.LastTestPilotRequest", properties = { Value = "" } },
			{ type = "createInstance", className = "StringValue", path = "ReplicatedStorage.CodexTestPilot.LastTestPilotResult", properties = { Value = "" } },
			V25.scriptWriteStep("StarterPlayer.StarterPlayerScripts.CodexTestPilotClient", "LocalScript", V45.clientSource()),
			V25.scriptWriteStep("ServerScriptService.CodexTestPilotRelay", "Script", V45.relaySource()),
			V25.scriptWriteStep("ReplicatedStorage.CodexTestPilot.Manifest", "ModuleScript", "return { name = \"CodexTestPilot\", version = \"" .. VERSION .. "\", purpose = \"universal runtime movement and interaction testing\" }\n"),
		},
	}
end

function V45.getTestPilotStatus(payload)
	local paths = {}
	local installed = 0
	local requiredPaths = V45.paths()
	for _, path in ipairs(requiredPaths) do
		local instance = resolvePath(path)
		if instance then installed += 1 end
		table.insert(paths, { path = path, installed = instance ~= nil, className = instance and instance.ClassName or nil })
	end
	local complete = installed >= #requiredPaths
	local result = {
		at = isoNow(),
		version = VERSION,
		installed = complete,
		status = complete and "installed" or "missing",
		installedCount = installed,
		requiredCount = #requiredPaths,
		paths = paths,
		lastAction = V45.last.action,
		lastReport = V45.last.report,
		nextCommand = complete and "tools\\bridge.cmd test director" or "tools\\bridge.cmd test harness install",
	}
	V45.last.status = result
	return result
end

function V45.primaryPlayer(payload)
	payload = payload or {}
	local wanted = tostring(payload.playerName or payload.player or "")
	if wanted ~= "" then
		for _, player in ipairs(Players:GetPlayers()) do
			if player.Name == wanted or tostring(player.UserId) == wanted then
				return player
			end
		end
	end
	return Players:GetPlayers()[1]
end

function V45.characterParts(payload)
	local player = V45.primaryPlayer(payload)
	local character = player and player.Character or nil
	local humanoid = character and character:FindFirstChildOfClass("Humanoid") or nil
	local root = character and (character:FindFirstChild("HumanoidRootPart") or character.PrimaryPart) or nil
	return player, character, humanoid, root
end

function V45.vectorFromPayload(payload, fallback)
	payload = payload or {}
	local value = payload.position or payload.targetPosition or payload.destination or payload.point
	if typeof(value) == "Vector3" then
		return value
	end
	if type(value) == "table" then
		return Vector3.new(tonumber(value.x or value[1]) or 0, tonumber(value.y or value[2]) or 0, tonumber(value.z or value[3]) or 0)
	end
	if payload.x ~= nil or payload.y ~= nil or payload.z ~= nil then
		return Vector3.new(tonumber(payload.x) or 0, tonumber(payload.y) or 0, tonumber(payload.z) or 0)
	end
	if type(fallback) == "table" then
		return Vector3.new(tonumber(fallback.x or fallback[1]) or 0, tonumber(fallback.y or fallback[2]) or 0, tonumber(fallback.z or fallback[3]) or 0)
	end
	return nil
end

function V45.targetPosition(payload)
	payload = payload or {}
	local vector = V45.vectorFromPayload(payload)
	if vector then return vector, "coordinates" end
	local path = payload.targetPath or payload.path
	local target = path and resolvePath(path) or nil
	if target then
		if target:IsA("BasePart") then
			return target.Position, "path"
		elseif target:IsA("Model") then
			local ok, cf = pcall(function() return target:GetPivot() end)
			if ok then return cf.Position, "path" end
		elseif target:IsA("Attachment") then
			return target.WorldPosition, "path"
		end
	end
	return nil, "missing"
end

function V45.writePilotRequest(action)
	local value = resolvePath("ReplicatedStorage.CodexTestPilot.LastTestPilotRequest")
	if value and value:IsA("StringValue") then
		value.Value = encodeJson(action) or ""
	end
	return value
end

function V45.playerState(payload)
	local player, character, humanoid, root = V45.characterParts(payload)
	local tools = {}
	if player then
		local backpack = player:FindFirstChildOfClass("Backpack")
		if backpack then
			for _, child in ipairs(backpack:GetChildren()) do
				if child:IsA("Tool") then table.insert(tools, { name = child.Name, path = safeFullName(child), location = "Backpack" }) end
			end
		end
	end
	if character then
		for _, child in ipairs(character:GetChildren()) do
			if child:IsA("Tool") then table.insert(tools, { name = child.Name, path = safeFullName(child), location = "Character" }) end
		end
	end
	return {
		player = player and { name = player.Name, userId = player.UserId, attributes = serializeAttributes(player) } or nil,
		character = character and { path = safeFullName(character), attributes = serializeAttributes(character) } or nil,
		humanoid = humanoid and { health = humanoid.Health, maxHealth = humanoid.MaxHealth, state = tostring(humanoid:GetState()), walkSpeed = humanoid.WalkSpeed, jumpPower = humanoid.UseJumpPower and humanoid.JumpPower or nil, jumpHeight = humanoid.JumpHeight } or nil,
		root = root and { path = safeFullName(root), position = serializeValue(root.Position), cframe = serializeValue(root.CFrame) } or nil,
		tools = tools,
	}
end

function V45.getTestSnapshot(payload)
	payload = payload or {}
	local uiTargets = V32.getUiActionTargets({ query = payload.query or "" })
	local promptTargets = V32.getPromptActionTargets({ query = payload.query or "" })
	local snapshot = {
		at = isoNow(),
		version = VERSION,
		label = payload.label,
		runtime = getRuntimeStatus({}),
		player = V45.playerState(payload),
		attributes = V31.getLiveAttributeWatchReport(payload),
		watch = V28.getWatchNow(payload),
		ui = V25.getVisibleUiReport(payload),
		uiActionTargets = { count = uiTargets.count, totalUnfiltered = uiTargets.totalUnfiltered, targets = uiTargets.targets },
		promptActionTargets = { count = promptTargets.count, totalUnfiltered = promptTargets.totalUnfiltered, targets = promptTargets.targets },
		interactables = V32.getInteractableMap(payload),
		world = V8.getRuntimeWorldSummary(payload),
		remotes = V32.getRemoteTraceReport({ limit = payload.remoteLimit or 80 }),
		output = V31.getOutputSinceBaseline({ limit = payload.outputLimit or 120 }),
	}
	V45.last.snapshot = snapshot
	return snapshot
end

function V45.compactValue(value)
	local ok, encoded = pcall(function() return HttpService:JSONEncode(value) end)
	return ok and encoded or tostring(value)
end

function V45.getTestSnapshotDiff(payload)
	payload = payload or {}
	local before = payload.before or V45.last.beforeSnapshot or V45.last.snapshot
	local after = payload.after or V45.getTestSnapshot({ label = payload.label or "after" })
	local changed = {}
	local unchanged = {}
	local function compare(name, left, right)
		if V45.compactValue(left) ~= V45.compactValue(right) then
			table.insert(changed, { field = name, before = left, after = right })
		else
			table.insert(unchanged, name)
		end
	end
	if before then
		compare("playerRootPosition", before.player and before.player.root and before.player.root.position, after.player and after.player.root and after.player.root.position)
		compare("humanoidHealth", before.player and before.player.humanoid and before.player.humanoid.health, after.player and after.player.humanoid and after.player.humanoid.health)
		compare("humanoidState", before.player and before.player.humanoid and before.player.humanoid.state, after.player and after.player.humanoid and after.player.humanoid.state)
		compare("visibleUiCount", before.ui and before.ui.counts and before.ui.counts.visible, after.ui and after.ui.counts and after.ui.counts.visible)
		compare("outputErrorOrWarningCount", before.output and before.output.errorOrWarningCount, after.output and after.output.errorOrWarningCount)
	else
		table.insert(changed, { field = "snapshot", before = nil, after = "captured" })
	end
	local result = { at = isoNow(), version = VERSION, before = before, after = after, changed = changed, unchanged = unchanged, status = #changed > 0 and "changed" or "unchanged" }
	V45.last.diff = result
	return result
end

function V45.captureBefore(payload)
	V45.last.beforeSnapshot = V45.getTestSnapshot({ label = "before", outputLimit = payload and payload.outputLimit or 120 })
	return V45.last.beforeSnapshot
end

function V45.finishAction(action, status, detail, warnings, blockers)
	local after = V45.getTestSnapshot({ label = "after" })
	local diff = V45.getTestSnapshotDiff({ before = action.before, after = after })
	local blockerList = blockers or {}
	local warningList = warnings or {}
	local result = {
		at = isoNow(),
		version = VERSION,
		action = action,
		status = status,
		pass = #blockerList == 0 and status ~= "failed" and status ~= "notFound",
		detail = detail,
		before = action.before,
		after = after,
		changed = diff.changed,
		unchanged = diff.unchanged,
		warnings = warningList,
		blockers = blockerList,
		evidence = {
			player = after.player,
			output = after.output,
			watch = after.watch,
			remotes = after.remotes,
		},
		nextActions = #blockerList > 0 and { "Verify Play mode, harness status, and target selector." } or { "Review changed evidence and continue QA." },
	}
	V45.last.action = result
	return result
end

function V45.actionShell(kind, payload)
	local action = { id = HttpService:GenerateGUID(false), kind = kind, payload = payload or {}, before = V45.captureBefore(payload or {}), createdAt = isoNow() }
	V45.writePilotRequest({ id = action.id, type = kind, payload = payload or {}, at = action.createdAt, version = VERSION })
	return action
end

function V45.getTestPilotCapabilities(payload)
	local result = {
		at = isoNow(),
		version = VERSION,
		status = V45.getTestPilotStatus(payload),
		capabilities = {
			{ id = "move", command = "tools\\bridge.cmd test move <x> <y> <z>", mutatesRuntimeOnly = true },
			{ id = "teleport", command = "tools\\bridge.cmd test teleport <x> <y> <z>", mutatesRuntimeOnly = true },
			{ id = "jump", command = "tools\\bridge.cmd test jump", mutatesRuntimeOnly = true },
			{ id = "reset", command = "tools\\bridge.cmd test reset", mutatesRuntimeOnly = true },
			{ id = "face", command = "tools\\bridge.cmd test face <path-or-x-y-z>", mutatesRuntimeOnly = true },
			{ id = "path", command = "tools\\bridge.cmd test path <json-file>", mutatesRuntimeOnly = true },
			{ id = "interact", command = "tools\\bridge.cmd test interact <target-id-or-path>", usesActionBridge = true },
			{ id = "recipe", command = "tools\\bridge.cmd test run <recipe-or-intent>", usesSnapshots = true },
		},
		safety = "Runtime test actions affect only the local test player/character where possible. Production content, saves/economy, publish/upload, and broad destructive actions remain blocked/manual.",
		nextCommand = "tools\\bridge.cmd test targets",
	}
	V45.last.capabilities = result
	return result
end

function V45.getTestPilotTargetMap(payload)
	payload = payload or {}
	local prompts = V32.getPromptActionTargets(payload)
	local ui = V32.getUiActionTargets(payload)
	local interactables = V32.getInteractableMap(payload)
	local result = {
		at = isoNow(),
		version = VERSION,
		ui = ui,
		prompts = prompts,
		interactables = interactables,
		player = V45.playerState(payload),
		nextCommand = (prompts.targets and prompts.targets[1] and ("tools\\bridge.cmd test interact \"" .. (prompts.targets[1].id or prompts.targets[1].path) .. "\"")) or "tools\\bridge.cmd test snapshot",
	}
	V45.last.targets = result
	return result
end

function V45.getTestMovementPlan(payload)
	payload = payload or {}
	local position, source = V45.targetPosition(payload)
	return {
		at = isoNow(),
		version = VERSION,
		status = position and "ready" or "needsTarget",
		source = source,
		position = position and serializeValue(position) or nil,
		method = payload.teleport and "PivotTo" or "Humanoid:MoveTo",
		safety = "Runtime-only movement for the selected/local test player.",
		nextCommand = position and ("tools\\bridge.cmd test " .. (payload.teleport and "teleport" or "move") .. " " .. tostring(math.floor(position.X * 100) / 100) .. " " .. tostring(math.floor(position.Y * 100) / 100) .. " " .. tostring(math.floor(position.Z * 100) / 100)) or "tools\\bridge.cmd test targets",
	}
end

function V45.getTestInteractionPlan(payload)
	payload = payload or {}
	local selector = tostring(payload.target or payload.id or payload.path or payload.text or payload.name or "")
	local prompts = V32.getPromptActionTargets({ id = payload.id or selector, path = payload.path or selector, text = payload.text or selector, name = payload.name or selector })
	local ui = V32.getUiActionTargets({ id = payload.id or selector, path = payload.path or selector, text = payload.text or selector, name = payload.name or selector })
	local result = {
		at = isoNow(),
		version = VERSION,
		selector = selector ~= "" and selector or nil,
		uiMatches = ui.targets or {},
		promptMatches = prompts.targets or {},
		ambiguous = (ui.ambiguous == true) or (prompts.ambiguous == true),
		nextCommand = "tools\\bridge.cmd test interact <target-id-or-path>",
	}
	V45.last.interactionPlan = result
	return result
end

function V45.moveTestCharacter(payload)
	payload = payload or {}
	local action = V45.actionShell("move", payload)
	local _, _, humanoid = V45.characterParts(payload)
	local position = V45.vectorFromPayload(payload)
	if not humanoid then
		return V45.finishAction(action, "failed", nil, {}, { "No test character Humanoid found. Start Play and spawn first." })
	end
	if not position then
		return V45.finishAction(action, "failed", nil, {}, { "moveTestCharacter requires x/y/z or position." })
	end
	local ok, err = pcall(function()
		humanoid:MoveTo(position)
	end)
	task.wait(math.min(math.max(tonumber(payload.waitSeconds) or 0.75, 0), 5))
	return V45.finishAction(action, ok and "moved" or "failed", { position = serializeValue(position), method = "Humanoid:MoveTo", error = ok and nil or tostring(err) }, {}, ok and {} or { tostring(err) })
end

function V45.teleportTestCharacter(payload)
	payload = payload or {}
	local action = V45.actionShell("teleport", payload)
	local _, character = V45.characterParts(payload)
	local position = V45.vectorFromPayload(payload)
	if not character then
		return V45.finishAction(action, "failed", nil, {}, { "No test character found. Start Play and spawn first." })
	end
	if not position then
		return V45.finishAction(action, "failed", nil, {}, { "teleportTestCharacter requires x/y/z or position." })
	end
	local ok, err = pcall(function()
		character:PivotTo(CFrame.new(position))
	end)
	task.wait(0.2)
	return V45.finishAction(action, ok and "teleported" or "failed", { position = serializeValue(position), method = "Model:PivotTo", error = ok and nil or tostring(err) }, {}, ok and {} or { tostring(err) })
end

function V45.jumpTestCharacter(payload)
	payload = payload or {}
	local action = V45.actionShell("jump", payload)
	local _, _, humanoid = V45.characterParts(payload)
	if not humanoid then
		return V45.finishAction(action, "failed", nil, {}, { "No test character Humanoid found. Start Play and spawn first." })
	end
	local ok, err = pcall(function()
		humanoid.Jump = true
		humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
	end)
	task.wait(0.35)
	return V45.finishAction(action, ok and "jumped" or "failed", { method = "Humanoid.Jump/ChangeState", error = ok and nil or tostring(err) }, {}, ok and {} or { tostring(err) })
end

function V45.resetTestCharacter(payload)
	payload = payload or {}
	local action = V45.actionShell("reset", payload)
	local _, _, humanoid = V45.characterParts(payload)
	if not humanoid then
		return V45.finishAction(action, "failed", nil, {}, { "No test character Humanoid found. Start Play and spawn first." })
	end
	local ok, err = pcall(function()
		humanoid.Health = 0
	end)
	task.wait(0.8)
	return V45.finishAction(action, ok and "reset" or "failed", { method = "Humanoid.Health = 0", error = ok and nil or tostring(err) }, { "Reset is runtime QA only; it does not edit production content." }, ok and {} or { tostring(err) })
end

function V45.faceTestCharacter(payload)
	payload = payload or {}
	local action = V45.actionShell("face", payload)
	local _, character, _, root = V45.characterParts(payload)
	local position, source = V45.targetPosition(payload)
	if not (character and root) then
		return V45.finishAction(action, "failed", nil, {}, { "No test character root found. Start Play and spawn first." })
	end
	if not position then
		return V45.finishAction(action, "failed", nil, {}, { "faceTestCharacter requires target path or x/y/z." })
	end
	local rootPos = root.Position
	local look = Vector3.new(position.X, rootPos.Y, position.Z)
	local ok, err = pcall(function()
		character:PivotTo(CFrame.lookAt(rootPos, look))
	end)
	task.wait(0.15)
	return V45.finishAction(action, ok and "faced" or "failed", { target = serializeValue(position), source = source, method = "CFrame.lookAt", error = ok and nil or tostring(err) }, {}, ok and {} or { tostring(err) })
end

function V45.followTestPath(payload)
	payload = payload or {}
	local action = V45.actionShell("path", payload)
	local points = payload.points or payload.pathPoints or payload.path
	if type(points) ~= "table" then
		return V45.finishAction(action, "failed", nil, {}, { "followTestPath requires a JSON array of points." })
	end
	local _, _, humanoid = V45.characterParts(payload)
	if not humanoid then
		return V45.finishAction(action, "failed", nil, {}, { "No test character Humanoid found. Start Play and spawn first." })
	end
	local visited = {}
	local errors = {}
	for index, point in ipairs(points) do
		local position = V45.vectorFromPayload({ position = point })
		if position then
			local ok, err = pcall(function() humanoid:MoveTo(position) end)
			table.insert(visited, { index = index, position = serializeValue(position), ok = ok })
			if not ok then table.insert(errors, tostring(err)) end
			task.wait(math.min(math.max(tonumber(payload.stepWaitSeconds) or 0.75, 0.1), 3))
		else
			table.insert(errors, "Invalid point at index " .. tostring(index))
		end
	end
	return V45.finishAction(action, #errors == 0 and "pathFollowed" or "partial", { visited = visited }, errors, #errors > 0 and errors or {})
end

function V45.runTestInteraction(payload)
	payload = payload or {}
	local selector = tostring(payload.target or payload.targetId or payload.id or payload.path or payload.text or payload.name or "")
	if selector == "" then
		return { at = isoNow(), version = VERSION, status = "failed", blockers = { "runTestInteraction requires target id, path, text, or name." }, nextCommand = "tools\\bridge.cmd test targets" }
	end
	local promptReport = V32.getPromptActionTargets({ id = selector, path = selector, text = selector, name = selector })
	if promptReport.targets and #promptReport.targets == 1 then
		local target = promptReport.targets[1]
		local result = V32.applyPromptTriggerAction({ id = target.id, path = target.path, text = target.actionText or target.objectText, name = target.name, target = target })
		V45.last.action = result
		return result
	elseif promptReport.targets and #promptReport.targets > 1 then
		return { at = isoNow(), version = VERSION, status = "ambiguous", candidates = promptReport.targets, recommendedSelector = "Use tools\\bridge.cmd test interact <prompt-id>." }
	end
	local uiReport = V32.getUiActionTargets({ id = selector, path = selector, text = selector, name = selector })
	if uiReport.targets and #uiReport.targets == 1 then
		local target = uiReport.targets[1]
		local result = V32.applyUiClickAction({ id = target.id, path = target.path, text = target.text, name = target.name, target = target })
		V45.last.action = result
		return result
	elseif uiReport.targets and #uiReport.targets > 1 then
		return { at = isoNow(), version = VERSION, status = "ambiguous", candidates = uiReport.targets, recommendedSelector = "Use tools\\bridge.cmd test interact <ui-id>." }
	end
	local instance = resolvePath(selector)
	if instance and instance:IsA("BasePart") then
		local position = instance.Position + Vector3.new(0, math.max(3, instance.Size.Y / 2 + 2), 0)
		local result = V45.teleportTestCharacter({ position = { x = position.X, y = position.Y, z = position.Z }, reason = "touchPadOrWorldInteractable", targetPath = selector })
		result.interactionTarget = { path = selector, className = instance.ClassName, name = instance.Name }
		return result
	end
	return { at = isoNow(), version = VERSION, status = "notFound", blockers = { "No prompt, UI target, or world part matched selector." }, selector = selector, nextCommand = "tools\\bridge.cmd test targets" }
end

function V45.recipeCatalog()
	return {
		{ id = "full", title = "Full Universal Game Test", goal = "overall playable loop, UI, prompts, movement, output, attributes, map/performance evidence", defaultActions = { "snapshot", "jump" } },
		{ id = "first-5-minutes", title = "First 5 Minutes", goal = "join, spawn, objective, first interaction, feedback, reward/replay evidence", defaultActions = { "snapshot", "jump" } },
		{ id = "ui", title = "UI QA", goal = "visible UI, clickable targets, responsive risks, before/after UI evidence", defaultActions = { "snapshot" } },
		{ id = "prompt", title = "Prompt/Interactable QA", goal = "prompt list, distances, first target plan, before/after interaction evidence", defaultActions = { "snapshot" } },
		{ id = "shop", title = "Shop QA", goal = "shop buttons, prices, currency feedback, output errors", defaultActions = { "snapshot" } },
		{ id = "checkpoint", title = "Checkpoint/Respawn QA", goal = "spawn points, checkpoint pads, reset/respawn evidence", defaultActions = { "snapshot", "jump" } },
		{ id = "combat", title = "Combat QA", goal = "health, tools/weapons, ability/action feedback, output errors", defaultActions = { "snapshot" } },
		{ id = "economy", title = "Economy QA", goal = "leaderstats/currency visibility and risky save/economy remotes", defaultActions = { "snapshot" } },
		{ id = "tutorial", title = "Tutorial/Onboarding QA", goal = "objective text, guide UI, first interaction, feedback clarity", defaultActions = { "snapshot" } },
		{ id = "world-layout", title = "World Layout QA", goal = "movement space, landmarks, prompts, clutter, unanchored/floating risk", defaultActions = { "snapshot" } },
		{ id = "performance", title = "Performance QA", goal = "parts, scripts, lights, VFX, risky loops, low-end risk", defaultActions = { "snapshot" } },
		{ id = "mobile", title = "Mobile QA", goal = "viewport, tap targets, visible UI, safe area/readability risks", defaultActions = { "snapshot" } },
		{ id = "respawn", title = "Respawn QA", goal = "reset flow, spawn recovery, UI/output after respawn", defaultActions = { "snapshot", "reset" } },
		{ id = "ability", title = "Ability QA", goal = "Codex-generated ability package preview/test evidence", defaultActions = { "snapshot" } },
	}
end

function V45.findRecipe(id)
	local wanted = string.lower(tostring(id or "full"))
	for _, recipe in ipairs(V45.recipeCatalog()) do
		if recipe.id == wanted then return recipe end
	end
	return { id = "custom", title = "Custom Test", goal = tostring(id or "test the game"), defaultActions = { "snapshot" } }
end

function V45.getGameTestRecipeCatalog(payload)
	return { at = isoNow(), version = VERSION, recipes = V45.recipeCatalog(), nextCommand = "tools\\bridge.cmd test plan full" }
end

function V45.getGameTestRecipePlan(payload)
	payload = payload or {}
	local recipe = V45.findRecipe(payload.recipeId or payload.id or payload.intent or "full")
	local plan = {
		at = isoNow(),
		version = VERSION,
		recipe = recipe,
		steps = {
			"Mark/inspect Output baseline.",
			"Capture before snapshot.",
			"Run safe runtime actions when the recipe requests them.",
			"Capture after snapshot and diff.",
			"Report pass/blockers/warnings/evidence/next actions.",
		},
		readOnlyPreview = true,
		mutatingRuntimeOnlyWhenRun = true,
		nextCommand = "tools\\bridge.cmd test run " .. recipe.id,
	}
	V45.last.recipePlan = plan
	return plan
end

function V45.runGameTestRecipe(payload)
	payload = payload or {}
	local recipe = V45.findRecipe(payload.recipeId or payload.id or payload.intent or "full")
	local before = V45.captureBefore({ label = "recipeBefore" })
	local actions = {}
	if recipe.defaultActions then
		for _, actionName in ipairs(recipe.defaultActions) do
			if actionName == "jump" then
				table.insert(actions, V45.jumpTestCharacter({ reason = "recipe", recipeId = recipe.id }))
			elseif actionName == "reset" then
				table.insert(actions, V45.resetTestCharacter({ reason = "recipe", recipeId = recipe.id }))
			end
		end
	end
	if payload.target or payload.id or payload.path then
		table.insert(actions, V45.runTestInteraction(payload))
	end
	local after = V45.getTestSnapshot({ label = "recipeAfter" })
	local diff = V45.getTestSnapshotDiff({ before = before, after = after })
	local report = {
		at = isoNow(),
		version = VERSION,
		status = "completed",
		recipe = recipe,
		pass = (after.output and (after.output.errorOrWarningCount or 0) == 0) and true or false,
		before = before,
		after = after,
		actions = actions,
		changed = diff.changed,
		unchanged = diff.unchanged,
		blockers = after.output and (after.output.errorOrWarningCount or 0) > 0 and { "New Output errors/warnings were observed." } or {},
		warnings = { "Recipe actions are universal and conservative; provide a target id/path for deeper interaction tests." },
		nextActions = { "tools\\bridge.cmd test report", "tools\\bridge.cmd test targets" },
	}
	V45.last.report = report
	return report
end

function V45.getGameTestReport(payload)
	return V45.last.report or {
		at = isoNow(),
		version = VERSION,
		status = "noReportYet",
		nextCommand = "tools\\bridge.cmd test run full",
	}
end

function V45.installTestPilotHarness(payload)
	local result = applyBuildPlan({ blueprint = V45.harnessBlueprint(payload or {}) })
	result.kind = "testPilotHarnessInstall"
	result.status = V45.getTestPilotStatus(payload or {})
	return result
end

function V45.removeTestPilotHarness(payload)
	return withUndo("RemoveTestPilotHarness", function()
		local removed = {}
		local skipped = {}
		for _, path in ipairs(V45.paths()) do
			local instance = resolvePath(path)
			if instance then
				local ok, err = pcall(function() instance:Destroy() end)
				if ok then table.insert(removed, path) else table.insert(skipped, { path = path, error = tostring(err) }) end
			else
				table.insert(skipped, { path = path, reason = "missing" })
			end
		end
		stateDirty = true
		return { at = isoNow(), version = VERSION, status = "removed", removed = removed, skipped = skipped }
	end)
end

function V45.clearTestPilotRuntime(payload)
	local lastValue = resolvePath("ReplicatedStorage.CodexTestPilot.LastTestPilotRequest")
	local resultValue = resolvePath("ReplicatedStorage.CodexTestPilot.LastTestPilotResult")
	if lastValue and lastValue:IsA("StringValue") then lastValue.Value = "" end
	if resultValue and resultValue:IsA("StringValue") then resultValue.Value = "" end
	V45.last.action = nil
	V45.last.report = nil
	return { at = isoNow(), version = VERSION, status = "cleared" }
end

function V45.getTestPilotDirectorReport(payload)
	local result = {
		at = isoNow(),
		version = VERSION,
		status = V45.getTestPilotStatus(payload),
		capabilities = V45.getTestPilotCapabilities(payload),
		targets = V45.getTestPilotTargetMap({}),
		lastAction = V45.last.action,
		lastReport = V45.last.report,
		recommended = {
			"tools\\bridge.cmd test snapshot",
			"tools\\bridge.cmd test move 0 0 20",
			"tools\\bridge.cmd test jump",
			"tools\\bridge.cmd test targets",
			"tools\\bridge.cmd test run full",
		},
		nextCommand = "tools\\bridge.cmd test snapshot",
	}
	V45.last.director = result
	return result
end

-- V40 Universal Animation Director + Rig Authoring Workbench
function V40.roots(payload)
	payload = payload or {}
	if payload.path or payload.root then
		local root = resolvePath(payload.path or payload.root)
		return root and { root } or {}
	end
	local roots = {}
	for _, name in ipairs({ "Workspace", "ReplicatedStorage", "ServerStorage", "StarterPlayer" }) do
		local ok, service = pcall(function()
			return game:GetService(name)
		end)
		if ok and service then
			table.insert(roots, service)
		end
	end
	return roots
end

function V40.isRigCandidate(instance)
	if not instance or not instance:IsA("Model") then
		return false
	end
	if instance:FindFirstChildOfClass("Humanoid") or instance:FindFirstChildOfClass("AnimationController") then
		return true
	end
	for _, descendant in ipairs(instance:GetDescendants()) do
		if descendant:IsA("Motor6D") or descendant:IsA("AnimationConstraint") or descendant:IsA("Bone") then
			return true
		end
	end
	return false
end

function V40.safeRead(instance, propertyName)
	local ok, value = pcall(function()
		return instance[propertyName]
	end)
	if ok then
		return value, true
	end
	return nil, false
end

function V40.safeWrite(instance, propertyName, value)
	local ok, err = pcall(function()
		instance[propertyName] = value
	end)
	return ok, err
end

function V40.cframePose(value)
	if typeof(value) ~= "CFrame" then
		return nil
	end
	local rx, ry, rz = value:ToOrientation()
	return {
		cframe = serializeValue(value),
		position = { value.Position.X, value.Position.Y, value.Position.Z },
		rotationEulerDegrees = { math.deg(rx), math.deg(ry), math.deg(rz) },
	}
end

function V40.instanceInfo(instance)
	if not instance then
		return nil
	end
	return { id = getInstanceId(instance), name = instance.Name, className = instance.ClassName, path = safeFullName(instance) }
end

function V40.motorSummary(motor)
	return {
		id = getInstanceId(motor),
		name = motor.Name,
		path = safeFullName(motor),
		part0 = motor.Part0 and { id = getInstanceId(motor.Part0), name = motor.Part0.Name, path = safeFullName(motor.Part0) } or nil,
		part1 = motor.Part1 and { id = getInstanceId(motor.Part1), name = motor.Part1.Name, path = safeFullName(motor.Part1) } or nil,
		C0 = serializeValue(motor.C0),
		C1 = serializeValue(motor.C1),
		Transform = serializeValue(motor.Transform),
		pose = V40.cframePose(motor.Transform),
	}
end

function V40.constraintSummary(constraint)
	local attachment0 = V40.safeRead(constraint, "Attachment0")
	local attachment1 = V40.safeRead(constraint, "Attachment1")
	local transform = V40.safeRead(constraint, "Transform")
	local isKinematic = V40.safeRead(constraint, "IsKinematic")
	local c0 = V40.safeRead(constraint, "C0") or (attachment0 and attachment0:IsA("Attachment") and attachment0.CFrame or nil)
	local c1 = V40.safeRead(constraint, "C1") or (attachment1 and attachment1:IsA("Attachment") and attachment1.CFrame or nil)
	local part0 = V40.safeRead(constraint, "Part0") or (attachment0 and attachment0.Parent and attachment0.Parent:IsA("BasePart") and attachment0.Parent or nil)
	local part1 = V40.safeRead(constraint, "Part1") or (attachment1 and attachment1.Parent and attachment1.Parent:IsA("BasePart") and attachment1.Parent or nil)
	return {
		id = getInstanceId(constraint),
		name = constraint.Name,
		path = safeFullName(constraint),
		attachment0 = V40.instanceInfo(attachment0),
		attachment1 = V40.instanceInfo(attachment1),
		part0 = V40.instanceInfo(part0),
		part1 = V40.instanceInfo(part1),
		C0 = typeof(c0) == "CFrame" and serializeValue(c0) or nil,
		C1 = typeof(c1) == "CFrame" and serializeValue(c1) or nil,
		Transform = typeof(transform) == "CFrame" and serializeValue(transform) or nil,
		pose = V40.cframePose(transform),
		IsKinematic = isKinematic,
	}
end

function V40.boneSummary(bone)
	return {
		id = getInstanceId(bone),
		name = bone.Name,
		path = safeFullName(bone),
		parentPath = bone.Parent and safeFullName(bone.Parent) or nil,
		CFrame = serializeValue(bone.CFrame),
		Transform = serializeValue(bone.Transform),
		WorldCFrame = serializeValue(bone.WorldCFrame),
		pose = V40.cframePose(bone.Transform),
	}
end

function V40.animationSummary(instance)
	local summary = {
		id = getInstanceId(instance),
		name = instance.Name,
		className = instance.ClassName,
		path = safeFullName(instance),
	}
	if instance:IsA("Animation") then
		summary.animationId = instance.AnimationId
	elseif instance:IsA("KeyframeSequence") then
		summary.loop = instance.Loop
		summary.priority = tostring(instance.Priority)
		summary.keyframeCount = #instance:GetKeyframes()
		summary.hash = V40.animationHash(instance)
	end
	return summary
end

function V40.canonicalTargetReport(model)
	local names = {
		"Root",
		"HumanoidRootPart",
		"LowerTorso",
		"Waist",
		"UpperTorso",
		"Neck",
		"Head",
		"RightShoulder",
		"RightUpperArm",
		"RightElbow",
		"RightLowerArm",
		"RightWrist",
		"RightHand",
		"LeftShoulder",
		"LeftUpperArm",
		"LeftElbow",
		"LeftLowerArm",
		"LeftWrist",
		"LeftHand",
		"RightHip",
		"RightUpperLeg",
		"RightKnee",
		"RightLowerLeg",
		"RightAnkle",
		"RightFoot",
		"LeftHip",
		"LeftUpperLeg",
		"LeftKnee",
		"LeftLowerLeg",
		"LeftAnkle",
		"LeftFoot",
	}
	local map = V40.poseTargetMap and V40.poseTargetMap(model) or nil
	local report = {}
	for _, name in ipairs(names) do
		local target = map and V40.resolvePoseTarget(map, name) or nil
		report[name] = target and { kind = target.kind, path = safeFullName(target.instance), targetName = target.name } or nil
	end
	return report
end

function V40.rigSummary(model, includeDetails)
	local humanoid = model:FindFirstChildOfClass("Humanoid")
	local controller = model:FindFirstChildOfClass("AnimationController")
	local animator = nil
	if humanoid then
		animator = humanoid:FindFirstChildOfClass("Animator")
	elseif controller then
		animator = controller:FindFirstChildOfClass("Animator")
	end
	local motors = {}
	local animationConstraints = {}
	local bones = {}
	local animations = {}
	local bodyParts = {}
	local attachments = {}
	for _, descendant in ipairs(model:GetDescendants()) do
		if descendant:IsA("Motor6D") then
			table.insert(motors, includeDetails and V40.motorSummary(descendant) or { name = descendant.Name, path = safeFullName(descendant), part1 = descendant.Part1 and descendant.Part1.Name or nil })
		elseif descendant:IsA("AnimationConstraint") then
			table.insert(animationConstraints, includeDetails and V40.constraintSummary(descendant) or { name = descendant.Name, path = safeFullName(descendant), parent = descendant.Parent and descendant.Parent.Name or nil })
		elseif descendant:IsA("Bone") then
			table.insert(bones, includeDetails and V40.boneSummary(descendant) or { name = descendant.Name, path = safeFullName(descendant) })
		elseif descendant:IsA("Animation") or descendant:IsA("KeyframeSequence") then
			table.insert(animations, V40.animationSummary(descendant))
		elseif descendant:IsA("BasePart") then
			table.insert(bodyParts, includeDetails and { id = getInstanceId(descendant), name = descendant.Name, className = descendant.ClassName, path = safeFullName(descendant), position = serializeValue(descendant.Position), size = serializeValue(descendant.Size) } or descendant.Name)
		elseif descendant:IsA("Attachment") then
			table.insert(attachments, includeDetails and { id = getInstanceId(descendant), name = descendant.Name, path = safeFullName(descendant), parent = descendant.Parent and safeFullName(descendant.Parent) or nil, CFrame = serializeValue(descendant.CFrame), WorldCFrame = serializeValue(descendant.WorldCFrame) } or descendant.Name)
		end
	end
	local activeTracks = {}
	if animator then
		pcall(function()
			for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
				table.insert(activeTracks, {
					name = track.Name,
					animation = track.Animation and safeFullName(track.Animation) or nil,
					animationId = track.Animation and track.Animation.AnimationId or nil,
					timePosition = track.TimePosition,
					length = track.Length,
					priority = tostring(track.Priority),
					isPlaying = track.IsPlaying,
				})
			end
		end)
	end
	local worldPosition = nil
	pcall(function()
		local pivot = model:GetPivot()
		worldPosition = serializeValue(pivot.Position)
	end)
	local rigType = "custom"
	if humanoid then
		local humanoidRigType = tostring(humanoid.RigType):gsub("^Enum%.HumanoidRigType%.", "")
		if #animationConstraints > 0 and humanoidRigType == "R15" then
			rigType = "R15AnimationConstraint"
		elseif #motors > 0 and humanoidRigType == "R15" then
			rigType = "R15Motor6D"
		elseif #motors > 0 and humanoidRigType == "R6" then
			rigType = "R6Motor6D"
		else
			rigType = humanoidRigType
		end
	elseif #animationConstraints > 0 then
		rigType = "customAnimationConstraint"
	elseif #bones > 0 then
		rigType = "customBoneSkinned"
	elseif #motors > 0 then
		rigType = "customMotor6D"
	end
	return {
		id = getInstanceId(model),
		name = model.Name,
		className = model.ClassName,
		path = safeFullName(model),
		rigType = rigType,
		humanoid = humanoid and { id = getInstanceId(humanoid), path = safeFullName(humanoid), rigType = tostring(humanoid.RigType), health = humanoid.Health, hipHeight = humanoid.HipHeight } or nil,
		animationController = controller and { id = getInstanceId(controller), path = safeFullName(controller) } or nil,
		animator = animator and { id = getInstanceId(animator), path = safeFullName(animator) } or nil,
		worldPosition = worldPosition,
		partCount = #bodyParts,
		attachmentCount = #attachments,
		motorCount = #motors,
		animationConstraintCount = #animationConstraints,
		boneCount = #bones,
		animationCount = #animations,
		activeTrackCount = #activeTracks,
		activeTracks = activeTracks,
		canonicalR15 = includeDetails and V40.canonicalTargetReport(model) or nil,
		motors = motors,
		animationConstraints = animationConstraints,
		bones = bones,
		animations = animations,
		bodyParts = includeDetails and bodyParts or nil,
		attachments = includeDetails and attachments or nil,
	}
end

function V40.getAnimationRigInventory(payload)
	payload = payload or {}
	local maxModels = tonumber(payload.maxRigs or payload.maxResults or 120) or 120
	local rigs = {}
	local scanned = 0
	for _, root in ipairs(V40.roots(payload)) do
		if root:IsA("Model") and V40.isRigCandidate(root) then
			table.insert(rigs, V40.rigSummary(root, false))
		end
		for _, descendant in ipairs(root:GetDescendants()) do
			if descendant:IsA("Model") then
				scanned += 1
				if V40.isRigCandidate(descendant) then
					table.insert(rigs, V40.rigSummary(descendant, false))
					if #rigs >= maxModels then break end
				end
			end
		end
		if #rigs >= maxModels then break end
	end
	local result = { at = isoNow(), version = VERSION, count = #rigs, scanned = scanned, rigs = rigs, nextCommand = rigs[1] and ("tools\\bridge.cmd animation inspect-rig \"" .. rigs[1].path .. "\"") or "Insert/select a rig, then rerun tools\\bridge.cmd animation list-rigs" }
	V40.last.rigInventory = result
	return result
end

function V40.resolveRig(payload)
	payload = payload or {}
	local target = resolvePath(payload.rigPath or payload.path or payload.rig or "") or resolveInstance(payload.rigId or payload.id)
	if target and not target:IsA("Model") then
		target = target:FindFirstAncestorOfClass("Model")
	end
	return target
end

function V40.inspectAnimationRig(payload)
	local rig = V40.resolveRig(payload)
	if not rig then
		return { at = isoNow(), version = VERSION, status = "notFound", error = "Rig was not found.", requested = payload and (payload.rigPath or payload.path or payload.rigId) or nil }
	end
	local result = V40.rigSummary(rig, true)
	result.at = isoNow()
	result.version = VERSION
	result.status = "ok"
	result.nextCommand = "tools\\bridge.cmd animation pose \"" .. safeFullName(rig) .. "\""
	V40.last.rig = result
	return result
end

function V40.getRigPose(payload)
	local rig = V40.resolveRig(payload)
	if not rig then
		return { at = isoNow(), version = VERSION, status = "notFound", error = "Rig was not found." }
	end
	local joints = {}
	local constraints = {}
	local bones = {}
	for _, descendant in ipairs(rig:GetDescendants()) do
		if descendant:IsA("Motor6D") then
			joints[descendant.Name] = { kind = "Motor6D", path = safeFullName(descendant), part1 = descendant.Part1 and descendant.Part1.Name or nil, transform = serializeValue(descendant.Transform), pose = V40.cframePose(descendant.Transform) }
		elseif descendant:IsA("AnimationConstraint") then
			local summary = V40.constraintSummary(descendant)
			constraints[descendant.Name] = summary
			if descendant.Parent and descendant.Parent:IsA("BasePart") and not constraints[descendant.Parent.Name] then
				constraints[descendant.Parent.Name] = summary
			end
		elseif descendant:IsA("Bone") then
			bones[descendant.Name] = { kind = "Bone", path = safeFullName(descendant), transform = serializeValue(descendant.Transform), pose = V40.cframePose(descendant.Transform) }
		end
	end
	return { at = isoNow(), version = VERSION, status = "ok", rig = { path = safeFullName(rig), id = getInstanceId(rig), rigType = V40.rigSummary(rig, false).rigType }, joints = joints, constraints = constraints, bones = bones, jointCount = V40.countMap(joints), animationConstraintCount = V40.countMap(constraints), boneCount = V40.countMap(bones) }
end

function V40.countMap(map)
	local count = 0
	for _ in pairs(map or {}) do count += 1 end
	return count
end

function V40.eulerCFrame(pose)
	if type(pose) ~= "table" then return CFrame.new() end
	if type(pose.cframe) == "table" then
		local cf = deserializeValue(pose.cframe)
		if typeof(cf) == "CFrame" then return cf end
	end
	if type(pose.transform) == "table" then
		local cf = deserializeValue(pose.transform)
		if typeof(cf) == "CFrame" then return cf end
	end
	local position = pose.position or { 0, 0, 0 }
	local rotation = pose.rotationEulerDegrees or pose.rotationDegrees or pose.rotation or { 0, 0, 0 }
	local px = tonumber(position[1] or position.x or 0) or 0
	local py = tonumber(position[2] or position.y or 0) or 0
	local pz = tonumber(position[3] or position.z or 0) or 0
	local rx = math.rad(tonumber(rotation[1] or rotation.x or 0) or 0)
	local ry = math.rad(tonumber(rotation[2] or rotation.y or 0) or 0)
	local rz = math.rad(tonumber(rotation[3] or rotation.z or 0) or 0)
	return CFrame.new(px, py, pz) * CFrame.Angles(rx, ry, rz)
end

function V40.normalizedTargetName(name)
	return tostring(name or ""):lower():gsub("[%s_%-%.]", "")
end

function V40.addPoseTarget(map, name, target)
	if not map or not target or tostring(name or "") == "" then
		return
	end
	local key = tostring(name)
	if not map.exact[key] then
		map.exact[key] = target
	end
	local normalized = V40.normalizedTargetName(key)
	if normalized ~= "" and not map.normalized[normalized] then
		map.normalized[normalized] = target
	end
end

function V40.poseTargetMap(rig)
	local map = { exact = {}, normalized = {}, list = {} }
	if not rig then
		return map
	end
	for _, descendant in ipairs(rig:GetDescendants()) do
		if descendant:IsA("Motor6D") then
			local target = { kind = "Motor6D", instance = descendant, name = descendant.Name }
			table.insert(map.list, target)
			V40.addPoseTarget(map, descendant.Name, target)
			if descendant.Part1 then V40.addPoseTarget(map, descendant.Part1.Name, target) end
			if descendant.Part0 then V40.addPoseTarget(map, descendant.Part0.Name, target) end
		elseif descendant:IsA("AnimationConstraint") then
			local attachment0 = V40.safeRead(descendant, "Attachment0")
			local attachment1 = V40.safeRead(descendant, "Attachment1")
			local part0 = V40.safeRead(descendant, "Part0") or (attachment0 and attachment0.Parent and attachment0.Parent:IsA("BasePart") and attachment0.Parent or nil)
			local part1 = V40.safeRead(descendant, "Part1") or (attachment1 and attachment1.Parent and attachment1.Parent:IsA("BasePart") and attachment1.Parent or nil)
			local target = { kind = "AnimationConstraint", instance = descendant, name = descendant.Name, part0 = part0, part1 = part1 }
			table.insert(map.list, target)
			V40.addPoseTarget(map, descendant.Name, target)
			if descendant.Parent and descendant.Parent:IsA("BasePart") then V40.addPoseTarget(map, descendant.Parent.Name, target) end
			if part1 then V40.addPoseTarget(map, part1.Name, target) end
			if part0 then V40.addPoseTarget(map, part0.Name, target) end
		elseif descendant:IsA("Bone") then
			local target = { kind = "Bone", instance = descendant, name = descendant.Name }
			table.insert(map.list, target)
			V40.addPoseTarget(map, descendant.Name, target)
		end
	end
	return map
end

function V40.resolvePoseTarget(map, name)
	if not map then return nil end
	return map.exact[tostring(name or "")] or map.normalized[V40.normalizedTargetName(name)]
end

function V40.poseTargetTransform(target)
	if not target or not target.instance then
		return CFrame.new(), false
	end
	local value = nil
	local ok = false
	if target.kind == "AnimationConstraint" then
		value, ok = V40.safeRead(target.instance, "Transform")
	else
		ok, value = pcall(function()
			return target.instance.Transform
		end)
	end
	if ok and typeof(value) == "CFrame" then
		return value, true
	end
	return CFrame.new(), false
end

function V40.writePoseTargetTransform(target, transform)
	if not target or not target.instance or typeof(transform) ~= "CFrame" then
		return false, "invalid target or transform"
	end
	if target.kind == "AnimationConstraint" then
		return V40.safeWrite(target.instance, "Transform", transform)
	end
	return pcall(function()
		target.instance.Transform = transform
	end)
end

function V40.poseTargetSummary(target)
	if not target or not target.instance then
		return nil
	end
	local transform = V40.poseTargetTransform(target)
	return {
		kind = target.kind,
		name = target.name or target.instance.Name,
		path = safeFullName(target.instance),
		part0 = target.part0 and V40.instanceInfo(target.part0) or nil,
		part1 = target.part1 and V40.instanceInfo(target.part1) or nil,
		transform = serializeValue(transform),
		pose = V40.cframePose(transform),
	}
end

function V40.applyRigPose(payload)
	payload = payload or {}
	local rig = V40.resolveRig(payload)
	if not rig then error("Rig was not found.") end
	local pose = payload.pose or payload.poseJson or payload
	if pose.resetPose == true then
		return V40.resetRigPose({ rigPath = safeFullName(rig) })
	end
	return withUndo("ApplyRigPose", function()
		local applied = {}
		local missing = {}
		local errors = {}
		local targets = V40.poseTargetMap(rig)
		local function applyMap(source)
			for name, value in pairs(source or {}) do
				local target = V40.resolvePoseTarget(targets, name)
				if target then
					local ok, err = V40.writePoseTargetTransform(target, V40.eulerCFrame(value))
					if ok then
						table.insert(applied, { name = name, target = V40.poseTargetSummary(target) })
					else
						table.insert(errors, { name = name, error = tostring(err or "Transform write failed") })
					end
				else
					table.insert(missing, name)
				end
			end
		end
		applyMap(pose.joints)
		applyMap(pose.constraints)
		applyMap(pose.bones)
		applyMap(pose.poses)
		stateDirty = true
		return { at = isoNow(), version = VERSION, status = (#missing == 0 and #errors == 0) and "applied" or "partial", rig = safeFullName(rig), applied = applied, missing = missing, errors = errors, pose = V40.getRigPose({ rigPath = safeFullName(rig) }) }
	end)
end

function V40.resetRigPose(payload)
	local rig = V40.resolveRig(payload)
	if not rig then error("Rig was not found.") end
	return withUndo("ResetRigPose", function()
		local count = 0
		local errors = {}
		for _, descendant in ipairs(rig:GetDescendants()) do
			if descendant:IsA("Motor6D") or descendant:IsA("Bone") or descendant:IsA("AnimationConstraint") then
				local ok, err = V40.writePoseTargetTransform({ kind = descendant.ClassName, instance = descendant, name = descendant.Name }, CFrame.new())
				if ok then
					count += 1
				else
					table.insert(errors, { path = safeFullName(descendant), error = tostring(err) })
				end
			end
		end
		stateDirty = true
		return { at = isoNow(), version = VERSION, status = #errors == 0 and "reset" or "partial", rig = safeFullName(rig), resetCount = count, errors = errors }
	end)
end

function V40.listAnimations(payload)
	payload = payload or {}
	local root = resolvePath(payload.path or payload.root or "ReplicatedStorage") or game:GetService("ReplicatedStorage")
	local items = {}
	if root:IsA("Animation") or root:IsA("KeyframeSequence") then
		table.insert(items, V40.animationSummary(root))
	end
	for _, descendant in ipairs(root:GetDescendants()) do
		if descendant:IsA("Animation") or descendant:IsA("KeyframeSequence") then
			table.insert(items, V40.animationSummary(descendant))
			if #items >= tonumber(payload.maxResults or 300) then break end
		end
	end
	return { at = isoNow(), version = VERSION, root = safeFullName(root), count = #items, animations = items, nextCommand = items[1] and ("tools\\bridge.cmd animation inspect \"" .. items[1].path .. "\"") or "tools\\bridge.cmd animation create <rigPath> <json-file>" }
end

function V40.poseToJson(pose)
	local children = {}
	for _, child in ipairs(pose:GetSubPoses()) do
		table.insert(children, V40.poseToJson(child))
	end
	return { name = pose.Name, cframe = serializeValue(pose.CFrame), easingStyle = tostring(pose.EasingStyle), easingDirection = tostring(pose.EasingDirection), weight = pose.Weight, children = children }
end

function V40.inspectAnimation(payload)
	payload = payload or {}
	local target = resolvePath(payload.animationPath or payload.path or "") or resolveInstance(payload.animationId or payload.id)
	if not target then
		return { at = isoNow(), version = VERSION, status = "notFound", error = "Animation target was not found.", requested = payload.animationPath or payload.path or payload.id }
	end
	if target:IsA("Animation") then
		return { at = isoNow(), version = VERSION, status = "animationReference", animation = V40.animationSummary(target), publishStatus = V40.getAnimationPublishStatus({ path = safeFullName(target) }) }
	end
	if not target:IsA("KeyframeSequence") then
		return { at = isoNow(), version = VERSION, status = "unsupported", target = { path = safeFullName(target), className = target.ClassName } }
	end
	local keyframes = {}
	local markers = {}
	for _, keyframe in ipairs(target:GetKeyframes()) do
		local poses = {}
		for _, pose in ipairs(keyframe:GetPoses()) do
			table.insert(poses, V40.poseToJson(pose))
		end
		local frameMarkers = {}
		for _, marker in ipairs(keyframe:GetMarkers()) do
			local markerInfo = { name = marker.Name, value = marker.Value, time = keyframe.Time }
			table.insert(frameMarkers, markerInfo)
			table.insert(markers, markerInfo)
		end
		table.insert(keyframes, { name = keyframe.Name, time = keyframe.Time, poses = poses, markers = frameMarkers })
	end
	table.sort(keyframes, function(a, b) return a.time < b.time end)
	return { at = isoNow(), version = VERSION, status = "ok", animation = V40.animationSummary(target), keyframes = keyframes, markers = markers, manifest = V40.getAnimationTimelineManifest({ path = safeFullName(target) }), nextCommand = "tools\\bridge.cmd animation preview <rigPath> \"" .. safeFullName(target) .. "\"" }
end

function V40.animationHash(sequence)
	if not sequence or not sequence:IsA("KeyframeSequence") then return nil end
	local ok, encoded = pcall(function()
		local keyframes = {}
		for _, keyframe in ipairs(sequence:GetKeyframes()) do
			local frame = { name = keyframe.Name, time = keyframe.Time, poses = {}, markers = {} }
			local function collectPose(pose)
				table.insert(frame.poses, { name = pose.Name, cframe = serializeValue(pose.CFrame), easingStyle = tostring(pose.EasingStyle), easingDirection = tostring(pose.EasingDirection), weight = pose.Weight })
				for _, child in ipairs(pose:GetSubPoses()) do
					collectPose(child)
				end
			end
			for _, pose in ipairs(keyframe:GetPoses()) do
				collectPose(pose)
			end
			for _, marker in ipairs(keyframe:GetMarkers()) do
				table.insert(frame.markers, { name = marker.Name, value = marker.Value })
			end
			table.insert(keyframes, frame)
		end
		table.sort(keyframes, function(a, b) return a.time < b.time end)
		return HttpService:JSONEncode(keyframes)
	end)
	return sourceHash(ok and encoded or safeFullName(sequence))
end

function V40.findPoseTargetNames(rig)
	local names = {}
	if not rig then return names end
	local map = V40.poseTargetMap(rig)
	for name in pairs(map.exact or {}) do
		names[name] = true
	end
	for name in pairs(map.normalized or {}) do
		names[name] = true
	end
	return names
end

function V40.isFiniteNumber(value)
	local number = tonumber(value)
	return number ~= nil and number == number and number ~= math.huge and number ~= -math.huge
end

function V40.validateVector(values)
	if values == nil then return true end
	if type(values) ~= "table" then return false end
	for i = 1, 3 do
		local key = ({ "x", "y", "z" })[i]
		if not V40.isFiniteNumber(values[i] or values[key] or 0) then
			return false
		end
	end
	return true
end

function V40.validateAnimationSpec(payload)
	payload = payload or {}
	local spec = payload.animation or payload.spec or payload
	local rig = V40.resolveRig(payload)
	local errors = {}
	local warnings = {}
	local length = tonumber(spec.length or spec.Length or 0) or 0
	if tostring(spec.animationName or spec.name or "") == "" then table.insert(errors, "animationName is required.") end
	if length <= 0 then table.insert(errors, "length must be greater than 0.") end
	if spec.priority and not Enum.AnimationPriority[tostring(spec.priority)] then table.insert(errors, "Invalid AnimationPriority: " .. tostring(spec.priority)) end
	local targetMap = V40.poseTargetMap(rig)
	for index, keyframe in ipairs(spec.keyframes or {}) do
		local time = tonumber(keyframe.time)
		if not time or time < 0 or (length > 0 and time > length) then table.insert(errors, "Keyframe " .. tostring(index) .. " has invalid/out-of-range time.") end
		for poseName, pose in pairs(keyframe.poses or {}) do
			if rig and not V40.resolvePoseTarget(targetMap, poseName) then table.insert(errors, "Pose target does not exist on rig: " .. tostring(poseName)) end
			for _, listName in ipairs({ "rotation", "rotationEulerDegrees", "rotationDegrees", "position" }) do
				local values = pose[listName]
				if values and not V40.validateVector(values) then
					table.insert(errors, "Pose " .. tostring(poseName) .. " has invalid " .. listName .. ".")
				end
			end
		end
	end
	for _, marker in ipairs(spec.markers or {}) do
		local time = tonumber(marker.time)
		if tostring(marker.name or "") == "" then table.insert(errors, "Marker name is required.") end
		if not time or time < 0 or (length > 0 and time > length) then table.insert(errors, "Marker " .. tostring(marker.name or "?") .. " has invalid/out-of-range time.") end
	end
	if not rig then table.insert(warnings, "No rig supplied; joint/bone names were not validated.") end
	return { at = isoNow(), version = VERSION, valid = #errors == 0, errors = errors, warnings = warnings, rig = rig and safeFullName(rig) or nil, rigType = rig and V40.rigSummary(rig, false).rigType or nil, keyframeCount = #(spec.keyframes or {}), markerCount = #(spec.markers or {}), poseTargetCount = #(targetMap.list or {}) }
end

function V40.poseEnum(enumRoot, value, fallback)
	if not enumRoot then return fallback end
	value = tostring(value or "")
	if enumRoot[value] then return enumRoot[value] end
	value = value:gsub("^Enum%.%w+%.", "")
	if enumRoot[value] then return enumRoot[value] end
	return fallback
end

function V40.canonicalPoseName(name)
	local map = {
		Root = "HumanoidRootPart",
		RootJoint = "LowerTorso",
		Waist = "UpperTorso",
		Neck = "Head",
		RightShoulder = "RightUpperArm",
		RightElbow = "RightLowerArm",
		RightWrist = "RightHand",
		LeftShoulder = "LeftUpperArm",
		LeftElbow = "LeftLowerArm",
		LeftWrist = "LeftHand",
		RightHip = "RightUpperLeg",
		RightKnee = "RightLowerLeg",
		RightAnkle = "RightFoot",
		LeftHip = "LeftUpperLeg",
		LeftKnee = "LeftLowerLeg",
		LeftAnkle = "LeftFoot",
	}
	return map[tostring(name or "")] or tostring(name or "")
end

function V40.poseParentName(name)
	local parents = {
		LowerTorso = "HumanoidRootPart",
		UpperTorso = "LowerTorso",
		Head = "UpperTorso",
		RightUpperArm = "UpperTorso",
		RightLowerArm = "RightUpperArm",
		RightHand = "RightLowerArm",
		LeftUpperArm = "UpperTorso",
		LeftLowerArm = "LeftUpperArm",
		LeftHand = "LeftLowerArm",
		RightUpperLeg = "LowerTorso",
		RightLowerLeg = "RightUpperLeg",
		RightFoot = "RightLowerLeg",
		LeftUpperLeg = "LowerTorso",
		LeftLowerLeg = "LeftUpperLeg",
		LeftFoot = "LeftLowerLeg",
	}
	return parents[tostring(name or "")]
end

function V40.ensurePose(parent, posesByName, poseName)
	poseName = V40.canonicalPoseName(poseName)
	if posesByName[poseName] then
		return posesByName[poseName]
	end
	local container = parent
	local parentName = V40.poseParentName(poseName)
	if parentName then
		container = V40.ensurePose(parent, posesByName, parentName)
	end
	local pose = Instance.new("Pose")
	pose.Name = poseName
	pose.CFrame = CFrame.new()
	pose.Parent = container
	posesByName[poseName] = pose
	return pose
end

function V40.buildSequence(spec, rig)
	local validation = V40.validateAnimationSpec({ animation = spec, rigPath = rig and safeFullName(rig) or nil })
	if not validation.valid then error("Invalid animation spec: " .. table.concat(validation.errors, "; ")) end
	local sequence = Instance.new("KeyframeSequence")
	sequence.Name = V40.safeAnimationName(spec.animationName or spec.name or "GeneratedAnimation")
	sequence.Loop = spec.looped == true or spec.loop == true
	sequence.Priority = V40.poseEnum(Enum.AnimationPriority, spec.priority or "Action", Enum.AnimationPriority.Action)
	local keyframesByTime = {}
	local function getKeyframe(time)
		local key = string.format("%.4f", tonumber(time) or 0)
		if keyframesByTime[key] then return keyframesByTime[key] end
		local keyframe = Instance.new("Keyframe")
		keyframe.Name = "t" .. key
		keyframe.Time = tonumber(time) or 0
		keyframe.Parent = sequence
		keyframesByTime[key] = keyframe
		return keyframe
	end
	for _, frame in ipairs(spec.keyframes or {}) do
		local keyframe = getKeyframe(frame.time)
		local posesByName = {}
		for poseName, poseSpec in pairs(frame.poses or {}) do
			local pose = V40.ensurePose(keyframe, posesByName, poseName)
			pose.CFrame = V40.eulerCFrame(poseSpec)
			pose.EasingStyle = V40.poseEnum(Enum.PoseEasingStyle, poseSpec.easingStyle or frame.easingStyle or "Linear", Enum.PoseEasingStyle.Linear)
			pose.EasingDirection = V40.poseEnum(Enum.PoseEasingDirection, poseSpec.easingDirection or frame.easingDirection or "Out", Enum.PoseEasingDirection.Out)
			pose.Weight = tonumber(poseSpec.weight or 1) or 1
		end
	end
	for _, markerSpec in ipairs(spec.markers or {}) do
		local marker = Instance.new("KeyframeMarker")
		marker.Name = tostring(markerSpec.name)
		marker.Value = tostring(markerSpec.value or markerSpec.name or "")
		marker.Parent = getKeyframe(markerSpec.time)
	end
	getKeyframe(tonumber(spec.length) or 0)
	return sequence
end

function V40.safeAnimationName(name)
	local text = tostring(name or "GeneratedAnimation"):gsub("[^%w_%-]", "_")
	if text == "" then text = "GeneratedAnimation" end
	return text
end

function V40.generatedFolder()
	local storage = game:GetService("ReplicatedStorage")
	local folder = storage:FindFirstChild("GeneratedAnimations")
	if not folder then
		folder = Instance.new("Folder")
		folder.Name = "GeneratedAnimations"
		folder.Parent = storage
	end
	return folder
end

function V40.nextVersionName(folder, baseName)
	local index = 1
	while true do
		local candidate = string.format("%s_v%03d", baseName, index)
		if not folder:FindFirstChild(candidate) then return candidate end
		index += 1
	end
end

function V40.manifestSource(folder)
	local entries = {}
	for _, child in ipairs(folder:GetChildren()) do
		if child:IsA("KeyframeSequence") then
			table.insert(entries, V40.getAnimationTimelineManifest({ path = safeFullName(child) }))
		end
	end
	return "return { format = \"codex-animation-manifest-v1\", version = " .. V8.luaString(VERSION) .. ", generatedAt = " .. V8.luaString(isoNow()) .. ", json = " .. V8.luaString(HttpService:JSONEncode(entries)) .. " }\n"
end

function V40.saveGeneratedAnimation(payload)
	payload = payload or {}
	local spec = payload.animation or payload.spec or payload
	local rig = V40.resolveRig(payload)
	return withUndo("SaveGeneratedAnimation", function()
		local folder = V40.generatedFolder()
		local baseName = V40.safeAnimationName(spec.animationName or spec.name or "GeneratedAnimation")
		local versionName = V40.nextVersionName(folder, baseName)
		local sequence = V40.buildSequence(spec, rig)
		sequence.Name = versionName
		sequence.Parent = folder
		local metadata = Instance.new("StringValue")
		metadata.Name = "CodexMetadata"
		metadata.Value = HttpService:JSONEncode({ generatedAt = isoNow(), version = VERSION, sourceName = baseName, rigPath = rig and safeFullName(rig) or nil, spec = spec })
		metadata.Parent = sequence
		local manifest = folder:FindFirstChild("AnimationManifest")
		if not manifest then
			manifest = Instance.new("ModuleScript")
			manifest.Name = "AnimationManifest"
			manifest.Parent = folder
		end
		updateScriptSource(manifest, V40.manifestSource(folder))
		stateDirty = true
		local result = { at = isoNow(), version = VERSION, status = "saved", path = safeFullName(sequence), name = sequence.Name, hash = V40.animationHash(sequence), manifestPath = safeFullName(manifest), timeline = V40.getAnimationTimelineManifest({ path = safeFullName(sequence) }) }
		V40.last.saved = result
		return result
	end)
end

function V40.editGeneratedAnimation(payload)
	payload = payload or {}
	local target = resolvePath(payload.animationPath or payload.path or "")
	if not target or not target:IsA("KeyframeSequence") then error("editGeneratedAnimation requires a KeyframeSequence path.") end
	local expected = payload.expectedHash or payload.expectedAnimationHash
	if expected and expected ~= V40.animationHash(target) then error("Animation hash is stale; refusing edit.") end
	local spec = payload.animation or payload.spec or payload.patch
	if type(spec) ~= "table" then error("editGeneratedAnimation requires animation/spec/patch JSON.") end
	spec.animationName = spec.animationName or target.Name:gsub("_v%d%d%d$", "")
	return V40.saveGeneratedAnimation({ animation = spec, rigPath = payload.rigPath })
end

function V40.timelineForSequence(target)
	local markers = {}
	local soundCues = {}
	local vfxCues = {}
	local length = 0
	for _, keyframe in ipairs(target:GetKeyframes()) do
		if keyframe.Time > length then length = keyframe.Time end
		for _, marker in ipairs(keyframe:GetMarkers()) do
			markers[marker.Name] = keyframe.Time
			local lower = string.lower(marker.Name)
			if lower:find("sound", 1, true) or lower:find("cue", 1, true) then soundCues[marker.Name] = keyframe.Time end
			if lower:find("vfx", 1, true) or lower:find("impact", 1, true) or lower:find("fire", 1, true) then vfxCues[marker.Name] = keyframe.Time end
		end
	end
	return { Animation = target.Name, Path = target.Parent and safeFullName(target) or nil, Length = length, Loop = target.Loop, Priority = tostring(target.Priority), Markers = markers, SoundCues = soundCues, VFXCues = vfxCues, Hash = V40.animationHash(target) }
end

function V40.getAnimationTimelineManifest(payload)
	payload = payload or {}
	local target = resolvePath(payload.animationPath or payload.path or "")
	if not target or not target:IsA("KeyframeSequence") then
		return { at = isoNow(), version = VERSION, status = "notFound", requested = payload.animationPath or payload.path }
	end
	local manifest = V40.timelineForSequence(target)
	manifest.at = isoNow()
	manifest.version = VERSION
	manifest.status = "ok"
	return manifest
end

function V40.findAnimator(rig, createIfMissing)
	local humanoid = rig and rig:FindFirstChildOfClass("Humanoid")
	local controller = rig and rig:FindFirstChildOfClass("AnimationController")
	if humanoid then
		local animator = humanoid:FindFirstChildOfClass("Animator")
		if not animator and createIfMissing then
			animator = Instance.new("Animator")
			animator.Parent = humanoid
		end
		return animator
	end
	if not controller and createIfMissing then
		controller = Instance.new("AnimationController")
		controller.Name = "CodexAnimationController"
		controller.Parent = rig
	end
	if controller then
		local animator = controller:FindFirstChildOfClass("Animator")
		if not animator and createIfMissing then
			animator = Instance.new("Animator")
			animator.Parent = controller
		end
		return animator
	end
	return nil
end

function V40.sequenceFromPayload(payload)
	local target = resolvePath(payload.animationPath or payload.path or "")
	if target and target:IsA("KeyframeSequence") then return target end
	if type(payload.animation) == "table" or type(payload.spec) == "table" then
		return V40.buildSequence(payload.animation or payload.spec, V40.resolveRig(payload))
	end
	return nil
end

function V40.previewAnimation(payload)
	payload = payload or {}
	local rig = V40.resolveRig(payload)
	if not rig then error("Rig was not found.") end
	local sequence = V40.sequenceFromPayload(payload)
	if not sequence then error("Animation KeyframeSequence/spec was not found.") end
	return withUndo("PreviewAnimation", function()
		local animator = V40.findAnimator(rig, true)
		if not animator then error("Rig has no Humanoid/AnimationController Animator path.") end
		local okProvider, provider = pcall(function() return game:GetService("KeyframeSequenceProvider") end)
		if not okProvider or not provider then error("KeyframeSequenceProvider unavailable.") end
		local animationId = nil
		local okRegister, registerError = pcall(function()
			animationId = provider:RegisterKeyframeSequence(sequence)
		end)
		if not okRegister then error("Could not register temporary animation: " .. tostring(registerError)) end
		local animation = Instance.new("Animation")
		animation.Name = "CodexPreview_" .. sequence.Name
		animation.AnimationId = animationId
		animation.Parent = rig
		local track = animator:LoadAnimation(animation)
		track.Looped = payload.looped == true or sequence.Loop
		track.Priority = sequence.Priority
		track:Play(tonumber(payload.fadeTime or 0.1) or 0.1, 1, tonumber(payload.speed or 1) or 1)
		local key = safeFullName(rig)
		V40.tracks[key] = { track = track, animation = animation, sequence = sequence, startedAt = isoNow() }
		local timeline = V40.timelineForSequence(sequence)
		local result = { at = isoNow(), version = VERSION, status = "previewing", rig = key, animationPath = sequence.Parent and safeFullName(sequence) or sequence.Name, temporaryAnimationId = tostring(animationId), track = { length = track.Length, timePosition = track.TimePosition, speed = tonumber(payload.speed or 1) or 1 }, markers = timeline.Markers, timeline = timeline }
		V40.last.preview = result
		return result
	end)
end

function V40.scrubAnimationPreview(payload)
	payload = payload or {}
	local rig = V40.resolveRig(payload)
	if not rig then error("Rig was not found.") end
	local timePosition = tonumber(payload.time or payload.seconds or 0) or 0
	local key = safeFullName(rig)
	local preview = V40.tracks[key]
	if preview and preview.track then
		pcall(function()
			preview.track.TimePosition = timePosition
			preview.track:AdjustSpeed(0)
		end)
		return { at = isoNow(), version = VERSION, status = "scrubbedTrack", rig = key, time = timePosition, track = { timePosition = preview.track.TimePosition, length = preview.track.Length } }
	end
	local sequence = V40.sequenceFromPayload(payload)
	if sequence then
		return V40.applyNearestKeyframePose(rig, sequence, timePosition)
	end
	return { at = isoNow(), version = VERSION, status = "notPreviewing", rig = key, time = timePosition, message = "No preview track was active; provide an animationPath to apply nearest keyframe pose." }
end

function V40.applyNearestKeyframePose(rig, sequence, timePosition)
	local keyframes = sequence:GetKeyframes()
	table.sort(keyframes, function(a, b) return a.Time < b.Time end)
	local previousFrame = nil
	local nextFrame = nil
	local nearest = nil
	for _, keyframe in ipairs(keyframes) do
		if keyframe.Time <= timePosition then previousFrame = keyframe end
		if not nextFrame and keyframe.Time >= timePosition then nextFrame = keyframe end
		if not nearest or math.abs(keyframe.Time - timePosition) < math.abs(nearest.Time - timePosition) then nearest = keyframe end
	end
	for _, keyframe in ipairs(sequence:GetKeyframes()) do
		if not nearest or math.abs(keyframe.Time - timePosition) < math.abs(nearest.Time - timePosition) then
			nearest = keyframe
		end
	end
	if not nearest then return { at = isoNow(), version = VERSION, status = "noKeyframes" } end
	local function poseMap(frame)
		local map = {}
		local function collect(poseInstance)
			map[poseInstance.Name] = poseInstance.CFrame
			for _, child in ipairs(poseInstance:GetSubPoses()) do collect(child) end
		end
		for _, poseInstance in ipairs(frame:GetPoses()) do collect(poseInstance) end
		return map
	end
	local selected = {}
	local previousMap = previousFrame and poseMap(previousFrame) or {}
	local nextMap = nextFrame and poseMap(nextFrame) or {}
	local alpha = 0
	if previousFrame and nextFrame and nextFrame ~= previousFrame and nextFrame.Time > previousFrame.Time then
		alpha = math.clamp((timePosition - previousFrame.Time) / (nextFrame.Time - previousFrame.Time), 0, 1)
	end
	for name, cf in pairs(previousMap) do
		if nextMap[name] and typeof(cf) == "CFrame" and typeof(nextMap[name]) == "CFrame" then
			selected[name] = cf:Lerp(nextMap[name], alpha)
		else
			selected[name] = cf
		end
	end
	for name, cf in pairs(nextMap) do
		if not selected[name] then
			selected[name] = cf
		end
	end
	if next(selected) == nil then
		selected = poseMap(nearest)
	end
	local pose = { poses = {} }
	for name, cf in pairs(selected) do
		pose.poses[name] = { cframe = serializeValue(cf) }
	end
	local result = V40.applyRigPose({ rigPath = safeFullName(rig), pose = pose })
	result.status = "scrubbedInterpolatedPose"
	result.time = timePosition
	result.previousKeyframeTime = previousFrame and previousFrame.Time or nil
	result.nextKeyframeTime = nextFrame and nextFrame.Time or nil
	result.nearestKeyframeTime = nearest.Time
	return result
end

function V40.stopAnimationPreview(payload)
	local rig = V40.resolveRig(payload)
	local key = rig and safeFullName(rig) or tostring(payload and (payload.rigPath or payload.path) or "")
	local preview = V40.tracks[key]
	if preview and preview.track then pcall(function() preview.track:Stop(tonumber(payload.fadeTime or 0.1) or 0.1) end) end
	if preview and preview.animation then pcall(function() preview.animation:Destroy() end) end
	V40.tracks[key] = nil
	return { at = isoNow(), version = VERSION, status = "stopped", rig = key }
end

function V40.getAnimationPreviewStatus(payload)
	local paths = {
		"ReplicatedStorage.CodexAnimationWorkbench",
		"ReplicatedStorage.GeneratedAnimations",
		"ReplicatedStorage.GeneratedAnimations.AnimationManifest",
	}
	local installed = 0
	local entries = {}
	for _, path in ipairs(paths) do
		local instance = resolvePath(path)
		if instance then installed += 1 end
		table.insert(entries, { path = path, exists = instance ~= nil, className = instance and instance.ClassName or nil })
	end
	local active = {}
	for rigPath, preview in pairs(V40.tracks) do
		table.insert(active, { rigPath = rigPath, animation = preview.sequence and safeFullName(preview.sequence) or nil, startedAt = preview.startedAt })
	end
	return { at = isoNow(), version = VERSION, installed = installed >= 1, status = installed >= 1 and "installed" or "missing", installedCount = installed, paths = entries, activePreviewCount = #active, activePreviews = active, nextCommand = installed >= 1 and "tools\\bridge.cmd animation report" or "tools\\bridge.cmd animation harness install" }
end

function V40.getAnimationCaptureReport(payload)
	return { at = isoNow(), version = VERSION, status = "structuredFallback", camera = V25.getCameraViewReport and V25.getCameraViewReport(payload or {}) or nil, capture = V25.getVisualCaptureReport and V25.getVisualCaptureReport(payload or {}) or nil, preview = V40.getAnimationPreviewStatus(payload or {}), message = "Animation capture uses existing live-vision/camera capture when supported; structured rig/pose data is always returned." }
end

function V40.rigViewFrame(rig, payload)
	payload = payload or {}
	local centerCFrame, size = rig:GetBoundingBox()
	local center = centerCFrame.Position
	local radius = math.max(size.X, size.Y, size.Z, 6)
	local distance = tonumber(payload.distance) or radius * 2.4
	local height = tonumber(payload.height) or math.max(size.Y * 0.2, 2)
	local angle = tostring(payload.angle or "threeQuarterFront")
	local directions = {
		front = Vector3.new(0, 0, distance),
		back = Vector3.new(0, 0, -distance),
		left = Vector3.new(-distance, 0, 0),
		right = Vector3.new(distance, 0, 0),
		threeQuarterFront = Vector3.new(distance * 0.7, 0, distance * 0.7),
		threeQuarterBack = Vector3.new(-distance * 0.7, 0, -distance * 0.7),
		top = Vector3.new(0, distance, 0.01),
	}
	local offset = directions[angle] or directions.threeQuarterFront
	local lookAtOffset = V36.vectorFromPayload and V36.vectorFromPayload(payload.lookAtOffset, Vector3.new(0, height, 0)) or Vector3.new(0, height, 0)
	local lookAt = center + lookAtOffset
	local position = center + offset + Vector3.new(0, height, 0)
	if angle == "top" then
		position = center + offset
	end
	return {
		angle = angle,
		center = serializeValue(center),
		size = serializeValue(size),
		position = serializeValue(position),
		lookAt = serializeValue(lookAt),
		cframe = serializeValue(CFrame.lookAt(position, lookAt)),
	}
end

function V40.captureAnimationPreview(payload)
	payload = payload or {}
	local rig = V40.resolveRig(payload)
	local framing = nil
	local cameraStatus = "notApplied"
	if rig then
		framing = V40.rigViewFrame(rig, payload)
		local camera = workspace.CurrentCamera
		if camera and framing and framing.cframe then
			local cf = deserializeValue(framing.cframe)
			if typeof(cf) == "CFrame" then
				camera.CFrame = cf
				camera.Focus = CFrame.new(cf.Position + cf.LookVector * 12)
				cameraStatus = "framed"
			end
		end
	end
	return { at = isoNow(), version = VERSION, status = "captureRequestedBestEffort", cameraStatus = cameraStatus, rig = rig and safeFullName(rig) or nil, framing = framing, capture = V40.getAnimationCaptureReport(payload or {}), pose = V40.getRigPose(payload or {}) }
end

function V40.getAnimationPublishStatus(payload)
	return { at = isoNow(), version = VERSION, status = "manualRequired", supported = "bestEffortPromptOnly", message = "StudioBridge can save KeyframeSequences and manifest data. Publishing animation assets requires Roblox Studio/creator confirmation; use Save to Roblox manually if no supported prompt is available.", nextCommand = "Right-click the KeyframeSequence under ReplicatedStorage.GeneratedAnimations, then Save to Roblox." }
end

function V40.requestPublishAnimation(payload)
	return { at = isoNow(), version = VERSION, status = "manualRequired", animationPath = payload and (payload.animationPath or payload.path) or nil, publish = V40.getAnimationPublishStatus(payload or {}) }
end

function V40.animationWorkbenchBlueprint(payload)
	return {
		name = "Codex Animation Workbench Harness",
		mode = "supervised",
		source = "installAnimationWorkbenchHarness",
		steps = {
			{ type = "ensureFolder", path = "ReplicatedStorage.CodexAnimationWorkbench" },
			{ type = "ensureFolder", path = "ReplicatedStorage.GeneratedAnimations" },
			V25.scriptWriteStep("ReplicatedStorage.CodexAnimationWorkbench.Manifest", "ModuleScript", "return { name = \"CodexAnimationWorkbench\", version = \"" .. VERSION .. "\", purpose = \"universal rig inspection, KeyframeSequence authoring, preview, marker, and manifest tooling\" }\n"),
			V25.scriptWriteStep("ReplicatedStorage.GeneratedAnimations.AnimationManifest", "ModuleScript", "return {}\n"),
		},
	}
end

function V40.installAnimationWorkbenchHarness(payload)
	local result = applyBuildPlan({ blueprint = V40.animationWorkbenchBlueprint(payload or {}) })
	result.kind = "animationWorkbenchInstall"
	result.status = V40.getAnimationPreviewStatus(payload)
	return result
end

function V40.removeAnimationWorkbenchHarness(payload)
	return withUndo("RemoveAnimationWorkbenchHarness", function()
		local result = { at = isoNow(), version = VERSION, removed = {}, missing = {} }
		for _, path in ipairs({ "ReplicatedStorage.CodexAnimationWorkbench" }) do
			local instance = resolvePath(path)
			if instance then
				instance:Destroy()
				table.insert(result.removed, path)
			else
				table.insert(result.missing, path)
			end
		end
		stateDirty = true
		return result
	end)
end

function V40.getAnimationWorkbenchReport(payload)
	return {
		at = isoNow(),
		version = VERSION,
		status = V40.getAnimationPreviewStatus(payload or {}),
		rigs = V40.getAnimationRigInventory(payload or {}),
		animations = V40.listAnimations({ path = "ReplicatedStorage.GeneratedAnimations" }),
		capture = V40.getAnimationCaptureReport(payload or {}),
		publish = V40.getAnimationPublishStatus(payload or {}),
		nextCommand = "tools\\bridge.cmd animation list-rigs Workspace",
	}
end

-- V42 Professional Animation Director: intent generation, polish, audit, retime, mirror, and compare.
V42.styleCatalog = {
	realistic = { id = "realistic", title = "Realistic", lengthScale = 1.05, exaggeration = 0.85, easing = "Sine", direction = "InOut", notes = "grounded arcs, readable weight, restrained overshoot" },
	snappy = { id = "snappy", title = "Snappy", lengthScale = 0.78, exaggeration = 1.1, easing = "Cubic", direction = "Out", notes = "fast anticipation, crisp impact, short recovery" },
	anime = { id = "anime", title = "Anime", lengthScale = 0.92, exaggeration = 1.45, easing = "Quint", direction = "Out", notes = "strong silhouettes, held impact frames, big follow-through" },
	cartoony = { id = "cartoony", title = "Cartoony", lengthScale = 1.0, exaggeration = 1.35, easing = "Back", direction = "Out", notes = "squash/stretch feel, broad arcs, playful recovery" },
	heavy = { id = "heavy", title = "Heavy", lengthScale = 1.2, exaggeration = 1.15, easing = "Quad", direction = "InOut", notes = "slow windup, grounded torso, weighty recovery" },
	floaty = { id = "floaty", title = "Floaty", lengthScale = 1.35, exaggeration = 0.75, easing = "Sine", direction = "InOut", notes = "smooth drift, soft transitions, light impact" },
	robotic = { id = "robotic", title = "Robotic", lengthScale = 0.95, exaggeration = 0.9, easing = "Linear", direction = "Out", notes = "stepped mechanical posing and precise stops" },
	cinematic = { id = "cinematic", title = "Cinematic", lengthScale = 1.18, exaggeration = 1.25, easing = "Quart", direction = "InOut", notes = "clear staging, camera-friendly holds, dramatic timing" },
}

V42.kindCatalog = {
	idle = { id = "idle", title = "Idle", length = 2.2, looped = true, priority = "Idle" },
	walk = { id = "walk", title = "Walk", length = 1.0, looped = true, priority = "Movement" },
	run = { id = "run", title = "Run", length = 0.72, looped = true, priority = "Movement" },
	jump = { id = "jump", title = "Jump", length = 0.85, looped = false, priority = "Action" },
	emote = { id = "emote", title = "Emote", length = 1.8, looped = false, priority = "Action" },
	combatSlash = { id = "combatSlash", title = "Combat Slash", length = 0.95, looped = false, priority = "Action4" },
	projectileCast = { id = "projectileCast", title = "Projectile Cast", length = 1.35, looped = false, priority = "Action4" },
	abilityCharge = { id = "abilityCharge", title = "Ability Charge", length = 1.6, looped = false, priority = "Action4" },
	hitReaction = { id = "hitReaction", title = "Hit Reaction", length = 0.75, looped = false, priority = "Action3" },
	death = { id = "death", title = "Death", length = 1.45, looped = false, priority = "Action4" },
	cutsceneBeat = { id = "cutsceneBeat", title = "Cutscene Beat", length = 2.0, looped = false, priority = "Action" },
}

function V42.lowerText(value)
	return tostring(value or ""):lower()
end

function V42.getAnimationStyleCatalog(payload)
	local styles = {}
	for _, style in pairs(V42.styleCatalog) do
		table.insert(styles, style)
	end
	table.sort(styles, function(a, b) return a.id < b.id end)
	local kinds = {}
	for _, kind in pairs(V42.kindCatalog) do
		table.insert(kinds, kind)
	end
	table.sort(kinds, function(a, b) return a.id < b.id end)
	return {
		at = isoNow(),
		version = VERSION,
		status = "ok",
		styles = styles,
		animationTypes = kinds,
		phases = { "anticipation", "action", "impact", "followThrough", "recovery" },
		nextCommand = "tools\\bridge.cmd animation generate <rigPath> \"anime heavy projectile cast\"",
	}
end

function V42.inferStyle(intent)
	local lower = V42.lowerText(intent)
	for id in pairs(V42.styleCatalog) do
		if lower:find(id, 1, true) then
			return id
		end
	end
	if lower:find("fast", 1, true) or lower:find("crisp", 1, true) then return "snappy" end
	if lower:find("big", 1, true) or lower:find("dramatic", 1, true) then return "cinematic" end
	if lower:find("weight", 1, true) or lower:find("slam", 1, true) then return "heavy" end
	return "snappy"
end

function V42.inferKind(intent)
	local lower = V42.lowerText(intent)
	if lower:find("kame", 1, true) or lower:find("blast", 1, true) or lower:find("beam", 1, true) or lower:find("projectile", 1, true) or lower:find("fire", 1, true) then return "projectileCast" end
	if lower:find("slash", 1, true) or lower:find("sword", 1, true) or lower:find("melee", 1, true) or lower:find("punch", 1, true) then return "combatSlash" end
	if lower:find("charge", 1, true) or lower:find("power", 1, true) then return "abilityCharge" end
	if lower:find("hit", 1, true) or lower:find("damage", 1, true) or lower:find("flinch", 1, true) then return "hitReaction" end
	if lower:find("death", 1, true) or lower:find("fall", 1, true) then return "death" end
	if lower:find("run", 1, true) then return "run" end
	if lower:find("walk", 1, true) then return "walk" end
	if lower:find("jump", 1, true) then return "jump" end
	if lower:find("idle", 1, true) then return "idle" end
	if lower:find("emote", 1, true) or lower:find("dance", 1, true) then return "emote" end
	if lower:find("cutscene", 1, true) or lower:find("cinematic", 1, true) then return "cutsceneBeat" end
	return "projectileCast"
end

function V42.rigFamily(rig)
	local summary = rig and V40.rigSummary(rig, false) or nil
	local rigType = summary and tostring(summary.rigType or "") or ""
	if rigType:find("R6", 1, true) then
		return "R6"
	end
	return "R15"
end

function V42.roundTime(value)
	return math.floor((tonumber(value) or 0) * 1000 + 0.5) / 1000
end

function V42.scaled(value, amount)
	return V42.roundTime((tonumber(value) or 0) * (tonumber(amount) or 1))
end

function V42.pose(rotation, position, easingStyle, easingDirection)
	return {
		rotation = rotation,
		rotationEulerDegrees = rotation,
		position = position,
		easingStyle = easingStyle,
		easingDirection = easingDirection,
	}
end

function V42.addPose(poses, name, rotation, amount, position, easingStyle, easingDirection)
	local scaled = {}
	for index = 1, 3 do
		scaled[index] = V42.scaled(rotation[index] or 0, amount)
	end
	poses[name] = V42.pose(scaled, position, easingStyle, easingDirection)
end

function V42.r15Pose(kind, phase, amount, style)
	local poses = {}
	local easing = style.easing
	local direction = style.direction
	if kind == "projectileCast" or kind == "abilityCharge" then
		if phase == "anticipation" then
			V42.addPose(poses, "UpperTorso", { -8, 0, 0 }, amount, nil, easing, "Out")
			V42.addPose(poses, "RightUpperArm", { -42, 22, 48 }, amount, nil, easing, "Out")
			V42.addPose(poses, "LeftUpperArm", { -42, -22, -48 }, amount, nil, easing, "Out")
			V42.addPose(poses, "RightLowerArm", { -38, 0, 0 }, amount, nil, easing, "Out")
			V42.addPose(poses, "LeftLowerArm", { -38, 0, 0 }, amount, nil, easing, "Out")
			V42.addPose(poses, "Head", { -4, 0, 0 }, amount, nil, easing, "Out")
		elseif phase == "action" then
			V42.addPose(poses, "UpperTorso", { -13, 0, 0 }, amount, nil, easing, direction)
			V42.addPose(poses, "RightUpperArm", { -84, 7, 20 }, amount, nil, easing, direction)
			V42.addPose(poses, "LeftUpperArm", { -84, -7, -20 }, amount, nil, easing, direction)
			V42.addPose(poses, "RightLowerArm", { -8, 0, 0 }, amount, nil, easing, direction)
			V42.addPose(poses, "LeftLowerArm", { -8, 0, 0 }, amount, nil, easing, direction)
			V42.addPose(poses, "RightHand", { -3, 0, 0 }, amount, nil, easing, direction)
			V42.addPose(poses, "LeftHand", { -3, 0, 0 }, amount, nil, easing, direction)
		elseif phase == "impact" then
			V42.addPose(poses, "UpperTorso", { -16, 0, 0 }, amount, nil, "Quad", "Out")
			V42.addPose(poses, "RightUpperArm", { -88, 4, 17 }, amount, nil, "Quad", "Out")
			V42.addPose(poses, "LeftUpperArm", { -88, -4, -17 }, amount, nil, "Quad", "Out")
			V42.addPose(poses, "Head", { -9, 0, 0 }, amount, nil, "Quad", "Out")
		elseif phase == "followThrough" then
			V42.addPose(poses, "UpperTorso", { -7, 0, 0 }, amount, nil, "Sine", "InOut")
			V42.addPose(poses, "RightUpperArm", { -46, 16, 32 }, amount, nil, "Sine", "InOut")
			V42.addPose(poses, "LeftUpperArm", { -46, -16, -32 }, amount, nil, "Sine", "InOut")
		end
	elseif kind == "combatSlash" then
		if phase == "anticipation" then
			V42.addPose(poses, "UpperTorso", { 0, 18, -8 }, amount, nil, easing, "Out")
			V42.addPose(poses, "RightUpperArm", { -28, 58, 62 }, amount, nil, easing, "Out")
			V42.addPose(poses, "RightLowerArm", { -54, 0, 12 }, amount, nil, easing, "Out")
			V42.addPose(poses, "LeftUpperArm", { -18, -18, -22 }, amount, nil, easing, "Out")
		elseif phase == "action" then
			V42.addPose(poses, "UpperTorso", { -4, -24, 9 }, amount, nil, easing, direction)
			V42.addPose(poses, "RightUpperArm", { -64, -32, -38 }, amount, nil, easing, direction)
			V42.addPose(poses, "RightLowerArm", { -16, 0, -14 }, amount, nil, easing, direction)
			V42.addPose(poses, "LeftUpperArm", { -22, 18, 18 }, amount, nil, easing, direction)
		elseif phase == "impact" then
			V42.addPose(poses, "UpperTorso", { -7, -35, 13 }, amount, nil, "Quad", "Out")
			V42.addPose(poses, "RightUpperArm", { -72, -45, -42 }, amount, nil, "Quad", "Out")
			V42.addPose(poses, "RightLowerArm", { -6, 0, -18 }, amount, nil, "Quad", "Out")
		elseif phase == "followThrough" then
			V42.addPose(poses, "UpperTorso", { -2, -12, 5 }, amount, nil, "Sine", "InOut")
			V42.addPose(poses, "RightUpperArm", { -32, -14, -18 }, amount, nil, "Sine", "InOut")
		end
	elseif kind == "hitReaction" or kind == "death" then
		if phase == "action" or phase == "impact" then
			V42.addPose(poses, "UpperTorso", { 18, 0, 0 }, amount, nil, "Quad", "Out")
			V42.addPose(poses, "Head", { 14, 0, 0 }, amount, nil, "Quad", "Out")
			V42.addPose(poses, "RightUpperArm", { 18, 0, 40 }, amount, nil, "Quad", "Out")
			V42.addPose(poses, "LeftUpperArm", { 18, 0, -40 }, amount, nil, "Quad", "Out")
		elseif phase == "followThrough" then
			V42.addPose(poses, "UpperTorso", { 8, 0, 0 }, amount, nil, "Sine", "InOut")
		end
	elseif kind == "walk" or kind == "run" then
		local stride = kind == "run" and 34 or 22
		if phase == "anticipation" or phase == "impact" then
			V42.addPose(poses, "RightUpperLeg", { -stride, 0, 0 }, amount, nil, easing, direction)
			V42.addPose(poses, "LeftUpperLeg", { stride, 0, 0 }, amount, nil, easing, direction)
			V42.addPose(poses, "RightUpperArm", { stride * 0.65, 0, 0 }, amount, nil, easing, direction)
			V42.addPose(poses, "LeftUpperArm", { -stride * 0.65, 0, 0 }, amount, nil, easing, direction)
		elseif phase == "action" or phase == "followThrough" then
			V42.addPose(poses, "RightUpperLeg", { stride, 0, 0 }, amount, nil, easing, direction)
			V42.addPose(poses, "LeftUpperLeg", { -stride, 0, 0 }, amount, nil, easing, direction)
			V42.addPose(poses, "RightUpperArm", { -stride * 0.65, 0, 0 }, amount, nil, easing, direction)
			V42.addPose(poses, "LeftUpperArm", { stride * 0.65, 0, 0 }, amount, nil, easing, direction)
		end
	else
		if phase == "anticipation" or phase == "impact" then
			V42.addPose(poses, "UpperTorso", { -3, 0, 0 }, amount, nil, easing, direction)
			V42.addPose(poses, "Head", { 2, 0, 0 }, amount, nil, easing, direction)
			V42.addPose(poses, "RightUpperArm", { -8, 0, 8 }, amount, nil, easing, direction)
			V42.addPose(poses, "LeftUpperArm", { -8, 0, -8 }, amount, nil, easing, direction)
		end
	end
	return poses
end

function V42.r6Pose(kind, phase, amount, style)
	local poses = {}
	local easing = style.easing
	local direction = style.direction
	if kind == "projectileCast" or kind == "abilityCharge" then
		if phase == "anticipation" then
			V42.addPose(poses, "Torso", { -7, 0, 0 }, amount, nil, easing, "Out")
			V42.addPose(poses, "Right Arm", { -54, 16, 45 }, amount, nil, easing, "Out")
			V42.addPose(poses, "Left Arm", { -54, -16, -45 }, amount, nil, easing, "Out")
		elseif phase == "action" or phase == "impact" then
			V42.addPose(poses, "Torso", { -14, 0, 0 }, amount, nil, easing, direction)
			V42.addPose(poses, "Right Arm", { -86, 5, 18 }, amount, nil, easing, direction)
			V42.addPose(poses, "Left Arm", { -86, -5, -18 }, amount, nil, easing, direction)
		elseif phase == "followThrough" then
			V42.addPose(poses, "Torso", { -5, 0, 0 }, amount, nil, "Sine", "InOut")
			V42.addPose(poses, "Right Arm", { -38, 12, 26 }, amount, nil, "Sine", "InOut")
			V42.addPose(poses, "Left Arm", { -38, -12, -26 }, amount, nil, "Sine", "InOut")
		end
	elseif kind == "combatSlash" then
		if phase == "anticipation" then
			V42.addPose(poses, "Torso", { 0, 18, -8 }, amount, nil, easing, "Out")
			V42.addPose(poses, "Right Arm", { -28, 58, 62 }, amount, nil, easing, "Out")
		elseif phase == "action" or phase == "impact" then
			V42.addPose(poses, "Torso", { -4, -28, 10 }, amount, nil, easing, direction)
			V42.addPose(poses, "Right Arm", { -72, -38, -38 }, amount, nil, easing, direction)
		elseif phase == "followThrough" then
			V42.addPose(poses, "Torso", { -2, -12, 5 }, amount, nil, "Sine", "InOut")
			V42.addPose(poses, "Right Arm", { -32, -14, -18 }, amount, nil, "Sine", "InOut")
		end
	else
		if phase == "anticipation" or phase == "impact" then
			V42.addPose(poses, "Torso", { -3, 0, 0 }, amount, nil, easing, direction)
			V42.addPose(poses, "Right Arm", { -8, 0, 8 }, amount, nil, easing, direction)
			V42.addPose(poses, "Left Arm", { -8, 0, -8 }, amount, nil, easing, direction)
		end
	end
	return poses
end

function V42.phaseMarkers(kind, times)
	local markers = {
		{ name = "Anticipation", time = times.anticipation },
		{ name = "Action", time = times.action },
		{ name = "Impact", time = times.impact },
		{ name = "FollowThrough", time = times.followThrough },
		{ name = "Recovery", time = times.recovery },
	}
	if kind == "projectileCast" or kind == "abilityCharge" then
		table.insert(markers, { name = "ChargeStart", time = times.anticipation })
		table.insert(markers, { name = "Fire", time = times.impact })
		table.insert(markers, { name = "VFXBurst", time = times.impact })
		table.insert(markers, { name = "SoundCue", time = times.impact })
	elseif kind == "combatSlash" then
		table.insert(markers, { name = "DamageWindowStart", time = times.action })
		table.insert(markers, { name = "DamageWindowEnd", time = times.followThrough })
		table.insert(markers, { name = "SoundCue", time = times.impact })
	elseif kind == "hitReaction" then
		table.insert(markers, { name = "HitReact", time = times.impact })
	end
	return markers
end

function V42.filterSpecForRig(spec, rig)
	if not rig then
		return spec, {}
	end
	local targets = V40.poseTargetMap(rig)
	local removed = {}
	for _, keyframe in ipairs(spec.keyframes or {}) do
		for name in pairs(keyframe.poses or {}) do
			if not V40.resolvePoseTarget(targets, name) then
				keyframe.poses[name] = nil
				removed[name] = true
			end
		end
	end
	local removedList = {}
	for name in pairs(removed) do table.insert(removedList, name) end
	table.sort(removedList)
	return spec, removedList
end

function V42.intentSpec(payload)
	payload = payload or {}
	if type(payload.animation) == "table" or type(payload.spec) == "table" then
		return payload.animation or payload.spec, { source = "providedSpec" }
	end
	local intent = tostring(payload.intent or payload.text or payload.prompt or payload.description or "snappy projectile cast")
	local rig = V40.resolveRig(payload)
	local styleId = payload.style or V42.inferStyle(intent)
	local kindId = payload.animationType or payload.kind or V42.inferKind(intent)
	local style = V42.styleCatalog[styleId] or V42.styleCatalog.snappy
	local kind = V42.kindCatalog[kindId] or V42.kindCatalog.projectileCast
	local length = V42.roundTime((tonumber(payload.length or kind.length) or kind.length) * (tonumber(style.lengthScale) or 1))
	local times = {
		start = 0,
		anticipation = V42.roundTime(length * 0.12),
		action = V42.roundTime(length * 0.46),
		impact = V42.roundTime(length * 0.56),
		followThrough = V42.roundTime(length * 0.75),
		recovery = V42.roundTime(length * 0.9),
		final = length,
	}
	local family = V42.rigFamily(rig)
	local poseFactory = family == "R6" and V42.r6Pose or V42.r15Pose
	local amount = tonumber(payload.exaggeration or style.exaggeration) or 1
	local keyframes = {
		{ time = times.start, poses = {}, easingStyle = style.easing, easingDirection = "Out" },
		{ time = times.anticipation, poses = poseFactory(kind.id, "anticipation", amount, style), easingStyle = style.easing, easingDirection = "Out" },
		{ time = times.action, poses = poseFactory(kind.id, "action", amount, style), easingStyle = style.easing, easingDirection = style.direction },
		{ time = times.impact, poses = poseFactory(kind.id, "impact", amount, style), easingStyle = "Quad", easingDirection = "Out" },
		{ time = times.followThrough, poses = poseFactory(kind.id, "followThrough", amount, style), easingStyle = "Sine", easingDirection = "InOut" },
		{ time = times.recovery, poses = poseFactory(kind.id, "recovery", amount, style), easingStyle = "Sine", easingDirection = "InOut" },
		{ time = times.final, poses = {}, easingStyle = "Quad", easingDirection = "In" },
	}
	local name = payload.animationName or payload.name
	if not name or tostring(name) == "" then
		name = (style.id .. "_" .. kind.id .. "_" .. intent:gsub("[^%w]+", "_")):sub(1, 64)
	end
	local spec = {
		animationName = V40.safeAnimationName(name),
		intent = intent,
		style = style.id,
		animationType = kind.id,
		length = length,
		looped = kind.looped,
		priority = kind.priority,
		keyframes = keyframes,
		markers = V42.phaseMarkers(kind.id, times),
		soundCues = { SoundCue = times.impact },
		vfxCues = { VFXBurst = times.impact },
		cameraCues = { ImpactShake = times.impact },
	}
	local removed = {}
	spec, removed = V42.filterSpecForRig(spec, rig)
	return spec, {
		source = "intent",
		intent = intent,
		style = style,
		animationType = kind,
		rig = rig and safeFullName(rig) or nil,
		rigFamily = family,
		removedMissingTargets = removed,
	}
end

function V42.getAnimationIntentPlan(payload)
	local spec, meta = V42.intentSpec(payload or {})
	local validation = V40.validateAnimationSpec({ animation = spec, rigPath = payload and payload.rigPath or nil })
	local result = {
		at = isoNow(),
		version = VERSION,
		status = validation.valid and "ready" or "needsFix",
		meta = meta,
		animation = spec,
		validation = validation,
		nextCommand = "tools\\bridge.cmd animation generate <rigPath> \"intent text\"",
	}
	V42.last.intentPlan = result
	return result
end

function V42.specFromSequence(sequence)
	if not sequence or not sequence:IsA("KeyframeSequence") then
		return nil
	end
	local metadata = sequence:FindFirstChild("CodexMetadata")
	if metadata and metadata:IsA("StringValue") then
		local decoded = decodeJson(metadata.Value)
		if decoded and type(decoded.spec) == "table" then
			local spec = decoded.spec
			spec.animationName = spec.animationName or sequence.Name:gsub("_v%d%d%d$", "")
			return spec, "metadata"
		end
	end
	local spec = {
		animationName = sequence.Name:gsub("_v%d%d%d$", ""),
		length = 0,
		looped = sequence.Loop,
		priority = tostring(sequence.Priority):gsub("^Enum%.AnimationPriority%.", ""),
		keyframes = {},
		markers = {},
	}
	for _, keyframe in ipairs(sequence:GetKeyframes()) do
		if keyframe.Time > spec.length then spec.length = keyframe.Time end
		local poses = {}
		local function collect(pose)
			poses[pose.Name] = { cframe = serializeValue(pose.CFrame), easingStyle = tostring(pose.EasingStyle):gsub("^Enum%.PoseEasingStyle%.", ""), easingDirection = tostring(pose.EasingDirection):gsub("^Enum%.PoseEasingDirection%.", ""), weight = pose.Weight }
			for _, child in ipairs(pose:GetSubPoses()) do collect(child) end
		end
		for _, pose in ipairs(keyframe:GetPoses()) do collect(pose) end
		table.insert(spec.keyframes, { time = keyframe.Time, poses = poses })
		for _, marker in ipairs(keyframe:GetMarkers()) do
			table.insert(spec.markers, { name = marker.Name, value = marker.Value, time = keyframe.Time })
		end
	end
	table.sort(spec.keyframes, function(a, b) return a.time < b.time end)
	return spec, "sequence"
end

function V42.specFromPayload(payload)
	payload = payload or {}
	if type(payload.animation) == "table" or type(payload.spec) == "table" then
		return payload.animation or payload.spec, "payload"
	end
	local target = resolvePath(payload.animationPath or payload.path or payload.target or "")
	if target and target:IsA("KeyframeSequence") then
		return V42.specFromSequence(target)
	end
	return nil, "missing"
end

function V42.cloneSpec(spec)
	local encoded = encodeJson(spec)
	if encoded then
		local decoded = decodeJson(encoded)
		if decoded then return decoded end
	end
	return spec
end

function V42.collectSpecStats(spec)
	local stats = { length = tonumber(spec and spec.length or 0) or 0, keyframeCount = 0, markerCount = 0, poseNames = {}, poseNameList = {}, markers = {}, poseCount = 0, movingPoseCount = 0 }
	for _, frame in ipairs(spec and spec.keyframes or {}) do
		stats.keyframeCount += 1
		for name, pose in pairs(frame.poses or {}) do
			if not stats.poseNames[name] then
				stats.poseNames[name] = true
				table.insert(stats.poseNameList, name)
			end
			stats.poseCount += 1
			local rotation = pose.rotation or pose.rotationEulerDegrees or pose.rotationDegrees
			if type(rotation) == "table" then
				local magnitude = math.abs(tonumber(rotation[1] or rotation.x or 0) or 0) + math.abs(tonumber(rotation[2] or rotation.y or 0) or 0) + math.abs(tonumber(rotation[3] or rotation.z or 0) or 0)
				if magnitude > 2 then stats.movingPoseCount += 1 end
			elseif pose.cframe or pose.transform then
				stats.movingPoseCount += 1
			end
		end
	end
	for _, marker in ipairs(spec and spec.markers or {}) do
		stats.markerCount += 1
		stats.markers[tostring(marker.name or "")] = tonumber(marker.time or 0) or 0
	end
	table.sort(stats.poseNameList)
	return stats
end

function V42.hasMarker(stats, names)
	for _, markerName in ipairs(names) do
		for existing in pairs(stats.markers or {}) do
			local lower = V42.lowerText(existing)
			if lower:find(V42.lowerText(markerName), 1, true) then
				return true
			end
		end
	end
	return false
end

function V42.getAnimationQualityAudit(payload)
	local spec = V42.specFromPayload(payload or {})
	if not spec then
		return { at = isoNow(), version = VERSION, status = "notFound", score = 0, blockers = { "Animation/spec was not found." }, requested = payload and (payload.animationPath or payload.path or payload.animationFile) or nil }
	end
	local rig = V40.resolveRig(payload or {})
	local validation = V40.validateAnimationSpec({ animation = spec, rigPath = rig and safeFullName(rig) or nil })
	local stats = V42.collectSpecStats(spec)
	local score = 100
	local blockers = {}
	local warnings = {}
	local recommendations = {}
	if not validation.valid then
		score -= 25
		for _, err in ipairs(validation.errors or {}) do table.insert(blockers, err) end
	end
	if stats.keyframeCount < 5 then score -= 16; table.insert(warnings, "Too few keyframes for pro-quality timing."); table.insert(recommendations, "Add anticipation, action, impact, follow-through, and recovery keyframes.") end
	if stats.markerCount < 3 then score -= 12; table.insert(warnings, "Timeline markers are sparse."); table.insert(recommendations, "Add gameplay/VFX/sound markers around impact and recovery.") end
	if not V42.hasMarker(stats, { "anticipation", "charge" }) then score -= 8; table.insert(warnings, "No anticipation/charge marker found.") end
	if not V42.hasMarker(stats, { "impact", "fire", "hit" }) then score -= 10; table.insert(warnings, "No clear impact/fire marker found.") end
	if not V42.hasMarker(stats, { "recovery" }) then score -= 6; table.insert(warnings, "No recovery marker found.") end
	if #stats.poseNameList < 4 then score -= 14; table.insert(warnings, "Pose coverage is narrow; animation may look stiff.") end
	if stats.movingPoseCount < math.max(3, stats.poseCount * 0.35) then score -= 10; table.insert(warnings, "Most poses appear static or unvaried.") end
	if stats.length <= 0 then score -= 20; table.insert(blockers, "Animation length is zero.") end
	if stats.length > 4 and spec.looped ~= true then score -= 5; table.insert(warnings, "Long non-looping animation may need stronger staging or cutscene markers.") end
	score = math.clamp(math.floor(score + 0.5), 0, 100)
	local grade = score >= 90 and "pro-ready" or (score >= 75 and "solid" or (score >= 55 and "needs-polish" or "rough"))
	local result = {
		at = isoNow(),
		version = VERSION,
		status = "ok",
		score = score,
		grade = grade,
		stats = stats,
		validation = validation,
		blockers = blockers,
		warnings = warnings,
		recommendations = recommendations,
		nextCommand = "tools\\bridge.cmd animation polish <rigPath> <animationPath-or-json>",
	}
	V42.last.qualityAudit = result
	return result
end

function V42.ensureMarker(spec, name, time)
	for _, marker in ipairs(spec.markers or {}) do
		if tostring(marker.name or "") == name then
			marker.time = tonumber(marker.time or time) or time
			return
		end
	end
	spec.markers = spec.markers or {}
	table.insert(spec.markers, { name = name, time = time, value = name })
end

function V42.ensureFrame(spec, time, poses, easingStyle, easingDirection)
	spec.keyframes = spec.keyframes or {}
	local best = nil
	for _, frame in ipairs(spec.keyframes) do
		if math.abs((tonumber(frame.time) or 0) - time) < 0.015 then
			best = frame
			break
		end
	end
	if not best then
		best = { time = time, poses = {}, easingStyle = easingStyle, easingDirection = easingDirection }
		table.insert(spec.keyframes, best)
	end
	best.poses = best.poses or {}
	for name, pose in pairs(poses or {}) do
		if not best.poses[name] then
			best.poses[name] = pose
		end
	end
	best.easingStyle = best.easingStyle or easingStyle
	best.easingDirection = best.easingDirection or easingDirection
	table.sort(spec.keyframes, function(a, b) return (tonumber(a.time) or 0) < (tonumber(b.time) or 0) end)
end

function V42.polishedSpec(payload)
	payload = payload or {}
	local base, source = V42.specFromPayload(payload)
	if not base then
		base = V42.intentSpec(payload)
		source = "intentFallback"
	end
	local spec = V42.cloneSpec(base)
	spec.animationName = V40.safeAnimationName(tostring(spec.animationName or spec.name or "GeneratedAnimation"):gsub("_v%d%d%d$", "") .. "_Polished")
	local rig = V40.resolveRig(payload)
	local styleId = payload.style or spec.style or "cinematic"
	local style = V42.styleCatalog[styleId] or V42.styleCatalog.cinematic
	local kindId = spec.animationType or payload.animationType or payload.kind or V42.inferKind(spec.intent or spec.animationName or "")
	local kind = V42.kindCatalog[kindId] or V42.kindCatalog.projectileCast
	local length = tonumber(spec.length or 0) or 0
	if length <= 0 then length = kind.length end
	spec.length = V42.roundTime(length)
	local times = {
		anticipation = V42.roundTime(spec.length * 0.12),
		action = V42.roundTime(spec.length * 0.44),
		impact = V42.roundTime(spec.length * 0.56),
		followThrough = V42.roundTime(spec.length * 0.74),
		recovery = V42.roundTime(spec.length * 0.9),
		final = spec.length,
	}
	local family = V42.rigFamily(rig)
	local poseFactory = family == "R6" and V42.r6Pose or V42.r15Pose
	local amount = tonumber(payload.exaggeration or style.exaggeration) or 1.15
	V42.ensureFrame(spec, 0, {}, style.easing, "Out")
	V42.ensureFrame(spec, times.anticipation, poseFactory(kind.id, "anticipation", amount, style), style.easing, "Out")
	V42.ensureFrame(spec, times.action, poseFactory(kind.id, "action", amount, style), style.easing, style.direction)
	V42.ensureFrame(spec, times.impact, poseFactory(kind.id, "impact", amount, style), "Quad", "Out")
	V42.ensureFrame(spec, times.followThrough, poseFactory(kind.id, "followThrough", amount, style), "Sine", "InOut")
	V42.ensureFrame(spec, times.recovery, poseFactory(kind.id, "recovery", amount * 0.8, style), "Sine", "InOut")
	V42.ensureFrame(spec, times.final, {}, "Quad", "In")
	V42.ensureMarker(spec, "Anticipation", times.anticipation)
	V42.ensureMarker(spec, "Impact", times.impact)
	V42.ensureMarker(spec, "Recovery", times.recovery)
	if kind.id == "projectileCast" or kind.id == "abilityCharge" then
		V42.ensureMarker(spec, "ChargeStart", times.anticipation)
		V42.ensureMarker(spec, "Fire", times.impact)
		V42.ensureMarker(spec, "VFXBurst", times.impact)
		V42.ensureMarker(spec, "SoundCue", times.impact)
	elseif kind.id == "combatSlash" then
		V42.ensureMarker(spec, "DamageWindowStart", times.action)
		V42.ensureMarker(spec, "DamageWindowEnd", times.followThrough)
	end
	spec.style = style.id
	spec.animationType = kind.id
	spec.polishedBy = "CodexStudioBridge V42"
	local removed = {}
	spec, removed = V42.filterSpecForRig(spec, rig)
	return spec, { source = source, style = style, animationType = kind, removedMissingTargets = removed, rig = rig and safeFullName(rig) or nil }
end

function V42.getAnimationPolishPlan(payload)
	local spec, meta = V42.polishedSpec(payload or {})
	local audit = V42.getAnimationQualityAudit({ animation = spec, rigPath = payload and payload.rigPath or nil })
	return { at = isoNow(), version = VERSION, status = "ready", meta = meta, animation = spec, audit = audit, nextCommand = "tools\\bridge.cmd animation polish <rigPath> <animationPath-or-json>" }
end

function V42.generateAnimationFromIntent(payload)
	local spec, meta = V42.intentSpec(payload or {})
	local result = V40.saveGeneratedAnimation({ animation = spec, rigPath = payload and payload.rigPath or nil })
	result.kind = "generatedAnimationFromIntent"
	result.intentMeta = meta
	result.quality = V42.getAnimationQualityAudit({ animation = spec, rigPath = payload and payload.rigPath or nil })
	V42.last.generated = result
	return result
end

function V42.applyAnimationPolishPlan(payload)
	local spec, meta = V42.polishedSpec(payload or {})
	local result = V40.saveGeneratedAnimation({ animation = spec, rigPath = payload and payload.rigPath or nil })
	result.kind = "appliedAnimationPolishPlan"
	result.polishMeta = meta
	result.quality = V42.getAnimationQualityAudit({ animation = spec, rigPath = payload and payload.rigPath or nil })
	V42.last.polished = result
	return result
end

function V42.retimeSpec(spec, scale)
	local clone = V42.cloneSpec(spec)
	scale = tonumber(scale) or 1
	if scale <= 0 then scale = 1 end
	clone.animationName = V40.safeAnimationName(tostring(clone.animationName or clone.name or "GeneratedAnimation"):gsub("_v%d%d%d$", "") .. "_Retime")
	clone.length = V42.roundTime((tonumber(clone.length or 0) or 0) * scale)
	for _, frame in ipairs(clone.keyframes or {}) do
		frame.time = V42.roundTime((tonumber(frame.time or 0) or 0) * scale)
	end
	for _, marker in ipairs(clone.markers or {}) do
		marker.time = V42.roundTime((tonumber(marker.time or 0) or 0) * scale)
	end
	clone.retimedBy = "CodexStudioBridge V42"
	clone.retimeScale = scale
	return clone
end

function V42.retimeGeneratedAnimation(payload)
	local spec = V42.specFromPayload(payload or {})
	if not spec then error("retimeGeneratedAnimation requires an animation path or spec.") end
	local scale = tonumber(payload.scale or payload.timeScale or payload.multiplier or 1) or 1
	local retimed = V42.retimeSpec(spec, scale)
	local result = V40.saveGeneratedAnimation({ animation = retimed, rigPath = payload and payload.rigPath or nil })
	result.kind = "retimedGeneratedAnimation"
	result.scale = scale
	return result
end

function V42.mirrorName(name)
	local text = tostring(name or "")
	if text:find("Left", 1, true) then return text:gsub("Left", "Right") end
	if text:find("Right", 1, true) then return text:gsub("Right", "Left") end
	if text:find("left", 1, true) then return text:gsub("left", "right") end
	if text:find("right", 1, true) then return text:gsub("right", "left") end
	return text
end

function V42.mirrorPose(pose)
	local clone = V42.cloneSpec(pose)
	local rotation = clone.rotation or clone.rotationEulerDegrees or clone.rotationDegrees
	if type(rotation) == "table" then
		local x = tonumber(rotation[1] or rotation.x or 0) or 0
		local y = tonumber(rotation[2] or rotation.y or 0) or 0
		local z = tonumber(rotation[3] or rotation.z or 0) or 0
		clone.rotation = { x, -y, -z }
		clone.rotationEulerDegrees = { x, -y, -z }
	end
	local position = clone.position
	if type(position) == "table" then
		local x = tonumber(position[1] or position.x or 0) or 0
		local y = tonumber(position[2] or position.y or 0) or 0
		local z = tonumber(position[3] or position.z or 0) or 0
		clone.position = { -x, y, z }
	end
	return clone
end

function V42.mirrorSpec(spec, direction)
	local clone = V42.cloneSpec(spec)
	clone.animationName = V40.safeAnimationName(tostring(clone.animationName or clone.name or "GeneratedAnimation"):gsub("_v%d%d%d$", "") .. "_Mirror")
	for _, frame in ipairs(clone.keyframes or {}) do
		local mirrored = {}
		for name, pose in pairs(frame.poses or {}) do
			mirrored[V42.mirrorName(name)] = V42.mirrorPose(pose)
		end
		frame.poses = mirrored
	end
	clone.mirroredBy = "CodexStudioBridge V42"
	clone.mirrorDirection = direction or "swap-left-right"
	return clone
end

function V42.mirrorGeneratedAnimation(payload)
	local spec = V42.specFromPayload(payload or {})
	if not spec then error("mirrorGeneratedAnimation requires an animation path or spec.") end
	local mirrored = V42.mirrorSpec(spec, payload and payload.direction or nil)
	local result = V40.saveGeneratedAnimation({ animation = mirrored, rigPath = payload and payload.rigPath or nil })
	result.kind = "mirroredGeneratedAnimation"
	result.direction = payload and payload.direction or "swap-left-right"
	return result
end

function V42.getAnimationCompareReport(payload)
	payload = payload or {}
	local leftSpec = nil
	local rightSpec = nil
	if type(payload.leftAnimation) == "table" then leftSpec = payload.leftAnimation end
	if type(payload.rightAnimation) == "table" then rightSpec = payload.rightAnimation end
	if not leftSpec then
		local left = resolvePath(payload.leftPath or payload.animationA or payload.a or "")
		if left and left:IsA("KeyframeSequence") then leftSpec = V42.specFromSequence(left) end
	end
	if not rightSpec then
		local right = resolvePath(payload.rightPath or payload.animationB or payload.b or "")
		if right and right:IsA("KeyframeSequence") then rightSpec = V42.specFromSequence(right) end
	end
	if not leftSpec or not rightSpec then
		return { at = isoNow(), version = VERSION, status = "notFound", error = "Two animations/specs are required." }
	end
	local leftStats = V42.collectSpecStats(leftSpec)
	local rightStats = V42.collectSpecStats(rightSpec)
	local missingRight = {}
	for _, name in ipairs(leftStats.poseNameList) do
		if not rightStats.poseNames[name] then table.insert(missingRight, name) end
	end
	local missingLeft = {}
	for _, name in ipairs(rightStats.poseNameList) do
		if not leftStats.poseNames[name] then table.insert(missingLeft, name) end
	end
	return {
		at = isoNow(),
		version = VERSION,
		status = "ok",
		left = { name = leftSpec.animationName or leftSpec.name, stats = leftStats },
		right = { name = rightSpec.animationName or rightSpec.name, stats = rightStats },
		delta = {
			length = V42.roundTime((rightStats.length or 0) - (leftStats.length or 0)),
			keyframes = (rightStats.keyframeCount or 0) - (leftStats.keyframeCount or 0),
			markers = (rightStats.markerCount or 0) - (leftStats.markerCount or 0),
			posesOnlyInLeft = missingRight,
			posesOnlyInRight = missingLeft,
		},
		nextCommand = "tools\\bridge.cmd animation audit <rigPath> <animationPath>",
	}
end

function V42.getAnimationRetargetPlan(payload)
	payload = payload or {}
	local spec = V42.specFromPayload(payload)
	local rig = V40.resolveRig(payload)
	if not spec then
		return { at = isoNow(), version = VERSION, status = "notFound", error = "Animation/spec was not found." }
	end
	if not rig then
		return { at = isoNow(), version = VERSION, status = "needsRig", error = "Rig is required for retarget planning." }
	end
	local targets = V40.poseTargetMap(rig)
	local missing = {}
	local covered = {}
	for _, frame in ipairs(spec.keyframes or {}) do
		for name in pairs(frame.poses or {}) do
			if V40.resolvePoseTarget(targets, name) then
				covered[name] = true
			else
				missing[name] = true
			end
		end
	end
	local missingList = {}
	for name in pairs(missing) do table.insert(missingList, name) end
	table.sort(missingList)
	local coveredList = {}
	for name in pairs(covered) do table.insert(coveredList, name) end
	table.sort(coveredList)
	return { at = isoNow(), version = VERSION, status = #missingList == 0 and "ready" or "needsMapping", rig = safeFullName(rig), rigType = V40.rigSummary(rig, false).rigType, coveredTargets = coveredList, missingTargets = missingList, targetCount = #(targets.list or {}) }
end

function V42.applyAnimationPoseCleanup(payload)
	local rig = V40.resolveRig(payload or {})
	if not rig then error("Rig was not found.") end
	V40.stopAnimationPreview({ rigPath = safeFullName(rig) })
	local result = V40.resetRigPose({ rigPath = safeFullName(rig) })
	result.kind = "animationPoseCleanup"
	return result
end

function V42.getAnimationDirectorReport(payload)
	payload = payload or {}
	return {
		at = isoNow(),
		version = VERSION,
		status = "ok",
		styles = V42.getAnimationStyleCatalog(payload),
		workbench = V40.getAnimationWorkbenchReport(payload),
		last = V42.last,
		proCommands = {
			"tools\\bridge.cmd animation styles",
			"tools\\bridge.cmd animation generate <rigPath> \"anime heavy projectile cast\"",
			"tools\\bridge.cmd animation audit <rigPath> <animationPath>",
			"tools\\bridge.cmd animation polish <rigPath> <animationPath>",
			"tools\\bridge.cmd animation retime <animationPath> 0.85",
			"tools\\bridge.cmd animation mirror <animationPath>",
			"tools\\bridge.cmd animation compare <animationA> <animationB>",
		},
		nextCommand = "tools\\bridge.cmd animation generate <rigPath> \"snappy combat slash with strong impact\"",
	}
end

