		portalCast = { id = "portalCast", title = "Portal Cast", kind = "abilityCharge", defaultStyle = "cinematic", bodyFocus = { "one hand draws circle", "torso turns to portal", "off-hand stabilizes", "hold at open" }, markers = { "DrawStart", "PortalOpen", "TeleportWindow", "PortalClose", "Recovery" }, cues = { vfx = "circle glyph, swirl, edge sparks", camera = "portal framing hold", hitbox = "teleport/interaction window" } },
		pickup = { id = "pickup", title = "Pickup", kind = "emote", defaultStyle = "realistic", bodyFocus = { "torso bends", "dominant hand reaches", "knees soften", "item lifted to chest" }, markers = { "Reach", "Grab", "Collect", "Recovery" }, cues = { vfx = "pickup sparkle", camera = "none", hitbox = "collect at Grab" } },
		hitReaction = { id = "hitReaction", title = "Hit Reaction", kind = "hitReaction", defaultStyle = "snappy", bodyFocus = { "impact side recoils", "head follows hit direction", "arms open", "feet brace" }, markers = { "HitReact", "StaggerPeak", "Recovery" }, cues = { vfx = "hit spark and flash", camera = "victim shake optional", hitbox = "none" } },
		death = { id = "death", title = "Death", kind = "death", defaultStyle = "heavy", bodyFocus = { "torso collapses", "head lags", "arms lose tension", "final settle" }, markers = { "DeathStart", "Fall", "GroundImpact", "DeathEnd" }, cues = { vfx = "fade, smoke, soul burst optional", camera = "none", hitbox = "none" } },
		combatIdle = { id = "combatIdle", title = "Combat Idle", kind = "idle", defaultStyle = "realistic", bodyFocus = { "weighted stance", "subtle breathing", "weapon ready", "eyes forward" }, markers = { "LoopStart", "Breath", "LoopEnd" }, cues = { vfx = "ambient aura loop optional", camera = "none", hitbox = "none" } },
		bossRoar = { id = "bossRoar", title = "Boss Roar", kind = "cutsceneBeat", defaultStyle = "cinematic", bodyFocus = { "chest expands", "arms spread wide", "head snaps up", "long held silhouette" }, markers = { "Inhale", "RoarStart", "VFXBurst", "RoarPeak", "Recovery" }, cues = { vfx = "shockwave, aura flare", camera = "strong shake at RoarPeak", hitbox = "fear/stun radius optional" } },
		cinematicUltimate = { id = "cinematicUltimate", title = "Cinematic Ultimate", kind = "cutsceneBeat", defaultStyle = "cinematic", bodyFocus = { "hero pose", "charge hold", "dramatic release", "big recovery silhouette" }, markers = { "CinematicStart", "ChargeStart", "ChargePeak", "Fire", "Impact", "VFXBurst", "SoundCue", "Recovery" }, cues = { vfx = "multi-phase ultimate effect", camera = "framed charge, impact shake", hitbox = "ultimate damage window" } },
	}
end

function V53.catalogList()
	local list = {}
	for _, item in pairs(V53.catalog()) do table.insert(list, item) end
	table.sort(list, function(a, b) return tostring(a.id) < tostring(b.id) end)
	return list
end

function V53.getAnimationChoreographyCatalog(payload)
	return { at = isoNow(), version = VERSION, status = "ok", archetypes = V53.catalogList(), styles = V42.getAnimationStyleCatalog({}).styles, variants = { "light", "heavy", "finisher", "cinematic", "mobile-readable", "mirrored", "short-cast", "long-cast", "low-motion", "boss" }, phaseModel = { "start", "anticipation", "buildup", "action", "impact", "hold", "followThrough", "recovery", "final" }, nextCommand = "tools\\bridge.cmd animation choreograph <rigPath> \"heavy anime lightning sword dash slash\"" }
end

function V53.matchAny(text, words)
	for _, word in ipairs(words or {}) do
		if text:find(V53.lower(word), 1, true) then return true end
	end
	return false
end

function V53.inferArchetype(intent)
	local text = V53.lower(intent)
	if V53.matchAny(text, { "dash slash", "dash", "blink strike", "afterimage" }) then return "dashSlash" end
	if V53.matchAny(text, { "ground slam", "slam", "shockwave", "meteor" }) then return "groundSlam" end
	if V53.matchAny(text, { "shield", "block", "guard", "barrier" }) then return "shieldBlock" end
	if V53.matchAny(text, { "heal", "healing", "restore", "blessing" }) then return "healCast" end
	if V53.matchAny(text, { "portal", "teleport", "rift", "gate" }) then return "portalCast" end
	if V53.matchAny(text, { "pickup", "collect", "grab item" }) then return "pickup" end
	if V53.matchAny(text, { "boss roar", "roar", "taunt" }) then return "bossRoar" end
	if V53.matchAny(text, { "ultimate", "cinematic", "super", "finisher" }) then return "cinematicUltimate" end
	if V53.matchAny(text, { "idle", "stance", "ready pose" }) then return "combatIdle" end
	if V53.matchAny(text, { "death", "die", "defeat" }) then return "death" end
	if V53.matchAny(text, { "hit reaction", "flinch", "stagger", "knockback" }) then return "hitReaction" end
	if V53.matchAny(text, { "thrust", "stab", "pierce", "lunge" }) then return "thrust" end
	if V53.matchAny(text, { "slash", "sword", "katana", "blade", "axe" }) then return "swordSlash" end
	if V53.matchAny(text, { "charge", "power up", "gather energy" }) and not V53.matchAny(text, { "beam", "blast", "projectile" }) then return "handCharge" end
	if V53.matchAny(text, { "beam", "blast", "projectile", "kame", "fireball", "laser" }) then return "beamCast" end
	return "beamCast"
end

function V53.powerLevel(intent)
	local text = V53.lower(intent)
	if V53.matchAny(text, { "ultimate", "boss", "massive", "huge", "cinematic" }) then return "ultimate", 1.35 end
	if V53.matchAny(text, { "heavy", "powerful", "strong", "charged" }) then return "heavy", 1.18 end
	if V53.matchAny(text, { "light", "quick", "small", "tap" }) then return "light", 0.82 end
	return "medium", 1.0
end

function V53.handedness(intent)
	local text = V53.lower(intent)
	if V53.matchAny(text, { "left hand", "left-handed", "left arm" }) then return "left" end
	if V53.matchAny(text, { "both hands", "two hand", "two-handed", "dual hand", "kame" }) then return "both" end
	return "right"
end

function V53.inferFocus(intent, archetypeId)
	local text = V53.lower(intent)
	local focus = {}
	if V53.matchAny(text, { "sword", "weapon", "blade", "katana", "axe" }) then table.insert(focus, "weapon") end
	if V53.matchAny(text, { "hand", "palm", "fist", "punch" }) then table.insert(focus, "hands") end
	if V53.matchAny(text, { "dash", "run", "lunge" }) then table.insert(focus, "legs") end
	if V53.matchAny(text, { "beam", "blast", "cast", "ultimate" }) then table.insert(focus, "torso") end
	local entry = V53.catalog()[archetypeId]
	for _, item in ipairs(entry and entry.bodyFocus or {}) do table.insert(focus, item) end
	return focus
end

function V53.phaseTiming(archetypeId, style, powerScale)
	local archetype = V53.catalog()[archetypeId] or V53.catalog().beamCast
	local kind = V42.kindCatalog[archetype.kind] or V42.kindCatalog.projectileCast
	local length = V42.roundTime((kind.length or 1.2) * (tonumber(style and style.lengthScale) or 1) * (0.92 + ((tonumber(powerScale) or 1) - 1) * 0.45))
	if archetypeId == "cinematicUltimate" then length = math.max(length, 2.2) end
	if archetypeId == "combatIdle" then length = math.max(length, 2.0) end
	return { start = 0, anticipation = V42.roundTime(length * 0.1), buildup = V42.roundTime(length * 0.26), action = V42.roundTime(length * 0.43), impact = V42.roundTime(length * 0.55), hold = V42.roundTime(length * 0.62), followThrough = V42.roundTime(length * 0.76), recovery = V42.roundTime(length * 0.9), final = length }, length
end

function V53.getAnimationIntentBreakdown(payload)
	payload = payload or {}
	local intent = tostring(payload.intent or payload.text or payload.prompt or payload.description or "heavy anime beam cast")
	local archetypeId = payload.archetype or payload.motionType or V53.inferArchetype(intent)
	local archetype = V53.catalog()[archetypeId] or V53.catalog().beamCast
	local explicitStyle = payload.style ~= nil
	local styleId = payload.style or V42.inferStyle(intent)
	if not explicitStyle and archetype.defaultStyle and not V53.matchAny(V53.lower(intent), { "realistic", "snappy", "anime", "cartoony", "heavy", "floaty", "robotic", "cinematic" }) then styleId = archetype.defaultStyle end
	local style = V42.styleCatalog[styleId] or V42.styleCatalog.snappy
	local powerName, powerScale = V53.powerLevel(intent)
	local timing, length = V53.phaseTiming(archetype.id, style, powerScale)
	local result = { at = isoNow(), version = VERSION, status = "ok", intent = intent, archetype = archetype, animationType = archetype.kind, style = style, power = { id = powerName, scale = powerScale }, handedness = V53.handedness(intent), gameplayRole = archetype.cues and archetype.cues.hitbox or "animation/readability", bodyFocus = V53.inferFocus(intent, archetype.id), phaseTiming = timing, length = length, requiredMarkers = archetype.markers, sync = archetype.cues, nextCommand = "tools\\bridge.cmd animation choreograph <rigPath> \"" .. intent .. "\"" }
	V53.last.breakdown = result
	return result
end

function V53.enhancedPose(kind, archetypeId, phase, amount, style, handed, family)
	local poses = family == "R6" and V42.r6Pose(kind, phase, amount, style) or V42.r15Pose(kind, phase, amount, style)
	if family ~= "R6" then
		local function add(name, rotation, scalar)
			if not poses[name] then V42.addPose(poses, name, rotation, amount * (scalar or 1), nil, style.easing, style.direction) end
		end
		if archetypeId == "dashSlash" then
			if phase == "anticipation" then add("LowerTorso", { 10, 0, 0 }, 0.85); add("RightUpperLeg", { -20, 0, 0 }, 0.9); add("LeftUpperLeg", { 28, 0, 0 }, 0.9) end
			if phase == "action" or phase == "impact" then add("LowerTorso", { -8, -18, 6 }, 0.8); add("RightUpperLeg", { 18, 0, 0 }, 0.7); add("LeftUpperLeg", { -26, 0, 0 }, 0.7) end
		elseif archetypeId == "groundSlam" then
			if phase == "anticipation" then add("UpperTorso", { 18, 0, 0 }, 1); add("LowerTorso", { 12, 0, 0 }, 1); add("RightUpperLeg", { -18, 0, 0 }, 0.8); add("LeftUpperLeg", { -18, 0, 0 }, 0.8) end
			if phase == "impact" then add("UpperTorso", { -32, 0, 0 }, 1); add("LowerTorso", { -20, 0, 0 }, 1); add("Head", { -18, 0, 0 }, 1) end
		elseif archetypeId == "shieldBlock" then
			if phase == "action" or phase == "impact" then add("UpperTorso", { 3, 0, 0 }, 0.5); add("RightUpperArm", { -38, 0, 55 }, 1); add("LeftUpperArm", { -38, 0, -55 }, 1); add("RightLowerArm", { -70, 0, 0 }, 0.8); add("LeftLowerArm", { -70, 0, 0 }, 0.8) end
		elseif archetypeId == "healCast" or archetypeId == "portalCast" then
			if phase == "action" or phase == "impact" then add("UpperTorso", { -4, 12, 0 }, 0.55); add("RightUpperArm", { -54, 34, 46 }, 0.8); add("LeftUpperArm", { -34, -30, -36 }, 0.65); add("Head", { -3, 10, 0 }, 0.5) end
		elseif archetypeId == "combatIdle" then
			if phase == "anticipation" or phase == "impact" then add("UpperTorso", { -2, 5, 0 }, 0.4); add("LowerTorso", { 1, -3, 0 }, 0.35); add("RightUpperArm", { -8, 0, 12 }, 0.45); add("LeftUpperArm", { -8, 0, -12 }, 0.45) end
		elseif archetypeId == "bossRoar" or archetypeId == "cinematicUltimate" then
			if phase == "impact" or phase == "hold" then add("UpperTorso", { -12, 0, 0 }, 1); add("Head", { -20, 0, 0 }, 0.9); add("RightUpperArm", { -22, 0, 74 }, 1); add("LeftUpperArm", { -22, 0, -74 }, 1) end
		end
	end
	if handed == "left" then
		local mirrored = {}
		for name, pose in pairs(poses) do mirrored[V42.mirrorName(name)] = V42.mirrorPose(pose) end
		poses = mirrored
	end
	return poses
end

function V53.markerSet(breakdown)
	local markers, timing = {}, breakdown.phaseTiming or {}
	for _, name in ipairs(breakdown.requiredMarkers or {}) do
		local lower = V53.lower(name)
		local time = timing.impact or timing.action or 0
		if lower:find("anticip", 1, true) or lower:find("charge", 1, true) or lower:find("draw", 1, true) or lower:find("inhale", 1, true) then time = timing.anticipation or time end
		if lower:find("start", 1, true) and not lower:find("damage", 1, true) then time = timing.action or time end
		if lower == "damagewindowstart" or lower:find("windowstart", 1, true) then time = timing.action or time end
		if lower == "damagewindowend" or lower:find("windowend", 1, true) then time = timing.followThrough or time end
		if lower:find("peak", 1, true) or lower:find("impact", 1, true) or lower:find("fire", 1, true) or lower:find("burst", 1, true) or lower:find("sound", 1, true) then time = timing.impact or time end
		if lower:find("recover", 1, true) or lower:find("end", 1, true) or lower:find("close", 1, true) then time = timing.recovery or time end
		table.insert(markers, { name = name, time = V42.roundTime(time), value = name })
	end
	return markers
end

function V53.buildChoreographySpec(payload)
	payload = payload or {}
	local breakdown = V53.getAnimationIntentBreakdown(payload)
	local rig = V40.resolveRig(payload)
	local family = V42.rigFamily(rig)
	local style, kind, timing = breakdown.style or V42.styleCatalog.snappy, breakdown.animationType or "projectileCast", breakdown.phaseTiming
	local amount = (tonumber(payload.exaggeration) or (tonumber(style.exaggeration) or 1)) * (breakdown.power and breakdown.power.scale or 1)
	local phaseRows = {
		{ "start", timing.start, {} },
		{ "anticipation", timing.anticipation, V53.enhancedPose(kind, breakdown.archetype.id, "anticipation", amount, style, breakdown.handedness, family) },
		{ "buildup", timing.buildup, V53.enhancedPose(kind, breakdown.archetype.id, "anticipation", amount * 1.12, style, breakdown.handedness, family) },
		{ "action", timing.action, V53.enhancedPose(kind, breakdown.archetype.id, "action", amount, style, breakdown.handedness, family) },
		{ "impact", timing.impact, V53.enhancedPose(kind, breakdown.archetype.id, "impact", amount * 1.1, style, breakdown.handedness, family) },
		{ "hold", timing.hold, V53.enhancedPose(kind, breakdown.archetype.id, "impact", amount * 0.92, style, breakdown.handedness, family) },
		{ "followThrough", timing.followThrough, V53.enhancedPose(kind, breakdown.archetype.id, "followThrough", amount, style, breakdown.handedness, family) },
		{ "recovery", timing.recovery, V53.enhancedPose(kind, breakdown.archetype.id, "recovery", amount * 0.8, style, breakdown.handedness, family) },
		{ "final", timing.final, {} },
	}
	local keyframes = {}
	for _, row in ipairs(phaseRows) do
		table.insert(keyframes, { phase = row[1], time = V42.roundTime(row[2] or 0), poses = row[3] or {}, easingStyle = row[1] == "impact" and "Quad" or style.easing, easingDirection = (row[1] == "start" or row[1] == "anticipation") and "Out" or (row[1] == "final" and "In" or style.direction) })
	end
	local safeIntent = tostring(breakdown.intent or "Animation"):gsub("[^%w]+", "_")
	local spec = {
		animationName = V40.safeAnimationName(tostring(payload.animationName or payload.name or (breakdown.style.id .. "_" .. breakdown.archetype.id .. "_" .. safeIntent)):sub(1, 72)),
		intent = breakdown.intent,
		style = breakdown.style.id,
		animationType = kind,
		archetype = breakdown.archetype.id,
		length = breakdown.length,
		looped = kind == "idle",
		priority = kind == "idle" and "Idle" or "Action4",
		keyframes = keyframes,
		markers = V53.markerSet(breakdown),
		soundCues = { SoundCue = timing.impact, Recovery = timing.recovery },
		vfxCues = { VFXBurst = timing.impact, ChargeStart = timing.anticipation },
		cameraCues = { ImpactShake = timing.impact, FrameHold = timing.hold },
		ChoreographyManifest = { version = VERSION, archetype = breakdown.archetype.id, purpose = breakdown.gameplayRole, bodyFocus = breakdown.bodyFocus, phaseTiming = timing, bodyMechanics = breakdown.archetype.bodyFocus },
		AbilitySyncManifest = { damageWindowStart = timing.action, damageWindowEnd = timing.followThrough, fire = timing.impact, recovery = timing.recovery, vfxCue = "VFXBurst", soundCue = "SoundCue" },
	}
	local removed = {}
	spec, removed = V42.filterSpecForRig(spec, rig)
	return spec, { breakdown = breakdown, rig = rig and safeFullName(rig) or nil, removedMissingTargets = removed }
end

function V53.getAnimationAbilityMotionPlan(payload)
	payload = payload or {}
	local abilityText = tostring(payload.abilityIntent or payload.intent or payload.abilityPath or payload.path or "heavy ability cast")
	local spec, meta = V53.buildChoreographySpec({ rigPath = payload.rigPath, intent = abilityText, style = payload.style })
	local audit = V53.getAnimationMotionQualityAudit({ animation = spec, rigPath = payload.rigPath })
	local result = { at = isoNow(), version = VERSION, status = "ready", abilityIntent = abilityText, breakdown = meta.breakdown, animation = spec, quality = audit, nextCommand = "tools\\bridge.cmd animation choreograph <rigPath> \"" .. abilityText .. "\"" }
	V53.last.abilityPlan = result
	return result
end

function V53.getAnimationPoseRecipeCatalog(payload)
	local recipes = {}
	for _, item in ipairs(V53.catalogList()) do table.insert(recipes, { id = item.id, title = item.title, style = item.defaultStyle, animationType = item.kind, bodyFocus = item.bodyFocus, markers = item.markers, example = "tools\\bridge.cmd animation choreograph Workspace.Rig \"" .. item.title .. " " .. (item.defaultStyle or "snappy") .. "\"" }) end
	return { at = isoNow(), version = VERSION, status = "ok", recipes = recipes, nextCommand = "tools\\bridge.cmd animation choreograph <rigPath> <intent>" }
end

function V53.getAnimationMotionQualityAudit(payload)
	local base = V42.getAnimationQualityAudit(payload or {})
	local spec = V42.specFromPayload(payload or {})
	if not spec then return base end
	local score = tonumber(base.score or 0) or 0
	local warnings = V42.cloneSpec(base.warnings or {}) or {}
	local recommendations = V42.cloneSpec(base.recommendations or {}) or {}
	local stats = base.stats or {}
	local function penalize(points, warning, recommendation)
		score -= points
		table.insert(warnings, warning)
		if recommendation then table.insert(recommendations, recommendation) end
	end
	local phaseNames = {}
	for _, frame in ipairs(spec.keyframes or {}) do if frame.phase then phaseNames[tostring(frame.phase)] = true end end
	if not (phaseNames.anticipation or V42.hasMarker(stats, { "Anticipation", "ChargeStart" })) then penalize(8, "Motion has weak anticipation staging.", "Add a readable wind-up/charge pose before action.") end
	if not (phaseNames.impact or V42.hasMarker(stats, { "Impact", "Fire", "Hit" })) then penalize(10, "Motion lacks a clear impact/readability moment.", "Hold or exaggerate the impact frame and add impact/VFX markers.") end
	if not V42.hasMarker(stats, { "DamageWindowStart", "Fire", "HealPulse", "TeleportWindow", "GuardActive" }) then penalize(6, "Gameplay timing markers are thin.", "Add role-specific gameplay markers for hitbox or effect timing.") end
	local poseSet = stats.poseNames or {}
	if not (poseSet.UpperTorso or poseSet.Torso) then penalize(10, "Torso is not meaningfully posed.", "Use torso/hip rotation so the motion reads from the body, not only arms.") end
	if not (poseSet.LowerTorso or poseSet.RightUpperLeg or poseSet.LeftUpperLeg or poseSet["Right Leg"] or poseSet["Left Leg"]) then penalize(8, "Lower body support is missing.", "Add stance/leg support to reduce floaty upper-body motion.") end
	if not poseSet.Head then penalize(4, "Head/aim direction is not staged.", "Use head motion to guide player attention.") end
	base.score = math.clamp(math.floor(score + 0.5), 0, 100)
	base.motionGrade = base.score >= 90 and "pro-ready" or (base.score >= 75 and "solid" or (base.score >= 55 and "needs-polish" or "rough"))
	base.grade = base.motionGrade
	base.warnings = warnings
	base.recommendations = recommendations
	base.motionCriteria = { silhouette = "torso/head/limb coverage and impact staging", bodyMechanics = "torso, lower-body support, anticipation, follow-through", sync = "gameplay/VFX/sound marker coverage" }
	base.nextCommand = "tools\\bridge.cmd animation polish <rigPath> <animationPath-or-json>"
	V53.last.motionAudit = base
	return base
end

function V53.getAnimationVfxSyncReport(payload)
	local spec = V42.specFromPayload(payload or {})
	if not spec then return { at = isoNow(), version = VERSION, status = "notFound", blockers = { "Animation/spec was not found." } } end
	local stats = V42.collectSpecStats(spec)
	local sync = { charge = stats.markers.ChargeStart or stats.markers.Anticipation, fire = stats.markers.Fire or stats.markers.Impact, impact = stats.markers.Impact or stats.markers.VFXBurst, damageWindowStart = stats.markers.DamageWindowStart, damageWindowEnd = stats.markers.DamageWindowEnd, recovery = stats.markers.Recovery }
	local missing = {}
	for _, key in ipairs({ "fire", "impact", "recovery" }) do if sync[key] == nil then table.insert(missing, key) end end
	local result = { at = isoNow(), version = VERSION, status = #missing == 0 and "ready" or "needsMarkers", animationPath = payload and (payload.animationPath or payload.path) or nil, vfxPath = payload and (payload.vfxPath or payload.vfx or payload.abilityPath) or nil, sync = sync, missing = missing, recommendedVfxMarkers = { "ChargeStart", "Fire", "Impact", "VFXBurst", "SoundCue", "Recovery" }, nextCommand = "tools\\bridge.cmd animation sync-vfx <animationPath> <vfx-or-ability-path>" }
	V53.last.vfxSync = result
	return result
end

function V53.variantSpec(payload)
	local spec = V42.specFromPayload(payload or {})
	if not spec then error("generateAnimationVariant requires an animation path or spec.") end
	local variant = V53.lower(payload.variant or payload.variantType or payload.mode or "heavy")
	local clone = V42.cloneSpec(spec)
	clone.animationName = V40.safeAnimationName(tostring(clone.animationName or clone.name or "Animation"):gsub("_v%d%d%d$", "") .. "_" .. variant:gsub("[^%w]+", "_"))
	local scale, exaggeration = 1, 1
	if variant == "light" then scale = 0.82; exaggeration = 0.78 elseif variant == "heavy" then scale = 1.15; exaggeration = 1.18 elseif variant == "finisher" or variant == "cinematic" or variant == "boss" then scale = 1.28; exaggeration = 1.35 elseif variant == "mobile-readable" then scale = 1.08; exaggeration = 1.12 elseif variant == "short-cast" then scale = 0.75 elseif variant == "long-cast" then scale = 1.35 elseif variant == "low-motion" then exaggeration = 0.58 elseif variant == "mirrored" then clone = V42.mirrorSpec(clone, "swap-left-right") end
	clone = V42.retimeSpec(clone, scale)
	for _, frame in ipairs(clone.keyframes or {}) do
		for _, pose in pairs(frame.poses or {}) do
			local rotation = pose.rotation or pose.rotationEulerDegrees
			if type(rotation) == "table" then
				for index = 1, 3 do rotation[index] = V42.roundTime((tonumber(rotation[index] or 0) or 0) * exaggeration) end
				pose.rotation = rotation
				pose.rotationEulerDegrees = rotation
			end
		end
	end
	clone.variant = variant
	clone.variantGeneratedBy = "CodexStudioBridge V53"
	return clone
end

function V53.getAnimationVariantPlan(payload)
	local spec = V53.variantSpec(payload or {})
	local audit = V53.getAnimationMotionQualityAudit({ animation = spec, rigPath = payload and payload.rigPath or nil })
	return { at = isoNow(), version = VERSION, status = "ready", variant = payload and (payload.variant or payload.variantType) or "heavy", animation = spec, audit = audit, nextCommand = "tools\\bridge.cmd animation variant <animationPath> <variantType>" }
end

function V53.getAnimationCurveReport(payload)
	local spec = V42.specFromPayload(payload or {})
	if not spec then return { at = isoNow(), version = VERSION, status = "notFound", blockers = { "Animation/spec was not found." } } end
	local frames = {}
	for _, frame in ipairs(spec.keyframes or {}) do
		local poseCount = 0
		for _ in pairs(frame.poses or {}) do poseCount += 1 end
		table.insert(frames, { time = frame.time, phase = frame.phase, easingStyle = frame.easingStyle, easingDirection = frame.easingDirection, poseCount = poseCount })
	end
	return { at = isoNow(), version = VERSION, status = "ok", length = spec.length, keyframes = frames, markers = spec.markers or {}, nextCommand = "tools\\bridge.cmd animation scrub <rigPath> <animationPath> <seconds>" }
end

function V53.choreographAnimationFromIntent(payload)
	local spec, meta = V53.buildChoreographySpec(payload or {})
	local result = V40.saveGeneratedAnimation({ animation = spec, rigPath = payload and payload.rigPath or nil })
	result.kind = "choreographedAnimationFromIntent"
	result.choreography = meta.breakdown
	result.motionQuality = V53.getAnimationMotionQualityAudit({ animation = spec, rigPath = payload and payload.rigPath or nil })
	V53.last.choreographed = result
	return result
end

function V53.generateAnimationVariant(payload)
	local spec = V53.variantSpec(payload or {})
	local result = V40.saveGeneratedAnimation({ animation = spec, rigPath = payload and payload.rigPath or nil })
	result.kind = "generatedAnimationVariant"
	result.motionQuality = V53.getAnimationMotionQualityAudit({ animation = spec, rigPath = payload and payload.rigPath or nil })
	V53.last.variant = result
	return result
end

function V53.applyAnimationMotionPolish(payload)
	local spec
	if payload and (payload.animationPath or payload.path or payload.animation) then spec = V42.polishedSpec(payload) else spec = V53.buildChoreographySpec(payload or {}) end
	spec.MotionQualityAudit = V53.getAnimationMotionQualityAudit({ animation = spec, rigPath = payload and payload.rigPath or nil })
	local result = V40.saveGeneratedAnimation({ animation = spec, rigPath = payload and payload.rigPath or nil })
	result.kind = "appliedAnimationMotionPolish"
	result.motionQuality = spec.MotionQualityAudit
	V53.last.motionPolish = result
	return result
end

function V53.applyAnimationMarkerSync(payload)
	local spec = V42.specFromPayload(payload or {})
	if not spec then error("applyAnimationMarkerSync requires an animation path or spec.") end
	spec = V42.cloneSpec(spec)
	local sync = V53.getAnimationVfxSyncReport(payload or {})
	for _, markerName in ipairs(sync.recommendedVfxMarkers or {}) do
		local time = (sync.sync and (sync.sync.fire or sync.sync.impact or sync.sync.recovery)) or tonumber(spec.length or 0) or 0
		if markerName == "ChargeStart" then time = sync.sync and sync.sync.charge or time end
		if markerName == "Recovery" then time = sync.sync and sync.sync.recovery or time end
		V42.ensureMarker(spec, markerName, V42.roundTime(time))
	end
	spec.AbilitySyncManifest = sync.sync
	local result = V40.saveGeneratedAnimation({ animation = spec, rigPath = payload and payload.rigPath or nil })
	result.kind = "appliedAnimationMarkerSync"
	result.sync = sync
	V53.last.markerSync = result
	return result
end

function V53.bakeAnimationChoreographyManifest(payload)
	local spec = V42.specFromPayload(payload or {})
	if not spec then error("bakeAnimationChoreographyManifest requires an animation path or spec.") end
	spec = V42.cloneSpec(spec)
	spec.ChoreographyManifest = spec.ChoreographyManifest or { version = VERSION, source = "V53.bakeAnimationChoreographyManifest", intent = spec.intent, archetype = spec.archetype or V53.inferArchetype(spec.intent or spec.animationName or "") }
	spec.MotionQualityAudit = V53.getAnimationMotionQualityAudit({ animation = spec, rigPath = payload and payload.rigPath or nil })
	local result = V40.saveGeneratedAnimation({ animation = spec, rigPath = payload and payload.rigPath or nil })
	result.kind = "bakedAnimationChoreographyManifest"
	V53.last.manifest = result
	return result
end

function V53.getAnimationChoreographerReport(payload)
	return { at = isoNow(), version = VERSION, status = "ok", catalog = V53.getAnimationChoreographyCatalog(payload), poseRecipes = V53.getAnimationPoseRecipeCatalog(payload), last = V53.last, recommendedWorkflow = { "tools\\bridge.cmd animation choreograph <rigPath> \"intent\"", "tools\\bridge.cmd animation motion-audit <rigPath> <animationPath>", "tools\\bridge.cmd animation variant <animationPath> heavy", "tools\\bridge.cmd preview_animation <rigPath> <animationPath>" }, nextCommand = "tools\\bridge.cmd animation choreograph <rigPath> \"heavy anime beam cast\"" }
end

-- V54 Cinematic Motion + VFX Fusion Director
function V54.lower(value)
	return string.lower(tostring(value or ""))
end

function V54.catalog()
	return {
		beamCast = { title = "Beam Cast", keywords = { "beam", "laser", "kame", "blast" }, motion = "beamCast", vfx = "beam", details = { "bodyAura", "handGlow", "chargeSparks", "muzzleFlash", "beamCore", "beamRim", "impactBurst", "shockwave", "smokeResidue", "soundCue", "cameraCue" }, markers = { "Anticipation", "ChargeStart", "MuzzleFlash", "Fire", "DamageWindowStart", "Impact", "VFXBurst", "SoundCue", "CameraCue", "Residue", "Recovery" } },
		projectile = { title = "Projectile", keywords = { "projectile", "fireball", "orb", "shot" }, motion = "beamCast", vfx = "projectile", details = { "handGlow", "muzzleFlash", "projectileCore", "projectileTrail", "travelWisps", "impactBurst", "hitSparks", "dustRing", "soundCue" }, markers = { "Anticipation", "ChargeStart", "MuzzleFlash", "ProjectileSpawn", "Fire", "Impact", "VFXBurst", "Residue", "Recovery" } },
		swordSlash = { title = "Sword Slash", keywords = { "slash", "sword", "katana", "blade", "axe" }, motion = "swordSlash", vfx = "slash", details = { "weaponEnchant", "bladeGlint", "slashTrail", "airCut", "hitSparks", "impactBurst", "smokeResidue", "soundCue", "cameraCue" }, markers = { "Anticipation", "ChargeStart", "DamageWindowStart", "Fire", "Impact", "VFXBurst", "DamageWindowEnd", "Recovery" } },
		dashStrike = { title = "Dash Strike", keywords = { "dash", "blink", "lunge", "rush" }, motion = "dashSlash", vfx = "slash", details = { "footDust", "afterimage", "weaponTrail", "speedLines", "impactBurst", "shockwave", "soundCue", "cameraCue" }, markers = { "Anticipation", "ChargeStart", "Fire", "DamageWindowStart", "Impact", "VFXBurst", "DamageWindowEnd", "Recovery" } },
		groundSlam = { title = "Ground Slam", keywords = { "slam", "ground", "meteor", "crater" }, motion = "groundSlam", vfx = "explosion", details = { "bodyAura", "groundGlyph", "impactBurst", "dustRing", "rockDebris", "shockwave", "smokeResidue", "cameraCue" }, markers = { "Anticipation", "ChargeStart", "Fire", "Impact", "VFXBurst", "CameraCue", "Residue", "Recovery" } },
		shield = { title = "Shield / Barrier", keywords = { "shield", "barrier", "block", "guard" }, motion = "shieldBlock", vfx = "shield", details = { "handGlow", "barrierSurface", "rimPulse", "impactRipple", "sparkDeflect", "soundCue" }, markers = { "Anticipation", "ChargeStart", "Fire", "VFXBurst", "Recovery" } },
		heal = { title = "Healing Cast", keywords = { "heal", "healing", "restore", "blessing" }, motion = "healCast", vfx = "healing", details = { "bodyAura", "handGlow", "risingMotes", "circleGlyph", "softBloom", "soundCue" }, markers = { "Anticipation", "ChargeStart", "Fire", "VFXBurst", "Residue", "Recovery" } },
		portal = { title = "Portal / Rift", keywords = { "portal", "rift", "gate", "teleport" }, motion = "portalCast", vfx = "portal", details = { "handGlow", "circleGlyph", "swirlCore", "rimPulse", "ambientWisps", "soundCue", "cameraCue" }, markers = { "Anticipation", "ChargeStart", "Fire", "VFXBurst", "Residue", "Recovery" } },
		aura = { title = "Body Aura", keywords = { "aura", "power up", "transform", "charge up" }, motion = "handCharge", vfx = "aura", details = { "bodyAura", "handGlow", "risingMotes", "groundGlyph", "rimLight", "soundCue", "cameraCue" }, markers = { "Anticipation", "ChargeStart", "VFXBurst", "SoundCue", "Recovery" } },
		hitReaction = { title = "Hit Reaction", keywords = { "hit reaction", "flinch", "stagger", "knockback" }, motion = "hitReaction", vfx = "hitBurst", details = { "hitSparks", "impactBurst", "briefFlash", "dustPuff", "soundCue" }, markers = { "Impact", "VFXBurst", "Recovery" } },
		cinematicUltimate = { title = "Cinematic Ultimate", keywords = { "ultimate", "cinematic", "finisher", "super" }, motion = "cinematicUltimate", vfx = "ultimate", details = { "bodyAura", "handGlow", "weaponEnchant", "chargeSparks", "muzzleFlash", "beamCore", "shockwave", "impactBurst", "smokeResidue", "soundCue", "cameraCue" }, markers = { "Anticipation", "ChargeStart", "MuzzleFlash", "Fire", "DamageWindowStart", "Impact", "VFXBurst", "SoundCue", "CameraCue", "Residue", "Recovery" } },
	}
end

function V54.catalogList()
	local list = {}
	for id, item in pairs(V54.catalog()) do
		local copy = {}
		for key, value in pairs(item) do copy[key] = value end
		copy.id = id
		table.insert(list, copy)
	end
	table.sort(list, function(a, b) return tostring(a.id) < tostring(b.id) end)
	return list
end

function V54.getMotionVfxFusionCatalog(payload)
	return {
		at = isoNow(),
		version = VERSION,
		status = "ok",
		archetypes = V54.catalogList(),
		detailRoles = { "bodyAura", "handGlow", "weaponEnchant", "muzzleFlash", "projectileCore", "projectileTrail", "beamCore", "slashTrail", "impactBurst", "hitSparks", "shockwave", "dustRing", "smokeResidue", "soundCue", "cameraCue" },
		markerModel = { "Anticipation", "ChargeStart", "MuzzleFlash", "Fire", "ProjectileSpawn", "DamageWindowStart", "Impact", "VFXBurst", "SoundCue", "CameraCue", "Residue", "Recovery" },
		nextCommand = "tools\\bridge.cmd motion-vfx plan \"heavy purple beam attack with body aura and impact burst\"",
	}
end

function V54.matchAny(text, words)
	for _, word in ipairs(words or {}) do
		if text:find(V54.lower(word), 1, true) then return true end
	end
	return false
end

function V54.inferArchetype(intent)
	local text = V54.lower(intent)
	for id, item in pairs(V54.catalog()) do
		if V54.matchAny(text, item.keywords) then return id end
	end
	if V54.matchAny(text, { "charge", "power" }) then return "aura" end
	return "beamCast"
end

function V54.styleFromIntent(intent)
	local text = V54.lower(intent)
	if V54.matchAny(text, { "dark", "shadow", "void" }) then return "shadow" end
	if V54.matchAny(text, { "purple", "arcane", "magic" }) then return "arcanePurple" end
	if V54.matchAny(text, { "fire", "flame", "burn" }) then return "fire" end
	if V54.matchAny(text, { "ice", "frost", "snow" }) then return "ice" end
	if V54.matchAny(text, { "lightning", "electric", "thunder" }) then return "electric" end
	if V54.matchAny(text, { "heal", "holy", "blessing" }) then return "healing" end
	return V43.inferStyle(intent)
end

function V54.powerFromIntent(intent)
	local name, scale = V53.powerLevel(intent)
	if V54.matchAny(V54.lower(intent), { "tiny", "small", "minor" }) then return "light", 0.78 end
	return name, scale
end

function V54.round(value)
	return math.floor((tonumber(value) or 0) * 100 + 0.5) / 100
end

function V54.detailPhase(detail)
	local phases = {
		bodyAura = "buildup",
		handGlow = "charge",
		weaponEnchant = "charge",
		chargeSparks = "charge",
		muzzleFlash = "release",
		projectileCore = "travel",
		projectileTrail = "travel",
		travelWisps = "travel",
		beamCore = "release",
		beamRim = "release",
		slashTrail = "action",
		airCut = "action",
		impactBurst = "impact",
		hitSparks = "impact",
		shockwave = "impact",
		dustRing = "impact",
		rockDebris = "impact",
		smokeResidue = "residue",
		soundCue = "audio",
		cameraCue = "camera",
	}
	return phases[detail] or "support"
end

function V54.timelineFromBreakdown(breakdown)
	local timing = breakdown.animation and breakdown.animation.phaseTiming or {}
	local length = tonumber(breakdown.animation and breakdown.animation.length) or 1.35
	local function t(name, fallback)
		return V54.round(timing[name] or fallback)
	end
	return {
		{ time = 0, marker = "Start", purpose = "package begins" },
		{ time = t("anticipation", length * 0.12), marker = "Anticipation", purpose = "pose readability and pre-glow" },
		{ time = t("buildup", length * 0.26), marker = "ChargeStart", purpose = "start charge/aura/detail buildup" },
		{ time = t("action", length * 0.48), marker = "DamageWindowStart", purpose = "begin gameplay/action window metadata" },
		{ time = t("action", length * 0.54), marker = "MuzzleFlash", purpose = "one-frame release flash when applicable" },
		{ time = t("action", length * 0.56), marker = "Fire", purpose = "main launch, slash, or activation beat" },
		{ time = t("action", length * 0.58), marker = "ProjectileSpawn", purpose = "spawn projectile/beam core metadata" },
		{ time = t("impact", length * 0.66), marker = "Impact", purpose = "impact pose and hit VFX" },
		{ time = t("impact", length * 0.68), marker = "VFXBurst", purpose = "burst particles, shockwave, hit sparks" },
		{ time = t("impact", length * 0.7), marker = "SoundCue", purpose = "strongest sound beat" },
		{ time = t("impact", length * 0.71), marker = "CameraCue", purpose = "camera shake/framing cue metadata" },
		{ time = t("hold", length * 0.76), marker = "DamageWindowEnd", purpose = "end gameplay/action window metadata" },
		{ time = t("followThrough", length * 0.84), marker = "Residue", purpose = "smoke, motes, afterglow cleanup tail" },
		{ time = t("recovery", length * 0.94), marker = "Recovery", purpose = "return to control/readable idle" },
	}
end

function V54.getMotionVfxIntentBreakdown(payload)
	payload = payload or {}
	local intent = tostring(payload.intent or payload.text or payload.prompt or payload.goal or "cinematic motion VFX package")
	local archetypeId = payload.archetype or V54.inferArchetype(intent)
	local archetype = V54.catalog()[archetypeId] or V54.catalog().beamCast
	local style = tostring(payload.style or V54.styleFromIntent(intent))
	local powerName, powerScale = V54.powerFromIntent(intent)
	local animation = V53.getAnimationIntentBreakdown({ intent = intent, motionType = archetype.motion, style = payload.animationStyle or payload.style })
	local vfx = V51.getProVfxIntentPlan({ intent = intent, effectType = archetype.vfx, style = style, assetRoot = payload.assetRoot })
	local result = {
		at = isoNow(),
		version = VERSION,
		status = "ok",
		intent = intent,
		archetype = { id = archetypeId, title = archetype.title, motion = archetype.motion, vfx = archetype.vfx },
		style = style,
		power = { id = powerName, scale = powerScale },
		animation = animation,
		vfx = { effectType = archetype.vfx, plan = vfx },
		requiredDetails = archetype.details,
		requiredMarkers = archetype.markers,
		nextCommand = "tools\\bridge.cmd motion-vfx plan \"" .. intent .. "\"",
	}
	V54.last.breakdown = result
	return result
end

function V54.getMotionVfxDetailPlan(payload)
	local breakdown = payload and payload.breakdown or V54.getMotionVfxIntentBreakdown(payload or {})
	local timeline = V54.timelineFromBreakdown(breakdown)
	local markerTime = {}
	for _, entry in ipairs(timeline) do markerTime[entry.marker] = entry.time end
	local layers = {}
	for index, detail in ipairs(breakdown.requiredDetails or {}) do
		local phase = V54.detailPhase(detail)
		local marker = phase == "impact" and "Impact" or (phase == "release" and "MuzzleFlash" or (phase == "travel" and "ProjectileSpawn" or (phase == "audio" and "SoundCue" or (phase == "camera" and "CameraCue" or (phase == "residue" and "Residue" or "ChargeStart")))))
		table.insert(layers, {
			id = string.format("%02d_%s", index, detail),
			role = detail,
			phase = phase,
			marker = marker,
			time = markerTime[marker] or 0,
			target = payload and (payload.targetPath or payload.target) or nil,
			reason = "Required readability/detail layer for " .. tostring(breakdown.archetype and breakdown.archetype.title or "motion VFX"),
		})
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		status = "ready",
		intent = breakdown.intent,
		archetype = breakdown.archetype,
		detailLayers = layers,
		timeline = timeline,
		nextCommand = "tools\\bridge.cmd motion-vfx generate \"" .. tostring(breakdown.intent or "") .. "\"",
	}
	V54.last.detailPlan = result
	return result
end

function V54.packageBaseName(intent, archetypeId)
	local name = tostring(intent or "MotionVfxPackage")
	name = name:gsub("[^%w%s_%-]", " ")
	name = name:gsub("%s+", "_")
	if #name > 34 then name = string.sub(name, 1, 34) end
	return V39.safeName("CodexMotionVfx_" .. tostring(archetypeId or "Fusion") .. "_" .. name, "CodexMotionVfxPackage")
end

function V54.nextPackageName(baseName)
	baseName = V39.safeName(baseName, "CodexMotionVfxPackage")
	local root = resolvePath("ReplicatedStorage.CodexMotionVfxForge.Packages")
	local index = 1
	while true do
		local candidate = string.format("%s_v%03d", baseName, index)
		if not root or not root:FindFirstChild(candidate) then return candidate end
		index += 1
	end
end

function V54.packagePath(name)
	return "ReplicatedStorage.CodexMotionVfxForge.Packages." .. V39.safeName(name, "CodexMotionVfxPackage")
end

function V54.syncManifestFromPlan(plan)
	local timeline = plan.timeline or {}
	local detailByMarker = {}
	for _, layer in ipairs(plan.detailLayers or {}) do
		detailByMarker[layer.marker] = detailByMarker[layer.marker] or {}
		table.insert(detailByMarker[layer.marker], layer.role)
	end
	local manifestMarkers = {}
	for _, entry in ipairs(timeline) do
		table.insert(manifestMarkers, {
			time = entry.time,
			marker = entry.marker,
			purpose = entry.purpose,
			details = detailByMarker[entry.marker] or {},
		})
	end
	return {
		format = "codex-motion-vfx-sync-v1",
		version = VERSION,
		intent = plan.intent,
		archetype = plan.archetype,
		markers = manifestMarkers,
		damageWindows = {
			{ id = "primary", startMarker = "DamageWindowStart", endMarker = "DamageWindowEnd", notes = "Metadata only; production damage is not wired by V54." },
		},
		soundCues = {
			{ marker = "SoundCue", role = "main impact/release sound", notes = "Use generated VFX sound layer or game-selected sound asset." },
		},
		cameraCues = {
			{ marker = "CameraCue", role = "brief shake/framing emphasis", notes = "Camera cue metadata only unless a game camera system consumes it." },
		},
	}
end

function V54.getMotionVfxSyncManifest(payload)
	local plan = payload and payload.plan or V54.getMotionVfxPackagePlan(payload or {})
	local manifest = plan.syncManifest or V54.syncManifestFromPlan(plan)
	local result = { at = isoNow(), version = VERSION, status = "ok", manifest = manifest, nextCommand = "tools\\bridge.cmd motion-vfx generate <intent>" }
	V54.last.syncManifest = result
	return result
end

function V54.getMotionVfxPackagePlan(payload)
	payload = payload or {}
	local breakdown = payload.breakdown or V54.getMotionVfxIntentBreakdown(payload)
	local detailPlan = V54.getMotionVfxDetailPlan({ breakdown = breakdown, targetPath = payload.targetPath or payload.target })
	local baseName = payload.name and V39.safeName(payload.name, "CodexMotionVfxPackage") or V54.packageBaseName(breakdown.intent, breakdown.archetype and breakdown.archetype.id)
	local versionName = payload.packageName or V54.nextPackageName(baseName)
	local packagePath = V54.packagePath(versionName)
	local animationSpec, animationMeta = V53.buildChoreographySpec({ rigPath = payload.rigPath, intent = breakdown.intent, motionType = breakdown.archetype and breakdown.archetype.motion, style = payload.animationStyle })
	local vfxPreset, vfxMeta = V51.composeProPreset({ intent = breakdown.intent, effectType = breakdown.archetype and breakdown.archetype.vfx, style = breakdown.style, assetRoot = payload.assetRoot, targetPath = payload.targetPath })
	local syncManifest = V54.syncManifestFromPlan(detailPlan)
	local quality = V54.getMotionVfxQualityAudit({ packagePlan = { detailLayers = detailPlan.detailLayers, animation = animationSpec, vfxPreset = vfxPreset, syncManifest = syncManifest, breakdown = breakdown } })
	local result = {
		at = isoNow(),
		version = VERSION,
		status = "ready",
		name = versionName,
		packagePath = packagePath,
		intent = breakdown.intent,
		archetype = breakdown.archetype,
		style = breakdown.style,
		power = breakdown.power,
		animation = animationSpec,
		animationMeta = animationMeta,
		vfxPreset = vfxPreset,
		vfxMeta = vfxMeta,
		detailLayers = detailPlan.detailLayers,
		timeline = detailPlan.timeline,
		syncManifest = syncManifest,
		qualityAudit = quality,
		performancePlan = V54.getMotionVfxPerformancePlan({ vfxPreset = vfxPreset }),
		nextCommand = "tools\\bridge.cmd motion-vfx generate \"" .. tostring(breakdown.intent or "") .. "\"",
	}
	V54.last.packagePlan = result
	return result
end

function V54.getMotionVfxQualityAudit(payload)
	payload = payload or {}
	local plan = payload.packagePlan or payload.plan or {}
	if (not plan.animation and not plan.vfxPreset) and payload.path then
		local target = resolvePath(payload.path)
		if target then
			local score = 82
			local warnings = { "Path audit uses generated package structure plus stored manifests; rerun generation/polish for full in-memory motion and VFX scoring." }
			local hasManifest = target:FindFirstChild("MotionVfxManifest") ~= nil
			local hasSync = target:FindFirstChild("SyncManifest") ~= nil
			local hasQuality = target:FindFirstChild("QualityAudit") ~= nil
			if hasManifest then score += 8 else table.insert(warnings, "MotionVfxManifest is missing.") end
			if hasSync then score += 5 else table.insert(warnings, "SyncManifest is missing.") end
			if hasQuality then score += 5 else table.insert(warnings, "QualityAudit module is missing.") end
			local result = {
				at = isoNow(),
				version = VERSION,
				status = hasManifest and "ready" or "needsManifest",
				score = math.clamp(score, 0, 100),
				path = safeFullName(target),
				className = target.ClassName,
				blockers = hasManifest and {} or { "Generated package manifest is missing." },
				warnings = warnings,
				structure = { motionVfxManifest = hasManifest, syncManifest = hasSync, qualityAudit = hasQuality },
				nextCommand = "tools\\bridge.cmd motion-vfx polish \"" .. safeFullName(target) .. "\"",
			}
			V54.last.qualityAudit = result
			return result
		end
	end
	local animation = plan.animation or payload.animation
	local vfxPreset = plan.vfxPreset or payload.vfxPreset
	local detailLayers = plan.detailLayers or payload.detailLayers or {}
	local syncManifest = plan.syncManifest or payload.syncManifest or {}
	local motionAudit = animation and V53.getAnimationMotionQualityAudit({ animation = animation, rigPath = payload.rigPath }) or nil
	local vfxAudit = vfxPreset and V51.getProVfxQualityAudit({ preset = vfxPreset }) or nil
	local score = 100
	local blockers = {}
	local warnings = {}
	local markerSet = {}
	for _, entry in ipairs(syncManifest.markers or {}) do markerSet[entry.marker] = true end
	for _, marker in ipairs({ "Anticipation", "ChargeStart", "Fire", "Impact", "VFXBurst", "Recovery" }) do
		if not markerSet[marker] then
			score -= 8
			table.insert(warnings, "Missing sync marker: " .. marker)
		end
	end
	if #detailLayers < 6 then
		score -= 14
		table.insert(warnings, "Fusion package has too few detail layers for pro readability.")
	end
	if motionAudit and tonumber(motionAudit.score or 100) < 80 then
		score -= 10
		table.insert(warnings, "Motion audit is below pro target.")
	end
	if vfxAudit and tonumber(vfxAudit.score or 100) < 80 then
		score -= 10
		table.insert(warnings, "VFX audit is below pro target.")
	end
	if not animation then
		score -= 15
		table.insert(blockers, "Animation spec/path is missing.")
	end
	if not vfxPreset then
		score -= 15
		table.insert(blockers, "VFX preset/path is missing.")
	end
	score = math.max(0, math.min(100, score))
	local result = {
		at = isoNow(),
		version = VERSION,
		status = #blockers == 0 and "ready" or "blocked",
		score = score,
		blockers = blockers,
		warnings = warnings,
		motionAudit = motionAudit,
		vfxAudit = vfxAudit,
		criteria = { "motion readability", "body mechanics", "detail completeness", "marker coverage", "VFX sync", "mobile/performance risk", "cleanup safety" },
		nextCommand = score < 92 and "tools\\bridge.cmd motion-vfx polish <packagePath>" or "tools\\bridge.cmd motion-vfx generate <intent>",
	}
	V54.last.qualityAudit = result
	return result
end

function V54.getMotionVfxPerformancePlan(payload)
	payload = payload or {}
	local presetPath = payload.vfxPresetPath or payload.path or ""
	local budget = nil
	if presetPath ~= "" and resolvePath(presetPath) then
		budget = V52.getVfxPerformanceBudget({ path = presetPath, tier = payload.tier or "mobileBalanced" })
	else
		local preset = payload.vfxPreset or (payload.packagePlan and payload.packagePlan.vfxPreset) or nil
		local layerCount = preset and #(preset.layers or {}) or 0
		budget = {
			status = "planned",
			tier = payload.tier or "mobileBalanced",
			stats = { plannedLayers = layerCount, plannedEmitters = layerCount },
			budget = { ok = true, warnings = layerCount > 14 and { "High layer count; consider mobile optimization after generation." } or {} },
		}
	end
	local result = { at = isoNow(), version = VERSION, status = "ready", performance = budget, nextCommand = "tools\\bridge.cmd vfx budget <generatedVfxPath> mobileBalanced" }
	V54.last.performancePlan = result
	return result
end

function V54.manifestSource(manifest)
	return "return { format = \"codex-motion-vfx-fusion-v1\", version = " .. V8.luaString(VERSION) .. ", json = " .. V8.luaString(HttpService:JSONEncode(manifest)) .. " }\n"
end

function V54.packageBlueprint(plan, animationResult, vfxResult, quality)
	local manifest = {
		name = plan.name,
		intent = plan.intent,
		archetype = plan.archetype,
		style = plan.style,
		power = plan.power,
		animationPath = animationResult and animationResult.path or plan.animationPath,
		vfxPresetPath = vfxResult and vfxResult.presetPath or plan.vfxPresetPath,
		detailLayers = plan.detailLayers,
		markers = plan.syncManifest and plan.syncManifest.markers or {},
		timeline = plan.timeline,
		damageWindows = plan.syncManifest and plan.syncManifest.damageWindows or {},
		soundCues = plan.syncManifest and plan.syncManifest.soundCues or {},
		cameraCues = plan.syncManifest and plan.syncManifest.cameraCues or {},
		performanceBudget = plan.performancePlan,
		qualityAudit = quality or plan.qualityAudit,
		generatedAt = isoNow(),
		nextCommands = {
			"tools\\bridge.cmd motion-vfx audit " .. plan.packagePath,
			animationResult and ("tools\\bridge.cmd preview_animation <rigPath> \"" .. animationResult.path .. "\"") or nil,
			vfxResult and ("tools\\bridge.cmd vfx preview-pro \"" .. vfxResult.presetPath .. "\"") or nil,
		},
	}
	local steps = {
		{ type = "ensureInstance", className = "Folder", path = "ReplicatedStorage.CodexMotionVfxForge", properties = {} },
		{ type = "ensureInstance", className = "Folder", path = "ReplicatedStorage.CodexMotionVfxForge.Packages", properties = {} },
		{ type = "ensureInstance", className = "Folder", path = plan.packagePath, properties = {} },
		V25.scriptWriteStep(plan.packagePath .. ".MotionVfxManifest", "ModuleScript", V54.manifestSource(manifest)),
		V25.scriptWriteStep(plan.packagePath .. ".SyncManifest", "ModuleScript", V54.manifestSource(plan.syncManifest or {})),
		V25.scriptWriteStep(plan.packagePath .. ".QualityAudit", "ModuleScript", V54.manifestSource(quality or plan.qualityAudit or {})),
	}
	return { name = "Codex Motion VFX Fusion Package", mode = "fullTrust", source = "V54.generateMotionVfxPackage", steps = steps }, manifest
end

function V54.applyMotionVfxFusionPlan(payload)
	payload = payload or {}
	local plan = payload.plan or V54.getMotionVfxPackagePlan(payload)
	local animationResult = payload.animationResult
	local vfxResult = payload.vfxResult
	local quality = V54.getMotionVfxQualityAudit({ packagePlan = plan, rigPath = payload.rigPath })
	local blueprint, manifest = V54.packageBlueprint(plan, animationResult, vfxResult, quality)
	local result = applyBuildPlan({ blueprint = blueprint })
	result.kind = "motionVfxFusionPlan"
	result.packagePath = plan.packagePath
	result.manifest = manifest
	result.qualityAudit = quality
	V54.last.appliedPlan = result
	return result
end

function V54.generateMotionVfxPackage(payload)
	payload = payload or {}
	local plan = V54.getMotionVfxPackagePlan(payload)
	local animationResult = V53.choreographAnimationFromIntent({ rigPath = payload.rigPath, intent = plan.intent, motionType = plan.archetype and plan.archetype.motion, style = payload.animationStyle or payload.style })
	local vfxResult = V51.generateProVfxFromIntent({ intent = plan.intent, effectType = plan.archetype and plan.archetype.vfx, style = plan.style, assetRoot = payload.assetRoot, targetPath = payload.targetPath })
	plan.animationPath = animationResult and animationResult.path or nil
	plan.vfxPresetPath = vfxResult and vfxResult.presetPath or nil
	local quality = V54.getMotionVfxQualityAudit({ packagePlan = plan, rigPath = payload.rigPath })
	local packageResult = V54.applyMotionVfxFusionPlan({ plan = plan, animationResult = animationResult, vfxResult = vfxResult, rigPath = payload.rigPath })
	packageResult.animation = animationResult
	packageResult.vfx = vfxResult
	packageResult.qualityAudit = quality
	V54.last.generated = packageResult
	return packageResult
end

function V54.polishMotionVfxPackage(payload)
	payload = payload or {}
	local intent = tostring(payload.intent or payload.packageIntent or "polished cinematic motion VFX")
	local sourcePath = payload.packagePath or payload.path
	if sourcePath and sourcePath ~= "" then
		local target = resolvePath(sourcePath)
		if target then intent = target.Name .. " polished pro motion VFX" end
	end
	local plan = V54.getMotionVfxPackagePlan({
		intent = intent .. " stronger anticipation impact residue mobile readability",
		rigPath = payload.rigPath,
		targetPath = payload.targetPath,
		assetRoot = payload.assetRoot,
		style = payload.style,
	})
	local result = V54.applyMotionVfxFusionPlan({ plan = plan, rigPath = payload.rigPath })
	result.kind = "polishedMotionVfxPackage"
	V54.last.polished = result
	return result
end

function V54.syncMotionVfxPackage(payload)
	payload = payload or {}
	local animationPath = tostring(payload.animationPath or payload.animation or payload.path or "")
	local vfxPath = tostring(payload.vfxPath or payload.vfx or payload.targetPath or "")
	local manifest = V54.getMotionVfxSyncManifest({ intent = payload.intent or (animationPath .. " " .. vfxPath) })
	local packageName = V54.nextPackageName(V54.packageBaseName(payload.intent or "SyncedMotionVfx", "sync"))
	local plan = {
		name = packageName,
		packagePath = V54.packagePath(packageName),
		intent = payload.intent or "sync existing animation and VFX",
		archetype = { id = "sync", title = "Existing Animation/VFX Sync" },
		style = payload.style or "custom",
		power = { id = "custom", scale = 1 },
		animationPath = animationPath,
		vfxPresetPath = vfxPath,
		detailLayers = {},
		timeline = {},
		syncManifest = manifest.manifest,
		qualityAudit = {
			at = isoNow(),
			version = VERSION,
			status = (animationPath ~= "" and vfxPath ~= "") and "ready" or "blocked",
			score = (animationPath ~= "" and vfxPath ~= "") and 86 or 55,
			blockers = animationPath == "" and { "Animation path is missing." } or (vfxPath == "" and { "VFX path is missing." } or {}),
			warnings = { "Existing-path sync uses manifest metadata only; run motion-vfx audit after generation for full motion/VFX scoring." },
		},
	}
	local result = V54.applyMotionVfxFusionPlan({ plan = plan })
	result.kind = "syncedMotionVfxPackage"
	V54.last.synced = result
	return result
end

function V54.bakeMotionVfxManifest(payload)
	payload = payload or {}
	local plan = payload.plan or V54.getMotionVfxPackagePlan(payload)
	local result = V54.applyMotionVfxFusionPlan({ plan = plan, rigPath = payload.rigPath })
	result.kind = "bakedMotionVfxManifest"
	V54.last.manifest = result
	return result
end

function V54.getMotionVfxDirectorReport(payload)
	return {
		at = isoNow(),
		version = VERSION,
		status = "ok",
		catalog = V54.getMotionVfxFusionCatalog(payload),
		last = V54.last,
		recommendedWorkflow = {
			"tools\\bridge.cmd motion-vfx plan \"intent\"",
			"tools\\bridge.cmd motion-vfx generate \"intent\"",
			"tools\\bridge.cmd motion-vfx audit <packagePath>",
			"tools\\bridge.cmd preview_animation <rigPath> <generatedAnimationPath>",
			"tools\\bridge.cmd vfx preview-pro <generatedVfxPath>",
		},
		nextCommand = "tools\\bridge.cmd motion-vfx generate \"heavy purple beam attack with body aura, hand charge, muzzle flash, beam trail, and impact burst\"",
	}
end

-- V59 Universal Audio Director + Mix QA
function V59.lower(value)
	return tostring(value or ""):lower()
end

function V59.audioRoots(payload)
	payload = payload or {}
	local explicit = payload.path or payload.root or payload.target
	if explicit and tostring(explicit) ~= "" then
		return { resolvePath(explicit) or game:GetService("SoundService") }
	end
	local roots = {}
	for _, serviceName in ipairs({ "SoundService", "Workspace", "ReplicatedStorage", "StarterGui", "StarterPlayer", "ServerStorage", "ServerScriptService" }) do
		local ok, service = pcall(function() return game:GetService(serviceName) end)
		if ok and service then table.insert(roots, service) end
	end
	return roots
end

function V59.safeRead(instance, propertyName, fallback)
	local ok, value = pcall(function() return instance[propertyName] end)
	if ok then return value end
	return fallback
end

function V59.isAudioInstance(instance)
	if not instance then return false end
	local className = instance.ClassName
	return className == "Sound"
		or className == "SoundGroup"
		or className == "AudioAnalyzer"
		or className == "AudioPlayer"
		or className == "AudioDeviceOutput"
		or className == "AudioChannelMixer"
		or className == "Wire"
end

function V59.roleKeywords()
	return {
		music = { "music", "song", "theme", "ost", "bgm", "loop" },
		ambience = { "ambience", "ambient", "wind", "rain", "forest", "crowd", "room", "atmos" },
		ui = { "ui", "button", "click", "hover", "menu", "close", "open", "select" },
		combat = { "combat", "slash", "sword", "gun", "weapon", "punch", "kick", "shoot" },
		ability = { "ability", "spell", "cast", "charge", "beam", "fireball", "magic", "power" },
		impact = { "impact", "hit", "boom", "explode", "explosion", "burst", "crash", "slam" },
		footsteps = { "foot", "step", "walk", "run", "land" },
		voice = { "voice", "dialog", "dialogue", "talk", "narrator", "line" },
		reward = { "reward", "coin", "cash", "gem", "win", "success", "claim", "pickup" },
		warning = { "warning", "alert", "alarm", "danger", "error", "fail" },
		horrorSting = { "horror", "sting", "scare", "jumpscare", "creepy", "scream" },
		projectile = { "projectile", "muzzle", "laser", "orb", "shot", "arrow" },
		vfxCue = { "vfx", "cue", "whoosh", "swoosh", "spark", "aura", "portal" },
	}
end

function V59.groupForRole(role)
	local map = {
		music = "Music",
		ambience = "Ambience",
		ui = "UI",
		combat = "Combat",
		ability = "Abilities",
		impact = "SFX",
		footsteps = "SFX",
		voice = "Voice",
		reward = "SFX",
		warning = "SFX",
		horrorSting = "SFX",
		projectile = "Abilities",
		vfxCue = "Abilities",
	}
	return map[role] or "SFX"
end

function V59.classifySound(instance)
	if not instance then return "unknown" end
	local text = V59.lower((safeFullName(instance) or "") .. " " .. tostring(V59.safeRead(instance, "SoundId", "")))
	local bestRole = "unknown"
	local bestScore = 0
	for role, words in pairs(V59.roleKeywords()) do
		local score = 0
		for _, word in ipairs(words) do
			if text:find(word, 1, true) then score += 1 end
		end
		if score > bestScore then
			bestScore = score
			bestRole = role
		end
	end
	if bestRole == "unknown" and instance:IsA("Sound") then
		if V59.safeRead(instance, "Looped", false) then return "ambience" end
	end
	return bestRole
end

function V59.loudnessBand(value)
	local loudness = tonumber(value) or 0
	if loudness >= 850 then return "spiking" end
	if loudness >= 550 then return "tooLoud" end
	if loudness >= 250 then return "loud" end
	if loudness >= 50 then return "balanced" end
	if loudness >= 10 then return "low" end
	return "tooLow"
end

function V59.soundSummary(instance)
	local soundId = V59.safeRead(instance, "SoundId", "")
	local soundGroup = V59.safeRead(instance, "SoundGroup", nil)
	local playbackLoudness = V59.safeRead(instance, "PlaybackLoudness", 0)
	local isPlaying = V59.safeRead(instance, "IsPlaying", false)
	local role = V59.classifySound(instance)
	return {
		id = getInstanceId(instance),
		name = instance.Name,
		className = instance.ClassName,
		path = safeFullName(instance),
		parentPath = instance.Parent and safeFullName(instance.Parent) or nil,
		role = role,
		recommendedGroup = V59.groupForRole(role),
		soundId = V39.assetId(soundId),
		rawSoundId = tostring(soundId or ""),
		volume = V59.safeRead(instance, "Volume", nil),
		playbackSpeed = V59.safeRead(instance, "PlaybackSpeed", nil),
		looped = V59.safeRead(instance, "Looped", nil),
		isPlaying = isPlaying,
		timeLength = V59.safeRead(instance, "TimeLength", nil),
		rollOffMinDistance = V59.safeRead(instance, "RollOffMinDistance", nil),
		rollOffMaxDistance = V59.safeRead(instance, "RollOffMaxDistance", nil),
		playbackLoudness = playbackLoudness,
		loudnessBand = V59.loudnessBand(playbackLoudness),
		soundGroup = soundGroup and {
			name = soundGroup.Name,
			path = safeFullName(soundGroup),
			volume = V59.safeRead(soundGroup, "Volume", nil),
		} or nil,
	}
end

function V59.groupSummary(instance)
	return {
		id = getInstanceId(instance),
		name = instance.Name,
		className = instance.ClassName,
		path = safeFullName(instance),
		volume = V59.safeRead(instance, "Volume", nil),
	}
end

function V59.analyzerSummary(instance)
	local peak = V59.safeRead(instance, "PeakLevel", nil)
	local rms = V59.safeRead(instance, "RmsLevel", nil)
	local spectrum = nil
	local okSpectrum, spectrumValue = pcall(function()
		if instance.GetSpectrum then return instance:GetSpectrum() end
		return nil
	end)
	if okSpectrum and type(spectrumValue) == "table" then
		spectrum = {}
		for index = 1, math.min(16, #spectrumValue) do
			table.insert(spectrum, spectrumValue[index])
		end
	end
	return {
		id = getInstanceId(instance),
		name = instance.Name,
		className = instance.ClassName,
		path = safeFullName(instance),
		peakLevel = peak,
		rmsLevel = rms,
		spectrum = spectrum,
	}
end

function V59.scan(payload)
	payload = payload or {}
	local maxNodes = math.max(50, math.min(tonumber(payload.maxNodes) or 6000, 20000))
	local visited = 0
	local sounds = {}
	local groups = {}
	local analyzers = {}
	local audioPlayers = {}
	local classCounts = {}
	local soundIds = {}
	local duplicatesById = {}
	local truncated = false
	local function visit(instance)
		if not instance or visited >= maxNodes then
			truncated = true
			return
		end
		visited += 1
		if V59.isAudioInstance(instance) then
			classCounts[instance.ClassName] = (classCounts[instance.ClassName] or 0) + 1
			if instance:IsA("Sound") then
				local summary = V59.soundSummary(instance)
				table.insert(sounds, summary)
				if summary.soundId then
					soundIds[summary.soundId] = true
					duplicatesById[summary.soundId] = duplicatesById[summary.soundId] or {}
					table.insert(duplicatesById[summary.soundId], summary.path)
				end
			elseif instance:IsA("SoundGroup") then
				table.insert(groups, V59.groupSummary(instance))
			elseif instance.ClassName == "AudioAnalyzer" then
				table.insert(analyzers, V59.analyzerSummary(instance))
			elseif instance.ClassName == "AudioPlayer" then
				table.insert(audioPlayers, {
					id = getInstanceId(instance),
					name = instance.Name,
					className = instance.ClassName,
					path = safeFullName(instance),
					assetId = V39.assetId(V59.safeRead(instance, "AssetId", "")),
					volume = V59.safeRead(instance, "Volume", nil),
				})
			end
		end
		for _, child in ipairs(instance:GetChildren()) do
			if visited >= maxNodes then
				truncated = true
				return
			end
			visit(child)
		end
	end
	for _, root in ipairs(V59.audioRoots(payload)) do
		if root then visit(root) end
	end
	local assetList = {}
	for assetId in pairs(soundIds) do table.insert(assetList, assetId) end
	table.sort(assetList)
	local duplicateAssets = {}
	for assetId, paths in pairs(duplicatesById) do
		if #paths > 1 then table.insert(duplicateAssets, { soundId = assetId, count = #paths, paths = paths }) end
	end
	table.sort(duplicateAssets, function(a, b) return a.count > b.count end)
	return {
		visited = visited,
		truncated = truncated,
		sounds = sounds,
		soundGroups = groups,
		audioAnalyzers = analyzers,
		audioPlayers = audioPlayers,
		classCounts = classCounts,
		soundAssetIds = assetList,
		duplicateAssets = duplicateAssets,
	}
end

function V59.getAudioInventory(payload)
	local scan = V59.scan(payload or {})
	local result = {
		at = isoNow(),
		version = VERSION,
		path = payload and (payload.path or payload.root or payload.target) or "allAudioRoots",
		sounds = scan.sounds,
		soundGroups = scan.soundGroups,
		audioAnalyzers = scan.audioAnalyzers,
		audioPlayers = scan.audioPlayers,
		classCounts = scan.classCounts,
		counts = {
			sounds = #scan.sounds,
			soundGroups = #scan.soundGroups,
			audioAnalyzers = #scan.audioAnalyzers,
			audioPlayers = #scan.audioPlayers,
		},
		truncated = scan.truncated,
		visited = scan.visited,
	}
	V59.last.inventory = result
	return result
end

function V59.getAudioAssetCatalog(payload)
	local scan = V59.scan(payload or {})
	local byRole = {}
	for _, sound in ipairs(scan.sounds) do
		local role = sound.role or "unknown"
		byRole[role] = byRole[role] or {}
		table.insert(byRole[role], {
			path = sound.path,
			name = sound.name,
			soundId = sound.soundId,
			volume = sound.volume,
			looped = sound.looped,
			recommendedGroup = sound.recommendedGroup,
		})
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		assetIds = scan.soundAssetIds,
		byRole = byRole,
		duplicateAssets = scan.duplicateAssets,
		count = #scan.soundAssetIds,
	}
	V59.last.catalog = result
	return result
end

