function V59.profileFromIntent(intent)
	local text = V59.lower(intent)
	if text:find("mobile", 1, true) then return "mobile-safe" end
	if text:find("cinematic", 1, true) or text:find("movie", 1, true) then return "cinematic" end
	if text:find("loud", 1, true) or text:find("impact", 1, true) or text:find("punch", 1, true) then return "loud-impact" end
	if text:find("quiet", 1, true) or text:find("soft", 1, true) or text:find("ambience", 1, true) then return "quiet-ambience" end
	if text:find("horror", 1, true) or text:find("scary", 1, true) then return "horror-tension" end
	if text:find("anime", 1, true) or text:find("combat", 1, true) then return "anime-combat" end
	if text:find("ui", 1, true) or text:find("menu", 1, true) then return "ui-clean" end
	return "balanced"
end

function V59.getAudioMixProfileCatalog(payload)
	local profiles = {}
	for id, profile in pairs(V59.mixProfiles()) do
		table.insert(profiles, {
			id = id,
			label = profile.label,
			groupVolumes = profile.groupVolumes,
			roleVolumes = profile.roleVolumes,
			example = "tools\\bridge.cmd audio mix " .. id,
		})
	end
	table.sort(profiles, function(a, b) return a.id < b.id end)
	return {
		at = isoNow(),
		version = VERSION,
		defaultProfile = "balanced",
		profiles = profiles,
	}
end

function V59.getAudioLoudnessReport(payload)
	local inventory = V59.getAudioInventory(payload or {})
	local active = {}
	local bands = {}
	for _, sound in ipairs(inventory.sounds or {}) do
		bands[sound.loudnessBand] = (bands[sound.loudnessBand] or 0) + 1
		if sound.isPlaying or (tonumber(sound.playbackLoudness) or 0) > 0 then
			table.insert(active, sound)
		end
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		mode = RunService:IsRunning() and "playOrSimulation" or "edit",
		activeSoundCount = #active,
		activeSounds = active,
		bands = bands,
		audioAnalyzers = inventory.audioAnalyzers,
		message = #active > 0 and "Live sound loudness sampled from PlaybackLoudness." or "No currently playing sounds reported nonzero loudness; run in Play mode and trigger sounds for live mix evidence.",
	}
	V59.last.loudness = result
	return result
end

function V59.getAudioLiveMonitorStatus(payload)
	local loudness = V59.getAudioLoudnessReport(payload or {})
	return {
		at = isoNow(),
		version = VERSION,
		status = #loudness.activeSounds > 0 and "active" or "waitingForPlayback",
		playMode = RunService:IsRunning(),
		loudness = loudness,
		harness = {
			replicatedStorage = resolvePath("ReplicatedStorage.CodexAudioDirector") ~= nil,
			starterPlayerClient = resolvePath("StarterPlayer.StarterPlayerScripts.CodexAudioDirectorClient") ~= nil,
			soundServiceMetadata = resolvePath("SoundService.CodexAudioDirector") ~= nil,
		},
		nextCommand = "tools\\bridge.cmd audio live",
	}
end

function V59.getAudioQualityAudit(payload)
	local inventory = V59.getAudioInventory(payload or {})
	local score = 100
	local warnings = {}
	local blockers = {}
	local seenNames = {}
	local grouped = 0
	for _, group in ipairs(inventory.soundGroups or {}) do
		seenNames[group.name] = true
	end
	for _, sound in ipairs(inventory.sounds or {}) do
		if not sound.soundGroup then
			table.insert(warnings, "Sound has no SoundGroup: " .. tostring(sound.path))
			score -= 2
		else
			grouped += 1
		end
		local volume = tonumber(sound.volume) or 0
		if volume > 1.25 then
			table.insert(warnings, "Very high Volume " .. tostring(volume) .. ": " .. tostring(sound.path))
			score -= 8
		elseif volume <= 0 and not sound.looped then
			table.insert(warnings, "Non-looping sound is muted: " .. tostring(sound.path))
			score -= 3
		end
		if sound.looped and volume > 0.8 and (sound.role == "music" or sound.role == "ambience") then
			table.insert(warnings, "Looping background sound may dominate the mix: " .. tostring(sound.path))
			score -= 5
		end
		if sound.role ~= "ui" and sound.parentPath and (sound.parentPath:find("StarterGui", 1, true) or sound.parentPath:find("PlayerGui", 1, true)) and volume > 0.8 then
			table.insert(warnings, "GUI sound is loud and may be tiring: " .. tostring(sound.path))
			score -= 4
		end
		local rolloff = tonumber(sound.rollOffMaxDistance) or 0
		if rolloff > 180 and (sound.role == "impact" or sound.role == "combat" or sound.role == "ability") then
			table.insert(warnings, "3D action sound has very large rolloff distance: " .. tostring(sound.path))
			score -= 4
		end
	end
	for _, required in ipairs({ "Music", "SFX", "UI", "Ambience", "Combat", "Abilities", "Voice" }) do
		if not seenNames[required] then
			table.insert(warnings, "Missing SoundGroup: " .. required)
			score -= 3
		end
	end
	for _, duplicate in ipairs((V59.scan(payload or {}).duplicateAssets) or {}) do
		if duplicate.count >= 4 then
			table.insert(warnings, "Repeated sound asset may spam: " .. tostring(duplicate.soundId) .. " used " .. tostring(duplicate.count) .. " times.")
			score -= 4
		end
	end
	if #inventory.sounds == 0 then
		table.insert(blockers, "No Sound objects found in scanned audio roots.")
		score = math.min(score, 50)
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		score = math.max(0, math.min(100, math.floor(score + 0.5))),
		status = #blockers > 0 and "blocked" or (#warnings > 0 and "needsMixPass" or "healthy"),
		warnings = warnings,
		blockers = blockers,
		groupedSoundCount = grouped,
		totalSoundCount = #inventory.sounds,
		inventorySummary = inventory.counts,
		nextCommand = "tools\\bridge.cmd audio plan balanced",
	}
	V59.last.audit = result
	return result
end

function V59.getAudioMixPlan(payload)
	payload = payload or {}
	local intent = tostring(payload.intent or payload.profile or payload.mode or payload.text or "balanced")
	local profileId = V59.mixProfiles()[intent] and intent or V59.profileFromIntent(intent)
	local profile = V59.mixProfiles()[profileId] or V59.mixProfiles().balanced
	local inventory = V59.getAudioInventory(payload)
	local actions = {}
	local groupActions = {}
	for groupName, volume in pairs(profile.groupVolumes or {}) do
		table.insert(groupActions, {
			type = "ensureSoundGroup",
			path = "SoundService." .. groupName,
			name = groupName,
			volume = volume,
		})
	end
	for _, sound in ipairs(inventory.sounds or {}) do
		local role = sound.role or "unknown"
		local targetVolume = (profile.roleVolumes and profile.roleVolumes[role]) or profile.roleVolumes.unknown or 0.55
		local targetGroup = V59.groupForRole(role)
		local needsVolume = math.abs((tonumber(sound.volume) or 0) - targetVolume) > 0.025
		local needsGroup = not sound.soundGroup or sound.soundGroup.name ~= targetGroup
		if needsVolume or needsGroup then
			table.insert(actions, {
				type = "setSoundMix",
				path = sound.path,
				role = role,
				soundId = sound.soundId,
				current = {
					volume = sound.volume,
					soundGroup = sound.soundGroup and sound.soundGroup.path or nil,
				},
				target = {
					volume = targetVolume,
					soundGroup = "SoundService." .. targetGroup,
				},
				reason = "Match " .. tostring(profileId) .. " mix profile for " .. tostring(role) .. " sound.",
			})
		end
	end
	local result = {
		at = isoNow(),
		version = VERSION,
		profileId = profileId,
		profile = profile,
		intent = intent,
		groupActions = groupActions,
		actions = actions,
		actionCount = #actions,
		message = #actions == 0 and "Audio already matches the selected mix profile closely." or "Audio mix plan prepared.",
	}
	V59.last.mixPlan = result
	return result
end

function V59.groupBlueprint(profileId)
	local profile = V59.mixProfiles()[profileId or "balanced"] or V59.mixProfiles().balanced
	local steps = {
		{ type = "ensureFolder", path = "ReplicatedStorage.CodexAudioDirector" },
		{ type = "ensureFolder", path = "SoundService.CodexAudioDirector" },
	}
	for groupName, volume in pairs(profile.groupVolumes or {}) do
		table.insert(steps, { type = "ensureInstance", className = "SoundGroup", path = "SoundService." .. groupName, properties = { Volume = volume } })
		table.insert(steps, { type = "setProperties", path = "SoundService." .. groupName, properties = { Volume = volume } })
	end
	return {
		name = "Codex Audio SoundGroups",
		mode = "fullTrust",
		source = "V59.applyAudioSoundGroups",
		steps = steps,
	}
end

function V59.applyAudioSoundGroups(payload)
	payload = payload or {}
	local profileId = V59.mixProfiles()[payload.profile or payload.mode or payload.intent] and (payload.profile or payload.mode or payload.intent) or V59.profileFromIntent(payload.intent or payload.profile or payload.mode or "balanced")
	local result = applyBuildPlan({ blueprint = V59.groupBlueprint(profileId) })
	result.kind = "audioSoundGroups"
	result.profileId = profileId
	V59.last.soundGroups = result
	return result
end

function V59.applyAudioMixPlan(payload)
	payload = payload or {}
	local plan = payload.plan or V59.getAudioMixPlan(payload)
	V59.applyAudioSoundGroups({ profile = plan.profileId })
	return withUndo("ApplyAudioMixPlan", function()
		local result = {
			at = isoNow(),
			version = VERSION,
			profileId = plan.profileId,
			updated = {},
			skipped = {},
			failed = {},
			backups = {},
		}
		for _, action in ipairs(plan.actions or {}) do
			local sound = resolvePath(action.path)
			if not sound or not sound:IsA("Sound") then
				table.insert(result.failed, { path = action.path, reason = "Sound target not found." })
			else
				local backup = V59.soundSummary(sound)
				table.insert(result.backups, backup)
				local ok, err = pcall(function()
					if action.target and action.target.volume ~= nil then
						sound.Volume = tonumber(action.target.volume) or sound.Volume
					end
					if action.target and action.target.soundGroup then
						local group = resolvePath(action.target.soundGroup)
						if group and group:IsA("SoundGroup") then
							sound.SoundGroup = group
						end
					end
				end)
				if ok then
					table.insert(result.updated, { path = action.path, role = action.role, target = action.target })
				else
					table.insert(result.failed, { path = action.path, reason = tostring(err) })
				end
			end
		end
		result.summary = { updated = #result.updated, skipped = #result.skipped, failed = #result.failed, backups = #result.backups }
		stateDirty = true
		V59.last.appliedMix = result
		return result
	end)
end

function V59.installAudioDirectorHarness(payload)
	local manifest = {
		name = "CodexAudioDirector",
		version = VERSION,
		purpose = "Audio inventory, mix QA, live loudness metadata, and package sync.",
		defaultProfile = "balanced",
	}
	local source = V54.manifestSource(manifest)
	local clientSource = "script:SetAttribute(\"CodexAudioDirectorVersion\", \"" .. VERSION .. "\")\nscript:SetAttribute(\"Purpose\", \"Metadata marker for StudioBridge audio live checks; no hidden execution.\")\n"
	local blueprint = {
		name = "Codex Audio Director Harness",
		mode = "fullTrust",
		source = "V59.installAudioDirectorHarness",
		steps = {
			{ type = "ensureFolder", path = "ReplicatedStorage.CodexAudioDirector" },
			{ type = "ensureFolder", path = "SoundService.CodexAudioDirector" },
			{ type = "writeScript", path = "ReplicatedStorage.CodexAudioDirector.Manifest", className = "ModuleScript", source = source, overwrite = true },
			{ type = "writeScript", path = "StarterPlayer.StarterPlayerScripts.CodexAudioDirectorClient", className = "LocalScript", source = clientSource, overwrite = true },
		},
	}
	local result = applyBuildPlan({ blueprint = blueprint })
	result.kind = "audioDirectorHarness"
	V59.last.harness = result
	return result
end

function V59.removeAudioDirectorHarness(payload)
	return withUndo("RemoveAudioDirectorHarness", function()
		local result = { at = isoNow(), version = VERSION, removed = {}, missing = {}, failed = {} }
		for _, path in ipairs({ "ReplicatedStorage.CodexAudioDirector", "SoundService.CodexAudioDirector", "StarterPlayer.StarterPlayerScripts.CodexAudioDirectorClient" }) do
			local target = resolvePath(path)
			if target then
				local ok, err = pcall(function() target:Destroy() end)
				if ok then table.insert(result.removed, path) else table.insert(result.failed, { path = path, error = tostring(err) }) end
			else
				table.insert(result.missing, path)
			end
		end
		stateDirty = true
		V59.last.removedHarness = result
		return result
	end)
end

function V59.attachAudioCue(payload)
	payload = payload or {}
	local targetPath = tostring(payload.targetPath or payload.target or "")
	local target = resolvePath(targetPath)
	if not target then error("attachAudioCue target not found: " .. targetPath) end
	local sourcePath = payload.soundPath or payload.path
	local soundId = payload.soundId or payload.assetId or payload.id
	local name = V39.safeName(payload.name or payload.label or "CodexAudioCue", "CodexAudioCue")
	return withUndo("AttachAudioCue", function()
		local sound
		local source = sourcePath and resolvePath(sourcePath)
		if source and source:IsA("Sound") then
			sound = source:Clone()
			sound.Name = name
		else
			sound = Instance.new("Sound")
			sound.Name = name
			if soundId then sound.SoundId = V39.assetId(soundId) or tostring(soundId) end
		end
		sound.Volume = tonumber(payload.volume) or sound.Volume or 0.65
		sound.Parent = target
		stateDirty = true
		local result = {
			at = isoNow(),
			version = VERSION,
			status = "attached",
			targetPath = safeFullName(target),
			sound = V59.soundSummary(sound),
		}
		V59.last.attached = result
		return result
	end)
end

function V59.getAudioSyncPlan(payload)
	payload = payload or {}
	local targetPath = tostring(payload.path or payload.packagePath or payload.animationPath or payload.vfxPath or "")
	local target = targetPath ~= "" and resolvePath(targetPath) or nil
	local role = V59.profileFromIntent(payload.intent or targetPath)
	local markers = { "ChargeStart", "MuzzleFlash", "Fire", "Impact", "SoundCue", "Recovery" }
	local result = {
		at = isoNow(),
		version = VERSION,
		targetPath = targetPath ~= "" and targetPath or nil,
		targetExists = target ~= nil,
		profileId = role,
		soundCues = {
			{ marker = "ChargeStart", role = "charge swell", volumeIntent = "low-to-balanced" },
			{ marker = "MuzzleFlash", role = "short transient", volumeIntent = "balanced" },
			{ marker = "Fire", role = "release sound", volumeIntent = role == "loud-impact" and "loud" or "balanced" },
			{ marker = "Impact", role = "impact hit", volumeIntent = "loud" },
			{ marker = "Recovery", role = "tail/residue", volumeIntent = "low" },
		},
		requiredMarkers = markers,
		nextCommand = "tools\\bridge.cmd audio sync <package-or-animation-or-vfx-path>",
	}
	V59.last.syncPlan = result
	return result
end

function V59.syncAudioToPackage(payload)
	payload = payload or {}
	local plan = payload.plan or V59.getAudioSyncPlan(payload)
	local targetPath = tostring(payload.packagePath or payload.path or "")
	local target = targetPath ~= "" and resolvePath(targetPath) or nil
	local manifestPath
	if target then
		manifestPath = safeFullName(target) .. ".AudioSyncManifest"
	else
		local name = V39.safeName(payload.name or payload.intent or "AudioSyncManifest", "AudioSyncManifest")
		manifestPath = "ReplicatedStorage.CodexAudioDirector.SyncManifests." .. name
	end
	local blueprint = {
		name = "Codex Audio Sync Manifest",
		mode = "fullTrust",
		source = "V59.syncAudioToPackage",
		steps = {
			{ type = "ensureFolder", path = "ReplicatedStorage.CodexAudioDirector" },
			{ type = "ensureFolder", path = "ReplicatedStorage.CodexAudioDirector.SyncManifests" },
			{ type = "writeScript", path = manifestPath, className = "ModuleScript", source = V54.manifestSource(plan), overwrite = true },
		},
	}
	local result = applyBuildPlan({ blueprint = blueprint })
	result.kind = "audioSyncManifest"
	result.syncPlan = plan
	V59.last.synced = result
	return result
end

function V59.applyAudioCleanup(payload)
	payload = payload or {}
	return withUndo("ApplyAudioCleanup", function()
		local result = { at = isoNow(), version = VERSION, removed = {}, skipped = {} }
		local runtime = resolvePath("SoundService.CodexAudioDirector.Runtime")
		if runtime then
			runtime:Destroy()
			table.insert(result.removed, "SoundService.CodexAudioDirector.Runtime")
		else
			table.insert(result.skipped, "SoundService.CodexAudioDirector.Runtime")
		end
		stateDirty = true
		V59.last.cleanup = result
		return result
	end)
end

