-- V60 Universal Build Director + Procedural Model Workbench
function V60.lower(value)
	return string.lower(tostring(value or ""))
end

function V60.safeName(value, fallback)
	local text = tostring(value or fallback or "Build")
	text = string.gsub(text, "[^%w]+", "_")
	text = string.gsub(text, "^_+", "")
	text = string.gsub(text, "_+$", "")
	if text == "" then text = tostring(fallback or "Build") end
	if #text > 42 then text = string.sub(text, 1, 42) end
	return text
end

function V60.has(text, ...)
	local lower = V60.lower(text)
	for _, word in ipairs({ ... }) do
		if string.find(lower, tostring(word), 1, true) then
			return true
		end
	end
	return false
end

function V60.v3(x, y, z)
	return { __type = "Vector3", x = x, y = y, z = z }
end

function V60.rgb(r, g, b)
	return { __type = "Color3", mode = "rgb", r = r, g = g, b = b }
end

function V60.paletteForIntent(intent)
	if V60.has(intent, "cyber", "sci-fi", "scifi", "tech", "neon") then
		return { id = "neonTech", materials = { "Metal", "SmoothPlastic", "Neon", "Glass" }, primary = V60.rgb(35, 42, 56), secondary = V60.rgb(72, 86, 110), accent = V60.rgb(0, 210, 255), warning = V60.rgb(255, 190, 60) }
	end
	if V60.has(intent, "anime", "magic", "portal", "rift", "aura", "purple") then
		return { id = "animeMystic", materials = { "SmoothPlastic", "Neon", "Glass", "ForceField" }, primary = V60.rgb(42, 32, 66), secondary = V60.rgb(84, 60, 124), accent = V60.rgb(172, 80, 255), warning = V60.rgb(255, 230, 120) }
	end
	if V60.has(intent, "wood", "village", "shop", "market", "cozy") then
		return { id = "warmMarket", materials = { "Wood", "WoodPlanks", "SmoothPlastic", "Fabric" }, primary = V60.rgb(128, 84, 48), secondary = V60.rgb(194, 142, 74), accent = V60.rgb(255, 216, 120), warning = V60.rgb(90, 64, 42) }
	end
	if V60.has(intent, "horror", "dark", "abandoned", "cave") then
		return { id = "darkTension", materials = { "Slate", "Concrete", "Metal", "Neon" }, primary = V60.rgb(28, 30, 34), secondary = V60.rgb(58, 62, 66), accent = V60.rgb(170, 40, 55), warning = V60.rgb(235, 210, 120) }
	end
	return { id = "cleanUniversal", materials = { "SmoothPlastic", "Metal", "Neon", "Glass" }, primary = V60.rgb(74, 88, 104), secondary = V60.rgb(132, 148, 166), accent = V60.rgb(55, 190, 255), warning = V60.rgb(255, 205, 92) }
end

