	return {
		modelArchetypes = {
			{ id = "crate", purpose = "small readable prop", parts = { "base volume", "beveled trims", "vents", "corner caps", "warning decal slots" } },
			{ id = "portal", purpose = "teleport/readability landmark", parts = { "base plinth", "side pylons", "inner ring", "neon core", "vfx sockets" } },
			{ id = "shopStand", purpose = "purchase/interaction point", parts = { "counter", "sign plate", "display pad", "accent trim", "prompt socket" } },
			{ id = "cover", purpose = "combat/world cover", parts = { "main block", "side braces", "damage panels", "readable silhouette" } },
			{ id = "machine", purpose = "tycoon/simulator device", parts = { "base", "core tank", "pipes", "gauges", "output socket" } },
			{ id = "weaponStand", purpose = "weapon/ability showcase", parts = { "pedestal", "backplate", "weapon socket", "spotlight", "nameplate" } },
		},
		sceneArchetypes = {
			{ id = "lobby", flow = { "spawn", "landmark", "shop", "portal", "social/readability" } },
			{ id = "arena", flow = { "spawn", "cover", "lanes", "objective", "spectacle focal point" } },
			{ id = "obbyStage", flow = { "start", "hazard", "checkpoint", "reward", "next route" } },
			{ id = "tycoonPlot", flow = { "claim", "dropper", "upgrade", "collector", "prestige/flex" } },
			{ id = "bossRoom", flow = { "entrance", "boss focus", "danger ring", "reward exit", "cinematic framing" } },
		},
		detailLayers = { "blockout", "structure", "trim", "microDetail", "signage", "lighting", "vfxSockets", "gameplayMetadata", "optimization" },
		performanceBudgets = {
			prop = { maxParts = 70, maxNeon = 10, maxTransparent = 10, note = "Small prop should stay readable and cheap." },
			scene = { maxParts = 280, maxNeon = 35, maxTransparent = 35, note = "Scene blockouts should favor repeated modules and wide readable forms." },
		},
		proceduralMeshSupport = { status = "featureDetectedAtRuntimeOnly", note = "V60 prefers reliable primitives; EditableMesh/AI mesh routes are exposed as readiness/planning until safely callable." },
	}
