function V60.inferIntent(intent)
	local archetype = "prop"
	if V60.has(intent, "portal", "gate", "rift") then archetype = "portal" end
	if V60.has(intent, "shop", "stand", "vendor") then archetype = "shopStand" end
	if V60.has(intent, "crate", "box", "container") then archetype = "crate" end
	if V60.has(intent, "arena", "combat", "battle") then archetype = "arena" end
	if V60.has(intent, "lobby", "hub", "spawn") then archetype = "lobby" end
	if V60.has(intent, "obby", "checkpoint", "platform") then archetype = "obbyStage" end
	if V60.has(intent, "tycoon", "dropper", "machine") then archetype = "machine" end
	local scene = archetype == "arena" or archetype == "lobby" or archetype == "obbyStage" or V60.has(intent, "scene", "map", "room", "world")
	local style = "cleanUniversal"
	if V60.has(intent, "anime", "magic", "rift", "purple") then style = "animeMystic" end
	if V60.has(intent, "sci", "cyber", "tech", "neon") then style = "neonTech" end
	if V60.has(intent, "wood", "cozy", "market") then style = "warmMarket" end
	if V60.has(intent, "horror", "dark") then style = "darkTension" end
	return {
		intent = intent,
		archetype = archetype,
		isScene = scene,
		style = style,
		scale = V60.has(intent, "huge", "massive", "boss", "giant") and "large" or (V60.has(intent, "tiny", "small") and "small" or "medium"),
		purpose = scene and "world/level composition" or "model/prop construction",
		gameplayHooks = {
			V60.has(intent, "portal", "teleport", "gate") and "TeleportSocket" or nil,
			V60.has(intent, "shop", "buy", "vendor") and "ShopInteractable" or nil,
			V60.has(intent, "checkpoint") and "Checkpoint" or nil,
			V60.has(intent, "vfx", "aura", "magic", "neon") and "VfxSocket" or nil,
		},
	}
end

function V60.getBuildStyleCatalog(payload)
	return { ok = true, at = isoNow(), version = VERSION, catalog = V60.catalog(), materialPalettes = { cleanUniversal = V60.paletteForIntent("clean"), neonTech = V60.paletteForIntent("cyber neon"), animeMystic = V60.paletteForIntent("anime purple magic"), warmMarket = V60.paletteForIntent("warm wood shop"), darkTension = V60.paletteForIntent("dark horror") }, nextCommand = "tools\\bridge.cmd build plan <intent>" }
end

function V60.getBuildIntentPlan(payload)
	payload = payload or {}
	local intent = tostring(payload.intent or payload.text or "clean detailed Roblox model")
	local meta = V60.inferIntent(intent)
	local result = { ok = true, at = isoNow(), version = VERSION, intent = intent, breakdown = meta, palette = V60.paletteForIntent(intent), buildGrammar = { "blockout first with exact pivot-friendly dimensions", "large readable forms before micro detail", "trim strips and corner caps for bevel illusion", "accent glow only where it improves focal hierarchy", "Codex sockets for VFX, prompts, camera, and gameplay hooks", "manifest notes so scripts/test tools know what was built" }, recommendedCommand = meta.isScene and ("tools\\bridge.cmd generate_scene \"" .. intent .. "\"") or ("tools\\bridge.cmd generate_model \"" .. intent .. "\""), nextCommand = meta.isScene and "tools\\bridge.cmd build scene <intent>" or "tools\\bridge.cmd build generate <intent>" }
	V60.last.intentPlan = result
	return result
end

function V60.getBuildMaterialPalette(payload)
	payload = payload or {}
	local intent = payload.intent or payload.style or "clean"
	local palette = V60.paletteForIntent(intent)
	return { ok = true, at = isoNow(), version = VERSION, intent = intent, palette = palette, usage = { primary = "large structural forms", secondary = "side panels and braces", accent = "focal edge and interaction socket", warning = "small callouts and pad affordances" }, nextCommand = "tools\\bridge.cmd build generate <intent>" }
end

function V60.scanKitRoot(root)
	local report = { root = root and safeFullName(root) or nil, models = {}, meshParts = {}, parts = {}, textures = {}, decals = {}, sounds = {}, materials = {}, scanned = 0, truncated = false }
	if not root then return report end
	local materialSeen = {}
	local function rememberMaterial(instance)
		if instance:IsA("BasePart") then
			local material = tostring(instance.Material):gsub("^Enum.Material.", "")
			if not materialSeen[material] then
				materialSeen[material] = true
				table.insert(report.materials, material)
			end
		end
	end
	local function visit(instance)
		if report.scanned >= 1800 then report.truncated = true return end
		report.scanned += 1
		if instance:IsA("Model") and #report.models < 80 then
			table.insert(report.models, { path = safeFullName(instance), name = instance.Name, descendantCount = #instance:GetDescendants() })
		elseif instance:IsA("MeshPart") and #report.meshParts < 80 then
			table.insert(report.meshParts, { path = safeFullName(instance), name = instance.Name, meshId = V39.assetId(instance.MeshId) })
		elseif instance:IsA("BasePart") and #report.parts < 120 then
			rememberMaterial(instance)
			table.insert(report.parts, { path = safeFullName(instance), name = instance.Name, className = instance.ClassName, material = tostring(instance.Material):gsub("^Enum.Material.", ""), size = serializeValue(instance.Size) })
		elseif instance:IsA("Texture") and #report.textures < 100 then
			table.insert(report.textures, { path = safeFullName(instance), assetId = V39.assetId(instance.Texture) })
		elseif instance:IsA("Decal") and #report.decals < 100 then
			table.insert(report.decals, { path = safeFullName(instance), assetId = V39.assetId(instance.Texture) })
		elseif instance:IsA("Sound") and #report.sounds < 80 then
			table.insert(report.sounds, { path = safeFullName(instance), assetId = V39.assetId(instance.SoundId) })
		end
		for _, child in ipairs(instance:GetChildren()) do
			visit(child)
			if report.truncated then return end
		end
	end
	visit(root)
	return report
end

function V60.getBuildAssetKitReport(payload)
	payload = payload or {}
	local target = resolvePath(payload.path or payload.root or "Workspace")
	local report = V60.scanKitRoot(target)
	return { ok = target ~= nil, at = isoNow(), version = VERSION, path = payload.path or payload.root or "Workspace", report = report, recommendations = { #report.meshParts > 0 and "Use scanned MeshParts as visual references or explicit clone candidates." or nil, #report.textures + #report.decals > 0 and "Texture/decal IDs can guide signage and trim without uploading new assets." or nil, #report.models > 0 and "Existing models can inform scale, silhouette, and kit style before generating Codex-owned builds." or nil }, nextCommand = "tools\\bridge.cmd build plan <intent>" }
end

function V60.versionedPath(rootPath, baseName)
	local index = 1
	while index < 999 do
		local path = rootPath .. "." .. baseName .. "_v" .. string.format("%03d", index)
		if not resolvePath(path) then return path, index end
		index += 1
	end
	return rootPath .. "." .. baseName .. "_" .. tostring(os.time()), 0
end

function V60.manifestSource(manifest)
	return "return { format = \"codex-build-director-v1\", version = " .. V8.luaString(VERSION) .. ", json = " .. V8.luaString(HttpService:JSONEncode(manifest)) .. " }\n"
end

function V60.part(path, size, position, color, material, extra)
	local properties = { Anchored = true, CanCollide = extra and extra.canCollide ~= nil and extra.canCollide or true, CanQuery = true, CanTouch = false, Size = V60.v3(size[1], size[2], size[3]), Position = V60.v3(position[1], position[2], position[3]), Color = color, Material = material or "SmoothPlastic" }
	if extra then
		for key, value in pairs(extra) do
			if key ~= "canCollide" then properties[key] = value end
		end
	end
	return { type = "createPart", path = path, properties = properties, overwrite = false }
end

function V60.modelBlueprint(intent, forcedScene)
	local meta = V60.inferIntent(intent)
	meta.isScene = forcedScene == true or meta.isScene
	local palette = V60.paletteForIntent(intent)
	local safe = V60.safeName(meta.archetype .. "_" .. intent, "Build")
	local root = meta.isScene and "Workspace.CodexBuildDirector.Scenes" or "Workspace.CodexBuildDirector.Generated"
	local basePath, versionIndex = V60.versionedPath(root, safe)
	local manifestPath = "ReplicatedStorage.CodexBuildDirector.Manifests." .. V60.safeName(safe .. "_v" .. tostring(versionIndex), "BuildManifest")
	local steps = { { type = "ensureFolder", path = "Workspace.CodexBuildDirector" }, { type = "ensureFolder", path = "Workspace.CodexBuildDirector.Generated" }, { type = "ensureFolder", path = "Workspace.CodexBuildDirector.Scenes" }, { type = "ensureFolder", path = "ReplicatedStorage.CodexBuildDirector" }, { type = "ensureFolder", path = "ReplicatedStorage.CodexBuildDirector.Manifests" }, { type = "createModel", path = basePath }, { type = "createInstance", className = "Folder", path = basePath .. ".Details" }, { type = "createInstance", className = "Folder", path = basePath .. ".Sockets" } }
	if meta.isScene then
		table.insert(steps, V60.part(basePath .. ".Foundation", { 72, 1, 72 }, { 0, 0, 0 }, palette.primary, "SmoothPlastic"))
		table.insert(steps, V60.part(basePath .. ".MainPath", { 12, 0.35, 60 }, { 0, 0.8, 0 }, palette.secondary, "SmoothPlastic"))
		table.insert(steps, V60.part(basePath .. ".FocalPlatform", { 20, 1.2, 20 }, { 0, 1.4, -22 }, palette.secondary, "Metal"))
		table.insert(steps, V60.part(basePath .. ".SpawnPad", { 14, 0.45, 10 }, { 0, 1.2, 26 }, palette.accent, "Neon", { Transparency = 0.08 }))
		table.insert(steps, V60.part(basePath .. ".LeftLandmarkPylon", { 3, 18, 3 }, { -18, 10, -22 }, palette.primary, "Metal"))
		table.insert(steps, V60.part(basePath .. ".RightLandmarkPylon", { 3, 18, 3 }, { 18, 10, -22 }, palette.primary, "Metal"))
		table.insert(steps, V60.part(basePath .. ".PortalCore", { 20, 16, 1 }, { 0, 10, -24 }, palette.accent, "Neon", { CanCollide = false, Transparency = 0.25 }))
		table.insert(steps, V60.part(basePath .. ".ShopStandLeft", { 10, 5, 7 }, { -24, 3.5, 8 }, palette.primary, "Wood"))
		table.insert(steps, V60.part(basePath .. ".ShopStandRight", { 10, 5, 7 }, { 24, 3.5, 8 }, palette.primary, "Wood"))
		for i = 1, 6 do
			local z = -16 + (i * 6)
			table.insert(steps, V60.part(basePath .. ".Details.PathTrim" .. tostring(i) .. "L", { 1, 0.4, 4 }, { -7, 1.35, z }, palette.accent, "Neon", { CanCollide = false }))
			table.insert(steps, V60.part(basePath .. ".Details.PathTrim" .. tostring(i) .. "R", { 1, 0.4, 4 }, { 7, 1.35, z }, palette.accent, "Neon", { CanCollide = false }))
		end
		table.insert(steps, V60.part(basePath .. ".Sockets.CameraFocus", { 1, 1, 1 }, { 0, 8, -10 }, palette.warning, "Neon", { Transparency = 0.6, CanCollide = false }))
		table.insert(steps, V60.part(basePath .. ".Sockets.VfxSocket", { 1, 1, 1 }, { 0, 9, -23 }, palette.accent, "Neon", { Transparency = 0.35, CanCollide = false }))
	else
		local height = meta.scale == "large" and 10 or (meta.scale == "small" and 4 or 6)
		local width = meta.scale == "large" and 12 or (meta.scale == "small" and 5 or 8)
		local y = 5
		table.insert(steps, V60.part(basePath .. ".Core", { width, height, width }, { 0, y, 0 }, palette.primary, palette.materials[1] or "SmoothPlastic"))
		table.insert(steps, V60.part(basePath .. ".TopCap", { width + 1.2, 0.7, width + 1.2 }, { 0, y + (height / 2) + 0.5, 0 }, palette.secondary, "Metal"))
		table.insert(steps, V60.part(basePath .. ".BaseCap", { width + 1.6, 0.8, width + 1.6 }, { 0, y - (height / 2) - 0.5, 0 }, palette.secondary, "Metal"))
		table.insert(steps, V60.part(basePath .. ".FrontPanel", { width - 1.2, height * 0.45, 0.25 }, { 0, y, -(width / 2) - 0.16 }, palette.secondary, "SmoothPlastic", { CanCollide = false }))
		table.insert(steps, V60.part(basePath .. ".AccentCore", { width * 0.28, height * 0.5, 0.35 }, { 0, y, -(width / 2) - 0.35 }, palette.accent, "Neon", { CanCollide = false, Transparency = 0.05 }))
		for i = 1, 4 do
			local sx = (i <= 2) and -1 or 1
			local sz = (i == 1 or i == 3) and -1 or 1
			table.insert(steps, V60.part(basePath .. ".Details.CornerCap" .. tostring(i), { 0.7, height + 0.8, 0.7 }, { sx * (width / 2 + 0.35), y, sz * (width / 2 + 0.35) }, palette.secondary, "Metal"))
		end
		for i = 1, 3 do
			table.insert(steps, V60.part(basePath .. ".Details.Trim" .. tostring(i), { width + 1.1, 0.25, 0.35 }, { 0, y - height / 2 + (i * height / 4), -(width / 2) - 0.45 }, palette.warning, "Neon", { CanCollide = false }))
		end
		table.insert(steps, V60.part(basePath .. ".Sockets.InteractionSocket", { 1, 1, 1 }, { 0, y + height / 2 + 1.4, 0 }, palette.warning, "Neon", { Transparency = 0.45, CanCollide = false }))
		table.insert(steps, V60.part(basePath .. ".Sockets.VfxSocket", { 1, 1, 1 }, { 0, y, -(width / 2) - 1.2 }, palette.accent, "Neon", { Transparency = 0.35, CanCollide = false }))
	end
	local manifest = { name = safe, version = VERSION, intent = intent, archetype = meta.archetype, isScene = meta.isScene, style = meta.style, scale = meta.scale, path = basePath, palette = palette.id, gameplayHooks = meta.gameplayHooks, performanceBudget = meta.isScene and V60.catalog().performanceBudgets.scene or V60.catalog().performanceBudgets.prop, nextCommands = { "tools\\bridge.cmd build audit " .. basePath, "tools\\bridge.cmd build polish " .. basePath, "tools\\bridge.cmd build optimize " .. basePath } }
	table.insert(steps, { type = "writeScript", className = "ModuleScript", path = manifestPath, source = V60.manifestSource(manifest), overwrite = false })
	return { ok = true, at = isoNow(), version = VERSION, intent = intent, breakdown = meta, buildPath = basePath, manifestPath = manifestPath, manifest = manifest, blueprint = { name = safe, mode = "fullTrustCodexOwnedGeneratedBuild", steps = steps }, stepCount = #steps, nextCommand = meta.isScene and "tools\\bridge.cmd build scene <intent>" or "tools\\bridge.cmd build generate <intent>" }
end

function V60.getProceduralModelPlan(payload)
	payload = payload or {}
	local plan = V60.modelBlueprint(tostring(payload.intent or payload.text or "detailed model"), false)
	plan.proceduralMesh = { status = "primitiveFirst", editableMeshReady = false, reason = "V60 uses reliable Roblox parts unless EditableMesh/AI mesh APIs are explicitly exposed and safe in the current Studio session.", fallback = "Generated primitive construction with clean pivots, sockets, and manifest." }
	V60.last.modelPlan = plan
	return plan
end

function V60.getSceneBuildPlan(payload)
	payload = payload or {}
	local plan = V60.modelBlueprint(tostring(payload.intent or payload.text or "detailed scene"), true)
	V60.last.scenePlan = plan
	return plan
end

function V60.markGenerated(path, manifest)
	local root = resolvePath(path)
	if not root then return end
	pcall(function()
		root:SetAttribute("CodexGenerated", true)
		root:SetAttribute("CodexBuildDirectorVersion", VERSION)
		root:SetAttribute("CodexBuildIntent", tostring(manifest and manifest.intent or ""))
		root:SetAttribute("CodexBuildArchetype", tostring(manifest and manifest.archetype or ""))
	end)
	pcall(function()
		game:GetService("CollectionService"):AddTag(root, "CodexGeneratedBuild")
	end)
end

function V60.applyBuildDirectorPlan(payload)
	payload = payload or {}
	local plan = payload.plan or payload.buildPlan
	if type(plan) ~= "table" or type(plan.blueprint) ~= "table" then
		plan = V60.modelBlueprint(tostring(payload.intent or payload.text or "detailed model"), payload.scene == true)
	end
	local result = applyBuildPlan({ blueprint = plan.blueprint })
	result.kind = "buildDirectorPlan"
	result.plan = { buildPath = plan.buildPath, manifestPath = plan.manifestPath, intent = plan.intent, archetype = plan.breakdown and plan.breakdown.archetype }
	V60.markGenerated(plan.buildPath, plan.manifest)
	V60.last.applied = result
	return result
end

function V60.generateModelFromIntent(payload)
	local plan = V60.modelBlueprint(tostring((payload or {}).intent or (payload or {}).text or "detailed Roblox model"), false)
	local result = V60.applyBuildDirectorPlan({ plan = plan })
	result.generatedPath = plan.buildPath
	result.manifestPath = plan.manifestPath
	result.nextCommand = "tools\\bridge.cmd build audit " .. plan.buildPath
	V60.last.generatedModel = result
	return result
end

function V60.generateSceneFromIntent(payload)
	local plan = V60.modelBlueprint(tostring((payload or {}).intent or (payload or {}).text or "detailed Roblox scene"), true)
	local result = V60.applyBuildDirectorPlan({ plan = plan })
	result.generatedPath = plan.buildPath
	result.manifestPath = plan.manifestPath
	result.nextCommand = "tools\\bridge.cmd build audit " .. plan.buildPath
	V60.last.generatedScene = result
	return result
end

function V60.getBuildQualityAudit(payload)
	payload = payload or {}
	local targetPath = payload.path or payload.modelPath or payload.targetPath
	local target = resolvePath(targetPath)
	if not target then return { ok = false, at = isoNow(), version = VERSION, status = "notFound", path = targetPath, blockers = { "Build target was not found." }, nextCommand = "tools\\bridge.cmd build kit Workspace" } end
	local counts = { parts = 0, meshParts = 0, anchored = 0, unanchored = 0, neon = 0, transparent = 0, scripts = 0, decals = 0, textures = 0, constraints = 0 }
	local materials = {}
	local min = Vector3.new(math.huge, math.huge, math.huge)
	local max = Vector3.new(-math.huge, -math.huge, -math.huge)
	local function includePart(part)
		counts.parts += 1
		if part:IsA("MeshPart") then counts.meshParts += 1 end
		if part.Anchored then counts.anchored += 1 else counts.unanchored += 1 end
		if part.Material == Enum.Material.Neon then counts.neon += 1 end
		if part.Transparency > 0.25 then counts.transparent += 1 end
		local material = tostring(part.Material):gsub("^Enum.Material.", "")
		materials[material] = (materials[material] or 0) + 1
		local half = part.Size / 2
		local p = part.Position
		min = Vector3.new(math.min(min.X, p.X - half.X), math.min(min.Y, p.Y - half.Y), math.min(min.Z, p.Z - half.Z))
		max = Vector3.new(math.max(max.X, p.X + half.X), math.max(max.Y, p.Y + half.Y), math.max(max.Z, p.Z + half.Z))
	end
	if target:IsA("BasePart") then includePart(target) end
	for _, descendant in ipairs(target:GetDescendants()) do
		if descendant:IsA("BasePart") then includePart(descendant)
		elseif descendant:IsA("LuaSourceContainer") then counts.scripts += 1
		elseif descendant:IsA("Decal") then counts.decals += 1
		elseif descendant:IsA("Texture") then counts.textures += 1
		elseif descendant:IsA("Constraint") then counts.constraints += 1 end
	end
	local warnings = {}
	local blockers = {}
	if counts.parts == 0 then table.insert(blockers, "No BaseParts found; this is not yet a physical build.") end
	if counts.unanchored > 0 then table.insert(warnings, tostring(counts.unanchored) .. " parts are unanchored.") end
	if counts.parts > 280 then table.insert(warnings, "High part count; consider mesh consolidation or repeated modules later.") end
	if counts.neon > 35 then table.insert(warnings, "Many neon parts may over-brighten the scene.") end
	if counts.transparent > 45 then table.insert(warnings, "Many transparent parts can increase mobile overdraw.") end
	local bounds = nil
	if counts.parts > 0 then bounds = { min = serializeValue(min), max = serializeValue(max), size = serializeValue(max - min), center = serializeValue((min + max) / 2) } end
	local score = math.max(0, 100 - (#warnings * 8) - (#blockers * 25))
	local result = { ok = #blockers == 0, at = isoNow(), version = VERSION, path = safeFullName(target), className = target.ClassName, counts = counts, materials = materials, bounds = bounds, score = score, blockers = blockers, warnings = warnings, nextCommand = #blockers == 0 and ("tools\\bridge.cmd build polish " .. safeFullName(target)) or "tools\\bridge.cmd build plan <intent>" }
	V60.last.audit = result
	return result
end

function V60.getBuildOptimizationPlan(payload)
	local audit = V60.getBuildQualityAudit(payload or {})
	local actions = { "Keep big readable forms as parts; reserve micro-detail for focal areas.", "Convert repeated decorative strips to reusable modules when productionizing.", "Keep only interaction/VFX socket parts non-collidable and transparent.", "Use MeshPart consolidation only after the primitive silhouette is approved." }
	if audit.counts and audit.counts.neon and audit.counts.neon > 20 then table.insert(actions, "Reduce neon accents or group them around the primary focal point.") end
	return { ok = audit.ok ~= false, at = isoNow(), version = VERSION, target = audit.path, audit = audit, actions = actions, nextCommand = "tools\\bridge.cmd build optimize <modelPath>" }
end

function V60.polishGeneratedBuild(payload)
	payload = payload or {}
	local targetPath = payload.path or payload.modelPath or payload.targetPath
	local target = resolvePath(targetPath)
	if not target then return { ok = false, at = isoNow(), version = VERSION, status = "notFound", path = targetPath } end
	local base = safeFullName(target) .. ".CodexPolish_" .. tostring(os.time())
	local center = Vector3.new(0, 5, 0)
	local size = Vector3.new(8, 6, 8)
	pcall(function()
		if target:IsA("Model") then local cf, modelSize = target:GetBoundingBox(); center = cf.Position; size = modelSize
		elseif target:IsA("BasePart") then center = target.Position; size = target.Size end
	end)
	local palette = V60.paletteForIntent(payload.intent or target.Name)
	local steps = { { type = "createModel", path = base }, V60.part(base .. ".ReadableNamePlate", { math.max(4, size.X * 0.45), 0.35, 0.35 }, { center.X, center.Y + size.Y / 2 + 1.2, center.Z - size.Z / 2 - 0.8 }, palette.warning, "Neon", { CanCollide = false }), V60.part(base .. ".FocalGlow", { 1.2, 1.2, 1.2 }, { center.X, center.Y + size.Y / 2 + 2.2, center.Z }, palette.accent, "Neon", { CanCollide = false, Transparency = 0.25 }), V60.part(base .. ".GroundShadowPlate", { math.max(6, size.X * 0.9), 0.1, math.max(6, size.Z * 0.9) }, { center.X, center.Y - size.Y / 2 - 0.05, center.Z }, V60.rgb(20, 22, 26), "SmoothPlastic", { CanCollide = false, Transparency = 0.35 }) }
	local result = applyBuildPlan({ blueprint = { name = "CodexBuildPolish", mode = "fullTrustCodexOwnedPolish", steps = steps } })
	result.kind = "buildPolish"
	result.polishPath = base
	result.targetPath = safeFullName(target)
	V60.markGenerated(base, { intent = "polish " .. safeFullName(target), archetype = "polish" })
	V60.last.polish = result
	return result
end

function V60.optimizeGeneratedBuild(payload)
	payload = payload or {}
	local targetPath = payload.path or payload.modelPath or payload.targetPath
	local plan = V60.getBuildOptimizationPlan({ path = targetPath })
	local safe = V60.safeName((targetPath or "Build") .. "_Optimization", "BuildOptimization")
	local manifestPath = "ReplicatedStorage.CodexBuildDirector.Optimization." .. safe .. "_" .. tostring(os.time())
	local result = applyBuildPlan({ blueprint = { name = "CodexBuildOptimizationManifest", mode = "fullTrustCodexOwnedManifest", steps = { { type = "ensureFolder", path = "ReplicatedStorage.CodexBuildDirector" }, { type = "ensureFolder", path = "ReplicatedStorage.CodexBuildDirector.Optimization" }, { type = "writeScript", className = "ModuleScript", path = manifestPath, source = V60.manifestSource(plan), overwrite = false } } } })
	result.kind = "buildOptimizationManifest"
	result.optimizationManifestPath = manifestPath
	result.plan = plan
	V60.last.optimize = result
	return result
end

function V60.getBuildDirectorReport(payload)
	return { ok = true, at = isoNow(), version = VERSION, status = "ready", catalog = V60.catalog(), last = V60.last, recommendedWorkflow = { "tools\\bridge.cmd build plan \"intent\"", "tools\\bridge.cmd generate_model \"intent\"", "tools\\bridge.cmd build audit <modelPath>", "tools\\bridge.cmd build polish <modelPath>", "tools\\bridge.cmd build optimize <modelPath>" }, nextCommand = "tools\\bridge.cmd build plan <intent>" }
end

function V60.getBuildExposureGuide(payload)
	return { ok = true, at = isoNow(), version = VERSION, commands = { "tools\\bridge.cmd build styles", "tools\\bridge.cmd build plan <intent>", "tools\\bridge.cmd build generate <intent>", "tools\\bridge.cmd build scene <intent>", "tools\\bridge.cmd generate_model <intent>", "tools\\bridge.cmd generate_scene <intent>", "tools\\bridge.cmd build audit <modelPath>", "tools\\bridge.cmd polish_build <modelPath>", "tools\\bridge.cmd optimize_build <modelPath>" }, safety = "Generated objects stay under Workspace.CodexBuildDirector and ReplicatedStorage.CodexBuildDirector manifests unless a future explicit integration command says otherwise.", nextCommand = "tools\\bridge.cmd tools search build" }
end

-- V61 Roblox Brain Core + Unified Game Creator OS
function V61.withAction(payload, action)
	local copy = {}
	for key, value in pairs(payload or {}) do
		copy[key] = value
	end
	copy.action = action
	return copy
end

function V61.lower(value)
	return string.lower(tostring(value or ""))
end

function V61.has(text, ...)
	local lower = V61.lower(text)
	for _, word in ipairs({ ... }) do
		if string.find(lower, V61.lower(word), 1, true) then
			return true
		end
	end
	return false
end

function V61.safeGoal(payload)
	payload = payload or {}
	return tostring(payload.goal or payload.intent or payload.text or payload.query or "improve this Roblox game")
end

function V61.addScore(scores, key, amount)
	scores[key] = (scores[key] or 0) + amount
end

function V61.classify(goal)
	local scores = { build = 0, vfx = 0, animation = 0, motionVfx = 0, ability = 0, audio = 0, test = 0, code = 0, ui = 0, world = 0, camera = 0 }
	if V61.has(goal, "build", "model", "scene", "lobby", "arena", "map", "prop", "room", "portal", "shop", "obby", "tycoon", "base", "world") then V61.addScore(scores, "build", 4) end
	if V61.has(goal, "vfx", "effect", "aura", "beam", "projectile", "slash", "impact", "explosion", "wind", "lightning", "smoke", "portal") then V61.addScore(scores, "vfx", 4) end
	if V61.has(goal, "animation", "animate", "pose", "rig", "keyframe", "choreograph", "run", "idle", "attack motion") then V61.addScore(scores, "animation", 4) end
	if V61.has(goal, "motion vfx", "animation and vfx", "vfx and animation", "cinematic", "muzzle flash", "body aura", "hand charge") then V61.addScore(scores, "motionVfx", 6) end
	if V61.has(goal, "ability", "skill", "power", "attack", "spell", "ultimate", "boss move", "combat") then V61.addScore(scores, "ability", 4) end
	if V61.has(goal, "audio", "sound", "music", "sfx", "volume", "loud", "quiet", "mix", "ambience") then V61.addScore(scores, "audio", 4) end
	if V61.has(goal, "test", "qa", "playtest", "bug", "verify", "launch", "mobile", "first minutes") then V61.addScore(scores, "test", 4) end
	if V61.has(goal, "script", "code", "system", "remote", "datastore", "server", "client", "fix") then V61.addScore(scores, "code", 3) end
	if V61.has(goal, "ui", "hud", "menu", "button", "shop", "screen", "mobile layout") then V61.addScore(scores, "ui", 3) end
	if V61.has(goal, "camera", "screen", "view", "cinematic shot", "composition") then V61.addScore(scores, "camera", 3) end
	if V61.has(goal, "premium", "top dev", "polish", "beautiful", "better", "massive", "everything", "whole game") then
		V61.addScore(scores, "build", 2)
		V61.addScore(scores, "vfx", 2)
		V61.addScore(scores, "animation", 2)
		V61.addScore(scores, "audio", 2)
		V61.addScore(scores, "test", 2)
	end
	if V61.has(goal, "simulator") then V61.addScore(scores, "ui", 1) end
	local priority = { "motionVfx", "ability", "build", "vfx", "animation", "audio", "test", "ui", "code", "camera", "world" }
	local primary = "build"
	local best = -1
	for _, key in ipairs(priority) do
		local value = scores[key] or 0
		if value > best then
			best = value
			primary = key
		end
	end
	local style = "cleanUniversal"
	if V61.has(goal, "anime", "purple", "magic", "rift", "aura") then style = "animeMystic" end
	if V61.has(goal, "sci", "cyber", "tech", "neon") then style = "neonTech" end
	if V61.has(goal, "horror", "dark", "scary") then style = "darkTension" end
	return {
		goal = goal,
		scores = scores,
		primaryDomain = primary,
		confidence = math.min(0.98, 0.48 + (best * 0.07)),
		style = style,
		scale = V61.has(goal, "huge", "massive", "boss", "world", "whole game") and "large" or "focused",
		gameType = V61.has(goal, "obby") and "obby" or (V61.has(goal, "simulator") and "simulator" or (V61.has(goal, "horror") and "horror" or (V61.has(goal, "combat", "arena", "boss") and "combat" or "universal"))),
	}
end

function V61.manifest()
	return {
		name = "Roblox Brain Core",
		version = VERSION,
		purpose = "Unify StudioBridge perception, planning, generation, testing, polish, and handoff across every Roblox project.",
		brainLoops = { "understand", "design", "route", "generate", "integrate", "test", "polish", "optimize", "remember" },
		specialists = {
			build = { command = "tools\\bridge.cmd build plan <goal>", creates = "Workspace.CodexBuildDirector" },
			vfx = { command = "tools\\bridge.cmd generate_pro_vfx <goal>", creates = "ReplicatedStorage.CodexVfxWorkbench" },
			animation = { command = "tools\\bridge.cmd animation choreograph <rigPath> <goal>", creates = "ReplicatedStorage.GeneratedAnimations" },
			motionVfx = { command = "tools\\bridge.cmd generate_motion_vfx <goal>", creates = "ReplicatedStorage.CodexMotionVfxForge" },
			ability = { command = "tools\\bridge.cmd generate_ability <goal>", creates = "ReplicatedStorage.CodexAbilityForge" },
			audio = { command = "tools\\bridge.cmd audio plan <goal>", creates = "SoundService/Codex audio metadata" },
			test = { command = "tools\\bridge.cmd test run <recipe>", creates = "runtime evidence only" },
			code = { command = "tools\\bridge.cmd code doctor", creates = "hash-backed patches only when explicitly routed" },
		},
		qualityRules = { "player readability first", "large silhouette before detail", "feedback at every important action", "mobile performance budget before spectacle", "generated assets stay organized and versioned", "test evidence beats assumptions" },
		fullTrust = { localStudioBridgeActions = true, auditEveryMutation = true, externalAccountRisksStillManual = true },
	}
end

function V61.commandsFor(profile, action)
	local goal = profile.goal
	local q = "\"" .. string.gsub(goal, "\"", "\\\"") .. "\""
	local commands = { "tools\\bridge.cmd brain scan", "tools\\bridge.cmd brain plan " .. q }
	if profile.primaryDomain == "motionVfx" then
		table.insert(commands, "tools\\bridge.cmd generate_motion_vfx " .. q)
	elseif profile.primaryDomain == "ability" then
		table.insert(commands, "tools\\bridge.cmd generate_ability " .. q)
	elseif profile.primaryDomain == "vfx" then
		table.insert(commands, "tools\\bridge.cmd generate_pro_vfx " .. q)
	elseif profile.primaryDomain == "animation" then
		table.insert(commands, "tools\\bridge.cmd animation choreograph <rigPath> " .. q)
	elseif profile.primaryDomain == "audio" then
		local audioCommand = "tools\\bridge.cmd audio plan " .. q
		if action == "polish" or action == "improve" then
			audioCommand = "tools\\bridge.cmd audio mix " .. q
		end
		table.insert(commands, audioCommand)
	elseif profile.primaryDomain == "test" then
		table.insert(commands, "tools\\bridge.cmd test plan " .. q)
		table.insert(commands, "tools\\bridge.cmd test run " .. q)
	elseif profile.primaryDomain == "code" then
		table.insert(commands, "tools\\bridge.cmd baseline mark")
		table.insert(commands, "tools\\bridge.cmd code doctor")
	elseif profile.primaryDomain == "ui" then
		table.insert(commands, "tools\\bridge.cmd ui deep")
		table.insert(commands, "tools\\bridge.cmd action ui list")
	else
		table.insert(commands, profile.scale == "large" and ("tools\\bridge.cmd generate_scene " .. q) or ("tools\\bridge.cmd generate_model " .. q))
	end
	table.insert(commands, "tools\\bridge.cmd watch errors")
	table.insert(commands, "tools\\bridge.cmd brain quality " .. q)
	return commands
end

function V61.getRobloxBrainManifest(payload)
	return { ok = true, at = isoNow(), version = VERSION, manifest = V61.manifest(), commands = { "tools\\bridge.cmd brain status", "tools\\bridge.cmd brain scan", "tools\\bridge.cmd brain plan <goal>", "tools\\bridge.cmd roblox_brain <goal>", "tools\\bridge.cmd build_game <goal>", "tools\\bridge.cmd improve_game <goal>", "tools\\bridge.cmd test_game <goal>", "tools\\bridge.cmd polish_game <goal>" }, nextCommand = "tools\\bridge.cmd brain plan <goal>" }
end

function V61.getRobloxBrainContext(payload)
	payload = payload or {}
	local contextOk, context = pcall(function() return V46.getCodexLiveContext(payload) end)
	local toolsOk, tools = pcall(function() return V46.getCodexToolManifest({}) end)
	local statusOk, startStatus = pcall(function() return V29.getProjectStartStatus(payload) end)
	local watchOk, watch = pcall(function() return V28.getWatchNow(payload) end)
	return {
		ok = true,
		at = isoNow(),
		version = VERSION,
		context = contextOk and context or { ok = false, error = tostring(context) },
		watch = watchOk and watch or nil,
		start = statusOk and startStatus or nil,
		toolCategories = toolsOk and tools.summary or nil,
		memory = payload.memory,
		fullTrust = V41.mode(),
		nextCommand = "tools\\bridge.cmd brain plan <goal>",
	}
end

function V61.getRobloxBrainPlan(payload)
	payload = payload or {}
	local action = tostring(payload.action or "plan")
	local goal = V61.safeGoal(payload)
	local profile = V61.classify(goal)
	local phases = {
		{ id = "understand", command = "tools\\bridge.cmd brain scan", evidence = "live context, output, watch, tree, tool readiness" },
		{ id = "design", command = "tools\\bridge.cmd brain plan \"" .. goal .. "\"", evidence = "style, player loop, visual hierarchy, performance budget" },
		{ id = "generate", command = V61.commandsFor(profile, action)[3], evidence = "Codex-owned generated assets and manifests" },
		{ id = "test", command = "tools\\bridge.cmd test snapshot", evidence = "runtime state, output, UI, player data" },
		{ id = "polish", command = "tools\\bridge.cmd brain polish \"" .. goal .. "\"", evidence = "readability, VFX/audio/animation/camera sync, mobile risk" },
		{ id = "optimize", command = "tools\\bridge.cmd plugin-health", evidence = "parity, source safety, performance warnings" },
	}
	local result = {
		ok = true,
		at = isoNow(),
		version = VERSION,
		goal = goal,
		action = action,
		breakdown = profile,
		phases = phases,
		exactCommands = V61.commandsFor(profile, action),
		brainPrinciples = V61.manifest().qualityRules,
		specialistStack = V61.manifest().specialists,
		nextCommand = profile.confidence >= 0.75 and ("tools\\bridge.cmd brain " .. (action == "plan" and "build" or action) .. " \"" .. goal .. "\"") or "tools\\bridge.cmd brain route <goal>",
	}
	V61.last.plan = result
	return result
end

function V61.getRobloxBrainRoute(payload)
	local plan = V61.getRobloxBrainPlan(payload or {})
	return { ok = true, at = isoNow(), version = VERSION, goal = plan.goal, primaryDomain = plan.breakdown.primaryDomain, confidence = plan.breakdown.confidence, command = plan.exactCommands[3] or plan.exactCommands[1], allCommands = plan.exactCommands, rationale = "Chosen from unified goal classification and current StudioBridge specialist availability.", nextCommand = plan.nextCommand }
end

function V61.getRobloxBrainQualityReport(payload)
	payload = payload or {}
	local goal = V61.safeGoal(payload)
	local profile = V61.classify(goal)
	local context = V61.getRobloxBrainContext(payload)
	local warnings = {}
	local score = 86
	if context.context and context.context.readiness and context.context.readiness.toolkitInstalled == false then
		table.insert(warnings, "Codex Ready toolkit is not fully installed for this place.")
		score -= 14
	end
	if context.watch and context.watch.latestOutputIssue then
		table.insert(warnings, "Current watch/output issue should be fixed before launch polish.")
		score -= 12
	end
	if profile.scores.test < 2 then
		table.insert(warnings, "Goal does not explicitly include QA; add a brain test pass after generation.")
		score -= 4
	end
	if profile.scores.audio < 2 and (profile.scores.vfx > 0 or profile.scores.ability > 0 or profile.scores.motionVfx > 0) then
		table.insert(warnings, "Visual/action goal should include audio cue planning for premium feel.")
		score -= 5
	end
	return { ok = true, at = isoNow(), version = VERSION, goal = goal, score = math.max(0, score), profile = profile, warnings = warnings, checks = { styleCoherence = profile.style, primaryDomain = profile.primaryDomain, fullTrust = V41.mode(), contextFresh = context.context and context.context.freshness and context.context.freshness.fresh == true }, nextCommand = #warnings > 0 and "tools\\bridge.cmd brain improve <goal>" or "tools\\bridge.cmd brain build <goal>" }
end

function V61.getRobloxBrainStatus(payload)
	local context = V61.getRobloxBrainContext(payload or {})
	local manifest = V61.manifest()
	return { ok = true, at = isoNow(), version = VERSION, status = "ready", fullTrust = V41.mode(), context = context, specialistCount = 0, manifest = manifest, last = V61.last, nextCommand = "tools\\bridge.cmd brain plan <goal>" }
end

function V61.getRobloxBrainDirectorReport(payload)
	return { ok = true, at = isoNow(), version = VERSION, status = "ready", manifest = V61.manifest(), statusReport = V61.getRobloxBrainStatus(payload or {}), recentPlan = V61.last.plan, recommendedWorkflow = { "tools\\bridge.cmd brain scan", "tools\\bridge.cmd brain plan \"goal\"", "tools\\bridge.cmd roblox_brain \"goal\"", "tools\\bridge.cmd brain test \"goal\"", "tools\\bridge.cmd brain polish \"goal\"" }, nextCommand = "tools\\bridge.cmd brain plan <goal>" }
end

function V61.writeBrainManifest(plan, execution)
	local safe = V60.safeName((plan.breakdown and plan.breakdown.primaryDomain or "Brain") .. "_" .. plan.goal, "RobloxBrainPlan")
	local path = "ReplicatedStorage.CodexRobloxBrain.Plans." .. safe .. "_" .. tostring(os.time())
	local manifest = { plan = plan, execution = execution, writtenAt = isoNow(), version = VERSION }
	local result = applyBuildPlan({ blueprint = { name = "CodexRobloxBrainManifest", mode = "fullTrustBrainManifest", steps = { { type = "ensureFolder", path = "ReplicatedStorage.CodexRobloxBrain" }, { type = "ensureFolder", path = "ReplicatedStorage.CodexRobloxBrain.Plans" }, { type = "writeScript", className = "ModuleScript", path = path, source = V60.manifestSource(manifest), overwrite = false } } } })
	return { path = path, result = result }
end

function V61.addArtifact(list, value)
	if type(value) == "string" and value ~= "" then
		table.insert(list, value)
	end
end

function V61.compactList(list, limit)
	local out = {}
	if type(list) ~= "table" then
		return out
	end
	for _, value in ipairs(list) do
		if #out >= (limit or 8) then
			break
		end
		if value ~= nil then
			table.insert(out, value)
		end
	end
	return out
end

function V61.summarizeSpecialist(label, result)
	result = type(result) == "table" and result or {}
	local artifacts = {}
	V61.addArtifact(artifacts, result.path)
	V61.addArtifact(artifacts, result.buildPath)
	V61.addArtifact(artifacts, result.manifestPath)
	V61.addArtifact(artifacts, result.presetPath)
	V61.addArtifact(artifacts, result.packagePath)
	V61.addArtifact(artifacts, result.animationPath)
	V61.addArtifact(artifacts, result.abilityPath)
	V61.addArtifact(artifacts, result.vfxPresetPath)
	V61.addArtifact(artifacts, result.modelPath)
	if type(result.manifest) == "table" then
		V61.addArtifact(artifacts, result.manifest.path)
		V61.addArtifact(artifacts, result.manifestPath)
	end
	return {
		label = label,
		ok = result.ok ~= false,
		status = tostring(result.status or (result.ok == false and "failed" or "ok")),
		artifacts = artifacts,
		stepCount = result.stepCount or (result.blueprint and type(result.blueprint.steps) == "table" and #result.blueprint.steps or nil),
		warnings = V61.compactList(result.warnings, 6),
		blockers = V61.compactList(result.blockers, 6),
		nextCommand = result.nextCommand,
		summary = result.summary or result.message or result.intent,
	}
end

function V61.trySpecialist(label, fn, payload)
	if type(fn) ~= "function" then
		return { label = label, ok = false, skipped = true, reason = "Specialist function is unavailable in the loaded plugin." }
	end
	local ok, result = pcall(fn, payload)
	if not ok then
		return { label = label, ok = false, error = tostring(result) }
	end
	return V61.summarizeSpecialist(label, result)
end

function V61.executeRobloxBrainPlan(payload)
	payload = payload or {}
	local action = tostring(payload.action or "build")
	local goal = V61.safeGoal(payload)
	local plan = V61.getRobloxBrainPlan({ goal = goal, action = action, memory = payload.memory })
	local profile = plan.breakdown
	local specialistResults = {}
	if action == "test" then
		table.insert(specialistResults, { label = "testRoute", ok = true, manual = false, command = "tools\\bridge.cmd test run \"" .. goal .. "\"", note = "Brain recorded the test route; Test Pilot commands remain available for runtime execution." })
	elseif profile.primaryDomain == "motionVfx" then
		table.insert(specialistResults, V61.trySpecialist("motionVfx", V54 and V54.generateMotionVfxPackage, { intent = goal, goal = goal }))
	elseif profile.primaryDomain == "ability" then
		table.insert(specialistResults, V61.trySpecialist("ability", V44 and V44.generateAbilityFromIntent, { intent = goal, goal = goal }))
	elseif profile.primaryDomain == "vfx" then
		table.insert(specialistResults, V61.trySpecialist("proVfx", V51 and V51.generateProVfxFromIntent, { intent = goal, goal = goal, targetPath = payload.targetPath, assetRoot = payload.assetRoot }))
	elseif profile.primaryDomain == "animation" then
		table.insert(specialistResults, V61.trySpecialist("animationPlan", V53 and V53.getAnimationAbilityMotionPlan, { intent = goal, goal = goal, rigPath = payload.rigPath }))
	elseif profile.primaryDomain == "audio" then
		local audioFn = (action == "polish" or action == "improve") and V59.applyAudioMixPlan or V59.getAudioMixPlan
		table.insert(specialistResults, V61.trySpecialist("audio", audioFn, { intent = goal, profile = payload.profile or "balanced" }))
	elseif profile.primaryDomain == "code" then
		table.insert(specialistResults, { label = "codeRoute", ok = true, command = "tools\\bridge.cmd code doctor", note = "Brain avoids hidden arbitrary code execution; use hash-backed code routes." })
	else
		local generateFn = profile.scale == "large" and V60.generateSceneFromIntent or V60.generateModelFromIntent
		table.insert(specialistResults, V61.trySpecialist("build", generateFn, { intent = goal, goal = goal }))
	end
	local manifest = V61.writeBrainManifest(plan, { action = action, specialistResults = specialistResults })
	local primary = specialistResults[1] or {}
	local artifacts = {}
	for _, item in ipairs(specialistResults) do
		if type(item.artifacts) == "table" then
			for _, path in ipairs(item.artifacts) do
				V61.addArtifact(artifacts, path)
			end
		end
	end
	V61.addArtifact(artifacts, manifest.path)
	local warnings = {}
	local blockers = {}
	for _, item in ipairs(specialistResults) do
		if type(item.warnings) == "table" then
			for _, warning in ipairs(item.warnings) do table.insert(warnings, warning) end
		end
		if item.ok == false then
			table.insert(blockers, item.error or item.reason or (item.label .. " did not complete."))
		end
		if type(item.blockers) == "table" then
			for _, blocker in ipairs(item.blockers) do table.insert(blockers, blocker) end
		end
	end
	local result = {
		ok = #blockers == 0,
		status = #blockers == 0 and "executed" or "needsAttention",
		contract = "robloxBrainExecution.v2",
		at = isoNow(),
		version = VERSION,
		action = action,
		goal = goal,
		primaryDomain = profile.primaryDomain,
		style = profile.style,
		specialist = primary.label,
		specialistResults = specialistResults,
		artifacts = artifacts,
		manifestPath = manifest.path,
		planSummary = {
			primaryDomain = profile.primaryDomain,
			confidence = profile.confidence,
			style = profile.style,
			scale = profile.scale,
			gameType = profile.gameType,
			phaseCount = #(plan.phases or {}),
		},
		warnings = V61.compactList(warnings, 8),
		blockers = V61.compactList(blockers, 8),
		summary = "Roblox Brain routed " .. action .. " through " .. tostring(primary.label or profile.primaryDomain) .. " and wrote a Codex-owned manifest.",
		nextCommands = plan.exactCommands,
		nextCommand = "tools\\bridge.cmd brain quality \"" .. goal .. "\"",
	}
	V61.last.execution = result
	return result
end

-- V62 Roblox Creator OS + Asset Forge
function V62.safeIntent(payload)
	payload = payload or {}
	return tostring(payload.intent or payload.goal or payload.text or payload.query or "premium Roblox game experience")
end

function V62.styleFromIntent(intent)
	local style = "premiumUniversal"
	if V61.has(intent, "slime", "bubble", "cute", "pet", "simulator", "candy") then style = "toyBrightSimulator" end
	if V61.has(intent, "anime", "aura", "beam", "sword", "boss", "ultimate") then style = "animeCinematic" end
	if V61.has(intent, "sci", "cyber", "tech", "neon", "space") then style = "neonTech" end
	if V61.has(intent, "horror", "dark", "haunted", "scary") then style = "darkAtmospheric" end
	if V61.has(intent, "fantasy", "magic", "portal", "castle") then style = "fantasyAdventure" end
	return style
end

function V62.archetypeFromIntent(intent)
	if V61.has(intent, "lobby", "hub", "spawn") then return "spawnHub" end
	if V61.has(intent, "arena", "boss", "combat") then return "combatArena" end
	if V61.has(intent, "obby", "course", "stage") then return "obbyCourse" end
	if V61.has(intent, "tycoon", "factory", "dropper") then return "tycoonBase" end
	if V61.has(intent, "ability", "power", "attack", "skill") then return "abilityPackage" end
	if V61.has(intent, "vfx", "effect", "beam", "aura", "projectile") then return "vfxPackage" end
	return "premiumGameSlice"
end

function V62.materialLanguage(style)
	if style == "toyBrightSimulator" then
		return { "glossy white plastic", "transparent glass tubes", "gold rounded trim", "colored portal glow", "slime decals", "bubble particles" }
	elseif style == "animeCinematic" then
		return { "high contrast neon accents", "dark readable bases", "emissive aura cores", "trail-ready metal", "impact flash materials" }
	elseif style == "neonTech" then
		return { "black satin metal", "cyan/magenta neon", "panel seams", "glass screens", "thin gold or chrome trims" }
	elseif style == "darkAtmospheric" then
		return { "rough stone", "desaturated wood", "fog layers", "warm diegetic lights", "high contrast silhouette props" }
	end
	return { "primary material family", "secondary contrast material", "trim material", "glass/glow material", "ground/readability material" }
end

function V62.shapeGrammar(style, archetype)
	local grammar = {
		primaryShapes = { "large readable silhouettes", "rounded bevel-like trims", "clear focal center", "layered height tiers" },
		modules = { "base plinth", "portal/entry frame", "trim rail", "sign frame", "VFX socket", "interaction pad" },
		detailRules = { "big shape first", "repeated trim rhythm", "color-coded interactables", "avoid tiny noise at player scale", "reserve glow for important actions" },
	}
	if archetype == "spawnHub" then
		grammar.modules = { "spawn pad", "central core", "radial paths", "shop portals", "leaderboard bay", "upgrade/pets/rebirth bays", "background landmarks" }
	elseif archetype == "combatArena" then
		grammar.modules = { "central fight floor", "cover pieces", "entry gates", "spectator rim", "VFX-safe impact zones", "camera-readable landmarks" }
	elseif archetype == "abilityPackage" or archetype == "vfxPackage" then
		grammar.modules = { "attachment targets", "animation markers", "charge layer", "release flash", "projectile/trail layer", "impact/residue layer", "audio cue slots" }
	end
	if style == "toyBrightSimulator" then
		grammar.primaryShapes = { "soft cylinders", "rounded arches", "chunky signs", "fat pipes", "bubble circles", "dripping slime silhouettes" }
	end
	return grammar
end

function V62.getCreatorStyleBible(payload)
	local intent = V62.safeIntent(payload)
	local style = V62.styleFromIntent(intent)
	local archetype = V62.archetypeFromIntent(intent)
	local bible = {
		name = style .. " Style Bible",
		intent = intent,
		style = style,
		archetype = archetype,
		visualPromise = "Make every generated asset feel intentional, readable, premium, mobile-safe, and connected to gameplay purpose.",
		palette = style == "toyBrightSimulator" and {
			primary = "sky cyan",
			secondary = "bubble pink",
			accent = "slime green",
			trim = "warm gold",
			neutral = "soft white stone",
		} or {
			primary = "clear focal color from intent",
			secondary = "cool/warm contrast color",
			accent = "limited high-energy glow",
			trim = "premium metallic or dark outline",
			neutral = "readable base material",
		},
		materials = V62.materialLanguage(style),
		shapeGrammar = V62.shapeGrammar(style, archetype),
		lighting = { "strong readable key light", "soft fill", "Bloom only on focal VFX", "Atmosphere/DepthOfField tuned after screenshot compare" },
		signage = { "3D sign frames", "large readable labels", "icon support", "color-coded service zones", "avoid tiny text on mobile" },
		vfxLanguage = { "ambient motion at low cost", "action VFX only at gameplay beats", "particles support silhouette instead of hiding it", "cleanup and mobile budget required" },
		audioLanguage = { "UI clicks are crisp and quiet", "major actions need impact cues", "ambience stays below gameplay SFX", "mix profile chosen by intent" },
		performanceBudget = { parts = "prefer modular repetition", particles = "cap emitters and burst counts", lights = "few focal lights", mobile = "first-class target" },
	}
	V62.last.styleBible = bible
	return { ok = true, at = isoNow(), version = VERSION, styleBible = bible, nextCommand = "tools\\bridge.cmd creator assets \"" .. intent .. "\"" }
end

function V62.getCreatorAssetForgePlan(payload)
	local intent = V62.safeIntent(payload)
	local style = V62.styleFromIntent(intent)
	local archetype = V62.archetypeFromIntent(intent)
	local kitRoots = { payload and payload.assetRoot or nil, "Workspace", "ReplicatedStorage", "StarterGui", "SoundService" }
	local roles = {
		meshes = { "arches/domescaps", "pipes/tubes", "trim rings", "sign boards", "projectile cores", "shockwave rings", "portal frames" },
		materials = V62.materialLanguage(style),
		textures = { "trim sheet", "decal icons", "slime/noise/glow masks", "portal swirl", "spark/smoke/slash particles" },
		audio = { "UI click", "portal hum", "charge", "release", "impact", "reward" },
		animation = { "idle loop", "interact pose", "ability charge", "impact reaction", "emote/cinematic beat" },
	}
	return {
		ok = true,
		at = isoNow(),
		version = VERSION,
		intent = intent,
		style = style,
		archetype = archetype,
		assetForge = {
			kitRoots = kitRoots,
			reuseFirst = true,
			createWhenMissing = { "simple primitive modules in Studio", "mesh export plan for Blender/Open Cloud when Roblox primitives cannot hit the silhouette", "generated decals/textures only through explicit local asset workflow" },
			roles = roles,
			indexCommands = { "tools\\bridge.cmd build kit Workspace", "tools\\bridge.cmd vfx textures Workspace", "tools\\bridge.cmd audio catalog Workspace", "tools\\bridge.cmd animation list Workspace" },
			outputFolders = { "Workspace.CodexBuildDirector", "ReplicatedStorage.CodexVfxWorkbench", "ReplicatedStorage.GeneratedAnimations", "ReplicatedStorage.CodexCreatorOS" },
		},
		nextCommand = "tools\\bridge.cmd creator pipeline \"" .. intent .. "\"",
	}
end

function V62.getCreatorProductionPipeline(payload)
	local intent = V62.safeIntent(payload)
	local style = V62.styleFromIntent(intent)
	return {
		ok = true,
		at = isoNow(),
		version = VERSION,
		intent = intent,
		style = style,
		pipeline = {
			{ id = "reference", command = "tools\\bridge.cmd creator style \"" .. intent .. "\"", evidence = "style bible, shape grammar, material language" },
			{ id = "inventory", command = "tools\\bridge.cmd creator assets \"" .. intent .. "\"", evidence = "asset roles, reusable kit roots, missing asset list" },
			{ id = "blockout", command = "tools\\bridge.cmd build plan \"" .. intent .. "\"", evidence = "layout, scale, sockets, modular grammar" },
			{ id = "generate", command = "tools\\bridge.cmd creator generate \"" .. intent .. "\"", evidence = "Codex-owned manifests plus specialist generated assets" },
			{ id = "visual-pass", command = "tools\\bridge.cmd camera director", evidence = "camera framing and screenshot targets" },
			{ id = "critique", command = "tools\\bridge.cmd creator critique \"" .. intent .. "\"", evidence = "compare composition/material/detail/readability against style bible" },
			{ id = "polish", command = "tools\\bridge.cmd creator polish \"" .. intent .. "\"", evidence = "trim/detail/VFX/audio/lighting/performance iteration" },
			{ id = "qa", command = "tools\\bridge.cmd test_game \"full launch QA for " .. intent .. "\"", evidence = "runtime, UI, output, movement, interaction, performance" },
		},
		externalPipeline = {
			"Use Blender/Python or future mesh generator for rounded custom silhouettes Roblox primitives cannot match.",
			"Use glTF/PBR-style material thinking for SurfaceAppearance/texture atlas plans.",
			"Use screenshot compare loops instead of trusting first-pass generation.",
			"Use Open Cloud/manual import only when creator credentials and Roblox upload flow allow it.",
		},
		nextCommand = "tools\\bridge.cmd creator generate \"" .. intent .. "\"",
	}
end

function V62.getCreatorVisualCritiquePlan(payload)
	local intent = V62.safeIntent(payload)
	local style = V62.styleFromIntent(intent)
	return {
		ok = true,
		at = isoNow(),
		version = VERSION,
		intent = intent,
		style = style,
		critique = {
			scoreAreas = { "composition/focal point", "shape silhouette", "material harmony", "detail density", "VFX sync", "lighting/camera", "mobile readability", "performance budget", "gameplay clarity" },
			loop = {
				"capture current camera/screen",
				"compare against style bible and target intent",
				"list exact misses by priority",
				"route fixes to Build/VFX/Animation/Audio/Camera/Test specialists",
				"repeat until the visual promise is met",
			},
			commands = { "tools\\bridge.cmd camera director", "tools\\bridge.cmd screen status", "tools\\bridge.cmd build audit <modelPath>", "tools\\bridge.cmd vfx audit <presetPath>", "tools\\bridge.cmd audio audit Workspace", "tools\\bridge.cmd creator polish \"" .. intent .. "\"" },
		},
		nextCommand = "tools\\bridge.cmd creator polish \"" .. intent .. "\"",
	}
end

function V62.getCreatorGameBlueprint(payload)
	local intent = V62.safeIntent(payload)
	local styleBible = V62.getCreatorStyleBible({ intent = intent }).styleBible
	local assetForge = V62.getCreatorAssetForgePlan({ intent = intent, assetRoot = payload and payload.assetRoot or nil }).assetForge
	local pipeline = V62.getCreatorProductionPipeline({ intent = intent }).pipeline
	local profile = V61.classify(intent)
	local blueprint = {
		intent = intent,
		styleBible = styleBible,
		assetForge = assetForge,
		productionPipeline = pipeline,
		brainRoute = V61.getRobloxBrainRoute({ goal = intent, intent = intent }),
		qualityGates = {
			"clear player purpose in first camera view",
			"large silhouette reads before small detail",
			"materials and colors obey style bible",
			"all key interactions have VFX/audio/animation feedback",
			"mobile budget and output errors checked before calling it done",
		},
		profile = profile,
	}
	V62.last.blueprint = blueprint
	return { ok = true, at = isoNow(), version = VERSION, blueprint = blueprint, nextCommand = "tools\\bridge.cmd creator generate \"" .. intent .. "\"" }
end

function V62.writeCreatorManifest(kind, payload)
	local intent = V62.safeIntent(payload)
	local safe = V60.safeName(kind .. "_" .. intent, "CreatorOS")
	local path = "ReplicatedStorage.CodexCreatorOS." .. tostring(kind) .. "." .. safe .. "_" .. tostring(os.time())
	local sourcePayload = { kind = kind, intent = intent, generatedAt = isoNow(), version = VERSION, payload = payload }
	return applyBuildPlan({ blueprint = { name = "CodexCreatorOS" .. tostring(kind), mode = "fullTrustCreatorOSManifest", steps = { { type = "ensureFolder", path = "ReplicatedStorage.CodexCreatorOS" }, { type = "ensureFolder", path = "ReplicatedStorage.CodexCreatorOS.StyleBibles" }, { type = "ensureFolder", path = "ReplicatedStorage.CodexCreatorOS.AssetForge" }, { type = "ensureFolder", path = "ReplicatedStorage.CodexCreatorOS.Blueprints" }, { type = "ensureFolder", path = "ReplicatedStorage.CodexCreatorOS.Packages" }, { type = "writeScript", className = "ModuleScript", path = path, source = V60.manifestSource(sourcePayload), overwrite = false } } } }), path
end

function V62.bakeCreatorStyleBible(payload)
	local report = V62.getCreatorStyleBible(payload or {})
	local result, manifestPath = V62.writeCreatorManifest("StyleBibles", report.styleBible)
	report.status = result and result.status or "written"
	report.manifestPath = manifestPath
	report.result = result
	V62.last.styleBake = report
	return report
end

function V62.applyCreatorOsPlan(payload)
	payload = payload or {}
	local intent = V62.safeIntent(payload)
	local blueprint = V62.getCreatorGameBlueprint({ intent = intent, assetRoot = payload.assetRoot }).blueprint
	local brainExecution = V61.executeRobloxBrainPlan({ goal = intent, intent = intent, action = payload.action or "build", rigPath = payload.rigPath, targetPath = payload.targetPath, assetRoot = payload.assetRoot })
	local result, manifestPath = V62.writeCreatorManifest("Packages", { intent = intent, blueprint = blueprint, brainExecution = brainExecution })
	local artifacts = {}
	if type(brainExecution.artifacts) == "table" then
		for _, value in ipairs(brainExecution.artifacts) do table.insert(artifacts, value) end
	end
	table.insert(artifacts, manifestPath)
	local package = {
		ok = brainExecution.ok ~= false and (result == nil or result.ok ~= false),
		status = "executed",
		contract = "creatorOSPackage.v1",
		at = isoNow(),
		version = VERSION,
		intent = intent,
		style = blueprint.styleBible.style,
		archetype = blueprint.styleBible.archetype,
		manifestPath = manifestPath,
		brainExecution = brainExecution,
		artifacts = artifacts,
		warnings = brainExecution.warnings or {},
		blockers = brainExecution.blockers or {},
		summary = "Creator OS generated a style bible, asset forge plan, production blueprint, and routed the goal through the unified Roblox Brain.",
		nextCommand = "tools\\bridge.cmd creator critique \"" .. intent .. "\"",
	}
	V62.last.package = package
	return package
end

function V62.generateCreatorOsPackage(payload)
	return V62.applyCreatorOsPlan(payload or {})
end

function V62.polishCreatorOsPackage(payload)
	local intent = V62.safeIntent(payload)
	local critique = V62.getCreatorVisualCritiquePlan({ intent = intent })
	local brainPolish = V61.executeRobloxBrainPlan({ goal = intent, intent = intent, action = "polish", rigPath = payload and payload.rigPath or nil, targetPath = payload and payload.targetPath or nil, assetRoot = payload and payload.assetRoot or nil })
	local result, manifestPath = V62.writeCreatorManifest("Packages", { intent = intent, critique = critique, polish = brainPolish })
	return { ok = brainPolish.ok ~= false, at = isoNow(), version = VERSION, intent = intent, status = "polishRouted", critique = critique, polish = brainPolish, manifestPath = manifestPath, writeResult = result, nextCommand = "tools\\bridge.cmd creator critique \"" .. intent .. "\"" }
end

function V62.getCreatorOsStatus(payload)
	return { ok = true, at = isoNow(), version = VERSION, status = "ready", name = "Roblox Creator OS + Asset Forge", fullTrust = V41.mode(), last = V62.last, capabilities = { "style bible", "asset forge", "procedural build grammar", "VFX/animation/audio sync", "external mesh/material pipeline plan", "visual critique loop", "unified specialist routing" }, nextCommand = "tools\\bridge.cmd creator blueprint <intent>" }
end

function V62.getCreatorOsCapabilityMap(payload)
	return { ok = true, at = isoNow(), version = VERSION, categories = { build = "V60 Build Director", brain = "V61 Roblox Brain", creatorOs = "V62 style/asset/critique/package brain", vfx = "V51/V52 pro VFX", animation = "V53 choreographer", motionVfx = "V54 fusion", ability = "V44 forge", audio = "V59 director", test = "V45 pilot", camera = "V37/V38 camera/screen" }, directCommands = { "creator_os", "create_game", "premium_build", "style_bible", "forge_assets", "visual_critique" }, nextCommand = "tools\\bridge.cmd creator director" }
end

function V62.getCreatorDirectorReport(payload)
	return { ok = true, at = isoNow(), version = VERSION, status = "ready", statusReport = V62.getCreatorOsStatus(payload or {}), capabilityMap = V62.getCreatorOsCapabilityMap(payload or {}), workflow = { "tools\\bridge.cmd creator style <intent>", "tools\\bridge.cmd creator assets <intent>", "tools\\bridge.cmd creator blueprint <intent>", "tools\\bridge.cmd creator generate <intent>", "tools\\bridge.cmd creator critique <intent>", "tools\\bridge.cmd creator polish <intent>" }, last = V62.last, nextCommand = "tools\\bridge.cmd creator blueprint <intent>" }
end

