function commandRequiresApproval(command)
	if command.requiresApproval ~= nil then
		return command.requiresApproval == true
	end
	return mutatingTypes[command.type] == true
end

local function startPluginUi()
local widgetInfo = DockWidgetPluginGuiInfo.new(
	Enum.InitialDockState.Right,
	false,
	false,
	420,
	640,
	320,
	460
)

local widget
local okWidget, widgetOrError = pcall(function()
	return plugin:CreateDockWidgetPluginGuiAsync("CodexStudioBridgeV1", widgetInfo)
end)
if okWidget then
	widget = widgetOrError
else
	widget = plugin:CreateDockWidgetPluginGui("CodexStudioBridgeV1", widgetInfo)
end
widget.Title = "Codex Studio Bridge"

