local function updateStatus(text)
	statusLabel.Text = text
end

local function refreshAutoApproveUi()
	local trustMode = V41.mode()
	if trustMode == "fullTrustAutopilot" then
		autoModeButton.Text = "Full Trust: ON"
		autoModeButton.BackgroundColor3 = Color3.fromRGB(38, 152, 95)
	elseif trustMode == "paused" then
		autoModeButton.Text = "Full Trust: PAUSED"
		autoModeButton.BackgroundColor3 = Color3.fromRGB(172, 112, 44)
	elseif trustMode == "emergencyStop" then
		autoModeButton.Text = "Emergency Stop"
		autoModeButton.BackgroundColor3 = Color3.fromRGB(158, 64, 64)
	else
		autoModeButton.Text = "Full Trust: OFF"
		autoModeButton.BackgroundColor3 = Color3.fromRGB(66, 72, 82)
	end
	autoOffButton.Text = "Emergency Stop"
end

updateSnapshotLabel = function()
	if not State.snapshotStats then
		snapshotLabel.Text = "Snapshot: waiting"
		return
	end
	local truncatedText = State.snapshotStats.truncated and "truncated" or "complete"
	snapshotLabel.Text = "Snapshot: " .. tostring(State.snapshotStats.nodeCount)
		.. " nodes, " .. tostring(State.snapshotStats.scriptCount)
		.. " scripts, " .. truncatedText
end

updateLastCommandLabel = function()
	lastCommandLabel.Text = "Last command: " .. tostring(State.commandSummary)
end

updateRuntimeLabel = function()
	local mode = State.runtimeStatus and tostring(State.runtimeStatus.mode or "unknown") or "waiting"
	local contextType = State.runtimeStatus and tostring(State.runtimeStatus.contextType or "unknown") or "waiting"
	local playerCount = 0
	if State.runtimeStatus and State.runtimeStatus.players then
		playerCount = tonumber(State.runtimeStatus.players.count) or 0
	elseif State.runtimeStatus and State.runtimeStatus.playerCount then
		playerCount = tonumber(State.runtimeStatus.playerCount) or 0
	end
	local missingRemotes = State.remoteDoctor
		and State.remoteDoctor.comparison
		and tonumber(State.remoteDoctor.comparison.missingFromEditCount)
		or (State.remoteInventory and tonumber(State.remoteInventory.missingCount) or 0)
	local healthText = State.healthScore and tostring(State.healthScore.score) or "?"
	local projectText = State.projectProfile and tostring(State.projectProfile.id or State.projectProfile.name or "project") or "none"
	local projectScoreText = State.projectHealth and tostring(State.projectHealth.score) or "?"
	local projectIssues = State.projectValidation and State.projectValidation.summary and tonumber(State.projectValidation.summary.total) or 0
	local mirrorText = State.runtimeMirrorStatus and tostring(State.runtimeMirrorStatus.mode or "fallback") or "?"
	local harnessText = State.harnessStatus and (State.harnessStatus.installed and "installed" or "missing") or "?"
	local scenarioText = State.scenarioRunReport and tostring(State.scenarioRunReport.status or "ran") or "none"
	local reportText = State.playtestReport and tostring(State.playtestReport.at) or "none"
	local focusText = State.builderBrainStatus and tostring(State.builderBrainStatus.currentFocus or "") or ""
	if focusText == "" then
		focusText = "none"
	end
	focusText = V9.trimText(focusText, 36)
	local visualText = State.visualSnapshot and tostring(State.visualSnapshot.at or "ready") or "none"
	local nextText = State.autonomousPlan and tostring(State.autonomousPlan.nextAction or "plan ready") or "none"
	nextText = V9.trimText(nextText, 54)
	local directorText = State.directorRoundPlan and tostring(State.directorRoundPlan.reason or "round ready") or "none"
	directorText = V9.trimText(directorText, 54)
	local milestoneText = V16.last.milestonePlan and V16.last.milestonePlan.milestone and tostring(V16.last.milestonePlan.milestone.id or "milestone") or "none"
	local verificationText = V16.last.verificationReport and V16.last.verificationReport.summary and tostring(V16.last.verificationReport.summary.status or "ran") or "none"
	local verificationHarnessText = V16.last.verificationHarnessStatus and (V16.last.verificationHarnessStatus.installed and "installed" or "missing") or "?"
	local qaText = V17.session and (V17.session.endedAt and "ended" or "active") or "none"
	local qaBugText = V17.last.playtestBugReport and tostring(V17.last.playtestBugReport.bugCount or 0) or "?"
	local qaHarnessText = V17.last.qaHarnessStatus and (V17.last.qaHarnessStatus.installed and "installed" or "missing") or "?"
	local dashboardText = V20.last.dashboard and ("score " .. tostring(V20.last.dashboard.overallScore or "?")
		.. " | weak " .. tostring(V20.last.dashboard.weakestCategory and V20.last.dashboard.weakestCategory.id or "?")) or "none"
	local dashboardNext = V20.last.dashboard and V20.last.dashboard.nextStep and tostring(V20.last.dashboard.nextStep.command or "") or ""
	dashboardNext = V9.trimText(dashboardNext ~= "" and dashboardNext or "run dashboard", 54)
	local reliabilityText = V21.last.selfTest and ("self-test " .. tostring(V21.last.selfTest.score or "?")
		.. " | fails " .. tostring(V21.last.selfTest.counts and V21.last.selfTest.counts.fail or 0)) or "self-test none"
	local timing = V22.timingSummary(10)
	local slowText = timing.slowCommands and timing.slowCommands[1] and (tostring(timing.slowCommands[1].type)
		.. " " .. tostring(timing.slowCommands[1].totalMs) .. "ms") or "none"
	local cacheText = V20.last.dashboard and tostring(V20.last.dashboard.at or "ready") or "empty"
	local handoffText = V23.last.handoff and ("ready " .. tostring(V23.last.handoff.at or "")) or "not run"
	local handoffNext = V23.last.handoff and tostring(V23.last.handoff.nextCommand or "tools/bridge.cmd next") or "tools/bridge.cmd handoff"
	local readyText = V26.last.status and (tostring(V26.last.status.status or "unknown")
		.. " " .. tostring(V26.last.status.score or "?")) or "not checked"
	local readyHttpText = V26.last.status and V26.last.status.summary and tostring(V26.last.status.summary.httpStatus or "?") or "?"
	local readyNext = V26.last.status and tostring(V26.last.status.nextCommand or "tools/bridge.cmd ready status") or "tools/bridge.cmd ready status"
	local awarenessText = V27.last.status and ((V27.last.status.fresh and "fresh" or "stale")
		.. " | harness " .. (V27.last.status.harness and (V27.last.status.harness.installed and "installed" or "missing") or "?")) or "not checked"
	local awarenessNext = V27.last.status and tostring(V27.last.status.nextCommand or "tools/bridge.cmd awareness status") or "tools/bridge.cmd awareness status"
	local watchText = V28.last.status and ((V28.last.status.fresh and "fresh" or "stale")
		.. " | " .. tostring(V28.last.status.mode or "smartWatch")) or "not checked"
	local watchNext = V28.last.status and tostring(V28.last.status.nextCommand or "tools/bridge.cmd watch now") or "tools/bridge.cmd watch now"
	local startText = V29.last.status and ("score " .. tostring(V29.last.status.checklist and V29.last.status.checklist.score or "?")
		.. " | " .. tostring(V29.last.status.checklist and V29.last.status.checklist.readyCount or "?")
		.. "/" .. tostring(V29.last.status.checklist and V29.last.status.checklist.total or "?")) or "not checked"
	local startNext = V29.last.status and V29.last.status.next and tostring(V29.last.status.next.command or "tools/bridge.cmd start") or "tools/bridge.cmd start"
	local sessionText = V30.last.status and (tostring(V30.last.status.mode and V30.last.status.mode.mode or "?")
		.. " | score " .. tostring(V30.last.status.checklist and V30.last.status.checklist.score or "?")) or "not checked"
	local sessionNext = V30.last.route and tostring(V30.last.route.command or "tools/bridge.cmd session start") or "tools/bridge.cmd session start"
	local autonomyStatus = V33.getAutonomyStatus({})
	local trustStatus = autonomyStatus.fullTrust or V41.getStatus({})
	local autoText = tostring(trustStatus.mode or autonomyStatus.label or autonomyStatus.mode or "Off")
	local autoLast = trustStatus.lastAutoRun and (tostring(trustStatus.lastAutoRun.type or "?")
		.. " " .. V9.trimText(tostring(trustStatus.lastAutoRun.rule or ""), 18)) or "none"
	local playStatus = V33.getStudioPlayControlStatus({})
	local playText = tostring(playStatus.mode or "?") .. " | start " .. tostring(playStatus.canStartPlay) .. " | stop " .. tostring(playStatus.canStopPlay)
	runtimeLabel.Text = "Runtime: " .. mode
		.. " / " .. contextType
		.. " | players " .. tostring(playerCount)
		.. " | missing remotes " .. tostring(missingRemotes)
		.. "\nProject " .. projectText
		.. " | score " .. projectScoreText
		.. " | issues " .. tostring(projectIssues)
		.. "\nMirror " .. mirrorText
		.. " | harness " .. harnessText
		.. " | scenario " .. scenarioText
		.. " | legacy score " .. healthText
		.. "\nBrain " .. focusText
		.. " | visual " .. visualText
		.. "\nNext " .. nextText
		.. "\nDirector " .. directorText
		.. "\nMilestone " .. milestoneText
		.. " | verify " .. verificationText
		.. " | v-harness " .. verificationHarnessText
		.. "\nQA " .. qaText
		.. " | bugs " .. qaBugText
		.. " | qa-harness " .. qaHarnessText
		.. " | report " .. reportText
		.. "\nDashboard " .. dashboardText
		.. " | next " .. dashboardNext
		.. "\nV21 " .. reliabilityText
		.. "\nV22 cache " .. cacheText
		.. " | avg " .. tostring(timing.averageMs or "?") .. "ms"
		.. " | slow " .. V9.trimText(slowText, 38)
		.. "\nV23 handoff " .. V9.trimText(handoffText, 34)
		.. " | next " .. V9.trimText(handoffNext, 34)
		.. "\nV26 Codex Ready " .. V9.trimText(readyText, 36)
		.. " | HTTP " .. V9.trimText(readyHttpText, 18)
		.. " | next " .. V9.trimText(readyNext, 42)
		.. "\nV27 awareness " .. V9.trimText(awarenessText, 38)
		.. " | next " .. V9.trimText(awarenessNext, 38)
		.. "\nV28 watch " .. V9.trimText(watchText, 38)
		.. " | next " .. V9.trimText(watchNext, 38)
		.. "\nV29 start " .. V9.trimText(startText, 38)
		.. " | next " .. V9.trimText(startNext, 38)
		.. "\nV30 session " .. V9.trimText(sessionText, 38)
		.. " | next " .. V9.trimText(sessionNext, 38)
		.. "\nV41 trust " .. V9.trimText(autoText, 28)
		.. " | pending " .. tostring(trustStatus.pendingCount or autonomyStatus.pendingCount or 0)
		.. " | last " .. V9.trimText(autoLast, 26)
		.. "\nV34 play " .. V9.trimText(playText, 48)
		.. "\nV50 place " .. V9.trimText(tostring(game.Name), 22)
		.. " | id " .. V9.trimText(tostring(studioId), 12)
		.. " | use tools\\bridge.cmd places"
end

local function rebuildSelectionLabel()
	local selected = Selection:Get()
	if #selected == 0 then
		selectionLabel.Text = "Selection: none"
		return
	end

	local names = {}
	for index, instance in ipairs(selected) do
		if index > 3 then
			table.insert(names, "...")
			break
		end
		table.insert(names, instance.Name .. " (" .. instance.ClassName .. ")")
	end
	selectionLabel.Text = "Selection: " .. table.concat(names, ", ")
end

local function refreshCanvas(frame, listLayout)
	task.defer(function()
		frame.CanvasSize = UDim2.new(0, 0, 0, listLayout.AbsoluteContentSize.Y + 12)
	end)
end

local function removeChildren(frame)
	for _, child in ipairs(frame:GetChildren()) do
		if not child:IsA("UIListLayout") and not child:IsA("UIPadding") then
			child:Destroy()
		end
	end
end

local function rebuildOutput()
	removeChildren(outputFrame)
	local startIndex = math.max(1, #outputBuffer - 40)
	for index = startIndex, #outputBuffer do
		local entry = outputBuffer[index]
		local label = Instance.new("TextLabel")
		label.BackgroundTransparency = 1
		label.Size = UDim2.new(1, -6, 0, 34)
		label.Font = Enum.Font.Code
		label.TextColor3 = Color3.fromRGB(218, 225, 235)
		if tostring(entry.type):lower():find("error") then
			label.TextColor3 = Color3.fromRGB(255, 137, 137)
		elseif tostring(entry.type):lower():find("warn") then
			label.TextColor3 = Color3.fromRGB(255, 213, 128)
		end
		label.TextXAlignment = Enum.TextXAlignment.Left
		label.TextYAlignment = Enum.TextYAlignment.Top
		label.TextSize = 13
		label.TextWrapped = true
		label.Text = "[" .. tostring(entry.type) .. "] " .. tostring(entry.message)
		label.Parent = outputFrame
	end
	refreshCanvas(outputFrame, outputLayout)
end

local function commandPreviewText(command)
	local payload = command.payload or {}
	if command.type == "applyScriptPatch" then
		local diff = payload.diff or {}
		local lineText = ""
		if diff.oldLineCount or diff.newLineCount or diff.changedLineCount then
			lineText = " | lines " .. tostring(diff.oldLineCount or "?") .. " -> " .. tostring(diff.newLineCount or "?")
				.. " | changed " .. tostring(diff.changedLineCount or "?")
		end
		return "applyScriptPatch\n"
			.. tostring(payload.path or payload.scriptId or "unknown script")
			.. lineText
			.. "\n" .. tostring(payload.summary or "No summary")
	end
	if command.type == "applyCodePatchSet" then
		local patches = payload.patches or (type(payload.patchSet) == "table" and payload.patchSet.patches) or {}
		local first = type(patches) == "table" and patches[1] or nil
		local diff = type(first) == "table" and first.diff or {}
		local detail = ""
		if type(first) == "table" then
			detail = tostring(first.path or first.scriptId or "script")
			if diff and (diff.oldLineCount or diff.newLineCount or diff.changedLineCount) then
				detail = detail .. " | lines " .. tostring(diff.oldLineCount or "?") .. " -> " .. tostring(diff.newLineCount or "?")
					.. " | changed " .. tostring(diff.changedLineCount or "?")
			end
		end
		return "applyCodePatchSet\npatches: " .. tostring(type(patches) == "table" and #patches or "?")
			.. "\n" .. detail
			.. "\n" .. tostring(payload.summary or "Hash-verified script patches")
	end
	if command.type == "applyProductionRefactorPlan" then
		local plan = payload.plan or payload.refactorPlan or payload
		local actions = type(plan.instanceActions) == "table" and #plan.instanceActions or 0
		local patches = type(plan.scriptPatches) == "table" and #plan.scriptPatches or 0
		return "applyProductionRefactorPlan\n"
			.. tostring(plan.summary or plan.refactorKind or "Production refactor")
			.. "\nactions: " .. tostring(actions) .. " | patches: " .. tostring(patches) .. " | hash-check + undo"
	end
	if command.type == "applyBuildPlan" then
		local blueprint = payload.blueprint or payload.buildPlan or payload
		local name = type(blueprint) == "table" and tostring(blueprint.name or "Untitled Build Plan") or "Build Plan"
		local stepCount = type(blueprint) == "table" and type(blueprint.steps) == "table" and #blueprint.steps or 0
		return "applyBuildPlan\n" .. name .. "\nsteps: " .. tostring(stepCount)
	end
	if command.type == "applyTestScenario" then
		local blueprint = payload.blueprint or payload.buildPlan or payload
		local name = type(blueprint) == "table" and tostring(blueprint.name or "Ruleforge Test Scenario") or "Test Scenario"
		local stepCount = type(blueprint) == "table" and type(blueprint.steps) == "table" and #blueprint.steps or 0
		return "applyTestScenario\n" .. name .. "\nsteps: " .. tostring(stepCount)
	end
	if command.type == "applyRemoteRepairPlan" then
		local blueprint = payload.blueprint or payload.buildPlan or payload
		local name = type(blueprint) == "table" and tostring(blueprint.name or "Ruleforge Remote Repair") or "Ruleforge Remote Repair"
		local stepCount = type(blueprint) == "table" and type(blueprint.steps) == "table" and #blueprint.steps or "auto"
		return "applyRemoteRepairPlan\n" .. name .. "\nsteps: " .. tostring(stepCount)
	end
	if command.type == "applyScenario" then
		local blueprint = payload.blueprint or payload.buildPlan or payload
		local name = type(blueprint) == "table" and tostring(blueprint.name or payload.scenario or "Ruleforge Scenario") or "Ruleforge Scenario"
		local stepCount = type(blueprint) == "table" and type(blueprint.steps) == "table" and #blueprint.steps or 0
		return "applyScenario\n" .. name .. "\nsteps: " .. tostring(stepCount)
	end
	if command.type == "applyProjectPlan" then
		local blueprint = payload.blueprint or payload.buildPlan or payload
		local profile = payload.profile or payload.activeProfile or {}
		local name = type(blueprint) == "table" and tostring(blueprint.name or "Project Plan") or "Project Plan"
		local stepCount = type(blueprint) == "table" and type(blueprint.steps) == "table" and #blueprint.steps or 0
		return "applyProjectPlan\n" .. name .. "\nprofile: " .. tostring(profile.id or "universal") .. " | steps: " .. tostring(stepCount)
	end
	if command.type == "applyProjectScenario" then
		local blueprint = payload.blueprint or payload.buildPlan or payload
		local profile = payload.profile or payload.activeProfile or {}
		local name = type(blueprint) == "table" and tostring(blueprint.name or payload.scenario or "Project Scenario") or "Project Scenario"
		local stepCount = type(blueprint) == "table" and type(blueprint.steps) == "table" and #blueprint.steps or 0
		return "applyProjectScenario\n" .. name .. "\nprofile: " .. tostring(profile.id or "universal") .. " | steps: " .. tostring(stepCount)
	end
	if command.type == "applyCleanupPlan" then
		local plan = payload.cleanupPlan or payload.plan or {}
		local summary = type(plan) == "table" and plan.summary or {}
		return "applyCleanupPlan\n"
			.. "enabled: " .. tostring(summary and summary.enabledActions or "?")
			.. " | duplicate renames: " .. tostring(summary and summary.renameActions or "?")
	end
	if command.type == "installTestHarness" then
		local profile = payload.profile or payload.activeProfile or {}
		return "installTestHarness\nprofile: " .. tostring(profile.id or "universal")
			.. "\nCreates CodexTestHarness folders/scripts; undoable."
	end
	if command.type == "removeTestHarness" then
		return "removeTestHarness\nRemoves only CodexTestHarness-owned objects.\nUndoable."
	end
	if command.type == "applyScenarioHarness" then
		local blueprint = payload.blueprint or payload.buildPlan or payload
		local stepCount = type(blueprint) == "table" and type(blueprint.steps) == "table" and #blueprint.steps or "auto"
		return "applyScenarioHarness\n" .. tostring(payload.scenario or payload.name or "scenario")
			.. "\nsteps: " .. tostring(stepCount) .. " | undoable"
	end
	if command.type == "applyAutonomousPlan" then
		local blueprint = payload.blueprint or payload.buildPlan or payload
		local stepCount = type(blueprint) == "table" and type(blueprint.steps) == "table" and #blueprint.steps or "auto"
		return "applyAutonomousPlan\n" .. tostring(type(blueprint) == "table" and blueprint.name or "Codex Autonomous Plan")
			.. "\nsteps: " .. tostring(stepCount) .. " | Full Trust + undo/audit"
	end
	if command.type == "installVisualHarness" then
		return "installVisualHarness\nCreates CodexVisualHarness objects for optional visual capture.\nFull Trust + undo where supported."
	end
	if command.type == "removeVisualHarness" then
		return "removeVisualHarness\nRemoves only CodexVisualHarness-owned objects.\nFull Trust + undo where supported."
	end
	if command.type == "installLiveVisionHarness" then
		return "installLiveVisionHarness\nCreates CodexLiveVisionHarness client/capture marker objects.\nFull Trust + undo where supported."
	end
	if command.type == "removeLiveVisionHarness" then
		return "removeLiveVisionHarness\nRemoves only CodexLiveVisionHarness-owned objects.\nFull Trust + undo where supported."
	end
	if command.type == "requestLiveVisionCapture" then
		return "requestLiveVisionCapture\nRequests a best-effort client screenshot/capture marker.\nFull Trust local request; no hidden screen access."
	end
	if command.type == "applyCodexReadySetup" then
		return "applyCodexReadySetup\nInstalls/updates the full Codex Ready toolkit under Codex-owned paths.\nFull Trust auto-runs it after pairing; no production game objects touched."
	end
	if command.type == "installActionBridgeHarness" then
		return "installActionBridgeHarness\nCreates CodexActionBridge client/server action relay objects.\nFull Trust + undo where supported; owned paths only."
	end
	if command.type == "removeActionBridgeHarness" then
		return "removeActionBridgeHarness\nRemoves only CodexActionBridge-owned objects.\nFull Trust + undo where supported."
	end
	if command.type == "applyUiClickAction" then
		return "applyUiClickAction\nTarget: " .. tostring(payload.path or payload.text or payload.name or "unspecified")
			.. "\nRuns through CodexActionBridge in Play mode and returns before/after diffs."
	end
	if command.type == "applyPromptTriggerAction" then
		return "applyPromptTriggerAction\nTarget: " .. tostring(payload.path or payload.text or payload.name or "unspecified")
			.. "\nRuns through CodexActionBridge in Play mode and returns before/after diffs."
	end
	if command.type == "applyTeleportNearPromptAction" then
		return "applyTeleportNearPromptAction\nPrompt: " .. tostring(payload.path or payload.text or payload.name or "unspecified")
			.. "\nMoves only the test player near the prompt, then reports evidence."
	end
	if command.type == "applyTestRemoteAction" then
		return "applyTestRemoteAction\nRemote: " .. tostring(payload.remotePath or payload.path or payload.name or "unspecified")
			.. "\nExplicit test remote call; Full Trust runs safe local tests and blocks/manual-falls back for economy/save/monetization risk."
	end
	if command.type == "applyLaunchQaActionPlan" then
		return "applyLaunchQaActionPlan\nRecipe: " .. tostring(payload.recipeId or payload.id or "full-launch")
			.. "\nMarks a clean Output baseline; risky external/account actions remain blocked/manual."
	end
	if command.type == "requestStartPlay" then
		return "requestStartPlay\nStarts Roblox Studio Play/Test if a supported public API is available.\nFalls back to manual-required guidance."
	end
	if command.type == "requestStopPlay" then
		return "requestStopPlay\nStops Roblox Studio Play/Test if a supported public API is available.\nFalls back to manual-required guidance."
	end
	if command.type == "requestRestartPlay" then
		return "requestRestartPlay\nRestarts Studio Play/Test through feature-detected Play/Stop support.\nFalls back honestly if unavailable."
	end
	if command.type == "installRealtimeAwarenessHarness" then
		return "installRealtimeAwarenessHarness\nCreates CodexRealtimeAwareness client/server pulse objects.\nFull Trust + undo where supported; compact structured data only."
	end
	if command.type == "removeRealtimeAwarenessHarness" then
		return "removeRealtimeAwarenessHarness\nRemoves only CodexRealtimeAwareness-owned objects.\nFull Trust + undo where supported."
	end
	if command.type == "applyUiBuildPlan" or command.type == "applyAssetPlan" then
		local blueprint = payload.blueprint or payload.buildPlan or payload
		local stepCount = type(blueprint) == "table" and type(blueprint.steps) == "table" and #blueprint.steps or "auto"
		return command.type .. "\n" .. tostring(type(blueprint) == "table" and blueprint.name or "Codex Plan")
			.. "\nsteps: " .. tostring(stepCount) .. " | Full Trust + undo/audit"
	end
	if command.type == "applyUiForgePlan" or command.type == "applyUiPolishPlan" or command.type == "applyGameLoopPlan" or command.type == "applyStyleAssetPlan" or command.type == "applyDirectorRound"
		or command.type == "applyWorldForgePlan" or command.type == "applyAssetPlacementPlan" or command.type == "applyTerrainForgePlan" or command.type == "applyLightingStylePlan" then
		local blueprint = payload.blueprint or payload.buildPlan or payload
		local profile = payload.profile or payload.activeProfile or {}
		local stepCount = type(blueprint) == "table" and type(blueprint.steps) == "table" and #blueprint.steps or "auto"
		return command.type .. "\n" .. tostring(type(blueprint) == "table" and blueprint.name or "Codex Forge Plan")
			.. "\nprofile: " .. tostring(profile.id or "universal") .. " | steps: " .. tostring(stepCount) .. " | Full Trust + undo/audit"
	end
	if command.type == "applyGameplayFeaturePlan" then
		local bundle = payload.bundle or payload.plan or payload
		local blueprint = type(bundle) == "table" and (bundle.blueprint or bundle.buildPlan) or nil
		local patchSet = type(bundle) == "table" and bundle.patchSet or payload.patchSet
		local stepCount = type(blueprint) == "table" and type(blueprint.steps) == "table" and #blueprint.steps or "auto"
		local patchCount = type(patchSet) == "table" and type(patchSet.patches) == "table" and #patchSet.patches or 0
		return "applyGameplayFeaturePlan\n" .. tostring(type(bundle) == "table" and (bundle.title or bundle.featureId) or "Gameplay Feature")
			.. "\nsteps: " .. tostring(stepCount) .. " | patches: " .. tostring(patchCount) .. " | Full Trust + undo/audit"
	end
	if command.type == "applyMilestonePlan" then
		local mutation = payload.mutation or (payload.planSummary and payload.planSummary.mutation) or {}
		local bundle = type(mutation) == "table" and mutation.bundle or nil
		local blueprint = type(bundle) == "table" and bundle.blueprint or (type(mutation) == "table" and mutation.blueprint or nil)
		local patchSet = type(bundle) == "table" and bundle.patchSet or nil
		local milestone = payload.milestone or (payload.planSummary and payload.planSummary.milestone) or {}
		local stepCount = type(blueprint) == "table" and type(blueprint.steps) == "table" and #blueprint.steps or "auto"
		local patchCount = type(patchSet) == "table" and type(patchSet.patches) == "table" and #patchSet.patches or 0
		return "applyMilestonePlan\n" .. tostring(type(milestone) == "table" and (milestone.title or milestone.id) or payload.milestoneId or "Milestone")
			.. "\nsteps: " .. tostring(stepCount) .. " | patches: " .. tostring(patchCount) .. " | Full Trust + undo/audit"
	end
	if command.type == "applySystemTestHarness" then
		local profile = payload.profile or payload.activeProfile or {}
		return "applySystemTestHarness\nprofile: " .. tostring(profile.id or "universal")
			.. "\nCreates only CodexSystemHarness objects; undoable."
	end
	if command.type == "removeSystemTestHarness" then
		return "removeSystemTestHarness\nRemoves only CodexSystemHarness objects.\nFull Trust + undo where supported."
	end
	if command.type == "installVerificationHarness" then
		local profile = payload.profile or payload.activeProfile or {}
		return "installVerificationHarness\nprofile: " .. tostring(profile.id or "universal")
			.. "\nCreates only CodexVerificationHarness objects; undoable."
	end
	if command.type == "removeVerificationHarness" then
		return "removeVerificationHarness\nRemoves only CodexVerificationHarness objects.\nFull Trust + undo where supported."
	end
	if command.type == "installQaHarness" then
		local profile = payload.profile or payload.activeProfile or {}
		return "installQaHarness\nprofile: " .. tostring(profile.id or "universal")
			.. "\nCreates only CodexQaHarness marker objects; Full Trust + undo/audit."
	end
	if command.type == "removeQaHarness" then
		return "removeQaHarness\nRemoves only CodexQaHarness objects.\nFull Trust + undo where supported."
	end
	if command.type == "applyQaScenarioMarkers" then
		local scenario = tostring(payload.scenario or payload.name or "manual")
		return "applyQaScenarioMarkers\nscenario: " .. scenario
			.. "\nCreates/updates only CodexQaHarness scenario markers; Full Trust + undo/audit."
	end
	return command.type .. "\n" .. shortId(command.id)
end

local function finishCommand(command, status, result, err)
	pendingCommands[command.id] = nil
	for index = #commandOrder, 1, -1 do
		if commandOrder[index] == command.id then
			table.remove(commandOrder, index)
		end
	end
	V22.addTiming(command, status)
	V21.addAuditRecord({
		id = command.id,
		type = command.type,
		status = status,
		requiresApproval = commandRequiresApproval(command),
		approvalState = commandRequiresApproval(command) and status or "readOnly",
		autoApproved = command._autoApproved == true,
		autoApproveMode = command._autoApproveMode,
		autoApproveRule = command._autoApproveRule,
		resultSummary = V21.resultSummary(result),
		error = err,
		preview = commandPreviewText(command),
	})
	if command._fullTrustAutoRun then
		local finalDecision = {
			mode = command._autoApproveMode or V41.mode(),
			rule = command._autoApproveRule or "fullTrustAutopilot",
			reason = err or (status == "executed" and "Full Trust command completed." or "Full Trust command finished."),
		}
		V41.addAuditRecord(command, status == "executed" and "autoRunExecuted" or status, finalDecision)
	end
	reportCommand(command.id, status, result, err)
end

local function runCommand(command)
	if processedCommands[command.id] then
		V22.addTiming(command, "duplicateIgnored")
		V21.addAuditRecord({
			id = command.id,
			type = command.type,
			status = "duplicateIgnored",
			requiresApproval = commandRequiresApproval(command),
			approvalState = "duplicate",
			error = "Command was already processed by this Studio session.",
			preview = commandPreviewText(command),
		})
		reportCommand(command.id, "duplicateIgnored", nil, "Command was already processed by this Studio session.")
		return
	end
	processedCommands[command.id] = true

	local ok, result = pcall(function()
		return executeCommand(command)
	end)
	if ok then
		finishCommand(command, "executed", result, nil)
		State.commandSummary = command.type .. " executed"
		updateLastCommandLabel()
		addOutput("Executed command " .. command.type .. " (" .. shortId(command.id) .. ")", "Info", "CodexStudioBridge")
		sendState(true)
	else
		finishCommand(command, "failed", nil, tostring(result))
		State.commandSummary = command.type .. " failed: " .. tostring(result)
		updateLastCommandLabel()
		addOutput("Command failed " .. command.type .. ": " .. tostring(result), "Error", "CodexStudioBridge")
	end
end

local function rebuildPending()
	removeChildren(pendingFrame)
	if #commandOrder == 0 then
		local empty = Instance.new("TextLabel")
		empty.BackgroundTransparency = 1
		empty.Size = UDim2.new(1, -6, 0, 28)
		empty.Font = Enum.Font.SourceSansItalic
		empty.TextColor3 = Color3.fromRGB(170, 179, 190)
		empty.TextXAlignment = Enum.TextXAlignment.Left
		empty.Text = V41.isEnabled() and "Full Trust ON: approval queue is bypassed." or "No pending edits."
		empty.TextSize = 15
		empty.Parent = pendingFrame
		refreshCanvas(pendingFrame, pendingLayout)
		return
	end

	for _, commandId in ipairs(commandOrder) do
		local command = pendingCommands[commandId]
		if command then
			local isLargePreview = command.type == "applyScriptPatch"
				or command.type == "applyCodePatchSet"
				or command.type == "applyBuildPlan"
				or command.type == "applyTestScenario"
				or command.type == "applyRemoteRepairPlan"
				or command.type == "applyScenario"
				or command.type == "applyProjectPlan"
				or command.type == "applyProjectScenario"
				or command.type == "applyCleanupPlan"
				or command.type == "installTestHarness"
				or command.type == "removeTestHarness"
				or command.type == "applyScenarioHarness"
				or command.type == "applyAutonomousPlan"
				or command.type == "installVisualHarness"
				or command.type == "removeVisualHarness"
				or command.type == "applyUiBuildPlan"
				or command.type == "applyAssetPlan"
				or command.type == "applyUiForgePlan"
				or command.type == "applyUiPolishPlan"
				or command.type == "applyWorldForgePlan"
				or command.type == "applyAssetPlacementPlan"
				or command.type == "applyTerrainForgePlan"
				or command.type == "applyLightingStylePlan"
				or command.type == "applyGameplayFeaturePlan"
				or command.type == "applySystemTestHarness"
				or command.type == "removeSystemTestHarness"
				or command.type == "applyMilestonePlan"
				or command.type == "installVerificationHarness"
				or command.type == "removeVerificationHarness"
				or command.type == "installQaHarness"
				or command.type == "removeQaHarness"
				or command.type == "applyQaScenarioMarkers"
				or command.type == "applyGameLoopPlan"
				or command.type == "applyStyleAssetPlan"
				or command.type == "applyDirectorRound"
				or command.type == "applyProductionRefactorPlan"
				or command.type == "installLiveVisionHarness"
				or command.type == "removeLiveVisionHarness"
				or command.type == "requestLiveVisionCapture"
				or command.type == "applyCodexReadySetup"
				or command.type == "installRealtimeAwarenessHarness"
				or command.type == "removeRealtimeAwarenessHarness"
			local rowHeight = isLargePreview and 92 or 64
			local row = Instance.new("Frame")
			row.BackgroundColor3 = Color3.fromRGB(43, 48, 56)
			row.BorderSizePixel = 0
			row.Size = UDim2.new(1, -6, 0, rowHeight)
			row.Parent = pendingFrame

			local label = Instance.new("TextLabel")
			label.BackgroundTransparency = 1
			label.Position = UDim2.new(0, 8, 0, 6)
			label.Size = UDim2.new(1, -150, 1, -12)
			label.Font = Enum.Font.SourceSans
			label.TextColor3 = Color3.fromRGB(238, 241, 245)
			label.TextXAlignment = Enum.TextXAlignment.Left
			label.TextYAlignment = Enum.TextYAlignment.Top
			label.TextSize = 15
			label.TextWrapped = true
			label.Text = commandPreviewText(command)
			label.Parent = row

			local approve = Instance.new("TextButton")
			approve.BackgroundColor3 = Color3.fromRGB(38, 152, 95)
			approve.BorderSizePixel = 0
			approve.Position = UDim2.new(1, -136, 0, 10)
			approve.Size = UDim2.new(0, 62, 0, rowHeight - 20)
