local function enqueueCommand(command)
	if not command or not command.id or processedCommands[command.id] then
		return
	end
	command._studioReceivedClock = command._studioReceivedClock or os.clock()

	if commandRequiresApproval(command) then
		local trustDecision = V41.shouldRunImmediately(command)
		if trustDecision.allowed then
			local trustAudit = V41.addAuditRecord(command, "autoRunQueued", trustDecision)
			local legacyAudit = V33.addAuditRecord(command, "autoApproved", trustDecision)
			command._autoApproved = true
			command._fullTrustAutoRun = true
			command._autoApproveMode = trustDecision.mode
			command._autoApproveRule = trustDecision.rule
			command._autoApproveAuditId = trustAudit and trustAudit.at or nil
			reportCommand(command.id, "autoRunQueued", {
				fullTrustAutopilot = true,
				autoApproveMode = trustDecision.mode,
				policyRule = trustDecision.rule,
				reason = trustDecision.reason,
				audit = trustAudit,
				legacyAudit = legacyAudit,
			}, nil)
			V21.addAuditRecord({
				id = command.id,
				type = command.type,
				status = "autoRunQueued",
				requiresApproval = true,
				approvalState = "autoRun",
				autoApproved = true,
				autoApproveMode = trustDecision.mode,
				autoApproveRule = trustDecision.rule,
				preview = commandPreviewText(command),
			})
			State.commandSummary = command.type .. " auto-run"
			updateLastCommandLabel()
			addOutput("Full Trust auto-run " .. command.type .. " (" .. shortId(command.id) .. ")", "Info", "CodexStudioBridge")
			runCommand(command)
			return
		elseif trustDecision.blocked then
			V41.addAuditRecord(command, "blockedExternalRisk", trustDecision)
			V33.addAuditRecord(command, "blocked", trustDecision)
			State.commandSummary = command.type .. " blocked: " .. tostring(trustDecision.reason)
			updateLastCommandLabel()
			addOutput("Full Trust blocked external-risk command " .. command.type .. ": " .. tostring(trustDecision.reason), "Warning", "CodexStudioBridge")
			finishCommand(command, "blockedExternalRisk", {
				fullTrustAutopilot = true,
				blocked = true,
				rule = trustDecision.rule,
				reason = trustDecision.reason,
				manualRequired = true,
			}, tostring(trustDecision.reason))
			return
		end

		local decision = V33.shouldAutoApprove(command)
		if decision.allowed then
			local auditRecord = V33.addAuditRecord(command, "autoApproved", decision)
			command._autoApproved = true
			command._autoApproveMode = decision.mode
			command._autoApproveRule = decision.rule
			command._autoApproveAuditId = auditRecord and auditRecord.at or nil
			reportCommand(command.id, "autoApproved", {
				autoApproveMode = decision.mode,
				policyRule = decision.rule,
				reason = decision.reason,
				audit = auditRecord,
			}, nil)
			V21.addAuditRecord({
				id = command.id,
				type = command.type,
				status = "autoApproved",
				requiresApproval = true,
				approvalState = "autoApproved",
				autoApproved = true,
				autoApproveMode = decision.mode,
				autoApproveRule = decision.rule,
				preview = commandPreviewText(command),
			})
			State.commandSummary = command.type .. " auto-approved"
			updateLastCommandLabel()
			addOutput("Auto-approved " .. command.type .. " (" .. shortId(command.id) .. ") via " .. tostring(decision.mode), "Info", "CodexStudioBridge")
			runCommand(command)
			return
		elseif decision.blocked then
			V33.addAuditRecord(command, "blocked", decision)
		end
		if not pendingCommands[command.id] then
			pendingCommands[command.id] = command
			table.insert(commandOrder, command.id)
			reportCommand(command.id, "pendingApproval", nil, nil)
			V21.addAuditRecord({
				id = command.id,
				type = command.type,
				status = "pendingApproval",
				requiresApproval = true,
				approvalState = "pending",
				preview = commandPreviewText(command),
			})
			State.commandSummary = command.type .. " manual fallback"
			updateLastCommandLabel()
			addOutput("Manual fallback queued: " .. command.type .. " (" .. shortId(command.id) .. ")", "Info", "CodexStudioBridge")
			rebuildPending()
		end
	else
		reportCommand(command.id, "running", nil, nil)
		V21.addAuditRecord({
			id = command.id,
			type = command.type,
			status = "running",
			requiresApproval = false,
			approvalState = "readOnly",
			preview = commandPreviewText(command),
		})
		runCommand(command)
	end
end

pairButton.MouseButton1Click:Connect(function()
	local code = pairCodeBox.Text
	if code == "" then
		updateStatus("Run tools\\bridge.cmd connect for pairing, or tools\\bridge.cmd always-on repair if the bridge is wedged.")
		return
	end

	updateStatus("Pairing with " .. bridgeUrl .. " ...")
	local response, err = request("POST", "/studio/pair", {
		pairingCode = code,
		studioId = studioId,
		studioIdSettingKey = studioIdSettingKey,
		sessionTokenSettingKey = sessionTokenSettingKey,
		placeIdentityKey = placeIdentityKey,
		pluginVersion = VERSION,
		placeId = game.PlaceId,
		gameId = game.GameId,
		placeName = game.Name,
	}, false)

	if response and response.sessionToken then
		if type(response.studioId) == "string" and response.studioId ~= "" and response.studioId ~= studioId then
			studioId = response.studioId
			plugin:SetSetting(studioIdSettingKey, studioId)
		end
		sessionToken = response.sessionToken
		paired = true
		plugin:SetSetting(sessionTokenSettingKey, sessionToken)
		plugin:SetSetting("SessionToken", "")
		updateStatus("Paired with " .. bridgeUrl .. " as " .. tostring(response.studioId or studioId))
		addOutput("Paired with Codex Studio Bridge.", "Info", "CodexStudioBridge")
		sendHeartbeatAsync("paired")
		sendState(true)
	else
		updateStatus("Pair failed: " .. tostring(err))
		addOutput("Pair failed: " .. tostring(err), "Error", "CodexStudioBridge")
	end
end)

