local function setLoopHealth(name, patch)
	State.loopHealth = State.loopHealth or { loops = {}, restartCount = 0 }
	State.loopHealth.loops = State.loopHealth.loops or {}
	local loop = State.loopHealth.loops[name] or { name = name, starts = 0, errors = 0 }
	for key, value in pairs(patch or {}) do
		loop[key] = value
	end
	loop.updatedAt = isoNow()
	State.loopHealth.loops[name] = loop
	return loop
end

local function markLoopBeat(name, extra)
	local patch = {
		status = "running",
		lastBeatAt = isoNow(),
		lastBeatClock = os.clock(),
	}
	for key, value in pairs(extra or {}) do
		patch[key] = value
	end
	return setLoopHealth(name, patch)
end

local function superviseLoop(name, callback)
	task.spawn(function()
		while running do
			local current = State.loopHealth and State.loopHealth.loops and State.loopHealth.loops[name] or nil
			setLoopHealth(name, {
				status = "running",
				starts = (current and tonumber(current.starts) or 0) + 1,
				lastStartAt = isoNow(),
			})
			local ok, err = xpcall(callback, function(errorMessage)
				return tostring(errorMessage)
			end)
			if not running then
				break
			end
			if ok then
				break
			end
			current = State.loopHealth and State.loopHealth.loops and State.loopHealth.loops[name] or nil
			local errorCount = (current and tonumber(current.errors) or 0) + 1
			State.loopHealth.restartCount = (tonumber(State.loopHealth.restartCount) or 0) + 1
			State.loopHealth.lastLoopError = {
				name = name,
				at = isoNow(),
				message = tostring(err),
			}
			setLoopHealth(name, {
				status = "restarting",
				errors = errorCount,
				lastError = tostring(err),
				lastErrorAt = isoNow(),
			})
			addOutput("Plugin loop '" .. tostring(name) .. "' restarted after error: " .. tostring(err), "Warning", "CodexStudioBridge", true)
			rebuildOutput()
			updateStatus("Recovered plugin loop: " .. tostring(name))
			task.wait(math.min(8, 1 + errorCount * 0.5))
		end
		setLoopHealth(name, {
			status = "stopped",
			stoppedAt = isoNow(),
		})
	end)
end

superviseLoop("heartbeat", function()
	while running do
		task.wait(RunService:IsRunning() and 0.5 or HEARTBEAT_SECONDS)
		markLoopBeat("heartbeat", {
			paired = paired,
			playMode = RunService:IsRunning(),
			inFlight = heartbeatInFlight,
			sequence = heartbeatSequence,
		})
		sendHeartbeatAsync("supervisedHeartbeat")
	end
end)

superviseLoop("commandPoll", function()
	while running do
		local waitSeconds = POLL_SECONDS
		if #commandOrder > 0 then
			waitSeconds = 0.25
		elseif RunService:IsRunning() then
			waitSeconds = 0.4
		end
		task.wait(waitSeconds)
		markLoopBeat("commandPoll", { paired = paired, pendingCommands = #commandOrder })
		if paired then
			local response, err = request("GET", "/studio/commands", nil, true)
			if response and type(response.commands) == "table" then
				updateStatus("Connected to " .. bridgeUrl .. " | commands: " .. tostring(#commandOrder))
				for _, command in ipairs(response.commands) do
					enqueueCommand(command)
				end
			elseif err then
				updateStatus("Bridge disconnected: " .. tostring(err))
			end
		end
	end
end)

superviseLoop("editPulse", function()
	while running do
		task.wait(RunService:IsRunning() and 0.75 or 1.25)
		markLoopBeat("editPulse", { paired = paired, playMode = RunService:IsRunning() })
		if paired then
			V27.sendEditPulse()
		end
	end
end)

superviseLoop("stateUpload", function()
	while running do
		task.wait(STATE_SECONDS)
		markLoopBeat("stateUpload", { paired = paired, stateDirty = stateDirty, playMode = RunService:IsRunning() })
		if paired then
			sendState(false)
		end
	end
end)

superviseLoop("outputUpload", function()
	while running do
		task.wait(OUTPUT_SECONDS)
		markLoopBeat("outputUpload", { paired = paired, queuedOutput = #outputQueue })
		if paired and #outputQueue > 0 then
			local now = os.clock()
			local nextUploadAt = tonumber(State.nextOutputUploadAt) or 0
			if now >= nextUploadAt then
				local batch = {}
				local maxBatch = tonumber(State.outputUploadMaxBatch) or 80
				local takeCount = math.min(#outputQueue, maxBatch)
				for index = 1, takeCount do
					table.insert(batch, outputQueue[index])
				end
				for _ = 1, takeCount do
					table.remove(outputQueue, 1)
				end
				local response, err = request("POST", "/studio/output", {
					messages = batch,
					pluginStatus = {
			studioId = studioId,
			studioIdSettingKey = studioIdSettingKey,
			sessionTokenSettingKey = sessionTokenSettingKey,
			placeIdentityKey = placeIdentityKey,
						pluginVersion = VERSION,
						placeId = game.PlaceId,
						gameId = game.GameId,
						placeName = game.Name,
					},
				}, true)
				if not response then
					State.lastOutputError = tostring(err)
					local rateLimited = isHttpRateLimitError(err)
					for index = #batch, 1, -1 do
						local entry = batch[index]
						table.insert(outputQueue, 1, entry)
					end
					while #outputQueue > OUTPUT_LIMIT do
						table.remove(outputQueue, 1)
					end
					local previousBackoff = tonumber(State.outputUploadBackoffSeconds) or OUTPUT_SECONDS
					local nextBackoff = rateLimited
						and math.min(12, math.max(4, previousBackoff * 2))
						or math.min(8, math.max(2, previousBackoff * 1.5))
					State.outputUploadBackoffSeconds = nextBackoff
					State.nextOutputUploadAt = now + nextBackoff
					State.lastOutputBackoffSeconds = nextBackoff
					if rateLimited then
						State.lastOutputRateLimitedAt = isoNow()
						local lastNotice = tonumber(State.lastOutputRateLimitNoticeClock) or 0
						if now - lastNotice > 20 then
							State.lastOutputRateLimitNoticeClock = now
							updateStatus("Output upload rate-limited; backing off " .. tostring(math.floor(nextBackoff)) .. "s.")
						end
					else
						local lastWarning = tonumber(State.lastOutputUploadWarningClock) or 0
						if now - lastWarning > 20 then
							State.lastOutputUploadWarningClock = now
							addOutput("Output upload failed: " .. tostring(err), "Warning", "CodexStudioBridge", true)
							rebuildOutput()
						end
					end
				else
					State.lastOutputSentAt = isoNow()
					State.lastOutputBatchSize = #batch
					State.lastOutputError = nil
					State.outputUploadBackoffSeconds = OUTPUT_SECONDS
					State.nextOutputUploadAt = now + OUTPUT_SECONDS
					State.lastOutputBackoffSeconds = nil
				end
			end
		end
	end
end)

widget:GetPropertyChangedSignal("Enabled"):Connect(function()
	toggleButton:SetActive(widget.Enabled)
end)

plugin.Unloading:Connect(function()
	State.lastPluginUnloadSignalAt = isoNow()
	State.loopHealth = State.loopHealth or { loops = {}, restartCount = 0 }
	State.loopHealth.lastPluginUnloadSignalAt = State.lastPluginUnloadSignalAt
	-- Roblox Studio can fire Plugin.Unloading during Play/Test transitions while this
	-- plugin environment is still alive. Do not set running=false here; real unloads
	-- terminate the script anyway, and transient unload signals used to stop every
	-- bridge poller until the user reloaded Studio.
	addOutput("Plugin unload signal observed; bridge loops remain armed for Play/Test recovery.", "Info", "CodexStudioBridge", true)
end)

rebuildSelectionLabel()
rebuildPending()
rebuildOutput()
updateSnapshotLabel()
updateLastCommandLabel()
refreshAutoApproveUi()
updateRuntimeLabel()
if paired then
	updateStatus("Stored pairing token loaded for " .. bridgeUrl)
	stateDirty = true
else
	updateStatus("Start bridge, then enter pairing code from http://127.0.0.1:" .. tostring(bridgePort) .. "/health")
end
end

startPluginUi()
